# Helper function to convert UTC datetime to Rome timezone (Europe/Rome)
def to_rome_time(dt: datetime) -> datetime:
    """Convert UTC datetime to Rome timezone (CET/CEST)"""
    # Rome is UTC+1 in winter, UTC+2 in summer (DST)
    # Using a simple calculation for CET (we could use pytz for more accuracy)
    # Check if DST is active (last Sunday of March to last Sunday of October)
    year = dt.year
    # Last Sunday of March
    march_last_sunday = datetime(year, 3, 31, 2, 0, tzinfo=timezone.utc)
    while march_last_sunday.weekday() != 6:  # 6 = Sunday
        march_last_sunday -= timedelta(days=1)
    # Last Sunday of October  
    october_last_sunday = datetime(year, 10, 31, 3, 0, tzinfo=timezone.utc)
    while october_last_sunday.weekday() != 6:
        october_last_sunday -= timedelta(days=1)
    
    # Determine if DST is active
    if march_last_sunday <= dt.replace(tzinfo=timezone.utc) < october_last_sunday:
        # Summer time (CEST) - UTC+2
        return dt + timedelta(hours=2)
    else:
        # Winter time (CET) - UTC+1
        return dt + timedelta(hours=1)

def format_rome_timestamp(dt: datetime) -> str:
    """Format datetime as Rome timezone string"""
    rome_dt = to_rome_time(dt)
    return rome_dt.strftime('%Y-%m-%d %H:%M:%S')


def _missing_residence(entity: dict) -> list:
    """🆕 16/08/2026 — Campi residenza obbligatori per firmare i documenti GDPR."""
    missing = []
    if not (entity.get("address") or "").strip():
        missing.append("Indirizzo di residenza")
    if not (entity.get("city") or "").strip():
        missing.append("Città di residenza")
    if not (entity.get("province") or "").strip():
        missing.append("Provincia di residenza")
    if not (entity.get("postal_code") or "").strip():
        missing.append("CAP")
    return missing


def validate_parent_profile(parent: dict) -> list:
    """Check required fields for parent profile. Returns list of missing field names."""
    missing = []
    if not (parent.get("full_name") or "").strip():
        missing.append("Nome completo")
    if not (parent.get("fiscal_code") or "").strip():
        missing.append("Codice Fiscale")
    if not (parent.get("phone") or "").strip():
        missing.append("Telefono")
    return missing


def format_date_it(date_str) -> str:
    """Format a date string (ISO or similar) to dd/mm/yyyy Italian format"""
    if not date_str:
        return ""
    s = str(date_str)[:10]
    try:
        from datetime import datetime as dt
        d = dt.strptime(s, "%Y-%m-%d")
        return d.strftime("%d/%m/%Y")
    except:
        return s

def validate_athlete_profile(athlete: dict) -> list:
    """Check required fields for athlete profile. Returns list of missing field names."""
    missing = []
    if not (athlete.get("full_name") or "").strip():
        missing.append("Nome completo")
    if not athlete.get("date_of_birth"):
        missing.append("Data di nascita")
    if not (athlete.get("fiscal_code") or "").strip():
        missing.append("Codice Fiscale")
    country = (athlete.get("country_of_birth") or "Italia").strip().upper()
    is_foreign = country not in ("ITALIA", "")
    if not is_foreign:
        place = athlete.get("place_of_birth") or athlete.get("birth_place") or ""
        if not place.strip():
            missing.append("Luogo di nascita")
    missing.extend(_missing_residence(athlete))
    return missing

def check_profiles_for_document(parent: dict = None, athlete: dict = None):
    """Raise HTTPException if parent or athlete profiles are incomplete."""
    all_missing = []
    if parent:
        parent_missing = validate_parent_profile(parent)
        if parent_missing:
            all_missing.append(f"Genitore: {', '.join(parent_missing)}")
    if athlete:
        athlete_missing = validate_athlete_profile(athlete)
        if athlete_missing:
            all_missing.append(f"Atleta: {', '.join(athlete_missing)}")
    if all_missing:
        detail = "Anagrafica incompleta. Compilare i seguenti campi prima di generare il documento: " + " | ".join(all_missing)
        raise HTTPException(status_code=400, detail=detail)


def _compute_is_minor(athlete: dict) -> bool:
    """Ritorna True se l'atleta è minorenne.
    - Se il flag `is_minor` è esplicitamente settato → usa quello.
    - Altrimenti calcola da `date_of_birth` (età < 18).
    - Default sicuro: True (comportamento pre-esistente per record legacy).
    """
    v = athlete.get("is_minor")
    if isinstance(v, bool):
        return v
    dob = athlete.get("date_of_birth")
    if dob:
        try:
            if isinstance(dob, str):
                dob_dt = datetime.fromisoformat(dob.replace("Z", "").split("T")[0])
            else:
                dob_dt = dob
            today = datetime.utcnow()
            age = today.year - dob_dt.year - ((today.month, today.day) < (dob_dt.month, dob_dt.day))
            return age < 18
        except Exception:
            pass
    return True

# Progressive rate limiting configuration
def get_real_ip(request: Request) -> str:
    """Get real client IP from X-Forwarded-For header or fall back to remote address"""
    forwarded = request.headers.get("x-forwarded-for")
    if forwarded:
        return forwarded.split(",")[0].strip()
    return get_remote_address(request)

async def check_login_rate_limit(ip: str) -> dict:
    """
    Progressive rate limiting:
    - 5 attempts: 1 minute block
    - 10 attempts: 5 minutes block  
    - 15+ attempts: 1 hour block + suggest password reset
    """
    now = datetime.now(timezone.utc)
    
    # Get or create rate limit record for this IP
    record = await db.login_rate_limits.find_one({"ip": ip})
    
    if not record:
        return {"allowed": True, "attempts": 0}
    
    attempts = record.get("attempts", 0)
    blocked_until = record.get("blocked_until")
    
    # Check if currently blocked
    if blocked_until:
        blocked_dt = datetime.fromisoformat(blocked_until.replace('Z', '+00:00')) if isinstance(blocked_until, str) else blocked_until
        if now < blocked_dt:
            remaining = (blocked_dt - now).total_seconds()
            if remaining > 3600:
                time_msg = f"{int(remaining // 3600)} ora"
            elif remaining > 60:
                time_msg = f"{int(remaining // 60)} minuti"
            else:
                time_msg = f"{int(remaining)} secondi"
            
            # Message based on attempt count
            if attempts >= 15:
                msg = f"Account temporaneamente bloccato. Riprova tra {time_msg}. Ti consigliamo di richiedere il reset della password."
            else:
                msg = f"Troppi tentativi di login. Riprova tra {time_msg}."
            
            return {"allowed": False, "message": msg, "attempts": attempts, "count_attempt": True}
    
    return {"allowed": True, "attempts": attempts}

async def record_failed_login(ip: str):
    """Record a failed login attempt and apply progressive blocking"""
    now = datetime.now(timezone.utc)
    
    # Get current record
    record = await db.login_rate_limits.find_one({"ip": ip})
    attempts = (record.get("attempts", 0) if record else 0) + 1
    
    # Determine block duration based on attempts
    block_duration = None
    if attempts >= 15:
        block_duration = timedelta(hours=1)
    elif attempts >= 10:
        block_duration = timedelta(minutes=5)
    elif attempts >= 5:
        block_duration = timedelta(minutes=1)
    
    blocked_until = (now + block_duration).isoformat() if block_duration else None
    
    # Update or create record
    await db.login_rate_limits.update_one(
        {"ip": ip},
        {"$set": {
            "ip": ip,
            "attempts": attempts,
            "blocked_until": blocked_until,
            "last_attempt": now.isoformat()
        }},
        upsert=True
    )
    
    return attempts

async def reset_login_rate_limit(ip: str):
    """Reset rate limit on successful login"""
    await db.login_rate_limits.delete_one({"ip": ip})

