import secrets
import string

def generate_invite_code(length=8):
    """Generate a random invite code"""
    chars = string.ascii_uppercase + string.digits
    return ''.join(secrets.choice(chars) for _ in range(length))

class UserRole:
    ADMIN = "admin"
    VIEWER = "viewer"  # Dirigente solo visualizzazione
    DIRIGENTE = "dirigente"  # Dirigenti sportivi
    COACH = "coach"
    COLLABORATORE = "collaboratore"  # Collaboratori (groundskeepers, secretaries, etc.)
    PARENT = "parent"
    ATHLETE = "athlete"
    COORDINATORE = "coordinatore"  # 🆕 27/02/2026 — Figura intermedia tra Admin e Dirigente:
                                    # accede a sezioni ORGANIZZATIVE (teams, atleti, presenze,
                                    # eventi, comunicazioni) ma NON a sezioni AMMINISTRATIVE
                                    # (compensi, fatture, IBAN, soglie, sponsor).
                                    # Permessi granulari impostati dall'Admin nel campo
                                    # users.coordinator_permissions (list of strings).


def _has_admin_or_coord_perm(user: Dict[str, Any], perm: str) -> bool:
    """True se l'utente è admin, OPPURE è coordinatore con `perm` nei permessi granulari.
    🆕 17/07/2026 — Helper per aprire endpoint admin ai coordinatori autorizzati.
    """
    role = user.get("role")
    if role == UserRole.ADMIN:
        return True
    if role == UserRole.COORDINATORE:
        perms = user.get("coordinator_permissions") or []
        return perm in perms
    return False



