class AthleteStatus:
    PENDING = "pending"      # In attesa di approvazione admin
    TRIAL = "trial"          # In periodo di prova
    ACTIVE = "active"        # Attivo
    BLOCKED = "blocked"      # Bloccato


# ─────────────────────────────────────────────────────────────────────────
# 🆕 Certificato medico — logica di blocco onboarding (Riforma/FIPAV)
#   • Adulti (18+): certificato SEMPRE obbligatorio (salvo squadra 'none').
#   • Minorenni: obbligatorio solo se "già tesserato/gioca già" (already_registered).
#   • Tipo (agonistico/buona_salute/none) dipende dalla CATEGORIA (squadra).
# ─────────────────────────────────────────────────────────────────────────
def cert_type_for_team(team) -> str:
    """Ritorna 'none' | 'buona_salute' | 'agonistico' (default agonistico)."""
    if not team:
        return "agonistico"
    return team.get("certificate_type_required") or "agonistico"

def has_valid_verified_cert(athlete: dict) -> bool:
    """True se l'atleta ha un certificato medico CONVALIDATO e non scaduto."""
    if not athlete.get("medical_certificate_verified"):
        return False
    exp = athlete.get("medical_certificate_expiry")
    if not exp:
        return False
    try:
        d = datetime.fromisoformat(str(exp).replace('Z', '+00:00')).replace(tzinfo=None)
        return d >= datetime.utcnow().replace(hour=0, minute=0, second=0, microsecond=0)
    except Exception:
        return False

def cert_required_for_trial(is_minor: bool, already_registered, cert_type: str) -> bool:
    """Il certificato serve PRIMA di iniziare la prova?"""
    if cert_type == "none":
        return False
    if not is_minor:
        return True  # adulti: sempre
    return bool(already_registered)  # minori: solo se già tesserati/giocano già

def cert_required_for_active(cert_type: str) -> bool:
    """Il certificato serve per il tesseramento definitivo (diventare ATTIVO)?"""
    return cert_type != "none"

def compute_pending_reason(a: dict) -> Optional[str]:
    """🆕 24/08/2026 — Motivo dell'"ATTESA" di un atleta, in linguaggio chiaro per
    l'admin (cosa sollecitare al genitore / all'atleta 18+). Ritorna None se
    l'atleta è ATTIVO / ritirato / bloccato (nessun sollecito necessario)."""
    if a.get("is_withdrawn"):
        return None
    status = a.get("status") or "pending"
    if status in ("blocked", "rejected"):
        return None
    is_minor = _compute_is_minor(a)
    priv = bool(a.get("privacy_accepted"))
    cert = bool(a.get("medical_certificate_verified"))
    # 🐛 26/09/2026 — la squadra può essere solo in `team_ids` (canonical) senza il
    # campo legacy `team_id` sincronizzato: consideriamo assegnata l'atleta se ha
    # almeno una squadra in team_ids OPPURE nel legacy team_id/primary_team_id.
    _team_ids = a.get("team_ids") or []
    has_team = bool(a.get("team_id") or a.get("primary_team_id") or (isinstance(_team_ids, list) and len(_team_ids) > 0))
    trial_started = bool(a.get("trial_start_date"))

    # ATTIVO: nessun sollecito, salvo che manchi la squadra (la lista lo mostra
    # comunque come "In attesa" finché non è assegnato a una squadra).
    if status == "active":
        return None if has_team else "In attesa: assegnazione a una squadra"

    # Non ancora accettato dalla società
    if status in ("pending", "pending_email"):
        return "In attesa: approvazione della società (accetta o rifiuta l'iscrizione)"

    parts = []
    if not has_team:
        parts.append("assegnazione a una squadra")
    if is_minor:
        # MINORENNI (under 18): unici a fare il PERIODO DI PROVA.
        # 🐛 28/08/2026 — Iter GUIDATO DAI DATI REALI (non dallo `status`, che poteva
        # risultare incoerente: es. due sorelle senza certificato ma con stato diverso).
        # Ordine dei "cancelli", ognuno blocca il successivo:
        #   1) manca la DATA di emissione del certificato   → "manca la data di emissione"
        #   2) data presente ma non convalidata dall'admin  → "certificato da convalidare"
        #   3) certificato convalidato, prova non iniziata  → "prima presenza (QR)"
        #   4) prova in corso                                → nessun sollecito (badge "In prova")
        #   5) prova terminata, privacy non firmata          → "firma della privacy"
        cert_date = (a.get("medical_certificate_issue_date")
                     or a.get("medical_certificate_date")
                     or a.get("medical_certificate_expiry"))
        if not cert_date:
            parts.append("manca la data di emissione del certificato medico")
        elif not cert:
            parts.append("certificato medico da convalidare dalla società")
        elif not trial_started:
            parts.append("prima presenza in palestra (scansione QR) per avviare la prova")
        elif not priv and status in ("pending_privacy", "pending_decision"):
            # Prova terminata: manca la scelta di restare (firma privacy)
            parts.append("firma della privacy da parte del genitore")
        # else: prova in corso regolare → nessun sollecito
    else:
        # ADULTI (18+): niente prova → serve privacy firmata + certificato convalidato
        if not priv:
            parts.append("firma della privacy da parte dell'atleta")
        if not cert:
            parts.append("certificato medico convalidato dalla società")
    if not parts:
        return None
    return "In attesa: " + " + ".join(parts)


def compute_status_badge(a: dict) -> Optional[str]:
    """🆕 28/08/2026 — Etichetta di STATO coerente per il badge, GUIDATA DAI DATI reali
    (non dallo `status` enum, che può essere incoerente: due atlete nello stesso stato
    documentale mostravano badge diversi). Ritorna None per stati gestiti altrove
    (ritirato/attivo/da approvare) → in quel caso il frontend usa il fallback classico."""
    if a.get("is_withdrawn"):
        return None
    status = a.get("status") or "pending"
    if status in ("blocked", "rejected", "pending", "pending_email", "active"):
        return None
    is_minor = _compute_is_minor(a)
    priv = bool(a.get("privacy_accepted"))
    cert = bool(a.get("medical_certificate_verified"))
    trial_started = bool(a.get("trial_start_date"))
    cert_date = (a.get("medical_certificate_issue_date")
                 or a.get("medical_certificate_date")
                 or a.get("medical_certificate_expiry"))
    if is_minor:
        if not cert_date:
            return "Attesa Certificato"
        if not cert:
            return "Validazione Certificato"
        if not trial_started:
            return "Attesa Prova"
        if status in ("pending_privacy", "pending_decision") and not priv:
            return "Attesa Privacy"
        if trial_started:
            return "In Prova"
        return None
    else:
        if not priv:
            return "Attesa Privacy"
        if not cert:
            return "Validazione Certificato"
        return None


class Athlete(BaseModel):
    id: str = Field(default_factory=lambda: str(ObjectId()))
    society_id: Optional[str] = None  # ID della società (multi-tenancy)
