# ==================== HELPER FUNCTIONS ====================

def clean_mongo_doc(doc):
    """Remove _id from MongoDB document and convert datetime fields for JSON serialization"""
    if doc:
        doc.pop('_id', None)
        # Convert datetime fields to ISO string WITH TIME AND TIMEZONE
        for key, value in list(doc.items()):
            if isinstance(value, datetime):
                # Include time and UTC timezone for proper frontend parsing
                doc[key] = value.replace(tzinfo=timezone.utc).strftime("%Y-%m-%dT%H:%M:%S+00:00")
    return doc

def clean_mongo_docs(docs):
    """Remove _id from list of MongoDB documents"""
    return [clean_mongo_doc(doc) for doc in docs]

def hash_password(password: str) -> str:
    return pwd_context.hash(password)

def verify_password(plain_password: str, hashed_password: str) -> bool:
    return pwd_context.verify(plain_password, hashed_password)

def create_token(user_id: str, role: str, athlete_id: str = None) -> str:
    payload = {
        "user_id": user_id,
        "role": role,
        "exp": datetime.utcnow() + timedelta(days=30)
    }
    if athlete_id:
        payload["athlete_id"] = athlete_id
    return jwt.encode(payload, SECRET_KEY, algorithm=ALGORITHM)

import time as _auth_time

# ============================================================
# ⚡ 18/08/2026 — Cache autenticazione per ridurre il carico su MongoDB Atlas M0.
# ------------------------------------------------------------
# PROBLEMA: ogni pagina del dashboard spara ~10 richieste in parallelo; ognuna
# eseguiva in get_current_user 1 LETTURA utente + 1 SCRITTURA (last_active_at).
# Su Atlas M0 (throughput molto limitato) il burst di ~20 operazioni si accoda
# e ogni richiesta finiva per impiegare 7-9s (anche endpoint banali come
# /seasons/current-name da 0.3kB).
# SOLUZIONE: cache in-process del documento utente (TTL breve) + throttle della
# scrittura last_active_at (max 1 volta/60s per utente). Sotto burst passiamo da
# ~20 operazioni Mongo a 1-2. La staleness max è pari al TTL (accettabile per
# ruolo/status/assigned_teams in un gestionale).
_AUTH_USER_CACHE = {}          # user_id -> (expires_at_monotonic, user_projection_dict)
_AUTH_CACHE_TTL = 8            # secondi — sufficiente a deduplicare il burst di richieste
                              # del caricamento pagina (10-15 in ~1-2s) con staleness trascurabile
_LAST_ACTIVE_WRITTEN = {}      # user_id -> last_write_monotonic
_LAST_ACTIVE_MIN_INTERVAL = 60 # secondi
_AUTH_INFLIGHT = {}            # user_id -> Future: dedup delle letture CONCORRENTI
                              # (il burst di ~30 richieste simultanee condivide 1 sola query)

# 🚀 06/2026 — Cache generica a tempo (TTL 10 min) per risultati costosi tipo le
# statistiche Prime Squadre: { key: (expires_at_monotonic, value) }.
_TTL_RESULT_CACHE = {}

def _ttl_cache_get(key: str):
    entry = _TTL_RESULT_CACHE.get(key)
    if entry and entry[0] > _auth_time.monotonic():
        return entry[1]
    return None

def _ttl_cache_set(key: str, value, ttl: int = 600):
    _TTL_RESULT_CACHE[key] = (_auth_time.monotonic() + ttl, value)
    if len(_TTL_RESULT_CACHE) > 2000:
        _TTL_RESULT_CACHE.clear()

def invalidate_ttl_cache(prefix: str = ""):
    """Invalida le voci della cache TTL che iniziano con `prefix` (o tutte se vuoto)."""
    if not prefix:
        _TTL_RESULT_CACHE.clear()
        return
    for k in [k for k in _TTL_RESULT_CACHE if k.startswith(prefix)]:
        _TTL_RESULT_CACHE.pop(k, None)


def _auth_cache_get(user_id: str):
    entry = _AUTH_USER_CACHE.get(user_id)
    if entry and entry[0] > _auth_time.monotonic():
        return entry[1]
    return None

def _auth_cache_set(user_id: str, user_doc: dict):
    _AUTH_USER_CACHE[user_id] = (_auth_time.monotonic() + _AUTH_CACHE_TTL, user_doc)
    # Bound memory: evita crescita illimitata della cache
    if len(_AUTH_USER_CACHE) > 5000:
        _AUTH_USER_CACHE.clear()

def invalidate_auth_cache(user_id: str):
    """Da chiamare quando cambiano ruolo/status/assigned_teams/permessi di un utente."""
    _AUTH_USER_CACHE.pop(user_id, None)

async def get_current_user(credentials: HTTPAuthorizationCredentials = Depends(security)):
    try:
        token = credentials.credentials
        payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
        user_id = payload.get("user_id")
        role = payload.get("role")
        
        # Minor role: user_id is the athlete_id, no user document
        if role == "minor":
            cached = _auth_cache_get(f"minor:{user_id}")
            if cached is not None:
                return cached
            # Projection: exclude heavy base64 fields and _id
            athlete = await db.athletes.find_one(
                {"id": user_id},
                {"_id": 0, "id": 1, "full_name": 1, "status": 1, "society_id": 1},
            )
            if not athlete:
                raise HTTPException(status_code=401, detail="Atleta non trovato")
            result = {
                "id": user_id,
                "role": "minor",
                "email": "",
                "full_name": athlete.get("full_name", ""),
                "assigned_teams": [],
                "status": athlete.get("status", "active"),
                "society_id": athlete.get("society_id"),
                "athlete_id": user_id,
            }
            _auth_cache_set(f"minor:{user_id}", result)
            return result

        # ⚡ Cache: evita la lettura utente su OGNI richiesta (vedi nota sopra).
        user = _auth_cache_get(user_id)
        if user is None:
            # ⚡ In-flight dedup: se una lettura per questo user_id è già in corso,
            # le richieste concorrenti attendono LA STESSA query invece di lanciarne
            # una ciascuna (fondamentale per non saturare Atlas M0 durante il burst
            # di apertura pagina, quando ~30 richieste arrivano insieme).
            import asyncio as _aio_auth
            _fut = _AUTH_INFLIGHT.get(user_id)
            if _fut is None:
                _fut = _aio_auth.ensure_future(db.users.find_one(
                    {"id": user_id},
                    {
                        "_id": 0,
                        "email": 1,
                        "full_name": 1,
                        "assigned_teams": 1,
                        "status": 1,
                        "society_id": 1,
                        "athlete_id": 1,
                        "coach_id": 1,
                        "coordinator_permissions": 1,
                        "pending_dirigente_user_id": 1,
                        "linked_dirigente_user_id": 1,
                    },
                ))
                _AUTH_INFLIGHT[user_id] = _fut
                try:
                    user = await _fut
                finally:
                    _AUTH_INFLIGHT.pop(user_id, None)
            else:
                user = await _fut
            if not user:
                raise HTTPException(status_code=401, detail="User not found")
            _auth_cache_set(user_id, user)

        # 🆕 03/07/2026 — Traccia "utenti online" (last_active_at) MA con throttle:
        # al massimo una scrittura ogni 60s per utente, per non saturare Atlas M0.
        _now_mono = _auth_time.monotonic()
        if _now_mono - _LAST_ACTIVE_WRITTEN.get(user_id, 0.0) > _LAST_ACTIVE_MIN_INTERVAL:
            _LAST_ACTIVE_WRITTEN[user_id] = _now_mono
            try:
                import asyncio as _asyncio
                _asyncio.create_task(db.users.update_one(
                    {"id": user_id},
                    {"$set": {"last_active_at": datetime.utcnow().isoformat()}},
                ))
            except Exception:
                pass

        return {
            "id": user_id, 
            "role": role, 
            "email": user["email"], 
            "full_name": user["full_name"],
            "assigned_teams": list(user.get("assigned_teams", [])),
            "status": user.get("status", "pending"),
            "society_id": user.get("society_id"),
            "athlete_id": user.get("athlete_id"),  # For athlete role
            "coach_id": user.get("coach_id"),      # For coach role
            "coordinator_permissions": list(user.get("coordinator_permissions") or []),
            "pending_dirigente_user_id": user.get("pending_dirigente_user_id"),
            "linked_dirigente_user_id": user.get("linked_dirigente_user_id"),
        }
    except jwt.ExpiredSignatureError:
        raise HTTPException(status_code=401, detail="Token expired")
    except jwt.InvalidTokenError:
        raise HTTPException(status_code=401, detail="Invalid token")
    except Exception as e:
        logging.error(f"JWT decode error: {str(e)}")
        raise HTTPException(status_code=401, detail="Invalid token")


async def _settings_logo_b64(society) -> str:
    """⚡ 06/2026 — Ritorna il logo società come base64/data-URI.
    Dual-read: se il logo è stato migrato su Emergent Object Storage
    (campo logo_storage_path) lo recupera da lì, altrimenti usa il base64
    legacy in `logo`. Ritorna stringa vuota se assente.
    """
    if not society:
        return ""
    lg = society.get("logo")
    if lg:
        return lg
    sp = society.get("logo_storage_path")
    if sp:
        try:
            from storage_util import get_image_datauri
            return await get_image_datauri(sp) or ""
        except Exception:
            return ""
    return ""


def generate_qr_code(athlete_id: str) -> str:
    """Generate QR code and return as base64 string"""
    qr = qrcode.QRCode(version=1, box_size=10, border=5)
    qr.add_data(athlete_id)
    qr.make(fit=True)
    
    img = qr.make_image(fill_color="black", back_color="white")
    
    # Convert to base64
    buffered = io.BytesIO()
    img.save(buffered, format="PNG")
    img_str = base64.b64encode(buffered.getvalue()).decode()
    
    return f"data:image/png;base64,{img_str}"

def generate_qr_identifier() -> str:
    """Generate unique 12-char alphanumeric QR identifier for athlete"""
    import secrets
    import string
    # Use uppercase letters and digits, excluding confusing chars (0, O, I, 1, L)
    alphabet = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789'
    return ''.join(secrets.choice(alphabet) for _ in range(12))


async def resolve_athlete_code_for_cf(fiscal_code: Optional[str]) -> str:
    """🆕 09/07/2026 (v7.12) — Risolve l'athlete_code garantendo persistenza per Codice Fiscale.
    
    Il codice atleta DEVE essere legato alla persona (identificata dal CF italiano),
    non alla società. Se la stessa persona viene registrata in società diverse
    (rinnovo o cambio società), riusa lo stesso athlete_code.
    
    Regole:
      1. Se `fiscal_code` è fornito (16 char) e già esiste un atleta con quel CF
         (in QUALSIASI società, case-insensitive) → riusa il suo `athlete_code`.
      2. Se il CF non è ancora nel sistema, genera un nuovo codice univoco.
      3. Se `fiscal_code` è vuoto/None (edge case: registrazione senza CF), genera
         un nuovo codice univoco.
    
    Sicurezza: non espone dati sensibili — solo il codice viene riusato, tutti gli
    altri campi (email, indirizzo, telefono, iscrizione) sono nuovi per la nuova società.
    """
    if fiscal_code and isinstance(fiscal_code, str):
        cf_normalized = fiscal_code.strip().upper()
        if len(cf_normalized) == 16:
            # Il campo in DB è `fiscal_code` (nome inglese). Case-insensitive search.
            existing = await db.athletes.find_one(
                {"fiscal_code": {"$regex": f"^{cf_normalized}$", "$options": "i"}},
                {"_id": 0, "athlete_code": 1, "qr_identifier": 1},
            )
            if existing:
                reused = existing.get("athlete_code") or existing.get("qr_identifier")
                if reused:
                    logger.info(f"[athlete_code] Riuso codice esistente per CF={cf_normalized[:6]}****: {reused}")
                    return reused
    
    # Nessun CF matching → genera nuovo codice univoco
    qr_id = generate_qr_identifier()
    while await db.athletes.find_one({"$or": [{"qr_identifier": qr_id}, {"athlete_code": qr_id}]}):
        qr_id = generate_qr_identifier()
    return qr_id

def generate_qr_code_from_identifier(qr_identifier: str) -> str:
    """Generate QR code image from qr_identifier"""
    qr = qrcode.QRCode(version=1, box_size=10, border=5)
    qr.add_data(qr_identifier)
    qr.make(fit=True)
    
    img = qr.make_image(fill_color="black", back_color="white")
    
    # Convert to base64
    buffered = io.BytesIO()
    img.save(buffered, format="PNG")
    img_str = base64.b64encode(buffered.getvalue()).decode()
    
    return f"data:image/png;base64,{img_str}"

def generate_athlete_code(last_name: str, first_name: str, team_name: str) -> str:
    """DEPRECATED: Non usare. athlete_code = qr_identifier (12-char alfanumerico per privacy)."""
    return generate_qr_identifier()

async def update_athlete_code(athlete_id: str):
    """Update athlete code to match qr_identifier"""
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        return None
    
    qr_id = athlete.get("qr_identifier")
    if qr_id:
        await db.athletes.update_one(
            {"id": athlete_id},
            {"$set": {"athlete_code": qr_id}}
        )
        return qr_id
    return athlete.get("athlete_code")


async def find_existing_athlete_by_fiscal_code(fiscal_code: str, society_id: str = None):
    """Check if an athlete with this fiscal code already exists.
    Returns the existing athlete record if found, None otherwise.
    The qr_identifier is permanent and tied to the person via fiscal code."""
    if not fiscal_code:
        return None
    
    fc = fiscal_code.strip().upper()
    if not fc:
        return None
    
    # Search globally first (athlete could come from any society)
    query = {"fiscal_code": fc}
    existing = await db.athletes.find_one(query)
    return existing


async def get_trial_block_reason(athlete: dict) -> Optional[str]:
    """🐛 Fix prove oltre il limite: ritorna il motivo di blocco se l'atleta è in
    PROVA e la prova è TERMINATA (giorni scaduti OPPURE sedute massime raggiunte).
    Prima veniva controllata solo la scadenza in giorni (e solo se la privacy non
    era accettata), quindi gli atleti in prova accumulavano presenze oltre il massimo."""
    status = athlete.get("status")
    if not (bool(athlete.get("is_trial")) or status in ("trial", "pending_trial")):
        return None
    if status in ("active", "approved"):
        return None  # già iscritto/attivo: il flag is_trial è residuo
    trial_start = athlete.get("trial_start_date")
    if not trial_start:
        return None  # prova non ancora iniziata: la prima presenza la avvia
    _sid = athlete.get("society_id")
    ss = await db.settings.find_one({"type": "society", "society_id": _sid}, {"_id": 0, "trial_max_sessions": 1}) if _sid else None
    max_sessions = int((ss or {}).get("trial_max_sessions", 3) or 3)
    sessions_count = int(athlete.get("trial_sessions_count", 0) or 0)
    if sessions_count >= max_sessions:
        return f"Periodo di prova terminato ({sessions_count}/{max_sessions} allenamenti) - iscrizione richiesta"
    trial_end = athlete.get("trial_end_date")
    if trial_end:
        try:
            end_dt = datetime.fromisoformat(str(trial_end)) if isinstance(trial_end, str) else trial_end
            if datetime.utcnow() > end_dt.replace(tzinfo=None):
                return "Periodo di prova terminato (giorni scaduti) - iscrizione richiesta"
        except Exception:
            pass
    return None


async def check_athlete_status(athlete_id: str):
    """Check if athlete can attend (certificate valid, payments up to date, privacy accepted)"""
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        return {"allowed": False, "reason": "Atleta non trovato", "warning": None}
    
    # Check if athlete is withdrawn
    if athlete.get("is_withdrawn", False):
        return {"allowed": False, "reason": "⛔ ATLETA RITIRATO - Non più iscritto alla squadra", "warning": None}
    
    # Prova terminata (giorni O sedute massime) → blocco finché non si iscrive
    trial_block = await get_trial_block_reason(athlete)
    if trial_block:
        return {"allowed": False, "reason": trial_block, "warning": None}
    # Prova in corso (non terminata): atleta in prova con is_trial o status trial/pending_trial
    trial_active = bool(athlete.get("is_trial")) or athlete.get("status") in ("trial", "pending_trial")
    
    # Check society settings for certificate blocking — 🐛 08/07/2026 fix multi-tenancy
    _asid = athlete.get("society_id")
    society_settings = await db.settings.find_one({"type": "society", "society_id": _asid}) if _asid else await db.settings.find_one({"type": "society"})
    block_certificates = True  # Default: block
    if society_settings:
        block_certificates = society_settings.get("block_expired_certificates", True)
        # Check if temporary override has expired
        override_expires = society_settings.get("override_expires_at")
        if override_expires and not block_certificates:
            try:
                exp_dt = datetime.fromisoformat(override_expires.replace('Z', '+00:00')).replace(tzinfo=None)
                if datetime.utcnow() > exp_dt:
                    # Override expired - reactivate blocking
                    await db.settings.update_one(
                        {"type": "society"},
                        {"$set": {"block_expired_certificates": True, "override_type": None, "override_expires_at": None}}
                    )
                    block_certificates = True
            except:
                pass
    
    # Check certificate (skip ONLY for active trial athletes who haven't accepted privacy yet)
    if trial_active and not athlete.get("privacy_accepted", False):
        # Trial athletes without privacy can train without certificate
        return {"allowed": True, "reason": None, "warning": "Atleta in periodo di prova - Certificato medico richiesto al termine della prova"}
    
    # If certificate blocking is disabled by admin, allow with warning
    if not block_certificates:
        certificate = await db.certificates.find_one({"athlete_id": athlete_id})
        if not certificate:
            return {"allowed": True, "reason": None, "warning": "⚠️ Certificato medico mancante (blocco disattivato dall'admin)"}
        if not athlete.get("medical_certificate_verified", False):
            return {"allowed": True, "reason": None, "warning": "⚠️ Certificato medico non autenticato (blocco disattivato dall'admin)"}
        return {"allowed": True, "reason": None, "warning": None}
    
    # Certificate blocking is ACTIVE
    
    # Check certificate
    certificate = await db.certificates.find_one({"athlete_id": athlete_id})
    cert_expiry = athlete.get("medical_certificate_expiry")
    
    # Determine certificate expiry date
    expiry_date = None
    if certificate and certificate.get("expiry_date"):
        expiry_date = certificate["expiry_date"]
        if isinstance(expiry_date, str):
            try:
                expiry_date = datetime.fromisoformat(expiry_date.replace('Z', '+00:00')).replace(tzinfo=None)
            except:
                expiry_date = None
    elif cert_expiry:
        try:
            expiry_date = datetime.fromisoformat(cert_expiry.replace('Z', '+00:00')).replace(tzinfo=None)
        except:
            expiry_date = None
    
    # Override athlete-specific: se attivo, consente l'ingresso una sola volta
    # indipendentemente dalla causa del blocco (mancante / non autenticato / scaduto)
    override_active = athlete.get("certificate_override_active", False)
    if override_active:
        override_reason = athlete.get("certificate_override_reason", "Autorizzato dall'admin")
        return {
            "allowed": True,
            "reason": f"⚠️ ACCESSO CONSENTITO (Override Admin: {override_reason})",
            "warning": "⚠️ Override certificato attivo SOLO per questo ingresso",
            "override_active": True,
            "athlete_id": athlete_id,
        }

    # Certificato mancante = BLOCCATO
    if not certificate and not cert_expiry:
        return {"allowed": False, "reason": "⛔ CERTIFICATO MEDICO MANCANTE - Atleta NON ammesso", "warning": None}
    
    # Certificato non autenticato dall'admin = BLOCCATO
    if not athlete.get("medical_certificate_verified", False):
        return {"allowed": False, "reason": "⛔ CERTIFICATO MEDICO NON AUTENTICATO - In attesa di verifica admin", "warning": None}
    
    # Check if certificate is expired
    if expiry_date and datetime.utcnow() > expiry_date:
        # No override - BLOCCATO
        return {"allowed": False, "reason": "⛔ CERTIFICATO MEDICO SCADUTO - Atleta NON ammesso all'allenamento", "warning": None}
    
    # Check if certificate is expiring soon (within 30 days)
    cert_warning = None
    if expiry_date:
        days_to_expiry = (expiry_date - datetime.utcnow()).days
        if days_to_expiry <= 30:
            cert_warning = f"⚠️ ATTENZIONE: CERTIFICATO MEDICO IN SCADENZA tra {days_to_expiry} giorni! Provvedere al rinnovo prima della scadenza per evitare di non essere ammessi agli allenamenti."
    
    # Check payments - upcoming due (within 7 days)
    payment_warning = None
    upcoming_payments = await db.payments.find({
        "athlete_id": athlete_id,
        "paid": False,
        "due_date": {
            "$gt": datetime.utcnow(),
            "$lt": datetime.utcnow() + timedelta(days=7)
        }
    }).to_list(100)
    
    if upcoming_payments:
        installments = [p["installment_number"] for p in upcoming_payments]
        amounts = sum(p["amount"] for p in upcoming_payments)
        payment_warning = f"💰 PROMEMORIA: Pagamento rata {', '.join(map(str, installments))} (€{amounts:.2f}) in scadenza entro 7 giorni."
    
    # Check payments overdue
    unpaid_payments = await db.payments.find({
        "athlete_id": athlete_id,
        "paid": False,
        "due_date": {"$lt": datetime.utcnow()}
    }).to_list(100)
    
    if unpaid_payments:
        installments = [p["installment_number"] for p in unpaid_payments]
        amounts = sum(p["amount"] for p in unpaid_payments)
        payment_warning = f"💰 ATTENZIONE: Pagamento rata {', '.join(map(str, installments))} (€{amounts:.2f}) SCADUTO! Ricordare all'atleta."
    
    # Combine warnings
    warnings = []
    if cert_warning:
        warnings.append(cert_warning)
    if payment_warning:
        warnings.append(payment_warning)
    
    combined_warning = "\n\n".join(warnings) if warnings else None
    
    return {"allowed": True, "reason": combined_warning, "warning": combined_warning}

