@api_router.post("/societies")
async def create_society(society_data: SocietyCreate, current_user = Depends(get_current_user)):
    """Create a new society - only for admins without a society or super-admins"""
    # Check if user already has a society
    if current_user.get("society_id"):
        raise HTTPException(status_code=400, detail="Sei già associato a una società")
    
    # Create society with unique invite code
    invite_code = generate_invite_code()
    # Make sure code is unique
    while await db.societies.find_one({"invite_code": invite_code}):
        invite_code = generate_invite_code()
    
    society = Society(
        name=society_data.name,
        email=society_data.email,
        phone=society_data.phone,
        invite_code=invite_code,
        owner_id=current_user["id"]
    )
    
    await db.societies.insert_one(society.dict())
    
    # Update current user with society_id
    await db.users.update_one(
        {"id": current_user["id"]},
        {"$set": {"society_id": society.id}}
    )
    
    return {
        "message": "Società creata con successo",
        "society": {
            "id": society.id,
            "name": society.name,
            "invite_code": society.invite_code
        }
    }

@api_router.get("/societies/my")
async def get_my_society(current_user = Depends(get_current_user)):
    """Get current user's society details"""
    if not current_user.get("society_id"):
        raise HTTPException(status_code=404, detail="Non sei associato a nessuna società")
    
    society = await db.societies.find_one({"id": current_user["society_id"]})
    if not society:
        raise HTTPException(status_code=404, detail="Società non trovata")
    
    # 🚀 16/08/2026 — Backfill compressione logo pesante: riduce payload/RAM e
    # velocizza sia questa pagina sia la generazione del biglietto da visita.
    from utils import compress_base64_image
    _logo = society.get("logo")
    if isinstance(_logo, str) and len(_logo) > 500_000:
        _comp = compress_base64_image(_logo)
        if _comp and _comp != _logo and len(_comp) < len(_logo):
            society["logo"] = _comp
            try:
                await db.societies.update_one({"id": society["id"]}, {"$set": {"logo": _comp}})
            except Exception:
                pass
    
    clean_mongo_doc(society)
    return society


# ============================================================================
# 🆕 27/07/2026 — MULTI-SPORT ARCHITECTURE
# ----------------------------------------------------------------------------
# Ogni società ha uno "sport" (pallavolo, basket, calcio ecc.) + federazione
# + regione (opzionale). Le feature specifiche di uno sport/federazione (es.
# regole FIPAV pallavolo) sono visibili solo quando le precondizioni sono
# soddisfatte via il helper is_feature_enabled().
# ============================================================================

# Sport di squadra supportati (Vincenzo 27/07/2026: solo sport di squadra)
SUPPORTED_SPORTS = {
    "pallavolo":         {"label": "Pallavolo",         "default_federation": "FIPAV"},
    "basket":            {"label": "Basket",            "default_federation": "FIP"},
    "calcio":            {"label": "Calcio",            "default_federation": "FIGC"},
    "calcio_a_5":        {"label": "Calcio a 5",        "default_federation": "FIGC"},
    "pallamano":         {"label": "Pallamano",         "default_federation": "FIGH"},
    "rugby":             {"label": "Rugby",             "default_federation": "FIR"},
    "pallanuoto":        {"label": "Pallanuoto",        "default_federation": "FIN"},
    "hockey":            {"label": "Hockey",            "default_federation": "FIH"},
    "baseball":          {"label": "Baseball",          "default_federation": "FIBS"},
    "softball":          {"label": "Softball",          "default_federation": "FIBS"},
    "football_americano":{"label": "Football americano","default_federation": "FIDAF"},
    "altro":             {"label": "Altro",             "default_federation": None},
}

# Feature flags condizionali per sport/federazione
FEATURE_PRECONDITIONS = {
    # Regole minorenni FIPAV pallavolo (Under 17 - 2 campionati categoria + 10 presenze superiore)
    "fipav_minor_rules": {
        "sport": "pallavolo",
        "federation": "FIPAV",
    },
    # Killswitch stagionale (data specifica FIPAV) — se un giorno cambia federazione, non si applica
    "fipav_killswitch_2027": {
        "sport": "pallavolo",
        "federation": "FIPAV",
    },
}


def is_feature_enabled(society: dict, feature_name: str) -> bool:
    """Verifica se una feature condizionata a sport/federation è abilitata per la società."""
    if not society:
        return False
    precond = FEATURE_PRECONDITIONS.get(feature_name)
    if not precond:
        return True  # Nessuna precondizione = feature sempre abilitata
    # Controlla ogni condizione
    for key, expected in precond.items():
        if society.get(key) != expected:
            return False
    return True


@api_router.get("/societies/sports/available")
async def list_available_sports():
    """Elenco sport supportati e federazioni suggerite (per dropdown UI)."""
    return {
        "sports": [
            {"key": k, "label": v["label"], "default_federation": v["default_federation"]}
            for k, v in SUPPORTED_SPORTS.items()
        ]
    }


class SportConfigUpdate(BaseModel):
    sport: str = Field(..., description="Chiave sport (es. 'pallavolo')")
    federation: Optional[str] = Field(None, description="Federazione (es. 'FIPAV'). Se null usa default sport")
    region: Optional[str] = Field(None, description="Regione italiana (opzionale, per varianti regionali)")


@api_router.patch("/societies/my/sport-config")
async def update_my_society_sport(data: SportConfigUpdate, current_user = Depends(get_current_user)):
    """Admin aggiorna sport/federazione/regione della propria società."""
    if current_user.get("role") != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")
    if not current_user.get("society_id"):
        raise HTTPException(status_code=404, detail="Non sei associato a nessuna società")
    if data.sport not in SUPPORTED_SPORTS:
        raise HTTPException(status_code=400, detail=f"Sport non supportato. Opzioni: {list(SUPPORTED_SPORTS.keys())}")
    # Se federation non specificata usa default per lo sport
    fed = data.federation if data.federation is not None else SUPPORTED_SPORTS[data.sport]["default_federation"]
    await db.societies.update_one(
        {"id": current_user["society_id"]},
        {"$set": {
            "sport": data.sport,
            "federation": fed,
            "region": (data.region or None),
        }}
    )
    return {"success": True, "sport": data.sport, "federation": fed, "region": data.region or None}


@api_router.get("/me/feature-flags")
async def get_my_feature_flags(current_user = Depends(get_current_user)):
    """Ritorna le feature flag abilitate per la società dell'utente corrente.
    Frontend usa questo per mostrare/nascondere sezioni condizionali."""
    society = None
    if current_user.get("society_id"):
        society = await db.societies.find_one({"id": current_user["society_id"]})
    # Default (retrocompatibilità): società esistenti senza campo sport → pallavolo/FIPAV
    if society and not society.get("sport"):
        society = {**society, "sport": "pallavolo", "federation": "FIPAV"}
    flags = {name: is_feature_enabled(society or {}, name) for name in FEATURE_PRECONDITIONS.keys()}
    return {
        "sport": (society or {}).get("sport", "pallavolo"),
        "federation": (society or {}).get("federation", "FIPAV"),
        "region": (society or {}).get("region"),
        "flags": flags,
    }


# ============================================================================
# 🆕 27/07/2026 — REGOLE FIPAV MINORENNI (Under 17 + max 10 presenze serie sup.)
# Vedere PRD.md sezione "Regolamenti FIPAV Minorenni" per le norme testuali.
# ============================================================================
FIPAV_KILLSWITCH_DATE = "2027-03-28"  # domenica 28/03/2027


def _fipav_under_17_cutoff_year(current_season: str) -> Optional[int]:
    """Dato una stagione '2026/2027', ritorna l'anno di nascita minimo per essere U17.
    Formula: secondo_anno_stagione - 17. Es. 2027 - 17 = 2010 → U17 = nati 2010+.
    """
    try:
        parts = current_season.split("/")
        if len(parts) == 2:
            return int(parts[1]) - 17
    except Exception:
        pass
    return None


# 🆕 22/08/2026 — Fase 1 regole FIPAV: fasce d'età per CATEGORIA (SETTORE FEMMINILE).
# Offset relativi al 2° anno di stagione (year2): la fascia scala di +1 ogni stagione.
#   anno_più_vecchio = year2 - oldest_offset   |   anno_più_giovane = year2 - youngest_offset
# Ammesso se: (year2 - oldest_offset) <= anno_nascita <= (year2 - youngest_offset).
# Le fasce NON sono derogabili (limiti fissi su entrambi i lati).
# Esempio (2026/2027 → year2=2027): nata 2012 ammessa SOLO in U15 (2012-2015) e U17 (2010-2013).
FIPAV_FEMALE_CATEGORY_AGE_OFFSETS = {
    "Under 12": (12, 11),  # 2015-2016
    "Under 13": (13, 11),  # 2014-2016
    "Under 14": (14, 12),  # 2013-2015
    "Under 15": (15, 12),  # 2012-2015
    "Under 17": (17, 14),  # 2010-2013
    "Under 19": (19, 16),  # 2008-2011
}


def _fipav_eligible_categories(birth_year: Optional[int], gender: Optional[str], season_year2: Optional[int]) -> List[str]:
    """Ritorna le categorie Under ammesse per età (Fase 1: solo settore FEMMINILE)."""
    if birth_year is None or season_year2 is None:
        return []
    g = (gender or "").lower()
    if not g.startswith("f"):
        return []  # Maschile: da configurare in un futuro upgrade
    out = []
    for label, (old_off, young_off) in FIPAV_FEMALE_CATEGORY_AGE_OFFSETS.items():
        oldest = season_year2 - old_off
        youngest = season_year2 - young_off
        if oldest <= birth_year <= youngest:
            out.append(label)
    out.sort(key=lambda lbl: int(re.search(r"(\d+)", lbl).group(1)) if re.search(r"(\d+)", lbl) else 0)
    return out


def _fipav_category_from_label(s: str) -> Optional[str]:
    """Estrae 'Under NN' da una stringa libera (es. 'U15 F', 'Under 15 Femm.'). None se non è una categoria."""
    m = re.search(r"[Uu](?:nder)?\s*\.?\s*(\d{2})", s or "")
    return f"Under {int(m.group(1))}" if m else None


class FipavAthleteRulesUpdate(BaseModel):
    """Update dei contatori FIPAV per un atleta (manuale da admin)."""
    upper_league_name: Optional[str] = None  # es. "Serie C", "Serie D", "1^ Div F"
    upper_league_presences: Optional[int] = Field(None, ge=0, le=99)
    category_championships: Optional[List[str]] = None  # max 2
    camp3_presences_count: Optional[int] = Field(None, ge=0, le=999)
    weekly_games_count: Optional[int] = Field(None, ge=0, le=10)


@api_router.get("/admin/athletes/{athlete_id}/fipav-rules")
async def get_athlete_fipav_rules(athlete_id: str, current_user = Depends(get_current_user)):
    """Ritorna lo stato dei contatori FIPAV per un atleta (visibile solo se sport=pallavolo+FIPAV)."""
    # 🐛 28/07/2026 — Ora anche i COACH possono LEGGERE (read-only). La PATCH resta admin-only.
    role = current_user.get("role")
    if role not in (UserRole.ADMIN, UserRole.COACH):
        raise HTTPException(status_code=403, detail="Solo admin/coach")
    society = await db.societies.find_one({"id": current_user.get("society_id")})
    if not is_feature_enabled(society or {}, "fipav_minor_rules"):
        raise HTTPException(status_code=400, detail="Feature FIPAV non abilitata per questa società")
    ath = await db.athletes.find_one({"id": athlete_id})
    if not ath:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    if ath.get("society_id") != current_user.get("society_id"):
        raise HTTPException(status_code=403, detail="Atleta non appartiene alla tua società")
    
    # 🆕 01/08/2026 — Registro presenze-gara DATATO (unico registro, alimenta sia
    # gli ingressi in Serie Superiore che il conteggio gare/settimana). I vecchi
    # contatori scalari NON vengono più usati (scelta utente: azzera e riparti pulito).
    from datetime import date as _date, timedelta
    entries = list(ath.get("game_presences") or [])
    entries.sort(key=lambda e: (e.get("date") or ""), reverse=True)
    upper_pres = len([e for e in entries if e.get("level") == "upper"])
    total_pres = len(entries)

    # Conteggio gare per settimana (Lunedì→Domenica) per verifica soglia max 3
    week_counts: Dict[str, int] = {}
    for e in entries:
        try:
            d = _date.fromisoformat((e.get("date") or "")[:10])
        except Exception:
            continue
        monday = d - timedelta(days=d.weekday())
        week_counts[monday.isoformat()] = week_counts.get(monday.isoformat(), 0) + 1
    violation_weeks = [
        {
            "week_start": k,
            "week_end": (_date.fromisoformat(k) + timedelta(days=6)).isoformat(),
            "count": v,
        }
        for k, v in sorted(week_counts.items()) if v > 3
    ]
    max_week = max(week_counts.values()) if week_counts else 0

    blocked = False
    # Auto-blocco se ha raggiunto 11 presenze
    if upper_pres >= 11:
        blocked = True
    # Auto-blocco post-killswitch (28/03/2027) con almeno 1 presenza
    from datetime import date
    try:
        today = date.today()
        killswitch = date.fromisoformat(FIPAV_KILLSWITCH_DATE)
        if today >= killswitch and upper_pres >= 1:
            blocked = True
    except Exception:
        pass
    
    # 🐛 29/07/2026 — Il campo canonico è `date_of_birth`; `birth_date` è stato usato
    # solo in poche righe legacy. Senza questo fallback l'UI riceveva birthYear=null e
    # non renderizzava NÉ i contatori NÉ il messaggio "non eligibile" → sezioni vuote.
    _dob_raw = ath.get("date_of_birth") or ath.get("birth_date") or ""
    _dob_str = _dob_raw.isoformat() if hasattr(_dob_raw, "isoformat") else str(_dob_raw)
    _birth_year = _dob_str[:4] if _dob_str and len(_dob_str) >= 4 and _dob_str[:4].isdigit() else None

    # 🆕 01/08/2026 — Soglie anni-di-nascita RELATIVE ALLA STAGIONE (non più hardcoded).
    # Le norme FIPAV scalano di +1 anno ogni stagione. Formula sul 2° anno stagione:
    #   U17 (categoria)          = anno2 - 17   → 2026/2027 = 2010
    #   Serie superiore maschi   = anno2 - 21   → 2026/2027 = 2006
    #   Serie superiore femmine  = anno2 - 19   → 2026/2027 = 2008
    from utils import get_current_season_for_society as _get_cs_fipav
    _season = await _get_cs_fipav(db, current_user.get("society_id"))
    try:
        _season_year2 = int(_season.replace("/", "-").split("-")[1])
    except Exception:
        _season_year2 = datetime.utcnow().year + (1 if datetime.utcnow().month >= 7 else 0)
    _u17_min = _season_year2 - 17
    _upper_male_min = _season_year2 - 21
    _upper_female_min = _season_year2 - 19
    _by_int = int(_birth_year) if _birth_year else None
    _gender_l = (ath.get("gender") or ath.get("sex") or "").lower()
    _is_male = _gender_l.startswith("m")
    _is_female = _gender_l.startswith("f")
    _elig_upper = _by_int is not None and (
        (_is_male and _by_int >= _upper_male_min) or (_is_female and _by_int >= _upper_female_min)
    )
    _elig_u17 = _by_int is not None and _by_int >= _u17_min
    _season_label = _season.replace("-", "/")
    # 🆕 22/08/2026 — Fase 1: categorie Under ammesse per età (settore femminile)
    _eligible_categories = _fipav_eligible_categories(
        _by_int, ath.get("gender") or ath.get("sex"), _season_year2
    )

    return {
        "athlete_id": athlete_id,
        "athlete_name": ath.get("full_name") or f"{ath.get('first_name','')} {ath.get('last_name','')}".strip(),
        "birth_year": _birth_year,
        "gender": ath.get("gender") or ath.get("sex") or "",
        # Feature A - campionati di categoria (U17)
        "category_championships": list(ath.get("category_championships") or []),
        "camp3_presences_count": total_pres,
        # 🆕 Fase 1: categorie ammesse per età (femminile). Lista vuota se non calcolabile.
        "eligible_categories": _eligible_categories,
        "weekly_games_count": max_week,
        # Feature B - presenze serie superiore
        "upper_league_name": ath.get("upper_league_name") or "",
        "upper_league_presences": upper_pres,
        "blocked_from_lower_league": blocked,
        "killswitch_date": FIPAV_KILLSWITCH_DATE,
        # 🆕 01/08/2026 — Registro datato + verifica soglia settimanale
        "game_presences": entries,
        "upper_league_options": ["Serie C", "Serie D", "1^ Divisione"],
        "weekly_summary": {"max_in_any_week": max_week, "violation_weeks": violation_weeks},
        # 🆕 01/08/2026 — Stagione + soglie eleggibilità relative alla stagione
        "season": _season_label,
        "eligibility": {
            "season": _season_label,
            "upper_league_min_year_male": _upper_male_min,
            "upper_league_min_year_female": _upper_female_min,
            "u17_min_year": _u17_min,
            "is_eligible_upper_league": _elig_upper,
            "is_eligible_u17": _elig_u17,
        },
    }


@api_router.patch("/admin/athletes/{athlete_id}/fipav-rules")
async def update_athlete_fipav_rules(
    athlete_id: str,
    data: FipavAthleteRulesUpdate,
    current_user = Depends(get_current_user),
):
    """Admin aggiorna contatori FIPAV dell'atleta.
    - category_championships: max 2 selezioni (validato)
    - upper_league_presences: aggiornamento manuale +/- (validato 0-99)
    """
    if current_user.get("role") != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")
    society = await db.societies.find_one({"id": current_user.get("society_id")})
    if not is_feature_enabled(society or {}, "fipav_minor_rules"):
        raise HTTPException(status_code=400, detail="Feature FIPAV non abilitata per questa società")
    ath = await db.athletes.find_one({"id": athlete_id})
    if not ath:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    if ath.get("society_id") != current_user.get("society_id"):
        raise HTTPException(status_code=403, detail="Atleta non appartiene alla tua società")
    
    # Validazione max 2 campionati categoria
    if data.category_championships is not None:
        clean_list = [c.strip() for c in data.category_championships if c and c.strip()]
        if len(clean_list) > 2:
            raise HTTPException(status_code=400, detail="Massimo 2 campionati di categoria consentiti (norma FIPAV U17)")
        data.category_championships = clean_list

        # 🆕 22/08/2026 — Fase 1: i campionati di categoria scelti devono essere tra
        # quelli ammessi per l'età dell'atleta (settore femminile). Le voci "serie"
        # (senza pattern "Under NN") non vengono vincolate qui.
        _dob_raw_p = ath.get("date_of_birth") or ath.get("birth_date") or ""
        _dob_str_p = _dob_raw_p.isoformat() if hasattr(_dob_raw_p, "isoformat") else str(_dob_raw_p)
        _by_p = int(_dob_str_p[:4]) if _dob_str_p[:4].isdigit() else None
        from utils import get_current_season_for_society as _get_cs_p
        _season_p = await _get_cs_p(db, current_user.get("society_id"))
        try:
            _season2_p = int(_season_p.replace("/", "-").split("-")[1])
        except Exception:
            _season2_p = None
        _eligible_p = _fipav_eligible_categories(_by_p, ath.get("gender") or ath.get("sex"), _season2_p)
        if _eligible_p:
            for _c in clean_list:
                _cat = _fipav_category_from_label(_c)
                if _cat and _cat not in _eligible_p:
                    raise HTTPException(
                        status_code=400,
                        detail=f"'{_c}' non è tra le categorie ammesse per l'età dell'atleta. Ammesse: {', '.join(_eligible_p)}.",
                    )
    
    update_dict = {}
    for field in ["upper_league_name", "upper_league_presences", "category_championships",
                  "camp3_presences_count", "weekly_games_count"]:
        val = getattr(data, field)
        if val is not None:
            update_dict[field] = val
    
    # Auto-flag blocked_from_lower_league quando >= 11 presenze
    if data.upper_league_presences is not None and data.upper_league_presences >= 11:
        update_dict["blocked_from_lower_league"] = True
    
    if update_dict:
        await db.athletes.update_one({"id": athlete_id}, {"$set": update_dict})
    
    # Ritorna lo stato aggiornato
    return await get_athlete_fipav_rules(athlete_id, current_user)


UPPER_LEAGUE_SET = {"Serie C", "Serie D", "1^ Divisione"}


class FipavPresenceAdd(BaseModel):
    """🆕 01/08/2026 — Aggiunta di un ingresso/gara al registro datato FIPAV."""
    date: str  # formato YYYY-MM-DD
    championship: str  # es. "Serie C" (superiore) oppure "Under 14" (categoria)


async def _fipav_guard(athlete_id: str, current_user, require_admin: bool = True):
    """Guardia comune: ruolo, feature flag, appartenenza società. Ritorna (society, ath)."""
    if require_admin and current_user.get("role") != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")
    society = await db.societies.find_one({"id": current_user.get("society_id")})
    if not is_feature_enabled(society or {}, "fipav_minor_rules"):
        raise HTTPException(status_code=400, detail="Feature FIPAV non abilitata per questa società")
    ath = await db.athletes.find_one({"id": athlete_id})
    if not ath:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    if ath.get("society_id") != current_user.get("society_id"):
        raise HTTPException(status_code=403, detail="Atleta non appartiene alla tua società")
    return society, ath


async def _persist_fipav_derived(athlete_id: str, entries: list):
    """Ricalcola e persiste i contatori derivati dal registro datato."""
    from datetime import date as _date
    upper_pres = len([e for e in entries if e.get("level") == "upper"])
    blocked = upper_pres >= 11
    try:
        if _date.today() >= _date.fromisoformat(FIPAV_KILLSWITCH_DATE) and upper_pres >= 1:
            blocked = True
    except Exception:
        pass
    await db.athletes.update_one(
        {"id": athlete_id},
        {"$set": {
            "game_presences": entries,
            "upper_league_presences": upper_pres,
            "camp3_presences_count": len(entries),
            "blocked_from_lower_league": blocked,
        }},
    )


@api_router.post("/admin/athletes/{athlete_id}/fipav-presences")
async def add_athlete_fipav_presence(
    athlete_id: str,
    data: FipavPresenceAdd,
    current_user = Depends(get_current_user),
):
    """Aggiunge un ingresso datato al registro presenze-gara dell'atleta.
    - Blocco doppio inserimento: max 1 gara per data (scelta utente).
    - Il livello (superiore/categoria) è dedotto dal campionato scelto.
    """
    from datetime import date as _date
    society, ath = await _fipav_guard(athlete_id, current_user)

    # Validazione data
    try:
        _date.fromisoformat((data.date or "")[:10])
    except Exception:
        raise HTTPException(status_code=400, detail="Data non valida (formato richiesto: AAAA-MM-GG)")
    championship = (data.championship or "").strip()
    if not championship:
        raise HTTPException(status_code=400, detail="Seleziona il campionato/gara dell'ingresso")

    entries = list(ath.get("game_presences") or [])
    # Blocco duplicato sulla stessa data (max 1 gara/giorno)
    if any((e.get("date") or "")[:10] == data.date[:10] for e in entries):
        raise HTTPException(
            status_code=400,
            detail="Esiste già una gara registrata in questa data (max 1 gara al giorno).",
        )

    level = "upper" if championship in UPPER_LEAGUE_SET else "category"
    entry = {
        "id": str(uuid.uuid4()),
        "date": data.date[:10],
        "championship": championship,
        "level": level,
        "added_by": current_user.get("id"),
        "added_by_name": current_user.get("full_name") or current_user.get("email") or "admin",
        "created_at": datetime.now(timezone.utc).isoformat(),
    }
    entries.append(entry)
    await _persist_fipav_derived(athlete_id, entries)
    return await get_athlete_fipav_rules(athlete_id, current_user)


@api_router.delete("/admin/athletes/{athlete_id}/fipav-presences/{entry_id}")
async def delete_athlete_fipav_presence(
    athlete_id: str,
    entry_id: str,
    current_user = Depends(get_current_user),
):
    """Rimuove un ingresso dal registro presenze-gara dell'atleta."""
    society, ath = await _fipav_guard(athlete_id, current_user)
    entries = list(ath.get("game_presences") or [])
    new_entries = [e for e in entries if e.get("id") != entry_id]
    if len(new_entries) == len(entries):
        raise HTTPException(status_code=404, detail="Ingresso non trovato")
    await _persist_fipav_derived(athlete_id, new_entries)
    return await get_athlete_fipav_rules(athlete_id, current_user)



