@api_router.post("/admin/users/{user_id}/change-email")
async def admin_change_user_email(user_id: str, payload: dict, current_user = Depends(get_current_user)):
    """Admin-only: change a user's email. Accepts user_id OR athlete_id.
    Verifica nuova email univoca, aggiorna user, e (se atleta) anche il record athlete.
    NB: l'admin cambia l'email ma la nuova deve essere RIVERIFICATA dall'utente
    tramite link inviato via Brevo. Lo status torna a `pending_email` per gli atleti
    minorenni / `pending_email_user` per gli adulti finché non clicca il link.
    """
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può cambiare email")
    new_email = (payload.get("new_email") or "").strip().lower()
    if not new_email or "@" not in new_email:
        raise HTTPException(status_code=400, detail="Email non valida")

    # Trova user (per user_id o athlete_id)
    user = await db.users.find_one({"id": user_id})
    if not user:
        user = await db.users.find_one({"athlete_id": user_id})
    if not user:
        raise HTTPException(status_code=404, detail="Utente non trovato")
    # Multi-tenant safety
    if current_user.get("society_id") and user.get("society_id") and \
            current_user["society_id"] != user["society_id"]:
        raise HTTPException(status_code=403, detail="L'utente appartiene a un'altra società")

    # Verifica univocità nuova email (no conflitti su altri user)
    existing = await db.users.find_one(
        {"email": new_email, "id": {"$ne": user["id"]}},
        {"_id": 0, "id": 1},
    )
    if existing:
        raise HTTPException(status_code=409, detail="Email già usata da un altro utente")

    old_email = user.get("email")
    new_token = secrets.token_urlsafe(32)
    await db.users.update_one(
        {"id": user["id"]},
        {"$set": {
            "email": new_email,
            "email_verified": False,
            "email_verification_token": new_token,
            "email_changed_by": current_user["id"],
            "email_changed_at": datetime.now(timezone.utc).isoformat(),
            "previous_email": old_email,
        }}
    )
    # Aggiorna anche record athlete se applicabile
    athlete_id = user.get("athlete_id")
    if athlete_id:
        await db.athletes.update_one(
            {"id": athlete_id},
            {"$set": {"email": new_email}}
        )

    # Invia mail di verifica al nuovo indirizzo
    try:
        society = await db.societies.find_one(
            {"id": user.get("society_id")},
            {"_id": 0, "name": 1},
        )
        full_name = user.get("full_name") or user.get("first_name") or ""
        await _send_verification_email(
            new_email,
            new_token,
            full_name,
            (society or {}).get("name", ""),
        )
        verification_sent = True
    except Exception as e:
        logging.error(f"[ADMIN-CHANGE-EMAIL] verification email failed: {e}")
        verification_sent = False

    logging.warning(
        f"[ADMIN-CHANGE-EMAIL] admin={current_user.get('email')} user={user['id']} "
        f"old={old_email} new={new_email} verification_sent={verification_sent}"
    )
    return {
        "message": "Email aggiornata. Verifica inviata al nuovo indirizzo." if verification_sent
                   else "Email aggiornata, ma invio mail di verifica fallito.",
        "old_email": old_email,
        "new_email": new_email,
        "verification_sent": verification_sent,
    }


@api_router.post("/admin/users/{user_id}/force-verify-email")
async def admin_force_verify_email(user_id: str, current_user = Depends(get_current_user)):
    """Admin-only: force verify a user's email without sending the link.
    Useful for test accounts (yopmail) or users who can't access their inbox.
    The path param can be either a user_id OR an athlete_id (fallback lookup).
    """
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può forzare la verifica email")

    user = await db.users.find_one({"id": user_id})
    if not user:
        # Fallback: lookup by athlete_id
        user = await db.users.find_one({"athlete_id": user_id})
    if not user:
        raise HTTPException(status_code=404, detail="Utente non trovato")

    # Enforce same society
    if current_user.get("society_id") and user.get("society_id") and \
            current_user["society_id"] != user["society_id"]:
        raise HTTPException(status_code=403, detail="L'utente appartiene a un'altra società")

    if user.get("email_verified") and user.get("status") not in ("pending_email", None):
        return {"message": "Utente già verificato", "already_verified": True}

    # 🆕 ADULTI (18+): niente periodo di prova → dopo verifica restano "pending"
    # (in attesa di approvazione admin). I minorenni mantengono "pending_trial".
    _fv_athlete_id = user.get("athlete_id")
    _fv_athlete = await db.athletes.find_one({"id": _fv_athlete_id}) if _fv_athlete_id else None
    _fv_is_minor = _compute_is_minor(_fv_athlete) if _fv_athlete else False
    if user.get("role") == "athlete":
        new_user_status = "pending_trial" if _fv_is_minor else "pending"
    else:
        new_user_status = "approved"
    await db.users.update_one(
        {"id": user_id},
        {"$set": {
            "email_verified": True,
            "status": new_user_status,
            "email_verification_token": None,
            "verified_at": datetime.now(timezone.utc).isoformat(),
            "force_verified_by": current_user["id"],
        }}
    )
    # Activate athlete record if applicable
    athlete_id = user.get("athlete_id")
    if athlete_id:
        await db.athletes.update_one(
            {"id": athlete_id},
            {"$set": {"status": "pending_trial" if _fv_is_minor else "pending"}}
        )
    # For parent, activate the linked minor athlete
    if user.get("role") == "parent":
        await db.athletes.update_many(
            {"parent_id": user_id, "status": "pending_email"},
            {"$set": {"status": "pending_trial"}}
        )

    return {"message": "Email verificata forzatamente dall'admin", "verified": True}


