# Modello per registrazione atleta maggiorenne (self-registration)
class AdultAthleteRegister(BaseModel):
    email: str
    password: str
    first_name: str
    last_name: str
    phone: str
    invite_code: str  # Required to join a society
    date_of_birth: Optional[str] = None  # YYYY-MM-DD format, optional initially
    fiscal_code: Optional[str] = None
    gender: Optional[str] = None  # 'M' or 'F'
    consents: Optional[dict] = None  # {privacy_viewed: bool, images_promo: bool}


# 🐛 03/08/2026 — Validazione formato email: un'email non valida (es. dominio "18+.com"
# con il "+") veniva accettata, il record creato, e un passaggio successivo falliva →
# errore generico + iscrizione "fantasma". Blocchiamo subito con messaggio chiaro.
import re as _re_email
_EMAIL_RE = _re_email.compile(r"^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)+$")

def is_valid_email(email: str) -> bool:
    if not email or not isinstance(email, str):
        return False
    email = email.strip()
    if len(email) > 254 or ".." in email:
        return False
    return bool(_EMAIL_RE.match(email))


@api_router.post("/auth/register-adult-athlete")
async def register_adult_athlete(data: AdultAthleteRegister):
    """
    Self-registration for adult athletes (18+).
    Creates both a user account and an athlete record.
    Account requires email verification before activation.
    """
    # 🐛 Fix "iscrizione fantasma": valida il formato email PRIMA di qualunque
    # scrittura su DB. Un'email malformata deve fallire subito con 400.
    if not is_valid_email(data.email):
        raise HTTPException(status_code=400, detail="Indirizzo email non valido. Controlla e riprova.")
    
    # Check if email already exists (🆕 libera l'email se l'account è uscito da tutte le società)
    await _release_or_block_email(data.email.lower())
    
    # Validate invite code and get society
    if not data.invite_code:
        raise HTTPException(status_code=400, detail="Codice invito richiesto")
    
    society = await db.societies.find_one({"invite_code": data.invite_code.upper()})
    if not society:
        raise HTTPException(status_code=400, detail="Codice invito non valido")
    if not society.get("is_active", True):
        raise HTTPException(status_code=400, detail="Questa società non è più attiva")
    
    society_id = society["id"]
    
    # Parse and validate date of birth if provided
    dob = None
    if data.date_of_birth:
        try:
            dob = datetime.fromisoformat(data.date_of_birth)
            age = (datetime.utcnow() - dob).days // 365
            if age < 18:
                raise HTTPException(status_code=400, detail="Devi essere maggiorenne (18+ anni) per registrarti come atleta adulto")
        except ValueError:
            raise HTTPException(status_code=400, detail="Formato data di nascita non valido. Usa YYYY-MM-DD")
    
    # Check if athlete already exists by fiscal code (permanent identity)
    existing_athlete = await find_existing_athlete_by_fiscal_code(data.fiscal_code)
    if existing_athlete:
        # Reactivate existing athlete record - keep the same qr_identifier
        reactivate_data = {
            "society_id": society_id,
            "email": data.email.lower(),
            "phone_athlete": data.phone,
            "is_withdrawn": False,
            "withdrawn_date": None,
            "withdrawn_reason": None,
            "status": "pending",
            "parents_detached": True,
        }
        if data.first_name:
            reactivate_data["first_name"] = data.first_name
            reactivate_data["last_name"] = data.last_name
            reactivate_data["full_name"] = f"{data.first_name} {data.last_name}"
        if dob:
            reactivate_data["date_of_birth"] = dob
        if data.gender:
            reactivate_data["gender"] = data.gender
        
        await db.athletes.update_one(
            {"id": existing_athlete["id"]},
            {"$set": reactivate_data}
        )
        
        # Create user account for the reactivated athlete (skip email verification)
        user_id = str(ObjectId())
        user = {
            "id": user_id,
            "society_id": society_id,
            "email": data.email.lower(),
            "password_hash": hash_password(data.password),
            "role": UserRole.ATHLETE,
            "full_name": f"{data.first_name} {data.last_name}",
            "first_name": data.first_name,
            "last_name": data.last_name,
            "phone": data.phone,
            "is_active": True,
            "status": "pending",  # In attesa di approvazione admin (skip email verify)
            "created_at": datetime.utcnow(),
            "athlete_id": existing_athlete["id"],
            "email_verified": True,  # No email verification step for adult athletes
        }
        await db.users.insert_one(user)
        
        # Update athlete with linked user
        await db.athletes.update_one(
            {"id": existing_athlete["id"]},
            {"$set": {"linked_user_id": user_id}}
        )
        
        return {
            "message": "Registrazione completata. La tua iscrizione è in attesa di approvazione da parte della società.",
            "status": "pending",
            "requires_admin_approval": True,
        }
    
    # Generate unique athlete code
    athlete_id = str(ObjectId())
    
    # 🆕 v7.12 riusa codice se stesso CF già registrato
    qr_id = await resolve_athlete_code_for_cf(getattr(data, "fiscal_code", None))
    qr_code = generate_qr_code_from_identifier(qr_id)
    
    athlete_code = qr_id
    
    full_name = f"{data.first_name} {data.last_name}"
    
    athlete_dict = {
        "id": athlete_id,
        "parent_id": None,
        "society_id": society_id,
        "athlete_code": athlete_code,
        "full_name": full_name,
        "first_name": data.first_name,
        "last_name": data.last_name,
        "date_of_birth": dob,
        "is_minor": False,
        "fiscal_code": data.fiscal_code,
        "gender": data.gender,
        "email": data.email.lower(),
        "phone_athlete": data.phone,
        "team_id": None,
        "qr_code": qr_code,
        "qr_identifier": qr_id,
        "status": "pending",  # In attesa di approvazione admin (skip email verify)
        "athlete_type": "quota",  # Default; admin sceglie quota/compensated all'approvazione
        "parents_detached": True,
        "created_at": datetime.utcnow(),
        "registration_date": datetime.utcnow(),
        "privacy_accepted": False,
    }
    
    await db.athletes.insert_one(athlete_dict)
    
    # Create user account WITHOUT email verification (admin approval replaces it)
    user = User(
        email=data.email.lower(),
        password_hash=hash_password(data.password),
        role="athlete",
        full_name=full_name,
        status="pending",  # In attesa di approvazione admin
        society_id=society_id,
        first_name=data.first_name,
        last_name=data.last_name,
        phone=data.phone
    )
    
    user_dict = user.dict()
    user_dict["athlete_id"] = athlete_id
    user_dict["email_verified"] = True  # Skip email verification for adult athletes
    
    await db.users.insert_one(user_dict)
    
    # Link athlete to user
    await db.athletes.update_one(
        {"id": athlete_id},
        {"$set": {"user_id": user_dict["id"]}}
    )
    
    # Save signed privacy/terms documents if consents provided
    if data.consents and data.consents.get("privacy_viewed"):
        now = datetime.utcnow()
        consent_data = data.consents or {}
        
        # Structured consent format with timestamp tracking (aligned with minors/staff)
        structured_consents = {
            "privacy_viewed": {
                "value": True,
                "timestamp": now.isoformat(),
                "user_id": user_dict["id"],
                "document_version": "1.0",
            },
        }
        for ctype in ["images_internal", "images_promo"]:
            cval = consent_data.get(ctype, False)
            structured_consents[ctype] = {
                "value": cval,
                "timestamp": now.isoformat(),
                "user_id": user_dict["id"],
                "document_version": "1.0",
            }
        
        # Build consent history entries (insert, not update)
        consent_history = []
        for ctype in ["privacy_viewed", "images_internal", "images_promo"]:
            consent_history.append({
                "type": ctype,
                "action": "granted" if structured_consents[ctype]["value"] else "set",
                "old_value": None,
                "new_value": structured_consents[ctype]["value"],
                "timestamp": now.isoformat(),
                "user_id": user_dict["id"],
                "source": "registration",
            })
        
        # Save Privacy document
        privacy_doc_id = str(ObjectId())
        privacy_doc = {
            "id": privacy_doc_id,
            "document_type": "gdpr_privacy_adult",
            "document_title": "Informativa Privacy - Atleta Adulto",
            "signer_id": user_dict["id"],
            "signer_name": full_name,
            "athlete_name": full_name,
            "related_entity_id": athlete_id,
            "society_id": society_id,
            "signed_at": now,
            "created_at": now,
            "consent_data": {
                "privacy_viewed": True,
                "images_internal": consent_data.get("images_internal", False),
                "images_promo": consent_data.get("images_promo", False),
            },
            "gdpr_metadata": {
                "is_adult": True,
                "signed_during_registration": True,
            },
        }
        await db.signed_documents.insert_one(privacy_doc)
        
        # Save Terms of Use document
        terms_doc_id = str(ObjectId())
        terms_doc = {
            "id": terms_doc_id,
            "document_type": "terms_of_use",
            "document_title": "Termini di Utilizzo",
            "signer_id": user_dict["id"],
            "signer_name": full_name,
            "athlete_name": full_name,
            "related_entity_id": athlete_id,
            "society_id": society_id,
            "signed_at": now,
            "created_at": now,
        }
        await db.signed_documents.insert_one(terms_doc)
        
        # Update athlete with structured consent info and history
        await db.athletes.update_one(
            {"id": athlete_id},
            {"$set": {
                "privacy_accepted": True,
                "consents": structured_consents,
                "consent_history": consent_history,
            }}
        )
        
        # Update user with structured consent info
        await db.users.update_one(
            {"id": user_dict["id"]},
            {"$set": {
                "consents": {
                    "privacy_viewed": structured_consents["privacy_viewed"],
                    "images_internal": structured_consents["images_internal"],
                    "images_promo": structured_consents["images_promo"],
                },
            }}
        )
    
    return {
        "message": "Registrazione completata. La tua iscrizione è in attesa di approvazione da parte della società.",
        "status": "pending",
        "requires_admin_approval": True,
    }


