# Email service - uses Brevo with SendGrid fallback
from email_service import send_transactional_email, send_email_with_pdf

SENDER_EMAIL = os.environ.get("SENDGRID_FROM_EMAIL", "info@pallavoloperugia.it")


async def send_document_email(
    to_email: str,
    subject: str,
    document_title: str,
    signer_name: str,
    pdf_bytes: bytes,
    filename: str,
    to_name: Optional[str] = None,
    is_admin_copy: bool = False,
):
    """Send a signed document PDF via email.

    🐛 01/08/2026 — `to_name` ora è distinto da `signer_name`: per la copia admin
    il nome del destinatario deve essere l'admin (non il firmatario), altrimenti
    l'email dell'admin risulta indirizzata al nome del firmatario. `is_admin_copy`
    cambia anche il testo (notifica invece che 'Gentile <firmatario>')."""
    try:
        import base64
        pdf_base64 = base64.b64encode(pdf_bytes).decode('utf-8')

        recipient_name = to_name or signer_name
        if is_admin_copy:
            intro = f"""<p>È stato firmato un nuovo documento da <strong>{signer_name}</strong>.</p>
            <p>In allegato trovi la copia del documento firmato digitalmente.</p>"""
        else:
            intro = f"""<p>Gentile {signer_name},</p>
            <p>In allegato trova il documento firmato digitalmente.</p>"""

        html_content = f"""
        <html>
        <body style="font-family: Arial, sans-serif; padding: 20px;">
            <h2 style="color: #8E44AD;">{document_title}</h2>
            {intro}
            <p>Questo documento è stato generato automaticamente e contiene i metadati 
            di firma per garantirne la validità legale (timestamp, IP, hash del documento).</p>
            <br>
            <p style="color: #666; font-size: 12px;">
                Conservi questo documento per i suoi archivi.<br>
                In caso di domande, contatti la società sportiva.
            </p>
        </body>
        </html>
        """
        
        result = await send_email_with_pdf(
            to_email=to_email,
            subject=subject,
            html_content=html_content,
            pdf_base64=pdf_base64,
            pdf_filename=filename,
            to_name=recipient_name
        )
        
        if result and not result.get('success', True):
            logging.warning(f"Email send warning: {result.get('error', 'Unknown error')}")
            
        return result
    except Exception as e:
        logging.warning(f"Could not send document email: {e}")
        return None


def generate_reset_token():
    """Generate a secure random token for password reset"""
    return secrets.token_urlsafe(32)

class ImageTransformRequest(BaseModel):
    image_base64: str

@api_router.post("/auth/me/transform-photo")
async def transform_user_photo(data: ImageTransformRequest, current_user = Depends(get_current_user)):
    """DISABILITATO - Foto profilo rimosse per privacy"""
    raise HTTPException(status_code=410, detail="Funzionalità foto profilo rimossa per privacy")

async def send_password_reset_email(to_email: str, reset_token: str, user_name: str, society_id: Optional[str] = None):
    """Send password reset email via Brevo/SendGrid (branded per società se society_id fornito)"""
    # Recupera società corrente dell'utente (per branding From Name + Reply-To)
    society_doc = None
    settings = None
    if society_id:
        society_doc = await db.societies.find_one({"id": society_id})
        settings = await db.settings.find_one({"society_id": society_id, "type": "society"})
    # Fallback (legacy): primo settings disponibile
    if not settings:
        settings = await db.settings.find_one({"type": "society"})  # noqa: multitenancy-ok — utente non trovato o senza società
    
    society_name = (
        (settings.get("ragione_sociale") if settings else None)
        or (society_doc.get("name") if society_doc else None)
        or (settings.get("name", "Gestione Società") if settings else "Gestione Società")
    )
    
    # Reply-To: società.email → altrimenti admin owner
    reply_to_email = None
    if society_doc:
        reply_to_email = (society_doc.get("email") or "").strip() or None
        if not reply_to_email and society_doc.get("owner_id"):
            owner = await db.users.find_one({"id": society_doc["owner_id"]}, {"_id": 0, "email": 1})
            if owner:
                reply_to_email = owner.get("email")
    
    # Create reset code (first 8 chars of token for easier communication)
    reset_code = reset_token[:8].upper()
    
    # Build reset link
    base_url = os.environ.get("EXPO_PUBLIC_BACKEND_URL", os.environ.get("FRONTEND_URL", ""))
    reset_link = f"{base_url}/reset-password?email={to_email}" if base_url else ""
    
    reset_button_html = ""
    if reset_link:
        reset_button_html = f"""
                <p style="text-align: center; margin: 24px 0 8px 0;">
                    <a href="{reset_link}" style="display: inline-block; background-color: #007AFF; color: white; text-decoration: none; padding: 14px 32px; border-radius: 8px; font-weight: 600; font-size: 16px;">
                        Reimposta la Password
                    </a>
                </p>
                <p style="text-align: center; font-size: 12px; color: #999;">Oppure apri l'app e inserisci il codice manualmente</p>
        """
    
    # Build logo URL
    logo_url = f"{base_url}/api/settings/society/logo.png" if base_url else ""
    logo_html = f'<img src="{logo_url}" alt="{society_name}" style="width: 60px; height: 60px; object-fit: contain; margin-bottom: 8px;" /><br>' if logo_url else ""
    
    html_content = f"""
    <!DOCTYPE html>
    <html>
    <head>
        <meta charset="utf-8">
        <style>
            body {{ font-family: Arial, sans-serif; line-height: 1.6; color: #333; }}
            .container {{ max-width: 600px; margin: 0 auto; padding: 20px; }}
            .header {{ padding: 24px 20px; text-align: center; border-radius: 8px 8px 0 0; }}
            .header h1 {{ color: #007AFF; margin: 0; font-size: 20px; }}
            .content {{ background-color: #f9f9f9; padding: 30px; border: 1px solid #ddd; }}
            .code {{ background-color: #007AFF; color: white; font-size: 28px; font-weight: bold; 
                     padding: 15px 30px; text-align: center; border-radius: 8px; margin: 20px 0;
                     letter-spacing: 4px; }}
            .footer {{ text-align: center; padding: 20px; color: #666; font-size: 12px; }}
            .warning {{ color: #ff6b6b; font-size: 13px; margin-top: 20px; }}
        </style>
    </head>
    <body>
        <div class="container">
            <div class="header">
                {logo_html}
                <h1>{society_name}</h1>
            </div>
            <div class="content">
                <p>Ciao <strong>{user_name}</strong>,</p>
                <p>Hai richiesto il reset della password. Usa questo codice per impostare una nuova password:</p>
                
                <div class="code">{reset_code}</div>
                
                {reset_button_html}
                
                <p class="warning">
                    Il codice scade tra <strong>1 ora</strong>.<br>
                    Se non hai richiesto tu il reset della password, ignora questa email.
                </p>
            </div>
            <div class="footer">
                <p>Questa è un'email automatica, non rispondere.</p>
                <p>&copy; {datetime.now().year} {society_name}</p>
            </div>
        </div>
    </body>
    </html>
    """
    
    try:
        result = await send_transactional_email(
            to_email=to_email,
            subject=f"🔐 Reset Password - {society_name}",
            html_content=html_content,
            to_name=user_name,
            sender_name=society_name,
            reply_to_email=reply_to_email,
            reply_to_name=society_name if reply_to_email else None,
        )
        if result.get("success"):
            logging.info(f"Password reset email sent to {to_email} via {result.get('provider', 'unknown')}")
            return True
        else:
            logging.error(f"Failed to send password reset email: {result.get('error')}")
            raise HTTPException(status_code=500, detail=f"Errore invio email: {result.get('error')}")
    except HTTPException:
        raise
    except Exception as e:
        logging.error(f"Email service error: {str(e)}")
        raise HTTPException(status_code=500, detail=f"Errore invio email: {str(e)}")

class ForgotPasswordRequest(BaseModel):
    email: EmailStr

