@api_router.post("/admin/test-email")
async def admin_test_email(data: TestEmailRequest, current_user = Depends(get_current_user)):
    """
    Invia un'email di test all'indirizzo indicato usando il branding della società
    dell'admin autenticato (nome società come From Name + reply-to = society.email o admin owner).
    Solo per verifica configurazione Brevo.
    """
    if current_user.get("role") != "admin":
        raise HTTPException(status_code=403, detail="Solo admin")
    society_id = current_user.get("society_id")
    if not society_id:
        raise HTTPException(status_code=400, detail="Admin senza società")
    society = await db.societies.find_one({"id": society_id})
    if not society:
        raise HTTPException(status_code=404, detail="Società non trovata")
    # Fallback reply_to su admin owner se society.email vuoto
    if not (society.get("email") or "").strip() and society.get("owner_id"):
        owner = await db.users.find_one({"id": society["owner_id"]}, {"_id": 0, "email": 1})
        if owner:
            society["admin_email"] = owner.get("email")
    from email_service import send_society_email, SENDER_EMAIL, SENDER_NAME, USE_BREVO
    subject = f"🧪 Test Email RegistraTEAM - {society.get('name')}"
    html = f"""
    <div style="font-family:-apple-system,sans-serif;max-width:600px;margin:0 auto;padding:24px;">
      <div style="background:linear-gradient(135deg,#1E40AF,#3B82F6);color:white;padding:24px;border-radius:12px 12px 0 0;text-align:center;">
        <h1 style="margin:0;font-size:22px;">✅ Configurazione Brevo OK</h1>
        <p style="margin:8px 0 0;opacity:0.9;">Test multi-tenant</p>
      </div>
      <div style="background:white;padding:24px;border:1px solid #e5e7eb;border-radius:0 0 12px 12px;">
        <p>Ciao <strong>{current_user.get('full_name','Admin')}</strong>! 👋</p>
        <p>Email di test inviata dal backend RegistraTEAM.</p>
        <table style="width:100%;border-collapse:collapse;margin:16px 0;font-size:13px;">
          <tr><td style="padding:6px 0;color:#6B7280;">Da (fisico):</td><td style="padding:6px 0;font-weight:600;">{SENDER_EMAIL}</td></tr>
          <tr><td style="padding:6px 0;color:#6B7280;">From Name:</td><td style="padding:6px 0;font-weight:600;">{society.get('name')}</td></tr>
          <tr><td style="padding:6px 0;color:#6B7280;">Reply-To:</td><td style="padding:6px 0;font-weight:600;">{(society.get('email') or society.get('admin_email') or '—')}</td></tr>
          <tr><td style="padding:6px 0;color:#6B7280;">Provider:</td><td style="padding:6px 0;font-weight:600;">{'Brevo' if USE_BREVO else 'SendGrid'}</td></tr>
        </table>
        <p style="font-size:12px;color:#9CA3AF;text-align:center;margin-top:24px;">
          RegistraTEAM · Sistema email centralizzato
        </p>
      </div>
    </div>
    """
    result = await send_society_email(
        society=society,
        to_email=data.to_email,
        subject=subject,
        html_content=html,
        to_name=current_user.get('full_name'),
    )
    return {
        "success": result.get("success", False),
        "provider": result.get("provider"),
        "message_id": result.get("message_id"),
        "error": result.get("error"),
        "sender_email_configured": SENDER_EMAIL,
        "sender_name_used": society.get("name"),
        "reply_to_used": (society.get("email") or society.get("admin_email") or None),
    }


class ResetPasswordRequest(BaseModel):
    email: EmailStr
    reset_code: str
    new_password: str

class ChangePasswordRequest(BaseModel):
    current_password: Optional[str] = None
    new_password: str

@api_router.post("/auth/forgot-password")
async def forgot_password(data: ForgotPasswordRequest):
    """Request password reset - sends email with reset code"""
    # Find user by email
    user = await db.users.find_one({"email": data.email.lower()})
    
    # Always return success to prevent email enumeration
    if not user:
        return {"message": "Se l'email esiste, riceverai un codice di reset"}
    
    # Generate reset token
    reset_token = generate_reset_token()
    reset_expires = datetime.utcnow() + timedelta(hours=1)
    
    # Store token in database
    await db.users.update_one(
        {"id": user["id"]},
        {"$set": {
            "password_reset_token": reset_token,
            "password_reset_expires": reset_expires
        }}
    )
    
    # Send email
    try:
        await send_password_reset_email(
            to_email=user["email"],
            reset_token=reset_token,
            user_name=user.get("full_name", "Utente"),
            society_id=user.get("society_id"),
        )
    except Exception as e:
        logging.error(f"Failed to send reset email: {str(e)}")
        raise HTTPException(status_code=500, detail="Errore nell'invio dell'email. Riprova più tardi.")
    
    return {"message": "Se l'email esiste, riceverai un codice di reset"}

@api_router.post("/auth/reset-password")
async def reset_password(data: ResetPasswordRequest):
    """Reset password using the code received via email"""
    # Find user by email
    user = await db.users.find_one({"email": data.email.lower()})
    
    if not user:
        raise HTTPException(status_code=400, detail="Email non trovata")
    
    # Check if user has a valid reset token
    stored_token = user.get("password_reset_token")
    token_expires = user.get("password_reset_expires")
    
    if not stored_token or not token_expires:
        raise HTTPException(status_code=400, detail="Nessuna richiesta di reset trovata. Richiedi un nuovo codice.")
    
    # Check if token expired
    if datetime.utcnow() > token_expires:
        # Clear expired token
        await db.users.update_one(
            {"id": user["id"]},
            {"$unset": {"password_reset_token": "", "password_reset_expires": ""}}
        )
        raise HTTPException(status_code=400, detail="Codice scaduto. Richiedi un nuovo codice.")
    
    # Verify reset code (first 8 chars of token, case insensitive)
    expected_code = stored_token[:8].upper()
    provided_code = data.reset_code.strip().upper()
    
    if provided_code != expected_code:
        raise HTTPException(status_code=400, detail="Codice non valido")
    
    # Validate new password
    if len(data.new_password) < 6:
        raise HTTPException(status_code=400, detail="La password deve avere almeno 6 caratteri")
    
    # Update password and clear reset token
    new_password_hash = hash_password(data.new_password)
    
    await db.users.update_one(
        {"id": user["id"]},
        {
            "$set": {"password_hash": new_password_hash},
            "$unset": {"password_reset_token": "", "password_reset_expires": ""}
        }
    )
    
    return {"message": "Password aggiornata con successo! Ora puoi accedere con la nuova password."}

@api_router.post("/auth/change-password")
async def change_password(data: ChangePasswordRequest, current_user = Depends(get_current_user)):
    """Change password for logged-in user. Athletes don't need current password."""
    # Get full user data
    user = await db.users.find_one({"id": current_user["id"]})
    
    if not user:
        raise HTTPException(status_code=404, detail="Utente non trovato")
    
    # For non-athlete roles, verify current password if provided
    if current_user["role"] != "athlete":
        if not data.current_password:
            raise HTTPException(status_code=400, detail="Password attuale richiesta")
        if not verify_password(data.current_password, user["password_hash"]):
            raise HTTPException(status_code=400, detail="Password attuale non corretta")
        if data.current_password == data.new_password:
            raise HTTPException(status_code=400, detail="La nuova password deve essere diversa da quella attuale")
    
    # Validate new password
    if len(data.new_password) < 6:
        raise HTTPException(status_code=400, detail="La nuova password deve avere almeno 6 caratteri")
    
    # Update password
    new_password_hash = hash_password(data.new_password)
    
    await db.users.update_one(
        {"id": current_user["id"]},
        {"$set": {"password_hash": new_password_hash}}
    )
    
    return {"message": "Password cambiata con successo!"}


# 🆕 17/07/2026 — Cambio email utente corrente (self-service)
class ChangeEmailRequest(BaseModel):
    current_password: str
    new_email: str


@api_router.post("/auth/change-email")
async def change_email(data: ChangeEmailRequest, current_user = Depends(get_current_user)):
    """Cambia l'email dell'utente corrente. Richiede password per sicurezza.
    Ammesso a tutti i ruoli. Verifica unicità (case-insensitive)."""
    user = await db.users.find_one({"id": current_user["id"]})
    if not user:
        raise HTTPException(status_code=404, detail="Utente non trovato")

    # Verifica password (skip per athlete che spesso non ne ha una vera)
    if current_user["role"] != "athlete":
        if not verify_password(data.current_password, user["password_hash"]):
            raise HTTPException(status_code=400, detail="Password non corretta")

    new_email = (data.new_email or "").strip().lower()
    if not new_email or "@" not in new_email or "." not in new_email:
        raise HTTPException(status_code=400, detail="Email non valida")

    if new_email == user.get("email", "").lower():
        raise HTTPException(status_code=400, detail="La nuova email è uguale a quella attuale")

    # Unicità case-insensitive
    exists = await db.users.find_one({"email": {"$regex": f"^{re.escape(new_email)}$", "$options": "i"}})
    if exists and exists.get("id") != current_user["id"]:
        raise HTTPException(status_code=400, detail="Questa email è già usata da un altro account")

    await db.users.update_one({"id": current_user["id"]}, {"$set": {"email": new_email}})
    return {"message": "Email aggiornata con successo!", "email": new_email}


# 🆕 17/07/2026 — Collega un atleta all'utente corrente come genitore (per dual-role staff↔genitore)
class LinkParentRequest(BaseModel):
    slot: Optional[str] = "primary"  # legacy — mantenuto per compatibilità admin unlink


@api_router.post("/athletes/{athlete_id}/link-me-as-parent")
async def link_me_as_parent(
    athlete_id: str,
    current_user = Depends(get_current_user),
):
    """🔐 17/07/2026 (v3) — Collegamento genitore con logica anti-frode:
    - CASO 1 (atleta senza genitori linkati): auto-verifica → link diretto se
        (a) l'utente ha creato la scheda atleta (created_by == me), OPPURE
        (b) il CF dell'utente combacia con parent_fiscal_code / mother_fiscal_code / father_fiscal_code dell'atleta
    - CASO 2 (almeno un genitore linkato): crea richiesta pending, invia email
        al/i genitore/i linkato/i + notifica in-app. L'utente viene collegato
        SOLO dopo approvazione esplicita.
    Sempre: audit log in parent_link_history.
    """
    ath = await db.athletes.find_one({"id": athlete_id})
    if not ath:
        raise HTTPException(status_code=404, detail="Atleta non trovato")

    role = current_user.get("role")
    staff_roles = {"admin", "viewer", "dirigente", "coordinatore", "coach", "collaboratore"}
    if role not in staff_roles and role != "parent":
        raise HTTPException(status_code=403, detail="Non autorizzato")
    if current_user.get("society_id") != ath.get("society_id"):
        raise HTTPException(status_code=403, detail="Atleta di un'altra società")

    uid = current_user["id"]
    current_primary = ath.get("parent_id")
    current_secondary = ath.get("second_parent_id")

    if current_primary == uid or current_secondary == uid:
        raise HTTPException(status_code=400, detail="Sei già collegato a questo atleta")

    # === CASO 1: nessun genitore linkato → verifica automatica ===
    if not current_primary and not current_secondary:
        # Recupera CF ed email dell'utente corrente
        user_doc = await db.users.find_one({"id": uid}, {"fiscal_code": 1, "email": 1})
        user_cf = (user_doc.get("fiscal_code") or "").strip().upper() if user_doc else ""
        user_email = (user_doc.get("email") or current_user.get("email") or "").strip().lower() if user_doc else ""

        # Match a) creato da me
        created_by_me = (ath.get("created_by") == uid)
        # Match b) CF combacia con uno dei genitori registrati sulla scheda
        athlete_parent_cfs = [
            (ath.get("parent_fiscal_code") or "").strip().upper(),
            (ath.get("mother_fiscal_code") or "").strip().upper(),
            (ath.get("father_fiscal_code") or "").strip().upper(),
        ]
        cf_match = bool(user_cf) and user_cf in [x for x in athlete_parent_cfs if x]
        # Match c) email combacia con second_parent_email / parent_email / mother_email / father_email dell'atleta
        athlete_parent_emails = [
            (ath.get("second_parent_email") or "").strip().lower(),
            (ath.get("parent_email") or "").strip().lower(),
            (ath.get("mother_email") or "").strip().lower(),
            (ath.get("father_email") or "").strip().lower(),
        ]
        email_match = bool(user_email) and user_email in [x for x in athlete_parent_emails if x]

        if created_by_me or cf_match or email_match:
            # Auto-link come parent_id
            await db.athletes.update_one({"id": athlete_id}, {"$set": {"parent_id": uid}})
            verification = "created_by" if created_by_me else ("cf_match" if cf_match else "email_match")
            try:
                await db.parent_link_history.insert_one({
                    "action": "link_auto_case1",
                    "athlete_id": athlete_id,
                    "user_id": uid,
                    "user_email": current_user.get("email"),
                    "user_role": role,
                    "slot": "primary",
                    "verification": verification,
                    "timestamp": datetime.now(timezone.utc),
                })
            except Exception:
                pass
            return {"status": "linked", "slot": "primary", "message": "Collegato come genitore (verifica automatica riuscita)"}
        else:
            try:
                await db.parent_link_history.insert_one({
                    "action": "link_auto_case1_failed",
                    "athlete_id": athlete_id,
                    "user_id": uid,
                    "user_email": current_user.get("email"),
                    "timestamp": datetime.now(timezone.utc),
                })
            except Exception:
                pass
            raise HTTPException(
                status_code=403,
                detail="Impossibile verificarti come registrante di questo atleta. Contatta l'admin della società per collegarti manualmente.",
            )

    # === CASO 2: almeno un genitore linkato → richiesta di approvazione ===
    # Riuso l'infrastruttura esistente `parent_link_requests` (schema: requester_id, approver_id, ...)
    # Il genitore già linkato userà la sua dashboard /parent con /parent-link/requests + /parent-link/respond.
    approver_id = None
    if current_primary and current_primary != uid:
        approver_id = current_primary
    elif current_secondary and current_secondary != uid:
        approver_id = current_secondary
    if not approver_id:
        raise HTTPException(status_code=409, detail="Impossibile determinare il genitore da notificare")

    # Verifica no duplicati
    existing = await db.parent_link_requests.find_one({
        "athlete_id": athlete_id,
        "requester_id": uid,
        "status": "pending",
    })
    if existing:
        raise HTTPException(
            status_code=409,
            detail="Hai già una richiesta in sospeso per questo atleta.",
        )

    if current_primary and current_secondary and current_primary != uid and current_secondary != uid:
        raise HTTPException(
            status_code=409,
            detail="Entrambi gli slot genitore sono già occupati.",
        )

    now_utc = datetime.now(timezone.utc)
    athlete_name = f"{ath.get('last_name','')} {ath.get('first_name','')}".strip().upper()
    request_doc = {
        "id": str(uuid.uuid4()),
        "requester_id": uid,
        "requester_name": current_user.get("full_name", ""),
        "requester_email": current_user.get("email", ""),
        "athlete_id": athlete_id,
        "athlete_name": athlete_name,
        "approver_id": approver_id,
        "society_id": ath.get("society_id", ""),
        "status": "pending",
        "source": "staff_self_link",  # 🆕 differenzia da athlete_registration
        "created_at": now_utc.isoformat(),
    }
    await db.parent_link_requests.insert_one(request_doc)

    # Notifica in-app (stesso formato del flusso esistente)
    try:
        await db.notifications.insert_one({
            "id": str(uuid.uuid4()),
            "user_id": approver_id,
            "type": "parent_link_request",
            "title": "Richiesta collegamento genitore",
            "message": f"{current_user.get('full_name','')} chiede di essere collegato/a come co-genitore di {athlete_name}. Accetta o rifiuta dalla tua dashboard.",
            "read": False,
            "created_at": now_utc.isoformat(),
            "data": {
                "athlete_id": athlete_id,
                "athlete_name": athlete_name,
                "requester_name": current_user.get("full_name", ""),
            },
        })
    except Exception as _e:
        logging.warning(f"[parent_link] notify failed: {_e}")

    try:
        await db.parent_link_history.insert_one({
            "action": "link_request_created",
            "athlete_id": athlete_id,
            "user_id": uid,
            "user_email": current_user.get("email"),
            "user_role": role,
            "approver_id": approver_id,
            "request_id": request_doc["id"],
            "timestamp": now_utc,
        })
    except Exception:
        pass

    return {
        "status": "pending",
        "message": "Richiesta inviata al genitore attualmente collegato. Sarai collegato solo dopo la sua approvazione.",
        "request_id": request_doc["id"],
    }


@api_router.delete("/athletes/{athlete_id}/unlink-me-as-parent")
async def unlink_me_as_parent(athlete_id: str, current_user = Depends(get_current_user)):
    """🆕 17/07/2026 — L'utente corrente si scollega dall'atleta (self-service).
    Rimuove sé stesso da parent_id e/o second_parent_id se linkato."""
    ath = await db.athletes.find_one({"id": athlete_id})
    if not ath:
        raise HTTPException(status_code=404, detail="Atleta non trovato")

    uid = current_user["id"]
    unset: Dict[str, Any] = {}
    if ath.get("parent_id") == uid:
        unset["parent_id"] = ""
    if ath.get("second_parent_id") == uid:
        unset["second_parent_id"] = ""

    if not unset:
        raise HTTPException(status_code=400, detail="Non sei collegato a questo atleta")

    await db.athletes.update_one({"id": athlete_id}, {"$unset": unset})

    # Audit log
    try:
        await db.parent_link_history.insert_one({
            "action": "unlink_self",
            "athlete_id": athlete_id,
            "user_id": uid,
            "user_email": current_user.get("email"),
            "unset_slots": list(unset.keys()),
            "timestamp": datetime.now(timezone.utc),
        })
    except Exception:
        pass

    return {"message": "Collegamento rimosso"}


@api_router.post("/athletes/{athlete_id}/unlink-parent")
async def admin_unlink_parent(athlete_id: str, data: LinkParentRequest, current_user = Depends(get_current_user)):
    """🆕 17/07/2026 — Admin scollega un genitore da un atleta (per pulire link errati).
    Body: {slot: 'primary'|'secondary'}."""
    if current_user.get("role") != "admin":
        raise HTTPException(status_code=403, detail="Solo admin")

    ath = await db.athletes.find_one({"id": athlete_id})
    if not ath or ath.get("society_id") != current_user.get("society_id"):
        raise HTTPException(status_code=404, detail="Atleta non trovato")

    slot = (data.slot or "primary").lower()
    if slot not in ("primary", "secondary"):
        raise HTTPException(status_code=400, detail="Slot non valido")

    field = "parent_id" if slot == "primary" else "second_parent_id"
    prev_id = ath.get(field)
    await db.athletes.update_one({"id": athlete_id}, {"$unset": {field: ""}})

    try:
        await db.parent_link_history.insert_one({
            "action": "unlink_by_admin",
            "athlete_id": athlete_id,
            "unlinked_user_id": prev_id,
            "admin_user_id": current_user["id"],
            "admin_email": current_user.get("email"),
            "slot": slot,
            "timestamp": datetime.now(timezone.utc),
        })
    except Exception:
        pass

    return {"message": f"Slot {slot} scollegato", "previous_user_id": prev_id}


# 🆕 26/07/2026 — Admin force-link parent (override manuale per cleanup)
class AdminLinkParentRequest(BaseModel):
    user_id: str  # ID dell'utente da collegare come genitore
    slot: Optional[str] = "primary"  # "primary" | "secondary"


@api_router.post("/athletes/{athlete_id}/admin-link-parent")
async def admin_link_parent(
    athlete_id: str,
    data: AdminLinkParentRequest,
    current_user = Depends(get_current_user),
):
    """Admin-only: collega manualmente un utente come genitore di un atleta.
    Bypassa la verifica anti-frode (CF/created_by/email). Utile per cleanup
    di link errati o casi in cui i dati anagrafici non combaciano.
    Audit log completo in parent_link_history."""
    if current_user.get("role") != "admin":
        raise HTTPException(status_code=403, detail="Solo admin")

    ath = await db.athletes.find_one({"id": athlete_id})
    if not ath or ath.get("society_id") != current_user.get("society_id"):
        raise HTTPException(status_code=404, detail="Atleta non trovato")

    target_user = await db.users.find_one({"id": data.user_id})
    if not target_user:
        raise HTTPException(status_code=404, detail="Utente non trovato")
    if target_user.get("society_id") != current_user.get("society_id"):
        raise HTTPException(status_code=403, detail="Utente di un'altra società")

    slot = (data.slot or "primary").lower()
    if slot not in ("primary", "secondary"):
        raise HTTPException(status_code=400, detail="Slot non valido")

    field = "parent_id" if slot == "primary" else "second_parent_id"
    other_field = "second_parent_id" if slot == "primary" else "parent_id"

    # Evita doppio link stesso utente
    if ath.get(other_field) == data.user_id:
        raise HTTPException(status_code=400, detail=f"Utente già collegato sull'altro slot ({other_field})")
    if ath.get(field) == data.user_id:
        raise HTTPException(status_code=400, detail="Utente già collegato su questo slot")

    await db.athletes.update_one({"id": athlete_id}, {"$set": {field: data.user_id}})

    try:
        await db.parent_link_history.insert_one({
            "action": "link_by_admin_override",
            "athlete_id": athlete_id,
            "linked_user_id": data.user_id,
            "linked_user_email": target_user.get("email"),
            "admin_user_id": current_user["id"],
            "admin_email": current_user.get("email"),
            "slot": slot,
            "timestamp": datetime.now(timezone.utc),
        })
    except Exception:
        pass

    return {
        "message": f"Utente collegato come {slot} parent",
        "athlete_id": athlete_id,
        "user_id": data.user_id,
        "slot": slot,
    }


@api_router.get("/users/me/parent-of")
async def get_my_linked_athletes(current_user = Depends(get_current_user)):
    """Ritorna gli atleti a cui l'utente corrente è collegato come genitore
    (parent_id o second_parent_id). Serve al frontend per mostrare/nascondere
    il pulsante 'Passa a Modalità Genitore'."""
    uid = current_user["id"]
    athletes = await db.athletes.find({
        "$or": [{"parent_id": uid}, {"second_parent_id": uid}],
        "society_id": current_user.get("society_id"),
    }, {
        "_id": 0, "id": 1, "first_name": 1, "last_name": 1,
        "date_of_birth": 1, "team_id": 1, "team_name": 1,
    }).to_list(50)
    return {"count": len(athletes), "athletes": athletes}

