# ============ 🆕 02/07/2026 — Rifirma privacy genitore a inizio nuova stagione ============

@api_router.get("/parent/privacy-renewal-status")
async def parent_privacy_renewal_status(current_user = Depends(get_current_user)):
    """Restituisce lo stato del banner rifirma-privacy per il genitore corrente."""
    if current_user.get("role") != UserRole.PARENT:
        raise HTTPException(status_code=403, detail="Solo genitori")

    must_sign = bool(current_user.get("privacy_pending_renewal"))
    season = current_user.get("privacy_pending_renewal_season")
    if not must_sign:
        return {"must_sign": False, "blocking": False}

    sid = current_user.get("society_id")
    settings = await db.settings.find_one({"type": "society", "society_id": sid}) or {}
    max_trainings = int(settings.get("trial_max_trainings", 3) or 3)
    max_days = int(settings.get("trial_max_days", 7) or 7)

    # Primo login: se non memorizzato, lo memorizzo adesso.
    first_login = current_user.get("privacy_renewal_first_login")
    now = datetime.utcnow()
    if not first_login:
        await db.users.update_one({"id": current_user["id"]}, {"$set": {"privacy_renewal_first_login": now.isoformat()}})
        first_login_dt = now
    else:
        try:
            first_login_dt = datetime.fromisoformat(first_login)
        except Exception:
            first_login_dt = now
    days_elapsed = (now - first_login_dt).days

    # Conteggio allenamenti frequentati dai figli minorenni nella nuova stagione
    children = await db.athletes.find(
        {"society_id": sid, "parent_id": current_user["id"]},
        {"_id": 0, "id": 1}
    ).to_list(20)
    child_ids = [c["id"] for c in children]
    trainings_attended = 0
    if child_ids and season:
        try:
            season_start_year = int(season.split("-")[0])
        except Exception:
            season_start_year = now.year
        start_iso = datetime(season_start_year, int(settings.get("season_start_month", 7) or 7), int(settings.get("season_start_day", 1) or 1)).isoformat()
        trainings_attended = await db.attendance.count_documents({
            "athlete_id": {"$in": child_ids},
            "present": True,
            "date": {"$gte": start_iso},
        })

    blocking = (trainings_attended >= max_trainings) or (days_elapsed >= max_days)
    return {
        "must_sign": True,
        "blocking": blocking,
        "season": season,
        "trainings_attended": trainings_attended,
        "max_trainings": max_trainings,
        "days_elapsed": days_elapsed,
        "max_days": max_days,
    }


class PrivacyDeclineBody(BaseModel):
    reason: Optional[str] = None


@api_router.post("/parent/privacy-renewal-decline")
async def parent_privacy_renewal_decline(body: PrivacyDeclineBody, current_user = Depends(get_current_user)):
    """Rinuncia alla nuova stagione: ritira gli atleti minorenni linkati + notifica coach.
    Soft-delete (15gg per ripensamento)."""
    if current_user.get("role") != UserRole.PARENT:
        raise HTTPException(status_code=403, detail="Solo genitori")
    sid = current_user.get("society_id")
    now_iso = datetime.utcnow().isoformat()
    children = await db.athletes.find(
        {"society_id": sid, "parent_id": current_user["id"]},
        {"_id": 0, "id": 1, "full_name": 1, "team_id": 1},
    ).to_list(20)

    withdrawn_ids = []
    for c in children:
        await db.athletes.update_one(
            {"id": c["id"], "society_id": sid},
            {"$set": {
                "is_withdrawn": True,
                "withdrawn_at": now_iso,
                "withdrawn_reason": (body.reason or "Rinuncia genitore a rifirma privacy nuova stagione"),
                "withdrawn_reversible_until": (datetime.utcnow() + timedelta(days=15)).isoformat(),
            }},
        )
        withdrawn_ids.append(c["id"])

        # Notifica in-app al coach della squadra
        if c.get("team_id"):
            team_coaches = await db.users.find(
                {"role": UserRole.COACH, "assigned_teams": c["team_id"], "society_id": sid},
                {"_id": 0, "id": 1},
            ).to_list(10)
            for coach in team_coaches:
                await db.notifications.insert_one({
                    "id": str(uuid.uuid4()),
                    "society_id": sid,
                    "user_id": coach["id"],
                    "type": "athlete_withdrawn",
                    "title": "⚠️ Ritiro atleta",
                    "message": f"{current_user.get('full_name', 'Un genitore')} ha ritirato {c.get('full_name', 'un atleta')} dalla società (mancata rifirma privacy nuova stagione).",
                    "read": False,
                    "created_at": now_iso,
                })

    if current_user.get("privacy_pending_renewal_season"):
        cs = current_user["privacy_pending_renewal_season"]
        await db.users.update_one(
            {"id": current_user["id"]},
            {"$pull": {"active_seasons": cs}, "$set": {
                "privacy_pending_renewal": False,
                "privacy_declined_at": now_iso,
                "privacy_declined_reason": body.reason,
            }},
        )
    return {"withdrawn_athletes": len(withdrawn_ids), "reversible_until_days": 15}


# ============ 🆕 03/07/2026 — Widget dashboard admin: online count + privacy alert ============

@api_router.get("/admin/dashboard-live-stats")
async def admin_dashboard_live_stats(current_user = Depends(get_current_user)):
    """Statistiche live per la dashboard admin:
    - `online_users`: utenti attivi negli ultimi 5 minuti (any role, stessa società)
    - `privacy_pending_count`: genitori con privacy da rifirmare per la nuova stagione
    - `withdrawn_reversible_count`: atleti in soft-delete ancora reversibile (entro 15gg)
    """
    if current_user.get("role") != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")
    sid = current_user.get("society_id")
    now = datetime.utcnow()
    five_min_ago = (now - timedelta(minutes=5)).isoformat()

    online_users = await db.users.count_documents({
        "society_id": sid,
        "last_active_at": {"$gte": five_min_ago},
    })
    # 🐛 Fix: "Privacy da firmare" contava SOLO le ri-firme di rinnovo stagione
    # (privacy_pending_renewal). Ora conta TUTTE le privacy in sospeso:
    #   (a) atleti il cui prossimo passo è la FIRMA della privacy (mai firmata)
    #   (b) genitori con ri-firma privacy per il rinnovo della nuova stagione
    renewal_pending_count = await db.users.count_documents({
        "society_id": sid,
        "role": UserRole.PARENT,
        "privacy_pending_renewal": True,
    })
    # (a) Atleti non ritirati con firma privacy ancora da fare (usa la stessa
    # logica dell'elenco atleti: compute_pending_reason → "firma della privacy").
    initial_pending_count = 0
    _pa_cursor = db.athletes.find(
        {"society_id": sid, "is_withdrawn": {"$ne": True}},
        {
            "_id": 0, "status": 1, "date_of_birth": 1, "privacy_accepted": 1,
            "medical_certificate_verified": 1, "medical_certificate_issue_date": 1,
            "medical_certificate_date": 1, "medical_certificate_expiry": 1,
            "team_id": 1, "primary_team_id": 1, "team_ids": 1,
            "trial_start_date": 1, "is_withdrawn": 1,
        },
    )
    async for _a in _pa_cursor:
        _reason = compute_pending_reason(_a)
        if _reason and "firma della privacy" in _reason:
            initial_pending_count += 1
    privacy_pending_count = initial_pending_count + renewal_pending_count
    withdrawn_reversible_count = await db.athletes.count_documents({
        "society_id": sid,
        "is_withdrawn": True,
        "withdrawn_reversible_until": {"$gte": now.isoformat()},
    })
    return {
        "online_users": online_users,
        "privacy_pending_count": privacy_pending_count,
        "withdrawn_reversible_count": withdrawn_reversible_count,
    }


@api_router.get("/users/parents")
async def get_parents(current_user = Depends(get_current_user)):
    """Get all parents linked to athletes active in current season.

    🐛 10/07/2026 (v7.15) — HOTFIX "cartella Genitori vuota".
    Prima si filtravano SOLO utenti con `active_seasons: current_season`
    (o senza active_seasons). Se il genitore era rimasto nella stagione
    precedente (bug `import-member` originale) SPARIVA dalla dashboard
    — anche se aveva figli attivi (Chiara Opale con Sandro/Lisa era il
    caso concreto: entrambi i genitori invisibili).

    Ora la source-of-truth è: "genitori collegati (primary o secondary)
    ad atleti attivi in stagione corrente". Chi compare ma non ha ancora
    la stagione corrente viene auto-heal-ato in background."""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può vedere i genitori")

    society_id = current_user.get("society_id")
    from utils import get_current_season_for_society as _get_cs
    _cs = await _get_cs(db, society_id)

    # 1. Atleti attivi in stagione corrente + loro parent_id / second_parent_id
    #    🐛 27/08/2026 — Includiamo anche gli atleti neo-iscritti SENZA active_seasons
    #    (o lista vuota): un bug creava gli atleti senza stagione, facendo sparire il
    #    genitore collegato dalla cartella Genitori. Escludiamo i ritirati/archiviati.
    current_athletes = await db.athletes.find(
        {"society_id": society_id, "is_withdrawn": {"$ne": True}, "$or": [
            {"active_seasons": _cs},
            {"active_seasons": {"$exists": False}},
            {"active_seasons": {"$size": 0}},
        ]},
        {"_id": 0, "id": 1, "parent_id": 1, "second_parent_id": 1, "active_seasons": 1,
         "phone_father": 1, "phone_mother": 1, "phone": 1, "phone_athlete": 1},
    ).to_list(5000)

    # Self-heal atleti neo-iscritti privi della stagione corrente (idempotente)
    _ath_needing_season = [
        a["id"] for a in current_athletes if _cs not in (a.get("active_seasons") or [])
    ]
    if _ath_needing_season:
        try:
            await db.athletes.update_many(
                {"id": {"$in": _ath_needing_season}},
                {"$addToSet": {"active_seasons": _cs}},
            )
        except Exception as _e:
            logging.warning(f"[users/parents] self-heal athlete active_seasons failed: {_e}")

    linked_parent_ids: set = set()
    counts_dict: dict = {}
    # 🆕 22/08/2026 — Fallback telefono: alcuni genitori hanno il numero salvato solo
    # sulla scheda ATLETA (phone_father/phone_mother), non sul record utente → il
    # pulsante WhatsApp non compariva. Costruiamo una mappa parent_id → telefono famiglia.
    parent_phone_map: dict = {}
    def _first_phone(*vals):
        for v in vals:
            if v and str(v).strip():
                return str(v).strip()
        return ""
    for a in current_athletes:
        for pid in [a.get("parent_id"), a.get("second_parent_id")]:
            if pid:
                linked_parent_ids.add(pid)
                counts_dict[pid] = counts_dict.get(pid, 0) + 1
        pf = a.get("phone_father"); pm = a.get("phone_mother")
        ph = a.get("phone"); pa = a.get("phone_athlete")
        if a.get("parent_id") and not parent_phone_map.get(a["parent_id"]):
            parent_phone_map[a["parent_id"]] = _first_phone(pf, pm, ph, pa)
        if a.get("second_parent_id") and not parent_phone_map.get(a["second_parent_id"]):
            parent_phone_map[a["second_parent_id"]] = _first_phone(pm, pf, ph, pa)

    # 2. Genitori: quelli collegati agli atleti attivi ∪ quelli con active_seasons=current
    #    ∪ quelli senza active_seasons (legacy fallback)
    q: dict = {
        "role": UserRole.PARENT,
        "society_id": society_id,
        "$or": [
            {"id": {"$in": list(linked_parent_ids)}} if linked_parent_ids else {"id": "__none__"},
            {"active_seasons": _cs},
            {"active_seasons": {"$exists": False}},
        ],
    }
    # 🚀 18/08/2026 PERF — projection: solo i campi usati (NIENTE profile_photo base64).
    parents = await db.users.find(q, {
        "_id": 0, "id": 1, "email": 1, "full_name": 1, "role": 1, "status": 1,
        "created_at": 1, "approved_at": 1, "phone": 1, "fiscal_code": 1,
        "active_seasons": 1,
        "linked_dirigente_user_id": 1, "pending_dirigente_user_id": 1,
    }).to_list(5000)

    # 3. Self-heal silenzioso: genitori collegati ad atleti attivi ma senza
    #    active_seasons=current_season → riporta in stagione (idempotente).
    needing_heal = [
        p["id"] for p in parents
        if p["id"] in linked_parent_ids
        and _cs not in (p.get("active_seasons") or [])
    ]
    if needing_heal:
        try:
            await db.users.update_many(
                {"id": {"$in": needing_heal}, "society_id": society_id, "role": UserRole.PARENT},
                {"$addToSet": {"active_seasons": _cs},
                 "$set": {"rollover_decision": "auto_healed",
                          "rollover_decision_season": _cs,
                          "rollover_decision_at": datetime.utcnow().isoformat(),
                          "rollover_repaired_from_orphan": True}},
            )
            logger.info(f"[parents self-heal] society={society_id} healed={len(needing_heal)} season={_cs}")
        except Exception as _e:
            logger.warning(f"[parents self-heal] failed: {_e}")

    result = []
    for p in parents:
        result.append({
            "id": p["id"],
            "email": p["email"],
            "full_name": p["full_name"],
            "role": p["role"],
            "status": p.get("status", UserStatus.APPROVED),
            "athletes_count": counts_dict.get(p["id"], 0),
            "created_at": p.get("created_at"),
            "approved_at": p.get("approved_at"),
            "phone": (p.get("phone") or "").strip() or parent_phone_map.get(p["id"], ""),
            "fiscal_code": p.get("fiscal_code", ""),
            "linked_dirigente_user_id": p.get("linked_dirigente_user_id"),
            "pending_dirigente_user_id": p.get("pending_dirigente_user_id"),
        })

    return result

