async def _sync_bank_details_to_linked(user_doc: dict, bank_sync: dict) -> None:
    """🆕 Propaga IBAN / intestatario / banca a TUTTI i record della stessa persona:
    record atleta collegato, alias dual-role (coach, dirigente, coordinatore, genitore)
    in entrambe le direzioni. Un solo conto per persona, qualunque profilo lo salvi."""
    if not bank_sync:
        return
    bank_sync = dict(bank_sync)
    # L'admin legge/scrive `iban_holder`, il lavoratore `account_holder` → allineiamo sempre entrambi
    holder = bank_sync.get("account_holder") or bank_sync.get("iban_holder")
    if holder is not None:
        bank_sync["account_holder"] = holder
        bank_sync["iban_holder"] = holder
    uid = user_doc.get("id")

    # Record atleta collegato (Atleta PRO)
    athlete_query = {"id": user_doc["athlete_id"]} if user_doc.get("athlete_id") else {"$or": [
        {"user_id": uid}, {"linked_user_id": uid},
        {"email": (user_doc.get("email") or "").lower().split("#", 1)[0]},
    ]}
    try:
        await db.athletes.update_one(athlete_query, {"$set": bank_sync})
    except Exception as _e:
        logging.warning(f"[BANK-SYNC] athlete sync failed for user {uid}: {_e}")

    # Alias dual-role collegati (link diretti e inversi)
    linked_ids = set()
    for k in ("linked_coach_user_id", "linked_dirigente_user_id", "linked_coordinatore_user_id", "linked_parent_user_id"):
        if user_doc.get(k):
            linked_ids.add(user_doc[k])
    try:
        async for u in db.users.find({"$or": [
            {"linked_coach_user_id": uid}, {"linked_dirigente_user_id": uid},
            {"linked_coordinatore_user_id": uid}, {"linked_parent_user_id": uid},
        ]}, {"_id": 0, "id": 1}):
            linked_ids.add(u["id"])
    except Exception:
        pass
    linked_ids.discard(uid)
    if linked_ids:
        try:
            await db.users.update_many({"id": {"$in": list(linked_ids)}}, {"$set": bank_sync})
            for lid in linked_ids:
                invalidate_auth_cache(lid)
        except Exception as _e:
            logging.warning(f"[BANK-SYNC] linked users sync failed for user {uid}: {_e}")


@api_router.patch("/users/me/bank-details")
async def update_my_bank_details(data: dict, current_user = Depends(get_current_user)):
    """Update current user's bank and document details"""
    allowed_fields = ["id_type", "id_front", "id_back", "iban", "account_holder", "bank_name", "doc_front_image", "doc_back_image"]
    update_dict = {k: v for k, v in data.items() if k in allowed_fields}
    
    if update_dict:
        if "account_holder" in update_dict:
            update_dict["iban_holder"] = update_dict["account_holder"]  # allineato alla vista admin
        await db.users.update_one(
            {"id": current_user["id"]},
            {"$set": update_dict}
        )

        # 🐛 Sync dei dati bancari su record atleta e alias dual-role (coach, dirigente,
        # coordinatore…): l'admin e gli altri profili della stessa persona vedono lo stesso IBAN.
        bank_sync = {k: v for k, v in update_dict.items() if k in ("iban", "account_holder", "bank_name")}
        if bank_sync:
            full_user = await db.users.find_one({"id": current_user["id"]}, {"_id": 0, "password_hash": 0}) or dict(current_user)
            await _sync_bank_details_to_linked(full_user, bank_sync)
    
    return {"message": "Dati bancari aggiornati"}

@api_router.patch("/users/{user_id}/role")
async def update_user_role(user_id: str, data: UserUpdateRole, current_user = Depends(get_current_user)):
    """Update user role (dirigenti: admin/viewer/dirigente/coordinatore)."""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può modificare i ruoli")

    # 🆕 16/07/2026 — Accetta anche `dirigente` e `coordinatore` come target
    allowed_targets = [UserRole.ADMIN, UserRole.VIEWER, UserRole.DIRIGENTE, UserRole.COORDINATORE]
    if data.role not in allowed_targets:
        raise HTTPException(status_code=400, detail="Ruolo non valido")

    user = await db.users.find_one({"id": user_id})
    if not user:
        raise HTTPException(status_code=404, detail="Utente non trovato")

    # Consenti conversioni tra admin/viewer/dirigente/coordinatore (staff → staff)
    staff_roles = {UserRole.ADMIN, UserRole.VIEWER, UserRole.DIRIGENTE, UserRole.COORDINATORE}
    if user["role"] not in staff_roles:
        raise HTTPException(status_code=400, detail="Questo utente non è un dirigente/coordinatore")

    # Multi-tenancy: non consentire modifiche cross-società
    if user.get("society_id") and current_user.get("society_id") and \
       user["society_id"] != current_user["society_id"]:
        raise HTTPException(status_code=403, detail="Utente di altra società")

    update: Dict[str, Any] = {"role": data.role}

    # Se target = coordinatore, salva anche i permessi (filtrati)
    if data.role == UserRole.COORDINATORE:
        valid_keys = set(COORDINATOR_PERMISSIONS.keys())
        perms = [p for p in (data.coordinator_permissions or []) if isinstance(p, str) and p in valid_keys]
        update["coordinator_permissions"] = perms
    else:
        # Se target != coordinatore, azzera i permessi coordinatore (pulizia)
        update["coordinator_permissions"] = []

    await db.users.update_one({"id": user_id}, {"$set": update})

    return {"message": "Ruolo aggiornato con successo", "role": data.role}

class AdminResetPassword(BaseModel):
    new_password: str

@api_router.patch("/users/{user_id}/reset-password")
async def admin_reset_password(user_id: str, data: AdminResetPassword, current_user = Depends(get_current_user)):
    """Admin can reset any user's password"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può resettare le password")
    
    user = await db.users.find_one({"id": user_id})
    if not user:
        raise HTTPException(status_code=404, detail="Utente non trovato")
    
    # Hash the new password
    password_hash = hash_password(data.new_password)
    
    await db.users.update_one(
        {"id": user_id},
        {"$set": {"password_hash": password_hash}}
    )
    
    return {"message": f"Password resettata per {user.get('full_name', user.get('email'))}"}

class AdminResetAthletePasswordRequest(BaseModel):
    send_email: bool = True  # If true, send reset link via email
    new_password: Optional[str] = None  # If provided, set this password directly

@api_router.post("/admin/athletes/{athlete_id}/reset-password")
async def admin_reset_athlete_password(athlete_id: str, data: AdminResetAthletePasswordRequest, current_user = Depends(get_current_user)):
    """Admin can reset an athlete's password and send reset link via email"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può resettare le password degli atleti")
    
    # Find the athlete
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    # Get athlete email
    athlete_email = athlete.get("email")
    if not athlete_email:
        raise HTTPException(status_code=400, detail="L'atleta non ha un indirizzo email registrato. Aggiungi prima un'email valida.")
    
    # Find user account linked to this athlete (by email)
    user = await db.users.find_one({"email": athlete_email.lower()})
    if not user:
        # Create user account for athlete if not exists
        user_id = str(ObjectId())
        user = {
            "id": user_id,
            "email": athlete_email.lower(),
            "password_hash": hash_password(generate_reset_token()[:12]),  # Random initial password
            "role": "athlete",
            "full_name": f"{athlete.get('first_name', '')} {athlete.get('last_name', '')}".strip() or athlete.get("full_name", "Atleta"),
            "status": UserStatus.APPROVED,
            "society_id": athlete.get("society_id"),
            "athlete_id": athlete_id,
            "created_at": datetime.utcnow(),
        }
        await db.users.insert_one(user)
    
    # Direct password reset (no email)
    if data.new_password:
        if len(data.new_password) < 6:
            raise HTTPException(status_code=400, detail="La password deve avere almeno 6 caratteri")
        new_hash = hash_password(data.new_password)
        await db.users.update_one(
            {"id": user["id"]},
            {"$set": {"password_hash": new_hash, "athlete_id": athlete_id}}
        )
        athlete_name = f"{athlete.get('first_name', '')} {athlete.get('last_name', '')}".strip() or athlete.get("full_name", "Atleta")
        return {
            "success": True,
            "message": f"Password reimpostata per {athlete_name}",
            "athlete_name": athlete_name,
            "email": athlete_email,
        }

    # Generate reset token for email flow
    reset_token = generate_reset_token()
    reset_expires = datetime.utcnow() + timedelta(hours=24)  # 24 hours for admin-initiated reset
    
    # Store token in database
    await db.users.update_one(
        {"id": user["id"]},
        {"$set": {
            "password_reset_token": reset_token,
            "password_reset_expires": reset_expires,
            "athlete_id": athlete_id,  # Ensure link is maintained
        }}
    )
    
    if data.send_email:
        # Send email with reset code
        try:
            await send_password_reset_email(
                to_email=athlete_email,
                reset_token=reset_token,
                user_name=f"{athlete.get('first_name', '')} {athlete.get('last_name', '')}".strip() or athlete.get("full_name", "Atleta")
            )
        except Exception as e:
            logging.error(f"Failed to send reset email to athlete: {str(e)}")
            raise HTTPException(status_code=500, detail=f"Errore nell'invio dell'email: {str(e)}")
    
    athlete_name = f"{athlete.get('first_name', '')} {athlete.get('last_name', '')}".strip() or athlete.get("full_name", "Atleta")
    return {
        "success": True,
        "message": f"Email di reset password inviata a {athlete_email}",
        "athlete_name": athlete_name,
        "email": athlete_email,
    }

@api_router.patch("/users/{user_id}/status")
async def update_user_status(user_id: str, data: UserUpdateStatus, current_user = Depends(get_current_user)):
    """Approve, reject or suspend a user"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può gestire gli utenti")
    
    # Validate status
    if data.status not in [UserStatus.APPROVED, UserStatus.REJECTED, UserStatus.SUSPENDED]:
        raise HTTPException(status_code=400, detail="Stato non valido")
    
    user = await db.users.find_one({"id": user_id})
    if not user:
        raise HTTPException(status_code=404, detail="Utente non trovato")
    
    update_data = {"status": data.status}
    if data.status == UserStatus.APPROVED:
        update_data["approved_at"] = datetime.utcnow()
        update_data["approved_by"] = current_user["id"]
    
    await db.users.update_one(
        {"id": user_id},
        {"$set": update_data}
    )
    
    return {"message": f"Utente {data.status} con successo"}

