@api_router.get("/athletes/{athlete_id}/matches")
async def get_athlete_matches(
    athlete_id: str,
    format: str = "json",
    only_upcoming: bool = False,
    current_user = Depends(get_current_user),
):
    """
    🆕 29/07/2026 — Calendario completo delle gare di tutte le squadre in cui gioca
    l'atleta. `format=ics` restituisce un file .ics importabile in Google Calendar /
    Apple Calendar / Outlook.
    """
    ath = await db.athletes.find_one({"id": athlete_id})
    if not ath:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    society_id = current_user.get("society_id")
    if society_id and ath.get("society_id") != society_id:
        raise HTTPException(status_code=403, detail="Atleta non appartiene alla tua società")

    # Autorizzazioni: admin / coach / dirigente della società; l'atleta stesso;
    # il genitore linkato all'atleta; il minorenne autenticato in Lite mode.
    role = current_user.get("role")
    user_id = current_user.get("id")
    allowed = False
    if role in (UserRole.ADMIN, UserRole.COACH, UserRole.DIRIGENTE, UserRole.COLLABORATORE):
        allowed = True
    elif role == UserRole.ATHLETE and ath.get("user_id") == user_id:
        allowed = True
    elif role == UserRole.PARENT and ath.get("parent_id") == user_id:
        allowed = True
    # 🆕 31/07/2026 — Consenti al minorenne (login Lite) di vedere/esportare
    # SOLO il proprio calendario. Nel token minor: user_id == athlete_id.
    elif role == "minor" and (current_user.get("athlete_id") == athlete_id or user_id == athlete_id):
        allowed = True
    if not allowed:
        raise HTTPException(status_code=403, detail="Non autorizzato a vedere le gare di questo atleta")

    # Raccogli TUTTI i team_ids in cui l'atleta gioca (canonico + legacy)
    team_ids = list(set(
        (ath.get("team_ids") or [])
        + ([ath.get("team_id")] if ath.get("team_id") else [])
    ))
    team_ids = [t for t in team_ids if t]
    if not team_ids:
        matches: List[Dict] = []
    else:
        q: Dict = {"team_id": {"$in": team_ids}}
        if society_id:
            # 🐛 01/08/2026 — Includi anche le gare legacy senza society_id (import
            # prima del tracking society_id). team_id è già scoped per società,
            # quindi è sicuro non escludere quelle con society_id nullo/mancante.
            q["$or"] = [
                {"society_id": society_id},
                {"society_id": {"$in": [None, ""]}},
                {"society_id": {"$exists": False}},
            ]
        if only_upcoming:
            q["date"] = {"$gte": datetime.now(timezone.utc)}
        raw = await db.matches.find(q).sort("date", 1).to_list(500)
        matches = []
        for m in raw:
            clean_mongo_doc(m)
            matches.append(m)

    # 🆕 01/08/2026 — Info squadre (con link calendario federazione) per permettere
    # anche all'atleta di aprire il calendario ufficiale FIPAV (utile per le squadre
    # nazionali Serie A/B, non importabili automaticamente).
    team_docs: List[Dict] = []
    if team_ids:
        async for t in db.teams.find(
            {"id": {"$in": team_ids}},
            {"_id": 0, "id": 1, "name": 1, "calendar_link": 1},
        ):
            team_docs.append({
                "id": t.get("id"),
                "name": t.get("name") or "",
                "calendar_link": t.get("calendar_link") or None,
            })

    if format.lower() != "ics":
        _soc = await _society_short_name_for(ath.get("society_id") or society_id)
        for _m in matches:
            _m["society_name"] = _soc  # 🆕 nome società al posto del nome squadra
        return {
            "athlete_id": athlete_id,
            "athlete_name": ath.get("full_name") or "",
            "team_ids": team_ids,
            "teams": team_docs,
            "society_name": _soc,
            "matches": matches,
            "count": len(matches),
        }

    # Genera ICS
    def _ics_escape(s: str) -> str:
        return (s or "").replace("\\", "\\\\").replace(",", "\\,").replace(";", "\\;").replace("\n", "\\n")

    def _fmt(dt) -> str:
        if isinstance(dt, str):
            try:
                dt = datetime.fromisoformat(dt.replace("Z", "+00:00"))
            except Exception:
                return ""
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc).strftime("%Y%m%dT%H%M%SZ")

    lines = [
        "BEGIN:VCALENDAR",
        "VERSION:2.0",
        "PRODID:-//RegistraTEAM//Athlete Calendar//IT",
        "CALSCALE:GREGORIAN",
        f"X-WR-CALNAME:Gare {_ics_escape(ath.get('full_name', ''))}",
    ]
    now_utc = _fmt(datetime.now(timezone.utc))
    for m in matches:
        uid = f"match-{m.get('id') or m.get('_id') or ''}@registrateam.it"
        start = _fmt(m.get("date"))
        if not start:
            continue
        home_away = (m.get("home_away") or "").lower()
        opponent = m.get("opponent") or "Avversario"
        team_name = m.get("team_name") or ""
        summary = f"{team_name} vs {opponent}" if home_away == "home" else f"{opponent} vs {team_name}"
        venue = m.get("venue") or ""
        addr = m.get("address") or m.get("city") or ""
        location = ", ".join([x for x in [venue, addr] if x])
        desc_parts = []
        if m.get("meeting_time"):
            desc_parts.append(f"Ritrovo: {m['meeting_time']}")
        if m.get("notes"):
            desc_parts.append(m["notes"])
        lines += [
            "BEGIN:VEVENT",
            f"UID:{uid}",
            f"DTSTAMP:{now_utc}",
            f"DTSTART:{start}",
            f"SUMMARY:{_ics_escape(summary)}",
        ]
        if location:
            lines.append(f"LOCATION:{_ics_escape(location)}")
        if desc_parts:
            lines.append(f"DESCRIPTION:{_ics_escape(' | '.join(desc_parts))}")
        lines.append("END:VEVENT")
    lines.append("END:VCALENDAR")
    ics = "\r\n".join(lines) + "\r\n"
    filename = f"gare_{(ath.get('full_name') or 'atleta').replace(' ', '_')}.ics"
    return Response(
        content=ics,
        media_type="text/calendar; charset=utf-8",
        headers={"Content-Disposition": f'attachment; filename="{filename}"'},
    )

@api_router.post("/matches")
async def create_match(match_data: MatchCreate, current_user = Depends(get_current_user)):
    """Create a new match"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può creare gare")
    
    # Get team name
    team = await db.teams.find_one({"id": match_data.team_id})
    team_name = team.get("name", "") if team else ""
    
    match = Match(
        society_id=current_user.get("society_id"),
        team_id=match_data.team_id,
        team_name=team_name,
        date=match_data.date,
        opponent=match_data.opponent,
        venue=match_data.venue,
        address=match_data.address,
        city=match_data.city,
        home_away=match_data.home_away,
        meeting_time=match_data.meeting_time,
        notes=match_data.notes,
        match_number=match_data.match_number,
        championship=match_data.championship,
        girone=match_data.girone
    )
    
    await db.matches.insert_one(match.dict())
    return match.dict()

@api_router.patch("/matches/{match_id}")
async def update_match(match_id: str, match_data: dict, current_user = Depends(get_current_user)):
    """Update a match"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può modificare gare")
    
    match_data["updated_at"] = datetime.utcnow()
    
    # If team_id is being updated, also update team_name
    if "team_id" in match_data:
        team = await db.teams.find_one({"id": match_data["team_id"]})
        match_data["team_name"] = team.get("name", "") if team else ""
    
    society_id = current_user.get("society_id")
    filter_q = {"id": match_id}
    if society_id:
        filter_q["society_id"] = society_id
    result = await db.matches.update_one(
        filter_q,
        {"$set": match_data}
    )
    
    if result.modified_count == 0:
        raise HTTPException(status_code=404, detail="Gara non trovata")
    
    return {"message": "Gara aggiornata"}

@api_router.delete("/matches/{match_id}")
async def delete_match(match_id: str, current_user = Depends(get_current_user)):
    """Delete a match"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può eliminare gare")
    
    society_id = current_user.get("society_id")
    filter_q = {"id": match_id}
    if society_id:
        filter_q["society_id"] = society_id
    result = await db.matches.delete_one(filter_q)
    
    if result.deleted_count == 0:
        raise HTTPException(status_code=404, detail="Gara non trovata")
    
    return {"message": "Gara eliminata"}


@api_router.delete("/matches/team/{team_id}/all")
async def delete_all_team_matches(team_id: str, current_user = Depends(get_current_user)):
    """🆕 22/09/2026 — Cancella IN BLOCCO tutte le partite (calendario) di una squadra.
    Utile quando si importa per errore un calendario duplicato/errato di una squadra."""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può eliminare gare")

    society_id = current_user.get("society_id")
    filter_q = {"team_id": team_id}
    if society_id:
        filter_q["society_id"] = society_id
    result = await db.matches.delete_many(filter_q)
    return {"message": "Calendario squadra eliminato", "deleted_count": result.deleted_count}



@api_router.post("/matches/sync-fipav")
async def sync_fipav_matches(current_user = Depends(get_current_user)):
    """Sync matches from FIPAV portal - updates dates/results for existing matches"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può sincronizzare")
    
    try:
        society_id_local = current_user.get("society_id")
        
        # Get federation config or use defaults for Pallavolo Perugia
        fed_config = await db.federation_configs.find_one({"society_id": society_id_local, "federation": "fipav"})
        
        federation_society_id = "3477"  # Default Pallavolo Perugia
        region = "umbria"
        season_id = None
        
        if fed_config:
            federation_society_id = fed_config.get("federation_society_id", federation_society_id)
            region = fed_config.get("region", region)
            # 🐛 01/10/2026 — La sync IGNORAVA la stagione salvata (StId) e chiamava lo
            # scraper senza season_id → il portale FIPAV restituiva 0 gare ("Gare trovate
            # sul portale: 0"). Ora riusiamo la stagione dell'ultimo import (come preview/import).
            season_id = fed_config.get("season_id")
        
        scraper = FIPAVScraper(region=region)

        # Determina le stagioni da provare: quella configurata + quella corrente.
        current_season_id = None
        try:
            _seasons = await scraper.get_seasons()
            if _seasons:
                current_season_id = _seasons[0]["id"]
        except Exception as _e:
            logging.warning(f"FIPAV sync: impossibile determinare la stagione corrente: {_e}")

        seasons_to_try = []
        for _s in [season_id, current_season_id]:
            if _s and _s not in seasons_to_try:
                seasons_to_try.append(_s)
        if not seasons_to_try:
            seasons_to_try = [None]

        # NB: NON passiamo championship_id così recuperiamo TUTTE le gare della società
        # (tutti i campionati) e le allineiamo per match_number.
        scraped_matches = []
        used_season_id = None
        for _s in seasons_to_try:
            scraped_matches = await scraper.scrape_matches(society_id=federation_society_id, season_id=_s)
            used_season_id = _s
            if scraped_matches:
                break

        # 🆕 01/10/2026 — Auto-risoluzione società per NOME.
        # In produzione il federation_society_id salvato può essere errato/obsoleto
        # (es. ID di un'altra società o di una stagione passata) → lo scraping resta a 0.
        # In quel caso cerchiamo la società sul portale confrontando il nome.
        resolved_society_id = None
        resolved_society_name = None
        if not scraped_matches:
            try:
                # Nome di riferimento: quello salvato nell'import, altrimenti il nome società app
                society_doc = await db.societies.find_one({"id": society_id_local}, {"_id": 0, "name": 1})
                candidate_names = []
                if fed_config and fed_config.get("federation_society_name"):
                    candidate_names.append(fed_config.get("federation_society_name"))
                if society_doc and society_doc.get("name"):
                    candidate_names.append(society_doc.get("name"))

                def _norm(s):
                    import re as _re
                    s = (s or "").upper()
                    for junk in ["A.S.D.", "ASD", "S.S.D.", "SSD", "A.D.", "A.P.D.", "APD", "VOLLEY", "PALLAVOLO", "SRL", "S.R.L.", "SPA", "S.P.A."]:
                        s = s.replace(junk, " ")
                    s = _re.sub(r"[^A-Z0-9 ]", " ", s)
                    return set(w for w in s.split() if len(w) > 2)

                for _s in (seasons_to_try or [current_season_id]):
                    portal_socs = await scraper.get_societies(season_id=_s)
                    if not portal_socs:
                        continue
                    # Punteggio per società (max token-overlap su tutti i nomi candidati)
                    scored = []
                    for so in portal_socs:
                        so_tokens = _norm(so.get("name"))
                        sc = 0
                        for cname in candidate_names:
                            ctokens = _norm(cname)
                            if ctokens:
                                sc = max(sc, len(ctokens & so_tokens))
                        scored.append((sc, so))
                    scored.sort(key=lambda x: x[0], reverse=True)
                    best_score = scored[0][0] if scored else 0
                    best = scored[0][1] if scored else None
                    second_score = scored[1][0] if len(scored) > 1 else 0
                    # Accetta SOLO se match univoco (vincitore chiaro) per evitare falsi
                    # positivi su token generici (es. "PERUGIA" presente in molte società).
                    if best and best_score >= 1 and best_score > second_score:
                        retry = await scraper.scrape_matches(society_id=best["id"], season_id=_s)
                        if retry:
                            scraped_matches = retry
                            resolved_society_id = best["id"]
                            resolved_society_name = best["name"]
                            used_season_id = _s
                            # Persisti l'ID corretto per le sync future
                            await db.federation_configs.update_one(
                                {"society_id": society_id_local, "federation": "fipav"},
                                {"$set": {"federation_society_id": best["id"], "federation_society_name": best["name"], "season_id": _s, "region": region}},
                                upsert=True,
                            )
                            logging.info(f"FIPAV sync: società risolta per nome -> {best} (score {best_score} vs {second_score})")
                            break
            except Exception as _e:
                logging.warning(f"FIPAV sync: auto-risoluzione società per nome fallita: {_e}")

        season_id = used_season_id
        logging.info(f"FIPAV sync: scraped {len(scraped_matches)} matches (society={resolved_society_id or federation_society_id}, season={season_id})")
        
        # Get all existing matches for this society
        existing_matches = await db.matches.find(
            {"society_id": society_id_local, "match_number": {"$ne": None}}
        ).to_list(500)
        
        # Build lookup by match_number
        existing_by_number = {}
        for m in existing_matches:
            if m.get("match_number"):
                existing_by_number[str(m["match_number"])] = m
        
        updated_count = 0
        changes = []

        # 🆕 Token del NOSTRO nome società per determinare casa/trasferta in modo dinamico
        # (prima era hardcoded "pallavolo perugia" → errato per altre società es. SIRIO).
        _GENERIC_TOKENS = {
            "VOLLEY", "PALLAVOLO", "PALLAVOLISTICA", "VOLLEYBALL", "TEAM", "CLUB",
            "SPORT", "SPORTIVA", "SPORTIVO", "POLISPORTIVA", "ASSOCIAZIONE",
            "DILETTANTISTICA", "GSD", "ASD", "SSD", "APD", "CITY", "ACADEMY",
        }
        def _name_tokens(s):
            import re as _re
            s = (s or "").upper()
            for junk in ["A.S.D.", "ASD", "S.S.D.", "SSD", "A.D.", "A.P.D.", "APD", "SRL", "S.R.L.", "SPA", "S.P.A."]:
                s = s.replace(junk, " ")
            s = _re.sub(r"[^A-Z0-9 ]", " ", s)
            return set(w for w in s.split() if len(w) > 2)
        def _ordered_tokens(s):
            import re as _re
            s = (s or "").upper()
            s = _re.sub(r"[^A-Z0-9 ]", " ", s)
            return [w for w in s.split() if len(w) > 2]
        _our_society_doc = await db.societies.find_one({"id": society_id_local}, {"_id": 0, "name": 1})
        our_name_tokens = set()
        _our_name_sources = [resolved_society_name, (fed_config or {}).get("federation_society_name") if fed_config else None, (_our_society_doc or {}).get("name")]
        for _n in _our_name_sources:
            our_name_tokens |= _name_tokens(_n)
        # Token distintivo del club (primo token NON generico, es. "SIRIO") per il tie-break
        our_primary = None
        for _n in _our_name_sources:
            for _t in _ordered_tokens(_n):
                if _t not in _GENERIC_TOKENS:
                    our_primary = _t
                    break
            if our_primary:
                break

        def _norm_name(s):
            import re as _re
            s = (s or "").upper()
            s = _re.sub(r"[^A-Z0-9 ]", " ", s)
            return " ".join(s.split())

        # 🆕 Nome ESATTO delle NOSTRE squadre sul portale, per team_id (dai team_mappings
        # salvati in fase di import). È il segnale più affidabile per distinguere casa/trasferta
        # anche nei DERBY tra due nostre squadre (es. SIRIO ROSSA vs SIRIO ARANCIO).
        team_portal_names = {}   # {local_team_id: set(nomi normalizzati)}
        all_our_portal_names = set()
        for _m in ((fed_config or {}).get("team_mappings") or []):
            _fn = _norm_name(_m.get("federation_team_name"))
            _lid = _m.get("local_team_id")
            if _fn:
                all_our_portal_names.add(_fn)
                if _lid:
                    team_portal_names.setdefault(_lid, set()).add(_fn)

        def _side_is_us(name_norm, team_id):
            """True se questa colonna (casa/ospite) è una NOSTRA squadra.
            Prima prova il nome ESATTO della squadra del match (team_id), poi gli altri
            nostri nomi portale, infine i token del nome società."""
            if not name_norm:
                return False
            own = team_portal_names.get(team_id) or set()
            for n in own:
                if n and (n == name_norm or n in name_norm or name_norm in n):
                    return True
            for n in all_our_portal_names:
                if n and (n == name_norm or n in name_norm or name_norm in n):
                    return True
            return False

        def _classify(home_team, away_team, team_id):
            """Ritorna (is_home, opponent) oppure (None, None) se ambiguo.
            GARANZIA: l'avversario non è MAI una nostra squadra."""
            h_norm = _norm_name(home_team)
            a_norm = _norm_name(away_team)
            # 1) Match ESATTO per nome squadra sul portale (gestisce anche i derby)
            if team_portal_names.get(team_id):
                own = team_portal_names[team_id]
                h_exact = any(n == h_norm for n in own)
                a_exact = any(n == a_norm for n in own)
                if h_exact and not a_exact:
                    return True, away_team
                if a_exact and not h_exact:
                    return False, home_team
            # 2) "Noi stessi": se una colonna è una nostra squadra e l'altra NO → l'altra è l'avversario
            h_us = _side_is_us(h_norm, team_id)
            a_us = _side_is_us(a_norm, team_id)
            if h_us and not a_us:
                return True, away_team
            if a_us and not h_us:
                return False, home_team
            # 3) Token DISTINTIVO del club (es. "SIRIO") — PRIORITARIO sui token generici:
            #    se solo UN lato contiene il nome-club distintivo, quello siamo noi.
            #    (Evita l'errore in cui un avversario che condivide città/sport comuni —
            #    es. "SCHOOL VOLLEY PERUGIA" vs "SIRIO PALLAVOLO" con società "SIRIO PERUGIA
            #    VOLLEY" — otteneva più overlap e ci faceva passare per avversari.)
            if our_primary:
                in_h = our_primary in _name_tokens(home_team)
                in_a = our_primary in _name_tokens(away_team)
                if in_h != in_a:
                    return in_h, (away_team if in_h else home_team)
            # 4) Overlap token nome società SOLO su token DISTINTIVI (ignora i generici
            #    tipo VOLLEY/PALLAVOLO per non farsi confondere dai nomi degli avversari)
            distinctive = our_name_tokens - _GENERIC_TOKENS
            if distinctive:
                ov_h = len(distinctive & (_name_tokens(home_team) - _GENERIC_TOKENS))
                ov_a = len(distinctive & (_name_tokens(away_team) - _GENERIC_TOKENS))
                if ov_h != ov_a:
                    is_home = ov_h > ov_a
                    return is_home, (away_team if is_home else home_team)
            return None, None

        for scraped in scraped_matches:
            if not scraped.match_number:
                continue
            
            match_num = str(scraped.match_number)
            existing = existing_by_number.get(match_num)
            
            if not existing:
                continue
            
            update_fields = {}
            change_details = {"match_number": match_num}
            
            # Compare dates
            existing_date = existing.get("date")
            if existing_date:
                if isinstance(existing_date, str):
                    try:
                        existing_date = datetime.fromisoformat(existing_date.replace("Z", "+00:00"))
                    except:
                        existing_date = None
                
                if existing_date and scraped.date:
                    # Compare without timezone (both are naive)
                    existing_naive = existing_date.replace(tzinfo=None) if existing_date.tzinfo else existing_date
                    scraped_naive = scraped.date.replace(tzinfo=None) if scraped.date.tzinfo else scraped.date
                    
                    if existing_naive != scraped_naive:
                        update_fields["date"] = scraped.date
                        change_details["date_old"] = existing_naive.strftime("%d/%m/%Y %H:%M")
                        change_details["date_new"] = scraped_naive.strftime("%d/%m/%Y %H:%M")
            
            # Compare results
            existing_result = existing.get("result")
            scraped_result = scraped.result
            if scraped_result and scraped_result != "-" and scraped_result != existing_result:
                update_fields["result"] = scraped_result
                change_details["result_old"] = existing_result or "—"
                change_details["result_new"] = scraped_result
            
            # Compare opponent name (might have changed) + casa/trasferta.
            # ⚠️ Aggiorniamo opponent/home_away SOLO se riusciamo a stabilire con certezza
            # qual è la NOSTRA squadra (altrimenti NON tocchiamo i campi: evita di scrivere
            # noi stessi come avversario in caso di ambiguità).
            _is_home, _opp = _classify(scraped.home_team, scraped.away_team, existing.get("team_id"))
            if _is_home is not None:
                if _opp and _opp != existing.get("opponent"):
                    update_fields["opponent"] = _opp
                    change_details["opponent_old"] = existing.get("opponent") or "—"
                    change_details["opponent_new"] = _opp
                new_home_away = "home" if _is_home else "away"
                if new_home_away != existing.get("home_away"):
                    update_fields["home_away"] = new_home_away

            # 🆕 Aggiorna la città della gara (solo città, no palestra/indirizzo)
            new_city = (scraped.venue_city or "").strip()
            if new_city and new_city != (existing.get("venue") or "").strip():
                update_fields["venue"] = new_city
                change_details["venue_old"] = existing.get("venue") or "—"
                change_details["venue_new"] = new_city
            
            if update_fields:
                update_fields["updated_at"] = datetime.utcnow()
                await db.matches.update_one(
                    {"id": existing["id"]},
                    {"$set": update_fields}
                )
                updated_count += 1
                changes.append(change_details)
        
        return {
            "message": f"Sincronizzazione completata. {updated_count} gare aggiornate su {len(scraped_matches)} trovate.",
            "scraped_total": len(scraped_matches),
            "updated": updated_count,
            "existing_matched": len(existing_by_number),
            "changes": changes,
            "debug": {
                "federation_society_id": resolved_society_id or federation_society_id,
                "federation_society_name": resolved_society_name or ((fed_config or {}).get("federation_society_name") if fed_config else None),
                "season_id": season_id,
                "region": region,
                "resolved_by_name": bool(resolved_society_id),
            },
        }
    
    except Exception as e:
        logging.error(f"Error syncing FIPAV: {e}")
        raise HTTPException(status_code=500, detail=f"Errore sincronizzazione FIPAV: {str(e)}")


@api_router.post("/matches/import")
async def import_matches_from_excel(file_data: dict, current_user = Depends(get_current_user)):
    """Import matches from Excel data (parsed on frontend)"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può importare gare")
    
    society_id_local = current_user.get("society_id")
    matches_data = file_data.get("matches", [])
    imported_count = 0
    deleted_count = 0
    updated_count = 0  # Match numbers che esistevano già (re-import = aggiornamento)
    new_count = 0      # Match numbers nuovi (mai visti prima)
    errors = []
    
    # Collect all match_numbers from the import to decide what to delete/update
    match_numbers_to_import = set()
    for row in matches_data:
        if row.get("match_number"):
            match_numbers_to_import.add(row["match_number"])

    # 🆕 30/08/2026 — Scope l'upsert anche per SQUADRA (team_id), non solo per società.
    # Motivo: squadre diverse possono avere la STESSA numerazione gare (1,2,3...). Senza
    # lo scope per squadra, importare il calendario della squadra B cancellava le gare
    # della squadra A con lo stesso numero (es. la "gara 1" spariva). Ora ogni squadra ha
    # la propria numerazione indipendente.
    team_ids_to_import = set()
    for row in matches_data:
        if row.get("team_id"):
            team_ids_to_import.add(row["team_id"])
    
    # Pre-calcola quali match_number esistono già nel DB → quelli sono "aggiornamenti"
    # Multi-tenant: scope to current society to avoid touching other tenants' matches.
    existing_match_numbers = set()
    if match_numbers_to_import:
        _existing_query = {"match_number": {"$in": list(match_numbers_to_import)}}
        if society_id_local:
            _existing_query["society_id"] = society_id_local
        if team_ids_to_import:
            _existing_query["team_id"] = {"$in": list(team_ids_to_import)}
        existing_cursor = db.matches.find(
            _existing_query,
            {"match_number": 1, "_id": 0}
        )
        async for doc in existing_cursor:
            if doc.get("match_number"):
                existing_match_numbers.add(doc["match_number"])
    
    # If we have match_numbers, delete only those specific matches (upsert logic)
    # Otherwise, fall back to deleting all future matches for those teams
    if match_numbers_to_import:
        # Delete existing matches with same match_number - scoped by society AND team
        _del_query = {"match_number": {"$in": list(match_numbers_to_import)}}
        if society_id_local:
            _del_query["society_id"] = society_id_local
        if team_ids_to_import:
            _del_query["team_id"] = {"$in": list(team_ids_to_import)}
        result = await db.matches.delete_many(_del_query)
        deleted_count = result.deleted_count
        logging.info(f"Deleted {deleted_count} existing matches with match_numbers: {match_numbers_to_import} (teams: {team_ids_to_import})")
    else:
        # Fallback: delete future matches for teams (old behavior)
        if team_ids_to_import:
            now = datetime.utcnow()
            today = now.replace(hour=0, minute=0, second=0, microsecond=0)
            
            for team_id in team_ids_to_import:
                _del_q = {
                    "team_id": team_id,
                    "date": {"$gte": today}
                }
                if society_id_local:
                    _del_q["society_id"] = society_id_local
                result = await db.matches.delete_many(_del_q)
                deleted_count += result.deleted_count
                logging.info(f"Deleted {result.deleted_count} existing future matches for team {team_id}")
    
    for i, row in enumerate(matches_data):
        try:
            # Log per debug
            logging.info(f"Import row {i}: {row}")
            
            # Validate required fields
            if not row.get("team_id") or not row.get("date") or not row.get("opponent"):
                errors.append(f"Riga {i+1}: dati mancanti (team_id={row.get('team_id')}, date={row.get('date')}, opponent={row.get('opponent')})")
                continue
            
            # Get team name
            team = await db.teams.find_one({"id": row["team_id"]})
            team_name = team.get("name", "") if team else ""
            
            # Parse date
            date_str = row.get("date")
            match_date = None
            if isinstance(date_str, str):
                # Try different date formats (including HH:MM:SS for federation files)
                for fmt in ["%Y-%m-%d %H:%M:%S", "%d/%m/%Y %H:%M:%S", "%Y-%m-%d %H:%M", "%d/%m/%Y %H:%M", "%d/%m/%y %H:%M:%S", "%d/%m/%y %H:%M", "%Y-%m-%dT%H:%M", "%d/%m/%Y", "%d/%m/%y", "%Y-%m-%d", "%m/%d/%Y %H:%M:%S", "%m/%d/%Y %H:%M", "%m/%d/%y %H:%M", "%m/%d/%y"]:
                    try:
                        match_date = datetime.strptime(date_str.strip(), fmt)
                        logging.info(f"Date parsed with format {fmt}: {match_date}")
                        break
                    except:
                        continue
                
                if not match_date:
                    errors.append(f"Riga {i+1}: formato data non valido '{date_str}'")
                    continue
            else:
                match_date = date_str
            
            match = Match(
                society_id=society_id_local,
                team_id=row["team_id"],
                team_name=team_name,
                match_number=row.get("match_number"),  # Numero gara univoco
                championship=row.get("championship"),  # 🆕 Campionato
                girone=row.get("girone"),  # 🆕 Girone
                date=match_date,
                opponent=row["opponent"],
                venue=row.get("venue", "") or "",
                address=row.get("address"),
                city=row.get("city"),
                home_away=row.get("home_away", "away"),  # Default to away for federation imports
                meeting_time=row.get("meeting_time"),
                notes=row.get("notes")
            )
            
            await db.matches.insert_one(match.dict())
            imported_count += 1
            # Distingui aggiornamento (match_number esisteva già) vs nuova partita
            if match.match_number and match.match_number in existing_match_numbers:
                updated_count += 1
            else:
                new_count += 1
            logging.info(f"Match imported: {match.team_name} ({match.match_number}) vs {match.opponent} on {match.date}")
            
        except Exception as e:
            logging.error(f"Error importing row {i}: {e}")
            errors.append(f"Riga {i+1}: {str(e)}")
    
    return {
        "message": f"Sostituite {deleted_count} gare esistenti. Importate {imported_count} nuove gare.",
        "imported": imported_count,
        "updated": updated_count,
        "new": new_count,
        "deleted": deleted_count,
        "errors": errors
    }



@api_router.post("/admin/maintenance/backfill-match-society-ids")
async def backfill_match_society_ids(current_user = Depends(get_current_user)):
    """One-shot maintenance: assign society_id to existing matches that have none,
    by looking up team_id -> team.society_id. Admin-only."""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può eseguire la maintenance")
    
    # Build team_id -> society_id map
    teams = await db.teams.find({}, {"id": 1, "society_id": 1, "_id": 0}).to_list(2000)
    team_to_society = {t["id"]: t.get("society_id") for t in teams if t.get("society_id")}
    
    updated = 0
    missing_team = 0
    already_set = 0
    
    cursor = db.matches.find({})
    async for m in cursor:
        if m.get("society_id"):
            already_set += 1
            continue
        team_society = team_to_society.get(m.get("team_id"))
        if team_society:
            await db.matches.update_one(
                {"id": m["id"]},
                {"$set": {"society_id": team_society}}
            )
            updated += 1
        else:
            missing_team += 1
    
    return {
        "message": "Backfill completed",
        "updated": updated,
        "already_set": already_set,
        "missing_team": missing_team,
    }


@api_router.post("/admin/maintenance/invalidate-pdf-cache")
async def invalidate_pdf_cache(current_user = Depends(get_current_user)):
    """🆕 08/07/2026 — One-shot maintenance: forza rigenerazione PDF firmati della propria società.
    
    Contesto: prima del fix multi-tenancy (7/8/2026), i PDF di quietanze/soglie/privacy
    generati venivano intestati alla PRIMA società del DB invece che a quella dell'utente.
    Questo endpoint svuota `pdf_base64` dai documenti firmati della società corrente,
    forzando la rigenerazione al prossimo download con la ragione sociale corretta.
    
    La firma digitale, la data di firma e i metadati NON vengono toccati: il PDF viene
    ricostruito con le stesse informazioni ma con l'intestazione societaria corretta.
    """
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può eseguire la maintenance")
    
    society_id = current_user.get("society_id")
    if not society_id:
        raise HTTPException(status_code=400, detail="Admin senza society_id: impossibile procedere")
    
    # Tipi documento da rigenerare (quelli con intestazione societaria):
    doc_types = [
        "compensation_receipt", "coach_compensation_receipt",
        "collaboratore_compensation_receipt", "dirigente_compensation_receipt",
        "threshold_5000_communication", "threshold_15000_communication",
        "gdpr_privacy_adult", "gdpr_privacy_minor", "gdpr_adult", "gdpr_minor",
        "privacy_consent",
    ]
    
    result = await db.signed_documents.update_many(
        {"society_id": society_id, "document_type": {"$in": doc_types}, "pdf_base64": {"$exists": True, "$ne": None}},
        {"$unset": {"pdf_base64": ""}},
    )
    
    logger.info(f"[ADMIN-MAINT] PDF cache invalidata per society_id={society_id}: {result.modified_count} documenti da rigenerare")
    return {
        "message": "Cache PDF invalidata. I documenti verranno rigenerati al prossimo download.",
        "invalidated": result.modified_count,
    }


# ==================== FEDERATION CALENDAR IMPORT ====================

from federation_scraper import FIPAVScraper, FIPScraper

class FederationImportConfig(BaseModel):
    """Configuration for federation calendar import"""
    federation: str  # "fipav" or "fip"
    region: str  # e.g., "umbria"
    society_name: str  # Name of the society to filter matches
    team_mappings: List[dict]  # [{federation_team_name: str, local_team_id: str}, ...]
    season_id: Optional[str] = None
    championship_ids: Optional[List[str]] = None

class FederationSocietyConfig(BaseModel):
    """Configuration stored per society for federation imports"""
    id: str = Field(default_factory=lambda: str(ObjectId()))
    society_id: str
    federation: str  # "fipav" or "fip"
    region: str
    federation_society_id: Optional[str] = None  # ID from federation website
    federation_society_name: str  # Name as appears on federation website
    team_mappings: List[dict] = []  # [{federation_team_name: str, local_team_id: str, championship_id: str}, ...]
    last_import: Optional[datetime] = None
    created_at: datetime = Field(default_factory=datetime.utcnow)

