@api_router.post("/federation/import")
async def import_from_federation(config: dict, current_user = Depends(get_current_user)):
    """Import matches from federation to local database"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può importare calendari")
    
    try:
        federation = config.get("federation", "fipav").lower()
        region = config.get("region", "umbria")
        society_name = config.get("society_name", "")
        championship_id = config.get("championship_id")
        season_id = config.get("season_id")
        society_id = config.get("federation_society_id")
        team_mappings = config.get("team_mappings", [])  # [{federation_team_name: str, local_team_id: str}, ...]
        
        society_id_local = current_user.get("society_id")
        
        if federation == "fipav":
            scraper = FIPAVScraper(region=region)
            matches = await scraper.scrape_matches(
                society_id=society_id,
                championship_id=championship_id,
                season_id=season_id,
                society_name=society_name
            )
            
            imported_count = 0
            skipped_count = 0
            errors = []
            
            # Build a mapping dict for quick lookup
            mapping_dict = {}
            for mapping in team_mappings:
                fed_name = mapping.get("federation_team_name", "").lower()
                local_id = mapping.get("local_team_id")
                if fed_name and local_id:
                    mapping_dict[fed_name] = local_id
            
            # Also add variations of society_name to mapping
            if society_name:
                for mapping in team_mappings:
                    fed_name = mapping.get("federation_team_name", "").lower()
                    local_id = mapping.get("local_team_id")
                    if local_id:
                        # Add the society_name as a key if it contains the federation name
                        if society_name.lower() in fed_name or fed_name in society_name.lower():
                            mapping_dict[society_name.lower()] = local_id
            
            # Collect match numbers for deletion
            match_numbers = [m.match_number for m in matches if m.match_number]
            
            # Delete existing matches with same match_number
            if match_numbers:
                delete_result = await db.matches.delete_many({
                    "match_number": {"$in": match_numbers},
                    "society_id": society_id_local
                })
                logging.info(f"Deleted {delete_result.deleted_count} existing matches")
            
            for scraped_match in matches:
                # Determine which team this match is for (our team can be home or away)
                local_team_id = None
                is_home = False
                
                # Check home team
                home_lower = scraped_match.home_team.lower()
                for key, value in mapping_dict.items():
                    if key in home_lower or home_lower in key:
                        local_team_id = value
                        is_home = True
                        break
                
                # Check away team if not found in home
                if not local_team_id:
                    away_lower = scraped_match.away_team.lower()
                    for key, value in mapping_dict.items():
                        if key in away_lower or away_lower in key:
                            local_team_id = value
                            is_home = False
                            break
                
                if not local_team_id:
                    skipped_count += 1
                    continue
                
                # Get team info
                team = await db.teams.find_one({"id": local_team_id})
                team_name = team.get("name", "") if team else ""
                
                # Determine opponent
                opponent = scraped_match.away_team if is_home else scraped_match.home_team
                
                # Create match
                match = Match(
                    society_id=society_id_local,
                    team_id=local_team_id,
                    team_name=team_name,
                    match_number=scraped_match.match_number,
                    date=scraped_match.date,
                    opponent=opponent,
                    home_away="home" if is_home else "away",
                    result=scraped_match.result,
                    venue=(scraped_match.venue_city or "").strip(),  # 🆕 Solo la città della gara
                    notes=f"Campionato: {scraped_match.championship}" if scraped_match.championship else None
                )
                
                await db.matches.insert_one(match.dict())
                imported_count += 1
            
            # Save import configuration for future use
            import_config = {
                "society_id": society_id_local,
                "federation": federation,
                "region": region,
                "federation_society_id": society_id,
                "federation_society_name": society_name,
                "championship_id": championship_id,
                "season_id": season_id,
                "team_mappings": team_mappings,
                "last_import": datetime.utcnow()
            }
            
            await db.federation_configs.update_one(
                {"society_id": society_id_local, "federation": federation},
                {"$set": import_config},
                upsert=True
            )
            
            return {
                "message": f"Importate {imported_count} partite dalla federazione",
                "imported": imported_count,
                "skipped": skipped_count,
                "errors": errors
            }
        elif federation == "fip":
            # FIP Basketball
            scraper = FIPScraper(region=region)
            codice_campionato = config.get("codice_campionato", "C1")
            codice_girone = config.get("codice_girone")
            sesso = config.get("sesso", "M")
            
            if not codice_girone:
                raise HTTPException(status_code=400, detail="Seleziona un campionato (codice_girone)")
            
            matches = await scraper.scrape_matches(
                codice_campionato=codice_campionato,
                codice_girone=codice_girone,
                society_name=society_name,
                sesso=sesso
            )
            
            imported_count = 0
            skipped_count = 0
            errors = []
            
            # Build a mapping dict for quick lookup
            mapping_dict = {}
            for mapping in team_mappings:
                fed_name = mapping.get("federation_team_name", "").lower()
                local_id = mapping.get("local_team_id")
                if fed_name and local_id:
                    mapping_dict[fed_name] = local_id
            
            # Also add variations of society_name to mapping
            if society_name:
                for mapping in team_mappings:
                    fed_name = mapping.get("federation_team_name", "").lower()
                    local_id = mapping.get("local_team_id")
                    if local_id:
                        if society_name.lower() in fed_name or fed_name in society_name.lower():
                            mapping_dict[society_name.lower()] = local_id
            
            # Collect match numbers for deletion
            match_numbers = [m.match_number for m in matches if m.match_number]
            
            # Delete existing matches with same match_number
            if match_numbers:
                delete_result = await db.matches.delete_many({
                    "match_number": {"$in": match_numbers},
                    "society_id": society_id_local
                })
                logging.info(f"[FIP] Deleted {delete_result.deleted_count} existing matches")
            
            for scraped_match in matches:
                local_team_id = None
                is_home = False
                
                # Check home team
                home_lower = scraped_match.home_team.lower()
                for key, value in mapping_dict.items():
                    if key in home_lower or home_lower in key:
                        local_team_id = value
                        is_home = True
                        break
                
                # Check away team if not found in home
                if not local_team_id:
                    away_lower = scraped_match.away_team.lower()
                    for key, value in mapping_dict.items():
                        if key in away_lower or away_lower in key:
                            local_team_id = value
                            is_home = False
                            break
                
                if not local_team_id:
                    skipped_count += 1
                    continue
                
                # Create match document
                match_doc = {
                    "id": str(uuid.uuid4()),
                    "team_id": local_team_id,
                    "society_id": society_id_local,
                    "match_number": scraped_match.match_number,
                    "date": scraped_match.date,
                    "opponent": scraped_match.away_team if is_home else scraped_match.home_team,
                    "home_away": "home" if is_home else "away",
                    "venue": scraped_match.venue,
                    "result": scraped_match.result,
                    "championship": scraped_match.championship,
                    "giornata": scraped_match.giornata,
                    "federation": "fip",
                    "imported_at": datetime.utcnow(),
                    "created_at": datetime.utcnow()
                }
                
                await db.matches.insert_one(match_doc)
                imported_count += 1
            
            # Save import configuration
            import_config = {
                "society_id": society_id_local,
                "federation": federation,
                "region": region,
                "codice_campionato": codice_campionato,
                "codice_girone": codice_girone,
                "sesso": sesso,
                "society_name": society_name,
                "team_mappings": team_mappings,
                "last_import": datetime.utcnow()
            }
            
            await db.federation_configs.update_one(
                {"society_id": society_id_local, "federation": federation},
                {"$set": import_config},
                upsert=True
            )
            
            return {
                "message": f"Importate {imported_count} partite FIP",
                "imported": imported_count,
                "skipped": skipped_count,
                "errors": errors
            }
        else:
            raise HTTPException(status_code=400, detail="Federazione non supportata")
    
    except HTTPException:
        raise
    except Exception as e:
        logging.error(f"Error importing from federation: {e}")
        raise HTTPException(status_code=500, detail=f"Errore import: {str(e)}")

@api_router.post("/federation/import-selected")
async def import_selected_matches(config: dict, current_user = Depends(get_current_user)):
    """Import selected matches directly (without re-scraping)"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può importare partite")
    
    try:
        matches = config.get("matches", [])
        society_name = config.get("society_name", "")
        team_mappings = config.get("team_mappings", [])
        
        society_id_local = current_user.get("society_id")
        
        imported_count = 0
        skipped_count = 0

        # 🆕 06/2026 — Classificazione ROBUSTA casa/trasferta + avversario.
        # Fonte di verità: il portale FIPAV indica GIÀ chi è in casa (home_team) e chi ospite
        # (away_team). Dobbiamo solo capire QUALE lato è una NOSTRA squadra (via team_mappings)
        # e, nei DERBY tra due nostre squadre, creare un record per CIASCUNA (avversario = l'altra).
        # Questo elimina i bug "giochiamo contro noi stessi" e casa/trasferta invertite.
        def _norm_tn(s):
            import re as _re
            s = (s or "").upper()
            s = _re.sub(r"[^A-Z0-9 ]", " ", s)
            return " ".join(s.split())

        # [(nome_federale_normalizzato, local_team_id)] dal più specifico (lungo) al più generico
        team_fed_map = []
        for mapping in team_mappings:
            fn = _norm_tn(mapping.get("federation_team_name"))
            lid = mapping.get("local_team_id")
            if fn and lid:
                team_fed_map.append((fn, lid))
        team_fed_map.sort(key=lambda x: len(x[0]), reverse=True)

        def _side_team(side_norm):
            """local_team_id se questo lato è una NOSTRA squadra.
            Match ESATTO prioritario; poi il nome federale PIÙ SPECIFICO contenuto nel lato
            (o viceversa). Così 'SIRIO PALLAVOLO ROSSA' non viene confuso con 'SIRIO PALLAVOLO'."""
            if not side_norm:
                return None
            for fn, lid in team_fed_map:
                if fn == side_norm:
                    return lid
            for fn, lid in team_fed_map:
                if fn and (fn in side_norm or side_norm in fn):
                    return lid
            return None

        # Cache dei documenti squadra locali (per mostrare l'avversario di un derby col nome interno)
        _teams_cache = {}
        async def _team_doc(tid):
            if tid not in _teams_cache:
                _teams_cache[tid] = await db.teams.find_one({"id": tid})
            return _teams_cache[tid]

        for match_data in matches:
            home_team = match_data.get("home_team", "")
            away_team = match_data.get("away_team", "")
            match_number = match_data.get("match_number", "")
            match_date_str = match_data.get("date", "")
            result = match_data.get("result")

            # Parse date
            try:
                match_date = datetime.fromisoformat(match_date_str.replace('Z', '+00:00'))
            except:
                skipped_count += 1
                continue

            h_team = _side_team(_norm_tn(home_team))
            a_team = _side_team(_norm_tn(away_team))

            # Piani di creazione: (local_team_id, is_home, opponent_raw, opponent_local_id)
            plans = []
            if h_team and a_team and h_team != a_team:
                # DERBY tra due NOSTRE squadre → un record per ciascuna
                plans.append((h_team, True, away_team, a_team))
                plans.append((a_team, False, home_team, h_team))
            elif h_team:
                plans.append((h_team, True, away_team, a_team if a_team and a_team != h_team else None))
            elif a_team:
                plans.append((a_team, False, home_team, h_team if h_team and h_team != a_team else None))
            else:
                skipped_count += 1
                continue

            venue_val = (match_data.get("venue_city") or match_data.get("venue") or "").strip()
            championship_val = match_data.get("championship")
            girone_val = match_data.get("girone")

            # 🆕 Pulizia PRE-insert: rimuove eventuali record vecchi/errati di QUESTA gara
            # (numero base + mirror derby "-D") per TUTTE le nostre squadre coinvolte, a
            # prescindere da chi era casa/trasferta. Evita duplicati e ripara i record
            # legacy con avversario sbagliato (es. "noi stessi").
            base_number = match_number or f"FIPAV-{match_date.strftime('%Y%m%d%H%M')}"
            plan_team_ids = list({p[0] for p in plans})
            await db.matches.delete_many({
                "match_number": {"$in": [base_number, f"{base_number}-D"]},
                "society_id": society_id_local,
                "team_id": {"$in": plan_team_ids},
            })

            for idx, (local_team_id, is_home, opponent_raw, opp_local_id) in enumerate(plans):
                # Avversario: se è una nostra squadra (derby) usa il nome INTERNO, altrimenti il nome federale
                opponent = opponent_raw
                if opp_local_id:
                    od = await _team_doc(opp_local_id)
                    if od and od.get("name"):
                        opponent = od["name"]

                team = await _team_doc(local_team_id)
                team_name = team.get("name", "") if team else ""

                # Numero gara: il record principale mantiene il numero reale; il mirror del derby usa suffisso
                rec_number = base_number if idx == 0 else f"{base_number}-D"

                match = Match(
                    society_id=society_id_local,
                    team_id=local_team_id,
                    team_name=team_name,
                    match_number=rec_number,
                    championship=championship_val,
                    girone=girone_val,
                    date=match_date,
                    opponent=opponent,
                    home_away="home" if is_home else "away",
                    result=result if result and result != '-' else None,
                    venue=venue_val,  # 🆕 Palestra + Città
                )

                await db.matches.insert_one(match.dict())
                imported_count += 1

        # 🆕 06/2026 — Persisti i team_mappings nella config federazione (merge, non azzerare).
        # Serve alla SYNC per riconoscere casa/trasferta e correggere i derby (nome ESATTO
        # della squadra sul portale). import-selected prima NON li salvava → sync "cieca".
        if team_mappings:
            existing_cfg = await db.federation_configs.find_one(
                {"society_id": society_id_local, "federation": "fipav"}
            ) or {}
            merged = {}
            for _m in (existing_cfg.get("team_mappings") or []):
                k = (_m.get("federation_team_name"), _m.get("local_team_id"))
                if k[0] and k[1]:
                    merged[k] = _m
            for _m in team_mappings:
                k = (_m.get("federation_team_name"), _m.get("local_team_id"))
                if k[0] and k[1]:
                    merged[k] = _m
            await db.federation_configs.update_one(
                {"society_id": society_id_local, "federation": "fipav"},
                {"$set": {
                    "team_mappings": list(merged.values()),
                    "federation_society_name": society_name or existing_cfg.get("federation_society_name"),
                    "last_import": datetime.utcnow(),
                }},
                upsert=True,
            )

        return {
            "message": f"Importate {imported_count} partite",
            "imported": imported_count,
            "skipped": skipped_count
        }
    
    except Exception as e:
        logging.error(f"Error importing selected matches: {e}")
        raise HTTPException(status_code=500, detail=f"Errore import: {str(e)}")

@api_router.get("/federation/config")
async def get_federation_config(current_user = Depends(get_current_user)):
    """Get saved federation import configuration for current society"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può vedere la configurazione")
    
    society_id = current_user.get("society_id")
    if not society_id:
        return None
    
    config = await db.federation_configs.find_one({"society_id": society_id})
    if config:
        clean_mongo_doc(config)
    
    return config

@api_router.delete("/federation/config")
async def delete_federation_config(current_user = Depends(get_current_user)):
    """Delete federation import configuration"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può eliminare la configurazione")
    
    society_id = current_user.get("society_id")
    if not society_id:
        return {"message": "Nessuna configurazione trovata"}
    
    await db.federation_configs.delete_one({"society_id": society_id})
    
    return {"message": "Configurazione eliminata"}

@api_router.get("/federation/preferences")
async def get_federation_preferences(current_user = Depends(get_current_user)):
    """Get saved federation selection preferences for current society"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")
    
    society_id = current_user.get("society_id")
