@api_router.get("/athletes")
async def get_all_athletes(light: bool = False, current_user = Depends(get_current_user)):
    """Get all athletes - admin only.
    🚀 06/2026 — Modalità `light=true`: per la LISTA atleti restituisce solo i dati
    minimi (nome/cognome/squadra/stato) SENZA il "join" sui pagamenti, SENZA la
    scrittura self-heal e con proiezione POSITIVA (solo i campi usati dalla lista).
    I dettagli pesanti (pagamenti, documenti, storico) si caricano solo aprendo
    l'atleta. La modalità piena resta il default per gli altri consumer.
    🆕 01/07/2026 — Filtro clean-slate: solo atleti della stagione corrente.
    🐛 16/07/2026 — HOTFIX "Atleti spariti dopo rollover stagione":
    stesso pattern dei bug "Genitori vuoti" (10/07) e "Dirigenti spariti"
    (16/07). Se l'atleta è rimasto nella stagione precedente (mancata
    migrazione), spariva dalla lista pur essendo contato in /admin/stats.
    Ora la source-of-truth è: "tutti gli atleti della società non
    esplicitamente rimossi dalla stagione corrente". Self-heal aggiunge
    la stagione corrente ad `active_seasons` (idempotente).
    """
    if current_user["role"] not in (UserRole.ADMIN, UserRole.COORDINATORE):
        raise HTTPException(status_code=403, detail="Solo admin può vedere tutti gli atleti")
    
    society_id = current_user.get("society_id")
    from utils import get_current_season_for_society as _get_cs
    _current_season = await _get_cs(db, society_id)

    _base_query = {
        "society_id": society_id,
        # Escludi solo chi è stato esplicitamente rimosso dalla stagione corrente
        "$or": [
            {"rollover_decision": {"$ne": "removed"}},
            {"rollover_decision_season": {"$ne": _current_season}},
        ],
    }

    # 🚀 06/2026 — FAST PATH per la lista: proiezione positiva minima, NIENTE join
    # pagamenti, NIENTE self-heal write. Riduce drasticamente peso e tempo di risposta.
    if light:
        _light_proj = {
            "_id": 0, "id": 1, "full_name": 1, "first_name": 1, "last_name": 1,
            "team_id": 1, "team_ids": 1, "primary_team_id": 1, "status": 1, "athlete_type": 1, "is_compensated": 1,
            "is_withdrawn": 1, "is_trial": 1, "athlete_code": 1, "date_of_birth": 1,
            "review_dismissed_season": 1, "privacy_pending_renewal": 1,
            "parent_id": 1, "second_parent_id": 1,
            # 🆕 24/08/2026 — campi per calcolare il MOTIVO dell'attesa (pending_reason)
            "is_minor": 1, "privacy_accepted": 1, "medical_certificate_verified": 1,
            "trial_start_date": 1,
            # 🆕 28/08/2026 — date certificato (necessarie a pending_reason/stato_display
            # per distinguere "manca la data" da "da convalidare")
            "medical_certificate_issue_date": 1, "medical_certificate_date": 1,
            "medical_certificate_expiry": 1,
        }
        athletes_l = await db.athletes.find(_base_query, _light_proj).to_list(5000)
        team_ids_l = list({a.get("team_id") for a in athletes_l if a.get("team_id")})
        teams_l = await db.teams.find(
            {"id": {"$in": team_ids_l}}, {"_id": 0, "id": 1, "name": 1}
        ).to_list(200)
        team_names_l = {t["id"]: t.get("name", "") for t in teams_l}
        out = []
        for a in athletes_l:
            full_name = a.get("full_name", "")
            if a.get("last_name") or a.get("first_name"):
                full_name = f"{a.get('last_name', '')} {a.get('first_name', '')}".strip()
            out.append({
                "id": a["id"],
                "full_name": full_name,
                "first_name": a.get("first_name", ""),
                "last_name": a.get("last_name", ""),
                "team_id": a.get("team_id"),
                "team_name": team_names_l.get(a.get("team_id"), ""),
                "status": a.get("status", "pending"),
                "parent_id": a.get("parent_id"),
                "second_parent_id": a.get("second_parent_id"),
                "date_of_birth": a.get("date_of_birth"),
                "athlete_type": a.get("athlete_type", "quota"),
                "is_compensated": a.get("is_compensated", False),
                "is_withdrawn": a.get("is_withdrawn", False),
                "is_trial": a.get("is_trial", False),
                "athlete_code": a.get("athlete_code"),
                "review_dismissed_season": a.get("review_dismissed_season"),
                "privacy_pending_renewal": a.get("privacy_pending_renewal", False),
                "pending_reason": compute_pending_reason(a),
                "stato_display": compute_status_badge(a),
            })
        return out


@api_router.get("/admin/team-roster")
async def get_team_roster(team_id: str, current_user = Depends(get_current_user)):
    """🆕 31/08/2026 — Elenco atleti di UNA squadra con campi selezionabili lato UI
    (data di nascita, età, tesserato, certificato medico, categoria, genere, CF, stato,
    genitore). Solo admin/coordinatore. Isolato per società + stagione corrente."""
    if current_user["role"] not in (UserRole.ADMIN, UserRole.COORDINATORE):
        raise HTTPException(status_code=403, detail="Solo admin può vedere l'elenco squadra")

    society_id = current_user.get("society_id")
    from utils import get_current_season_for_society as _get_cs
    _current_season = await _get_cs(db, society_id)

    is_all = (team_id or "").upper() == "ALL"

    # Mappa team_id -> nome (per la colonna Categoria, specie in modalità "tutta la società")
    teams_cur = db.teams.find({"society_id": society_id}, {"_id": 0, "id": 1, "name": 1})
    team_name_map = {t["id"]: t.get("name", "") for t in await teams_cur.to_list(500)}

    if is_all:
        team = {"id": "ALL", "name": "Tutta la società"}
        _q = {
            "society_id": society_id,
            # 🆕 05/10/2026 — Escludi gli atleti RITIRATI (is_withdrawn) dall'elenco squadra,
            # dal conteggio e da "Registra Presenze" (prima comparivano ancora perché il
            # filtro era solo su status/rollover e alcuni ritirati hanno is_withdrawn=True
            # ma status diverso).
            "is_withdrawn": {"$ne": True},
            "$or": [
                {"rollover_decision": {"$ne": "removed"}},
                {"rollover_decision_season": {"$ne": _current_season}},
            ],
        }
    else:
        if team_id not in team_name_map:
            raise HTTPException(status_code=404, detail="Squadra non trovata")
        team = {"id": team_id, "name": team_name_map.get(team_id, "")}
        # 🐛 22/09/2026 — includere anche gli atleti con questa squadra come SECONDA/TERZA
        # (team_ids), non solo la principale (team_id). Prima l'elenco risultava vuoto per U17/U19.
        _q = {
            "society_id": society_id,
            "is_withdrawn": {"$ne": True},  # 🆕 esclude i ritirati (vedi nota sopra)
            "$and": [
                {"$or": [{"team_id": team_id}, {"team_ids": team_id}]},
                {"$or": [
                    {"rollover_decision": {"$ne": "removed"}},
                    {"rollover_decision_season": {"$ne": _current_season}},
                ]},
            ],
        }
    proj = {
        "_id": 0, "id": 1, "first_name": 1, "last_name": 1, "full_name": 1,
        "date_of_birth": 1, "gender": 1, "fiscal_code": 1, "status": 1,
        "medical_certificate_expiry": 1, "parent_id": 1, "second_parent_id": 1,
        "privacy_accepted": 1, "medical_certificate_verified": 1,
        "address": 1, "city": 1, "cap": 1, "postal_code": 1, "team_id": 1, "is_registered": 1,
        "is_trial": 1, "trial_sessions_count": 1,
    }
    aths = await db.athletes.find(_q, proj).to_list(5000)

    pids = list({a.get("parent_id") for a in aths if a.get("parent_id")})
    pmap = {}
    if pids:
        parents = await db.users.find({"id": {"$in": pids}}, {"_id": 0, "id": 1, "full_name": 1}).to_list(5000)
        pmap = {p["id"]: p.get("full_name", "") for p in parents}

    today = now_it().replace(tzinfo=None).date()

    def _to_date(v):
        if not v:
            return None
        s = str(v).replace("Z", "").replace("+00:00", "")
        for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S", "%Y-%m-%d"):
            try:
                from datetime import datetime as _dt
                return _dt.strptime(s[:19] if "T" in s or " " in s else s[:10], fmt).date()
            except Exception:
                continue
        try:
            from datetime import datetime as _dt
            return _dt.fromisoformat(s[:10]).date()
        except Exception:
            return None

    def _calc_age(d):
        if not d:
            return None
        return today.year - d.year - ((today.month, today.day) < (d.month, d.day))

    # 🆕 limite prove della società (per evidenziare "PROVA SCADUTA" nel roster presenze)
    _ss_trial = await db.settings.find_one({"type": "society", "society_id": society_id}, {"_id": 0, "trial_max_sessions": 1}) if society_id else None
    _trial_max_sessions = (_ss_trial or {}).get("trial_max_sessions", 3) or 3
    _teams_full = {t["id"]: t for t in await db.teams.find({"society_id": society_id}, {"_id": 0, "id": 1, "certificate_type_required": 1}).to_list(1000)} if society_id else {}

    out = []
    for a in aths:
        # 🆕 Auto-attivazione minorenni "pronti" (privacy firmata + eventuale certificato
        # convalidato se richiesto dalla squadra) DIRETTAMENTE all'apertura del roster
        # presenze. Risolve: atleti bloccati in "PROVA SCADUTA · pronto: usa Ripara prove
        # in blocco" che non si attivavano mai da soli (es. squadre U12 senza obbligo di
        # certificato, dove il backfill allo startup li escludeva). Idempotente.
        _status_cur = a.get("status")
        # 🆕 Atleti GIÀ in forza (active/blocked/rejected) non devono MAI comparire come
        # "PROVA SCADUTA": se è rimasta appiccicata l'etichetta prova (is_trial=True) la
        # ripuliamo subito (auto-heal). Era questo il caso "pronto ma non succede nulla":
        # l'atleta era già attivo ma restava rosso e la riparazione lo saltava.
        if _status_cur in ("active", "blocked", "rejected"):
            if a.get("is_trial"):
                await db.athletes.update_one({"id": a["id"]}, {"$set": {"is_trial": False, "trial_status": "completed"}})
                a["is_trial"] = False
            _in_trial = False
            _missing = []
        else:
            _in_trial = bool(a.get("is_trial")) or _status_cur == "trial"
            _missing = _trial_missing_reasons(a, _teams_full.get(a.get("team_id"))) if _in_trial else []
            if _in_trial and not _missing:
                if await maybe_activate_athlete(a["id"]):
                    a["status"] = "active"
                    a["is_trial"] = False
                    _in_trial = False
                    _missing = []
        dob = _to_date(a.get("date_of_birth"))
        exp = _to_date(a.get("medical_certificate_expiry"))
        if not a.get("medical_certificate_expiry"):
            cert_label, cert_expiry, cert_valid = "Mancante", "", False
        elif exp is None:
            cert_label, cert_expiry, cert_valid = "Data non valida", "", False
        else:
            cert_valid = exp >= today
            cert_label = "Valido" if cert_valid else "Scaduto"
            cert_expiry = exp.strftime("%d/%m/%Y")
        full_name = (f"{a.get('last_name','')} {a.get('first_name','')}".strip() or a.get("full_name", ""))
        category = team_name_map.get(a.get("team_id"), "") if is_all else team.get("name", "")
        out.append({
            "id": a["id"],
            "full_name": full_name,
            "last_name": a.get("last_name", ""),
            "first_name": a.get("first_name", ""),
            "date_of_birth": dob.strftime("%d/%m/%Y") if dob else "",
            "age": _calc_age(dob),
            "tesserato": bool(a.get("is_registered")),
            "status": a.get("status", "pending"),
            "is_trial": _in_trial,
            "trial_sessions_count": a.get("trial_sessions_count", 0),
            "trial_max_sessions": _trial_max_sessions,
            # 🆕 perché è ancora in prova (es. "privacy da firmare", "certificato mancante")
            "trial_missing": _missing,
            "cert_label": cert_label,
            "cert_expiry": cert_expiry,
            "cert_valid": cert_valid,
            "gender": a.get("gender", ""),
            "fiscal_code": a.get("fiscal_code", ""),
            "category": category,
            "address": a.get("address", "") or "",
            "city": a.get("city", "") or "",
            "cap": a.get("postal_code", "") or a.get("cap", "") or "",
            "parent_name": pmap.get(a.get("parent_id"), ""),
        })
    out.sort(key=lambda x: (x.get("full_name") or "").lower())
    return {"team": team, "count": len(out), "athletes": out}

# ============================================================================
# 🆕 CONVOCAZIONI (call-ups) — Admin/Coach selezionano gli atleti della rosa di
# una squadra per una gara (dal calendario o inserita a mano), aggiungono
# ritrovo/orari/note, salvano come bozza o "inviata". Il PDF e l'apertura di
# WhatsApp precompilato avvengono lato app. Isolato per società.
# ============================================================================

async def _conv_team_or_403(current_user, team_id: str) -> dict:
    """Ritorna la squadra se l'utente può gestirne le convocazioni, altrimenti 403/404.
    Admin/Coordinatore: qualsiasi squadra della società. Coach: solo le assegnate."""
    society_id = current_user.get("society_id")
    team = await db.teams.find_one({"id": team_id, "society_id": society_id}, {"_id": 0, "id": 1, "name": 1})
    if not team:
        raise HTTPException(status_code=404, detail="Squadra non trovata")
    role = current_user["role"]
    if role in (UserRole.ADMIN, UserRole.COORDINATORE, UserRole.DIRIGENTE):
        return team
    if role == UserRole.COACH and team_id in (current_user.get("assigned_teams", []) or []):
        return team
    raise HTTPException(status_code=403, detail="Non sei autorizzato a gestire le convocazioni di questa squadra")


def _conv_phones_from_athlete(a: dict, pmap: dict) -> dict:
    """Telefoni (atleta/madre/padre con fallback dai genitori collegati)."""
    def _clean(v):
        return (str(v).strip() if v else "")
    athlete_phone = _clean(a.get("phone_athlete")) or _clean(a.get("phone"))
    mother_phone = _clean(a.get("phone_mother"))
    father_phone = _clean(a.get("phone_father"))
    parent_fallback = _clean(pmap.get(a.get("parent_id"))) or _clean(pmap.get(a.get("second_parent_id")))
    if not mother_phone and not father_phone and parent_fallback:
        mother_phone = parent_fallback
    return {"athlete_phone": athlete_phone, "mother_phone": mother_phone, "father_phone": father_phone}


@api_router.get("/convocations/team/{team_id}/roster")
async def convocation_roster(team_id: str, current_user = Depends(get_current_user)):
    """Elenco atleti (anche aggregati via team_ids) della squadra per la selezione
    nella convocazione. Accessibile ad admin/coordinatore/coach assegnato."""
    team = await _conv_team_or_403(current_user, team_id)
    society_id = current_user.get("society_id")
    # ⚠️ Stessa identica query del "Registro Presenze" (/teams/{id}/attendance-stats):
    # atleti collegati via team_id OPPURE team_id_2 (seconda squadra) OPPURE team_ids
    # (aggregati). Prima mancava team_id_2 → in squadre come la Serie D (13 atlete
    # assegnate come seconda squadra) la convocazione mostrava 0 atlete.
    q = {
        "$or": [
            {"team_id": team_id},
            {"team_id_2": team_id},
            {"team_ids": team_id},
        ],
        "status": {"$nin": ["rejected", "withdrawn", "removed", "deleted"]},
        "is_withdrawn": {"$ne": True},
    }
    if society_id:
        q["society_id"] = society_id
    proj = {"_id": 0, "id": 1, "first_name": 1, "last_name": 1, "full_name": 1,
            "date_of_birth": 1, "athlete_role": 1, "status": 1}
    aths = await db.athletes.find(q, proj).to_list(5000)
    # Parità col Registro Presenze: includi anche gli atleti in prova che hanno
    # presenze registrate per questa squadra ma senza team_id impostato.
    existing_ids = {a["id"] for a in aths}
    trial_attendance_ids = await db.attendances.distinct("athlete_id", {"team_id": team_id})
    missing_ids = [aid for aid in trial_attendance_ids if aid not in existing_ids]
    if missing_ids:
        q_extra = {"id": {"$in": missing_ids}, "status": "trial", "is_withdrawn": {"$ne": True}}
        if society_id:
            q_extra["society_id"] = society_id
        aths.extend(await db.athletes.find(q_extra, proj).to_list(500))
    out = []
    for a in aths:
        full_name = (f"{a.get('last_name','')} {a.get('first_name','')}".strip() or a.get("full_name", ""))
        out.append({
            "id": a["id"],
            "full_name": full_name,
            "role": a.get("athlete_role", "") or "",
            "is_minor": _compute_is_minor(a),
        })
    out.sort(key=lambda x: (x.get("full_name") or "").lower())
    return {"team": team, "count": len(out), "athletes": out}


def _conv_public(c: dict) -> dict:
    """Pulisce una convocazione per l'output (rimuove _id)."""
    c = dict(c)
    c.pop("_id", None)
    return c


@api_router.get("/convocations")
async def list_convocations(team_id: Optional[str] = None, current_user = Depends(get_current_user)):
    """Elenco convocazioni. Se team_id è passato → solo quella squadra (con controllo
    autorizzazione). Per i coach senza team_id → solo le squadre assegnate."""
    society_id = current_user.get("society_id")
    role = current_user["role"]
    q = {"society_id": society_id}
    if team_id:
        await _conv_team_or_403(current_user, team_id)
        q["team_id"] = team_id
    elif role == UserRole.COACH:
        q["team_id"] = {"$in": current_user.get("assigned_teams", []) or []}
    elif role not in (UserRole.ADMIN, UserRole.COORDINATORE, UserRole.DIRIGENTE):
        raise HTTPException(status_code=403, detail="Non autorizzato")
    items = await db.convocations.find(q).sort("created_at", -1).to_list(1000)
    return [_conv_public(c) for c in items]


@api_router.post("/convocations")
async def create_convocation(data: dict = Body(...), current_user = Depends(get_current_user)):
    """Crea una convocazione (bozza o inviata). Campi gara/ritrovo/note gestiti
    lato app (stringhe già formattate). athlete_ids = atleti selezionati."""
    team_id = (data.get("team_id") or "").strip()
    if not team_id:
        raise HTTPException(status_code=400, detail="team_id obbligatorio")
    team = await _conv_team_or_403(current_user, team_id)
    now = datetime.utcnow()
    conv = {
        "id": str(uuid.uuid4()),
        "society_id": current_user.get("society_id"),
        "team_id": team_id,
        "team_name": team.get("name", ""),
        "match_id": data.get("match_id") or None,
        "opponent": (data.get("opponent") or "").strip(),
        "match_date": (data.get("match_date") or "").strip(),
        "match_time": (data.get("match_time") or "").strip(),
        "home_away": data.get("home_away") or "home",
        "venue": (data.get("venue") or "").strip(),
        "venue_address": (data.get("venue_address") or "").strip(),
        "maps_url": (data.get("maps_url") or "").strip(),
        "city": (data.get("city") or "").strip(),
        "meeting_place": (data.get("meeting_place") or "").strip(),
        "meeting_time": (data.get("meeting_time") or "").strip(),
        "start_time": (data.get("start_time") or "").strip(),
        "notes": (data.get("notes") or "").strip(),
        "athlete_ids": list(data.get("athlete_ids") or []),
        "status": "sent" if data.get("status") == "sent" else "draft",
        "created_by": current_user["id"],
        "created_by_name": current_user.get("full_name", current_user.get("email", "")),
        "created_at": now,
        "updated_at": now,
        "sent_at": now if data.get("status") == "sent" else None,
    }
    await db.convocations.insert_one(conv)
    return _conv_public(conv)


async def _get_conv_or_404(conv_id: str, current_user) -> dict:
    conv = await db.convocations.find_one({"id": conv_id, "society_id": current_user.get("society_id")})
    if not conv:
        raise HTTPException(status_code=404, detail="Convocazione non trovata")
    await _conv_team_or_403(current_user, conv["team_id"])
    return conv


@api_router.get("/convocations/{conv_id}")
async def get_convocation(conv_id: str, current_user = Depends(get_current_user)):
    """Dettaglio convocazione con i nomi degli atleti selezionati (per il PDF/anteprima)."""
    conv = await _get_conv_or_404(conv_id, current_user)
    ids = conv.get("athlete_ids") or []
    names = []
    if ids:
        aths = await db.athletes.find({"id": {"$in": ids}}, {"_id": 0, "id": 1, "first_name": 1, "last_name": 1, "full_name": 1, "athlete_role": 1}).to_list(5000)
        amap = {a["id"]: a for a in aths}
        for aid in ids:
            a = amap.get(aid)
            if not a:
                continue
            names.append({
                "id": aid,
                "full_name": (f"{a.get('last_name','')} {a.get('first_name','')}".strip() or a.get("full_name", "")),
                "role": a.get("athlete_role", "") or "",
            })
        names.sort(key=lambda x: (x.get("full_name") or "").lower())
    out = _conv_public(conv)
    out["athletes"] = names
    return out


@api_router.patch("/convocations/{conv_id}")
async def update_convocation(conv_id: str, data: dict = Body(...), current_user = Depends(get_current_user)):
    """Aggiorna una convocazione esistente (campi gara/ritrovo/note/atleti/stato)."""
    conv = await _get_conv_or_404(conv_id, current_user)
    allowed = ["match_id", "opponent", "match_date", "match_time", "home_away",
               "venue", "venue_address", "maps_url", "city", "meeting_place",
               "meeting_time", "start_time", "notes", "athlete_ids", "status"]
    upd = {}
    for k in allowed:
        if k not in data:
            continue
        if k == "athlete_ids":
            upd[k] = list(data.get(k) or [])
        elif k == "status":
            upd[k] = "sent" if data.get(k) == "sent" else "draft"
        elif k == "match_id":
            upd[k] = data.get(k) or None
        elif k in ("home_away",):
            upd[k] = data.get(k) or "home"
        else:
            upd[k] = (str(data.get(k) or "")).strip()
    upd["updated_at"] = datetime.utcnow()
    if upd.get("status") == "sent" and not conv.get("sent_at"):
        upd["sent_at"] = datetime.utcnow()
    await db.convocations.update_one({"id": conv_id}, {"$set": upd})
    fresh = await db.convocations.find_one({"id": conv_id})
    return _conv_public(fresh)


@api_router.post("/convocations/{conv_id}/send")
async def send_convocation(conv_id: str, current_user = Depends(get_current_user)):
    """Segna la convocazione come INVIATA (dopo l'apertura di WhatsApp lato app)."""
    conv = await _get_conv_or_404(conv_id, current_user)
    now = datetime.utcnow()
    await db.convocations.update_one(
        {"id": conv_id},
        {"$set": {"status": "sent", "sent_at": conv.get("sent_at") or now, "updated_at": now}},
    )
    fresh = await db.convocations.find_one({"id": conv_id})
    return _conv_public(fresh)


@api_router.delete("/convocations/{conv_id}")
async def delete_convocation(conv_id: str, current_user = Depends(get_current_user)):
    await _get_conv_or_404(conv_id, current_user)
    await db.convocations.delete_one({"id": conv_id})
    return {"deleted": True}


@api_router.get("/convocations/{conv_id}/contacts")
async def convocation_contacts(conv_id: str, current_user = Depends(get_current_user)):
    """Telefoni (atleta/madre/padre) SOLO degli atleti convocati, per l'invio WhatsApp."""
    conv = await _get_conv_or_404(conv_id, current_user)
    ids = conv.get("athlete_ids") or []
    if not ids:
        return {"count": 0, "athletes": []}
    proj = {"_id": 0, "id": 1, "first_name": 1, "last_name": 1, "full_name": 1,
            "date_of_birth": 1, "phone_athlete": 1, "phone": 1,
            "phone_mother": 1, "phone_father": 1, "parent_id": 1, "second_parent_id": 1}
    aths = await db.athletes.find({"id": {"$in": ids}}, proj).to_list(5000)
    pids = list({p for a in aths for p in (a.get("parent_id"), a.get("second_parent_id")) if p})
    pmap = {}
    if pids:
        parents = await db.users.find({"id": {"$in": pids}}, {"_id": 0, "id": 1, "phone": 1}).to_list(5000)
        pmap = {p["id"]: (p.get("phone") or "").strip() for p in parents}
    out = []
    for a in aths:
        full_name = (f"{a.get('last_name','')} {a.get('first_name','')}".strip() or a.get("full_name", ""))
        phones = _conv_phones_from_athlete(a, pmap)
        out.append({
            "athlete_id": a["id"],
            "athlete_name": full_name,
            "is_minor": _compute_is_minor(a),
            **phones,
        })
    out.sort(key=lambda x: (x.get("athlete_name") or "").lower())
    return {"count": len(out), "athletes": out}


@api_router.get("/convocations/for-athlete/{athlete_id}")
async def convocations_for_athlete(athlete_id: str, current_user = Depends(get_current_user)):
    """🆕 Convocazioni INVIATE in cui l'atleta è convocato, in SOLA LETTURA, per
    la home dell'atleta/genitore e l'accesso Lite. Include i dati gara/ritrovo,
    indirizzo+mappa e il contatto del coach (per avvisare in caso di assenza)."""
    athlete = await db.athletes.find_one({"id": athlete_id}, {"_id": 0, "id": 1, "society_id": 1, "parent_id": 1, "second_parent_id": 1})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    sid = athlete.get("society_id")
    role = current_user.get("role")
    allowed = False
    if role in (UserRole.ADMIN, UserRole.COORDINATORE, UserRole.DIRIGENTE, UserRole.COACH) and current_user.get("society_id") == sid:
        allowed = True
    if current_user.get("athlete_id") == athlete_id:
        allowed = True
    if role in (UserRole.PARENT, "parent") and current_user.get("id") in (athlete.get("parent_id"), athlete.get("second_parent_id")):
        allowed = True
    if not allowed:
        raise HTTPException(status_code=403, detail="Non autorizzato")

    convs = await db.convocations.find(
        {"society_id": sid, "status": "sent", "athlete_ids": athlete_id}
    ).sort("created_at", -1).to_list(200)

    coach_cache: dict = {}
    async def _coach_for(team_id: str):
        if team_id in coach_cache:
            return coach_cache[team_id]
        coach = await db.users.find_one(
            {"society_id": sid, "role": UserRole.COACH, "assigned_teams": team_id},
            {"_id": 0, "full_name": 1, "phone": 1},
        )
        res = {"coach_name": (coach or {}).get("full_name", ""), "coach_phone": (coach or {}).get("phone", "")}
        coach_cache[team_id] = res
        return res

    out = []
    for c in convs:
        contact = await _coach_for(c.get("team_id"))
        out.append({
            "id": c["id"],
            "team_name": c.get("team_name", ""),
            "opponent": c.get("opponent", ""),
            "home_away": c.get("home_away", "home"),
            "match_date": c.get("match_date", ""),
            "match_time": c.get("match_time", ""),
            "venue": c.get("venue", ""),
            "venue_address": c.get("venue_address", ""),
            "maps_url": c.get("maps_url", ""),
            "city": c.get("city", ""),
            "meeting_place": c.get("meeting_place", ""),
            "meeting_time": c.get("meeting_time", ""),
            "start_time": c.get("start_time", ""),
            "notes": c.get("notes", ""),
            "coach_name": contact["coach_name"],
            "coach_phone": contact["coach_phone"],
            "sent_at": c.get("sent_at"),
        })
    return out



