def _fmt_export_date(v):
    if not v:
        return ""
    try:
        if isinstance(v, datetime):
            return v.strftime("%d/%m/%Y")
        s = str(v)
        return datetime.fromisoformat(s.replace("Z", "+00:00")).strftime("%d/%m/%Y")
    except Exception:
        return str(v)[:10]


@api_router.get("/admin/athletes/export-data")
async def admin_athletes_export_data(current_user = Depends(get_current_user)):
    """Dati anagrafici completi degli atleti della società per l'export XLS/CSV.
    Ritorna {fields:[{key,label,group}], rows:[{id, team_id, values:{key:val}}]}."""
    if current_user["role"] not in (UserRole.ADMIN, UserRole.COORDINATORE):
        raise HTTPException(status_code=403, detail="Solo admin")
    society_id = current_user.get("society_id")
    from utils import get_current_season_for_society as _get_cs
    _cs = await _get_cs(db, society_id)
    athletes = await db.athletes.find({
        "society_id": society_id,
        "$or": [
            {"rollover_decision": {"$ne": "removed"}},
            {"rollover_decision_season": {"$ne": _cs}},
        ],
    }, {
        "_id": 0, "id": 1, "first_name": 1, "last_name": 1, "full_name": 1,
        "date_of_birth": 1, "gender": 1, "birth_place": 1, "place_of_birth": 1,
        "birth_province": 1, "province_of_birth": 1, "fiscal_code": 1,
        "email": 1, "phone_athlete": 1, "phone_father": 1, "phone_mother": 1,
        "address": 1, "postal_code": 1, "city": 1, "province": 1,
        "team_id": 1, "athlete_role": 1, "athlete_height": 1, "athlete_weight": 1,
        "athlete_elevation": 1, "status": 1, "is_registered": 1, "athlete_code": 1,
        "registration_date": 1, "medical_certificate_expiry": 1,
        "medical_certificate_verified": 1, "medical_certificate_original_received": 1,
    }).to_list(5000)

    team_ids = list({a.get("team_id") for a in athletes if a.get("team_id")})
    teams = await db.teams.find({"id": {"$in": team_ids}}, {"_id": 0, "id": 1, "name": 1}).to_list(500)
    team_names = {t["id"]: t.get("name", "") for t in teams}

    def _yn(v):
        return "Sì" if v else "No"

    rows = []
    for a in athletes:
        last = a.get("last_name") or ""
        first = a.get("first_name") or ""
        if not (last or first) and a.get("full_name"):
            # full_name legacy = "Cognome Nome" oppure "Nome Cognome": best-effort
            last = a.get("full_name")
        values = {
            "last_name": last,
            "first_name": first,
            "date_of_birth": _fmt_export_date(a.get("date_of_birth")),
            "gender": a.get("gender") or "",
            "birth_place": a.get("birth_place") or a.get("place_of_birth") or "",
            "birth_province": a.get("birth_province") or a.get("province_of_birth") or "",
            "fiscal_code": a.get("fiscal_code") or "",
            "email": a.get("email") or "",
            "phone_athlete": a.get("phone_athlete") or "",
            "phone_father": a.get("phone_father") or "",
            "phone_mother": a.get("phone_mother") or "",
            "address": a.get("address") or "",
            "postal_code": a.get("postal_code") or "",
            "city": a.get("city") or "",
            "province": a.get("province") or "",
            "team_name": team_names.get(a.get("team_id"), ""),
            "athlete_role": a.get("athlete_role") or "",
            "athlete_height": a.get("athlete_height") or "",
            "athlete_weight": a.get("athlete_weight") or "",
            "athlete_elevation": a.get("athlete_elevation") or "",
            "status": a.get("status") or "",
            "is_registered": _yn(a.get("is_registered")),
            "athlete_code": a.get("athlete_code") or "",
            "registration_date": _fmt_export_date(a.get("registration_date")),
            "medical_certificate_expiry": _fmt_export_date(a.get("medical_certificate_expiry")),
            "medical_certificate_verified": _yn(a.get("medical_certificate_verified")),
            "medical_certificate_original_received": _yn(a.get("medical_certificate_original_received")),
        }
        rows.append({"id": a.get("id"), "team_id": a.get("team_id"), "values": values})

    return {"fields": EXPORT_FIELD_CATALOG, "rows": rows}


@api_router.post("/athletes", response_model=Athlete)
async def create_athlete(athlete_data: AthleteCreate, request_obj: Request, current_user = Depends(get_current_user)):
    # Only parents can create athletes
    if current_user["role"] != UserRole.PARENT:
        raise HTTPException(status_code=403, detail="Solo genitori possono registrare atleti")
    
    # Check if team exists (only if team_id provided)
    if athlete_data.team_id:
        team = await db.teams.find_one({"id": athlete_data.team_id})
        if not team:
            raise HTTPException(status_code=404, detail="Squadra non trovata")
    
    # Calculate if minor
    dob = datetime.fromisoformat(athlete_data.date_of_birth)
    age = (datetime.utcnow() - dob).days // 365
    is_minor = age < 18

    # 🆕 Certificato medico — determina lo stato di onboarding del minore:
    #   pending_certificate (ATTESA: serve cert convalidato) oppure
    #   pending_trial (ATTESA INIZIO PROVA: può provare senza cert).
    _team_for_cert = team if athlete_data.team_id else None
    _cert_type = cert_type_for_team(_team_for_cert)
    _already_reg = getattr(athlete_data, 'already_registered', None)
    _req_trial = cert_required_for_trial(is_minor, _already_reg, _cert_type)
    minor_onboarding_status = "pending_certificate" if _req_trial else "pending_trial"
    
    # Create athlete
    athlete_id = str(ObjectId())
    qr_code = generate_qr_code(athlete_id)
    
    # All athletes start as PENDING and need Admin approval
    # EXCEPT: minors registered by their parent go directly to trial
    is_trial = getattr(athlete_data, 'is_trial', True)
    # 🐛 03/08/2026 — SOLO PER I MINORENNI: la privacy NON si accetta MAI alla registrazione
    # (verrà firmata dal genitore a fine prova). Per i MAGGIORENNI resta il comportamento
    # originale (accettano la privacy in fase di registrazione).
    now = datetime.utcnow()
    document_version = "1.0-2026"
    if is_minor:
        privacy_accepted = False
        consent_privacy_viewed = False
        consent_img_internal = None
        consent_img_promo = None
    else:
        privacy_accepted = getattr(athlete_data, 'privacy_accepted', False)
        consent_privacy_viewed = getattr(athlete_data, 'consent_privacy_viewed', False)
        consent_img_internal = getattr(athlete_data, 'consent_images_internal', None)
        consent_img_promo = getattr(athlete_data, 'consent_images_promo', None)
    
    # Get client IP
    client_ip = request_obj.headers.get("x-forwarded-for", request_obj.client.host if request_obj.client else "unknown")
    
    # 🐛 09/08/2026 — MINORENNI: nessun consenso viene "espresso" alla registrazione.
    # La privacy (e i consensi immagine) vengono firmati dal genitore SOLO a fine prova
    # (o in caso di interruzione anticipata, se decide di restare). Prima salvavamo
    # privacy_viewed=false e immagini=null con timestamp: questo faceva risultare il
    # minore come "Privacy NEGATA" e "Consenso immagini NEGATO da <genitore>" pur non
    # avendo mai firmato nulla. Ora il minore parte "pulito" (consensi vuoti).
    if is_minor:
        consents = {}
        consent_history = []
    else:
        consents = {
            "privacy_viewed": {"value": consent_privacy_viewed, "timestamp": now.isoformat(), "user_id": current_user["id"], "document_version": document_version, "ip_address": client_ip},
            "images_internal": {"value": consent_img_internal, "timestamp": now.isoformat(), "user_id": current_user["id"], "document_version": document_version, "ip_address": client_ip},
            "images_promo": {"value": consent_img_promo, "timestamp": now.isoformat(), "user_id": current_user["id"], "document_version": document_version, "ip_address": client_ip},
        }
        consent_history = [
            {"type": "privacy_viewed", "old_value": None, "new_value": consent_privacy_viewed, "timestamp": now.isoformat(), "user_id": current_user["id"], "ip_address": client_ip},
            {"type": "images_internal", "old_value": None, "new_value": consent_img_internal, "timestamp": now.isoformat(), "user_id": current_user["id"], "ip_address": client_ip},
            {"type": "images_promo", "old_value": None, "new_value": consent_img_promo, "timestamp": now.isoformat(), "user_id": current_user["id"], "ip_address": client_ip},
        ]
    
    # Hash data password if provided (for minors - protects sensitive data)
    data_password_hash = None
    if athlete_data.data_password and is_minor:
        data_password_hash=hash_password(athlete_data.data_password)
    
    # Get society_id from the user's parent
    parent_user = await db.users.find_one({"id": current_user["id"]})
    society_id = parent_user.get("society_id") if parent_user else None

    # 🆕 27/08/2026 — BUGFIX "genitore invisibile": ogni atleta neo-iscritto DEVE avere
    # active_seasons = [stagione corrente], altrimenti sparisce dai filtri stagione (atleti
    # E genitori collegati). Prima veniva creato SENZA active_seasons.
    from utils import get_current_season_for_society as _get_cs_create
    _current_season_create = await _get_cs_create(db, society_id) if society_id else None

    # Check athlete limit (150 athletes until 30/06/2026)
    ATHLETE_LIMIT = 150
    LIMIT_END_DATE = datetime(2026, 6, 30, 23, 59, 59)
    
    if datetime.utcnow() < LIMIT_END_DATE and society_id:
        current_athlete_count = await db.athletes.count_documents({"society_id": society_id})
        if current_athlete_count >= ATHLETE_LIMIT:
            raise HTTPException(
                status_code=403, 
                detail=f"Limite di {ATHLETE_LIMIT} atleti raggiunto per questa stagione. Contatta l'amministratore per informazioni sui piani premium."
            )
    
    # Check if athlete already exists by fiscal code (permanent identity)
    existing_athlete = await find_existing_athlete_by_fiscal_code(athlete_data.fiscal_code)
    if existing_athlete:
        # Reactivate existing athlete - keep same qr_identifier/athlete_code
        reactivate_data = {
            "parent_id": current_user["id"],
            "society_id": society_id,
            "is_withdrawn": False,
            "withdrawn_date": None,
            "withdrawn_reason": None,
            "status": (minor_onboarding_status if is_minor else AthleteStatus.PENDING),
            # trial_end_date stays None until the FIRST QR scan (first training).
            # See QR scan handler around line 11195 which converts pending_trial -> trial
            # and only at that moment sets trial_start_date / trial_end_date.
            "trial_end_date": None,
            "is_minor": is_minor,
            "team_id": athlete_data.team_id,
            "already_registered": _already_reg,
            "privacy_accepted": privacy_accepted,
            "privacy_accepted_date": datetime.utcnow() if privacy_accepted else None,
            "consent_images_internal": consent_img_internal,
            "consent_images_promo": consent_img_promo,
            "consents": consents,
            "consent_history": consent_history,
        }
        if athlete_data.first_name:
            reactivate_data["first_name"] = athlete_data.first_name
            reactivate_data["last_name"] = athlete_data.last_name
            reactivate_data["full_name"] = athlete_data.full_name
        if athlete_data.country_of_birth:
            reactivate_data["country_of_birth"] = athlete_data.country_of_birth
        if athlete_data.birth_place:
            reactivate_data["birth_place"] = athlete_data.birth_place
        if athlete_data.birth_province:
            reactivate_data["birth_province"] = athlete_data.birth_province
        if athlete_data.email:
            reactivate_data["email"] = athlete_data.email
        if athlete_data.phone_athlete:
            reactivate_data["phone_athlete"] = athlete_data.phone_athlete
        if data_password_hash:
            reactivate_data["data_password_hash"] = data_password_hash
        # 🆕 24/08/2026 — Consenso alla PROVA in fase di (re)iscrizione (minori)
        if is_minor and getattr(athlete_data, 'trial_authorization', None):
            _ta_now = datetime.utcnow()
            reactivate_data["trial_document_generated"] = True
            reactivate_data["trial_authorized_at_registration"] = True
            reactivate_data["trial_document_signed_date"] = _ta_now.isoformat()
            reactivate_data["trial_document_signed_by"] = current_user["id"]
            reactivate_data["trial_document_signed_by_name"] = current_user.get("full_name", current_user.get("email", ""))
            _rc = dict(consents or {})
            _rc["trial_authorization"] = {
                "value": True, "timestamp": _ta_now.isoformat(), "user_id": current_user["id"],
                "parent_id": current_user["id"], "child_id": existing_athlete["id"], "ip_address": client_ip,
                "document_version": document_version, "source": "registration",
            }
            reactivate_data["consents"] = _rc
            _rh = list(consent_history or [])
            _rh.append({
                "type": "trial_authorization", "action": "granted", "old_value": None, "new_value": True,
                "timestamp": _ta_now.isoformat(), "user_id": current_user["id"], "ip_address": client_ip,
                "source": "registration",
            })
            reactivate_data["consent_history"] = _rh
        
        await db.athletes.update_one(
            {"id": existing_athlete["id"]},
            {"$set": reactivate_data}
        )
        # 🆕 Assicura la stagione corrente su atleta + genitore (self-heal collegamento)
        if _current_season_create:
            await db.athletes.update_one({"id": existing_athlete["id"]}, {"$addToSet": {"active_seasons": _current_season_create}})
            await db.users.update_one({"id": current_user["id"]}, {"$addToSet": {"active_seasons": _current_season_create}})

        updated = await db.athletes.find_one({"id": existing_athlete["id"]}, {"_id": 0})
        return Athlete(**updated)
    
    # Generate unique athlete code - now uses qr_identifier
    # 🆕 v7.12 riusa codice se stesso CF già registrato
    qr_id = await resolve_athlete_code_for_cf(getattr(athlete_data, "fiscal_code", None))
    qr_code = generate_qr_code_from_identifier(qr_id)
    athlete_code = qr_id  # athlete_code = qr_identifier
    
    athlete = Athlete(
        id=athlete_id,
        parent_id=current_user["id"],
        society_id=society_id,
        athlete_code=athlete_code,
        full_name=athlete_data.full_name,
        first_name=athlete_data.first_name,
        last_name=athlete_data.last_name,
        date_of_birth=dob,
        birth_place=athlete_data.birth_place,
        birth_province=athlete_data.birth_province,
        country_of_birth=athlete_data.country_of_birth or "Italia",
        gender=athlete_data.gender,
        is_minor=is_minor,
        fiscal_code=athlete_data.fiscal_code,
        email=athlete_data.email,
        address=athlete_data.address,
        city=athlete_data.city,
        postal_code=athlete_data.postal_code,
        province=athlete_data.province,
        phone_athlete=athlete_data.phone_athlete,
        phone_father=athlete_data.phone_father,
        phone_mother=athlete_data.phone_mother,
        tax_payer_name=athlete_data.tax_payer_name,
        tax_payer_last_name=athlete_data.tax_payer_last_name,
        tax_payer_first_name=athlete_data.tax_payer_first_name,
        tax_payer_fiscal_code=athlete_data.tax_payer_fiscal_code,
        team_id=athlete_data.team_id,
        team_id_2=athlete_data.team_id_2,
        qr_code=qr_code,
        qr_identifier=qr_id,
        trial_end_date=None,  # Set on first QR scan (see line ~11195)
        status=(minor_onboarding_status if is_minor else AthleteStatus.PENDING),  # Minors: trial starts at first QR scan
        privacy_accepted=privacy_accepted,
        privacy_accepted_date=datetime.utcnow() if privacy_accepted else None,
        consent_images_internal=consent_img_internal,
        consent_images_promo=consent_img_promo,
        consents=consents,
        consent_history=consent_history,
        data_password_hash=data_password_hash,
    )
    
    athlete_dict = athlete.dict()
    athlete_dict["created_at"] = datetime.utcnow()
    athlete_dict["already_registered"] = _already_reg
    # 🆕 Stagione corrente sull'atleta (evita "genitore invisibile" nella lista Genitori)
    if _current_season_create:
        athlete_dict["active_seasons"] = [_current_season_create]
    # 🆕 24/08/2026 — Consenso alla PROVA raccolto in fase di iscrizione (minori):
    # sostituisce la firma della "Dichiarazione di Prova" separata. Salviamo traccia
    # (timestamp/IP) e impostiamo trial_document_generated=True così l'onboarding
    # NON richiede una firma aggiuntiva successiva.
    if is_minor and getattr(athlete_data, 'trial_authorization', None):
        _ta_now = datetime.utcnow()
        athlete_dict["trial_document_generated"] = True
        athlete_dict["trial_authorized_at_registration"] = True
        athlete_dict["trial_document_signed_date"] = _ta_now.isoformat()
        athlete_dict["trial_document_signed_by"] = current_user["id"]
        athlete_dict["trial_document_signed_by_name"] = current_user.get("full_name", current_user.get("email", ""))
        _ta_consents = athlete_dict.get("consents") or {}
        _ta_consents["trial_authorization"] = {
            "value": True, "timestamp": _ta_now.isoformat(), "user_id": current_user["id"],
            "parent_id": current_user["id"], "child_id": athlete.id, "ip_address": client_ip,
            "document_version": document_version, "source": "registration",
        }
        athlete_dict["consents"] = _ta_consents
        _ta_hist = athlete_dict.get("consent_history") or []
        _ta_hist.append({
            "type": "trial_authorization", "action": "granted", "old_value": None, "new_value": True,
            "timestamp": _ta_now.isoformat(), "user_id": current_user["id"], "ip_address": client_ip,
            "source": "registration",
        })
        athlete_dict["consent_history"] = _ta_hist
    await db.athletes.insert_one(athlete_dict)
    # 🆕 Assicura la stagione corrente anche sul GENITORE che iscrive (così compare
    # subito nella cartella Genitori dell'admin, senza attendere il self-heal).
    if _current_season_create:
        await db.users.update_one({"id": current_user["id"]}, {"$addToSet": {"active_seasons": _current_season_create}})
    
    
    # Notifica admin per nuova iscrizione atleta minore
    parent_name = current_user.get("full_name", "")
    athlete_full_name = athlete_data.full_name or f"{athlete_data.last_name} {athlete_data.first_name}"
    society_id = current_user.get("society_id")
    if society_id:
        admins = await db.users.find({"society_id": society_id, "role": {"$in": ["admin", "viewer"]}, "status": "approved"}).to_list(100)
        for admin in admins:
            await db.notifications.insert_one({
                "id": str(uuid.uuid4()),
                "user_id": admin["id"],
                "type": "new_minor_athlete",
                "title": "Nuovo atleta minore iscritto",
                "message": f"{parent_name} ha iscritto {athlete_full_name} (minore).",
                "data": {"athlete_id": athlete.id, "athlete_name": athlete_full_name, "parent_name": parent_name},
                "read": False,
                "created_at": datetime.now(timezone.utc)
            })

    # === LINKING SECONDO GENITORE (solo salva email, richiesta creata quando B si registra) ===
    if athlete_data.second_parent_email:
        second_email = athlete_data.second_parent_email.lower().strip()
        update_fields = {"second_parent_email": second_email}
        # NON collegare automaticamente, anche se l'utente esiste già.
        # Creare una richiesta che il secondo genitore deve accettare.
        second_parent_user = await db.users.find_one({"email": second_email})
        if second_parent_user:
            # Il secondo genitore è già registrato: crea richiesta di collegamento
            link_request = {
                "id": str(uuid.uuid4()),
                "requester_id": current_user["id"],
                "requester_name": current_user.get("full_name", ""),
                "requester_email": current_user["email"],
                "athlete_id": athlete_id,
                "athlete_name": f"{athlete_data.last_name} {athlete_data.first_name}".upper(),
                "approver_id": second_parent_user["id"],
                "society_id": current_user.get("society_id", ""),
                "status": "pending",
                "source": "athlete_registration",
                "created_at": datetime.now(timezone.utc).isoformat(),
            }
            await db.parent_link_requests.insert_one(link_request)
            
            # Notifica al secondo genitore
            await db.notifications.insert_one({
                "id": str(uuid.uuid4()),
                "user_id": second_parent_user["id"],
                "type": "parent_link_request",
                "title": "Richiesta collegamento genitore",
                "message": f"{current_user.get('full_name', '')} ti ha indicato come secondo genitore di {athlete_data.last_name} {athlete_data.first_name}. Accetta o rifiuta dalla tua dashboard.",
                "read": False,
                "created_at": datetime.now(timezone.utc).isoformat(),
                "data": {
                    "athlete_id": athlete_id,
                    "athlete_name": f"{athlete_data.last_name} {athlete_data.first_name}".upper(),
                    "requester_name": current_user.get("full_name", ""),
                }
            })
        await db.athletes.update_one(
            {"id": athlete_id},
            {"$set": update_fields}
        )
    
    # Payment records are created when admin approves the athlete
    # This ensures payments are only created for approved athletes
    
    return athlete

# Endpoint per registrare atleti maggiorenni (solo Admin)
class AdultAthleteCreate(BaseModel):
    first_name: str
    last_name: str
    email: str  # Required for adult athletes (needed for account linking)
    fiscal_code: Optional[str] = None
    date_of_birth: Optional[str] = None  # YYYY-MM-DD, optional initially
    phone: Optional[str] = None
    team_id: Optional[str] = None  # Can assign team later
    athlete_type: str = "quota"  # "quota" o "compensated"


class MinorAthleteCreate(BaseModel):
    first_name: str
    last_name: str
    date_of_birth: str  # YYYY-MM-DD, required for minors
    fiscal_code: Optional[str] = None
    birth_place: Optional[str] = None
    birth_province: Optional[str] = None
    phone: Optional[str] = None
    team_id: Optional[str] = None
    parent_email: str  # Email genitore (obbligatorio per minori)
    second_parent_email: Optional[str] = None  # Email secondo genitore
    data_password: str  # Password protezione dati (obbligatoria per minori)
    gender: Optional[str] = None  # M or F

class DetachParentsRequest(BaseModel):
    athlete_email: str  # Email per il nuovo account indipendente dell'atleta
    athlete_password: str  # Password per il nuovo account

@api_router.post("/athletes/adult")
async def create_adult_athlete(data: AdultAthleteCreate, current_user = Depends(get_current_user)):
    """Registra un atleta maggiorenne direttamente dall'admin - form semplificato"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin possono registrare atleti maggiorenni")
    
    # 🐛 Fix "iscrizione fantasma": se l'email è fornita, deve essere valida
    if data.email and not is_valid_email(data.email):
        raise HTTPException(status_code=400, detail="Indirizzo email non valido. Controlla e riprova.")
    
    # Get admin's society_id
    admin_user = await db.users.find_one({"id": current_user["id"]})
    society_id = admin_user.get("society_id") if admin_user else None
    
    # Check if team exists (if provided)
    team = None
    if data.team_id:
        team = await db.teams.find_one({"id": data.team_id})
        if not team:
            raise HTTPException(status_code=404, detail="Squadra non trovata")
    
    # Parse date of birth if provided
    dob = None
    if data.date_of_birth:
        try:
            dob = datetime.fromisoformat(data.date_of_birth)
            age = (datetime.utcnow() - dob).days // 365
            if age < 18:
                raise HTTPException(status_code=400, detail="L'atleta deve essere maggiorenne (18+ anni)")
        except:
            pass
    
    # Check if athlete already exists by fiscal code (permanent identity)
    existing_athlete = await find_existing_athlete_by_fiscal_code(data.fiscal_code)
    if existing_athlete:
        # Reactivate existing athlete - keep same qr_identifier/athlete_code
        reactivate_data = {
            "society_id": society_id,
            "is_withdrawn": False,
            "withdrawn_date": None,
            "withdrawn_reason": None,
            "status": "active",
            "is_minor": False,
            "parents_detached": True,
        }
        if data.first_name:
            reactivate_data["first_name"] = data.first_name
            reactivate_data["last_name"] = data.last_name
            reactivate_data["full_name"] = f"{data.first_name} {data.last_name}"
        if data.email:
            reactivate_data["email"] = data.email.lower()
        if data.phone:
            reactivate_data["phone_athlete"] = data.phone
        if dob:
            reactivate_data["date_of_birth"] = dob
        if data.team_id:
            reactivate_data["team_id"] = data.team_id
        reactivate_data["athlete_type"] = data.athlete_type
        
        await db.athletes.update_one(
            {"id": existing_athlete["id"]},
            {"$set": reactivate_data}
        )
        
        updated = await db.athletes.find_one({"id": existing_athlete["id"]}, {"_id": 0})
        clean_mongo_doc(updated)
        return {"message": "Atleta riattivato con successo (codice fiscale già presente)", "athlete_id": existing_athlete["id"], "athlete_code": existing_athlete.get("athlete_code"), "reactivated": True}
    
    # Generate unique athlete code - new athlete
    # athlete_code is now the qr_identifier (12-char alphanumeric)
    
    # Create athlete
    athlete_id = str(ObjectId())
    
    # Generate new 12-char alphanumeric QR identifier for adult athletes
    # 🆕 v7.12 riusa codice se stesso CF già registrato
    qr_id = await resolve_athlete_code_for_cf(getattr(data, "fiscal_code", None))
    qr_code = generate_qr_code_from_identifier(qr_id)
    
    athlete_code = qr_id  # athlete_code = qr_identifier
    
    full_name = f"{data.first_name} {data.last_name}"
    
    athlete_dict = {
        "id": athlete_id,
        "parent_id": None,  # No parent for adult athletes
        "society_id": society_id,
        "athlete_code": athlete_code,
        "full_name": full_name,
        "first_name": data.first_name,
        "last_name": data.last_name,
        "date_of_birth": dob,
        "is_minor": False,
        "fiscal_code": data.fiscal_code,
        "email": data.email.lower() if data.email else None,
        "phone_athlete": data.phone,
        "team_id": data.team_id,
        "qr_code": qr_code,
        "qr_identifier": qr_id,
        "status": "active",  # Adult athletes are immediately active
        "athlete_type": data.athlete_type,  # "quota" or "compensated"
        "parents_detached": True,  # No parents for adult athletes
        "created_at": datetime.utcnow(),
        "privacy_accepted": True,  # Adult handles their own privacy
        "privacy_accepted_date": datetime.utcnow(),
    }
    
    await db.athletes.insert_one(athlete_dict)
    
    # If athlete pays quota, create payment records
    if data.athlete_type == "quota" and team:
        # Get team payment settings
        if team.get("total_amount", 0) > 0:
            # Use new installments format if available
            installments = team.get("installments", [])
            if installments:
                for i, inst in enumerate(installments):
                    payment = {
                        "id": str(ObjectId()),
                        "athlete_id": athlete_id,
                        "society_id": society_id,
                        "installment_number": i + 1,
                        "installment_name": inst.get("name", f"Rata {i + 1}"),
                        "amount": inst.get("amount", 0),
                        "due_date": inst.get("due_date"),
                        "paid": False,
                        "paid_date": None,
                        "created_at": datetime.utcnow(),
                    }
                    await db.payments.insert_one(payment)
    
    clean_mongo_doc(athlete_dict)
    return {"message": "Atleta registrato con successo", "athlete_id": athlete_id, "athlete_code": athlete_code}

@api_router.post("/athletes/minor")
async def create_minor_athlete(data: MinorAthleteCreate, current_user = Depends(get_current_user)):
    """Admin creates a minor athlete linked to a parent account"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin possono registrare atleti minorenni")
    
    admin_user = await db.users.find_one({"id": current_user["id"]})
    society_id = admin_user.get("society_id") if admin_user else None
    
    # Validate DOB - must be under 18
    try:
        dob = datetime.fromisoformat(data.date_of_birth)
        age = (datetime.utcnow() - dob).days // 365
        if age >= 18:
            raise HTTPException(status_code=400, detail="L'atleta ha 18+ anni. Usa il form per atleti maggiorenni.")
    except ValueError:
        raise HTTPException(status_code=400, detail="Data di nascita non valida")
    
    # Validate team
    team = None
    if data.team_id:
        team = await db.teams.find_one({"id": data.team_id})
        if not team:
            raise HTTPException(status_code=404, detail="Squadra non trovata")
    
    # Find or create parent account
    parent_email = data.parent_email.lower().strip()
    parent_user = await db.users.find_one({"email": parent_email})
    parent_id = None
    
    if parent_user:
        # Parent exists - link
        parent_id = parent_user["id"]
        # If parent doesn't have parent role, update it
        if parent_user.get("role") != UserRole.PARENT:
            # Don't change admin role
            if parent_user.get("role") not in [UserRole.ADMIN]:
                await db.users.update_one({"id": parent_id}, {"$set": {"role": UserRole.PARENT}})
    else:
        # Create a new parent user account with temporary password
        parent_id = str(ObjectId())
        temp_password = parent_email.split("@")[0] + "2026"
        parent_user_dict = {
            "id": parent_id,
            "email": parent_email,
            "password_hash": hash_password(temp_password),
            "role": UserRole.PARENT,
            "full_name": f"Genitore di {data.first_name} {data.last_name}",
            "first_name": "",
            "last_name": "",
            "society_id": society_id,
            "status": "approved",
            "created_at": datetime.utcnow(),
        }
        await db.users.insert_one(parent_user_dict)
    
    # Check for existing athlete by fiscal code
    if data.fiscal_code:
        existing_athlete = await find_existing_athlete_by_fiscal_code(data.fiscal_code)
        if existing_athlete:
            # Reactivate with minor settings
            reactivate_data = {
                "society_id": society_id,
                "is_withdrawn": False,
                "withdrawn_date": None,
                "withdrawn_reason": None,
                "status": "active",
                "is_minor": True,
                "parent_id": parent_id,
                "parents_detached": False,
                "first_name": data.first_name,
                "last_name": data.last_name,
                "full_name": f"{data.first_name} {data.last_name}",
                "date_of_birth": dob,
            }
            if data.data_password:
                reactivate_data["data_password_hash"] = hash_password(data.data_password)
            if data.team_id:
                reactivate_data["team_id"] = data.team_id
            if data.phone:
                reactivate_data["phone_athlete"] = data.phone
            
            # NON auto-linking per riattivazione - creare richiesta di approvazione
            if data.second_parent_email:
                sp_email = data.second_parent_email.lower().strip()
                reactivate_data["second_parent_email"] = sp_email
            
            await db.athletes.update_one({"id": existing_athlete["id"]}, {"$set": reactivate_data})
            return {"message": "Atleta minorenne riattivato", "athlete_id": existing_athlete["id"], "parent_id": parent_id, "reactivated": True}
    
    # Create new minor athlete
    athlete_id = str(ObjectId())
    # 🆕 v7.12 riusa codice se stesso CF già registrato
    qr_id = await resolve_athlete_code_for_cf(getattr(data, "fiscal_code", None))
    qr_code = generate_qr_code_from_identifier(qr_id)
    
    athlete_dict = {
        "id": athlete_id,
        "parent_id": parent_id,
        "society_id": society_id,
        "athlete_code": qr_id,
        "full_name": f"{data.first_name} {data.last_name}",
        "first_name": data.first_name,
        "last_name": data.last_name,
        "date_of_birth": dob,
        "is_minor": True,
        "fiscal_code": data.fiscal_code,
        "birth_place": data.birth_place,
        "birth_province": data.birth_province,
        "email": None,
        "phone_athlete": data.phone,
        "gender": data.gender,
        "team_id": data.team_id,
        "qr_code": qr_code,
        "qr_identifier": qr_id,
        "status": "active",
        "athlete_type": "quota",
        "parents_detached": False,
        "data_password_hash": hash_password(data.data_password),
        "second_parent_email": data.second_parent_email.lower().strip() if data.second_parent_email else None,
        "created_at": datetime.utcnow(),
        "privacy_accepted": False,
        "is_trial": False,
    }
    
    await db.athletes.insert_one(athlete_dict)
    
    # Se second_parent_email è fornita, crea richiesta di collegamento (MAI auto-link)
    if athlete_dict.get("second_parent_email"):
        second_parent = await db.users.find_one({
            "email": athlete_dict["second_parent_email"],
            "society_id": society_id,
            "role": UserRole.PARENT
        })
        if second_parent:
            # Crea richiesta pendente per il secondo genitore
            link_request = {
                "id": str(uuid.uuid4()),
                "requester_id": current_user["id"],
                "requester_name": current_user.get("full_name", ""),
                "requester_email": current_user.get("email", ""),
                "athlete_id": athlete_id,
                "athlete_name": data.full_name,
                "approver_id": second_parent["id"],
                "approver_name": second_parent.get("full_name", ""),
                "approver_email": second_parent.get("email", ""),
                "society_id": society_id,
                "status": "pending",
                "source": "athlete_creation",
                "created_at": datetime.now(timezone.utc).isoformat(),
            }
            await db.parent_link_requests.insert_one(link_request)
            
            # Crea notifica per il secondo genitore
            await db.notifications.insert_one({
                "id": str(uuid.uuid4()),
                "user_id": second_parent["id"],
                "type": "parent_link_request",
                "title": "Richiesta collegamento genitore",
                "message": f"{current_user.get('full_name', '')} ti ha indicato come secondo genitore di {data.full_name}. Accetta o rifiuta dalla tua dashboard.",
                "read": False,
                "created_at": datetime.now(timezone.utc).isoformat(),
                "data": {
                    "athlete_id": athlete_id,
                    "athlete_name": data.full_name,
                    "requester_name": current_user.get("full_name", ""),
                }
            })
    
    # Create payment records if team has installments
    if team and team.get("total_amount", 0) > 0:
        installments = team.get("installments", [])
        if installments:
            for i, inst in enumerate(installments):
                payment = {
                    "id": str(ObjectId()),
                    "athlete_id": athlete_id,
                    "society_id": society_id,
                    "installment_number": i + 1,
                    "installment_name": inst.get("name", f"Rata {i + 1}"),
                    "amount": inst.get("amount", 0),
                    "due_date": inst.get("due_date"),
                    "paid": False,
                    "paid_date": None,
                    "created_at": datetime.utcnow(),
                }
                await db.payments.insert_one(payment)
    
    clean_mongo_doc(athlete_dict)
    return {
        "message": "Atleta minorenne registrato con successo",
        "athlete_id": athlete_id,
        "athlete_code": qr_id,
        "parent_id": parent_id,
        "parent_existed": parent_user is not None if parent_user else False,
    }


# ============================================================================
# 🆕 26/07/2026 — REGISTRA UN MIO FIGLIO (Dual-role Staff → Genitore)
# ============================================================================

class MyChildCreate(BaseModel):
    first_name: str
    last_name: str
    date_of_birth: str  # YYYY-MM-DD
    fiscal_code: Optional[str] = None
    birth_place: Optional[str] = None
    birth_province: Optional[str] = None
    country_of_birth: Optional[str] = None
    gender: Optional[str] = None  # M or F
    phone: Optional[str] = None
    email: Optional[str] = None  # per atleta maggiorenne
    address: Optional[str] = None
    postal_code: Optional[str] = None
    city: Optional[str] = None
    province: Optional[str] = None
    team_id: Optional[str] = None
    data_password: Optional[str] = None  # obbligatoria se minore
    second_parent_email: Optional[str] = None
    parent_role: Optional[str] = "father"  # "father" | "mother" — dove salvare il tuo CF


@api_router.post("/athletes/register-my-child")
async def register_my_child(data: MyChildCreate, current_user = Depends(get_current_user)):
    """🆕 26/07/2026 — Endpoint dedicato al dual-role Staff/Genitore.
    Permette a qualsiasi utente autenticato di registrare un proprio figlio
    (minore o maggiorenne) collegandolo automaticamente come parent_id = current_user.
    - created_by = current_user (per CASO 1 auto-verifica futura)
    - Se già esiste un atleta con lo stesso CF nella società → 409 con hint
    - Se minore, data_password obbligatoria
    - Il CF del richiedente viene salvato in father_fiscal_code o mother_fiscal_code
      in base a `parent_role`, così le future verifiche automatiche lo trovano.
    """
    allowed_roles = {"parent", "admin", "viewer", "dirigente", "coordinatore", "coach", "collaboratore"}
    if current_user["role"] not in allowed_roles:
        raise HTTPException(status_code=403, detail="Non autorizzato")

    user_doc = await db.users.find_one({"id": current_user["id"]})
    if not user_doc:
        raise HTTPException(status_code=404, detail="Utente non trovato")
    society_id = user_doc.get("society_id")
    if not society_id:
        raise HTTPException(status_code=400, detail="Nessuna società associata al tuo account")

    # Parse & validate DOB
    try:
        dob = datetime.fromisoformat(data.date_of_birth)
    except ValueError:
        raise HTTPException(status_code=400, detail="Data di nascita non valida (usa YYYY-MM-DD)")
    age = (datetime.utcnow() - dob).days // 365
    is_minor = age < 18

    if is_minor and not data.data_password:
        raise HTTPException(status_code=400, detail="La password di protezione dati è obbligatoria per gli atleti minorenni")

    # Team check (opzionale)
    team = None
    if data.team_id:
        team = await db.teams.find_one({"id": data.team_id})
        if not team or team.get("society_id") != society_id:
            raise HTTPException(status_code=404, detail="Squadra non trovata")

    # Duplicate check by fiscal_code
    if data.fiscal_code:
        cf_clean = data.fiscal_code.strip().upper()
        existing = await db.athletes.find_one({
            "society_id": society_id,
            "fiscal_code": {"$regex": f"^{cf_clean}$", "$options": "i"},
            "is_withdrawn": {"$ne": True},
        })
        if existing:
            raise HTTPException(
                status_code=409,
                detail=f"Esiste già un atleta con questo CF nella società ({existing.get('first_name','')} {existing.get('last_name','')}). Usa 'Ho già un figlio iscritto' per collegarti.",
            )

    athlete_id = str(ObjectId())
    qr_id = await resolve_athlete_code_for_cf(data.fiscal_code)
    qr_code = generate_qr_code_from_identifier(qr_id)

    # Salva il CF del richiedente nel campo corretto in base a parent_role
    user_cf = (user_doc.get("fiscal_code") or "").strip().upper()
    parent_cf_field = "father_fiscal_code" if (data.parent_role or "father").lower() == "father" else "mother_fiscal_code"
    parent_email_field = "father_email" if parent_cf_field == "father_fiscal_code" else "mother_email"

    athlete_dict = {
        "id": athlete_id,
        "parent_id": current_user["id"],  # 🔗 auto-link
        "created_by": current_user["id"],  # 🔒 per future CASO 1 verifiche
        "society_id": society_id,
        "athlete_code": qr_id,
        "full_name": f"{data.first_name} {data.last_name}",
        "first_name": data.first_name,
        "last_name": data.last_name,
        "date_of_birth": dob,
        "is_minor": is_minor,
        "fiscal_code": data.fiscal_code.strip().upper() if data.fiscal_code else None,
        "birth_place": data.birth_place,
        "birth_province": data.birth_province,
        "country_of_birth": data.country_of_birth,
        "gender": data.gender,
        "email": (data.email or "").lower().strip() or None,
        "phone_athlete": data.phone,
        "address": data.address,
        "postal_code": data.postal_code,
        "city": data.city,
        "province": data.province,
        "team_id": data.team_id,
        "qr_code": qr_code,
        "qr_identifier": qr_id,
        "status": "active",
        "athlete_type": "quota",
        "parents_detached": False,
        "second_parent_email": data.second_parent_email.lower().strip() if data.second_parent_email else None,
        "created_at": datetime.utcnow(),
        "privacy_accepted": False,
        "is_trial": False,
    }
    # CF genitore corrente sulla scheda per audit + future verifiche
    if user_cf:
        athlete_dict[parent_cf_field] = user_cf
    if user_doc.get("email"):
        athlete_dict[parent_email_field] = (user_doc.get("email") or "").lower()
    if is_minor and data.data_password:
        athlete_dict["data_password_hash"] = hash_password(data.data_password)

    await db.athletes.insert_one(athlete_dict)

    # Audit log
    try:
        await db.parent_link_history.insert_one({
            "action": "self_register_child",
            "athlete_id": athlete_id,
            "user_id": current_user["id"],
            "user_email": current_user.get("email"),
            "user_role": current_user["role"],
            "slot": "primary",
            "verification": "self_created",
            "parent_role": data.parent_role or "father",
            "timestamp": datetime.now(timezone.utc),
        })
    except Exception:
        pass

    # Crea payments se team ha rate
    if team and team.get("total_amount", 0) > 0:
        installments = team.get("installments", [])
        for i, inst in enumerate(installments):
            await db.payments.insert_one({
                "id": str(ObjectId()),
                "athlete_id": athlete_id,
                "society_id": society_id,
                "installment_number": i + 1,
                "installment_name": inst.get("name", f"Rata {i + 1}"),
                "amount": inst.get("amount", 0),
                "due_date": inst.get("due_date"),
                "paid": False,
                "paid_date": None,
                "created_at": datetime.utcnow(),
            })

    # Notifica admin società
    try:
        admins = await db.users.find({
            "society_id": society_id, "role": {"$in": ["admin", "viewer"]}, "status": "approved"
        }).to_list(100)
        for adm in admins:
            await db.notifications.insert_one({
                "id": str(uuid.uuid4()),
                "user_id": adm["id"],
                "type": "new_minor_athlete" if is_minor else "new_adult_athlete",
                "title": "Nuova iscrizione (staff → genitore)",
                "message": f"{current_user.get('full_name','')} ha iscritto {data.first_name} {data.last_name} come proprio figlio.",
                "data": {"athlete_id": athlete_id, "athlete_name": f"{data.first_name} {data.last_name}"},
                "read": False,
                "created_at": datetime.now(timezone.utc),
            })
    except Exception:
        pass

    return {
        "message": "Figlio registrato e collegato al tuo account",
        "athlete_id": athlete_id,
        "athlete_code": qr_id,
        "is_minor": is_minor,
    }


@api_router.post("/athletes/{athlete_id}/detach-parents")
async def detach_parents(athlete_id: str, data: DetachParentsRequest, current_user = Depends(get_current_user)):
    """Detach parents from athlete who turned 18 - creates independent account"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin possono sganciare i genitori")
    
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    # Check age
    if athlete.get("date_of_birth"):
        age = (datetime.utcnow() - athlete["date_of_birth"]).days // 365
        if age < 18:
            raise HTTPException(status_code=400, detail=f"L'atleta ha {age} anni. Deve avere almeno 18 anni per lo sgancio genitori.")
    
    # Check if already detached
    if athlete.get("parents_detached"):
        raise HTTPException(status_code=400, detail="Genitori già sganciati per questo atleta")
    
    # Create independent user account for the athlete
    athlete_email = data.athlete_email.lower().strip()
    existing_user = await db.users.find_one({"email": athlete_email})
    if existing_user:
        raise HTTPException(status_code=400, detail="Email già in uso da un altro account")
    
    admin_user = await db.users.find_one({"id": current_user["id"]})
    society_id = admin_user.get("society_id") if admin_user else None
    
    user_id = str(ObjectId())
    user_dict = {
        "id": user_id,
        "email": athlete_email,
        "password_hash": hash_password(data.athlete_password),
        "role": "athlete",
        "full_name": athlete.get("full_name", ""),
        "first_name": athlete.get("first_name", ""),
        "last_name": athlete.get("last_name", ""),
        "society_id": society_id,
        "status": "approved",
        "athlete_id": athlete_id,
        "athlete_status": "active",
        "created_at": datetime.utcnow(),
    }
    await db.users.insert_one(user_dict)
    
    # Update athlete - detach parents, set email, mark as adult
    await db.athletes.update_one(
        {"id": athlete_id},
        {"$set": {
            "parents_detached": True,
            "parents_detached_date": datetime.utcnow().isoformat(),
            "is_minor": False,
            "email": athlete_email,
            "user_id": user_id,
        }}
    )
    
    return {
        "message": f"Genitori sganciati. Account indipendente creato per {athlete.get('full_name')}",
        "user_id": user_id,
        "email": athlete_email,
    }


@api_router.get("/athletes/my")
async def get_my_athletes(current_user = Depends(get_current_user)):
    # 🆕 17/07/2026 — Dual-role: se staff-user è linkato come parent_id di almeno un
    # atleta, ritorna SOLO i figli linkati (comportamento identico a parent). Serve per
    # la modalità genitore accessibile da admin/dirigente/coordinatore/coach.
    staff_roles = {UserRole.ADMIN, UserRole.VIEWER, "dirigente", UserRole.COORDINATORE, UserRole.COACH, "collaboratore"}
    is_staff = current_user["role"] in staff_roles

    # Prima verifica se lo user è genitore di qualche atleta
    linked_count = 0
    if is_staff:
        linked_count = await db.athletes.count_documents({
            "$or": [
                {"parent_id": current_user["id"]},
                {"second_parent_id": current_user["id"]},
            ],
            "society_id": current_user.get("society_id"),
        })

    if current_user["role"] == UserRole.PARENT or (is_staff and linked_count > 0):
        # Modalità genitore: solo figli linkati
        athletes = await db.athletes.find({
            "$or": [
                {"parent_id": current_user["id"]},
                {"second_parent_id": current_user["id"]}
            ]
        }).to_list(1000)
    elif current_user["role"] in [UserRole.ADMIN, UserRole.COACH]:
        # Admin/Coach senza figli linkati → visione generale (retrocompatibile)
        _sid = current_user.get("society_id")
        _q = {"society_id": _sid} if _sid else {}
        athletes = await db.athletes.find(_q).to_list(1000)
    else:
        raise HTTPException(status_code=403, detail="Accesso negato")
    
    clean_mongo_docs(athletes)
    
    # Arricchimento "altro genitore" per parent role E per staff-user in modalità genitore
    if current_user["role"] == UserRole.PARENT or (is_staff and linked_count > 0):
        for athlete in athletes:
            other_parent_id = None
            if athlete.get("parent_id") == current_user["id"]:
                other_parent_id = athlete.get("second_parent_id")
                other_parent_email = athlete.get("second_parent_email")
            elif athlete.get("second_parent_id") == current_user["id"]:
                other_parent_id = athlete.get("parent_id")
                other_parent_email = None
            else:
                other_parent_email = athlete.get("second_parent_email")
            
            if other_parent_id:
                other_parent = await db.users.find_one({"id": other_parent_id}, {"_id": 0, "full_name": 1, "email": 1})
                if other_parent:
                    athlete["other_parent_name"] = other_parent.get("full_name", "")
                    athlete["other_parent_email"] = other_parent.get("email", "")
            elif other_parent_email:
                other_parent = await db.users.find_one({"email": other_parent_email}, {"_id": 0, "full_name": 1, "email": 1})
                if other_parent:
                    athlete["other_parent_name"] = other_parent.get("full_name", "")
                    athlete["other_parent_email"] = other_parent.get("email", "")
                else:
                    athlete["other_parent_email"] = other_parent_email
    
    return athletes

# Athlete Compensation endpoints
@api_router.get("/athletes/{athlete_id}/compensation")
async def get_athlete_compensation(athlete_id: str, current_user = Depends(get_current_user)):
    """Get compensation settings for an athlete"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può vedere i compensi")
    
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    # Check if athlete is compensated type
    if athlete.get("athlete_type") != "compensated":
        raise HTTPException(status_code=400, detail="Questo atleta non è di tipo 'compensato'")
    
    comp = await db.athlete_compensations.find_one({"athlete_id": athlete_id})
    if not comp:
        return None
    
    clean_mongo_doc(comp)
    return comp

@api_router.post("/athletes/{athlete_id}/compensation")
async def set_athlete_compensation(athlete_id: str, data: dict, current_user = Depends(get_current_user)):
    """Set or update compensation for an athlete"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può impostare i compensi")
    
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    # 🔞 Atleta Pro = solo maggiorenni. I minorenni non possono ricevere compensi.
    try:
        bd = athlete.get("birth_date")
        if bd:
            from datetime import date as _date
            if isinstance(bd, str):
                bd_date = _date.fromisoformat(bd.split("T")[0])
            elif hasattr(bd, "date"):
                bd_date = bd.date()
            else:
                bd_date = bd
            today = _date.today()
            age = today.year - bd_date.year - ((today.month, today.day) < (bd_date.month, bd_date.day))
            if age < 18:
                raise HTTPException(
                    status_code=400,
                    detail="Impossibile assegnare un compenso a un atleta minorenne. Atleta Pro disponibile solo dai 18 anni.",
                )
    except HTTPException:
        raise
    except Exception as e:
        logging.warning(f"[set_athlete_compensation] age check failed for {athlete_id}: {e}")
    
    # Ensure athlete is marked as compensated
    if athlete.get("athlete_type") != "compensated":
        await db.athletes.update_one(
            {"id": athlete_id},
            {"$set": {"athlete_type": "compensated"}}
        )
    
    monthly_amount = data.get("monthly_amount", 0)
    start_date = data.get("start_date")
    end_date = data.get("end_date")
    
    # Parse dates if provided
    if start_date and isinstance(start_date, str):
        try:
            start_date = datetime.fromisoformat(start_date.replace('Z', '+00:00'))
        except:
            start_date = None
    
    if end_date and isinstance(end_date, str):
        try:
            end_date = datetime.fromisoformat(end_date.replace('Z', '+00:00'))
        except:
            end_date = None
    
    comp_data = {
        "athlete_id": athlete_id,
        "society_id": athlete.get("society_id"),
        "monthly_amount": monthly_amount,
        "start_date": start_date,
        "end_date": end_date,
        "updated_at": datetime.utcnow(),
    }
    
    # Upsert compensation
    result = await db.athlete_compensations.update_one(
        {"athlete_id": athlete_id},
        {"$set": comp_data},
        upsert=True
    )
    
    return {"message": "Compenso aggiornato con successo"}

@api_router.patch("/athletes/{athlete_id}/compensation/settings")
async def update_athlete_compensation_settings(athlete_id: str, data: dict, current_user = Depends(get_current_user)):
    """Update full compensation settings for an athlete (like coaches)"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può modificare i compensi")
    
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    update_data = {}
    
    # 🛡️ 27/06/2026 — Protezione anti-azzeramento accidentale:
    # Se il client invia esplicitamente monthly_compensation=0 (es. salvataggio
    # con campo vuoto dalla modal "Modifica Configurazione" di prime-squadre),
    # rifiutiamo l'update per evitare di azzerare un compenso esistente per sbaglio.
    # L'admin può azzerare solo passando "force_zero": true.
    if "monthly_compensation" in data:
        new_val = data.get("monthly_compensation")
        try:
            new_val_num = float(new_val) if new_val is not None and new_val != "" else 0
        except (ValueError, TypeError):
            new_val_num = 0
        current_val = float(athlete.get("monthly_compensation") or 0)
        if new_val_num <= 0 and current_val > 0 and not data.get("force_zero"):
            raise HTTPException(
                status_code=400,
                detail=f"Impossibile salvare con Compenso Mensile vuoto/zero: il valore attuale è €{current_val:.2f}. Inserisci un importo valido oppure usa l'opzione 'Rimuovi compenso' se vuoi davvero azzerare.",
            )
        update_data["monthly_compensation"] = new_val_num
    
    # Other annual compensation (prior)
    if "other_annual_compensation" in data:
        update_data["other_annual_compensation"] = data["other_annual_compensation"]
    
    if "prior_compensation" in data:
        update_data["prior_compensation"] = data["prior_compensation"]
    
    # Contract dates
    if "contract_start_date" in data:
        val = data["contract_start_date"]
        if val and isinstance(val, str):
            try:
                update_data["contract_start_date"] = datetime.fromisoformat(val.replace('Z', '+00:00')).isoformat()
            except:
                update_data["contract_start_date"] = val
        else:
            update_data["contract_start_date"] = val
    
    if "contract_end_date" in data:
        val = data["contract_end_date"]
        if val and isinstance(val, str):
            try:
                update_data["contract_end_date"] = datetime.fromisoformat(val.replace('Z', '+00:00')).isoformat()
            except:
                update_data["contract_end_date"] = val
        else:
            update_data["contract_end_date"] = val
    
    # Bank info
    if "iban" in data:
        update_data["iban"] = data["iban"]
    if "iban_holder_first_name" in data:
        # Convert to uppercase
        val = data["iban_holder_first_name"]
        update_data["iban_holder_first_name"] = val.upper() if val else None
    if "iban_holder_last_name" in data:
        # Convert to uppercase
        val = data["iban_holder_last_name"]
        update_data["iban_holder_last_name"] = val.upper() if val else None
    if "bank_name" in data:
        update_data["bank_name"] = data["bank_name"]
    
    if update_data:
        # 🆕 Se cambiano compenso mensile o periodo contratto, l'accettazione (B)
        # decade: l'atleta deve ri-accettare perché variano compensi e durata.
        def _ymd(v):
            if not v:
                return None
            s = v.isoformat() if hasattr(v, "isoformat") else str(v)
            return s[:10]
        reasons = []
        if "monthly_compensation" in update_data and float(update_data["monthly_compensation"] or 0) != float(athlete.get("monthly_compensation") or 0):
            reasons.append("compenso mensile")
        for _cf in ("contract_start_date", "contract_end_date"):
            if _cf in update_data and _ymd(update_data[_cf]) != _ymd(athlete.get(_cf)):
                reasons.append("periodo contratto")
                break
        if reasons and athlete.get("compensation_accepted"):
            update_data["compensation_accepted"] = False
            update_data["compensation_reaccept_reason"] = "Variazione " + " e ".join(reasons)
            # tieni allineato anche l'eventuale account utente collegato
            await db.users.update_many({"athlete_id": athlete_id}, {"$set": {"compensation_accepted": False}})
        await db.athletes.update_one({"id": athlete_id}, {"$set": update_data})
    
    return {"message": "Impostazioni compenso aggiornate"}

# ─────────────────────────────────────────────────────────────────────────────
# 🩺 10/07/2026 (v7.15) — Helper condiviso per normalizzazione record compensi.
# Gestisce record legacy (`month` string italiano, `signed`/`amount` field names)
# convertendoli al formato moderno (`month` int, `receipt_signed`/`amount_gross`).
# Usato da athlete/coach/dirigente/collaboratore compensations endpoints.
# ─────────────────────────────────────────────────────────────────────────────

_COMP_MONTH_NAME_TO_INT = {
    "gennaio": 1, "febbraio": 2, "marzo": 3, "aprile": 4, "maggio": 5, "giugno": 6,
    "luglio": 7, "agosto": 8, "settembre": 9, "ottobre": 10, "novembre": 11, "dicembre": 12,
}
_COMP_MONTH_INT_TO_NAME = {v: k.capitalize() for k, v in _COMP_MONTH_NAME_TO_INT.items()}


def _normalize_receipt_record_inplace(r: dict) -> dict:
    """Normalizza on-the-fly un singolo record compensi.
    Non tocca il DB. Aggiunge/completa i campi mancanti sull'oggetto passato."""
    _m_raw = r.get("month")
    _m_int = None
    if isinstance(_m_raw, int):
        _m_int = _m_raw
    elif isinstance(_m_raw, str):
        _m_int = _COMP_MONTH_NAME_TO_INT.get(_m_raw.strip().lower())
        if _m_int is None:
            try:
                _m_int = int(_m_raw)
            except (ValueError, TypeError):
                _m_int = None
    _rs = r.get("receipt_signed")
    if _rs is None:
        _rs = bool(r.get("signed"))
    _rs_date = r.get("receipt_signed_date") or r.get("signed_date")
    _amount_gross = r.get("amount_gross")
    if _amount_gross is None:
        _amount_gross = r.get("amount")
    _amount = r.get("amount")
    if _amount is None:
        _amount = _amount_gross
    r["month"] = _m_int if _m_int is not None else _m_raw
    if _m_int is not None and not r.get("month_name"):
        r["month_name"] = _COMP_MONTH_INT_TO_NAME.get(_m_int)
    r["receipt_signed"] = _rs
    r["receipt_signed_date"] = _rs_date
    r["amount_gross"] = _amount_gross
    r["amount"] = _amount
    return r


async def _normalize_legacy_records_in_db(collection_name: str, key: str, user_id: str) -> list:
    """Applica la normalizzazione PERMANENTE ai record legacy nel DB.
    Restituisce la lista delle modifiche fatte (per audit/report).
    Idempotente: rieseguibile senza effetti collaterali."""
    coll = db[collection_name]
    updated: list = []
    async for r in coll.find({key: user_id}, {"_id": 0}):
        changes: dict = {}
        _m_raw = r.get("month")
        if isinstance(_m_raw, str):
            _m_int = _COMP_MONTH_NAME_TO_INT.get(_m_raw.strip().lower())
            if _m_int is None:
                try:
                    _m_int = int(_m_raw)
                except (ValueError, TypeError):
                    _m_int = None
            if _m_int is not None:
                changes["month"] = _m_int
                if not r.get("month_name"):
                    changes["month_name"] = _COMP_MONTH_INT_TO_NAME.get(_m_int)
        if r.get("receipt_signed") is None and r.get("signed") is not None:
            changes["receipt_signed"] = bool(r.get("signed"))
        if r.get("signed") is None and r.get("receipt_signed") is not None:
            changes["signed"] = bool(r.get("receipt_signed"))
        if not r.get("receipt_signed_date") and r.get("signed_date"):
            changes["receipt_signed_date"] = r.get("signed_date")
        if not r.get("signed_date") and r.get("receipt_signed_date"):
            changes["signed_date"] = r.get("receipt_signed_date")
        if r.get("amount_gross") is None and r.get("amount") is not None:
            changes["amount_gross"] = r.get("amount")
        if r.get("amount") is None and r.get("amount_gross") is not None:
            changes["amount"] = r.get("amount_gross")

        if changes:
            await coll.update_one(
                {key: user_id, "year": r.get("year"), "month": r.get("month")},
                {"$set": changes},
            )
            updated.append({
                "year": r.get("year"),
                "month_before": _m_raw,
                "month_after": changes.get("month", _m_raw),
                "fields_updated": list(changes.keys()),
            })
    return updated


def _diagnostic_compensation_records(records: list) -> dict:
    """Calcola i counters di consistenza per un elenco di record raw.
    Restituisce metriche utili al pannello 'Diagnostica quietanze'."""
    total_signed = 0.0
    signed_count = 0
    legacy_month_strings = 0
    missing_receipt_signed = 0
    for r in records:
        is_signed = r.get("receipt_signed") or r.get("signed") or False
        if is_signed:
            signed_count += 1
            total_signed += float(r.get("amount_gross") or r.get("amount") or 0)
        _m = r.get("month")
        if isinstance(_m, str) and not _m.isdigit():
            legacy_month_strings += 1
        if r.get("receipt_signed") is None and r.get("signed") is not None:
            missing_receipt_signed += 1
    return {
        "records": len(records),
        "signed_records": signed_count,
        "signed_total_eur": round(total_signed, 2),
        "legacy_month_strings": legacy_month_strings,
        "missing_receipt_signed_field": missing_receipt_signed,
        "needs_normalization": legacy_month_strings > 0 or missing_receipt_signed > 0,
    }


@api_router.get("/athletes/{athlete_id}/compensation/receipts")
async def get_athlete_compensation_receipts(athlete_id: str, current_user = Depends(get_current_user)):
    """Get signed receipts for an athlete - admin or the athlete themselves.

    🐛 10/07/2026 (v7.15) — HOTFIX "Già Percepito €X vs. 0 mesi firmati".
    Il record legacy salvava `month` come STRING italiana ("Giugno"), mentre
    calendario/aggregazioni moderni usano INT 1-12. Normalizziamo qui, così:
      • il widget "Già Percepito" continua a sommare tutti i `receipt_signed`
      • il calendario Gestione Quietanze trova il record per mese
    Idem per i campi `receipt_signed`/`amount_gross`/`receipt_signed_date`
    (già normalizzati lato frontend, ma meglio farlo alla fonte).
    """
    # Allow admin or the athlete viewing their own receipts
    if current_user["role"] == "athlete":
        # Check if the athlete is viewing their own receipts
        if current_user.get("athlete_id") != athlete_id and current_user["id"] != athlete_id:
            raise HTTPException(status_code=403, detail="Puoi vedere solo le tue quietanze")
    elif current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Non autorizzato")

    receipts = await db.athlete_compensation_receipts.find({"athlete_id": athlete_id}).to_list(100)
    clean_mongo_docs(receipts)
    return [_normalize_receipt_record_inplace(r) for r in receipts]


# 🆕 27/02/2026 — Reset Quietanze: cancella TUTTE le quietanze di un atleta (e Coach linked se dual-role)
# Utile per dati di test o per ricominciare da zero quando admin/user vedono dati incoerenti.
@api_router.post("/admin/athletes/{athlete_id}/compensation/normalize-legacy")
async def admin_normalize_athlete_receipts(athlete_id: str, current_user = Depends(get_current_user)):
    """🛠️ 10/07/2026 (v7.15) — Normalizza permanentemente i record legacy in DB.

    Segnalazione utente (BRETELLI PAOLA): 'Già Percepito €750' ma nessun mese
    firmato nel calendario. Root cause: record DB con `month: "Giugno"` (string
    legacy) invece di `month: 6` (int), e/o solo `signed: True` invece di
    `receipt_signed: True`. Il widget somma tutto (senza filtro mese), il
    calendario cerca per int → mismatch.

    Questo endpoint:
      • Converte `month` string italiano → int 1-12
      • Duplica `signed`→`receipt_signed`, `signed_date`→`receipt_signed_date`,
        `amount`→`amount_gross` (e viceversa) per garantire idempotenza futura
      • Restituisce report dei record aggiornati

    Admin-only. Idempotente. Non elimina nulla."""
    if current_user.get("role") != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")

    athlete = await db.athletes.find_one({"id": athlete_id}, {"_id": 0, "id": 1, "society_id": 1, "full_name": 1})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    if athlete.get("society_id") != current_user.get("society_id"):
        raise HTTPException(status_code=403, detail="Atleta di altra società")

    updated = await _normalize_legacy_records_in_db("athlete_compensation_receipts", "athlete_id", athlete_id)

    return {
        "ok": True,
        "athlete_id": athlete_id,
        "athlete_name": athlete.get("full_name", ""),
        "records_updated": len(updated),
        "updates": updated,
    }


@api_router.get("/admin/athletes/{athlete_id}/compensation/receipts/diagnostic")
async def admin_diagnostic_athlete_receipts(athlete_id: str, current_user = Depends(get_current_user)):
    """🩺 10/07/2026 (v7.15) — Report raw dei record `athlete_compensation_receipts`
    per un atleta, senza normalizzazione. Utile per identificare discrepanze
    tra widget aggregati (es. Già Percepito) e vista calendario mensile.
    Restituisce ogni record con TUTTI i campi legacy + moderni.
    Admin-only. Read-only."""
    if current_user.get("role") != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")
    athlete = await db.athletes.find_one({"id": athlete_id}, {"_id": 0, "id": 1, "society_id": 1, "full_name": 1})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    if athlete.get("society_id") != current_user.get("society_id"):
        raise HTTPException(status_code=403, detail="Atleta di altra società")

    receipts = await db.athlete_compensation_receipts.find({"athlete_id": athlete_id}).to_list(200)
    clean_mongo_docs(receipts)

    return {
        "athlete_id": athlete_id,
        "athlete_name": athlete.get("full_name", ""),
        "totals": _diagnostic_compensation_records(receipts),
        "records": receipts,
    }


# ─────────────────────────────────────────────────────────────────────────────
# 🩺 10/07/2026 (v7.15) — Diagnostica + normalize-legacy per Coach/Dirigente/Collaboratore.
# Stesso pattern usato per gli atleti PRO: identifica record con `month` stringa
# italiana ("Giugno") o campi legacy `signed`/`amount` e li normalizza al formato
# moderno. Endpoints admin-only, idempotenti, non distruttivi.
# ─────────────────────────────────────────────────────────────────────────────

async def _admin_check_user_and_society(user_id: str, expected_roles: list, current_user: dict) -> dict:
    """Verifica che l'utente esista, sia del ruolo giusto e appartenga alla società admin."""
    if current_user.get("role") != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")
    user = await db.users.find_one({"id": user_id}, {"_id": 0, "id": 1, "society_id": 1, "full_name": 1, "role": 1})
    if not user:
        raise HTTPException(status_code=404, detail="Utente non trovato")
    if user.get("role") not in expected_roles:
        raise HTTPException(status_code=400, detail=f"Ruolo non compatibile: {user.get('role')}")
    if user.get("society_id") != current_user.get("society_id"):
        raise HTTPException(status_code=403, detail="Utente di altra società")
    return user


