@api_router.delete("/admin/athletes/{athlete_id}/compensation/reset-all")
async def admin_reset_athlete_compensations(athlete_id: str, current_user = Depends(get_current_user)):
    """ADMIN ONLY — Cancella TUTTE le quietanze, ricevute firmate, compensi coach linked,
    compensi esterni e autocertificazioni soglie di un atleta. NON ELIMINA l'anagrafica.
    Da usare con cautela: operazione irreversibile."""
    if current_user.get("role") != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")

    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")

    # Multi-tenancy: stesso society_id
    if athlete.get("society_id") != current_user.get("society_id"):
        raise HTTPException(status_code=403, detail="Atleta di altra società")

    result = {"athlete_name": athlete.get("full_name", ""), "athlete_id": athlete_id, "deleted": {}}

    r1 = await db.athlete_compensation_receipts.delete_many({"athlete_id": athlete_id})
    result["deleted"]["athlete_compensation_receipts"] = r1.deleted_count

    # Coach linked via CF / email
    coach_user = None
    try:
        coach_user = await _find_linked_compensated_user_for_athlete(athlete)
    except Exception:
        coach_user = None

    coach_count = 0
    if coach_user:
        rc = await db.coach_compensations.delete_many({"coach_id": coach_user["id"]})
        coach_count += rc.deleted_count
    rcb = await db.coach_compensations.delete_many({"linked_athlete_id": athlete_id})
    coach_count += rcb.deleted_count
    result["deleted"]["coach_compensations"] = coach_count

    r3 = await db.signed_documents.delete_many({
        "athlete_id": athlete_id,
        "document_type": {"$in": ["compensation_receipt", "compensation_receipt_split"]},
    })
    result["deleted"]["signed_documents"] = r3.deleted_count

    r4 = await db.external_compensations.delete_many({"athlete_id": athlete_id})
    result["deleted"]["external_compensations"] = r4.deleted_count

    try:
        r5 = await db.threshold_declarations.delete_many({"athlete_id": athlete_id})
        result["deleted"]["threshold_declarations"] = r5.deleted_count
    except Exception:
        result["deleted"]["threshold_declarations"] = 0

    logger.warning(f"[ADMIN-RESET] Quietanze atleta {athlete_id} ({athlete.get('full_name')}) cancellate da admin {current_user.get('id')}. Result: {result['deleted']}")
    return {"message": "Tutte le quietanze sono state cancellate", **result}

@api_router.post("/athletes/{athlete_id}/compensation/receipt")
async def sign_athlete_compensation_receipt(athlete_id: str, data: dict, current_user = Depends(get_current_user)):
    """Sign or unsign a monthly receipt for an athlete"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può firmare le quietanze")
    
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    month = data.get("month")
    year = data.get("year")
    signed = data.get("signed", True)
    
    if not month or not year:
        raise HTTPException(status_code=400, detail="Mese e anno sono obbligatori")
    
    receipt_data = {
        "athlete_id": athlete_id,
        "society_id": athlete.get("society_id"),
        "month": month,
        "year": year,
        "signed": signed,
        "signed_date": datetime.utcnow() if signed else None,
        "amount": athlete.get("monthly_compensation", 0),
        "updated_at": datetime.utcnow(),
    }
    
    # Upsert receipt
    await db.athlete_compensation_receipts.update_one(
        {"athlete_id": athlete_id, "month": month, "year": year},
        {"$set": receipt_data},
        upsert=True
    )
    
    return {"message": "Quietanza aggiornata"}


# ============================================================================
# 🆕 27/07/2026 — DICHIARAZIONE PREGRESSO CON FIRMA DIGITALE (Riforma Sport)
# ----------------------------------------------------------------------------
# L'utente (atleta/coach/dirigente/collaboratore) prima di poter accettare un
# compenso deve dichiarare quanto ha percepito da ALTRE ASD/SSD nell'anno
# fiscale corrente, firmando digitalmente. Solo l'admin può modificare dopo.
# Reset automatico al season rollover.
# ============================================================================
FISCAL_YEAR_FIELDS = [
    "other_annual_compensation",           # importo dichiarato (usato dal calcolo soglie)
    "other_annual_compensation_signed",    # True quando l'utente ha firmato
    "other_annual_compensation_signature", # base64 signature image
    "other_annual_compensation_signed_at", # datetime firma
    "other_annual_compensation_signed_year", # anno fiscale della firma
    "other_annual_compensation_ip",
    "other_annual_compensation_user_agent",
    "other_annual_compensation_admin_history",  # log modifiche admin
]

def _current_fiscal_year() -> int:
    """Anno fiscale corrente (Riforma Sport = anno solare gen-dic)."""
    return datetime.utcnow().year


async def _get_user_or_athlete(user_id: str) -> tuple:
    """Restituisce (doc, collection_name). Cerca prima in users poi in athletes."""
    doc = await db.users.find_one({"id": user_id})
    if doc:
        return doc, "users"
    doc = await db.athletes.find_one({"id": user_id})
    if doc:
        return doc, "athletes"
    return None, None


# 🆕 28/09/2026 — Il pregresso può essere firmato dall'atleta sul record `users`
# ma l'admin lo legge dal record `athletes` (adminUserId = athlete.id). Per evitare
# il disallineamento ("Non firmato" lato admin), sincronizziamo i due record collegati
# (user.athlete_id ↔ athlete.id), come già fatto per i Dati Bancari.
async def _get_linked_prior_comp_docs(user_id: str) -> list:
    """Ritorna [(doc, collection), ...] dei record collegati: users + athletes.
    🆕 Include anche l'altro account del DUAL-ROLE (Atleta PRO ↔ Coach/Dirigente/
    Collaboratore, alias `email#coach` / stesso CF): la posizione contributiva è
    UNA per persona, quindi pregresso e dichiarazione previdenziale sono condivisi."""
    out = []
    seen = set()

    def _add(doc, coll):
        if doc and doc.get("id") and doc["id"] not in seen:
            seen.add(doc["id"])
            out.append((doc, coll))

    u = await db.users.find_one({"id": user_id})
    if u:
        _add(u, db.users)
        aid = u.get("athlete_id")
        if aid:
            _add(await db.athletes.find_one({"id": aid}), db.athletes)
    else:
        a = await db.athletes.find_one({"id": user_id})
        if a:
            _add(a, db.athletes)
            _add(await db.users.find_one({"athlete_id": user_id}), db.users)

    # Dual-role: dall'atleta PRO al suo account coach/dirigente/collaboratore e viceversa
    for doc, coll in list(out):
        if coll.name == "athletes" and doc.get("is_compensated"):
            linked_user = await _find_linked_compensated_user_for_athlete(doc)
            if linked_user:
                _add(linked_user, db.users)
        elif coll.name == "users" and doc.get("role") in ("coach", "dirigente", "viewer", "collaboratore"):
            linked_ath = await _find_linked_athlete_pro_for_user(doc["id"])
            if linked_ath:
                _add(linked_ath, db.athletes)
                _add(await db.users.find_one({"athlete_id": linked_ath["id"]}), db.users)
    return out


async def _sync_prior_compensation(user_id: str, update_dict: dict) -> None:
    """Applica update_dict a TUTTI i record collegati (users + athletes)."""
    for doc, coll in await _get_linked_prior_comp_docs(user_id):
        await coll.update_one({"id": doc["id"]}, {"$set": update_dict})


async def _resolve_prior_comp_doc(user_id: str) -> Optional[dict]:
    """Tra i record collegati, restituisce quello che rappresenta lo stato di firma
    più valido (firmato anno corrente > firmato > primo disponibile)."""
    docs = await _get_linked_prior_comp_docs(user_id)
    if not docs:
        return None
    cy = _current_fiscal_year()
    for doc, _ in docs:
        if doc.get("other_annual_compensation_signed") and doc.get("other_annual_compensation_signed_year") == cy:
            return doc
    for doc, _ in docs:
        if doc.get("other_annual_compensation_signed"):
            return doc
    return docs[0][0]


def _prior_compensation_status_from_doc(doc: dict) -> dict:
    """Estrae lo stato della dichiarazione pregresso da un doc user/athlete."""
    signed = bool(doc.get("other_annual_compensation_signed") or False)
    signed_year = doc.get("other_annual_compensation_signed_year")
    current_year = _current_fiscal_year()
    # Se firma per anno fiscale diverso da corrente → considerata non valida
    valid_signature = signed and signed_year == current_year
    return {
        "signed": valid_signature,
        "amount": float(doc.get("other_annual_compensation") or 0),
        "signed_at": (doc.get("other_annual_compensation_signed_at").isoformat()
                      if isinstance(doc.get("other_annual_compensation_signed_at"), datetime)
                      else doc.get("other_annual_compensation_signed_at")),
        "signed_year": signed_year,
        "current_fiscal_year": current_year,
        "has_signature_image": bool(doc.get("other_annual_compensation_signature")),
        "requires_renewal": signed and signed_year != current_year,
        "versions": len(doc.get("other_annual_compensation_user_history") or []) + (1 if signed else 0),
    }


async def _require_pension_declared(ids: list) -> None:
    """🆕 Dichiarazione posizione previdenziale obbligatoria prima di completare
    l'accettazione dell'accordo (vedi routes/pension_declarations.py)."""
    from routes.pension_declarations import require_pension_declared
    await require_pension_declared(ids)


async def _require_prior_compensation_declared(user_id: str) -> None:
    """Raise HTTPException 403 se l'utente non ha dichiarato il pregresso
    per l'anno fiscale corrente. Da chiamare prima di ogni accept-compensation."""
    doc, _ = await _get_user_or_athlete(user_id)
    if not doc:
        raise HTTPException(status_code=404, detail="Utente non trovato")
    best = await _resolve_prior_comp_doc(user_id) or doc
    status = _prior_compensation_status_from_doc(best)
    if not status["signed"]:
        raise HTTPException(
            status_code=403,
            detail={
                "code": "PRIOR_COMPENSATION_REQUIRED",
                "message": "Devi dichiarare i compensi già percepiti da altre società prima di accettare questo compenso.",
                "current_fiscal_year": status["current_fiscal_year"],
                "requires_renewal": status["requires_renewal"],
            }
        )


@api_router.get("/me/prior-compensation/status")
async def get_my_prior_compensation_status(current_user = Depends(get_current_user)):
    """Ritorna lo stato della dichiarazione pregresso dell'utente corrente."""
    doc, _ = await _get_user_or_athlete(current_user["id"])
    if not doc:
        raise HTTPException(status_code=404, detail="Utente non trovato")
    best = await _resolve_prior_comp_doc(current_user["id"]) or doc
    return _prior_compensation_status_from_doc(best)


class PriorCompensationDeclareRequest(BaseModel):
    amount: float = Field(..., ge=0, description="Importo pregresso dichiarato (€, >= 0)")
    signature_base64: str = Field(..., min_length=50, description="Firma digitale (base64 PNG)")


@api_router.post("/me/prior-compensation/declare")
async def declare_my_prior_compensation(
    data: PriorCompensationDeclareRequest,
    request: Request,
    current_user = Depends(get_current_user),
):
    """L'utente firma la dichiarazione di pregresso per l'anno fiscale corrente.
    Solo l'utente stesso può farlo. Se già firmato per l'anno corrente, non permette
    di rifirmare (deve passare da admin per modifiche)."""
    doc, coll_name = await _get_user_or_athlete(current_user["id"])
    if not doc:
        raise HTTPException(status_code=404, detail="Utente non trovato")
    
    current_year = _current_fiscal_year()
    existing_signed = bool(doc.get("other_annual_compensation_signed"))
    existing_year = doc.get("other_annual_compensation_signed_year")
    # 🆕 Il lavoratore può VARIARE il pregresso già firmato: la nuova dichiarazione
    # sostituisce la precedente, che resta tracciata nello storico (append-only).
    user_history = list(doc.get("other_annual_compensation_user_history") or [])
    is_variation = existing_signed and existing_year == current_year
    if existing_signed:
        user_history.append({
            "amount": float(doc.get("other_annual_compensation") or 0),
            "signed_at": (doc.get("other_annual_compensation_signed_at").isoformat()
                          if isinstance(doc.get("other_annual_compensation_signed_at"), datetime)
                          else doc.get("other_annual_compensation_signed_at")),
            "signed_year": existing_year,
            "signature_base64": doc.get("other_annual_compensation_signature"),
            "ip": doc.get("other_annual_compensation_ip"),
            "user_agent": doc.get("other_annual_compensation_user_agent"),
            "replaced_at": datetime.utcnow().isoformat(),
        })
    
    # Metadati richiesta (per compliance)
    client_host = request.client.host if request.client else None
    forwarded_for = request.headers.get("x-forwarded-for", "")
    ip_addr = (forwarded_for.split(",")[0].strip() if forwarded_for else client_host) or "unknown"
    user_agent = request.headers.get("user-agent", "unknown")
    
    now = datetime.utcnow()
    update_dict = {
        "other_annual_compensation": round(float(data.amount), 2),
        "other_annual_compensation_signed": True,
        "other_annual_compensation_signature": data.signature_base64,
        "other_annual_compensation_signed_at": now,
        "other_annual_compensation_signed_year": current_year,
        "other_annual_compensation_ip": ip_addr,
        "other_annual_compensation_user_agent": user_agent,
        "other_annual_compensation_user_history": user_history,
    }
    coll = db.users if coll_name == "users" else db.athletes
    await coll.update_one({"id": current_user["id"]}, {"$set": update_dict})
    # 🆕 28/09/2026 — sincronizza sul record collegato (users↔athletes) così l'admin vede "Firmato"
    await _sync_prior_compensation(current_user["id"], update_dict)

    # 🆕 PDF firmato della dichiarazione pregresso in `signed_documents`
    # (visibile in "I Miei Documenti", archivio admin e Cronologia)
    try:
        from routes.declaration_pdf import build_declaration_pdf, store_signed_declaration, society_name_for
        _name = doc.get("full_name") or f"{doc.get('first_name', '')} {doc.get('last_name', '')}".strip() or current_user.get("full_name", "")
        _athlete_id = doc["id"] if coll_name == "athletes" else doc.get("athlete_id")
        _user_id = current_user["id"] if coll_name == "users" else None
        if not _user_id and _athlete_id:
            _lu = await db.users.find_one({"athlete_id": _athlete_id}, {"_id": 0, "id": 1})
            _user_id = (_lu or {}).get("id")
        _version = len(user_history) + 1
        _amount_str = "€ " + f"{float(data.amount):,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
        paragraphs = [
            {"text": f"Il/La sottoscritto/a {_name}, consapevole delle responsabilità penali previste dall'art. 76 del D.P.R. 445/2000 in caso di dichiarazioni mendaci,", "style": "normal"},
            {"text": "DICHIARA", "style": "title"},
            {"text": f"sotto la propria responsabilità, ai fini del calcolo delle soglie previste dalla Riforma dello Sport (D.Lgs. 36/2021), di aver percepito da altre ASD/SSD (diverse da quella cui presenta questa dichiarazione), per l'anno fiscale {current_year}, compensi per lavoro sportivo pari a:", "style": "normal"},
            {"text": _amount_str, "style": "title"},
        ]
        if is_variation:
            paragraphs.append({"text": f"La presente dichiarazione (n. {_version}) sostituisce quella precedentemente sottoscritta, che resta conservata nello storico.", "style": "normal"})
        paragraphs.append({"text": "Si impegna a comunicare tempestivamente alla società ogni variazione dei compensi percepiti da altre società sportive.", "style": "normal"})
        meta = {
            "Numero dichiarazione": str(_version),
            "Anno fiscale": str(current_year),
            "Data/ora": now.strftime("%d/%m/%Y %H:%M:%S UTC"),
            "Indirizzo IP": ip_addr,
            "Dispositivo": (user_agent or "")[:90],
        }
        pdf = build_declaration_pdf(
            title=f"Dichiarazione compensi pregressi {current_year}" + (f" — n. {_version}" if _version > 1 else ""),
            society_name=await society_name_for(doc.get("society_id") or current_user.get("society_id")),
            signer_name=_name, paragraphs=paragraphs, meta=meta,
            signature_base64=data.signature_base64, signed_at=now,
        )
        await store_signed_declaration(
            document_type="prior_compensation_declaration",
            document_title=f"Dichiarazione Pregresso {current_year}" + (f" (n. {_version})" if _version > 1 else ""),
            pdf_bytes=pdf, signer_id=_user_id or current_user["id"], signer_name=_name,
            signer_email=doc.get("email") or current_user.get("email"), athlete_id=_athlete_id,
            society_id=doc.get("society_id") or current_user.get("society_id"), signed_at=now,
            signature_base64=data.signature_base64,
            extra={"amount": round(float(data.amount), 2), "fiscal_year": current_year, "version_number": _version},
        )
    except Exception as _e:
        logging.warning(f"[prior_compensation] PDF non generato: {_e}")
    
    return {
        "success": True,
        "message": "Dichiarazione aggiornata correttamente" if is_variation else "Dichiarazione firmata correttamente",
        "is_variation": is_variation,
        "versions": len(user_history) + 1,
        "amount": update_dict["other_annual_compensation"],
        "signed_at": now.isoformat(),
        "signed_year": current_year,
    }


class AdminEditPriorCompensationRequest(BaseModel):
    amount: float = Field(..., ge=0)
    note: Optional[str] = Field(None, max_length=500, description="Motivo della modifica")


@api_router.patch("/admin/users/{user_id}/prior-compensation")
async def admin_edit_prior_compensation(
    user_id: str,
    data: AdminEditPriorCompensationRequest,
    current_user = Depends(get_current_user),
):
    """Solo l'admin può modificare l'importo pregresso dichiarato.
    Registra nella history: chi ha modificato, quando, da quale importo a quale, con nota."""
    if current_user.get("role") != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")
    doc, coll_name = await _get_user_or_athlete(user_id)
    if not doc:
        raise HTTPException(status_code=404, detail="Utente/atleta non trovato")
    # Multi-tenancy: admin può modificare solo utenti della propria società
    if doc.get("society_id") and doc.get("society_id") != current_user.get("society_id"):
        raise HTTPException(status_code=403, detail="Utente non appartiene alla tua società")
    
    old_amount = float(doc.get("other_annual_compensation") or 0)
    new_amount = round(float(data.amount), 2)
    
    history_entry = {
        "changed_at": datetime.utcnow().isoformat(),
        "changed_by_id": current_user["id"],
        "changed_by_name": current_user.get("full_name"),
        "changed_by_email": current_user.get("email"),
        "old_amount": old_amount,
        "new_amount": new_amount,
        "note": (data.note or "").strip() or None,
    }
    history = list(doc.get("other_annual_compensation_admin_history") or [])
    history.append(history_entry)
    
    coll = db.users if coll_name == "users" else db.athletes
    await coll.update_one(
        {"id": user_id},
        {"$set": {
            "other_annual_compensation": new_amount,
            "other_annual_compensation_admin_history": history,
        }}
    )
    # 🆕 28/09/2026 — sincronizza importo + storia sul record collegato (users↔athletes)
    await _sync_prior_compensation(user_id, {
        "other_annual_compensation": new_amount,
        "other_annual_compensation_admin_history": history,
    })
    return {
        "success": True,
        "old_amount": old_amount,
        "new_amount": new_amount,
        "history_entry": history_entry,
    }


@api_router.get("/admin/users/{user_id}/prior-compensation")
async def admin_get_prior_compensation(
    user_id: str,
    current_user = Depends(get_current_user),
):
    """Admin visualizza la dichiarazione pregresso + storia modifiche di un utente."""
    if current_user.get("role") != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")
    doc, _ = await _get_user_or_athlete(user_id)
    if not doc:
        raise HTTPException(status_code=404, detail="Utente/atleta non trovato")
    if doc.get("society_id") and doc.get("society_id") != current_user.get("society_id"):
        raise HTTPException(status_code=403, detail="Utente non appartiene alla tua società")

    # 🆕 28/09/2026 — legge lo stato firma dal record collegato più valido (users↔athletes)
    best = await _resolve_prior_comp_doc(user_id) or doc
    status = _prior_compensation_status_from_doc(best)
    return {
        **status,
        "signature_base64": best.get("other_annual_compensation_signature"),
        "ip": best.get("other_annual_compensation_ip"),
        "user_agent": best.get("other_annual_compensation_user_agent"),
        "admin_history": best.get("other_annual_compensation_admin_history") or doc.get("other_annual_compensation_admin_history") or [],
        # 🆕 storico delle dichiarazioni precedenti sostituite dal lavoratore (variazioni firmate)
        "user_history": best.get("other_annual_compensation_user_history") or doc.get("other_annual_compensation_user_history") or [],
        "user_full_name": doc.get("full_name") or f"{doc.get('first_name','')} {doc.get('last_name','')}".strip(),
        "user_email": doc.get("email"),
        "user_role": doc.get("role"),
    }


@api_router.post("/athletes/{athlete_id}/accept-compensation")
async def accept_athlete_compensation(athlete_id: str, current_user = Depends(get_current_user)):
    """Athlete accepts the compensation offer - can be called by athlete themselves or admin"""
    # Allow athletes to accept their own compensation, or admin to do it for them
    is_own_profile = current_user.get("athlete_id") == athlete_id
    is_admin = current_user["role"] == UserRole.ADMIN
    
    if not is_own_profile and not is_admin:
        raise HTTPException(status_code=403, detail="Solo l'atleta può accettare il proprio compenso")
    
    # Verify athlete exists and is compensated
    athlete = await db.athletes.find_one({"id": athlete_id, "is_compensated": True})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato in Prime Squadre")
    
    # Check if already accepted
    if athlete.get("compensation_accepted"):
        return {"message": "Compenso già accettato", "already_accepted": True}
    
    # 🆕 27/07/2026 — Blocca se pregresso non dichiarato (Riforma Sport)
    if not is_admin:
        await _require_prior_compensation_declared(athlete_id)
        # 🆕 Blocca se manca la Dichiarazione posizione previdenziale (firma separata)
        await _require_pension_declared([athlete_id, current_user["id"]])
    
    # Update athlete record
    now = datetime.utcnow()
    
    await db.athletes.update_one(
        {"id": athlete_id},
        {"$set": {
            "compensation_accepted": True,
            "compensation_accepted_date": now,
        }}
    )
    
    return {"message": "Compenso accettato con successo", "accepted_date": now.isoformat()}


@api_router.post("/athletes/{athlete_id}/compensation/receipt-sign")
async def sign_athlete_compensation_receipt_with_signature(
    athlete_id: str, 
    data: dict, 
    current_user = Depends(get_current_user)
):
    """Athlete signs their own monthly compensation receipt with digital signature"""
    # 🔍 DEBUG ENTRY LOG
    try:
        logging.warning(
            f"[ATHLETE-RECEIPT] ENTER athlete_id={athlete_id} user={current_user.get('email')} "
            f"month={data.get('month')} year={data.get('year')} amt={data.get('amount_gross')} "
            f"extAmt={data.get('external_compensation_amount')} extNone={data.get('external_compensation_none')}"
        )
    except Exception:
        pass
    # Allow both athlete (signing their own) and admin
    if current_user["role"] == "athlete":
        if current_user.get("athlete_id") != athlete_id and current_user["id"] != athlete_id:
            raise HTTPException(status_code=403, detail="Puoi firmare solo le tue quietanze")
    elif current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Non autorizzato")
    
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")

    # 🔞 Atleta Pro = solo maggiorenni
    try:
        bd = athlete.get("birth_date")
        if bd:
            from datetime import date as _date
            if isinstance(bd, str):
                bd_date = _date.fromisoformat(bd.split("T")[0])
            elif hasattr(bd, "date"):
                bd_date = bd.date()
            else:
                bd_date = bd
            today = _date.today()
            age = today.year - bd_date.year - ((today.month, today.day) < (bd_date.month, bd_date.day))
            if age < 18:
                raise HTTPException(
                    status_code=400,
                    detail="Solo gli atleti maggiorenni possono firmare quietanze. Atleta Pro disponibile dai 18 anni.",
                )
    except HTTPException:
        raise
    except Exception as e:
        logging.warning(f"[ATHLETE-RECEIPT] age check failed for {athlete_id}: {e}")

    _require_complete_anagrafica(athlete)
    
    month = data.get("month")  # int 1-12
    year = data.get("year")
    amount_gross = data.get("amount_gross", athlete.get("monthly_compensation", 0))
    signature_base64 = data.get("signature_base64")
    
    if not month or not year:
        raise HTTPException(status_code=400, detail="Mese e anno sono obbligatori")
    
    if not signature_base64:
        raise HTTPException(status_code=400, detail="Firma digitale obbligatoria")
    
    # Get society data — 🐛 08/07/2026 fix multi-tenancy: filtriamo per society_id dell'atleta,
    # altrimenti db.societies.find_one() senza filtro prende la PRIMA società del DB e
    # genera PDF con intestazione della società sbagliata.
    ath_society_id = athlete.get("society_id")
    society_settings = await db.settings.find_one({"type": "society", "society_id": ath_society_id}) if ath_society_id else None
    society_rec = await db.societies.find_one({"id": ath_society_id}) if ath_society_id else None
    # ALWAYS use ragione_sociale for official documents, fallback to name
    society_name = (society_settings.get("ragione_sociale") if society_settings else None) or (society_rec.get("ragione_sociale") if society_rec else None) or (society_settings.get("name") if society_settings else None) or (society_rec.get("name") if society_rec else None) or "ASD/SSD"
    admin_email = (society_settings.get("email") if society_settings else None) or (society_rec.get("email") if society_rec else None)
    society_city = (society_settings.get("city") if society_settings else None) or (society_rec.get("city") if society_rec else None) or ""
    
    # Get prior compensation
    prior_compensation = athlete.get("other_annual_compensation", 0) or 0
    
    # Calculate yearly totals
    # 🆕 FIX P1: recupera TUTTE le firme dell'anno (escluso solo il mese corrente) per gestire
    # correttamente le firme retroattive fuori ordine cronologico.
    yearly_receipts = await db.athlete_compensation_receipts.find({
        "athlete_id": athlete_id,
        "year": year,
        "signed": True,
        "month": {"$ne": month}
    }).to_list(12)
    
    signed_by_month = {r["month"]: float(r.get("amount", 0) or 0) for r in yearly_receipts}
    yearly_total_from_receipts = sum(signed_by_month.values())
    
    # Check contract start year for prior compensation
    contract_start = athlete.get("contract_start_date")
    contract_start_year = None
    if contract_start:
        if isinstance(contract_start, str):
            contract_start_year = int(contract_start.split('-')[0])
        elif hasattr(contract_start, 'year'):
            contract_start_year = contract_start.year
    
    if contract_start_year and year == contract_start_year:
        yearly_total = yearly_total_from_receipts + prior_compensation
    else:
        yearly_total = yearly_total_from_receipts

    # 📌 Compensi esterni auto-dichiarati (altre ASD/SSD) — criterio per CASSA.
    # ⚠️ Calcolo "ipotetico": la scrittura del record external_compensation
    # avviene SOLO dopo il salvataggio definitivo della quietanza (evita orfani).
    external_amount_pending = float(data.get("external_compensation_amount") or 0)
    external_none_pending = bool(data.get("external_compensation_none") or False)
    external_year_total_before = await _get_year_external_compensations_total(athlete_id, year)
    pending_external_amount = external_amount_pending if external_amount_pending > 0 else 0.0
    external_year_total = external_year_total_before + pending_external_amount
    yearly_total = yearly_total + external_year_total
    
    new_total = yearly_total + amount_gross

    # 🆕 26/02/2026 — "ZAINO" Dual-role: se l'atleta è anche Coach con contratto attivo
    # in questo mese, includo la quota Coach nel PDF e creerò un record coach parallelo.
    # Una singola firma vale per entrambe le voci (Atleta + Coach) → bonifico unico.
    linked_coach_user = None
    coach_amount_this_month = 0.0
    coach_contract_active_this_month = False
    try:
        linked_coach_user = await _find_linked_compensated_user_for_athlete(athlete)
        if linked_coach_user and (linked_coach_user.get("monthly_compensation") or 0) > 0:
            cs = _parse_contract_date(linked_coach_user.get("contract_start_date"))
            ce = _parse_contract_date(linked_coach_user.get("contract_end_date"))
            if cs and ce:
                import calendar as _cal
                from datetime import date as _d
                first_of_month = _d(year, month, 1)
                last_of_month = _d(year, month, _cal.monthrange(year, month)[1])
                if last_of_month >= cs and first_of_month <= ce:
                    coach_contract_active_this_month = True
                    coach_amount_this_month = float(linked_coach_user.get("monthly_compensation") or 0)
                    # Aggiungo le quote Coach degli ALTRI mesi attivi al cumulo cronologico
                    # delle soglie €5K/€15K (atleta + coach + pregresso + esterni).
                    c_monthly = coach_amount_this_month
                    for _m in range(1, 13):
                        if _m == month:
                            continue
                        _first = _d(year, _m, 1)
                        _last = _d(year, _m, _cal.monthrange(year, _m)[1])
                        if _last >= cs and _first <= ce:
                            signed_by_month[_m] = signed_by_month.get(_m, 0.0) + c_monthly
                    # Aggiorno anche yearly_total e new_total con la quota coach del mese
                    yearly_total = yearly_total + sum(
                        c_monthly for _m2 in range(1, 13)
                        if _m2 != month
                        and _d(year, _m2, _cal.monthrange(year, _m2)[1]) >= cs
                        and _d(year, _m2, 1) <= ce
                    )
                    new_total = yearly_total + amount_gross + coach_amount_this_month
    except Exception as e:
        logging.warning(f"[ATHLETE-RECEIPT] dual-role coach detection failed: {e}")
        coach_contract_active_this_month = False
        coach_amount_this_month = 0.0

    # Importo totale visualizzato nel PDF (combined) e nei messaggi
    combined_amount = float(amount_gross) + (coach_amount_this_month if coach_contract_active_this_month else 0.0)
    new_amount_for_threshold = combined_amount
    
    # Threshold checks — 🆕 FIX P1 applicato anche all'Atleta PRO: usa calcolo cronologico
    # cumulativo per gestire correttamente le firme retroattive fuori ordine.
    prior_for_year = prior_compensation if (contract_start_year and year == contract_start_year) else 0
    month_5k, month_15k = _detect_threshold_crossings_chronological(
        signed_by_month=signed_by_month,
        new_month=month,
        new_amount=new_amount_for_threshold,
        prior_compensation=prior_for_year,
        external_total=external_year_total,
    )
    first_time_exceeded_5000 = (month_5k == month)
    first_time_exceeded_15000 = (month_15k == month)
    
    # 🆕 Trattenuta INPS Gestione Separata (quota lavoratore 1/3) sull'eccedenza oltre €5.000.
    # Base = compenso combinato (Atleta + eventuale quota Coach dual-role) sul cumulo annuo lordo.
    inps_breakdown = compute_sport_inps_withholding(
        yearly_total, combined_amount,
        insured_elsewhere=bool(athlete.get("inps_insured_elsewhere", False)),
    )
    amount_net_combined = inps_breakdown["amount_net"]
    
    now = datetime.utcnow()
    month_names = ["", "Gennaio", "Febbraio", "Marzo", "Aprile", "Maggio", "Giugno",
                   "Luglio", "Agosto", "Settembre", "Ottobre", "Novembre", "Dicembre"]
    month_name = month_names[month]
    
    # Generate PDF
    try:
        # Pre-generate the document id so we can embed it as QR code in the PDF
        receipt_id = str(uuid.uuid4())
        # 🆕 29/06/2026 — Costruisci nome atleta robusto (full_name oppure ricomposto)
        athlete_display_name = (
            athlete.get('full_name')
            or f"{athlete.get('last_name', '').upper()} {athlete.get('first_name', '').upper()}".strip()
            or 'Atleta'
        )
        athlete_fiscal = athlete.get('fiscal_code') or ''
        # 🆕 30/06/2026 — Metadati di verifica per le comunicazioni di soglia 5k/15k.
        # Senza questi, il PDF non mostra il blocco "METADATI DI VERIFICA" a piè
        # di pagina (timestamp, totali prima/dopo, hash firma). Stessa struttura
        # usata per Coach/Dirigente/Collaboratore (parità).
        threshold_meta_athlete = {
            "yearly_total_before": yearly_total,
            "yearly_total_after": new_total,
            "prior_compensation_declared": prior_compensation,
            "threshold_crossed": "15000" if first_time_exceeded_15000 else ("5000" if first_time_exceeded_5000 else None),
            "signature_timestamp_utc": now.isoformat(),
            "signature_timestamp_rome": format_rome_timestamp(now),
            "signature_hash": hashlib.sha256(signature_base64.encode()).hexdigest() if signature_base64 else None,
            "monthly_compensation_rate": float(athlete.get('monthly_compensation', 0) or 0),
        }
        if first_time_exceeded_15000:
            pdf_bytes = generate_threshold_15k_pdf(
                society_name=society_name,
                collaborator_name=athlete_display_name,
                collaborator_fiscal_code=athlete_fiscal,
                year=year,
                signature_base64=signature_base64,
                society_city=society_city,
                threshold_metadata=threshold_meta_athlete,
                signed_at=now,
                threshold_month=month,
                document_id=receipt_id,
            )
            pdf_filename_prefix = "comunicazione_15k_atleta"
            doc_type = "threshold_15000_communication"
        elif first_time_exceeded_5000:
            pdf_bytes = generate_threshold_5k_pdf(
                society_name=society_name,
                collaborator_name=athlete_display_name,
                collaborator_fiscal_code=athlete_fiscal,
                year=year,
                signature_base64=signature_base64,
                society_city=society_city,
                threshold_metadata=threshold_meta_athlete,
                signed_at=now,
                threshold_month=month,
                document_id=receipt_id,
            )
            pdf_filename_prefix = "comunicazione_5k_atleta"
            doc_type = "threshold_5000_communication"
        else:
            pdf_bytes = generate_monthly_receipt_pdf(
                society_name=society_name,
                collaborator_name=athlete_display_name,
                collaborator_fiscal_code=athlete_fiscal,
                month_name=month_name,
                year=year,
                amount_gross=combined_amount,  # 🆕 Totale (Atleta + Coach se dual-role attivo)
                signature_base64=signature_base64,
                signed_at=now,
                document_id=receipt_id,
                signer_id=athlete_id,
                # 🆕 26/02/2026 — Split dual-role: se Coach attivo nel mese, mostra entrambe le voci
                coach_amount=(coach_amount_this_month if coach_contract_active_this_month else None),
                athlete_pro_amount=(float(amount_gross) if coach_contract_active_this_month else None),
                # 🆕 29/06/2026 — Label "Atleta:" invece di "Collaboratore:"
                role_label="Atleta",
                inps_breakdown=inps_breakdown,
            )
            pdf_filename_prefix = "quietanza_atleta"
            doc_type = "compensation_receipt"
    except Exception as e:
        logging.error(f"Error generating athlete PDF: {e}")
        raise HTTPException(status_code=500, detail=f"Errore nella generazione del PDF: {str(e)}")
    
    # Save PDF
    pdf_filename = f"{pdf_filename_prefix}_{athlete_id}_{year}_{month:02d}_{receipt_id}.pdf"
    pdf_path = os.path.join(SIGNED_DOCS_DIR, pdf_filename)
    
    try:
        with open(pdf_path, 'wb') as f:
            f.write(pdf_bytes)
    except Exception as e:
        logging.error(f"Error saving athlete PDF: {e}")
        raise HTTPException(status_code=500, detail="Errore nel salvataggio del documento")
    
    # 🆕 30/06/2026 — Titolo specifico per quietanze di superamento soglia
    # (prima erano salvate tutte come "Quietanza Compenso Atleta", confondendo
    # gli utenti nell'elenco "I Miei Documenti").
    if first_time_exceeded_15000:
        doc_title_str = f"Comunicazione Superamento €15.000 - {month_name} {year}"
    elif first_time_exceeded_5000:
        doc_title_str = f"Comunicazione Superamento €5.000 - {month_name} {year}"
    else:
        doc_title_str = f"Quietanza Compenso Atleta - {month_name} {year}"

    # Store document record
    document_record = {
        "id": receipt_id,
        "document_type": doc_type,
        "document_title": doc_title_str,
        # 🐛 27/07/2026 — Fix multi-tenancy: persistere society_id sul documento
        # firmato così la pagina QR verify riesce a mostrare la società corretta
        # (prima era None → il codice di fallback prendeva la prima società del DB).
        "society_id": athlete.get("society_id"),
        "athlete_id": athlete_id,
        "athlete_name": athlete.get('full_name', ''),
        "month": month,
        "year": year,
        "amount_gross": combined_amount,  # 🆕 Totale (Atleta + Coach se dual-role)
        "pdf_path": pdf_path,
        "pdf_filename": pdf_filename,
        "pdf_base64": base64.b64encode(pdf_bytes).decode(),
        "signed_at": now,
        "exceeded_5000": first_time_exceeded_5000,
        "exceeded_15000": first_time_exceeded_15000,
        # 🆕 30/06/2026 — Persistiamo i threshold metadata anche su doc Atleta,
        # così _regenerate_threshold_communication_pdf li ritrova al re-render.
        "threshold_metadata": threshold_meta_athlete if (first_time_exceeded_5000 or first_time_exceeded_15000) else None,
        # 🆕 26/02/2026 — Dual-role metadata (riferimento ricevuta unica)
        "dual_role_combined": coach_contract_active_this_month,
        "dual_role_athlete_portion": float(amount_gross) if coach_contract_active_this_month else None,
        "dual_role_coach_portion": coach_amount_this_month if coach_contract_active_this_month else None,
        "linked_coach_user_id": linked_coach_user.get("id") if (linked_coach_user and coach_contract_active_this_month) else None,
    }
    await db.signed_documents.insert_one(document_record)
    
    # Check if receipt already exists and is signed
    # Search by both number and string (legacy format) for the month
    existing_receipt = await db.athlete_compensation_receipts.find_one({
        "athlete_id": athlete_id, 
        "$or": [
            {"month": month},  # Number format (10, 11, 12)
            {"month": month_name}  # String format ("Ottobre", "Novembre", etc.)
        ],
        "year": year
    })
    
    if existing_receipt and existing_receipt.get("signed"):
        signed_date = existing_receipt.get('signed_date')
        if signed_date:
            if isinstance(signed_date, str):
                date_str = signed_date[:10]
            else:
                date_str = signed_date.strftime('%d/%m/%Y')
        else:
            date_str = 'data sconosciuta'
        raise HTTPException(
            status_code=400, 
            detail=f"Quietanza per {month_name} {year} già firmata il {date_str}"
        )
    
    # Update receipt record - also handle legacy records by matching both formats
    # 🆕 28/06/2026 — Scriviamo entrambi i nomi campo (legacy `signed`/`amount` + nuovi
    # `receipt_signed`/`amount_gross`) così non serve più normalizzare lato frontend.
    # I campi legacy restano per backward-compatibility con codice già esistente.
    receipt_data = {
        "athlete_id": athlete_id,
        "society_id": athlete.get("society_id"),
        "month": month,  # Store as integer (1-12) for consistent filtering
        "month_name": month_name,  # Keep month name for display
        "year": year,
        # Legacy fields (mantenuti per non rompere codice esistente)
        "signed": True,
        "signed_date": now,
        "amount": amount_gross,
        # 🆕 New canonical fields (allineati a coach/dirigente/collaboratore)
        "receipt_signed": True,
        "receipt_signed_date": now,
        "amount_gross": amount_gross,
        # 🆕 Netto corrisposto e trattenuta INPS (quota lavoratore 1/3) oltre €5.000
        "amount_net": amount_net_combined,
        "deductions": inps_breakdown.get("inps_worker", 0.0),
        "inps_breakdown": inps_breakdown,
        "signature_base64": signature_base64,
        "document_id": receipt_id,
        "pdf_filename": pdf_filename,
        "exceeded_5000": first_time_exceeded_5000,
        "exceeded_15000": first_time_exceeded_15000,
        "updated_at": now,
    }
    
    # Update using $or to match both legacy string format and new number format
    result = await db.athlete_compensation_receipts.update_one(
        {
            "athlete_id": athlete_id, 
            "$or": [{"month": month}, {"month": month_name}],
            "year": year
        },
        {"$set": receipt_data}
    )
    
    # If no existing record was updated, insert new one
    if result.matched_count == 0:
        await db.athlete_compensation_receipts.insert_one(receipt_data)

    # 🆕 26/02/2026 — ZAINO Dual-role: salva ANCHE record coach parallelo (1 firma = 2 quietanze)
    if coach_contract_active_this_month and linked_coach_user and coach_amount_this_month > 0:
        try:
            coach_user_id = linked_coach_user["id"]
            coach_existing = await db.coach_compensations.find_one({
                "coach_id": coach_user_id,
                "month": month,
                "year": year,
            })
            coach_receipt = {
                "coach_id": coach_user_id,
                "society_id": linked_coach_user.get("society_id") or athlete.get("society_id"),
                "month": month,
                "year": year,
                "amount_gross": coach_amount_this_month,
                "amount_net": coach_amount_this_month,
                "deductions": 0.0,
                "received": True,
                "received_date": now,
                "receipt_signed": True,
                "receipt_signature_base64": signature_base64,
                "receipt_document_id": receipt_id,  # Stesso PDF dell'atleta
                "receipt_signed_date": now,
                "exceeded_5000": first_time_exceeded_5000,
                "exceeded_5000_date": now if first_time_exceeded_5000 else None,
                "exceeded_15000": first_time_exceeded_15000,
                "exceeded_15000_date": now if first_time_exceeded_15000 else None,
                # 🎒 Metadati dual-role
                "dual_role_combined": True,
                "linked_athlete_id": athlete_id,
                "linked_athlete_receipt_id": receipt_id,
                "updated_at": now,
            }
            if coach_existing:
                await db.coach_compensations.update_one(
                    {"id": coach_existing["id"]},
                    {"$set": coach_receipt},
                )
                logging.info(f"[ATHLETE-RECEIPT] DUAL-ROLE: coach record UPDATED for coach_id={coach_user_id} month={month}/{year}")
            else:
                coach_receipt["id"] = str(uuid.uuid4())
                await db.coach_compensations.insert_one(coach_receipt)
                logging.info(f"[ATHLETE-RECEIPT] DUAL-ROLE: coach record CREATED for coach_id={coach_user_id} month={month}/{year} amt={coach_amount_this_month}")
        except Exception as e:
            # Non-blocking: la quietanza atleta è già salvata. Loghiamo e segnaliamo nella response.
            logging.error(f"[ATHLETE-RECEIPT] DUAL-ROLE coach record save FAILED: {e}")
    
    # ✅ Quietanza salvata: ORA registra la dichiarazione esterna (evita orfani)
    try:
        if pending_external_amount > 0:
            await _record_external_compensation_declaration(
                user_id=athlete_id, year=year,
                amount=pending_external_amount, declared_none=False,
                related_receipt_month=month, society_id=athlete.get("society_id"),
            )
        elif external_none_pending:
            await _record_external_compensation_declaration(
                user_id=athlete_id, year=year, amount=0.0, declared_none=True,
                related_receipt_month=month, society_id=athlete.get("society_id"),
            )
    except Exception as e:
        logging.error(f"[ATHLETE-RECEIPT] external_compensation declaration FAILED (non-blocking): {e}")
    
    # Send emails
    athlete_email = athlete.get('email')
    parent_email = None
    if athlete.get("parent_id"):
        parent = await db.users.find_one({"id": athlete.get("parent_id")})
        if parent:
            parent_email = parent.get("email")
    
    recipient_email = athlete_email or parent_email
    
    if recipient_email:
        try:
            import base64 as b64
            body = f"""<html><body>
            <h2>Quietanza Compenso Sportivo - {month_name} {year}</h2>
            <p>Gentile {athlete.get('full_name', 'Atleta')},</p>
            <p>In allegato trova la quietanza del compenso sportivo firmata per {month_name} {year}.</p>
            <ul><li>Compenso lordo: € {amount_gross:.2f}</li><li>Totale annuo progressivo: € {new_total:.2f}</li></ul>
            <hr><p><em>Documento generato automaticamente da RegistraTEAM</em></p>
            </body></html>"""
            
            encoded_pdf = b64.b64encode(pdf_bytes).decode()
            await send_email_with_pdf(to_email=recipient_email, subject=f"Quietanza Compenso - {month_name} {year} - {society_name}", html_content=body, pdf_base64=encoded_pdf, pdf_filename=pdf_filename, to_name=athlete.get('full_name', 'Atleta'))
        except Exception as e:
            logging.error(f"Error sending athlete receipt email: {e}")
    
    # NOTE: Email to admin removed - documents available in Archive section
    # if admin_email and admin_email != recipient_email:
    #     ... (email sending removed)
    
    return {
        "message": "Quietanza firmata con successo" + (" (Atleta + Coach — bonifico unico)" if coach_contract_active_this_month else ""),
        "document_id": receipt_id, 
        "pdf_filename": pdf_filename, 
        "exceeded_5000": first_time_exceeded_5000, 
        "exceeded_15000": first_time_exceeded_15000,
        "amount_gross": combined_amount,
        "amount_net": combined_amount,  # For athletes, net = gross (no deductions calculated here)
        "yearly_total": new_total,
        # 🎒 Dual-role info per UI feedback
        "dual_role_combined": coach_contract_active_this_month,
        "athlete_portion": float(amount_gross) if coach_contract_active_this_month else None,
        "coach_portion": coach_amount_this_month if coach_contract_active_this_month else None,
    }



