@api_router.get("/athletes/pending")
async def get_pending_athletes(current_user = Depends(get_current_user)):
    """Get all athletes pending approval - admin only - OPTIMIZED"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può vedere gli atleti in attesa")
    
    society_id = current_user.get("society_id")
    # Projection: only the fields we actually return. This avoids transferring
    # heavy base64 fields like athlete_photo / profile_photo.
    ATHLETE_PROJ = {
        "_id": 0, "id": 1, "full_name": 1, "first_name": 1, "last_name": 1,
        "date_of_birth": 1, "fiscal_code": 1, "team_id": 1, "parent_id": 1,
        "parents_detached": 1, "registration_date": 1, "status": 1,
        "email": 1, "phone_athlete": 1,
    }
    pending = await db.athletes.find(
        {"status": AthleteStatus.PENDING, "society_id": society_id},
        ATHLETE_PROJ,
    ).to_list(1000)
    
    # Batch fetch teams and users to avoid N+1 queries
    teams_list = await db.teams.find(
        {"society_id": society_id},
        {"_id": 0, "id": 1, "name": 1},
    ).to_list(1000)
    teams_dict = {t["id"]: t for t in teams_list}
    
    # Only fetch users that are actually referenced as parents (avoid loading
    # the whole users collection with all their base64 photos).
    parent_ids = [a.get("parent_id") for a in pending if a.get("parent_id")]
    users_dict = {}
    if parent_ids:
        users_list = await db.users.find(
            {"id": {"$in": list(set(parent_ids))}, "society_id": society_id},
            {"_id": 0, "id": 1, "full_name": 1, "email": 1},
        ).to_list(1000)
        users_dict = {u["id"]: u for u in users_list}
    
    result = []
    for athlete in pending:
        team = teams_dict.get(athlete.get("team_id")) if athlete.get("team_id") else None
        parent = users_dict.get(athlete.get("parent_id")) if athlete.get("parent_id") else None
        
        # Check if adult athlete (no parent_id)
        is_adult = athlete.get("parent_id") is None or athlete.get("parents_detached") is True
        
        result.append({
            "id": athlete["id"],
            "full_name": athlete["full_name"],
            "first_name": athlete.get("first_name"),
            "last_name": athlete.get("last_name"),
            "date_of_birth": athlete.get("date_of_birth"),
            "fiscal_code": athlete.get("fiscal_code"),
            "team_id": athlete.get("team_id"),
            "team_name": team["name"] if team else "Da assegnare",
            "parent_name": parent["full_name"] if parent else None,
            "parent_email": parent["email"] if parent else "",
            "registration_date": athlete.get("registration_date"),
            "status": athlete.get("status", "pending"),
            "is_adult": is_adult,
            "athlete_email": athlete.get("email"),
            "athlete_phone": athlete.get("phone_athlete"),
        })
    
    return result

class AthleteApprovalUpdate(BaseModel):
    status: str  # trial, active, rejected
    athlete_type: Optional[str] = None  # quota | compensated (per atleti maggiorenni: quota=paga, compensated=Atleta PRO)

@api_router.patch("/athletes/{athlete_id}/approval")
async def update_athlete_approval(athlete_id: str, data: AthleteApprovalUpdate, current_user = Depends(get_current_user)):
    """Approve or reject an athlete - admin only"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può approvare atleti")
    
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    # Validate status
    if data.status not in [AthleteStatus.TRIAL, AthleteStatus.ACTIVE, "rejected"]:
        raise HTTPException(status_code=400, detail="Stato non valido. Usa: trial, active, rejected")
    
    update_data = {
        "status": data.status,
        "approved_at": datetime.utcnow(),
        "approved_by": current_user["id"]
    }
    
    # Tipo atleta scelto da admin all'approvazione
    is_compensated_athlete = False
    if data.athlete_type:
        if data.athlete_type not in ("quota", "compensated"):
            raise HTTPException(status_code=400, detail="athlete_type non valido. Usa: quota | compensated")
        update_data["athlete_type"] = data.athlete_type
        if data.athlete_type == "compensated":
            update_data["is_compensated"] = True
            is_compensated_athlete = True
    
    # 🆕 ADULTI (18+): NESSUN periodo di prova. Distinguiamo subito minori/adulti.
    _is_adult = not _compute_is_minor(athlete)

    # If approving to trial, set trial end date from now — SOLO per i minorenni
    if data.status == AthleteStatus.TRIAL and not _is_adult:
        update_data["trial_end_date"] = datetime.utcnow() + timedelta(days=7)

    if _is_adult and data.status in (AthleteStatus.TRIAL, AthleteStatus.ACTIVE):
        # 🆕 ADULTI (18+): all'accettazione dell'admin l'atleta NON entra in prova.
        # Resta IN ATTESA (pending_certificate) finché non ha (privacy firmata E
        # certificato medico convalidato). Poi diventa ATTIVO automaticamente
        # (vedi maybe_activate_adult_athlete più sotto).
        update_data["status"] = "pending_certificate"
        update_data["is_trial"] = False
        update_data.pop("trial_end_date", None)
    elif data.status == AthleteStatus.TRIAL:
        # 🆕 MINORENNI — Certificato medico (blocco onboarding): quando l'admin
        # approva per la PROVA, l'atleta va in ATTESA INIZIO PROVA (pending_trial).
        # Ma se serve il certificato e non è ancora convalidato, resta in ATTESA
        # (pending_certificate) finché l'admin non convalida il certificato.
        _team = await db.teams.find_one({"id": athlete.get("team_id")}) if athlete.get("team_id") else None
        _cert_type = cert_type_for_team(_team)
        _is_minor = athlete.get("is_minor", False)
        _already_reg = athlete.get("already_registered")
        _req_trial = cert_required_for_trial(_is_minor, _already_reg, _cert_type)
        if _req_trial and not has_valid_verified_cert(athlete):
            update_data["status"] = "pending_certificate"
        else:
            update_data["status"] = "pending_trial"
    
    await db.athletes.update_one(
        {"id": athlete_id},
        {"$set": update_data}
    )

    # 🆕 ADULTI (18+): se all'accettazione l'atleta ha GIÀ privacy firmata E
    # certificato convalidato, attivalo subito (nessun periodo di prova).
    if _is_adult and data.status in (AthleteStatus.TRIAL, AthleteStatus.ACTIVE):
        await maybe_activate_adult_athlete(athlete_id, current_user)
    
    # AUTO-APPROVE PARENT: When approving an athlete, also approve their parent
    if data.status in [AthleteStatus.TRIAL, AthleteStatus.ACTIVE]:
        parent_id = athlete.get("parent_id")
        if parent_id:
            parent = await db.users.find_one({"id": parent_id})
            if parent and parent.get("status") == UserStatus.PENDING:
                await db.users.update_one(
                    {"id": parent_id},
                    {"$set": {
                        "status": UserStatus.APPROVED,
                        "approved_at": datetime.utcnow(),
                        "approved_by": current_user["id"]
                    }}
                )
        else:
            # Adult athlete - find and approve their user account
            adult_user = await db.users.find_one({"athlete_id": athlete_id})
            if adult_user and adult_user.get("status") == UserStatus.PENDING:
                await db.users.update_one(
                    {"athlete_id": athlete_id},
                    {"$set": {
                        "status": UserStatus.APPROVED,
                        "approved_at": datetime.utcnow(),
                        "approved_by": current_user["id"]
                    }}
                )
    
    # If approving, create payment records
    if data.status in [AthleteStatus.TRIAL, AthleteStatus.ACTIVE]:
        # Check if payments already exist for CURRENT season (ignora archiviati)
        existing_payments = await db.payments.count_documents({
            "athlete_id": athlete_id,
            "$or": [{"is_previous_season": {"$ne": True}}, {"is_previous_season": {"$exists": False}}],
        })
        if existing_payments == 0 and athlete.get("team_id"):
            team = await db.teams.find_one({"id": athlete["team_id"]})
            if team and team.get("installment_1_amount", 0) > 0:
                trial_end = update_data.get("trial_end_date", datetime.utcnow())
                # Installment 1 - Rata Iscrizione
                payment1 = Payment(
                    athlete_id=athlete_id,
                    installment_number=1,
                    description="Rata Iscrizione",
                    amount=team["installment_1_amount"],
                    due_date=trial_end,
                    paid=False
                )
                await db.payments.insert_one(payment1.dict())
                
                # Installment 2 - Prima Rata
                if team.get("installment_2_amount", 0) > 0:
                    due_date_2 = team.get("installment_2_due_date") or datetime.utcnow()
                    payment2 = Payment(
                        athlete_id=athlete_id,
                        installment_number=2,
                        description="1ª Rata",
                        amount=team["installment_2_amount"],
                        due_date=due_date_2,
                        paid=False
                    )
                    await db.payments.insert_one(payment2.dict())
                
                # Installment 3 - Seconda Rata
                if team.get("installment_3_amount", 0) > 0:
                    due_date_3 = team.get("installment_3_due_date") or datetime.utcnow()
                    payment3 = Payment(
                        athlete_id=athlete_id,
                        installment_number=3,
                        description="2ª Rata",
                        amount=team["installment_3_amount"],
                        due_date=due_date_3,
                        paid=False
                    )
                    await db.payments.insert_one(payment3.dict())
    
    # 📨 Welcome email per Atleti PRO (atleti maggiorenni remunerati)
    if is_compensated_athlete and data.status in [AthleteStatus.TRIAL, AthleteStatus.ACTIVE]:
        try:
            adult_user = await db.users.find_one(
                {"athlete_id": athlete_id},
                {"_id": 0, "email": 1, "full_name": 1},
            )
            if adult_user and adult_user.get("email"):
                society = await db.societies.find_one(
                    {"id": current_user.get("society_id")},
                    {"_id": 0, "name": 1},
                )
                society_name = (society or {}).get("name", "")
                subject = f"🏆 Benvenuto come Atleta PRO - {society_name}"
                body_html = f"""
                <p>Ciao <strong>{adult_user.get('full_name', '')}</strong>,</p>
                <p>la società <strong>{society_name}</strong> ti ha approvato come <strong>Atleta PRO</strong>! 🎉</p>
                <p>Da ora puoi accedere all'app RegistraTEAM con le credenziali che hai scelto in registrazione e:</p>
                <ul>
                  <li>Visualizzare i tuoi compensi mensili</li>
                  <li>Firmare digitalmente le quietanze</li>
                  <li>Gestire le dichiarazioni di compensi esterni</li>
                  <li>Scaricare i PDF firmati</li>
                </ul>
                <p>In bocca al lupo per la nuova stagione!</p>
                """
                try:
                    from email_service import send_transactional_email
                    await send_transactional_email(
                        to_email=adult_user["email"],
                        subject=subject,
                        html_content=body_html + _get_email_store_footer(),
                    )
                except Exception as e:
                    logging.warning(f"[ATHLETE-APPROVAL] welcome email failed: {e}")
        except Exception as e:
            logging.error(f"[ATHLETE-APPROVAL] welcome email FAILED (non-blocking): {e}")

    status_text = {
        AthleteStatus.TRIAL: "approvato (periodo di prova)",
        AthleteStatus.ACTIVE: "approvato (attivo)",
        "rejected": "rifiutato"
    }
    
    return {"message": f"Atleta {status_text.get(data.status, data.status)} con successo"}


@api_router.patch("/athletes/{athlete_id}/dismiss-review")
async def dismiss_athlete_review(athlete_id: str, current_user = Depends(get_current_user)):
    """Segna un atleta come 'già controllato' per la stagione corrente, così esce
    dalla sezione admin 'Da controllare' (nuove iscrizioni + riconferme)."""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può controllare gli atleti")

    society_id = current_user.get("society_id")
    athlete = await db.athletes.find_one({"id": athlete_id, "society_id": society_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")

    from utils import get_current_season_for_society as _get_cs
    current_season = await _get_cs(db, society_id)

    await db.athletes.update_one(
        {"id": athlete_id, "society_id": society_id},
        {"$set": {
            "review_dismissed_season": current_season,
            "review_dismissed_at": datetime.utcnow(),
            "review_dismissed_by": current_user["id"],
        }},
    )
