@api_router.get("/athletes/deletion-requests")
async def get_deletion_requests(current_user = Depends(get_current_user)):
    """Get all athletes with deletion requests - admin only"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può vedere le richieste di cancellazione")
    
    society_id = current_user.get("society_id")
    # Projection + society filter. Avoids transferring base64 photos.
    ATHLETE_PROJ = {
        "_id": 0, "id": 1, "full_name": 1, "first_name": 1, "last_name": 1,
        "team_id": 1, "parent_id": 1, "deletion_requested_at": 1,
        "deletion_requested_by": 1, "deletion_requested_by_name": 1,
    }
    requests = await db.athletes.find(
        {"deletion_requested": True, "society_id": society_id},
        ATHLETE_PROJ,
    ).to_list(1000)
    
    # Collect only relevant team and user ids (no full collection scan)
    team_ids = list({a.get("team_id") for a in requests if a.get("team_id")})
    user_ids = set()
    for a in requests:
        if a.get("parent_id"): user_ids.add(a["parent_id"])
        if a.get("deletion_requested_by"): user_ids.add(a["deletion_requested_by"])
    
    teams_dict = {}
    if team_ids:
        teams_list = await db.teams.find(
            {"id": {"$in": team_ids}, "society_id": society_id},
            {"_id": 0, "id": 1, "name": 1},
        ).to_list(1000)
        teams_dict = {t["id"]: t for t in teams_list}
    
    users_dict = {}
    if user_ids:
        users_list = await db.users.find(
            {"id": {"$in": list(user_ids)}, "society_id": society_id},
            {"_id": 0, "id": 1, "full_name": 1, "email": 1},
        ).to_list(1000)
        users_dict = {u["id"]: u for u in users_list}
    
    result = []
    for athlete in requests:
        team = teams_dict.get(athlete.get("team_id"))
        parent = users_dict.get(athlete.get("parent_id"))
        requested_by = users_dict.get(athlete.get("deletion_requested_by"))
        result.append({
            "id": athlete["id"],
            "full_name": athlete.get("full_name", f"{athlete.get('first_name', '')} {athlete.get('last_name', '')}"),
            "team_name": team["name"] if team else "Sconosciuta",
            "parent_name": parent["full_name"] if parent else "Sconosciuto",
            "parent_email": parent["email"] if parent else "",
            "requested_at": athlete.get("deletion_requested_at"),
            "requested_by_name": requested_by.get("full_name", "Sconosciuto") if requested_by else athlete.get("deletion_requested_by_name", "Sconosciuto"),
        })
    
    return result

@api_router.get("/athletes/registered-today")
async def get_athletes_registered_today(current_user = Depends(get_current_user)):
    """Get athletes registered today with parent info and team assignment status.

    "Today" is the Italian calendar day (Europe/Rome) to match what the user
    sees in the dashboard between midnight and ~02:00 local time.
    """
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")

    today = now_it().date()
    society_id = current_user.get("society_id")
    # Projection + society filter to avoid scanning base64 photos.
    all_athletes = await db.athletes.find(
        {"society_id": society_id},
        {
            "_id": 0, "id": 1, "full_name": 1, "is_minor": 1,
            "parent_id": 1, "second_parent_id": 1, "team_id": 1,
            "created_at": 1,
        },
    ).to_list(5000)
    
    today_athletes = []
    for a in all_athletes:
        created = a.get("created_at")
        if not created:
            continue
        try:
            if isinstance(created, str):
                created_dt = datetime.fromisoformat(created.replace('Z', '+00:00'))
            elif isinstance(created, datetime):
                created_dt = created
            else:
                continue
            if created_dt.date() == today:
                parent_name = None
                if a.get("parent_id"):
                    parent = await db.users.find_one({"id": a["parent_id"]}, {"_id": 0, "full_name": 1})
                    parent_name = parent.get("full_name") if parent else None
                
                second_parent_name = None
                if a.get("second_parent_id"):
                    sp = await db.users.find_one({"id": a["second_parent_id"]}, {"_id": 0, "full_name": 1})
                    second_parent_name = sp.get("full_name") if sp else None
                
                team_name = None
                if a.get("team_id"):
                    team = await db.teams.find_one({"id": a["team_id"]}, {"_id": 0, "name": 1})
                    team_name = team.get("name") if team else None
                
                today_athletes.append({
                    "id": a.get("id"),
                    "full_name": a.get("full_name", ""),
                    "is_minor": a.get("is_minor", False),
                    "parent_name": parent_name,
                    "second_parent_name": second_parent_name,
                    "team_id": a.get("team_id"),
                    "team_name": team_name,
                    "has_team": bool(a.get("team_id")),
                    "status": a.get("status", ""),
                    "created_at": str(created),
                })
        except:
            continue
    
    today_athletes.sort(key=lambda x: x["created_at"], reverse=True)
    return {"athletes": today_athletes, "count": len(today_athletes)}

@api_router.get("/athletes/registrations-history")
async def get_registrations_history(current_user = Depends(get_current_user)):
    """Get all athlete registrations grouped by date for admin"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")
    
    # Multi-tenant: scope to admin's society to prevent cross-tenant data leak.
    society_id = current_user.get("society_id")
    query = {"created_at": {"$exists": True, "$ne": None}}
    if society_id:
        query["society_id"] = society_id
    all_athletes = await db.athletes.find(query).sort("created_at", -1).to_list(5000)
    
    registrations = []
    for a in all_athletes:
        created = a.get("created_at")
        try:
            if isinstance(created, str):
                created_dt = datetime.fromisoformat(created.replace('Z', '+00:00'))
            elif isinstance(created, datetime):
                created_dt = created
            else:
                continue
            
            parent_name = None
            if a.get("parent_id"):
                parent = await db.users.find_one({"id": a["parent_id"]}, {"_id": 0, "full_name": 1})
                parent_name = parent.get("full_name") if parent else None
            
            second_parent_name = None
            if a.get("second_parent_id"):
                sp = await db.users.find_one({"id": a["second_parent_id"]}, {"_id": 0, "full_name": 1})
                second_parent_name = sp.get("full_name") if sp else None
            
            team_name = None
            if a.get("team_id"):
                team = await db.teams.find_one({"id": a["team_id"]}, {"_id": 0, "name": 1})
                team_name = team.get("name") if team else None
            
            registrations.append({
                "id": a.get("id"),
                "full_name": a.get("full_name", ""),
                "is_minor": a.get("is_minor", False),
                "parent_name": parent_name,
                "second_parent_name": second_parent_name,
                "team_id": a.get("team_id"),
                "team_name": team_name,
                "has_team": bool(a.get("team_id")),
                "status": a.get("status", ""),
                "date": created_dt.strftime("%Y-%m-%d"),
                "created_at": str(created),
            })
        except:
            continue
    
    return {"registrations": registrations}


@api_router.get("/athletes/{athlete_id}", response_model=Athlete)
async def get_athlete(athlete_id: str, current_user = Depends(get_current_user)):
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    # 🚀 16/08/2026 — Backfill compressione foto pesanti (riduce payload + RAM su Render,
    # velocizza l'apertura dell'anagrafica atleta). Solo se > ~500KB.
    from utils import compress_base64_image
    import asyncio as _asyncio_ath
    _photo_updates = {}
    for _pk in ('athlete_photo', 'athlete_photo_artistic'):
        _val = athlete.get(_pk)
        if isinstance(_val, str) and len(_val) > 500_000:
            # 🚀 18/08/2026 — Compressione OFF dall'event loop (thread separato).
            _comp = await _asyncio_ath.to_thread(compress_base64_image, _val)
            if _comp and _comp != _val and len(_comp) < len(_val):
                athlete[_pk] = _comp
                _photo_updates[_pk] = _comp
    if _photo_updates:
        try:
            await db.athletes.update_one({"id": athlete_id}, {"$set": _photo_updates})
        except Exception:
            pass
    
    # Check permissions - allow primary and second parent
    if current_user["role"] == UserRole.PARENT:
        is_primary_parent = athlete.get("parent_id") == current_user["id"]
        is_second_parent = athlete.get("second_parent_id") == current_user["id"]
        if not is_primary_parent and not is_second_parent:
            raise HTTPException(status_code=403, detail="Accesso negato")
    # Allow athlete to access their own data
    elif current_user["role"] == "athlete":
        if current_user.get("athlete_id") != athlete_id and current_user["id"] != athlete_id:
            raise HTTPException(status_code=403, detail="Puoi vedere solo i tuoi dati")
    
    # For compensated athletes, sync compensation data from separate collection if needed
    if athlete.get("athlete_type") == "compensated":
        # Check if compensation fields are missing but exist in separate collection
        if not athlete.get("monthly_compensation") or not athlete.get("contract_start_date"):
            comp = await db.athlete_compensations.find_one({"athlete_id": athlete_id})
            if comp:
                # Sync data to athlete document and response
                sync_data = {}
                if comp.get("monthly_amount") and not athlete.get("monthly_compensation"):
                    sync_data["monthly_compensation"] = comp["monthly_amount"]
                    athlete["monthly_compensation"] = comp["monthly_amount"]
                if comp.get("start_date"):
                    start_date = comp["start_date"]
                    if isinstance(start_date, datetime):
                        start_date = start_date.strftime("%Y-%m-%d")
                    if not athlete.get("contract_start_date"):
                        sync_data["contract_start_date"] = start_date
                        athlete["contract_start_date"] = start_date
                if comp.get("end_date"):
                    end_date = comp["end_date"]
                    if isinstance(end_date, datetime):
                        end_date = end_date.strftime("%Y-%m-%d")
                    if not athlete.get("contract_end_date"):
                        sync_data["contract_end_date"] = end_date
                        athlete["contract_end_date"] = end_date
                
                # Persist sync to database
                if sync_data:
                    await db.athletes.update_one({"id": athlete_id}, {"$set": sync_data})
    
    # Add team_name if team_id exists
    if athlete.get("team_id"):
        team = await db.teams.find_one({"id": athlete["team_id"]})
        if team:
            athlete["team_name"] = team.get("name", "")
    
    # Add profile_photo - check athlete_photo, then user profile_photo
    if not athlete.get("profile_photo"):
        if athlete.get("athlete_photo"):
            athlete["profile_photo"] = athlete["athlete_photo"]
        else:
            user = await db.users.find_one({"athlete_id": athlete_id})
            if user and user.get("profile_photo"):
                athlete["profile_photo"] = user["profile_photo"]
    
    # For adult athletes, sync personal data from user record if missing in athlete
    user = await db.users.find_one({"athlete_id": athlete_id})
    if user:
        # Sync gender if missing or empty
        if (not athlete.get("gender") or athlete.get("gender") == "") and user.get("gender"):
            athlete["gender"] = user["gender"]
        # Sync place_of_birth if missing
        if not athlete.get("place_of_birth") and user.get("place_of_birth"):
            athlete["place_of_birth"] = user["place_of_birth"]
        if not athlete.get("birth_place") and user.get("place_of_birth"):
            athlete["birth_place"] = user["place_of_birth"]
        # Sync date_of_birth if missing
        if not athlete.get("date_of_birth") and user.get("date_of_birth"):
            athlete["date_of_birth"] = user["date_of_birth"]
    
    # 🆕 22/08/2026 — Dati bancari dual-role: se l'atleta (18+ PRO) è anche staff
    # (coach/dirigente/collaboratore) e i suoi campi bancari sono vuoti, ereditali
    # dal record utente collegato. Stesso collegamento tra profili usato per i consensi.
    _bank_empty = (
        not (athlete.get("iban") or "").strip()
        and not (athlete.get("bank_name") or "").strip()
        and not (athlete.get("account_holder") or "").strip()
        and not (athlete.get("iban_holder") or "").strip()
    )
    if _bank_empty:
        _bank_proj = {"_id": 0, "iban": 1, "bank_name": 1, "account_holder": 1,
                      "iban_holder": 1, "iban_holder_first_name": 1, "iban_holder_last_name": 1}
        linked_staff = None
        if athlete.get("linked_coach_user_id"):
            linked_staff = await db.users.find_one({"id": athlete["linked_coach_user_id"]}, _bank_proj)
        if not linked_staff:
            linked_staff = await db.users.find_one(
                {"linked_athlete_id": athlete_id, "role": {"$in": ["coach", "dirigente", "collaboratore"]}},
                _bank_proj,
            )
        # 🐛 24/09/2026 — Fallback anche sull'ACCOUNT PROPRIO dell'atleta (role="athlete"):
        # l'atleta 18+ PRO salva i dati bancari dal proprio profilo tramite
        # /users/me/bank-details (record `users`), ma l'admin li legge dal record
        # `athletes`. Se non è dual-role staff, ereditiamo i campi dal suo user.
        if not linked_staff:
            _own_user = await db.users.find_one(
                {"$or": [
                    {"athlete_id": athlete_id},
                    {"user_id": athlete_id},
                    {"linked_athlete_id": athlete_id},
                ]},
                _bank_proj,
            )
            if _own_user and (_own_user.get("iban") or _own_user.get("bank_name") or _own_user.get("account_holder") or _own_user.get("iban_holder")):
                linked_staff = _own_user
        if linked_staff:
            if linked_staff.get("iban"):
                athlete["iban"] = linked_staff["iban"]
            if linked_staff.get("bank_name"):
                athlete["bank_name"] = linked_staff["bank_name"]
            _holder = (
                linked_staff.get("iban_holder")
                or linked_staff.get("account_holder")
                or " ".join([x for x in [linked_staff.get("iban_holder_last_name"), linked_staff.get("iban_holder_first_name")] if x]).strip()
            )
            if _holder and not athlete.get("account_holder"):
                athlete["account_holder"] = _holder
    
    # 🆕 06/09/2026 — Auto-riparazione prova: ricalcola dai record di presenza reali.
    # 12/09/2026: esteso anche alle prove GIÀ avviate, così la fine prova viene
    # anticipata quando si raggiunge il numero massimo di sedute (3/3) anche se la
    # settimana non è ancora finita.
    try:
        _st = athlete.get("status")
        if _st in ("trial", "pending_trial"):
            _tid = athlete.get("team_id")
            if _tid:
                _has_att = await db.attendances.find_one({"athlete_id": athlete_id, "team_id": _tid})
                if _has_att:
                    await _recompute_trial_from_attendance(athlete, _tid)
                    _fresh = await db.athletes.find_one({"id": athlete_id})
                    if _fresh:
                        for _k in ("status", "is_trial", "trial_start_date", "trial_end_date", "trial_sessions_count", "trial_max_sessions"):
                            if _k in _fresh:
                                athlete[_k] = _fresh[_k]
    except Exception as _rep_err:
        logging.getLogger(__name__).warning(f"[trial-autofix] {athlete_id}: {_rep_err}")

    # 🆕 24/08/2026 — Motivo dell'ATTESA (visibile anche a genitore/atleta: sa cosa
    # manca per andare "in attività").
    athlete["pending_reason"] = compute_pending_reason(athlete)
    athlete["stato_display"] = compute_status_badge(athlete)
    
    return Athlete(**athlete)

@api_router.get("/athletes/{athlete_id}/technical-data")
async def get_athlete_technical_data(athlete_id: str, current_user = Depends(get_current_user)):
    """Get only technical data of an athlete - accessible by coach, admin, and parent"""
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    # Get certificate info
    certificate = await db.certificates.find_one({"athlete_id": athlete_id})
    cert_status = None
    cert_expiry = None
    if certificate:
        cert_expiry = certificate.get("expiry_date")
        if cert_expiry:
            expiry_date = datetime.fromisoformat(cert_expiry.replace('Z', '+00:00')) if isinstance(cert_expiry, str) else cert_expiry
            now = datetime.now(expiry_date.tzinfo) if expiry_date.tzinfo else datetime.utcnow()
            if expiry_date < now:
                cert_status = "expired"
            elif expiry_date < now + timedelta(days=30):
                cert_status = "expiring_soon"
            else:
                cert_status = "valid"
    
    # Get parent contact info for emergencies
    parent = await db.users.find_one({"id": athlete.get("parent_id")})
    parent_phone = parent.get("phone") if parent else None
    parent_name = parent.get("full_name") if parent else None
    
    # Also get emergency phone from athlete record
    emergency_phone = athlete.get("emergency_phone")

    # 🆕 01/08/2026 — Statistiche presenze per la vista tecnica del coach.
    # Riusa la stessa logica di /athletes/{id}/my-stats (che è però riservato
    # ad atleta/admin): qui le esponiamo anche al coach per la sua squadra.
    stats = None
    try:
        team_id_stats = athlete.get("team_id")
        training_sessions = []
        if team_id_stats:
            team_doc = await db.teams.find_one({"id": team_id_stats})
            if team_doc:
                training_sessions = team_doc.get("training_sessions", [])
        trainings_per_week = len(training_sessions) if training_sessions else 3
        now_s = datetime.now()
        today_end_s = now_s.replace(hour=23, minute=59, second=59, microsecond=999999)
        week_start_s = (now_s - timedelta(days=now_s.weekday())).replace(hour=0, minute=0, second=0, microsecond=0)
        month_start_s = now_s.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        expected_weekly = count_training_days_in_period(training_sessions, week_start_s, today_end_s) if training_sessions else trainings_per_week
        expected_monthly = count_training_days_in_period(training_sessions, month_start_s, today_end_s) if training_sessions else trainings_per_week * 4
        reg_date_s = athlete.get("registration_date") or athlete.get("created_at") or now_s
        if isinstance(reg_date_s, str):
            reg_date_s = datetime.fromisoformat(reg_date_s.replace('Z', '+00:00')).replace(tzinfo=None)
        expected_total = count_training_days_in_period(training_sessions, reg_date_s, today_end_s) if training_sessions else 10
        expected_total = max(expected_total, 1)
        all_att = await db.attendances.count_documents({"athlete_id": athlete_id})
        week_att = await db.attendances.count_documents({"athlete_id": athlete_id, "check_in_time": {"$gte": week_start_s}})
        month_att = await db.attendances.count_documents({"athlete_id": athlete_id, "check_in_time": {"$gte": month_start_s}})
        games_played = len(athlete.get("game_presences") or [])
        stats = {
            "total_attendances": all_att,
            "weekly_attendances": week_att,
            "monthly_attendances": month_att,
            "weekly_percentage": min(100, round((week_att / max(expected_weekly, 1)) * 100)),
            "monthly_percentage": min(100, round((month_att / max(expected_monthly, 1)) * 100)),
            "total_percentage": min(100, round((all_att / expected_total) * 100)),
            "games_played": games_played,
        }
    except Exception as _stats_err:
        logging.getLogger(__name__).warning(f"[technical-data] stats calc failed for {athlete_id}: {_stats_err}")
        stats = None

    # Return technical data + certificate status + emergency contacts
    return {
        "id": athlete["id"],
        "full_name": athlete.get("full_name"),
        "first_name": athlete.get("first_name"),
        "last_name": athlete.get("last_name"),
        "date_of_birth": athlete.get("date_of_birth"),  # For age calculation only
        "team_id": athlete.get("team_id"),
        "team_id_2": athlete.get("team_id_2"),
        # Athlete code
        "athlete_code": athlete.get("athlete_code"),
        # Technical data
        "athlete_photo": athlete.get("athlete_photo"),
        "athlete_photo_artistic": athlete.get("athlete_photo_artistic"),
        "athlete_role": athlete.get("athlete_role"),
        "athlete_height": athlete.get("athlete_height"),
        "athlete_weight": athlete.get("athlete_weight"),
        "athlete_elevation": athlete.get("athlete_elevation"),
        "athlete_notes": athlete.get("athlete_notes"),
        "athlete_characteristics": athlete.get("athlete_characteristics", []),
        "second_parent_email": athlete.get("second_parent_email"),
        # Certificate info (visible to all)
        "certificate_status": cert_status,
        "certificate_expiry": cert_expiry,
        # Emergency contacts (visible to coach for emergencies)
        "parent_name": parent_name,
        "parent_phone": parent_phone,
        "emergency_phone": emergency_phone,
        # 🆕 01/08/2026 — Statistiche presenze (per coach)
        "stats": stats,
    }

@api_router.patch("/athletes/{athlete_id}/technical-data")
async def update_athlete_technical_data(athlete_id: str, data: dict, current_user = Depends(get_current_user)):
    """Update only technical data of an athlete - accessible by coach and admin"""
    if current_user["role"] not in [UserRole.ADMIN, UserRole.COACH]:
        raise HTTPException(status_code=403, detail="Solo admin e coach possono modificare i dati tecnici")
    
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    # Only allow updating technical fields
    allowed_fields = ["athlete_photo", "athlete_photo_artistic", "athlete_role", 
                      "athlete_height", "athlete_weight", "athlete_elevation", 
                      "athlete_notes", "athlete_characteristics"]
    
    update_dict = {k: v for k, v in data.items() if k in allowed_fields}
    
    if update_dict:
        await db.athletes.update_one(
            {"id": athlete_id},
            {"$set": update_dict}
        )
    
    return {"message": "Dati tecnici aggiornati con successo"}

@api_router.patch("/athletes/{athlete_id}", response_model=Athlete)
async def update_athlete(athlete_id: str, update_data: AthleteUpdate, current_user = Depends(get_current_user)):
    # Lightweight read: skip heavy base64 photo fields when checking permissions
    # and reading existing values. Avoids a ~500KB transfer per PATCH (which on
    # mobile + Render Free tier could time out at ~30s).
    HEAVY_PHOTO_FIELDS = {
        "_id": 0, "athlete_photo": 0, "athlete_photo_artistic": 0,
        "id_back": 0, "id_front": 0, "doc_back_image": 0, "doc_front_image": 0,
        "document_back": 0, "document_front": 0, "medical_certificate_file": 0,
    }
    athlete = await db.athletes.find_one({"id": athlete_id}, HEAVY_PHOTO_FIELDS)
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    # Check permissions - allow primary and second parent
    if current_user["role"] == UserRole.PARENT:
        is_primary = athlete.get("parent_id") == current_user["id"]
        is_second = athlete.get("second_parent_id") == current_user["id"]
        if not is_primary and not is_second:
            raise HTTPException(status_code=403, detail="Accesso negato")
    
    update_dict = {}
    
    # Campi testuali
    # Tesseramento (solo admin)
    if update_data.federal_code is not None:
        update_dict["federal_code"] = update_data.federal_code
    if update_data.is_registered is not None:
        update_dict["is_registered"] = update_data.is_registered
    # Anagrafica
    if update_data.full_name is not None:
        update_dict["full_name"] = update_data.full_name
    if update_data.first_name is not None:
        update_dict["first_name"] = update_data.first_name
    if update_data.last_name is not None:
        update_dict["last_name"] = update_data.last_name
    if update_data.date_of_birth is not None:
        try:
            update_dict["date_of_birth"] = datetime.fromisoformat(update_data.date_of_birth)
        except:
            pass
    if update_data.birth_place is not None:
        update_dict["birth_place"] = update_data.birth_place
    if update_data.birth_province is not None:
        update_dict["birth_province"] = update_data.birth_province
    if update_data.country_of_birth is not None:
        update_dict["country_of_birth"] = update_data.country_of_birth
    if update_data.gender is not None:
        update_dict["gender"] = update_data.gender.upper()  # Store as uppercase M/F
    if update_data.fiscal_code is not None:
        update_dict["fiscal_code"] = update_data.fiscal_code
    if update_data.email is not None:
        update_dict["email"] = update_data.email
    if update_data.phone_athlete is not None:
        update_dict["phone_athlete"] = update_data.phone_athlete
    if update_data.phone_father is not None:
        update_dict["phone_father"] = update_data.phone_father
    if update_data.phone_mother is not None:
        update_dict["phone_mother"] = update_data.phone_mother
    if update_data.address is not None:
        update_dict["address"] = update_data.address
    if update_data.postal_code is not None:
        update_dict["postal_code"] = update_data.postal_code
    if update_data.city is not None:
        update_dict["city"] = update_data.city
    if update_data.province is not None:
        update_dict["province"] = update_data.province
    if update_data.tax_payer_name is not None:
        update_dict["tax_payer_name"] = update_data.tax_payer_name
    if update_data.tax_payer_last_name is not None:
        update_dict["tax_payer_last_name"] = update_data.tax_payer_last_name
    if update_data.tax_payer_first_name is not None:
        update_dict["tax_payer_first_name"] = update_data.tax_payer_first_name
    if update_data.tax_payer_fiscal_code is not None:
        update_dict["tax_payer_fiscal_code"] = update_data.tax_payer_fiscal_code
    if update_data.team_id is not None:
        # Verify team exists
        team = await db.teams.find_one({"id": update_data.team_id})
        if team:
            old_team_id = athlete.get("team_id")
            update_dict["team_id"] = update_data.team_id
            # athlete_code is now qr_identifier (permanent), no need to regenerate on team change
            
            # Create payments when team is assigned (for quota athletes)
            if old_team_id != update_data.team_id and athlete.get("athlete_type") == "quota":
                # 🐛 21/09/2026 — FIX perdita dati/ricevute: eliminare SOLO le rate NON pagate.
                # Prima eliminava TUTTI i pagamenti (anche quelli pagati con numero ricevuta),
                # creando "buchi" nella numerazione ricevute al cambio squadra.
                await db.payments.delete_many({"athlete_id": athlete_id, "paid": {"$ne": True}})
                
                # Create new payments based on team installments
                installments = team.get("installments", [])
                for i, installment in enumerate(installments):
                    payment = {
                        "id": str(uuid.uuid4()),
                        "athlete_id": athlete_id,
                        "society_id": athlete.get("society_id"),
                        "amount": installment.get("amount", 0),
                        "due_date": installment.get("due_date"),
                        "paid_date": None,
                        "status": "pending",
                        "description": installment.get("name", f"Rata {i+1}"),
                        "installment_number": i + 1,
                        "created_at": datetime.utcnow()
                    }
                    await db.payments.insert_one(payment)
    
    # Manual athlete_code override (takes priority over auto-generated)
    if update_data.athlete_code is not None:
        if update_data.athlete_code.strip():
            # Verify uniqueness within society
            athlete = await db.athletes.find_one({"id": athlete_id})
            if athlete:
                existing = await db.athletes.find_one({
                    "athlete_code": update_data.athlete_code.upper().strip(),
                    "society_id": athlete.get("society_id"),
                    "id": {"$ne": athlete_id}
                })
                if existing:
                    raise HTTPException(
                        status_code=400,
                        detail=f"Codice atleta '{update_data.athlete_code}' già in uso da un altro atleta"
                    )
                update_dict["athlete_code"] = update_data.athlete_code.upper().strip()
    
    # 🆕 08/07/2026 — Nuovo array team_ids (canonical). Se presente sovrascrive team_id/team_id_2 e viceversa
    # per backward compatibility popoliamo sempre entrambi (team_ids + team_id/team_id_2).
    if update_data.team_ids is not None:
        # Deduplica preservando l'ordine e filtra stringhe vuote
        seen = set()
        deduped_ids = []
        for tid in update_data.team_ids:
            if tid and tid not in seen:
                seen.add(tid)
                deduped_ids.append(tid)
        # Verifica che tutte le squadre esistano
        if deduped_ids:
            existing_teams = await db.teams.find(
                {"id": {"$in": deduped_ids}},
                {"_id": 0, "id": 1}
            ).to_list(100)
            existing_ids = {t["id"] for t in existing_teams}
            deduped_ids = [tid for tid in deduped_ids if tid in existing_ids]

        update_dict["team_ids"] = deduped_ids
        # Sync legacy fields
        old_team_id = athlete.get("team_id")
        new_primary = deduped_ids[0] if len(deduped_ids) > 0 else None
        new_secondary = deduped_ids[1] if len(deduped_ids) > 1 else None
        update_dict["team_id"] = new_primary
        update_dict["team_id_2"] = new_secondary

        # Ricrea pagamenti se la squadra principale è cambiata (per atleti quota)
        if old_team_id != new_primary and athlete.get("athlete_type") == "quota" and new_primary:
            primary_team = await db.teams.find_one({"id": new_primary})
            if primary_team:
                # 🐛 21/09/2026 — FIX: preservare i pagamenti già incassati (e le ricevute).
                # Elimina solo le rate NON pagate prima di ricreare lo scadenzario.
                await db.payments.delete_many({"athlete_id": athlete_id, "paid": {"$ne": True}})
                installments = primary_team.get("installments", [])
                for i, installment in enumerate(installments):
                    payment = {
                        "id": str(uuid.uuid4()),
                        "athlete_id": athlete_id,
                        "society_id": athlete.get("society_id"),
                        "amount": installment.get("amount", 0),
                        "due_date": installment.get("due_date"),
                        "paid_date": None,
                        "status": "pending",
                        "description": installment.get("name", f"Rata {i+1}"),
                        "installment_number": i + 1,
                        "created_at": datetime.utcnow()
                    }
                    await db.payments.insert_one(payment)

    # Seconda squadra (opzionale) — LEGACY path (usato solo se team_ids NON è stato inviato)
    elif update_data.team_id_2 is not None:
        if update_data.team_id_2 == "":
            # Remove secondary team
            update_dict["team_id_2"] = None
        else:
            # Verify team exists
            team2 = await db.teams.find_one({"id": update_data.team_id_2})
            if team2:
                update_dict["team_id_2"] = update_data.team_id_2
    
    # Sconto
    if update_data.discount_amount is not None:
        update_dict["discount_amount"] = update_data.discount_amount
    if update_data.discount_reason is not None:
        update_dict["discount_reason"] = update_data.discount_reason
    if update_data.discount_note is not None:
        update_dict["discount_note"] = update_data.discount_note
    
    # Dati tecnici atleta (solo admin e coach)
    if current_user["role"] in [UserRole.ADMIN, UserRole.COACH]:
        if update_data.athlete_role is not None:
            update_dict["athlete_role"] = update_data.athlete_role
        if update_data.athlete_height is not None:
            update_dict["athlete_height"] = update_data.athlete_height
        if update_data.athlete_weight is not None:
            update_dict["athlete_weight"] = update_data.athlete_weight
        if update_data.athlete_elevation is not None:
            update_dict["athlete_elevation"] = update_data.athlete_elevation
        if update_data.athlete_notes is not None:
            update_dict["athlete_notes"] = update_data.athlete_notes

    # Email secondo genitore (accessibile da admin, coach e parent)
    if update_data.second_parent_email is not None:
        new_email = update_data.second_parent_email.lower().strip() if update_data.second_parent_email else None
        update_dict["second_parent_email"] = new_email
        
        # Se c'è un'email, cerca se esiste un utente con questa email e collegalo
        if new_email:
            # Trova l'atleta per ottenere la society_id
            athlete = await db.athletes.find_one({"id": athlete_id})
            if athlete:
                # Cerca l'utente genitore con questa email nella stessa società
                second_parent = await db.users.find_one({
                    "email": new_email,
                    "society_id": athlete.get("society_id"),
                    "role": UserRole.PARENT
                })
                if second_parent:
                    update_dict["second_parent_id"] = second_parent["id"]
                    
                    # === CROSS-LINKING BIDIREZIONALE ===
                    # Se il partner (second_parent) ha atleti dove second_parent_email = email del genitore corrente,
                    # collega anche quelli
                    current_parent = await db.users.find_one({"id": current_user["id"]})
                    if current_parent:
                        current_email = current_parent.get("email", "").lower()
                        if current_email:
                            await db.athletes.update_many(
                                {
                                    "parent_id": second_parent["id"],
                                    "second_parent_email": current_email,
                                    "second_parent_id": {"$in": [None, ""]},
                                },
                                {"$set": {"second_parent_id": current_user["id"]}}
                            )
                else:
                    # Nessun utente trovato, rimuovi l'ID precedente
                    update_dict["second_parent_id"] = None
        else:
            # Email rimossa, rimuovi anche l'ID
            update_dict["second_parent_id"] = None
    
    # Campi booleani
    if update_data.privacy_accepted is not None:
        update_dict["privacy_accepted"] = update_data.privacy_accepted
        if update_data.privacy_accepted:
            update_dict["privacy_accepted_date"] = datetime.utcnow()
    
    if update_data.image_consent is not None:
        update_dict["image_consent"] = update_data.image_consent
    
    # Status
    if update_data.status is not None:
        if update_data.status in ["trial", "active", "blocked"]:
            update_dict["status"] = update_data.status
    
    # Ritiro atleta (solo admin)
    if update_data.is_withdrawn is not None and current_user["role"] == UserRole.ADMIN:
        update_dict["is_withdrawn"] = update_data.is_withdrawn
        if update_data.is_withdrawn:
            update_dict["withdrawn_date"] = datetime.utcnow()
            if update_data.withdrawn_reason:
                update_dict["withdrawn_reason"] = update_data.withdrawn_reason
    
    # Certificato medico (admin, viewer/dirigente, athlete)
    if update_data.medical_certificate_date is not None:
        try:
            dt = datetime.fromisoformat(update_data.medical_certificate_date.replace('Z', '+00:00'))
            update_dict["medical_certificate_date"] = dt.isoformat()
        except:
            update_dict["medical_certificate_date"] = update_data.medical_certificate_date
        now = datetime.utcnow()
        update_dict["medical_certificate_updated_by"] = current_user["id"]
        update_dict["medical_certificate_updated_by_name"] = current_user.get("full_name", "")
        update_dict["medical_certificate_updated_by_role"] = current_user.get("role", "")
        update_dict["medical_certificate_updated_at"] = now.isoformat()
    if update_data.medical_certificate_expiry is not None:
        try:
            dt = datetime.fromisoformat(update_data.medical_certificate_expiry.replace('Z', '+00:00'))
            update_dict["medical_certificate_expiry"] = dt.isoformat()
        except:
            update_dict["medical_certificate_expiry"] = update_data.medical_certificate_expiry
    
    if update_dict:
        # 🆕 08/07/2026 — Sincronizza sempre team_ids in linea con team_id/team_id_2 se non fornito esplicitamente
        # (garantisce la coerenza anche quando arrivano richieste legacy che modificano solo team_id o team_id_2).
        if "team_ids" not in update_dict and ("team_id" in update_dict or "team_id_2" in update_dict):
            new_primary = update_dict.get("team_id", athlete.get("team_id"))
            new_secondary = update_dict.get("team_id_2", athlete.get("team_id_2"))
            synced_ids = []
            for tid in [new_primary, new_secondary]:
                if tid and tid not in synced_ids:
                    synced_ids.append(tid)
            update_dict["team_ids"] = synced_ids

        await db.athletes.update_one({"id": athlete_id}, {"$set": update_dict})
        athlete.update(update_dict)
    
    # Check end-trial auto-activation when privacy is accepted
    if update_data.privacy_accepted and athlete.get("end_trial_requested"):
        activated = await check_and_activate_if_ready(athlete_id)
        if activated:
            athlete["status"] = "active"
            athlete["is_trial"] = False
    # 🆕 MINORENNI in prova: attivazione automatica se privacy + certificato ok
    if update_dict and athlete.get("status") != "active":
        if await maybe_activate_minor_athlete(athlete_id, current_user):
            athlete["status"] = "active"
            athlete["is_trial"] = False
    
    return Athlete(**athlete)

# ==================== DATA PASSWORD ENDPOINTS ====================

class VerifyDataPassword(BaseModel):
    password: str

class ChangeDataPassword(BaseModel):
    old_password: Optional[str] = None  # Opzionale solo se non esiste password
    new_password: str

@api_router.post("/athletes/{athlete_id}/verify-password")
async def verify_data_password(athlete_id: str, data: VerifyDataPassword, current_user = Depends(get_current_user)):
    """Verify data password for an athlete - each parent has their own password"""
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    # Determine which parent is requesting
    is_primary = athlete.get("parent_id") == current_user["id"]
    is_second = athlete.get("second_parent_id") == current_user["id"]
    
    if current_user["role"] == UserRole.PARENT:
        if not is_primary and not is_second:
            raise HTTPException(status_code=403, detail="Accesso negato")
    
    # Select the correct password hash based on which parent
    if is_second:
        pw_hash = athlete.get("second_parent_data_password_hash") or athlete.get("data_password_hash")
    else:
        pw_hash = athlete.get("data_password_hash")
    
    # If no password is set for this parent, they need to set one
    if not pw_hash:
        return {"verified": False, "has_password": False, "needs_setup": True}
    
    is_valid = verify_password(data.password, pw_hash)
    return {"verified": is_valid, "has_password": True, "needs_setup": False}

@api_router.post("/athletes/{athlete_id}/change-password")
async def change_data_password(athlete_id: str, data: ChangeDataPassword, current_user = Depends(get_current_user)):
    """Change or set data password for an athlete - each parent has their own"""
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    is_primary = athlete.get("parent_id") == current_user["id"]
    is_second = athlete.get("second_parent_id") == current_user["id"]
    
    if current_user["role"] != UserRole.PARENT:
        raise HTTPException(status_code=403, detail="Solo il genitore può modificare la password")
    if not is_primary and not is_second:
        raise HTTPException(status_code=403, detail="Solo il genitore può modificare la password")
    
    # Determine which password field to use
    pw_field = "second_parent_data_password_hash" if is_second else "data_password_hash"
    
    # Hash and set new password (no need to verify old password - parent is already authenticated)
    new_hash = hash_password(data.new_password)
    await db.athletes.update_one(
        {"id": athlete_id},
        {"$set": {pw_field: new_hash}}
    )
    
    return {"message": "Password dati aggiornata con successo"}

@api_router.get("/athletes/{athlete_id}/has-password")
async def check_has_password(athlete_id: str, current_user = Depends(get_current_user)):
    """Check if athlete has a data password set for the current parent"""
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    is_second = athlete.get("second_parent_id") == current_user["id"]
    
    if is_second:
        # Check second parent's own field first, fallback to shared field
        has_pw = bool(athlete.get("second_parent_data_password_hash") or athlete.get("data_password_hash"))
    else:
        has_pw = bool(athlete.get("data_password_hash"))
    
    return {"has_password": has_pw}

@api_router.get("/athletes/{athlete_id}/parents-info")
async def get_parents_info(athlete_id: str, current_user = Depends(get_current_user)):
    """Admin gets info about both parents of a minor athlete, including data password status"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")
    
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    parents = []
    
    # Primary parent
    parent_id = athlete.get("parent_id")
    if parent_id:
        parent_user = await db.users.find_one({"id": parent_id}, {"_id": 0, "id": 1, "full_name": 1, "email": 1, "phone": 1})
        if parent_user:
            parents.append({
                "type": "primary",
                "id": parent_user["id"],
                "full_name": parent_user.get("full_name", ""),
                "email": parent_user.get("email", ""),
                "phone": parent_user.get("phone", ""),
                "has_data_password": bool(athlete.get("data_password_hash")),
            })
    
    # Second parent
    second_parent_id = athlete.get("second_parent_id")
    if second_parent_id:
        second_parent_user = await db.users.find_one({"id": second_parent_id}, {"_id": 0, "id": 1, "full_name": 1, "email": 1, "phone": 1})
        if second_parent_user:
            parents.append({
                "type": "second",
                "id": second_parent_user["id"],
                "full_name": second_parent_user.get("full_name", ""),
                "email": second_parent_user.get("email", ""),
                "phone": second_parent_user.get("phone", ""),
                "has_data_password": bool(athlete.get("second_parent_data_password_hash")),
            })
    elif athlete.get("second_parent_email"):
        # 🐛 20/07/2026 — Non duplicare la card "non ancora registrato" se
        # l'email del "secondo genitore" coincide con quella del genitore
        # primario (caso classico: admin ha collegato il genitore che è già
        # registrato ma lo ritrova come "secondo genitore email" del vecchio
        # flusso di preiscrizione).
        second_email = (athlete.get("second_parent_email") or "").strip().lower()
        primary_email = parents[0]["email"].strip().lower() if parents else ""
        if second_email and second_email != primary_email:
            # Second parent email set but not yet registered
            parents.append({
                "type": "second",
                "id": None,
                "full_name": "(non ancora registrato)",
                "email": athlete.get("second_parent_email", ""),
                "phone": "",
                "has_data_password": False,
                "not_registered": True,
            })
    
    return parents

class AdminResetDataPassword(BaseModel):
    parent_type: str  # "primary" or "second" - which parent's password to reset

@api_router.patch("/athletes/{athlete_id}/reset-data-password")
async def admin_reset_data_password(athlete_id: str, data: AdminResetDataPassword, current_user = Depends(get_current_user)):
    """Admin resets (deletes) a specific parent's data password. The parent will set a new one at next access."""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può resettare la password dati")
    
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    if data.parent_type == "second":
        pw_field = "second_parent_data_password_hash"
        parent_id = athlete.get("second_parent_id")
    else:
        pw_field = "data_password_hash"
        parent_id = athlete.get("parent_id")
    
    # Get parent name for the response
    parent_name = "Genitore"
    if parent_id:
        parent_user = await db.users.find_one({"id": parent_id})
        if parent_user:
            parent_name = parent_user.get("full_name", "Genitore")
    
    # Delete the password (set to None) - parent will be prompted to create a new one
    await db.athletes.update_one(
        {"id": athlete_id},
        {"$unset": {pw_field: ""}}
    )
    
    return {"message": f"Password dati cancellata per {parent_name}. Al prossimo accesso dovrà impostarne una nuova."}


# --- Self-service data password reset (parent) ---
class RequestDataPasswordResetRequest(BaseModel):
    athlete_id: str  # The minor athlete whose data password to reset

@api_router.post("/auth/request-data-password-reset")
async def request_data_password_reset(data: RequestDataPasswordResetRequest, current_user = Depends(get_current_user)):
    """Parent requests a verification code to reset their own data password for a minor."""
    if current_user["role"] != UserRole.PARENT:
        raise HTTPException(status_code=403, detail="Solo genitori possono resettare la propria password dati")
    
    athlete = await db.athletes.find_one({"id": data.athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    # Verify parent is linked to this athlete
    is_primary = athlete.get("parent_id") == current_user["id"]
    is_second = athlete.get("second_parent_id") == current_user["id"]
    if not is_primary and not is_second:
        raise HTTPException(status_code=403, detail="Non sei un genitore di questo atleta")
    
    # Generate verification code (6 digits)
    import random
    verification_code = str(random.randint(100000, 999999))
    code_expires = datetime.utcnow() + timedelta(minutes=15)
    
    # Store code in user record
    await db.users.update_one(
        {"id": current_user["id"]},
        {"$set": {
            "data_pw_reset_code": verification_code,
            "data_pw_reset_expires": code_expires,
            "data_pw_reset_athlete_id": data.athlete_id
        }}
    )
    
    # Send email with code
    try:
        from email_service import send_transactional_email
        athlete_name = f"{athlete.get('first_name', '')} {athlete.get('last_name', '')}".strip()
        await send_transactional_email(
            to_email=current_user["email"],
            to_name=current_user.get("full_name", "Genitore"),
            subject=f"Codice reset password dati - {athlete_name}",
            html_content=f"""
            <p>Ciao {current_user.get('full_name', 'Genitore')},</p>
            <p>Hai richiesto il reset della password dati per <strong>{athlete_name}</strong>.</p>
            <p>Il tuo codice di verifica è:</p>
            <h2 style="text-align:center; color:#7B1FA2; font-size:32px; letter-spacing:8px;">{verification_code}</h2>
            <p>Il codice scade tra 15 minuti.</p>
            <p>Se non hai richiesto tu questo reset, ignora questa email.</p>
            """
        )
    except Exception as e:
        logging.error(f"Failed to send data pw reset email: {str(e)}")
        raise HTTPException(status_code=500, detail="Errore nell'invio dell'email")
    
    return {"message": f"Codice di verifica inviato a {current_user['email']}"}


class ConfirmDataPasswordResetRequest(BaseModel):
    athlete_id: str
    verification_code: str
    new_password: str

@api_router.post("/auth/confirm-data-password-reset")
async def confirm_data_password_reset(data: ConfirmDataPasswordResetRequest, current_user = Depends(get_current_user)):
    """Verify code and set new data password."""
    if current_user["role"] != UserRole.PARENT:
        raise HTTPException(status_code=403, detail="Solo genitori")
    
    user = await db.users.find_one({"id": current_user["id"]})
    stored_code = user.get("data_pw_reset_code")
    code_expires = user.get("data_pw_reset_expires")
    stored_athlete_id = user.get("data_pw_reset_athlete_id")
    
    if not stored_code or not code_expires:
        raise HTTPException(status_code=400, detail="Nessuna richiesta di reset trovata. Richiedi un nuovo codice.")
    
    if datetime.utcnow() > code_expires:
        await db.users.update_one({"id": current_user["id"]}, {"$unset": {"data_pw_reset_code": "", "data_pw_reset_expires": "", "data_pw_reset_athlete_id": ""}})
        raise HTTPException(status_code=400, detail="Codice scaduto. Richiedi un nuovo codice.")
    
    if data.verification_code.strip() != stored_code:
        raise HTTPException(status_code=400, detail="Codice non valido")
    
    if stored_athlete_id != data.athlete_id:
        raise HTTPException(status_code=400, detail="Richiesta non valida")
    
    if len(data.new_password) < 4:
        raise HTTPException(status_code=400, detail="La password deve avere almeno 4 caratteri")
    
    # Determine which field to update
    athlete = await db.athletes.find_one({"id": data.athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    is_primary = athlete.get("parent_id") == current_user["id"]
    pw_field = "data_password_hash" if is_primary else "second_parent_data_password_hash"
    
    # Update the password
    new_hash = hash_password(data.new_password)
    await db.athletes.update_one(
        {"id": data.athlete_id},
        {"$set": {pw_field: new_hash}}
    )
    
    # Clear reset code
    await db.users.update_one(
        {"id": current_user["id"]},
        {"$unset": {"data_pw_reset_code": "", "data_pw_reset_expires": "", "data_pw_reset_athlete_id": ""}}
    )
    
    return {"message": "Password dati aggiornata con successo"}



class CreateAthleteAccountRequest(BaseModel):
    password: str

@api_router.post("/athletes/{athlete_id}/create-account")
async def create_athlete_account(athlete_id: str, data: CreateAthleteAccountRequest, current_user = Depends(get_current_user)):
    """Create a user account for a compensated athlete so they can login and sign receipts"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può creare account atleta")
    
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    # Only compensated athletes need accounts
    if athlete.get("athlete_type") != "compensated":
        raise HTTPException(status_code=400, detail="Solo gli atleti retribuiti necessitano di un account")
    
    # Check if email exists
    email = athlete.get("email")
    if not email:
        raise HTTPException(status_code=400, detail="L'atleta deve avere un'email per creare un account")
    
    # Check if user already exists
    existing_user = await db.users.find_one({"email": email})
    if existing_user:
        # If user exists but is not linked to this athlete, update it
        if existing_user.get("role") != "athlete" or existing_user.get("athlete_id") != athlete_id:
            await db.users.update_one(
                {"email": email},
                {"$set": {"role": "athlete", "athlete_id": athlete_id}}
            )
            return {"message": "Account esistente aggiornato come atleta", "user_id": existing_user["id"]}
        else:
            raise HTTPException(status_code=400, detail="L'atleta ha già un account")
    
    # Create new user
    user_id = str(ObjectId())
    password_hash = hash_password(data.password)
    
    user_dict = {
        "id": user_id,
        "email": email,
        "password_hash": password_hash,
        "role": "athlete",
        "athlete_id": athlete_id,
        "first_name": athlete.get("first_name", ""),
        "last_name": athlete.get("last_name", ""),
        "full_name": athlete.get("full_name", ""),
        "society_id": athlete.get("society_id"),
        "is_approved": True,  # Auto-approved
        "created_at": datetime.utcnow(),
    }
    
    await db.users.insert_one(user_dict)
    
    return {"message": "Account atleta creato con successo", "user_id": user_id, "email": email}


class UploadMedicalCertificateRequest(BaseModel):
    certificate_base64: str
    expiry_date: str  # formato ISO: YYYY-MM-DD

@api_router.post("/athletes/upload-medical-certificate")
async def upload_medical_certificate(data: UploadMedicalCertificateRequest, current_user = Depends(get_current_user)):
    """Allow athletes to upload their own medical certificate"""
    # Get athlete_id from current user
    athlete_id = current_user.get("athlete_id")
    if not athlete_id:
        raise HTTPException(status_code=403, detail="Solo atleti possono caricare il proprio certificato")
    
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    # Validate base64 data
    if not data.certificate_base64:
        raise HTTPException(status_code=400, detail="Certificato non fornito")
    
    # Parse and validate expiry date
    try:
        expiry_date = datetime.fromisoformat(data.expiry_date)
    except:
        raise HTTPException(status_code=400, detail="Formato data non valido. Usa YYYY-MM-DD")
    
    # Calculate issue date (12 months before expiry for standard certificates)
    issue_date = expiry_date - timedelta(days=365)
    
    # Archive the certificate for 5-year retention (legal requirement for ASD/SSD)
    archive_entry = {
        "id": str(uuid.uuid4()),
        "athlete_id": athlete_id,
        "last_name": athlete.get("last_name", ""),
        "first_name": athlete.get("first_name", ""),
        "full_name": athlete.get("full_name", f"{athlete.get('last_name', '')} {athlete.get('first_name', '')}"),
        "team_id": athlete.get("team_id"),
        "team_name": athlete.get("team_name"),
        "issue_date": issue_date.isoformat(),
        "expiry_date": expiry_date.isoformat(),
        "certificate_data": data.certificate_base64,
        "uploaded_at": datetime.utcnow().isoformat(),
        "uploaded_by": "athlete",
        "society_id": athlete.get("society_id")
    }
    await db.medical_certificates_archive.insert_one(archive_entry)
    
    # Update athlete record
    await db.athletes.update_one(
        {"id": athlete_id},
        {"$set": {
            "medical_certificate_url": data.certificate_base64,
            "medical_certificate_expiry": expiry_date.isoformat()
        }}
    )
    
    return {"message": "Certificato medico caricato con successo", "expiry_date": expiry_date.isoformat()}


# ===================== MEDICAL CERTIFICATES ARCHIVE (5-year retention) =====================

@api_router.get("/admin/medical-certificates-archive")
async def get_medical_certificates_archive(
    page: int = 1,
    limit: int = 50,
    search: str = None,
    current_user = Depends(get_current_user)
):
    """Get archived medical certificates for admin (5-year retention for ASD/SSD compliance)"""
    if current_user["role"] not in [UserRole.ADMIN, UserRole.VIEWER, UserRole.COORDINATORE]:
        raise HTTPException(status_code=403, detail="Accesso riservato agli amministratori")
    
    _sid = current_user.get("society_id")
    query = {}
    if _sid:
        query["society_id"] = _sid
    if search:
        search_regex = {"$regex": search, "$options": "i"}
        query["$or"] = [
            {"last_name": search_regex},
            {"first_name": search_regex},
            {"full_name": search_regex}
        ]
    
    total = await db.medical_certificates_archive.count_documents(query)
    skip = (page - 1) * limit
    
    certificates = await db.medical_certificates_archive.find(
        query,
        {"certificate_data": 0}  # Exclude base64 data for listing
    ).sort("uploaded_at", -1).skip(skip).limit(limit).to_list(limit)
    
    clean_mongo_docs(certificates)
    
    return {
        "certificates": certificates,
        "total": total,
        "page": page,
        "pages": (total + limit - 1) // limit
    }


@api_router.get("/admin/medical-certificates-archive/stats")
async def get_certificates_archive_stats(current_user = Depends(get_current_user)):
    """Get statistics about archived certificates"""
    if current_user["role"] not in [UserRole.ADMIN, UserRole.VIEWER, UserRole.COORDINATORE]:
        raise HTTPException(status_code=403, detail="Accesso riservato agli amministratori")
    
    _sid = current_user.get("society_id")
    _q = {"society_id": _sid} if _sid else {}
    total = await db.medical_certificates_archive.count_documents(_q)
    
    # Count by year (scoped to society)
    pipeline = [
        {"$match": _q},
        {
            "$group": {
                "_id": {"$substr": ["$uploaded_at", 0, 4]},
                "count": {"$sum": 1}
            }
        },
        {"$sort": {"_id": -1}}
    ]
    by_year = await db.medical_certificates_archive.aggregate(pipeline).to_list(10)
    
    return {
        "total_certificates": total,
        "by_year": {item["_id"]: item["count"] for item in by_year}
    }


@api_router.get("/admin/certificates-expiry-list")
async def get_certificates_expiry_list(
    search: str = None,
    current_user = Depends(get_current_user)
):
    """🆕 09/08/2026 — Scadenzario certificati medici.
    Per privacy NON archiviamo le immagini dei certificati, quindi l'Archivio
    risultava vuoto. Questo endpoint restituisce l'elenco degli atleti con i
    metadati del certificato (data scadenza) ordinato per scadenza crescente,
    con nome atleta e squadra. Utile a admin/dirigente/coordinatore.
    """
    if current_user["role"] not in [UserRole.ADMIN, UserRole.VIEWER, UserRole.DIRIGENTE, UserRole.COORDINATORE]:
        raise HTTPException(status_code=403, detail="Accesso riservato")

    _sid = current_user.get("society_id")
    query = {"status": {"$nin": ["rejected", "withdrawn", "removed", "deleted"]}, "is_withdrawn": {"$ne": True}}
    if _sid:
        query["society_id"] = _sid

    athletes = await db.athletes.find(query).to_list(2000)

    # Mappa squadre → nome
    team_ids = set()
    for a in athletes:
        for k in ("team_id", "team_id_2"):
            if a.get(k):
                team_ids.add(a[k])
        for tid in (a.get("team_ids") or []):
            if tid:
                team_ids.add(tid)
    teams_map = {}
    if team_ids:
        tq = {"id": {"$in": list(team_ids)}}
        async for t in db.teams.find(tq, {"id": 1, "name": 1}):
            teams_map[t["id"]] = t.get("name", "")

    now = datetime.utcnow().replace(hour=0, minute=0, second=0, microsecond=0)

    def _parse(dt):
        if not dt:
            return None
        try:
            if isinstance(dt, str):
                return datetime.fromisoformat(dt.replace('Z', '+00:00')).replace(tzinfo=None)
            if isinstance(dt, datetime):
                return dt.replace(tzinfo=None)
        except Exception:
            return None
        return None

    with_cert = []
    without_cert = []
    for a in athletes:
        last = (a.get("last_name") or "").strip()
        first = (a.get("first_name") or "").strip()
        full = f"{last} {first}".strip() or (a.get("full_name") or "").strip()
        if search:
            s = search.lower()
            if s not in full.lower():
                continue
        # Nome squadra (primo team disponibile)
        team_name = ""
        for k in ("team_id", "team_id_2"):
            if a.get(k) and teams_map.get(a[k]):
                team_name = teams_map[a[k]]
                break
        if not team_name:
            for tid in (a.get("team_ids") or []):
                if teams_map.get(tid):
                    team_name = teams_map[tid]
                    break

        expiry = _parse(a.get("medical_certificate_expiry"))
        issue = _parse(a.get("medical_certificate_date"))
        verified = bool(a.get("medical_certificate_verified"))

        row = {
            "athlete_id": a.get("id"),
            "full_name": full,
            "team_name": team_name,
            "issue_date": issue.isoformat() if issue else None,
            "expiry_date": expiry.isoformat() if expiry else None,
            "verified": verified,
        }
        if expiry:
            days = (expiry - now).days
            row["days_until_expiry"] = days
            if days < 0:
                row["status"] = "expired"
            elif days <= 30:
                row["status"] = "expiring"
            else:
                row["status"] = "valid"
            with_cert.append(row)
        else:
            row["days_until_expiry"] = None
            row["status"] = "missing"
            without_cert.append(row)

    with_cert.sort(key=lambda x: x["expiry_date"])
    without_cert.sort(key=lambda x: x["full_name"].lower())
    items = with_cert + without_cert

    return {
        "items": items,
        "total": len(items),
        "count_expired": sum(1 for r in with_cert if r["status"] == "expired"),
        "count_expiring": sum(1 for r in with_cert if r["status"] == "expiring"),
        "count_valid": sum(1 for r in with_cert if r["status"] == "valid"),
        "count_missing": len(without_cert),
    }


