class SelfDeleteTrialBody(BaseModel):
    reason: Optional[str] = None


@api_router.post("/athletes/{athlete_id}/self-delete-trial")
async def self_delete_trial_athlete(athlete_id: str, request: Request, preview: bool = False, payload: Optional[SelfDeleteTrialBody] = None, current_user = Depends(get_current_user)):
    """🆕 06/09/2026 — Cancellazione IMMEDIATA e irreversibile di un atleta IN PROVA
    da parte del genitore (o atleta adulto in prova). Consentita SOLO se l'atleta è
    in prova/attesa-prova e NON ha obblighi (pagamenti da saldare, documenti fiscali,
    compensi). Elimina tutti i dati; se il genitore resta senza figli e senza obblighi
    elimina anche il suo account. Tracciato negli audit log."""
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")

    # Permessi: genitore collegato o atleta adulto proprietario
    is_parent = current_user["role"] == UserRole.PARENT and (
        athlete.get("parent_id") == current_user["id"] or athlete.get("second_parent_id") == current_user["id"]
    )
    is_self_adult = athlete.get("user_id") == current_user["id"]
    if not (is_parent or is_self_adult):
        raise HTTPException(status_code=403, detail="Accesso negato")

    # Solo durante il periodo di prova (o attesa prova)
    status = athlete.get("status")
    if status not in ("trial", "pending_trial"):
        raise HTTPException(status_code=400, detail="Cancellazione rapida disponibile solo durante il periodo di prova")

    society_id = athlete.get("society_id")
    athlete_name = athlete.get("full_name") or f"{athlete.get('first_name','')} {athlete.get('last_name','')}".strip()
    parent_id = athlete.get("parent_id")
    reason = (payload.reason if payload else None) or ""
    reason = reason.strip()

    # Email genitore + dati società catturati PRIMA della cancellazione (per email di addio)
    parent_email = None
    parent_name = None
    if parent_id:
        _p = await db.users.find_one({"id": parent_id}, {"_id": 0, "email": 1, "full_name": 1})
        if _p:
            parent_email = _p.get("email")
            parent_name = _p.get("full_name")
    society_doc = await db.settings.find_one({"type": "society", "society_id": society_id}) if society_id else await db.settings.find_one({"type": "society"})
    society_name = (society_doc or {}).get("name") if society_doc else None

    # Nessun obbligo: pagamenti non saldati, documenti fiscali, compensi
    fiscal_doc_types = ["ricevuta", "receipt", "fattura", "invoice", "fiscal"]
    unpaid = await db.payments.count_documents({"athlete_id": athlete_id, "paid": {"$ne": True}})
    fiscal_docs = await db.signed_documents.count_documents({"related_entity_id": athlete_id, "document_type": {"$in": fiscal_doc_types}})
    comps = await db.collaboratore_compensations.count_documents({"collaboratore_id": athlete_id})
    if unpaid > 0 or fiscal_docs > 0 or comps > 0:
        raise HTTPException(status_code=400, detail="Cancellazione rapida non disponibile: risultano pagamenti o documenti da gestire. Contatta la società.")

    # Conta i dati che verranno eliminati (per il riepilogo nell'email)
    n_att = await db.attendances.count_documents({"athlete_id": athlete_id})
    n_docs = await db.signed_documents.count_documents({"related_entity_id": athlete_id})
    n_cert = await db.certificates.count_documents({"athlete_id": athlete_id})

    # 🛡️ Anteprima di sicurezza (dry-run): con ?preview=1 ritorna il riepilogo
    # di ciò che verrebbe eliminato SENZA eseguire alcuna cancellazione.
    parent_will_be_deleted = False
    if parent_id:
        remaining_preview = await db.athletes.count_documents({"$or": [{"parent_id": parent_id}, {"second_parent_id": parent_id}]})
        if remaining_preview <= 1:
            p_fiscal_prev = await db.signed_documents.count_documents({"signer_id": parent_id, "document_type": {"$in": fiscal_doc_types}})
            p_comp_prev = await db.collaboratore_compensations.count_documents({"collaboratore_id": parent_id})
            parent_will_be_deleted = (p_fiscal_prev == 0 and p_comp_prev == 0)
    if preview:
        return {
            "preview": True,
            "athlete_name": athlete_name,
            "attendances_count": n_att,
            "documents_count": n_docs,
            "certificates_count": n_cert,
            "parent_will_be_deleted": parent_will_be_deleted,
        }

    # Registra il MOTIVO di uscita (statistiche società), l'atleta viene poi eliminato
    try:
        await db.deletion_reasons.insert_one({
            "id": str(ObjectId()),
            "society_id": society_id,
            "athlete_name": athlete_name,
            "reason": reason,
            "context": "trial_leave",
            "created_at": datetime.now(timezone.utc).isoformat(),
        })
    except Exception:
        pass

    # Elimina tutti i dati dell'atleta
    await db.signed_documents.delete_many({"related_entity_id": athlete_id})
    await db.certificates.delete_many({"athlete_id": athlete_id})
    await db.attendances.delete_many({"athlete_id": athlete_id})
    await db.payments.delete_many({"athlete_id": athlete_id})

    await log_audit(
        action="deletion_approved",
        user_id=current_user["id"],
        user_email=current_user.get("email", ""),
        society_id=society_id or "",
        target_user_id=athlete_id,
        target_user_name=athlete_name,
        ip_address=get_real_ip(request),
        details={
            "executor_name": current_user.get("full_name", ""),
            "executor_role": current_user.get("role", ""),
            "athlete_name": athlete_name,
            "self_service": True,
            "trial_leave": True,
            "reason": reason,
        }
    )

    await db.athletes.delete_one({"id": athlete_id})

    # Elimina account genitore se rimasto senza figli e senza obblighi
    parent_deleted = False
    if parent_id:
        remaining = await db.athletes.count_documents({"$or": [{"parent_id": parent_id}, {"second_parent_id": parent_id}]})
        if remaining == 0:
            p_fiscal = await db.signed_documents.count_documents({"signer_id": parent_id, "document_type": {"$in": fiscal_doc_types}})
            p_comp = await db.collaboratore_compensations.count_documents({"collaboratore_id": parent_id})
            if p_fiscal == 0 and p_comp == 0:
                await db.users.delete_one({"id": parent_id})
                await db.signed_documents.delete_many({"signer_id": parent_id})
                parent_deleted = True

    # 🆕 Email di addio con riepilogo dei dati eliminati
    if parent_email:
        try:
            from email_service import send_society_email
            _sn = society_name or "la Società"
            html = f"""
            <div style="font-family:Arial,sans-serif;color:#222;">
              <h2 style="color:#1565C0;">Conferma cancellazione dati</h2>
              <p>Ciao {parent_name or ''},</p>
              <p>Come richiesto, al termine del periodo di prova abbiamo eliminato definitivamente
              tutti i dati dell'atleta <strong>{athlete_name}</strong> da {_sn}.</p>
              <p style="margin-top:12px;"><strong>Riepilogo dati eliminati:</strong></p>
              <ul>
                <li>Scheda anagrafica dell'atleta</li>
                <li>{n_att} presenze/registrazioni allenamenti</li>
                <li>{n_cert} certificati medici</li>
                <li>{n_docs} documenti</li>
                {"<li>Account di accesso del genitore</li>" if parent_deleted else ""}
              </ul>
              {f"<p><strong>Motivo indicato:</strong> {reason}</p>" if reason else ""}
              <p style="margin-top:12px;">Grazie per aver provato le nostre attività. Le porte restano aperte: puoi
              iscriverti di nuovo quando vuoi.</p>
              <p style="color:#888;font-size:13px;">{_sn}</p>
            </div>
            """
            await send_society_email(society_doc, parent_email, f"Cancellazione dati completata - {athlete_name}", html)
        except Exception as _mail_err:
            logging.getLogger(__name__).warning(f"[self-delete email] {_mail_err}")

    return {
        "message": f"{athlete_name} e tutti i suoi dati sono stati eliminati.",
        "parent_deleted": parent_deleted,
    }



@api_router.post("/athletes/{athlete_id}/request-deletion")
async def request_athlete_deletion(athlete_id: str, current_user = Depends(get_current_user)):
    """Request deletion of an athlete - sends notification to admin"""
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    # Check permissions - only parent or adult athlete can request
    if current_user["role"] == UserRole.PARENT:
        is_primary = athlete.get("parent_id") == current_user["id"]
        is_second = athlete.get("second_parent_id") == current_user["id"]
        if not is_primary and not is_second:
            raise HTTPException(status_code=403, detail="Accesso negato")
    elif current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Non autorizzato")
    
    if athlete.get("deletion_requested"):
        raise HTTPException(status_code=400, detail="Richiesta di cancellazione gia inviata")
    
    # Atomic update: only succeeds if deletion_requested is NOT already True.
    # This prevents race conditions under slow networks where the same user
    # clicks twice before the first request has written to DB (which would
    # otherwise create two admin notifications).
    result = await db.athletes.update_one(
        {"id": athlete_id, "$or": [{"deletion_requested": {"$ne": True}}, {"deletion_requested": {"$exists": False}}]},
        {"$set": {
            "deletion_requested": True,
            "deletion_requested_at": datetime.now(timezone.utc),
            "deletion_requested_by": current_user["id"],
            "deletion_requested_by_name": current_user.get("full_name", current_user.get("email", ""))
        }}
    )
    if result.modified_count == 0:
        raise HTTPException(status_code=409, detail="Richiesta di cancellazione gia inviata")
    
    # Audit log
    athlete_name = f"{athlete.get('first_name', '')} {athlete.get('last_name', '')}"
    await log_audit(
        action="deletion_requested",
        user_id=current_user["id"],
        user_email=current_user.get("email", ""),
        society_id=current_user.get("society_id", ""),
        target_user_id=athlete_id,
        target_user_name=athlete_name,
        details={
            "requester_name": current_user.get("full_name", ""),
            "requester_role": current_user.get("role", ""),
            "athlete_name": athlete_name,
        }
    )
    
    # Notification to admin.
    # 🔒 06/2026 — La notifica deve andare agli admin della società DELL'ATLETA (dove
    # risiedono i dati da cancellare), non a quella del richiedente (che potrebbe essersi
    # spostato in un'altra società). Priorità: società dell'atleta.
    society_id = athlete.get("society_id") or current_user.get("society_id")
    if society_id:
        admin_users = await db.users.find({"society_id": society_id, "role": "admin"}).to_list(100)
        for admin_user in admin_users:
            await db.admin_notifications.insert_one({
                "id": str(ObjectId()),
                "society_id": society_id,
                "admin_id": admin_user["id"],
                "type": "deletion_requested",
                "title": "Richiesta cancellazione dati",
                "message": f"{current_user.get('full_name', current_user.get('email', ''))} ha richiesto la cancellazione dei dati dell'atleta {athlete_name}.",
                "read": False,
                "created_at": datetime.now(timezone.utc).isoformat(),
                "entity_type": "athlete",
                "entity_id": athlete_id,
            })
    
    return {"message": "Richiesta di cancellazione inviata"}

@api_router.post("/athletes/{athlete_id}/approve-deletion")
async def approve_athlete_deletion(athlete_id: str, current_user = Depends(get_current_user)):
    """Approve deletion request - admin verifies obligations and deletes"""
    if current_user["role"] not in [UserRole.ADMIN, UserRole.DIRIGENTE]:
        raise HTTPException(status_code=403, detail="Solo admin puo approvare le cancellazioni")
    
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    athlete_name = f"{athlete.get('first_name', '')} {athlete.get('last_name', '')}".strip() or athlete.get("full_name", "Atleta")
    requester_name = athlete.get("deletion_requested_by_name", "N/D")
    parent_id = athlete.get("parent_id")
    society_id = athlete.get("society_id") or current_user.get("society_id", "")
    
    # Check administrative obligations
    unpaid_payments = await db.payments.find({"athlete_id": athlete_id, "paid": False}).to_list(1000)
    fiscal_doc_types = [
        "compensation_receipt", "collaboratore_compensation_receipt",
        "threshold_declaration_5000", "threshold_declaration_15000",
        "threshold_5000_communication", "threshold_15000_communication",
    ]
    fiscal_docs = await db.signed_documents.find({
        "related_entity_id": athlete_id,
        "document_type": {"$in": fiscal_doc_types}
    }).to_list(1000)
    compensations = await db.collaboratore_compensations.find({"collaboratore_id": athlete_id}).to_list(1000)
    
    has_obligations = bool(unpaid_payments) or bool(fiscal_docs) or bool(compensations)
    archived_data = {}
    
    # Fetch parent once (used both below and for audit logging later).
    # Lightweight projection: no base64 photos (avoids ~500KB transfer).
    parent = None
    if parent_id:
        parent = await db.users.find_one(
            {"id": parent_id},
            {"_id": 0, "id": 1, "full_name": 1, "email": 1},
        )
    
    if has_obligations:
        # Archive minimum data for legal compliance before deleting rest
        archived_record = {
            "id": str(uuid.uuid4()),
            "original_athlete_id": athlete_id,
            "athlete_name": athlete_name,
            "athlete_fiscal_code": athlete.get("fiscal_code", ""),
            "athlete_birth_date": athlete.get("birth_date", ""),
            "society_id": society_id,
            "parent_id": parent_id,
            "parent_name": "",
            "archived_at": datetime.now(timezone.utc),
            "archived_by": current_user["id"],
            "archived_by_name": current_user.get("full_name", ""),
            "reason": "deletion_request_with_obligations",
            "unpaid_payments": [
                {"id": p["id"], "amount": p.get("amount", 0), "description": p.get("description", ""), "due_date": p.get("due_date", "")}
                for p in unpaid_payments
            ],
            "fiscal_document_ids": [d["id"] for d in fiscal_docs],
            "compensation_ids": [c["id"] for c in compensations],
        }
        # Fetch parent name
        if parent_id:
            parent = await db.users.find_one({"id": parent_id})
            if parent:
                archived_record["parent_name"] = parent.get("full_name", "")
        
        await db.archived_deletions.insert_one(archived_record)
        archived_data = {
            "unpaid_payments_count": len(unpaid_payments),
            "fiscal_documents_preserved": len(fiscal_docs),
            "compensations_preserved": len(compensations),
        }
        # Keep fiscal documents and compensations, delete the rest
        non_fiscal_doc_types = [t for t in await db.signed_documents.distinct("document_type", {"related_entity_id": athlete_id}) if t not in fiscal_doc_types]
        if non_fiscal_doc_types:
            await db.signed_documents.delete_many({"related_entity_id": athlete_id, "document_type": {"$in": non_fiscal_doc_types}})
    else:
        # No obligations - delete everything
        await db.signed_documents.delete_many({"related_entity_id": athlete_id})
        await db.collaboratore_compensations.delete_many({"collaboratore_id": athlete_id})
    
    # Always delete these (non-fiscal)
    await db.certificates.delete_many({"athlete_id": athlete_id})
    await db.attendances.delete_many({"athlete_id": athlete_id})
    
    # Delete payments that are paid (keep unpaid for obligations)
    if has_obligations:
        await db.payments.delete_many({"athlete_id": athlete_id, "paid": True})
    else:
        await db.payments.delete_many({"athlete_id": athlete_id})
    
    # Audit log BEFORE deleting athlete
    await log_audit(
        action="deletion_approved",
        user_id=current_user["id"],
        user_email=current_user.get("email", ""),
        society_id=society_id,
        target_user_id=athlete_id,
        target_user_name=athlete_name,
        details={
            "executor_name": current_user.get("full_name", ""),
            "executor_role": current_user.get("role", ""),
            "athlete_name": athlete_name,
            "originally_requested_by": athlete.get("deletion_requested_by", ""),
            "originally_requested_by_name": requester_name,
            "originally_requested_at": str(athlete.get("deletion_requested_at", "")),
            "had_obligations": has_obligations,
            "archived_data": archived_data,
        }
    )
    
    # Delete athlete record
    await db.athletes.delete_one({"id": athlete_id})
    
    # Check if parent account should be deleted
    parent_deleted = False
    if parent_id:
        other_children_primary = await db.athletes.count_documents({"parent_id": parent_id})
        other_children_second = await db.athletes.count_documents({"second_parent_id": parent_id})
        total_children = other_children_primary + other_children_second
        
        if total_children == 0:
            # Check parent fiscal obligations
            parent_fiscal_docs = await db.signed_documents.find({
                "signer_id": parent_id,
                "document_type": {"$in": fiscal_doc_types}
            }).to_list(100)
            parent_compensations = await db.collaboratore_compensations.find({"collaboratore_id": parent_id}).to_list(100)
            
            if not parent_fiscal_docs and not parent_compensations:
                # Delete parent account
                await db.users.delete_one({"id": parent_id})
                await db.signed_documents.delete_many({"signer_id": parent_id})
                parent_deleted = True
                await log_audit(
                    action="parent_account_deleted",
                    user_id=current_user["id"],
                    user_email=current_user.get("email", ""),
                    society_id=society_id,
                    target_user_id=parent_id,
                    target_user_name=parent.get("full_name", "") if parent else "",
                    details={
                        "reason": "no_other_children_no_obligations",
                        "triggered_by_athlete_deletion": athlete_id,
                        "parent_name": parent.get("full_name", "") if parent else "",
                        "parent_email": parent.get("email", "") if parent else "",
                        "athlete_name": athlete_name,
                    }
                )
    
    # Notify requester if possible (via admin notification system)
    if athlete.get("deletion_requested_by"):
        await db.admin_notifications.insert_one({
            "id": str(ObjectId()),
            "society_id": society_id,
            "admin_id": athlete.get("deletion_requested_by"),
            "type": "deletion_approved",
            "title": "Cancellazione approvata",
            "message": f"La cancellazione dei dati dell'atleta {athlete_name} e stata approvata ed eseguita.",
            "read": False,
            "created_at": datetime.now(timezone.utc).isoformat(),
            "entity_type": "athlete",
            "entity_id": athlete_id,
        })
    
    result_msg = f"Atleta {athlete_name} eliminato con successo."
    if has_obligations:
        result_msg += " Alcuni dati fiscali sono stati archiviati per obblighi di legge."
    if parent_deleted:
        result_msg += " Account genitore eliminato (nessun altro figlio e nessun obbligo)."
    
    return {
        "message": result_msg,
        "had_obligations": has_obligations,
        "archived_data": archived_data,
        "parent_deleted": parent_deleted,
    }

@api_router.post("/athletes/{athlete_id}/reject-deletion")
async def reject_athlete_deletion(athlete_id: str, current_user = Depends(get_current_user)):
    """Reject deletion request - admin only"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può rifiutare le cancellazioni")
    
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    # Remove deletion request flag
    await db.athletes.update_one(
        {"id": athlete_id},
        {"$unset": {
            "deletion_requested": "",
            "deletion_requested_at": "",
            "deletion_requested_by": "",
            "deletion_requested_by_name": ""
        }}
    )
    
    # Audit log
    athlete_name = f"{athlete.get('first_name', '')} {athlete.get('last_name', '')}"
    await log_audit(
        action="deletion_rejected",
        user_id=current_user["id"],
        user_email=current_user.get("email", ""),
        society_id=current_user.get("society_id", ""),
        target_user_id=athlete_id,
        target_user_name=athlete_name,
        details={
            "executor_name": current_user.get("full_name", ""),
            "athlete_name": athlete_name,
            "originally_requested_by": athlete.get("deletion_requested_by", ""),
            "originally_requested_by_name": athlete.get("deletion_requested_by_name", "N/D"),
        }
    )
    
    return {"message": "Richiesta di cancellazione rifiutata"}

@api_router.post("/athletes/withdraw-trial")
async def withdraw_from_trial(current_user = Depends(get_current_user)):
    """Withdraw from trial period - for adult athletes (legacy endpoint, redirects to stay)"""
    # Legacy endpoint - default to stay behavior
    return await withdraw_trial_stay(current_user)


@api_router.post("/athletes/withdraw-trial-stay")
async def withdraw_trial_stay(current_user = Depends(get_current_user)):
    """End trial but stay - if privacy already signed, go directly to active"""
    athlete_id = current_user.get("athlete_id")
    if not athlete_id:
        raise HTTPException(status_code=400, detail="Non sei un atleta")
    
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    if athlete.get("status") != "trial":
        raise HTTPException(status_code=400, detail="Non sei in periodo di prova")
    
    # If privacy is already accepted (adult 18+ signed during registration), go directly to active
    if athlete.get("privacy_accepted"):
        await db.athletes.update_one(
            {"id": athlete_id},
            {"$set": {
                "status": "active",
                "trial_ended_date": datetime.utcnow(),
            }}
        )
        await db.users.update_one(
            {"id": current_user["id"]},
            {"$set": {"status": "active"}}
        )
        return {"message": "Benvenuto nella società!", "action": "activated"}
    
    # Minor or athlete without privacy: change to pending_privacy
    await db.athletes.update_one(
        {"id": athlete_id},
        {"$set": {
            "status": "pending_privacy",
            "trial_ended_date": datetime.utcnow(),
            "privacy_accepted": False,
            "privacy_accepted_date": None
        }}
    )
    
    return {"message": "Per continuare devi accettare la privacy", "action": "sign_privacy"}


@api_router.post("/athletes/withdraw-trial-leave")
async def withdraw_trial_leave(current_user = Depends(get_current_user)):
    """Leave completely - delete all athlete data"""
    athlete_id = current_user.get("athlete_id")
    user_id = current_user.get("id")
    
    if not athlete_id:
        raise HTTPException(status_code=400, detail="Non sei un atleta")
    
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    if athlete.get("status") != "trial":
        raise HTTPException(status_code=400, detail="Non sei in periodo di prova")
    
    # Delete all related data
    await db.certificates.delete_many({"athlete_id": athlete_id})
    await db.payments.delete_many({"athlete_id": athlete_id})
    await db.attendances.delete_many({"athlete_id": athlete_id})
    await db.signed_documents.delete_many({"signer_id": user_id})
    await db.signed_documents.delete_many({"signer_id": athlete_id})
    
    # Delete the athlete record
    await db.athletes.delete_one({"id": athlete_id})
    
    # Delete the user account
    await db.users.delete_one({"id": user_id})
    
    # Log the auto-deletion
    await db.audit_logs.insert_one({
        "id": str(uuid.uuid4()),
        "user_id": user_id,
        "action": "trial_leave_data_deleted",
        "details": {
            "athlete_id": athlete_id,
            "athlete_name": athlete.get("full_name", ""),
            "reason": "Atleta ha scelto di lasciare durante il periodo di prova",
        },
        "created_at": datetime.now(timezone.utc)
    })
    
    # Notify admin
    await db.admin_notifications.insert_one({
        "id": str(uuid.uuid4()),
        "type": "trial_leave_deleted",
        "title": "Atleta rinuncia - dati cancellati",
        "message": f"{athlete.get('full_name', '')} ha rinunciato al periodo di prova e i dati sono stati cancellati automaticamente (GDPR).",
        "data": {"athlete_name": athlete.get("full_name", ""), "athlete_email": athlete.get("email", "")},
        "read": False,
        "created_at": datetime.now(timezone.utc),
    })
    
    return {"message": "Account e dati eliminati con successo", "action": "logout"}

@api_router.post("/staff/leave-society")
async def staff_leave_society(current_user = Depends(get_current_user)):
    """Staff member (coach, dirigente, collaboratore) requests to leave the society - deletes all data (GDPR)"""
    user_id = current_user.get("id")
    role = current_user.get("role")
    
    if role not in ["coach", "dirigente", "collaboratore"]:
        raise HTTPException(status_code=403, detail="Questa funzione è disponibile solo per coach, dirigenti e collaboratori")
    
    user = await db.users.find_one({"id": user_id})
    if not user:
        raise HTTPException(status_code=404, detail="Utente non trovato")
    
    user_name = user.get("full_name", "")
    user_email = user.get("email", "")
    
    # Check for fiscal obligations (compensation receipts)
    fiscal_doc_types = ["compensation_receipt", "quietanza"]
    fiscal_docs = await db.signed_documents.find({
        "signer_id": user_id,
        "document_type": {"$in": fiscal_doc_types}
    }).to_list(10)
    
    # Check for compensation records
    comp_collection = f"{role}_compensations"
    compensations = await db[comp_collection].find({f"{role}_id": user_id}).to_list(10) if comp_collection in await db.list_collection_names() else []
    
    has_obligations = bool(fiscal_docs) or bool(compensations)
    
    if has_obligations:
        # Cannot auto-delete - flag for admin review
        await db.users.update_one({"id": user_id}, {"$set": {
            "leave_requested": True,
            "leave_requested_date": datetime.now(timezone.utc),
            "status": "leave_requested",
        }})
        
        await db.admin_notifications.insert_one({
            "id": str(uuid.uuid4()),
            "type": "staff_leave_request",
            "title": f"{role.capitalize()} richiede di lasciare",
            "message": f"{user_name} ({role}) ha richiesto di lasciare la società. Ha obblighi fiscali, verificare prima di cancellare.",
            "data": {"user_id": user_id, "user_name": user_name, "role": role, "has_obligations": True},
            "read": False,
            "created_at": datetime.now(timezone.utc),
        })
        
        return {"message": "Richiesta di uscita registrata. L'admin verificherà gli obblighi fiscali prima di procedere.", "data_deleted": False, "has_obligations": True}
    
    # No obligations - auto-delete all data
    await db.signed_documents.delete_many({"signer_id": user_id})
    await db.users.delete_one({"id": user_id})
    
    # Log the deletion
    await db.audit_logs.insert_one({
        "id": str(uuid.uuid4()),
        "user_id": user_id,
        "user_email": user_email,
        "action": "staff_leave_data_deleted",
        "details": {
            "user_name": user_name,
            "role": role,
            "reason": f"{role.capitalize()} ha scelto di lasciare la società - cancellazione automatica GDPR",
        },
        "created_at": datetime.now(timezone.utc)
    })
    
    # Notify admin
    await db.admin_notifications.insert_one({
        "id": str(uuid.uuid4()),
        "type": "staff_leave_deleted",
        "title": f"{role.capitalize()} lascia - dati cancellati",
        "message": f"{user_name} ({role}) ha lasciato la società. I dati sono stati cancellati automaticamente (GDPR).",
        "data": {"user_name": user_name, "user_email": user_email, "role": role},
        "read": False,
        "created_at": datetime.now(timezone.utc),
    })
    
    return {"message": "I tuoi dati sono stati cancellati. Arrivederci!", "data_deleted": True, "action": "logout"}




@api_router.delete("/athletes/{athlete_id}")
async def delete_athlete(athlete_id: str, current_user = Depends(get_current_user)):
    """Delete an athlete and all related data (certificates, payments, attendances)"""
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    # Check permissions - only parent of the athlete or admin can delete (primary or second)
    if current_user["role"] == UserRole.PARENT:
        is_primary = athlete.get("parent_id") == current_user["id"]
        is_second = athlete.get("second_parent_id") == current_user["id"]
        if not is_primary and not is_second:
            raise HTTPException(status_code=403, detail="Accesso negato")
    
    # AUDIT LOG: Athlete deletion
    await log_audit(
        action=AuditAction.USER_DELETED,
        user_id=current_user["id"],
        user_email=current_user["email"],
        society_id=current_user.get("society_id", ""),
        target_user_id=athlete_id,
        target_user_name=athlete.get("full_name"),
        details={"deleted_role": "athlete", "deleted_by_role": current_user["role"]}
    )
    
    # Delete all related data
    await db.certificates.delete_many({"athlete_id": athlete_id})
    await db.payments.delete_many({"athlete_id": athlete_id})
    await db.attendances.delete_many({"athlete_id": athlete_id})
    
    # Delete the athlete
    await db.athletes.delete_one({"id": athlete_id})
    
    return {"message": "Atleta eliminato con successo"}

# ==================== CERTIFICATE ENDPOINTS ====================

@api_router.post("/certificates")
async def upload_certificate(
    athlete_id: str,
    issue_date: str,
    validity_months: int,
    file: UploadFile = File(...),
    current_user = Depends(get_current_user)
):
    # Check athlete exists and permissions
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    if current_user["role"] == UserRole.PARENT:
        is_primary = athlete.get("parent_id") == current_user["id"]
        is_second = athlete.get("second_parent_id") == current_user["id"]
        if not is_primary and not is_second:
            raise HTTPException(status_code=403, detail="Accesso negato")
    
    # Read PDF and encode to base64
    pdf_data = await file.read()
    pdf_base64 = base64.b64encode(pdf_data).decode()
    
    # Calculate expiry date: issue_date + validity_months - 1 day
    issue_dt = datetime.fromisoformat(issue_date)
    # Add months properly using relativedelta, then subtract 1 day
    from dateutil.relativedelta import relativedelta
    expiry_dt = issue_dt + relativedelta(months=validity_months) - timedelta(days=1)
    
    # Delete old certificate if exists
    await db.certificates.delete_many({"athlete_id": athlete_id})
    
    # Create certificate
    certificate = Certificate(
        athlete_id=athlete_id,
        pdf_data=pdf_base64,
        issue_date=issue_dt,
        validity_months=validity_months,
        expiry_date=expiry_dt
    )
    
    await db.certificates.insert_one(certificate.dict())
    
    return {"message": "Certificato caricato con successo", "expiry_date": expiry_dt.isoformat()}

@api_router.post("/certificates/upload-base64")
async def upload_certificate_base64(
    data: CertificateUploadBase64,
    current_user = Depends(get_current_user)
):
    # Check athlete exists and permissions
    athlete = await db.athletes.find_one({"id": data.athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    if current_user["role"] == UserRole.PARENT:
        is_primary = athlete.get("parent_id") == current_user["id"]
        is_second = athlete.get("second_parent_id") == current_user["id"]
        if not is_primary and not is_second:
            raise HTTPException(status_code=403, detail="Accesso negato")
    
    # Calculate expiry date: issue_date + validity_months - 1 day
    # Example: issue 14/04/2025 + 12 months - 1 day = 13/04/2026
    issue_dt = datetime.fromisoformat(data.issue_date)
    from dateutil.relativedelta import relativedelta
    expiry_dt = issue_dt + relativedelta(months=data.validity_months) - timedelta(days=1)
    
    # Delete old certificate if exists
    await db.certificates.delete_many({"athlete_id": data.athlete_id})
    
    # Create certificate
    certificate = Certificate(
        athlete_id=data.athlete_id,
        pdf_data=data.pdf_base64,
        issue_date=issue_dt,
        validity_months=data.validity_months,
        expiry_date=expiry_dt
    )
    
    await db.certificates.insert_one(certificate.dict())

    # 🐛 18/08/2026 — Sincronizza i campi medical_certificate_* sull'atleta.
    # Prima l'upload del PDF scriveva SOLO nella collezione `certificates`, quindi
    # la nuova data di emissione/scadenza NON veniva "memorizzata" sul documento
    # atleta usato da admin, scheduler scadenze e gate onboarding.
    _now_cert = datetime.utcnow()
    await db.athletes.update_one(
        {"id": data.athlete_id},
        {"$set": {
            "medical_certificate_issue_date": issue_dt.isoformat(),
            "medical_certificate_expiry": expiry_dt.isoformat(),
            "medical_certificate_updated_at": _now_cert.isoformat(),
            "medical_certificate_updated_by": current_user["id"],
            "medical_certificate_updated_by_name": current_user.get("full_name", current_user.get("email", "")),
            "medical_certificate_updated_by_role": current_user["role"],
        }}
    )

    return {"message": "Certificato caricato con successo", "expiry_date": expiry_dt.isoformat()}


class CertificateSimple(BaseModel):
    athlete_id: str
    issue_date: Optional[str] = None  # ISO format - data di emissione
    expiry_date: str  # ISO format - data di scadenza (calcolata: giorno prima anniversario)
    verified: Optional[bool] = None  # Certificato verificato dall'admin

@api_router.post("/certificates/simple")
async def create_certificate_simple(
    data: CertificateSimple,
    current_user = Depends(get_current_user)
):
    """Create/update certificate - Admin, Dirigente (assigned to team), Athlete (own), Parent (own child).
    Only Admin can mark as verified. Full metadata tracking."""
    # Check athlete exists
    athlete = await db.athletes.find_one({"id": data.athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")

    # 🐛 18/08/2026 — Autorizzazione basata sulla RELAZIONE con l'atleta (robusta
    # rispetto a piccole differenze nella stringa 'role'). Un genitore realmente
    # collegato all'atleta (parent_id/second_parent_id) veniva rifiutato con
    # "Non hai i permessi per aggiornare certificati" quando il suo ruolo non era
    # ESATTAMENTE "parent" (es. utente collegato come genitore ma con ruolo
    # coach/coordinatore/dual-role): la whitelist di ruoli scattava PRIMA del
    # controllo di parentela. Ora consentiamo la modifica se l'utente è: admin o
    # coordinatore della stessa società, genitore collegato (primario/secondario),
    # l'atleta stesso (incl. login Lite minorenne), o il dirigente/coach incaricato
    # della squadra dell'atleta. La sicurezza è garantita dalla relazione, non dal ruolo.
    role = current_user.get("role")
    uid = current_user.get("id")
    same_society = athlete.get("society_id") == current_user.get("society_id")

    is_admin = role == UserRole.ADMIN
    is_coordinatore = role == "coordinatore" and same_society
    is_linked_parent = (
        athlete.get("parent_id") == uid or athlete.get("second_parent_id") == uid
    )
    is_self_athlete = (
        current_user.get("athlete_id") == data.athlete_id or uid == data.athlete_id
    )

    is_authorized_staff = False
    if role in [UserRole.DIRIGENTE, UserRole.VIEWER, UserRole.COACH]:
        athlete_team_id = athlete.get("team_id")
        if athlete_team_id:
            team = await db.teams.find_one({"id": athlete_team_id})
            dirigente_ids = team.get("dirigente_ids", []) if team else []
            coach_ids = team.get("coach_ids", []) if team else []
            user_assigned_teams = current_user.get("assigned_teams", [])
            if uid in dirigente_ids or uid in coach_ids or athlete_team_id in user_assigned_teams:
                is_authorized_staff = True

    if not (is_admin or is_coordinatore or is_linked_parent or is_self_athlete or is_authorized_staff):
        raise HTTPException(status_code=403, detail="Non hai i permessi per aggiornare certificati")
    
    # Only admin can set verified = True
    verified_value = data.verified if data.verified is not None else False
    if verified_value and current_user["role"] != UserRole.ADMIN:
        verified_value = False  # Silently ignore verified flag for non-admin
    
    # Get old data for audit trail
    old_expiry = athlete.get("medical_certificate_expiry")
    old_issue = athlete.get("medical_certificate_issue_date")
    old_verified = athlete.get("medical_certificate_verified", False)
    
    # Parse dates
    try:
        expiry_dt = datetime.fromisoformat(data.expiry_date.replace('Z', '+00:00'))
        if expiry_dt.tzinfo is None:
            expiry_dt = expiry_dt.replace(tzinfo=timezone.utc)
    except:
        raise HTTPException(status_code=400, detail="Formato data scadenza non valido")
    
    issue_dt = None
    if data.issue_date:
        try:
            issue_dt = datetime.fromisoformat(data.issue_date.replace('Z', '+00:00'))
        except:
            pass
    
    now = datetime.utcnow()
    
    # Build metadata update
    update_data = {
        "medical_certificate_expiry": expiry_dt.isoformat(),
        "medical_certificate_issue_date": issue_dt.isoformat() if issue_dt else None,
        "medical_certificate_verified": verified_value,
        "medical_certificate_updated_at": now.isoformat(),
        "medical_certificate_updated_by": current_user["id"],
        "medical_certificate_updated_by_name": current_user.get("full_name", current_user.get("email", "")),
        "medical_certificate_updated_by_role": current_user["role"],
    }
    
    # Track who inserted the data originally (only on first insert)
    if not old_expiry:
        update_data["medical_certificate_inserted_at"] = now.isoformat()
        update_data["medical_certificate_inserted_by"] = current_user["id"]
        update_data["medical_certificate_inserted_by_name"] = current_user.get("full_name", current_user.get("email", ""))
        update_data["medical_certificate_inserted_by_role"] = current_user["role"]
    
    # Track verification separately
    if verified_value and not old_verified:
        update_data["medical_certificate_verified_at"] = now.isoformat()
        update_data["medical_certificate_verified_by"] = current_user["id"]
        update_data["medical_certificate_verified_by_name"] = current_user.get("full_name", current_user.get("email", ""))
    elif not verified_value:
        update_data["medical_certificate_verified_at"] = None
        update_data["medical_certificate_verified_by"] = None
        update_data["medical_certificate_verified_by_name"] = None
    
    await db.athletes.update_one(
        {"id": data.athlete_id},
        {"$set": update_data}
    )

    # 🆕 Avanzamento onboarding alla CONVALIDA del certificato:
    #   • MINORENNI: da pending_certificate → pending_trial (la prova parte al 1° QR)
    #   • ADULTI (18+): nessuna prova. Se manca ancora la firma privacy → pending_privacy
    #     ("Firma Privacy"); se la privacy è già firmata verranno attivati sotto.
    if verified_value and athlete.get("status") == "pending_certificate":
        exp_ok = expiry_dt >= datetime.now(timezone.utc).replace(hour=0, minute=0, second=0, microsecond=0)
        if exp_ok:
            if _compute_is_minor(athlete):
                await db.athletes.update_one(
                    {"id": data.athlete_id, "status": "pending_certificate"},
                    {"$set": {"status": "pending_trial"}}
                )
                if athlete.get("user_id"):
                    await db.users.update_one({"id": athlete["user_id"]}, {"$set": {"status": "pending_trial"}})
            elif not athlete.get("privacy_accepted"):
                await db.athletes.update_one(
                    {"id": data.athlete_id, "status": "pending_certificate"},
                    {"$set": {"status": "pending_privacy"}}
                )
                if athlete.get("user_id"):
                    await db.users.update_one({"id": athlete["user_id"]}, {"$set": {"status": UserStatus.APPROVED}})
    
    history_entry = {
        "athlete_id": data.athlete_id,
        "athlete_name": athlete.get("full_name"),
        "action": "insert" if not old_expiry else "update",
        "old_issue_date": old_issue,
        "new_issue_date": issue_dt.isoformat() if issue_dt else None,
        "old_expiry_date": old_expiry,
        "new_expiry_date": expiry_dt.isoformat(),
        "old_verified": old_verified,
        "new_verified": verified_value,
        "changed_by": current_user["id"],
        "changed_by_name": current_user.get("full_name", current_user.get("email", "")),
        "changed_by_role": current_user["role"],
        "changed_at": now.isoformat(),
        "society_id": current_user.get("society_id", ""),
    }
    await db.certificate_history.insert_one(history_entry)
    
    # Also update certificates collection for compatibility (no pdf_data stored)
    await db.certificates.delete_many({"athlete_id": data.athlete_id})
    
    certificate = Certificate(
        athlete_id=data.athlete_id,
        pdf_data="",  # No file stored - privacy compliance
        issue_date=issue_dt or datetime.utcnow(),
        validity_months=12,
        expiry_date=expiry_dt
    )
    
    await db.certificates.insert_one(certificate.dict())
    
    # AUDIT LOG
    await log_audit(
        action=AuditAction.CERTIFICATE_MODIFIED,
        user_id=current_user["id"],
        user_email=current_user["email"],
        society_id=current_user.get("society_id", ""),
        target_user_id=data.athlete_id,
        target_user_name=athlete.get("full_name"),
        details={
            "old_expiry": old_expiry,
            "new_expiry": expiry_dt.isoformat(),
            "old_issue_date": old_issue,
            "new_issue_date": issue_dt.isoformat() if issue_dt else None,
            "verified": verified_value,
            "verified_changed": verified_value != old_verified,
        }
    )
    
    # Notifica admin quando un non-admin modifica il certificato
    if current_user["role"] != UserRole.ADMIN:
        role_labels = {"viewer": "Dirigente", "coach": "Coach", "athlete": "Atleta", "parent": "Genitore"}
        role_label = role_labels.get(current_user["role"], current_user["role"])
        expiry_str = expiry_dt.strftime("%d/%m/%Y") if expiry_dt else "N/D"
        issue_str = issue_dt.strftime("%d/%m/%Y") if issue_dt else "N/D"
        
        admin_notification = {
            "id": str(uuid.uuid4()),
            "type": "certificate_update",
            "title": f"Certificato medico aggiornato",
            "message": f"{current_user.get('full_name', '')} ({role_label}) ha aggiornato il certificato medico di {athlete.get('full_name', '')} - Emissione: {issue_str}, Scadenza: {expiry_str}",
            "data": {
                "athlete_id": data.athlete_id,
                "athlete_name": athlete.get("full_name", ""),
                "changed_by": current_user.get("full_name", ""),
                "changed_by_role": role_label,
                "issue_date": issue_str,
                "expiry_date": expiry_str,
            },
            "read": False,
            "created_at": datetime.now(timezone.utc),
            "society_id": current_user.get("society_id", ""),
        }
        await db.admin_notifications.insert_one(admin_notification)
    
    # Check if end-trial flow can be completed
    activated = False
    activated_as_pro = False
    if verified_value and athlete.get("end_trial_requested"):
        activated = await check_and_activate_if_ready(data.athlete_id)

    # 🆕 MINORENNI: alla convalida del certificato, se la privacy è firmata, l'atleta
    # esce dalla prova e diventa ATTIVO anche senza "Termina prova" del genitore.
    if verified_value and not activated:
        if await maybe_activate_minor_athlete(data.athlete_id, current_user):
            activated = True

    # 🆕 ADULTI (18+): nessun periodo di prova. Alla convalida del certificato
    # medico, se la privacy è già stata firmata, l'atleta diventa ATTIVO
    # automaticamente. Vale sia per gli atleti "quota" sia per i PRO/compensated.
    # (La guardia età è dentro maybe_activate_adult_athlete: i minorenni non sono
    # mai attivati da qui.)
    if verified_value and not activated and current_user["role"] == UserRole.ADMIN:
        _adult_activated = await maybe_activate_adult_athlete(data.athlete_id, current_user)
        if _adult_activated:
            activated = True
            _ath_after = await db.athletes.find_one(
                {"id": data.athlete_id}, {"_id": 0, "athlete_type": 1}
            )
            activated_as_pro = bool(_ath_after and _ath_after.get("athlete_type") == "compensated")

    return {
        "id": certificate.id,
        "athlete_id": certificate.athlete_id,
        "expiry_date": certificate.expiry_date.isoformat(),
        "verified": verified_value,
        "updated_by": current_user.get("full_name", ""),
        "message": "Certificato salvato con successo" + (" - Atleta attivato!" if activated else ""),
        "athlete_activated": activated,
        "activated_as_pro": activated_as_pro,
    }

# 🆕 06/2026 — Flag "copia originale ricevuta" (requisito FIPAV).
class CertificateOriginalRequest(BaseModel):
    original_received: bool


@api_router.patch("/admin/athletes/{athlete_id}/certificate-original")
async def set_certificate_original_received(
    athlete_id: str,
    data: CertificateOriginalRequest,
    current_user = Depends(get_current_user),
):
    """Attesta (o revoca) il possesso della COPIA ORIGINALE cartacea del certificato
    medico. È indipendente dalla convalida (che può avvenire su foto anticipata dal
    genitore): serve all'admin per sapere se l'originale FIPAV è effettivamente in sede.
    Solo admin o coordinatore autorizzato ai certificati, stessa società."""
    if not _has_admin_or_coord_perm(current_user, "certificates"):
        raise HTTPException(status_code=403, detail="Solo admin o coordinatore autorizzato")
    athlete = await db.athletes.find_one({"id": athlete_id}, {"_id": 0, "society_id": 1, "full_name": 1})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    if athlete.get("society_id") != current_user.get("society_id"):
        raise HTTPException(status_code=403, detail="Atleta di un'altra società")

    now = datetime.utcnow()
    if data.original_received:
        update = {
            "medical_certificate_original_received": True,
            "medical_certificate_original_received_by": current_user["id"],
            "medical_certificate_original_received_by_name": current_user.get("full_name", current_user.get("email", "")),
            "medical_certificate_original_received_at": now.isoformat(),
        }
    else:
        update = {
            "medical_certificate_original_received": False,
            "medical_certificate_original_received_by": None,
            "medical_certificate_original_received_by_name": None,
            "medical_certificate_original_received_at": None,
        }
    await db.athletes.update_one({"id": athlete_id}, {"$set": update})
    return {
        "athlete_id": athlete_id,
        "medical_certificate_original_received": update["medical_certificate_original_received"],
        "medical_certificate_original_received_by_name": update.get("medical_certificate_original_received_by_name"),
        "medical_certificate_original_received_at": update.get("medical_certificate_original_received_at"),
    }


@api_router.get("/admin/athletes/certificate-originals")
async def admin_list_certificate_originals(current_user = Depends(get_current_user)):
    """Elenco di TUTTI gli atleti della società con lo stato della COPIA ORIGINALE
    cartacea del certificato medico. Il frontend divide in due tab
    (Da consegnare / Già consegnato) e permette l'ordinamento per nome o squadra."""
    if not _has_admin_or_coord_perm(current_user, "certificates"):
        raise HTTPException(status_code=403, detail="Solo admin o coordinatore autorizzato")
    society_id = current_user.get("society_id")
    athletes = await db.athletes.find(
        {"society_id": society_id},
        {"_id": 0, "id": 1, "full_name": 1, "first_name": 1, "last_name": 1,
         "team_id": 1, "medical_certificate_original_received": 1,
         "medical_certificate_verified": 1, "medical_certificate_expiry": 1,
         "medical_certificate_original_received_at": 1,
         "medical_certificate_original_received_by_name": 1},
    ).to_list(5000)

    team_ids = list({a.get("team_id") for a in athletes if a.get("team_id")})
    teams = await db.teams.find({"id": {"$in": team_ids}}, {"_id": 0, "id": 1, "name": 1}).to_list(500)
    team_names = {t["id"]: t.get("name", "—") for t in teams}

    rows = []
    for a in athletes:
        name = a.get("full_name") or f"{a.get('first_name','')} {a.get('last_name','')}".strip() or "—"
        rows.append({
            "id": a.get("id"),
            "full_name": name,
            "team_id": a.get("team_id"),
            "team_name": team_names.get(a.get("team_id"), "Nessuna squadra"),
            "original_received": bool(a.get("medical_certificate_original_received")),
            "certificate_verified": bool(a.get("medical_certificate_verified")),
            "has_certificate": bool(a.get("medical_certificate_expiry") or a.get("medical_certificate_verified")),
            "original_received_at": a.get("medical_certificate_original_received_at"),
            "original_received_by_name": a.get("medical_certificate_original_received_by_name"),
        })
    rows.sort(key=lambda r: (r["full_name"] or "").lower())
    received = [r for r in rows if r["original_received"]]
    pending = [r for r in rows if not r["original_received"]]
    return {"total": len(rows), "received_count": len(received), "pending_count": len(pending), "athletes": rows}


# Override blocco certificato scaduto (solo Admin)
class CertificateOverrideRequest(BaseModel):
    athlete_id: str
    reason: str  # Motivo dell'override - OBBLIGATORIO

@api_router.post("/certificates/override")
async def override_certificate_block(
    data: CertificateOverrideRequest,
    request: Request,
    current_user = Depends(get_current_user)
):
    """Override certificate block for an athlete - Admin only, valid for SINGLE SESSION, always logged"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può fare override del blocco")
    
    # Validate reason is not empty
    if not data.reason or len(data.reason.strip()) < 5:
        raise HTTPException(status_code=400, detail="Motivo obbligatorio (minimo 5 caratteri)")
    
    # Check athlete exists
    athlete = await db.athletes.find_one({"id": data.athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    # Get client IP
    client_ip = request.client.host if request.client else "unknown"
    forwarded_for = request.headers.get("x-forwarded-for")
    if forwarded_for:
        client_ip = forwarded_for.split(",")[0].strip()
    
    # Create override log entry
    override_log = {
        "id": str(uuid.uuid4()),
        "athlete_id": data.athlete_id,
        "athlete_name": athlete.get("full_name"),
        "user_id": current_user["id"],
        "user_name": current_user.get("full_name", current_user.get("email")),
        "reason": data.reason.strip(),
        "timestamp": datetime.utcnow().isoformat(),
        "ip_address": client_ip,
        "type": "certificate_block_override",
        "override_type": "single_session"  # Valido solo per singola sessione
    }
    
    # Save to audit log collection (legacy format)
    await db.audit_logs.insert_one(override_log)
    
    # AUDIT LOG: Certificate override (standardized format)
    await log_audit(
        action=AuditAction.CERTIFICATE_OVERRIDE,
        user_id=current_user["id"],
        user_email=current_user["email"],
        society_id=current_user.get("society_id", ""),
        target_user_id=data.athlete_id,
        target_user_name=athlete.get("full_name"),
        ip_address=client_ip,
        details={"reason": data.reason.strip(), "override_type": "single_session"}
    )
    
    # Set override on athlete - valid for SINGLE attendance registration only
    # The override will be consumed when attendance is registered
    await db.athletes.update_one(
        {"id": data.athlete_id},
        {"$set": {
            "certificate_override_active": True,  # Flag per singola sessione
            "certificate_override_by": current_user["id"],
            "certificate_override_reason": data.reason.strip(),
            "certificate_override_timestamp": datetime.utcnow().isoformat()
        }}
    )
    
    return {
        "message": "⚠️ Override attivato per SINGOLA SESSIONE",
        "warning": "L'atleta potrà partecipare SOLO a questa sessione. Il blocco si riattiverà automaticamente.",
        "log_id": override_log["id"],
        "athlete_name": athlete.get("full_name")
    }


class CertificateDenyAccessRequest(BaseModel):
    athlete_id: str
    athlete_name: str
    reason: str  # Motivo del blocco (es: certificato scaduto)


@api_router.post("/certificates/deny-access")
async def deny_certificate_access(
    data: CertificateDenyAccessRequest,
    request: Request,
    current_user = Depends(get_current_user)
):
    """Log denial of access due to expired certificate - Admin/Coach only"""
    if current_user["role"] not in [UserRole.ADMIN, UserRole.COACH]:
        raise HTTPException(status_code=403, detail="Solo admin o coach può registrare il rifiuto")
    
    # Get client IP
    client_ip = request.client.host if request.client else "unknown"
    forwarded_for = request.headers.get("x-forwarded-for")
    if forwarded_for:
        client_ip = forwarded_for.split(",")[0].strip()
    
    # Create denial log entry
    denial_log = {
        "id": str(uuid.uuid4()),
        "athlete_id": data.athlete_id,
        "athlete_name": data.athlete_name,
        "user_id": current_user["id"],
        "user_name": current_user.get("full_name", current_user.get("email")),
        "reason": data.reason,
        "timestamp": datetime.utcnow().isoformat(),
        "ip_address": client_ip,
        "type": "certificate_access_denied"
    }
    
    # Save to audit log collection
    await db.audit_logs.insert_one(denial_log)
    
    # AUDIT LOG: Certificate access denied (standardized format)
    await log_audit(
        action="certificate_access_denied",
        user_id=current_user["id"],
        user_email=current_user["email"],
        society_id=current_user.get("society_id", ""),
        target_user_id=data.athlete_id,
        target_user_name=data.athlete_name,
        ip_address=client_ip,
        details={"reason": data.reason, "action": "access_denied_expired_certificate"}
    )
    
    return {
        "message": "⛔ Accesso rifiutato registrato",
        "log_id": denial_log["id"],
        "athlete_name": data.athlete_name
    }


@api_router.get("/certificates/override-logs")
async def get_certificate_override_logs(current_user = Depends(get_current_user)):
    """Get all certificate override logs - Admin only"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può vedere i log")
    
    _sid = current_user.get("society_id")
    _q = {"type": "certificate_block_override"}
    if _sid:
        _q["society_id"] = _sid
    logs = await db.audit_logs.find(_q).sort("timestamp", -1).to_list(100)
    
    for log in logs:
        clean_mongo_doc(log)
    
    return logs


@api_router.get("/certificates/expiring")
async def get_expiring_certificates(current_user = Depends(get_current_user)):
    """Get certificates expiring today and within next 30 days"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può vedere i certificati in scadenza")
    
    society_id = current_user.get("society_id")
    today = datetime.utcnow().replace(hour=0, minute=0, second=0, microsecond=0)
    today_end = today + timedelta(days=1)
    thirty_days_from_now = today + timedelta(days=30)
    
    # Get athletes with expiring certificates
    expiring_today = []
    expiring_soon = []
    
    # Get all athletes for this society with medical certificate info
    # 🚀 18/08/2026 PERF — projection: solo i campi necessari (NIENTE foto base64).
    athletes = await db.athletes.find(
        {"society_id": society_id},
        {"_id": 0, "id": 1, "full_name": 1, "medical_certificate_expiry": 1,
         "phone": 1, "athlete_phone": 1, "parent_id": 1},
    ).to_list(2000)

    # 🆕 27/09/2026 — Mappa parent_id → telefono famiglia (per il sollecito WhatsApp
    # dal popup certificati: se l'atleta è minorenne usiamo il numero del genitore).
    _parent_ids = list({a.get("parent_id") for a in athletes if a.get("parent_id")})
    _parent_phones = {}
    if _parent_ids:
        async for _p in db.users.find(
            {"id": {"$in": _parent_ids}},
            {"_id": 0, "id": 1, "phone": 1},
        ):
            if _p.get("phone"):
                _parent_phones[_p["id"]] = _p["phone"]

    for athlete in athletes:
        expiry_str = athlete.get("medical_certificate_expiry")
        if not expiry_str:
            continue
            
        try:
            if isinstance(expiry_str, str):
                expiry_date = datetime.fromisoformat(expiry_str.replace('Z', '+00:00')).replace(tzinfo=None)
            elif isinstance(expiry_str, datetime):
                expiry_date = expiry_str.replace(tzinfo=None)
            else:
                continue
        except:
            continue
        
        _phone = athlete.get("phone") or athlete.get("athlete_phone") \
            or _parent_phones.get(athlete.get("parent_id")) or ""
        athlete_info = {
            "id": athlete.get("id"),
            "athlete_name": athlete.get("full_name"),
            "expiry_date": expiry_date.isoformat(),
            "days_until_expiry": (expiry_date - today).days,
            "phone": _phone,
        }
        
        # Check if expiring today
        if today <= expiry_date < today_end:
            expiring_today.append(athlete_info)
        # Check if expiring in next 30 days (but not today)
        elif today_end <= expiry_date <= thirty_days_from_now:
            expiring_soon.append(athlete_info)
    
    # Sort by days until expiry
    expiring_soon.sort(key=lambda x: x["days_until_expiry"])
    
    return {
        "count_today": len(expiring_today),
        "count_30_days": len(expiring_soon),
        "expiring_today": expiring_today,
        "expiring_soon": expiring_soon
    }


# Endpoint for athletes to upload their own medical certificate
@api_router.post("/certificates/upload-self")
async def upload_self_certificate(request: dict, current_user = Depends(get_current_user)):
    """Allow athlete to upload their own medical certificate"""
    
    # Get athlete_id from current user
    athlete_id = current_user.get("athlete_id")
    if not athlete_id:
        raise HTTPException(status_code=400, detail="Utente non associato a un atleta")
    
    # Verify the athlete exists
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    certificate_data = request.get("certificate_data")
    filename = request.get("filename", "certificate.jpg")
    mime_type = request.get("mime_type", "image/jpeg")
    
    if not certificate_data:
        raise HTTPException(status_code=400, detail="Dati del certificato mancanti")
    
    # Create a data URL for the certificate
    certificate_url = f"data:{mime_type};base64,{certificate_data}"
    
    # Default expiry to 1 year from now
    expiry_date = datetime.utcnow() + timedelta(days=365)
    
    # Check if certificate already exists for this athlete
    existing_cert = await db.certificates.find_one({"athlete_id": athlete_id})
    
    if existing_cert:
        # Archive the old certificate before updating
        archive_entry = {
            "id": str(uuid.uuid4()),
            "athlete_id": athlete_id,
            "last_name": athlete.get("last_name", ""),
            "first_name": athlete.get("first_name", ""),
            "full_name": athlete.get("full_name", f"{athlete.get('last_name', '')} {athlete.get('first_name', '')}"),
            "team_id": athlete.get("team_id"),
            "team_name": athlete.get("team_name"),
            "issue_date": existing_cert.get("issue_date"),
            "expiry_date": existing_cert.get("expiry_date"),
            "certificate_data": existing_cert.get("certificate_data"),
            "uploaded_at": existing_cert.get("uploaded_at"),
            "uploaded_by": existing_cert.get("uploaded_by", "unknown"),
            "society_id": athlete.get("society_id"),
            "archived_at": datetime.utcnow().isoformat()
        }
        await db.medical_certificates_archive.insert_one(archive_entry)
        
        # Update existing certificate
        await db.certificates.update_one(
            {"athlete_id": athlete_id},
            {"$set": {
                "certificate_data": certificate_url,
                "uploaded_at": datetime.utcnow().isoformat(),
                "uploaded_by": "athlete",
                "filename": filename,
                "mime_type": mime_type
            }}
        )
    else:
        # Create new certificate record
        cert_record = {
            "id": str(uuid.uuid4()),
            "athlete_id": athlete_id,
            "society_id": athlete.get("society_id"),
            "certificate_data": certificate_url,
            "issue_date": datetime.utcnow().isoformat(),
            "expiry_date": expiry_date.isoformat(),
            "uploaded_at": datetime.utcnow().isoformat(),
            "uploaded_by": "athlete",
            "filename": filename,
            "mime_type": mime_type
        }
        await db.certificates.insert_one(cert_record)
    
    # Also update athlete's medical certificate expiry
    await db.athletes.update_one(
        {"id": athlete_id},
        {"$set": {
            "medical_certificate_expiry": expiry_date.strftime("%Y-%m-%d"),
            "medical_certificate_url": certificate_url
        }}
    )
    
    return {
        "success": True,
        "message": "Certificato medico caricato con successo",
        "expiry_date": expiry_date.strftime("%Y-%m-%d")
    }
    
    today = datetime.utcnow().replace(hour=0, minute=0, second=0, microsecond=0)
    thirty_days = today + timedelta(days=30)
    
    expiring_today = []
    expiring_soon = []
    
    # Get all certificates (multi-tenant scope)
    _sid_c = current_user.get("society_id")
    _q_c = {"society_id": _sid_c} if _sid_c else {}
    certificates = await db.certificates.find(_q_c).to_list(1000)
    
    for cert in certificates:
        expiry = cert.get("expiry_date")
        if not expiry:
            continue
            
        if isinstance(expiry, str):
            try:
                expiry = datetime.fromisoformat(expiry.replace('Z', '+00:00'))
            except:
                continue
        
        # Get athlete info
        athlete = await db.athletes.find_one({"id": cert.get("athlete_id")})
        if not athlete:
            continue
        
        # Check if withdrawn
        if athlete.get("is_withdrawn"):
            continue
            
        cert_info = {
            "id": str(cert.get("_id")),
            "athlete_id": athlete["id"],
            "athlete_name": athlete["full_name"],
            "expiry_date": expiry.isoformat(),
            "team_id": athlete.get("team_id")
        }
        
        # Expiring today
        if expiry.date() == today.date():
            expiring_today.append(cert_info)
        # Expiring within 30 days
        elif today < expiry <= thirty_days:
            cert_info["days_until_expiry"] = (expiry - today).days
            expiring_soon.append(cert_info)
    
    return {
        "expiring_today": expiring_today,
        "expiring_soon": sorted(expiring_soon, key=lambda x: x.get("days_until_expiry", 30)),
        "count_today": len(expiring_today),
        "count_30_days": len(expiring_soon)
    }


@api_router.get("/certificates/{athlete_id}")
async def get_certificate(athlete_id: str, current_user = Depends(get_current_user)):
    certificate = await db.certificates.find_one({"athlete_id": athlete_id})
    
    # Check permissions
    athlete = await db.athletes.find_one({"id": athlete_id})
    if current_user["role"] == UserRole.PARENT:
        is_primary = athlete.get("parent_id") == current_user["id"] if athlete else False
        is_second = athlete.get("second_parent_id") == current_user["id"] if athlete else False
        if not is_primary and not is_second:
            raise HTTPException(status_code=403, detail="Accesso negato")
    
    if not certificate:
        # Fallback: check athlete's medical_certificate fields
        if athlete and athlete.get("medical_certificate_expiry"):
            _iss = athlete.get("medical_certificate_issue_date") or athlete.get("medical_certificate_date")
            _exp = athlete.get("medical_certificate_expiry")
            # Deriva validity_months da emissione↔scadenza per pre-compilare il form
            _vm = None
            try:
                if _iss and _exp:
                    _i = datetime.fromisoformat(str(_iss).replace('Z', '+00:00'))
                    _e = datetime.fromisoformat(str(_exp).replace('Z', '+00:00'))
                    _months = round((_e - _i).days / 30.4375)
                    if _months > 0:
                        _vm = _months
            except Exception:
                _vm = None
            return {
                "id": f"athlete-cert-{athlete_id}",
                "athlete_id": athlete_id,
                "issue_date": _iss,
                "expiry_date": _exp,
                "validity_months": _vm,
                "verified": athlete.get("medical_certificate_verified", False),
                "uploaded_by": athlete.get("medical_certificate_updated_by_name"),
                "created_at": athlete.get("medical_certificate_inserted_at"),
            }
        raise HTTPException(status_code=404, detail="Certificato non trovato")
    
    return Certificate(**certificate)

def count_training_days_in_period(training_sessions: list, start_date: datetime, end_date: datetime) -> int:
    """
    Count how many training days occurred between start_date and end_date (inclusive).
    Based on team's configured training_sessions.
    """
    if not training_sessions:
        return 0
    
    # Map Italian day names to weekday numbers (Monday=0, Sunday=6)
    day_map = {
        'lunedì': 0, 'lunedi': 0,
        'martedì': 1, 'martedi': 1,
        'mercoledì': 2, 'mercoledi': 2,
        'giovedì': 3, 'giovedi': 3,
        'venerdì': 4, 'venerdi': 4,
        'sabato': 5,
        'domenica': 6
    }
    
    # Get training weekdays from team config
    training_weekdays = set()
    for session in training_sessions:
        day_name = session.get('day', '').lower().strip()
        if day_name in day_map:
            training_weekdays.add(day_map[day_name])
    
    if not training_weekdays:
        return 0
    
    # Count training days in the period
    count = 0
    current = start_date
    while current <= end_date:
        if current.weekday() in training_weekdays:
            count += 1
        current += timedelta(days=1)
    
    return count

async def get_current_user_pdf(request: Request, token: Optional[str] = None):
    """🆕 27/09/2026 — Auth flessibile per i PDF (QR squadra/atleta).
    Accetta il token via header Authorization OPPURE via query param `?token=`
    (token dedicato al download, a vita breve). Questo permette di APRIRE il PDF
    con un URL reale del server anche su mobile (i blob: non sono apribili/condivisibili).
    """
    # 1) Token dedicato al download passato in query
    if token:
        try:
            payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
        except Exception:
            raise HTTPException(status_code=401, detail="Link scaduto o non valido")
        if payload.get("purpose") == "pdf_download":
            return {
                "role": payload.get("role", UserRole.ADMIN),
                "society_id": payload.get("society_id"),
                "id": payload.get("user_id"),
                "_pdf_download": True,
            }
        raise HTTPException(status_code=401, detail="Token non valido per il download")
    # 2) Header Authorization standard
    auth = request.headers.get("Authorization", "")
    if auth.startswith("Bearer "):
        creds = HTTPAuthorizationCredentials(scheme="Bearer", credentials=auth.split(" ", 1)[1])
        return await get_current_user(creds)
    raise HTTPException(status_code=401, detail="Non autenticato")


def _create_pdf_download_token(current_user: dict, minutes: int = 30) -> str:
    """Token firmato a vita breve, monouso per il download PDF (non è il JWT di sessione)."""
    payload = {
        "purpose": "pdf_download",
        "role": current_user.get("role"),
        "society_id": current_user.get("society_id"),
        "user_id": current_user.get("id"),
        "exp": datetime.utcnow() + timedelta(minutes=minutes),
    }
    return jwt.encode(payload, SECRET_KEY, algorithm=ALGORITHM)


@api_router.get("/pdf-download-token")
async def get_pdf_download_token(current_user = Depends(get_current_user)):
    """🆕 Restituisce un token a vita breve (30') da usare come `?token=` per aprire
    i PDF (QR squadra/atleta) con un URL reale del server, apribile anche su mobile."""
    if current_user["role"] not in [
        UserRole.ADMIN, UserRole.COACH, UserRole.VIEWER,
        UserRole.DIRIGENTE, UserRole.COORDINATORE, UserRole.PARENT,
    ]:
        raise HTTPException(status_code=403, detail="Non autorizzato")
    return {"token": _create_pdf_download_token(current_user)}



@api_router.get("/teams/{team_id}/qr-codes-pdf")
async def get_team_qr_codes_pdf(team_id: str, current_user = Depends(get_current_user_pdf)):
    """🆕 Genera un PDF con TUTTI i codici QR degli atleti di una squadra.
    Titolo = nome squadra, griglia di QR con il nome dell'atleta sotto ciascuno.
    Accessibile ad Admin/Coach/Dirigente/Coordinatore (isolamento per società)."""
    if current_user["role"] not in [
        UserRole.ADMIN, UserRole.COACH, UserRole.VIEWER,
        UserRole.DIRIGENTE, UserRole.COORDINATORE,
    ]:
        raise HTTPException(status_code=403, detail="Non autorizzato")
    if not HAS_PDF_GENERATION:
        raise HTTPException(status_code=500, detail="Generazione PDF non disponibile")

    team = await db.teams.find_one({"id": team_id})
    if not team:
        raise HTTPException(status_code=404, detail="Squadra non trovata")
    _sid = current_user.get("society_id")
    if _sid and team.get("society_id") and team.get("society_id") != _sid:
        raise HTTPException(status_code=404, detail="Squadra non trovata")

    _q = {
        "$or": [
            {"team_id": team_id},
            {"team_id_2": team_id},
            {"team_ids": team_id},
        ],
        "status": {"$nin": ["rejected", "withdrawn", "removed", "deleted"]},
        "is_withdrawn": {"$ne": True},
    }
    if _sid:
        _q["society_id"] = _sid
    athletes = await db.athletes.find(
        _q,
        {"_id": 0, "id": 1, "full_name": 1, "first_name": 1, "last_name": 1,
         "qr_identifier": 1, "athlete_code": 1,
         "registration_date": 1, "created_at": 1},
    ).to_list(1000)

    def _name_of(a):
        n = (a.get("full_name") or "").strip()
        if not n:
            n = f"{a.get('last_name') or ''} {a.get('first_name') or ''}".strip()
        return n or "—"

    # 🆕 Percentuale presenze (totale stagione): stesse regole del "Registro Presenze"
    # = presenze / allenamenti previsti dalla registrazione ad oggi (per orario squadra).
    training_sessions = team.get("training_sessions", [])
    now = datetime.now()
    today_end = now.replace(hour=23, minute=59, second=59, microsecond=999999)
    activity_start = None
    _asd = team.get("activity_start_date")
    if _asd:
        try:
            activity_start = datetime.fromisoformat(str(_asd).replace('Z', '').replace('+00:00', '')).replace(hour=0, minute=0, second=0, microsecond=0)
        except Exception:
            activity_start = None

    async def _attendance_pct(athlete):
        reg_date = athlete.get("registration_date") or athlete.get("created_at") or now
        if isinstance(reg_date, str):
            try:
                reg_date = datetime.fromisoformat(reg_date.replace('Z', '+00:00'))
            except Exception:
                reg_date = now
        if getattr(reg_date, "tzinfo", None) is not None:
            reg_date = reg_date.replace(tzinfo=None)
        if activity_start and reg_date < activity_start:
            reg_date = activity_start
        expected_total = count_training_days_in_period(training_sessions, reg_date, today_end)
        _att_q = {"athlete_id": athlete["id"]}
        if activity_start:
            _att_q["check_in_time"] = {"$gte": activity_start}
        done = await db.attendances.count_documents(_att_q)
        pct = round((done / max(expected_total, 1)) * 100, 1)
        return min(pct, 100), done, expected_total

    # Solo atleti con un codice QR valido
    items = []
    for a in athletes:
        code = a.get("qr_identifier") or a.get("athlete_code")
        if code:
            pct, done, exp = await _attendance_pct(a)
            items.append((_name_of(a), str(code), pct, done, exp))
    items.sort(key=lambda x: x[0].lower())

    team_name = team.get("name") or "Squadra"

    from reportlab.lib.utils import ImageReader

    # 🆕 Logo società (per l'intestazione del PDF)
    _society = await db.societies.find_one({"id": _sid}) if _sid else None
    _logo_reader = None
    try:
        _logo_b64 = await _settings_logo_b64(_society) if _society else ""
        if _logo_b64:
            if _logo_b64.startswith("data:"):
                _logo_b64 = _logo_b64.split(",", 1)[1]
            _logo_bytes = base64.b64decode(_logo_b64)
            _logo_reader = ImageReader(io.BytesIO(_logo_bytes))
    except Exception:
        _logo_reader = None

    buffer = io.BytesIO()
    c = canvas.Canvas(buffer, pagesize=A4)
    width, height = A4

    # Layout: 3 colonne x 3 righe = 9 QR per pagina
    cols, rows = 3, 3
    per_page = cols * rows
    margin_x = 1.5 * cm
    band_h = 2.6 * cm
    top_area = height - band_h - 0.5 * cm  # spazio per titolo
    grid_w = width - 2 * margin_x
    cell_w = grid_w / cols
    cell_h = (top_area - 1.5 * cm) / rows
    qr_size = min(cell_w, cell_h) - 1.6 * cm

    def _pct_color(p):
        if p >= 80:
            return colors.HexColor("#2E7D32")
        if p >= 50:
            return colors.HexColor("#EF6C00")
        return colors.HexColor("#C62828")

    def draw_header(page_no, total_pages):
        c.setFillColor(colors.HexColor("#5856D6"))
        c.rect(0, height - band_h, width, band_h, fill=1, stroke=0)
        # Logo in alto a destra dentro la fascia
        logo_w = 0
        if _logo_reader is not None:
            logo_side = 1.7 * cm
            try:
                c.drawImage(_logo_reader, width - margin_x - logo_side,
                            height - band_h + (band_h - logo_side) / 2,
                            width=logo_side, height=logo_side,
                            preserveAspectRatio=True, mask='auto')
                logo_w = logo_side + 0.4 * cm
            except Exception:
                logo_w = 0
        c.setFillColor(colors.white)
        c.setFont("Helvetica-Bold", 20)
        c.drawString(margin_x, height - 1.5 * cm, team_name)
        c.setFont("Helvetica", 10)
        c.drawString(margin_x, height - 2.1 * cm,
                     f"Codici QR presenze  -  {len(items)} atleti")
        if total_pages > 1:
            c.drawRightString(width - margin_x - logo_w, height - 2.1 * cm,
                              f"Pag. {page_no}/{total_pages}")

    total_pages = max(1, (len(items) + per_page - 1) // per_page)

    if not items:
        draw_header(1, 1)
        c.setFillColor(colors.HexColor("#666666"))
        c.setFont("Helvetica", 12)
        c.drawCentredString(width / 2, height / 2, "Nessun atleta con codice QR in questa squadra.")
        c.showPage()
    else:
        for idx, (name, code, pct, done, exp) in enumerate(items):
            pos_in_page = idx % per_page
            if pos_in_page == 0:
                if idx > 0:
                    c.showPage()
                draw_header(idx // per_page + 1, total_pages)
            r = pos_in_page // cols
            col = pos_in_page % cols
            cell_x = margin_x + col * cell_w
            cell_y = top_area - (r + 1) * cell_h

            # QR image
            qr = qrcode.QRCode(version=1, box_size=10, border=1)
            qr.add_data(code)
            qr.make(fit=True)
            img = qr.make_image(fill_color="black", back_color="white")
            qbuf = io.BytesIO()
            img.save(qbuf, format="PNG")
            qbuf.seek(0)
            qr_x = cell_x + (cell_w - qr_size) / 2
            qr_y = cell_y + (cell_h - qr_size) / 2 + 0.7 * cm
            c.drawImage(ImageReader(qbuf), qr_x, qr_y, width=qr_size, height=qr_size,
                        preserveAspectRatio=True, mask='auto')

            # Nome sotto il QR
            c.setFillColor(colors.HexColor("#111111"))
            c.setFont("Helvetica-Bold", 9)
            _label = name if len(name) <= 28 else (name[:27] + "…")
            c.drawCentredString(cell_x + cell_w / 2, qr_y - 0.45 * cm, _label)

            # 🆕 Percentuale presenze sotto il nome
            c.setFillColor(_pct_color(pct))
            c.setFont("Helvetica-Bold", 9)
            c.drawCentredString(cell_x + cell_w / 2, qr_y - 0.90 * cm,
                                f"Presenze: {pct:g}%  ({done}/{exp})")
        c.showPage()

    c.save()
    buffer.seek(0)
    import re as _re
    _fname = _re.sub(r"[^\w.\-]", "_", f"QR_{team_name}.pdf")
    return StreamingResponse(
        io.BytesIO(buffer.getvalue()),
        media_type="application/pdf",
        headers={
            "Content-Disposition": f'inline; filename="{_fname}"',
            "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0",
        },
    )


@api_router.get("/athletes/{athlete_id}/qr-code-pdf")
async def get_athlete_qr_code_pdf(athlete_id: str, current_user = Depends(get_current_user_pdf)):
    """🆕 Genera un PDF (una pagina) con il QR di un singolo atleta: logo società,
    nome squadra, QR grande centrato e nome atleta sotto. Stampabile dalla scheda.
    Accessibile a staff (admin/coach/viewer/dirigente/coordinatore, isolamento società)
    e al genitore collegato all'atleta."""
    if not HAS_PDF_GENERATION:
        raise HTTPException(status_code=500, detail="Generazione PDF non disponibile")

    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    _sid = current_user.get("society_id")
    role = current_user["role"]
    is_staff = role in [UserRole.ADMIN, UserRole.COACH, UserRole.VIEWER,
                        UserRole.DIRIGENTE, UserRole.COORDINATORE]
    is_parent = (role == UserRole.PARENT and athlete.get("parent_id") == current_user["id"])
    if not (is_staff or is_parent):
        raise HTTPException(status_code=403, detail="Non autorizzato")
    if _sid and athlete.get("society_id") and athlete.get("society_id") != _sid and not is_parent:
        raise HTTPException(status_code=404, detail="Atleta non trovato")

    code = athlete.get("qr_identifier") or athlete.get("athlete_code")
    if not code:
        raise HTTPException(status_code=404, detail="Questo atleta non ha ancora un codice QR")

    name = (athlete.get("full_name") or "").strip() or \
        f"{athlete.get('last_name') or ''} {athlete.get('first_name') or ''}".strip() or "—"

    # Nome squadra (principale)
    team_name = ""
    _tid = None
    _tids = athlete.get("team_ids") or []
    if _tids:
        _tid = _tids[0]
    _tid = _tid or athlete.get("primary_team_id") or athlete.get("team_id")
    if _tid:
        _t = await db.teams.find_one({"id": _tid}, {"_id": 0, "name": 1})
        if _t:
            team_name = _t.get("name") or ""

    _society_id = athlete.get("society_id") or _sid
    _society = await db.societies.find_one({"id": _society_id}) if _society_id else None
    society_name = (_society or {}).get("name") or ""

    from reportlab.lib.utils import ImageReader

    _logo_reader = None
    try:
        _logo_b64 = await _settings_logo_b64(_society) if _society else ""
        if _logo_b64:
            if _logo_b64.startswith("data:"):
                _logo_b64 = _logo_b64.split(",", 1)[1]
            _logo_reader = ImageReader(io.BytesIO(base64.b64decode(_logo_b64)))
    except Exception:
        _logo_reader = None

    buffer = io.BytesIO()
    c = canvas.Canvas(buffer, pagesize=A4)
    width, height = A4

    # Logo centrato in alto
    y = height - 3 * cm
    if _logo_reader is not None:
        logo_side = 3 * cm
        try:
            c.drawImage(_logo_reader, (width - logo_side) / 2, y - logo_side,
                        width=logo_side, height=logo_side,
                        preserveAspectRatio=True, mask='auto')
            y -= (logo_side + 0.6 * cm)
        except Exception:
            pass

    if society_name:
        c.setFillColor(colors.HexColor("#333333"))
        c.setFont("Helvetica-Bold", 14)
        c.drawCentredString(width / 2, y, society_name)
        y -= 1.0 * cm

    if team_name:
        c.setFillColor(colors.HexColor("#5856D6"))
        c.setFont("Helvetica-Bold", 16)
        c.drawCentredString(width / 2, y, team_name)
        y -= 1.2 * cm

    # QR grande centrato
    qr = qrcode.QRCode(version=1, box_size=10, border=1)
    qr.add_data(str(code))
    qr.make(fit=True)
    img = qr.make_image(fill_color="black", back_color="white")
    qbuf = io.BytesIO()
    img.save(qbuf, format="PNG")
    qbuf.seek(0)
    qr_size = 9 * cm
    qr_y = y - qr_size
    c.drawImage(ImageReader(qbuf), (width - qr_size) / 2, qr_y,
                width=qr_size, height=qr_size, preserveAspectRatio=True, mask='auto')

    # Nome atleta sotto il QR
    c.setFillColor(colors.HexColor("#111111"))
    c.setFont("Helvetica-Bold", 20)
    c.drawCentredString(width / 2, qr_y - 1.2 * cm, name)

    c.setFillColor(colors.HexColor("#888888"))
    c.setFont("Helvetica", 10)
    c.drawCentredString(width / 2, qr_y - 1.9 * cm, "Scansiona per registrare la presenza")

    c.showPage()
    c.save()
    buffer.seek(0)
    import re as _re
    _fname = _re.sub(r"[^\w.\-]", "_", f"QR_{name}.pdf")
    return StreamingResponse(
        io.BytesIO(buffer.getvalue()),
        media_type="application/pdf",
        headers={
            "Content-Disposition": f'inline; filename="{_fname}"',
            "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0",
        },
    )




@api_router.get("/teams/{team_id}/attendance-stats")
async def get_team_attendance_stats(team_id: str, current_user = Depends(get_current_user)):
    """Get attendance statistics for all athletes in a team"""
    # 🐛 09/08/2026 — Il Coordinatore (e il Dirigente) apriva il "Registro Presenze"
    # di una squadra e riceveva 403 → la pagina mostrava "Errore". Abilitati i ruoli
    # organizzativi (viewer/dirigente/coordinatore) oltre ad admin/coach, con
    # isolamento per società garantito dal filtro society_id sotto.
    if current_user["role"] not in [
        UserRole.ADMIN, UserRole.COACH, UserRole.VIEWER,
        UserRole.DIRIGENTE, UserRole.COORDINATORE,
    ]:
        raise HTTPException(status_code=403, detail="Non autorizzato a vedere le statistiche")
    
    # Check team exists
    team = await db.teams.find_one({"id": team_id})
    if not team:
        raise HTTPException(status_code=404, detail="Squadra non trovata")
    # Isolamento multi-tenant: la squadra deve appartenere alla società dell'utente
    _uid_sid = current_user.get("society_id")
    if _uid_sid and team.get("society_id") and team.get("society_id") != _uid_sid:
        raise HTTPException(status_code=404, detail="Squadra non trovata")
    
    # Get all athletes in the team — scoped by society.
    # 🐛 08/08/2026 — Mostrare TUTTI gli atleti assegnati alla squadra (per team_id
    # o team_id_2), esclusi solo ritirati e rifiutati/rimossi. Prima il filtro era
    # status ∈ ["active","trial"] e nascondeva gli atleti in onboarding
    # (pending / pending_trial / pending_certificate / pending_privacy) — dopo il
    # rollover di stagione o le nuove iscrizioni il Registro Presenze mostrava "0 atleti".
    _sid = current_user.get("society_id")
    _q = {
        "$or": [
            {"team_id": team_id},
            {"team_id_2": team_id},
            {"team_ids": team_id}
        ],
        "status": {"$nin": ["rejected", "withdrawn", "removed", "deleted"]},
        "is_withdrawn": {"$ne": True}
    }
    if _sid:
        _q["society_id"] = _sid
    athletes = await db.athletes.find(_q).to_list(1000)
    
    # 🆕 16/08/2026 — Mappa id→nome squadre (per etichetta "Aggregata — paga in [X]")
    _team_name_map = {}
    _team_total_map = {}  # 🆕 21/09/2026 — id→total_amount (per calcolo saldo corretto)
    async for _t in db.teams.find(
        ({"society_id": _sid} if _sid else {}),
        {"_id": 0, "id": 1, "name": 1, "total_amount": 1}
    ):
        _team_name_map[_t.get("id")] = _t.get("name") or ""
        _team_total_map[_t.get("id")] = float(_t.get("total_amount") or 0)
    
    def _primary_team_of(a):
        tids = a.get("team_ids") or []
        if tids:
            return tids[0]
        return a.get("team_id")
    
    # Also include trial athletes who have attendances for this team but no team_id set
    team_athlete_ids = [a["id"] for a in athletes]
    trial_attendance_ids = await db.attendances.distinct("athlete_id", {"team_id": team_id})
    missing_trial_ids = [aid for aid in trial_attendance_ids if aid not in team_athlete_ids]
    if missing_trial_ids:
        _q_extra = {
            "id": {"$in": missing_trial_ids},
            "status": "trial",
            "is_withdrawn": {"$ne": True}
        }
        if _sid:
            _q_extra["society_id"] = _sid
        extra_athletes = await db.athletes.find(_q_extra).to_list(100)
        athletes.extend(extra_athletes)
    
    # Get team's training sessions configuration
    training_sessions = team.get("training_sessions", [])
    trainings_per_week = len(training_sessions) if training_sessions else 3  # fallback to 3
    
    # Get current date info
    now = datetime.now()
    today_end = now.replace(hour=23, minute=59, second=59, microsecond=999999)
    
    # Set week_start to Monday 00:00:00
    week_start = (now - timedelta(days=now.weekday())).replace(hour=0, minute=0, second=0, microsecond=0)
    # Set month_start to 1st of month 00:00:00
    month_start = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)

    # 🆕 12/08/2026 — Data inizio attività: le statistiche presenze partono da questa
    # data. Prima di essa nessun allenamento viene conteggiato (attività ferma).
    activity_start = None
    _asd = team.get("activity_start_date")
    if _asd:
        try:
            activity_start = datetime.fromisoformat(str(_asd).replace('Z', '').replace('+00:00', '')).replace(hour=0, minute=0, second=0, microsecond=0)
        except Exception:
            activity_start = None
    if activity_start:
        if week_start < activity_start:
            week_start = activity_start
        if month_start < activity_start:
            month_start = activity_start

    # Calculate expected trainings based on ACTUAL training days up to TODAY
    expected_weekly = count_training_days_in_period(training_sessions, week_start, today_end)
    expected_monthly = count_training_days_in_period(training_sessions, month_start, today_end)
    
    # 🆕 13/09/2026 — Saldo atleti: visibile all'Admin SEMPRE e ai Coordinatori/collaboratori
    # con il permesso "view_balances". Mostra Totale pagato € e Saldo residuo sotto il nome.
    _perms = current_user.get("coordinator_permissions") or []
    show_balance = (current_user["role"] == UserRole.ADMIN) or (
        current_user["role"] == UserRole.COORDINATORE and "view_balances" in _perms
    )

    # Calculate stats for each athlete
    stats = []
    for athlete in athletes:
        athlete_id = athlete["id"]
        
        # Get registration date for total calculation (fallback to created_at or today)
        reg_date = athlete.get("registration_date") or athlete.get("created_at") or now
        if isinstance(reg_date, str):
            reg_date = datetime.fromisoformat(reg_date.replace('Z', '+00:00'))
        # Ensure naive datetime for comparison
        if reg_date.tzinfo is not None:
            reg_date = reg_date.replace(tzinfo=None)
        # 🆕 Clamp alla data inizio attività (le presenze contano da lì)
        if activity_start and reg_date < activity_start:
            reg_date = activity_start
        
        # Calculate expected total trainings from registration to today
        expected_total = count_training_days_in_period(training_sessions, reg_date, today_end)
        
        # Get all attendances for this athlete (dalla data inizio attività, se impostata)
        _att_q = {"athlete_id": athlete_id}
        if activity_start:
            _att_q["check_in_time"] = {"$gte": activity_start}
        all_attendances = await db.attendances.count_documents(_att_q)
        
        # Get weekly attendances (use datetime objects, not strings for MongoDB comparison)
        week_attendances = await db.attendances.count_documents({
            "athlete_id": athlete_id,
            "check_in_time": {"$gte": week_start}
        })
        
        # Get monthly attendances
        month_attendances = await db.attendances.count_documents({
            "athlete_id": athlete_id,
            "check_in_time": {"$gte": month_start}
        })
        
        # Calculate percentages based on actual expected trainings
        total_percentage = round((all_attendances / max(expected_total, 1)) * 100, 1)
        monthly_percentage = round((month_attendances / max(expected_monthly, 1)) * 100, 1)
        weekly_percentage = round((week_attendances / max(expected_weekly, 1)) * 100, 1)
        
        # Cap at 100%
        total_percentage = min(total_percentage, 100)
        monthly_percentage = min(monthly_percentage, 100)
        weekly_percentage = min(weekly_percentage, 100)
        
        # 🆕 16/08/2026 — Squadra principale (paga qui) vs aggregata (paga altrove)
        _primary_tid = _primary_team_of(athlete)
        _is_primary = (_primary_tid == team_id)
        # 🆕 13/09/2026 — Saldo (solo se autorizzato)
        # 🐛 21/09/2026 — FIX: usare la stessa formula dell'anagrafica/summary:
        # dovuto = quota squadra principale − sconto; pagato = somma dei pagamenti paid.
        # (Prima sommava TUTTI i record come dovuto → saldo gonfiato, es. 820 invece di 320.)
        bal_paid = 0.0
        bal_due = 0.0
        if show_balance:
            _quota = _team_total_map.get(_primary_tid)
            if _quota is None:
                _quota = _team_total_map.get(athlete.get("team_id"), 0.0)
            _disc = float(athlete.get("discount_amount") or 0)
            bal_due = max(0.0, float(_quota or 0) - _disc)
            async for _p in db.payments.find({"athlete_id": athlete_id, "paid": True}):
                bal_paid += float(_p.get("amount") or 0)
        stats.append({
            "athlete_id": athlete_id,
            "athlete_name": athlete["full_name"],
            "status": athlete.get("status", "active"),
            "show_balance": show_balance,
            "balance_paid": round(bal_paid, 2),
            "balance_residual": round(bal_due - bal_paid, 2),
            "is_primary_team": _is_primary,
            "primary_team_id": _primary_tid,
            "primary_team_name": _team_name_map.get(_primary_tid, "") if not _is_primary else team["name"],
            "total_attendances": all_attendances,
            "weekly_attendances": week_attendances,
            "monthly_attendances": month_attendances,
            "expected_weekly": expected_weekly,
            "expected_monthly": expected_monthly,
            "expected_total": expected_total,
            "total_percentage": total_percentage,
            "monthly_percentage": monthly_percentage,
            "weekly_percentage": weekly_percentage,
        })
    
    # Sort: trial athletes first, then by name
    stats.sort(key=lambda x: (0 if x.get("status") == "trial" else 1, x["athlete_name"]))
    
    return {
        "team_name": team["name"],
        "total_athletes": len(athletes),
        "trainings_per_week": trainings_per_week,
        "week_start": week_start.strftime("%d/%m/%Y"),
        "month_name": now.strftime("%B %Y"),
        "expected_weekly": expected_weekly,
        "expected_monthly": expected_monthly,
        "athletes": stats
    }

@api_router.get("/athletes/{athlete_id}/my-stats")
async def get_athlete_personal_stats(athlete_id: str, current_user = Depends(get_current_user)):
    """Get attendance statistics for a specific athlete (accessible by the athlete themselves)"""
    # Check if user is viewing their own stats or is admin
    user_athlete_id = current_user.get("athlete_id")
    is_own_stats = str(user_athlete_id) == str(athlete_id)
    is_admin = current_user["role"] == UserRole.ADMIN
    
    if not is_own_stats and not is_admin:
        raise HTTPException(status_code=403, detail="Puoi vedere solo le tue statistiche")
    
    # Get athlete
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    # Get team for training configuration
    team_id = athlete.get("team_id")
    training_sessions = []
    if team_id:
        team = await db.teams.find_one({"id": team_id})
        if team:
            training_sessions = team.get("training_sessions", [])
    
    trainings_per_week = len(training_sessions) if training_sessions else 3
    
    # Get current date info
    now = datetime.now()
    today_end = now.replace(hour=23, minute=59, second=59, microsecond=999999)
    week_start = (now - timedelta(days=now.weekday())).replace(hour=0, minute=0, second=0, microsecond=0)
    month_start = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
    
    # Calculate expected trainings
    expected_weekly = count_training_days_in_period(training_sessions, week_start, today_end) if training_sessions else trainings_per_week
    expected_monthly = count_training_days_in_period(training_sessions, month_start, today_end) if training_sessions else trainings_per_week * 4
    
    # Get registration date for total calculation
    reg_date = athlete.get("registration_date") or athlete.get("created_at") or now
    if isinstance(reg_date, str):
        reg_date = datetime.fromisoformat(reg_date.replace('Z', '+00:00')).replace(tzinfo=None)
    
    expected_total = count_training_days_in_period(training_sessions, reg_date, today_end) if training_sessions else 10
    expected_total = max(expected_total, 1)  # Avoid division by zero
    
    # Get attendance counts
    all_attendances = await db.attendances.count_documents({"athlete_id": athlete_id})
    week_attendances = await db.attendances.count_documents({
        "athlete_id": athlete_id,
        "check_in_time": {"$gte": week_start}
    })
    month_attendances = await db.attendances.count_documents({
        "athlete_id": athlete_id,
        "check_in_time": {"$gte": month_start}
    })
    
    # Calculate percentages
    weekly_percentage = min(100, round((week_attendances / max(expected_weekly, 1)) * 100))
    monthly_percentage = min(100, round((month_attendances / max(expected_monthly, 1)) * 100))
    total_percentage = min(100, round((all_attendances / expected_total) * 100))
    
    return {
        "athlete_id": athlete_id,
        "athlete_name": athlete.get("full_name"),
        "total_attendances": all_attendances,
        "weekly_attendances": week_attendances,
        "monthly_attendances": month_attendances,
        "weekly_percentage": weekly_percentage,
        "monthly_percentage": monthly_percentage,
        "total_percentage": total_percentage,
        "expected_weekly": expected_weekly,
        "expected_monthly": expected_monthly,
        "expected_total": expected_total
    }

