@api_router.get("/admin/payments/duplicates")
async def get_payment_duplicates(current_user = Depends(get_current_user)):
    """🆕 20/09/2026 — Igiene dati pagamenti: rileva atleti con RATE DUPLICATE
    (stessa rata/installment_number presente più volte tra i pagamenti non ricorrenti).
    Suggerisce quali record eliminare (mantiene quello pagato o il più vecchio)."""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")

    society_id = current_user.get("society_id")
    athletes = await db.athletes.find(
        {"society_id": society_id, "is_withdrawn": {"$ne": True}},
        {"athlete_photo": 0, "athlete_photo_artistic": 0, "doc_back_image": 0,
         "doc_front_image": 0, "privacy_signature": 0, "privacy_pdf_snapshot": 0},
    ).to_list(10000)
    teams = await db.teams.find({"society_id": society_id} if society_id else {}).to_list(200)
    team_map = {t["id"]: t.get("name", "") for t in teams}

    result = []
    for a in athletes:
        payments = await db.payments.find({"athlete_id": a["id"]}).to_list(200)
        # Raggruppa per numero rata (solo non ricorrenti, con installment_number valorizzato)
        groups = {}
        for p in payments:
            if p.get("recurring_plan_id"):
                continue
            key = p.get("installment_number")
            if key is None:
                continue
            groups.setdefault(key, []).append(p)

        dup_groups = []
        for key in sorted(groups.keys()):
            plist = groups[key]
            if len(plist) <= 1:
                continue
            # Mantieni: il pagato se esiste, altrimenti il più vecchio. Gli altri = eliminabili.
            def _sort_key(x):
                created = x.get("created_at")
                return (0 if x.get("paid") else 1, str(created))
            ordered = sorted(plist, key=_sort_key)
            keep_id = ordered[0].get("id")
            records = []
            for p in ordered:
                records.append({
                    "id": p.get("id", ""),
                    "name": p.get("installment_name") or p.get("description") or f"Rata {key}",
                    "amount": p.get("amount", 0),
                    "paid": bool(p.get("paid")),
                    "paid_amount": p.get("paid_amount", 0) or 0,
                    "suggested_delete": p.get("id") != keep_id,
                })
            dup_groups.append({
                "installment_number": key,
                "label": (ordered[0].get("installment_name") or ordered[0].get("description") or f"Rata {key}"),
                "count": len(plist),
                "records": records,
            })

        if dup_groups:
            result.append({
                "athlete_id": a["id"],
                "athlete_name": f"{a.get('last_name','')} {a.get('first_name','')}".strip(),
                "team_name": team_map.get(a.get("team_id"), ""),
                "groups": dup_groups,
            })

    result.sort(key=lambda x: x.get("athlete_name", "").upper())
    return {"count": len(result), "athletes": result}


@api_router.get("/admin/payments/rate-summary")
async def get_rate_summary(current_user = Depends(get_current_user)):
    """🆕 20/09/2026 — Riepilogo cassa per fascia (stagione, tutti gli atleti).
    Per ogni atleta: dovuto per rata dallo scadenzario squadra (sconto sull'ultima rata),
    incassato = somma pagamenti reali (paid=True, non ricorrenti) SCALATO in ordine 1ª→2ª→3ª
    (waterfall). Ricorrenti gestiti a parte. Restituisce dovuto/pagato/residuo per fascia."""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")

    society_id = current_user.get("society_id")
    athletes = await db.athletes.find(
        {"society_id": society_id, "is_withdrawn": {"$ne": True}},
        {"id": 1, "team_id": 1, "discount_amount": 1},
    ).to_list(20000)
    teams = await db.teams.find({"society_id": society_id} if society_id else {}).to_list(300)
    team_map = {t["id"]: t for t in teams}

    ath_ids = [a["id"] for a in athletes]
    # Tutti i pagamenti degli atleti della società
    payments = await db.payments.find({"athlete_id": {"$in": ath_ids}}).to_list(100000)
    pay_by_ath: dict = {}
    for p in payments:
        pay_by_ath.setdefault(p["athlete_id"], []).append(p)

    def _schedule_for(team: dict, discount: float):
        """Ritorna la lista degli importi dovuti per rata (sconto sull'ultima rata > 0)."""
        amounts = []
        dyn = team.get("installments") or []
        for inst in dyn:
            try:
                amt = float(inst.get("amount") or 0)
            except (TypeError, ValueError):
                amt = 0
            if amt > 0:
                amounts.append(amt)
        if not amounts:
            for key in ("installment_1_amount", "installment_2_amount", "installment_3_amount"):
                amt = team.get(key) or 0
                try:
                    amt = float(amt)
                except (TypeError, ValueError):
                    amt = 0
                if amt > 0:
                    amounts.append(amt)
        if amounts and discount:
            amounts[-1] = max(0.0, amounts[-1] - float(discount))
        return amounts

    max_rate = 0
    rate_agg: dict = {}   # idx -> {due, paid, residuo}
    rec = {"due": 0.0, "paid": 0.0, "residuo": 0.0}
    altro = {"due": 0.0, "paid": 0.0, "residuo": 0.0}

    def _bucket(idx):
        if idx not in rate_agg:
            rate_agg[idx] = {"due": 0.0, "paid": 0.0, "residuo": 0.0}
        return rate_agg[idx]

    for a in athletes:
        team = team_map.get(a.get("team_id"))
        discount = a.get("discount_amount", 0) or 0
        schedule = _schedule_for(team, discount) if team else []
        max_rate = max(max_rate, len(schedule))

        plist = pay_by_ath.get(a["id"], [])
        paid_nonrec = 0.0
        for p in plist:
            if p.get("status") == "refunded":
                continue
            if p.get("recurring_plan_id"):
                # Ricorrenti: dovuto = amount, pagato se paid
                amt = float(p.get("amount", 0) or 0)
                rec["due"] += amt
                if p.get("paid"):
                    rec["paid"] += amt
                else:
                    rec["residuo"] += amt
                continue
            if p.get("paid"):
                paid_nonrec += float(p.get("amount", 0) or 0)

        # Waterfall dell'incassato sulle rate in ordine
        remaining = paid_nonrec
        for idx, due_i in enumerate(schedule):
            b = _bucket(idx)
            pay_i = min(remaining, due_i)
            remaining -= pay_i
            b["due"] += due_i
            b["paid"] += pay_i
            b["residuo"] += max(due_i - pay_i, 0.0)
        # Eventuale incassato oltre lo scadenzario (o atleti senza piano rate)
        if remaining > 0.0001:
            altro["paid"] += remaining

    rate = []
    for idx in range(max_rate):
        b = rate_agg.get(idx, {"due": 0.0, "paid": 0.0, "residuo": 0.0})
        label = "Iscrizione - Rata 1" if idx == 0 else f"Rata {idx + 1}"
        rate.append({
            "index": idx,
            "label": label,
            "short": f"{idx + 1}ª rata",
            "due": round(b["due"], 2),
            "paid": round(b["paid"], 2),
            "residuo": round(b["residuo"], 2),
        })

    total_due = round(sum(r["due"] for r in rate) + rec["due"] + altro["due"], 2)
    total_paid = round(sum(r["paid"] for r in rate) + rec["paid"] + altro["paid"], 2)
    total_residuo = round(sum(r["residuo"] for r in rate) + rec["residuo"] + altro["residuo"], 2)

    return {
        "rate": rate,
        "recurring": {"due": round(rec["due"], 2), "paid": round(rec["paid"], 2), "residuo": round(rec["residuo"], 2)},
        "altro": {"due": round(altro["due"], 2), "paid": round(altro["paid"], 2), "residuo": round(altro["residuo"], 2)},
        "total_due": total_due,
        "total_paid": total_paid,
        "total_residuo": total_residuo,
    }



class PaymentUpdate(BaseModel):
    amount: float
    paid_date: str
    is_cash: bool = False
    notes: Optional[str] = None
    description: Optional[str] = None
    payment_method: Optional[str] = None

@api_router.put("/payments/manual/{payment_id}")
async def update_manual_payment(payment_id: str, payment_data: PaymentUpdate, current_user = Depends(get_current_user)):
    """Update a manual payment record (admin only)"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può modificare pagamenti")
    
    payment = await db.payments.find_one({"id": payment_id})
    if not payment:
        raise HTTPException(status_code=404, detail="Pagamento non trovato")
    
    # Parse date (format: gg/mm/aaaa)
    try:
        parts = payment_data.paid_date.split('/')
        paid_date = datetime(int(parts[2]), int(parts[1]), int(parts[0]))
    except:
        raise HTTPException(status_code=400, detail="Formato data non valido. Usa gg/mm/aaaa")
    
    # Use provided payment_method or derive from is_cash
    payment_method = payment_data.payment_method if payment_data.payment_method else ("Contanti" if payment_data.is_cash else "Bonifico")
    
    # Use provided description or generate default
    description = payment_data.description if payment_data.description else f"Pagamento del {payment_data.paid_date}"
    
    update_data = {
        "amount": payment_data.amount,
        "paid_date": paid_date,
        "is_cash": payment_data.is_cash or payment_method == "Contanti",
        "payment_method": payment_method,
        "notes": payment_data.notes,
        "description": description,
    }
    
    await db.payments.update_one({"id": payment_id}, {"$set": update_data})
    
    updated_payment = await db.payments.find_one({"id": payment_id})
    clean_mongo_docs([updated_payment])
    return Payment(**updated_payment)

@api_router.get("/payments/{athlete_id}/summary")
async def get_payment_summary(athlete_id: str, current_user = Depends(get_current_user)):
    """Get payment summary for an athlete including total due, paid, and residual"""
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    if current_user["role"] == UserRole.PARENT:
        is_primary = athlete.get("parent_id") == current_user["id"]
        is_second = athlete.get("second_parent_id") == current_user["id"]
        if not is_primary and not is_second:
            raise HTTPException(status_code=403, detail="Accesso negato")
    
    # Get team for quote amounts
    team = await db.teams.find_one({"id": athlete["team_id"]})
    if not team:
        raise HTTPException(status_code=404, detail="Squadra non trovata")
    
    total_due = team.get("total_amount", 0)
    discount = athlete.get("discount_amount", 0)
    total_after_discount = total_due - discount
    
    # Get all payments
    payments = await db.payments.find({"athlete_id": athlete_id, "paid": True}).to_list(100)
    total_paid = sum(p.get("amount", 0) for p in payments)
    
    # Calculate residual - can be negative if overpaid
    residual = total_after_discount - total_paid

    # 🐛 28/07/2026 — Ritorno anche l'array dinamico di rate (fino a 12).
    # Il vecchio dict `installments.{first,second,third}` mostrava solo 3 rate,
    # quindi genitori/admin non vedevano dalla 4ª in su. Rinominiamo i nomi
    # in base alla POSIZIONE per consistenza con l'admin form.
    def _label(idx: int) -> str:
        return "Iscrizione - Rata 1" if idx == 0 else f"Rata {idx + 1}"

    dynamic_installments = team.get("installments") or []
    installments_list = []
    for idx, inst in enumerate(dynamic_installments):
        try:
            amt = float(inst.get("amount") or 0)
        except (TypeError, ValueError):
            amt = 0
        if amt <= 0:
            continue
        # Sconto applicato SEMPRE sull'ultima rata > 0
        installments_list.append({
            "name": _label(len(installments_list)),
            "amount": amt,
            "due_date": inst.get("due_date"),
        })
    # Se non c'è l'array dinamico, ricostruisci dai campi legacy
    if not installments_list:
        legacy = [
            ("installment_1_amount", None),
            ("installment_2_amount", "installment_2_due_date"),
            ("installment_3_amount", "installment_3_due_date"),
        ]
        for a_key, d_key in legacy:
            amt = team.get(a_key) or 0
            if amt <= 0:
                continue
            installments_list.append({
                "name": _label(len(installments_list)),
                "amount": amt,
                "due_date": team.get(d_key) if d_key else None,
            })
    # Applica lo sconto sull'ultima rata (comportamento storico)
    if installments_list and discount:
        installments_list[-1] = {
            **installments_list[-1],
            "amount": max(0, installments_list[-1]["amount"] - discount),
            "discounted": True,
        }
    
    return {
        "total_due": total_due,
        "discount": discount,
        "discount_note": athlete.get("discount_note", ""),
        "total_after_discount": total_after_discount,
        "total_paid": total_paid,
        "residual": residual,
        # 🆕 Dinamico — usare questo lato client
        "installments_list": installments_list,
        # Legacy 3-fisso — mantenuto per retrocompatibilità
        "installments": {
            "first": team.get("installment_1_amount", 0),
            "second": team.get("installment_2_amount", 0),
            "third": team.get("installment_3_amount", 0) - discount  # Sconto su ultima rata
        }
    }

@api_router.get("/notifications/expiring")
async def get_expiring_notifications(current_user = Depends(get_current_user)):
    """Get notifications for upcoming payment and certificate expirations (7 days)"""
    from datetime import datetime, timedelta
    
    notifications = []
    today = datetime.utcnow().replace(hour=0, minute=0, second=0, microsecond=0)
    seven_days_later = today + timedelta(days=7)
    
    # Get athletes based on user role
    athletes_to_check = []
    
    if current_user["role"] == "athlete":
        # Adult athlete - check their own data
        athlete_id = current_user.get("athlete_id")
        if athlete_id:
            athlete = await db.athletes.find_one({"id": athlete_id})
            if athlete:
                athletes_to_check.append(athlete)
    elif current_user["role"] == UserRole.PARENT:
        # Parent - check all their children
        parent_id = current_user["id"]
        children = await db.athletes.find({
            "$or": [
                {"parent_id": parent_id},
                {"second_parent_id": parent_id}
            ]
        }).to_list(100)
        athletes_to_check.extend(children)
    else:
        # Admin/Coach/etc - no personal notifications
        return {"notifications": []}
    
    for athlete in athletes_to_check:
        athlete_name = f"{athlete.get('first_name', '')} {athlete.get('last_name', '')}".strip()
        athlete_id = athlete.get("id")
        
        # Check medical certificate expiry
        cert_expiry = athlete.get("medical_certificate_expiry")
        if cert_expiry:
            if isinstance(cert_expiry, str):
                try:
                    cert_expiry = datetime.fromisoformat(cert_expiry.replace('Z', '+00:00'))
                except:
                    cert_expiry = None
            
            if cert_expiry:
                cert_expiry_date = cert_expiry.replace(tzinfo=None)
                if cert_expiry_date <= seven_days_later:
                    days_until = (cert_expiry_date - today).days
                    if days_until < 0:
                        status = "expired"
                        message = f"Certificato medico SCADUTO"
                    elif days_until == 0:
                        status = "urgent"
                        message = f"Certificato medico scade OGGI"
                    else:
                        status = "warning"
                        message = f"Certificato medico scade tra {days_until} giorni"
                    
                    notifications.append({
                        "type": "certificate",
                        "athlete_id": athlete_id,
                        "athlete_name": athlete_name,
                        "message": message,
                        "status": status,
                        "expiry_date": cert_expiry_date.strftime("%d/%m/%Y"),
                        "days_until": days_until
                    })
        
        # Check payment due dates
        payments = await db.payments.find({
            "athlete_id": athlete_id,
            "paid": {"$ne": True}
        }).to_list(100)
        
        for payment in payments:
            due_date = payment.get("due_date")
            if due_date:
                if isinstance(due_date, str):
                    try:
                        due_date = datetime.fromisoformat(due_date.replace('Z', '+00:00'))
                    except:
                        due_date = None
                
                if due_date:
                    due_date_clean = due_date.replace(tzinfo=None)
                    if due_date_clean <= seven_days_later:
                        days_until = (due_date_clean - today).days
                        amount = payment.get("amount", 0)
                        
                        if days_until < 0:
                            status = "expired"
                            message = f"Rata €{amount:.0f} SCADUTA"
                        elif days_until == 0:
                            status = "urgent"
                            message = f"Rata €{amount:.0f} scade OGGI"
                        else:
                            status = "warning"
                            message = f"Rata €{amount:.0f} scade tra {days_until} giorni"
                        
                        notifications.append({
                            "type": "payment",
                            "athlete_id": athlete_id,
                            "athlete_name": athlete_name,
                            "message": message,
                            "status": status,
                            "due_date": due_date_clean.strftime("%d/%m/%Y"),
                            "days_until": days_until,
                            "amount": amount
                        })
    
        # Check trial period expiring - only for athletes still in trial status
        athlete_status = athlete.get("status", "")
        if athlete_status == "trial" and athlete.get("trial_start_date"):
            # Check if athlete already has a valid medical certificate
            cert = await db.certificates.find_one({"athlete_id": athlete_id})
            has_valid_cert = False
            if cert:
                cert_exp = cert.get("expiry_date")
                if cert_exp:
                    try:
                        exp_dt = datetime.fromisoformat(str(cert_exp).replace('Z', '+00:00')) if isinstance(cert_exp, str) else cert_exp
                        has_valid_cert = exp_dt.replace(tzinfo=None) > today
                    except:
                        pass
            
            # 🐛 08/07/2026 fix multi-tenancy
            _asid_t = athlete.get("society_id")
            society_settings = await db.settings.find_one({"type": "society", "society_id": _asid_t}) if _asid_t else await db.settings.find_one({"type": "society"})
            max_sessions = society_settings.get("trial_max_sessions", 3) if society_settings else 3
            max_days = society_settings.get("trial_max_days", 7) if society_settings else 7
            sessions_count = athlete.get("trial_sessions_count", 0)
            sessions_remaining = max_sessions - sessions_count
            
            days_remaining = None
            trial_end = athlete.get("trial_end_date")
            if trial_end:
                try:
                    end_dt = datetime.fromisoformat(str(trial_end)) if isinstance(trial_end, str) else trial_end
                    days_remaining = max(0, (end_dt.replace(tzinfo=None) - today).days)
                except:
                    pass
            
            trial_expired = (days_remaining is not None and days_remaining <= 0) or sessions_count >= max_sessions
            trial_warning = not trial_expired and (sessions_remaining <= 1 or (days_remaining is not None and days_remaining <= 2))
            
            if trial_expired:
                if not has_valid_cert:
                    notifications.append({
                        "type": "trial",
                        "athlete_id": athlete_id,
                        "athlete_name": athlete_name,
                        "message": "Periodo di prova terminato. Inserire certificato medico per proseguire.",
                        "status": "expired",
                        "days_until": 0,
                        "sessions_remaining": 0,
                        "trial_days_remaining": days_remaining or 0,
                    })
            elif trial_warning:
                warn_detail = f"Rimane {sessions_remaining} allenamento" if sessions_remaining <= 1 else f"Rimangono {days_remaining} giorni"
                notifications.append({
                    "type": "trial",
                    "athlete_id": athlete_id,
                    "athlete_name": athlete_name,
                    "message": f"Il periodo di prova sta per terminare. {warn_detail}. Per continuare l'attivita e necessario inserire il certificato medico.",
                    "status": "urgent",
                    "days_until": days_remaining if days_remaining is not None else 1,
                    "sessions_remaining": max(0, sessions_remaining),
                    "trial_days_remaining": days_remaining,
                })
    
    # Sort by urgency (expired first, then by days_until)
    notifications.sort(key=lambda x: (
        0 if x["status"] == "expired" else (1 if x["status"] == "urgent" else 2),
        x.get("days_until", 999)
    ))
    
    return {"notifications": notifications}


@api_router.get("/payments/{athlete_id}/fiscal-receipt")
async def get_fiscal_receipt_data(athlete_id: str, current_user = Depends(get_current_user)):
    """Get all data needed to generate a fiscal receipt for an athlete"""
    # Get athlete
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    # Check permissions - parent can only access their children
    if current_user["role"] == UserRole.PARENT:
        if athlete.get("parent_id") != current_user["id"] and athlete.get("second_parent_id") != current_user["id"]:
            raise HTTPException(status_code=403, detail="Accesso negato")
    
    # Get parent data
    parent = await db.users.find_one({"id": athlete.get("parent_id")})
    
    # Get team
    team = await db.teams.find_one({"id": athlete.get("team_id")})
    
    # Get society settings from correct collection — 🐛 08/07/2026 fix multi-tenancy
    society = await db.settings.find_one({"type": "society", "society_id": athlete.get("society_id")}) if athlete.get("society_id") else await db.settings.find_one({"type": "society"})
    
    # Get all payments for this athlete
    payments = await db.payments.find({"athlete_id": athlete_id, "paid": True}).sort("paid_date", 1).to_list(100)

    # 🆕 10/08/2026 — Backfill N. Prog. per pagamenti PAGATI senza ricevuta
    # (es. incassi Stripe registrati prima di questo fix). Assegnati in ordine
    # cronologico (paid_date asc) così l'attestato mostra sempre il progressivo.
    from utils import get_next_receipt_number as _next_rn
    for p in payments:
        if p.get("paid") and not p.get("receipt_number"):
            try:
                rn = await _next_rn(db, athlete.get("society_id") or "")
                await db.payments.update_one({"id": p["id"]}, {"$set": {"receipt_number": rn}})
                p["receipt_number"] = rn
            except Exception:
                pass

    def _method_label(p: dict) -> str:
        """Etichetta leggibile del metodo di pagamento per la colonna Note."""
        pm = (p.get("payment_method") or "").strip().lower()
        if pm == "stripe":
            return "Online con Stripe (ricorrente)" if p.get("recurring_plan_id") else "Online con Stripe"
        if pm in ("contanti", "cash") or p.get("is_cash"):
            return "Contanti"
        if pm in ("bonifico", "bank", "bank_transfer", "wire"):
            return "Bonifico"
        if pm == "pos":
            return "POS"
        return (p.get("payment_method") or "").strip() or (p.get("notes") or "")
    
    # Generate receipt number based on date and athlete
    from datetime import datetime
    now = datetime.utcnow()
    receipt_count = await db.payments.count_documents({"athlete_id": athlete_id, "paid": True})
    receipt_number = f"RF-{now.year}-{str(receipt_count).zfill(4)}"
    
    # 🐛 19/07/2026 — Fix: usa la stagione configurata dalla società
    # (season_start_month/day) invece di hardcodare luglio-giugno. Prima
    # l'attestato mostrava "2025/2026" anche quando l'admin aveva già impostato
    # la stagione 2026/2027 in Impostazioni.
    from utils import get_current_season_for_society
    season_raw = await get_current_season_for_society(db, athlete.get("society_id"))
    season = season_raw.replace("-", "/")
    
    return {
        "athlete": {
            "first_name": athlete.get("first_name", ""),
            "last_name": athlete.get("last_name", ""),
            "fiscal_code": athlete.get("fiscal_code", ""),
            "address": athlete.get("address", ""),
            "postal_code": athlete.get("postal_code", ""),
            "city": athlete.get("city", ""),
            "province": athlete.get("province", ""),
            "date_of_birth": athlete.get("date_of_birth"),
            "birth_place": athlete.get("birth_place", ""),
            "birth_province": athlete.get("birth_province", ""),
            "country_of_birth": athlete.get("country_of_birth", "Italia"),
        },
        "parent": {
            "first_name": athlete.get("tax_payer_first_name", "") or (parent.get("first_name", "") if parent else current_user.get("first_name", "")),
            "last_name": athlete.get("tax_payer_last_name", "") or (parent.get("last_name", "") if parent else current_user.get("last_name", "")),
            "fiscal_code": athlete.get("tax_payer_fiscal_code", "") or (parent.get("fiscal_code", "") or parent.get("tax_code", "") if parent else current_user.get("fiscal_code", "") or current_user.get("tax_code", "")),
        },
        "society": {
            "name": society.get("name") or society.get("ragione_sociale", "SOCIETÀ SPORTIVA") if society else "SOCIETÀ SPORTIVA",
            "address": society.get("address", "") if society else "",
            "city": society.get("city", "") if society else "",
            "postal_code": society.get("postal_code", "") if society else "",
            "province": society.get("province", "") if society else "",
            "fiscal_code": society.get("fiscal_code", "") if society else "",
            "phone": society.get("phone", "") if society else "",
            "phone2": society.get("phone2", "") if society else "",
            "president_name": society.get("president_name", "") if society else "",
            "logo": await _settings_logo_b64(society),
            "stamp_signature": society.get("stamp_signature", "") if society else "",
            "sport_type": society.get("sport_type", "PALLAVOLO") if society else "PALLAVOLO",
        },
        "team_name": team.get("name", "") if team else "",
        "season": season,
        "receipt_number": receipt_number,
        "payments": [
            {
                "date": p.get("paid_date").isoformat() if p.get("paid_date") else "",
                "receipt_number": p.get("receipt_number", ""),
                "amount": p.get("amount", 0),
                "description": p.get("description", ""),
                "notes": _method_label(p),
                "payment_method": _method_label(p),
                "registration_date": p.get("registration_date").isoformat() if p.get("registration_date") else "",
            }
            for p in payments
        ],
    }

@api_router.patch("/payments/{payment_id}", response_model=Payment)
async def update_payment(payment_id: str, update_data: PaymentUpdate, current_user = Depends(get_current_user)):
    payment = await db.payments.find_one({"id": payment_id})
    if not payment:
        raise HTTPException(status_code=404, detail="Pagamento non trovato")
    
    # Check permissions - allow primary and second parent
    athlete = await db.athletes.find_one({"id": payment["athlete_id"]})
    if current_user["role"] == UserRole.PARENT:
        is_primary = athlete.get("parent_id") == current_user["id"]
        is_second = athlete.get("second_parent_id") == current_user["id"]
        if not is_primary and not is_second:
            raise HTTPException(status_code=403, detail="Accesso negato")
    
    update_dict = {}
    if update_data.paid is not None:
        update_dict["paid"] = update_data.paid
        if update_data.paid:
            update_dict["paid_date"] = datetime.utcnow()
            if update_data.payment_method:
                update_dict["payment_method"] = update_data.payment_method
            # Generate receipt number only if not already assigned
            if not payment.get("receipt_number"):
                receipt_number = await get_next_receipt_number(athlete.get("society_id") or "")
                update_dict["receipt_number"] = receipt_number
    
    if update_dict:
        await db.payments.update_one({"id": payment_id}, {"$set": update_dict})
        payment.update(update_dict)
    
    return Payment(**payment)

async def get_next_receipt_number(society_id: str) -> str:
    """Generate next receipt number for the current sports season: RIC-24/25-0001
    Sports season dates are configurable in society settings (default: July 1st - June 30th)
    """
    now = datetime.utcnow()
    
    # Get season start from society settings — 🐛 08/07/2026 fix multi-tenancy
    settings = await db.settings.find_one({"type": "society", "society_id": society_id}) if society_id else await db.settings.find_one({"type": "society"})
    season_start_month = settings.get("season_start_month", 7) if settings else 7  # Default July
    season_start_day = settings.get("season_start_day", 1) if settings else 1  # Default 1st
    
    # Determine current sports season based on configurable start date
    # If we're past the season start date, season is current_year/next_year
    # If we're before the season start date, season is previous_year/current_year
    season_start_this_year = datetime(now.year, season_start_month, season_start_day)
    
    if now >= season_start_this_year:
        # We're in the new season (current_year/next_year)
        season_start_year = now.year
        season_end_year = now.year + 1
    else:
        # We're still in the old season (previous_year/current_year)
        season_start_year = now.year - 1
        season_end_year = now.year
    
    # Format: RIC-24/25-0001
    season_str = f"{season_start_year % 100:02d}/{season_end_year % 100:02d}"
    prefix = f"RIC-{season_str}-"
    
    # 🆕 13/09/2026 — Numerazione INDIPENDENTE per società: si contano solo le ricevute
    # dei pagamenti degli atleti di QUESTA società (i pagamenti non salvano society_id,
    # quindi si passa dagli atleti). Senza society_id resta il comportamento globale.
    receipt_query = {"receipt_number": {"$regex": f"^{prefix}"}}
    if society_id:
        _ath_ids = [a["id"] for a in await db.athletes.find({"society_id": society_id}, {"_id": 0, "id": 1}).to_list(20000)]
        receipt_query["athlete_id"] = {"$in": _ath_ids}
    last_payment = await db.payments.find_one(receipt_query, sort=[("receipt_number", -1)])
    
    if last_payment and last_payment.get("receipt_number"):
        # Extract the number and increment
        try:
            last_num = int(last_payment["receipt_number"].split("-")[-1])
            next_num = last_num + 1
        except:
            next_num = 1
    else:
        next_num = 1
    
    return f"{prefix}{next_num:04d}"

async def get_next_attestato_number() -> str:
    """Generate next attestato number for the current year: ATT-2025-0001"""
    current_year = datetime.utcnow().year
    prefix = f"ATT-{current_year}-"
    
    # Find the highest attestato number for this year
    last_attestato = await db.attestati_versamento.find_one(
        {
            "attestato_number": {"$regex": f"^{prefix}"},
        },
        sort=[("attestato_number", -1)]
    )
    
    if last_attestato and last_attestato.get("attestato_number"):
        try:
            last_num = int(last_attestato["attestato_number"].split("-")[-1])
            next_num = last_num + 1
        except:
            next_num = 1
    else:
        next_num = 1
    
    return f"{prefix}{next_num:04d}"

@api_router.post("/attestati/generate-number/{athlete_id}")
async def generate_attestato_number(
    athlete_id: str,
    current_user = Depends(get_current_user)
):
    """Generate and save a unique attestato number for a minor athlete"""
    if current_user["role"] not in [UserRole.ADMIN, UserRole.PARENT]:
        raise HTTPException(status_code=403, detail="Solo admin e genitori possono generare attestati")
    
    # Check if athlete exists
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    # Check if there's already an attestato for this athlete this year
    current_year = datetime.utcnow().year
    existing = await db.attestati_versamento.find_one({
        "athlete_id": athlete_id,
        "year": current_year
    })
    
    if existing:
        return {"attestato_number": existing["attestato_number"], "existing": True}
    
    # Generate new number
    attestato_number = await get_next_attestato_number()
    
    # Save to database
    attestato_record = {
        "id": str(uuid.uuid4()),
        "attestato_number": attestato_number,
        "athlete_id": athlete_id,
        "athlete_name": athlete.get("full_name", ""),
        "year": current_year,
        "created_at": datetime.utcnow().isoformat(),
        "created_by": current_user["id"]
    }
    await db.attestati_versamento.insert_one(attestato_record)
    
    return {"attestato_number": attestato_number, "existing": False}

@api_router.get("/attestati/number/{athlete_id}")
async def get_attestato_number(
    athlete_id: str,
    current_user = Depends(get_current_user)
):
    """Get existing attestato number for an athlete this year, or None if not generated yet"""
    current_year = datetime.utcnow().year
    existing = await db.attestati_versamento.find_one({
        "athlete_id": athlete_id,
        "year": current_year
    })
    
    if existing:
        return {"attestato_number": existing["attestato_number"]}
    return {"attestato_number": None}

@api_router.post("/payments/import")
async def import_payments(file: UploadFile = File(...), current_user = Depends(get_current_user)):
    """Import payments from Excel file. Matches athletes by Cognome+Nome or CodiceAtleta."""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può importare pagamenti")
    
    content = await file.read()
    
    try:
        import pandas as pd
        from io import BytesIO
        import unicodedata
        
        df = pd.read_excel(BytesIO(content))
        
        # Detect format: new (Cognome+Nome) or legacy (CodiceAtleta)
        has_name_cols = 'Cognome' in df.columns and 'Nome' in df.columns
        has_code_col = 'CodiceAtleta' in df.columns
        
        if not has_name_cols and not has_code_col:
            raise HTTPException(status_code=400, detail="Colonne mancanti: serve 'Cognome' + 'Nome' oppure 'CodiceAtleta'")
        
        required_cols = ['DataPagamento', 'Importo', 'TipoPagamento']
        missing_cols = [col for col in required_cols if col not in df.columns]
        if missing_cols:
            raise HTTPException(status_code=400, detail=f"Colonne mancanti: {', '.join(missing_cols)}")
        
        society_id = current_user.get("society_id")
        imported = 0
        errors = []
        duplicates = []
        unresolved = []
        
        # Pre-load all athletes for name matching
        society_query = {
            "$or": [
                {"society_id": society_id},
                {"society_id": None},
                {"society_id": "None"},
                {"society_id": ""},
                {"society_id": {"$exists": False}}
            ],
            "is_withdrawn": {"$ne": True}
        }
        all_athletes = await db.athletes.find(society_query).to_list(1000)
        _teams_q = {"society_id": society_id} if society_id else {}
        teams = await db.teams.find(_teams_q).to_list(100)
        team_dict = {t["id"]: t["name"] for t in teams}
        
        def normalize_name(s):
            """Normalize name for matching: uppercase, strip, remove accents"""
            if not s or (isinstance(s, float) and pd.isna(s)):
                return ""
            s = str(s).strip().upper()
            s = unicodedata.normalize('NFD', s)
            s = ''.join(c for c in s if unicodedata.category(c) != 'Mn')
            return s
        
        def find_athlete_by_name(cognome_input, nome_input):
            """Find athlete by Cognome+Nome with fuzzy matching.
            Returns (athlete, error_msg, candidates) - candidates only for ambiguous matches"""
            cn = normalize_name(cognome_input)
            nn = normalize_name(nome_input)
            if not cn:
                return None, "Cognome mancante", None
            
            # 1) Exact match last_name + first_name
            exact = [a for a in all_athletes 
                     if normalize_name(a.get("last_name")) == cn 
                     and normalize_name(a.get("first_name")) == nn]
            if len(exact) == 1:
                return exact[0], None, None
            if len(exact) > 1:
                candidates = [{"id": a["id"], "first_name": a.get("first_name",""), "last_name": a.get("last_name",""), "team": team_dict.get(a.get("team_id"), "?")} for a in exact]
                return None, f"Trovati {len(exact)} omonimi", candidates
            
            # 2) Match only by last_name
            by_surname = [a for a in all_athletes if normalize_name(a.get("last_name")) == cn]
            if len(by_surname) == 1:
                return by_surname[0], None, None
            if len(by_surname) > 1:
                if nn:
                    partial = [a for a in by_surname 
                               if nn in normalize_name(a.get("first_name")) 
                               or normalize_name(a.get("first_name")) in nn
                               or nn[:3] == normalize_name(a.get("first_name"))[:3]]
                    if len(partial) == 1:
                        return partial[0], None, None
                candidates = [{"id": a["id"], "first_name": a.get("first_name",""), "last_name": a.get("last_name",""), "team": team_dict.get(a.get("team_id"), "?")} for a in by_surname]
                return None, f"Cognome '{cognome_input}' ambiguo", candidates
            
            # 3) No match
            return None, f"Atleta '{cognome_input} {nome_input}' non trovato nel sistema", None
        
        for idx, row in df.iterrows():
            try:
                # Find athlete - by name or by code
                athlete = None
                match_label = ""
                
                if has_name_cols and not has_code_col:
                    # New format: Cognome + Nome
                    cognome = row.get('Cognome', '')
                    nome = row.get('Nome', '')
                    if pd.isna(cognome) or str(cognome).strip() == '':
                        errors.append(f"Riga {idx+2}: Cognome mancante")
                        continue
                    athlete, match_error, candidates = find_athlete_by_name(cognome, nome)
                    match_label = f"{cognome} {nome}".strip()
                    if not athlete:
                        if candidates:
                            # Ambiguous match - save row data and candidates for frontend resolution
                            row_data = {}
                            for col in df.columns:
                                val = row.get(col, '')
                                row_data[col] = '' if (isinstance(val, float) and pd.isna(val)) else str(val)
                            unresolved.append({
                                "row_index": idx + 2,
                                "cognome": str(cognome),
                                "nome": str(nome),
                                "row_data": row_data,
                                "candidates": candidates,
                                "error": match_error,
                            })
                        else:
                            errors.append(f"Riga {idx+2}: {match_error}")
                        continue
                elif has_code_col:
                    # Legacy format: CodiceAtleta
                    athlete_code = str(row['CodiceAtleta']).strip().upper()
                    athlete = await db.athletes.find_one({
                        "athlete_code": athlete_code,
                        "$or": [
                            {"society_id": society_id},
                            {"society_id": None},
                            {"society_id": "None"},
                            {"society_id": ""},
                            {"society_id": {"$exists": False}}
                        ]
                    })
                    match_label = athlete_code
                    if not athlete:
                        errors.append(f"Riga {idx+2}: Atleta {athlete_code} non trovato")
                        continue
                
                # Parse dates
                data_pagamento = row['DataPagamento']
                if isinstance(data_pagamento, str):
                    try:
                        data_pagamento = datetime.strptime(data_pagamento, "%d/%m/%Y")
                    except:
                        data_pagamento = datetime.strptime(data_pagamento, "%Y-%m-%d")
                
                data_registrazione = None
                if 'DataRegistrazione' in df.columns and pd.notna(row.get('DataRegistrazione')):
                    dr = row['DataRegistrazione']
                    if isinstance(dr, str):
                        try:
                            data_registrazione = datetime.strptime(dr, "%d/%m/%Y")
                        except:
                            data_registrazione = datetime.strptime(dr, "%Y-%m-%d")
                    else:
                        data_registrazione = dr
                
                # Get amount - handle € format (e.g., "€ 150,00" or "150,00" or 150.00)
                importo_raw = row['Importo']
                if isinstance(importo_raw, str):
                    # Remove € symbol, spaces, and convert comma to dot
                    importo_clean = importo_raw.replace('€', '').replace(' ', '').replace('.', '').replace(',', '.')
                    importo = float(importo_clean)
                else:
                    importo = float(importo_raw)
                
                # ============ DUPLICATE CHECK ============
                # Check if a payment with same date and amount already exists for this athlete
                # We use a date range of the same day to handle timezone issues
                date_start = data_pagamento.replace(hour=0, minute=0, second=0, microsecond=0)
                date_end = data_pagamento.replace(hour=23, minute=59, second=59, microsecond=999999)
                
                existing_payment = await db.payments.find_one({
                    "athlete_id": athlete["id"],
                    "amount": importo,
                    "paid_date": {"$gte": date_start, "$lte": date_end}
                })
                
                if existing_payment:
                    athlete_name = athlete.get("full_name", match_label)
                    duplicates.append(f"Riga {idx+2}: {athlete_name} - €{importo:.2f} del {data_pagamento.strftime('%d/%m/%Y')} (già registrato)")
                    continue
                # ============ END DUPLICATE CHECK ============
                
                # Get payment method - support both letter and full name
                tipo_raw = row.get('TipoPagamento', '')
                if pd.isna(tipo_raw) or tipo_raw is None or str(tipo_raw).strip() == '':
                    tipo = 'Altro'
                else:
                    tipo_raw = str(tipo_raw).strip().upper()
                    tipo_map = {
                        'B': 'Bonifico', 'BONIFICO': 'Bonifico',
                        'P': 'POS', 'POS': 'POS',
                        'C': 'Contanti', 'CONTANTI': 'Contanti',
                        'A': 'Assegno', 'ASSEGNO': 'Assegno',
                        'O': 'Online', 'ONLINE': 'Online',
                    }
                    tipo = tipo_map.get(tipo_raw, 'Altro')
                
                # Causale (optional) - handle NaN, None, empty strings properly
                causale_raw = row.get('Causale', '')
                if pd.isna(causale_raw) or causale_raw is None or str(causale_raw).strip() in ['', 'nan', 'None']:
                    causale = f"Pagamento importato - {tipo}"
                else:
                    causale = str(causale_raw).strip()
                
                # Generate receipt number
                receipt_number = await get_next_receipt_number(society_id)
                
                # Create payment
                payment = Payment(
                    athlete_id=athlete["id"],
                    description=causale,
                    amount=importo,
                    paid=True,
                    paid_date=data_pagamento,
                    payment_method=tipo,
                    is_cash=(tipo == 'Contanti'),
                    receipt_number=receipt_number,
                    registration_date=data_registrazione or datetime.utcnow(),
                    created_by=current_user["id"],
                )
                
                await db.payments.insert_one(payment.dict())
                imported += 1
                
            except Exception as e:
                errors.append(f"Riga {idx+2}: {str(e)}")
        
        # Build response message
        message_parts = [f"Importati {imported} pagamenti"]
        if duplicates:
            message_parts.append(f"{len(duplicates)} duplicati ignorati")
        if unresolved:
            message_parts.append(f"{len(unresolved)} da risolvere")
        if errors:
            message_parts.append(f"{len(errors)} errori")
        
        return {
            "success": True,
            "imported": imported,
            "duplicates": duplicates,
            "duplicates_count": len(duplicates),
            "errors": errors,
            "unresolved": unresolved,
            "unresolved_count": len(unresolved),
            "message": " - ".join(message_parts)
        }
        
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Errore lettura file: {str(e)}")

@api_router.post("/payments/import-resolve")
async def import_resolve_payments(data: dict, current_user = Depends(get_current_user)):
    """Import previously unresolved payments with admin-selected athlete IDs"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")
    
    resolutions = data.get("resolutions", [])
    if not resolutions:
        raise HTTPException(status_code=400, detail="Nessuna risoluzione fornita")
    
    society_id = current_user.get("society_id")
    imported = 0
    errors = []
    
    for res in resolutions:
        try:
            athlete_id = res.get("athlete_id")
            row_data = res.get("row_data", {})
            
            if not athlete_id:
                continue
            
            athlete = await db.athletes.find_one({"id": athlete_id})
            if not athlete:
                errors.append(f"{row_data.get('Cognome', '')} {row_data.get('Nome', '')}: Atleta non trovato")
                continue
            
            # Parse payment data from row_data
            import_str = row_data.get("Importo", "0")
            importo = float(str(import_str).replace(",", ".").replace("€", "").replace(" ", "").strip())
            
            data_pagamento_str = row_data.get("DataPagamento", "")
            data_pagamento = None
            if data_pagamento_str:
                for fmt in ["%d/%m/%Y", "%d-%m-%Y", "%Y-%m-%d", "%d/%m/%y"]:
                    try:
                        data_pagamento = datetime.strptime(data_pagamento_str.strip(), fmt)
                        break
                    except:
                        continue
            
            data_reg_str = row_data.get("DataRegistrazione", "")
            data_registrazione = None
            if data_reg_str and str(data_reg_str).strip():
                for fmt in ["%d/%m/%Y", "%d-%m-%Y", "%Y-%m-%d", "%d/%m/%y"]:
                    try:
                        data_registrazione = datetime.strptime(str(data_reg_str).strip(), fmt)
                        break
                    except:
                        continue
            
            tipo_map = {"B": "Bonifico", "P": "POS", "C": "Contanti", "A": "Assegno"}
            tipo_raw = str(row_data.get("TipoPagamento", "")).strip().upper()
            payment_method = tipo_map.get(tipo_raw, tipo_raw)
            causale = str(row_data.get("Causale", "")).strip() if row_data.get("Causale") else ""
            
            # Check for duplicate
            existing = await db.payments.find_one({
                "athlete_id": athlete_id,
                "amount": importo,
                "paid_date": data_pagamento,
                "payment_method": payment_method,
            })
            if existing:
                errors.append(f"{athlete.get('last_name','')} {athlete.get('first_name','')}: Duplicato, pagamento già presente")
                continue
            
            receipt_number = await get_next_receipt_number(society_id)
            
            payment = Payment(
                id=str(uuid.uuid4()),
                athlete_id=athlete_id,
                society_id=society_id,
                amount=importo,
                paid=True,
                paid_date=data_pagamento or datetime.utcnow(),
                payment_method=payment_method,
                description=causale or "Pagamento importato",
                receipt_number=receipt_number,
                registration_date=data_registrazione or datetime.utcnow(),
                created_by=current_user["id"],
            )
            
            await db.payments.insert_one(payment.dict())
            imported += 1
            
        except Exception as e:
            errors.append(f"Errore: {str(e)}")
    
    return {
        "success": True,
        "imported": imported,
        "errors": errors,
        "message": f"Importati {imported} pagamenti risolti" + (f" - {len(errors)} errori" if errors else "")
    }

def get_current_training_slot(team: dict) -> Optional[dict]:
    """Find the current training slot based on day and time"""
    now = datetime.now()
    current_day = now.strftime("%A").lower()  # monday, tuesday, etc.
    current_time = now.strftime("%H:%M")
    
    # Map Italian day names
    day_mapping = {
        "monday": ["lunedì", "lunedi", "monday", "lun"],
        "tuesday": ["martedì", "martedi", "tuesday", "mar"],
        "wednesday": ["mercoledì", "mercoledi", "wednesday", "mer"],
        "thursday": ["giovedì", "giovedi", "thursday", "gio"],
        "friday": ["venerdì", "venerdi", "friday", "ven"],
        "saturday": ["sabato", "saturday", "sab"],
        "sunday": ["domenica", "sunday", "dom"]
    }
    
    training_sessions = team.get("training_sessions", [])
    
    for session in training_sessions:
        session_day = (session.get("day") or "").lower()
        # Check if day matches
        for eng_day, variants in day_mapping.items():
            if session_day in variants and current_day == eng_day:
                # Check if time is within range (with 30 min tolerance before)
                start_time = session.get("start_time", "00:00")
                end_time = session.get("end_time", "23:59")
                
                # Add 30 min tolerance before start
                try:
                    start_dt = datetime.strptime(start_time, "%H:%M")
                    tolerance_start = (start_dt - timedelta(minutes=30)).strftime("%H:%M")
                except:
                    tolerance_start = start_time
                
                if tolerance_start <= current_time <= end_time:
                    return {
                        "day": session.get("day"),
                        "start_time": start_time,
                        "end_time": end_time,
                        "venue": session.get("venue", team.get("venue"))
                    }
    
    return None

# ═══════════════════════════════════════════════════════════════════════════════
# ✅ SECTION: ATTENDANCE (presenze, check-in)
# Linee ~11958-12500 — endpoint per registrazione presenze atleti.
# Pianificato per estrazione → routers/attendance.py
# ═══════════════════════════════════════════════════════════════════════════════
@api_router.post("/attendance/check")
async def check_attendance(attendance_data: AttendanceCreate, request: Request, current_user = Depends(get_current_user)):
    """
    Registra presenza atleta con nuova logica:
    - Verifica atleta attivo
    - Verifica certificato medico
    - Check duplicato per atleta + squadra + slot + data
    - Supporta forzatura con nota
    """
    if current_user["role"] not in (UserRole.COACH, UserRole.ADMIN, UserRole.COORDINATORE):
        raise HTTPException(status_code=403, detail="Non autorizzato a registrare presenze")
    
    qr_code_value = attendance_data.qr_code.strip().upper()
    team_id = attendance_data.team_id
    # Use Italian timezone for date comparison
    italy_tz = timezone(timedelta(hours=2))  # CET+1 (CEST in summer)
    today = datetime.now(italy_tz).strftime("%Y-%m-%d")
    
    # 1. Find athlete by qr_identifier, athlete_code, or id
    athlete = await db.athletes.find_one({"qr_identifier": qr_code_value})
    if not athlete:
        athlete = await db.athletes.find_one({"athlete_code": qr_code_value})
    if not athlete:
        athlete = await db.athletes.find_one({"id": qr_code_value})
    if not athlete:
        # Case-insensitive fallback
        athlete = await db.athletes.find_one({"athlete_code": {"$regex": f"^{qr_code_value}$", "$options": "i"}})
    
    if not athlete:
        raise HTTPException(status_code=404, detail="QR code non valido o atleta non trovato")
    
    # Isolamento multi-tenant: solo atleti della propria società
    if athlete.get("society_id") and current_user.get("society_id") and athlete.get("society_id") != current_user.get("society_id"):
        raise HTTPException(status_code=403, detail="Atleta di un'altra società")
    
    athlete_id = athlete["id"]
    athlete_name = athlete.get("full_name", "Atleta")
    
    # 2. Check if athlete is active or in trial
    athlete_status = athlete.get("status", "pending")
    
    # Allow pending_trial athletes: first QR scan starts their trial
    if athlete_status == "pending_trial":
        # Start the trial period
        trial_days = 7  # default trial period
        trial_sessions = 3  # default max sessions
        
        # Get society settings for trial config — 🐛 08/07/2026 fix multi-tenancy
        society_settings = await db.settings.find_one({"type": "society", "society_id": athlete.get("society_id")}) if athlete.get("society_id") else await db.settings.find_one({"type": "society"})
        if society_settings:
            # 🐛 fix: la chiave corretta è trial_max_days (prima leggeva "trial_days" → sempre 14gg)
            trial_days = society_settings.get("trial_max_days", 7) or 7
            trial_sessions = society_settings.get("trial_max_sessions", 3) or 3
        
        trial_start = datetime.now()
        trial_end = trial_start + timedelta(days=trial_days)
        
        await db.athletes.update_one(
            {"id": athlete_id},
            {"$set": {
                "status": "trial",
                "trial_start_date": trial_start.isoformat(),
                "trial_end_date": trial_end.isoformat(),
                "trial_max_sessions": trial_sessions,
            }}
        )
        # Also update user status
        user_id = athlete.get("user_id")
        if user_id:
            await db.users.update_one({"id": user_id}, {"$set": {"status": "trial"}})
        
        athlete_status = "trial"
        logger.info(f"Trial started for athlete {athlete_name} ({athlete_id})")
    
    if athlete_status not in ["active", "trial", "approved"]:
        raise HTTPException(
            status_code=403, 
            detail=f"Atleta non attivo per la stagione corrente. Stato: {athlete_status}"
        )
    
    # Check if athlete is withdrawn
    if athlete.get("is_withdrawn"):
        raise HTTPException(status_code=403, detail="Atleta ritirato dalla squadra")
    
    # 3. Get team and training slot
    team = await db.teams.find_one({"id": team_id})
    if not team:
        raise HTTPException(status_code=404, detail="Squadra non trovata")
    
    # 3b. Verify athlete belongs to the selected team
    athlete_team_id = athlete.get("team_id")
    if athlete_team_id and athlete_team_id != team_id and not attendance_data.force:
        # Get athlete's actual team name
        actual_team = await db.teams.find_one({"id": athlete_team_id})
        actual_team_name = actual_team.get("name", "Altra squadra") if actual_team else "Altra squadra"
        return {
            "id": None,
            "athlete_id": athlete_id,
            "athlete_name": athlete_name,
            "team_id": team_id,
            "team_name": team.get("name"),
            "status": "wrong_team",
            "block_reason": f"{athlete_name} non è nella squadra {team.get('name')}. È tesserato/a nella squadra: {actual_team_name}",
            "actual_team": actual_team_name,
            "actual_team_id": athlete_team_id,
            "can_force": True
        }
    
    training_slot = get_current_training_slot(team)
    
    # 4. Check medical certificate status
    status_check = await check_athlete_status(athlete_id)
    
    # 5. Check for existing attendance (same athlete + team + date)
    existing_attendance = await db.attendances.find_one({
        "athlete_id": athlete_id,
        "team_id": team_id,
        "date": today
    })
    
    if existing_attendance and not attendance_data.force:
        # Return info about existing attendance - show Italian time
        existing_time = existing_attendance.get("check_in_time")
        if isinstance(existing_time, datetime):
            italy_time = existing_time + timedelta(hours=2) if existing_time.tzinfo is None else existing_time.astimezone(italy_tz)
            time_str = italy_time.strftime("%H:%M")
        else:
            time_str = str(existing_time)[:5] if existing_time else "N/D"
        
        return {
            "id": existing_attendance["id"],
            "athlete_id": athlete_id,
            "athlete_name": athlete_name,
            "team_id": team_id,
            "team_name": team.get("name"),
            "coach_id": existing_attendance.get("coach_id"),
            "check_in_time": existing_attendance.get("check_in_time").isoformat() if isinstance(existing_attendance.get("check_in_time"), datetime) else str(existing_attendance.get("check_in_time", "")),
            "date": today,
            "training_slot": existing_attendance.get("training_slot"),
            "status": "already_registered",
            "block_reason": f"Presenza già registrata oggi alle {time_str}",
            "forced": False,
            "force_note": None,
            "qr_code_used": qr_code_value,
            "can_force": True  # Frontend può mostrare opzione forzatura
        }
    
    # 6. Check if blocked due to certificate
    certificate_blocked = False
    certificate_block_reason = None
    if not status_check["allowed"]:
        reason = status_check.get("reason", "")
        if "CERTIFICATO" in reason.upper():
            certificate_blocked = True
            certificate_block_reason = reason
    
    # If blocked (not by certificate or no override possible), return blocked status
    if not status_check["allowed"] and not certificate_blocked:
        return {
            "id": None,
            "athlete_id": athlete_id,
            "athlete_name": athlete_name,
            "team_id": team_id,
            "team_name": team.get("name"),
            "status": "blocked",
            "block_reason": status_check.get("reason"),
            "certificate_blocked": False
        }
    
    # If blocked by certificate: notify Admin and require admin authorization
    # NOTE: Override è SEMPRE athlete-specific e richiede approvazione Admin via notifica
    # (no in-place override per evitare abusi su atleti diversi)
    if certificate_blocked and not attendance_data.force:
        # Check if there's ALREADY a notification for this athlete today
        # (pending OR authorized OR denied): in questi casi NON creiamo una nuova richiesta.
        # - pending  → l'admin deve ancora decidere sulla richiesta di stamattina
        # - authorized → l'atleta ha già consumato il suo override giornaliero
        # - denied   → l'admin ha già detto NO oggi, non riproporre
        try:
            existing_notif = await db.admin_notifications.find_one({
                "type": "expired_cert_scan",
                "athlete_id": athlete_id,
                "date": today,
            })
            already_used_override = bool(
                existing_notif and existing_notif.get("override_status") == "authorized"
            )
            already_denied_today = bool(
                existing_notif and existing_notif.get("override_status") == "denied"
            )
            if not existing_notif:
                coach_name = current_user.get("full_name") or current_user.get("email") or "Coach"
                await db.admin_notifications.insert_one({
                    "id": str(uuid.uuid4()),
                    "type": "expired_cert_scan",
                    "title": "Richiesta override certificato",
                    "message": f"{athlete_name} ({team.get('name', '')}) si è presentato/a all'allenamento con certificato medico scaduto/mancante. Coach {coach_name} richiede l'autorizzazione all'ingresso.",
                    "athlete_id": athlete_id,
                    "athlete_name": athlete_name,
                    "team_id": team_id,
                    "team_name": team.get("name", ""),
                    "date": today,
                    "priority": "high",
                    "read": False,
                    "override_status": "pending",  # pending | authorized | denied
                    "created_at": datetime.utcnow(),
                    "data": {
                        "action": "expired_cert_authorize",
                        "athlete_id": athlete_id,
                        "athlete_name": athlete_name,
                        "team_id": team_id,
                        "team_name": team.get("name", ""),
                        "coach_id": current_user["id"],
                        "coach_name": coach_name,
                        "block_reason": certificate_block_reason,
                    }
                })
        except Exception as e:
            logger.warning(f"Could not create admin notification for expired cert scan: {e}")
            already_used_override = False
            already_denied_today = False

        # Build an informative block reason for the Coach so they understand
        # why the override is NOT being requested again today.
        coach_block_reason = certificate_block_reason
        if already_used_override:
            coach_block_reason = (
                f"{certificate_block_reason}\n\n"
                f"⚠️ {athlete_name} ha già usato l'override giornaliero autorizzato dall'Admin. "
                f"Non può rientrare oggi senza un certificato medico valido."
            )
        elif already_denied_today:
            coach_block_reason = (
                f"{certificate_block_reason}\n\n"
                f"⛔ L'Admin ha già rifiutato l'override per {athlete_name} oggi."
            )

        return {
            "id": None,
            "athlete_id": athlete_id,
            "athlete_name": athlete_name,
            "team_id": team_id,
            "team_name": team.get("name"),
            "status": "blocked",
            "block_reason": coach_block_reason,
            "certificate_blocked": True,
            "can_override": False,  # Override gestito SOLO via notifica Admin (athlete-specific)
            "awaiting_admin_authorization": not (already_used_override or already_denied_today),
            "override_already_used_today": already_used_override,
            "override_denied_today": already_denied_today,
        }
    
    # 7. Create attendance record
    attendance_dict = {
        "id": str(ObjectId()),
        "athlete_id": athlete_id,
        "team_id": team_id,
        "coach_id": current_user["id"],
        "check_in_time": datetime.now(),
        "date": today,
        "training_slot": training_slot,
        "status": "allowed" if status_check["allowed"] else "blocked",
        "block_reason": status_check.get("reason"),
        "forced": attendance_data.force,
        "force_note": attendance_data.force_note if attendance_data.force else None,
        "qr_code_used": qr_code_value
    }
    
    # 7. If forcing, don't overwrite - create new record with forced flag
    if attendance_data.force and existing_attendance:
        attendance_dict["forced"] = True
        attendance_dict["force_note"] = attendance_data.force_note or "Forzatura coach"
    
    # 8. Handle certificate override consumption
    override_consumed = False
    override_reason_used = None
    if status_check["allowed"] and status_check.get("override_active"):
        override_consumed = True
        override_reason_used = athlete.get("certificate_override_reason", "")
        await db.athletes.update_one(
            {"id": athlete_id},
            {"$set": {
                "certificate_override_active": False,
                "certificate_override_consumed_at": datetime.utcnow().isoformat()
            }}
        )
        await db.audit_logs.insert_one({
            "id": str(uuid.uuid4()),
            "type": "certificate_override_consumed",
            "athlete_id": athlete_id,
            "athlete_name": athlete_name,
            "consumed_at": datetime.utcnow().isoformat(),
            "coach_id": current_user["id"],
            "coach_name": current_user.get("full_name", current_user.get("email"))
        })
    
    # 9. Save attendance
    await db.attendances.insert_one(attendance_dict)
    
    # 9a. Audit log for attendance
    await log_audit(
        action="attendance_recorded",
        user_id=current_user["id"],
        user_email=current_user.get("email", ""),
        society_id=current_user.get("society_id", ""),
        target_user_id=athlete_id,
        target_user_name=athlete_name,
        ip_address=get_real_ip(request),
        details={
            "team_name": team.get("name", ""),
            "training_slot": training_slot or "",
            "date": today,
            "forced": bool(attendance_data.force),
        }
    )
    
    # 9b. Trial period: if first attendance, set trial start date
    if athlete.get("is_trial") and not athlete.get("trial_start_date"):
        # Get trial settings from society — 🐛 08/07/2026 fix multi-tenancy
        _sid = athlete.get("society_id")
        society_settings = await db.settings.find_one({"type": "society", "society_id": _sid}) if _sid else await db.settings.find_one({"type": "society"})
        max_days = society_settings.get("trial_max_days", 7) if society_settings else 7
        trial_start = datetime.now()
        trial_end = trial_start + timedelta(days=max_days)
        await db.athletes.update_one(
            {"id": athlete_id},
            {"$set": {
                "trial_start_date": trial_start.isoformat(),
                "trial_end_date": trial_end.isoformat(),
                "trial_sessions_count": 1,
            }}
        )
        # Audit log for trial start
        await log_audit(
            action="trial_started",
            user_id=current_user["id"],
            user_email=current_user.get("email", ""),
            society_id=current_user.get("society_id", ""),
            target_user_id=athlete_id,
            target_user_name=athlete_name,
            ip_address=get_real_ip(request),
            details={
                "trial_start_date": trial_start.isoformat(),
                "trial_end_date": trial_end.isoformat(),
                "max_days": max_days,
                "team_name": team.get("name", ""),
            }
        )
    elif athlete.get("is_trial") and athlete.get("trial_start_date"):
        # Increment trial sessions count
        await db.athletes.update_one(
            {"id": athlete_id},
            {"$inc": {"trial_sessions_count": 1}}
        )
    
    # 10. Return response with athlete name for display (ensure all values are JSON serializable)
    response = {
        "id": str(attendance_dict["id"]),
        "athlete_id": str(attendance_dict["athlete_id"]),
        "athlete_name": str(athlete_name),
        "team_id": str(attendance_dict["team_id"]),
        "team_name": str(team.get("name", "")),
        "coach_id": str(attendance_dict["coach_id"]),
        "check_in_time": attendance_dict["check_in_time"].isoformat() if isinstance(attendance_dict["check_in_time"], datetime) else str(attendance_dict["check_in_time"]),
        "date": str(attendance_dict["date"]),
        "training_slot": attendance_dict.get("training_slot"),
        "status": str(attendance_dict["status"]),
        "block_reason": attendance_dict.get("block_reason"),
        "forced": bool(attendance_dict.get("forced", False)),
        "force_note": attendance_dict.get("force_note"),
        "qr_code_used": str(attendance_dict.get("qr_code_used", "")),
        "certificate_override_consumed": override_consumed,
        "certificate_override_reason": override_reason_used,
    }
    
    # Add trial info if athlete is in trial
    if athlete.get("is_trial"):
        # 🐛 08/07/2026 fix multi-tenancy
        _sid2 = athlete.get("society_id")
        society_settings = await db.settings.find_one({"type": "society", "society_id": _sid2}) if _sid2 else await db.settings.find_one({"type": "society"})
        max_sessions = society_settings.get("trial_max_sessions", 3) if society_settings else 3
        max_days = society_settings.get("trial_max_days", 7) if society_settings else 7
        sessions_count = athlete.get("trial_sessions_count", 0)
        # After the increment above, get the updated count
        updated_athlete = await db.athletes.find_one({"id": athlete_id})
        sessions_count = updated_athlete.get("trial_sessions_count", 0) if updated_athlete else sessions_count
        days_remaining = None
        trial_end = updated_athlete.get("trial_end_date") if updated_athlete else None
        if trial_end:
            try:
                end_dt = datetime.fromisoformat(str(trial_end)) if isinstance(trial_end, str) else trial_end
                days_remaining = max(0, (end_dt - datetime.now()).days)
            except:
                pass
        response["is_trial"] = True
        response["trial_sessions_count"] = sessions_count
        response["trial_max_sessions"] = max_sessions
        response["trial_days_remaining"] = days_remaining
    
    return response

class ManualAttendanceCreate(BaseModel):
    date: str  # YYYY-MM-DD
    time: Optional[str] = None  # HH:MM (opzionale)
    note: Optional[str] = None


@api_router.post("/coach/athletes/{athlete_id}/manual-attendance")
async def add_manual_attendance(athlete_id: str, data: ManualAttendanceCreate, request: Request, current_user = Depends(get_current_user)):
    """🆕 05/09/2026 — Presenza STRAORDINARIA inserita manualmente dal coach dal
    profilo atleta (es. QR non scansionato per errore). Registra la presenza con
    flag manuale + audit log visibile agli admin. Solo coach assegnato alla
    squadra dell'atleta (o admin). Isolato per società."""
    if current_user["role"] not in (UserRole.COACH, UserRole.ADMIN, UserRole.COORDINATORE):
        raise HTTPException(status_code=403, detail="Operazione riservata a coach/admin")

    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")

    # Isolamento multi-tenant
    if athlete.get("society_id") and athlete.get("society_id") != current_user.get("society_id"):
        raise HTTPException(status_code=403, detail="Atleta di un'altra società")

    team_id = athlete.get("team_id")
    if not team_id:
        raise HTTPException(status_code=400, detail="L'atleta non è assegnato a nessuna squadra")

    # Il coach deve essere assegnato alla squadra dell'atleta (admin/coordinatore bypass)
    if current_user["role"] == UserRole.COACH:
        assigned = current_user.get("assigned_teams", []) or []
        if team_id not in assigned:
            raise HTTPException(status_code=403, detail="Non sei allenatore di questa squadra")

    # 🐛 Prova terminata (giorni o sedute massime): non si possono aggiungere altre presenze
    _trial_block = await get_trial_block_reason(athlete)
    if _trial_block:
        raise HTTPException(status_code=400, detail=f"{_trial_block}. L'atleta deve iscriversi (o lasciare) prima di registrare nuove presenze.")

    # Parse data (obbligatoria) e ora (opzionale)
    try:
        base_dt = datetime.strptime((data.date or "").strip(), "%Y-%m-%d")
    except Exception:
        raise HTTPException(status_code=400, detail="Data non valida (usa GG/MM/AAAA)")
    hh, mm = 0, 0
    if data.time and data.time.strip():
        try:
            parts = data.time.strip().split(":")
            hh = int(parts[0]); mm = int(parts[1]) if len(parts) > 1 else 0
        except Exception:
            hh, mm = 0, 0
    check_in = base_dt.replace(hour=hh, minute=mm)
    # 🆕 28/09/2026 — orario inserito dal coach in ora di Roma → salviamo in UTC (naive)
    try:
        check_in = check_in.replace(tzinfo=_IT_TZ).astimezone(timezone.utc).replace(tzinfo=None)
    except Exception:
        pass

    team = await db.teams.find_one({"id": team_id}, {"_id": 0, "name": 1})
    athlete_name = athlete.get("full_name") or f"{athlete.get('first_name','')} {athlete.get('last_name','')}".strip()
    actor_name = current_user.get("full_name") or current_user.get("email")

    attendance_dict = {
        "id": str(ObjectId()),
        "athlete_id": athlete_id,
        "team_id": team_id,
        "coach_id": current_user["id"],
        "check_in_time": check_in,
        "date": data.date,
        "training_slot": {"time": data.time} if (data.time and data.time.strip()) else None,
        "status": "allowed",
        "block_reason": None,
        "forced": True,
        "force_note": (data.note or "").strip() or "Presenza inserita manualmente dal coach",
        "qr_code_used": None,
        # marcatori presenza manuale (per audit/visibilità admin)
        "manual_entry": True,
        "manual_by_id": current_user["id"],
        "manual_by_name": actor_name,
        "manual_created_at": datetime.now(timezone.utc).isoformat(),
    }
    await db.attendances.insert_one(attendance_dict)

    # Conteggio prova (come QR): converte pending_trial→trial e conta le sessioni
    await _recompute_trial_from_attendance(athlete, team_id)

    await log_audit(
        action="manual_attendance_added",
        user_id=current_user["id"],
        user_email=current_user.get("email", ""),
        society_id=current_user.get("society_id", ""),
        target_user_id=athlete_id,
        target_user_name=athlete_name,
        ip_address=get_real_ip(request),
        details={
            "team_name": team.get("name", "") if team else "",
            "date": data.date,
            "time": data.time or "",
            "note": (data.note or "").strip(),
            "inserted_by": actor_name,
            "extraordinary": True,
        },
    )
    return {
        "message": "Presenza registrata manualmente",
        "attendance_id": attendance_dict["id"],
        "athlete_name": athlete_name,
        "date": data.date,
        "time": data.time or "",
    }


# 🆕 27/09/2026 — Annulla la presenza di OGGI di un atleta (gemello della registrazione
# straordinaria): usato dal profilo atleta del coach per correggere una scansione QR errata.
@api_router.delete("/coach/athletes/{athlete_id}/attendance/today")
async def delete_today_attendance_for_athlete(athlete_id: str, request: Request, current_user = Depends(get_current_user)):
    if current_user["role"] not in (UserRole.COACH, UserRole.ADMIN, UserRole.COORDINATORE):
        raise HTTPException(status_code=403, detail="Operazione riservata a coach/admin")
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    if athlete.get("society_id") and athlete.get("society_id") != current_user.get("society_id"):
        raise HTTPException(status_code=403, detail="Atleta di un'altra società")
    team_id = athlete.get("team_id")
    # Il coach deve essere assegnato alla squadra (admin/coordinatore bypass)
    if current_user["role"] == UserRole.COACH:
        assigned = current_user.get("assigned_teams", []) or []
        if team_id and team_id not in assigned:
            raise HTTPException(status_code=403, detail="Non sei allenatore di questa squadra")
    italy_tz = timezone(timedelta(hours=2))
    today = datetime.now(italy_tz).strftime("%Y-%m-%d")
    today_start = datetime.utcnow().replace(hour=0, minute=0, second=0, microsecond=0) - timedelta(hours=2)
    # Presenze di oggi dell'atleta (per data stringa o check_in_time)
    atts = await db.attendances.find({
        "athlete_id": athlete_id,
        "$or": [{"date": today}, {"check_in_time": {"$gte": today_start}}],
    }).to_list(50)
    if not atts:
        raise HTTPException(status_code=404, detail="Nessuna presenza registrata oggi per questo atleta")
    athlete_name = athlete.get("full_name") or f"{athlete.get('first_name','')} {athlete.get('last_name','')}".strip()
    deleted = 0
    for att in atts:
        snap = dict(att); snap.pop("_id", None)
        await db.deleted_attendances.insert_one({
            "attendance": snap,
            "deleted_by_id": current_user["id"],
            "deleted_by_name": current_user.get("full_name") or current_user.get("email", ""),
            "deleted_by_role": current_user["role"],
            "deleted_at": datetime.utcnow(),
            "society_id": current_user.get("society_id"),
        })
        await db.attendances.delete_one({"id": att.get("id")})
        deleted += 1
    # Ricalcola stato prova
    if team_id:
        try:
            await _recompute_trial_from_attendance(athlete, team_id)
        except Exception as _e:
            logging.warning(f"[DELETE-TODAY-ATT] recompute failed: {_e}")
    try:
        await log_audit(
            action="attendance_deleted",
            user_id=current_user["id"],
            user_email=current_user.get("email", ""),
            society_id=current_user.get("society_id", ""),
            target_user_id=athlete_id,
            target_user_name=athlete_name,
            ip_address=get_real_ip(request),
            details={"date": today, "count": deleted, "source": "coach_athlete_profile"},
        )
    except Exception:
        pass
    return {"message": f"Presenza di oggi annullata per {athlete_name}", "deleted": deleted}


class BulkAttendanceCreate(BaseModel):
    athlete_ids: List[str]
    date: str  # YYYY-MM-DD
    time: Optional[str] = None  # HH:MM (opzionale)
    note: Optional[str] = None


async def _recompute_trial_from_attendance(athlete: dict, team_id: str):
    """🆕 Ricalcola lo stato prova dai record di presenza REALI (idempotente e
    auto-correttivo). Usato dalle presenze manuali (singola e multipla) così la
    prova parte/avanza come con lo scan QR e si riparano i dati già inseriti:
    - converte pending_trial → trial
    - imposta trial_start_date (prima presenza) se mancante
    - trial_sessions_count = numero di date distinte con presenza."""
    aid = athlete["id"]
    status = athlete.get("status")
    is_trial = bool(athlete.get("is_trial")) or status in ("trial", "pending_trial")
    if not is_trial:
        return
    _sid = athlete.get("society_id")
    ss = await db.settings.find_one({"type": "society", "society_id": _sid}) if _sid else await db.settings.find_one({"type": "society"})
    max_days = (ss.get("trial_max_days", 7) if ss else 7) or 7
    max_sessions = (ss.get("trial_max_sessions", 3) if ss else 3) or 3

    atts = await db.attendances.find({"athlete_id": aid, "team_id": team_id}).to_list(2000)
    dates = set()
    earliest = None
    date_to_dt: dict = {}  # data (iso) -> primo check-in di quel giorno
    for at in atts:
        ci = at.get("check_in_time")
        d = at.get("date")
        if not d and isinstance(ci, datetime):
            d = ci.date().isoformat()
        if d:
            dates.add(d)
            if isinstance(ci, datetime):
                prev = date_to_dt.get(d)
                if prev is None or ci < prev:
                    date_to_dt[d] = ci
        if isinstance(ci, datetime):
            if earliest is None or ci < earliest:
                earliest = ci

    set_fields = {
        "is_trial": True,
        "trial_sessions_count": len(dates),
        "trial_max_sessions": max_sessions,
    }
    if status == "pending_trial":
        set_fields["status"] = "trial"
    if not athlete.get("trial_start_date") and earliest is not None:
        set_fields["trial_start_date"] = earliest.isoformat()
        set_fields["trial_end_date"] = (earliest + timedelta(days=max_days)).isoformat()

    # 🆕 12/09/2026 (richiesta utente): la prova si CONCLUDE al raggiungimento del
    # numero massimo di sedute (OR con i giorni). Anticipiamo trial_end_date al
    # momento della seduta che completa il massimo, così la prova risulta terminata
    # subito (giorni rimanenti = 0) anche se la settimana non è finita.
    if len(dates) >= max_sessions:
        sorted_dates = sorted(dates)
        completing_date = sorted_dates[max_sessions - 1]
        completing_dt = date_to_dt.get(completing_date)
        if completing_dt is None:
            try:
                completing_dt = datetime.fromisoformat(completing_date)
            except Exception:
                completing_dt = datetime.now()
        set_fields["trial_end_date"] = completing_dt.isoformat()

    await db.athletes.update_one({"id": aid}, {"$set": set_fields})
    if status == "pending_trial":
        uid = athlete.get("user_id")
        if uid:
            await db.users.update_one({"id": uid}, {"$set": {"status": "trial"}})


@api_router.post("/admin/teams/{team_id}/recompute-trials")
async def recompute_team_trials(team_id: str, current_user = Depends(get_current_user)):
    """🆕 06/09/2026 — Ripara/ricalcola in blocco la prova di TUTTI gli atleti in
    prova della squadra, dalle presenze reali. Utile per sistemare gli atleti
    inseriti col vecchio bulk. Solo admin/coordinatore (o coach assegnato)."""
    if current_user["role"] not in (UserRole.ADMIN, UserRole.COORDINATORE, UserRole.COACH):
        raise HTTPException(status_code=403, detail="Operazione riservata ad admin/coach")
    society_id = current_user.get("society_id")
    team = await db.teams.find_one({"id": team_id, "society_id": society_id}, {"_id": 0, "id": 1, "certificate_type_required": 1})
    if not team:
        raise HTTPException(status_code=404, detail="Squadra non trovata")
    if current_user["role"] == UserRole.COACH and team_id not in (current_user.get("assigned_teams", []) or []):
        raise HTTPException(status_code=403, detail="Non sei allenatore di questa squadra")

    # 🐛 Allineato all'elenco presenze: include anche gli atleti aggregati da altre
    # squadre (team_ids), non solo la squadra principale (team_id). Prima la
    # riparazione saltava questi atleti e "non succedeva nulla".
    aths = await db.athletes.find({
        "society_id": society_id,
        "is_withdrawn": {"$ne": True},
        "$and": [
            {"$or": [{"team_id": team_id}, {"team_ids": team_id}]},
            {"$or": [{"is_trial": True}, {"status": {"$in": ["trial", "pending_trial"]}}]},
        ],
    }).to_list(2000)
    fixed = 0
    activated = 0
    not_activated = []  # 🆕 motivo per atleta non attivato (diagnostica)
    for a in aths:
        await _recompute_trial_from_attendance(a, team_id)
        fixed += 1
        # 🆕 chi ha già privacy + certificato convalidato esce dalla prova → ATTIVO
        # (minorenne o maggiorenne)
        if await maybe_activate_athlete(a["id"], current_user):
            activated += 1
        else:
            fresh = await db.athletes.find_one({"id": a["id"]}) or a
            _name = fresh.get("full_name") or f"{fresh.get('first_name','')} {fresh.get('last_name','')}".strip() or "Atleta"
            # 🆕 Già in forza ma con l'etichetta prova rimasta appiccicata → la ripuliamo
            # (è il caso "pronto ma non succede nulla": l'atleta era già attivo e restava
            # rosso come PROVA SCADUTA). Dopo la pulizia torna normale, lo contiamo come
            # sistemato.
            if fresh.get("status") in ("active", "blocked", "rejected"):
                if fresh.get("is_trial"):
                    await db.athletes.update_one({"id": a["id"]}, {"$set": {"is_trial": False, "trial_status": "completed"}})
                    activated += 1
                continue
            reasons = _trial_missing_reasons(fresh, team)
            _cnt = fresh.get("trial_sessions_count", 0) or 0
            _max = fresh.get("trial_max_sessions", 3) or 3
            if reasons:
                not_activated.append(f"{_name}: {', '.join(reasons)}")
            elif _cnt < _max:
                not_activated.append(f"{_name}: prova non completata ({_cnt}/{_max} presenze)")
            else:
                not_activated.append(f"{_name}: stato={fresh.get('status')}, minore={_compute_is_minor(fresh)}, privacy={'ok' if fresh.get('privacy_accepted') else 'NO'} — non attivato")
    msg = f"Ricalcolo completato su {fixed} atleti in prova. Attivati: {activated}."
    if not_activated:
        msg += "\n\nNon attivati (motivo):\n• " + "\n• ".join(not_activated)
    return {"message": msg, "count": fixed, "activated": activated, "not_activated": not_activated}


@api_router.post("/admin/athletes/repair-minor-flags")
async def repair_minor_flags(current_user = Depends(get_current_user)):
    """🆕 Riparazione una-tantum: ricalcola il flag `is_minor` di TUTTI gli atleti
    della società dalla data di nascita (età < 18 → minorenne). Corregge i record
    importati con il flag errato, che impediva l'attivazione automatica e altre
    logiche minore/maggiorenne. Idempotente. Salta chi non ha una data valida."""
    if current_user["role"] not in (UserRole.ADMIN, UserRole.COORDINATORE):
        raise HTTPException(status_code=403, detail="Operazione riservata ad admin")
    society_id = current_user.get("society_id")
    query = {"society_id": society_id} if society_id else {}
    aths = await db.athletes.find(query, {"_id": 0, "id": 1, "is_minor": 1, "date_of_birth": 1}).to_list(10000)
    today = datetime.utcnow()
    fixed = 0
    no_dob = 0
    for a in aths:
        dob = a.get("date_of_birth")
        if not dob:
            no_dob += 1
            continue
        try:
            if isinstance(dob, str):
                dob_dt = datetime.fromisoformat(dob.replace("Z", "").split("T")[0])
            else:
                dob_dt = dob
            age = today.year - dob_dt.year - ((today.month, today.day) < (dob_dt.month, dob_dt.day))
        except Exception:
            no_dob += 1
            continue
        correct_minor = age < 18
        if a.get("is_minor") is not correct_minor:
            await db.athletes.update_one({"id": a["id"]}, {"$set": {"is_minor": correct_minor}})
            fixed += 1
    msg = f"Etichetta minorenne/maggiorenne ricalcolata. Corretti {fixed} atleti."
    if no_dob:
        msg += f" ({no_dob} saltati: data di nascita mancante o non valida.)"
    return {"message": msg, "fixed": fixed, "skipped_no_dob": no_dob, "total": len(aths)}



@api_router.post("/athletes/{athlete_id}/force-end-trial")
async def force_end_trial(athlete_id: str, request: Request, current_user = Depends(get_current_user)):
    """🆕 06/09/2026 — Termina SUBITO il periodo di prova di un atleta (admin):
    la prova risulta conclusa (raggiunte le sessioni massime) e l'atleta passa alla
    fase decisionale (resta e firma / lascia). Tracciato negli audit log."""
    if current_user["role"] not in (UserRole.ADMIN, UserRole.COORDINATORE):
        raise HTTPException(status_code=403, detail="Operazione riservata ad admin")
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    if athlete.get("society_id") and athlete.get("society_id") != current_user.get("society_id"):
        raise HTTPException(status_code=403, detail="Atleta di un'altra società")
    if athlete.get("status") not in ("trial", "pending_trial"):
        raise HTTPException(status_code=400, detail="L'atleta non è in periodo di prova")

    _sid = athlete.get("society_id")
    ss = await db.settings.find_one({"type": "society", "society_id": _sid}) if _sid else await db.settings.find_one({"type": "society"})
    max_sessions = (ss.get("trial_max_sessions", 3) if ss else 3) or 3
    now_it = datetime.now(timezone.utc)
    start = athlete.get("trial_start_date") or now_it.isoformat()
    await db.athletes.update_one({"id": athlete_id}, {"$set": {
        "status": "trial",
        "is_trial": True,
        "trial_start_date": start,
        "trial_end_date": now_it.isoformat(),
        "trial_sessions_count": max_sessions,
        "trial_max_sessions": max_sessions,
        "admin_ended_trial": True,
    }})
    uid = athlete.get("user_id")
    if uid:
        await db.users.update_one({"id": uid}, {"$set": {"status": "trial"}})

    athlete_name = athlete.get("full_name") or f"{athlete.get('first_name','')} {athlete.get('last_name','')}".strip()
    await log_audit(
        action="trial_force_ended",
        user_id=current_user["id"],
        user_email=current_user.get("email", ""),
        society_id=_sid or "",
        target_user_id=athlete_id,
        target_user_name=athlete_name,
        ip_address=get_real_ip(request),
        details={"executor_name": current_user.get("full_name", "")},
    )
    return {"message": f"Periodo di prova concluso per {athlete_name}"}


