@api_router.post("/admin/trials/close-all")
async def close_all_trials(request: Request, current_user = Depends(get_current_user)):
    """🆕 02/10/2026 — "Fine periodo prove": termina IN BLOCCO tutte le prove ancora
    attive della società. Ogni atleta in prova entra nella fase decisionale
    (resta e firma privacy + quota + certificato / oppure lascia), esattamente come
    il pulsante "Termina prova" sul singolo atleta. Esclude ritirati e già attivi.
    Tracciato negli audit log."""
    if current_user["role"] not in (UserRole.ADMIN, UserRole.COORDINATORE):
        raise HTTPException(status_code=403, detail="Operazione riservata ad admin")
    sid = current_user.get("society_id")
    query = {
        "status": {"$in": ["trial", "pending_trial"]},
        "is_withdrawn": {"$ne": True},
        "admin_ended_trial": {"$ne": True},
        "end_trial_requested": {"$ne": True},
    }
    if sid:
        query["society_id"] = sid
    athletes = await db.athletes.find(query).to_list(5000)

    # Numero massimo di sessioni di prova (impostazioni società)
    ss = await db.settings.find_one({"type": "society", "society_id": sid}) if sid else await db.settings.find_one({"type": "society"})
    max_sessions = (ss.get("trial_max_sessions", 3) if ss else 3) or 3
    now_it = datetime.now(timezone.utc)

    closed_names = []
    for athlete in athletes:
        start = athlete.get("trial_start_date") or now_it.isoformat()
        await db.athletes.update_one({"id": athlete["id"]}, {"$set": {
            "status": "trial",
            "is_trial": True,
            "trial_start_date": start,
            "trial_end_date": now_it.isoformat(),
            "trial_sessions_count": max_sessions,
            "trial_max_sessions": max_sessions,
            "admin_ended_trial": True,
        }})
        uid = athlete.get("user_id")
        if uid:
            await db.users.update_one({"id": uid}, {"$set": {"status": "trial"}})
        closed_names.append(athlete.get("full_name") or f"{athlete.get('first_name','')} {athlete.get('last_name','')}".strip())

    await log_audit(
        action="trial_close_all",
        user_id=current_user["id"],
        user_email=current_user.get("email", ""),
        society_id=sid or "",
        target_user_id="",
        target_user_name=f"{len(closed_names)} atleti",
        ip_address=get_real_ip(request),
        details={"executor_name": current_user.get("full_name", ""), "closed_count": len(closed_names)},
    )
    return {
        "message": f"Periodo di prova concluso per {len(closed_names)} atleti" if closed_names else "Nessuna prova attiva da chiudere",
        "closed": len(closed_names),
        "names": closed_names,
    }




@api_router.post("/athletes/{athlete_id}/skip-trial-activate")
async def skip_trial_and_activate(athlete_id: str, request: Request, current_user = Depends(get_current_user)):
    """🆕 12/09/2026 — Admin: ANNULLA il periodo di prova e ATTIVA SUBITO l'atleta
    (per i "vecchi tesserati" già confermati). NESSUNA fase decisionale resta/lascia.
    La privacy NON viene firmata automaticamente: resta da firmare dall'atleta (18+)
    o dal genitore (18-) tramite il banner privacy esistente. Se il certificato medico
    è già convalidato → ATTIVO; altrimenti → in attesa certificato. Tracciato in audit."""
    if current_user["role"] not in (UserRole.ADMIN, UserRole.COORDINATORE):
        raise HTTPException(status_code=403, detail="Operazione riservata ad admin")
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    if athlete.get("society_id") and athlete.get("society_id") != current_user.get("society_id"):
        raise HTTPException(status_code=403, detail="Atleta di un'altra società")
    if athlete.get("is_withdrawn"):
        raise HTTPException(status_code=400, detail="Atleta ritirato")
    if athlete.get("status") == "active":
        raise HTTPException(status_code=400, detail="L'atleta è già attivo")

    _team = await db.teams.find_one({"id": athlete.get("team_id")}) if athlete.get("team_id") else None
    _cert_type = cert_type_for_team(_team)
    cert_ok = has_valid_verified_cert(athlete) if cert_required_for_active(_cert_type) else True
    now = datetime.utcnow()
    upd = {
        "is_trial": False,
        "trial_start_date": None,
        "trial_end_date": None,
        "end_trial_requested": False,
        "trial_skipped_by_admin": True,
    }
    if cert_ok:
        upd["status"] = "active"
        upd["activated_at"] = now.isoformat()
        upd["activated_by"] = current_user.get("id")
        upd["activated_by_name"] = current_user.get("full_name", current_user.get("email", ""))
        new_status = "active"
    else:
        upd["status"] = "pending_certificate"
        new_status = "pending_certificate"
    await db.athletes.update_one({"id": athlete_id}, {"$set": upd})
    uid = athlete.get("user_id") or athlete.get("linked_user_id")
    if uid and cert_ok:
        await db.users.update_one({"id": uid}, {"$set": {"status": UserStatus.APPROVED}})

    athlete_name = athlete.get("full_name") or f"{athlete.get('first_name','')} {athlete.get('last_name','')}".strip()
    _sid2 = athlete.get("society_id")
    await log_audit(
        action="trial_skipped_activate",
        user_id=current_user["id"],
        user_email=current_user.get("email", ""),
        society_id=_sid2 or "",
        target_user_id=athlete_id,
        target_user_name=athlete_name,
        ip_address=get_real_ip(request),
        details={"executor_name": current_user.get("full_name", ""), "result_status": new_status, "cert_ok": cert_ok},
    )
    privacy_signed = bool(athlete.get("privacy_accepted"))
    if new_status == "active":
        msg = f"{athlete_name} è ora ATTIVO (prova annullata)."
    else:
        msg = f"Prova annullata per {athlete_name}. Resta in attesa della convalida del certificato medico."
    if not privacy_signed:
        msg += " La privacy deve ancora essere firmata."
    return {"status": new_status, "privacy_required": not privacy_signed, "message": msg}


@api_router.post("/admin/teams/{team_id}/bulk-attendance")
async def add_bulk_attendance(team_id: str, data: BulkAttendanceCreate, request: Request, current_user = Depends(get_current_user)):
    """🆕 06/09/2026 — Registrazione presenze MULTIPLE per una squadra da parte
    dell'admin (o coach assegnato). Seleziona atleti + data/ora e registra la
    presenza per tutti. Le presenze contano per il periodo di prova (come lo
    scan QR): incrementano trial_sessions_count così la prova può concludersi.
    Ogni inserimento è tracciato negli audit log (visibile agli admin)."""
    if current_user["role"] not in (UserRole.ADMIN, UserRole.COORDINATORE, UserRole.COACH):
        raise HTTPException(status_code=403, detail="Operazione riservata ad admin/coach")

    society_id = current_user.get("society_id")
    team = await db.teams.find_one({"id": team_id, "society_id": society_id}, {"_id": 0, "id": 1, "name": 1})
    if not team:
        raise HTTPException(status_code=404, detail="Squadra non trovata")

    # Coach: solo squadre assegnate + permesso esplicito concesso dall'admin
    if current_user["role"] == UserRole.COACH:
        if team_id not in (current_user.get("assigned_teams", []) or []):
            raise HTTPException(status_code=403, detail="Non sei allenatore di questa squadra")
        if not current_user.get("can_manual_attendance"):
            raise HTTPException(status_code=403, detail="Registrazione manuale non abilitata per il tuo profilo. Chiedi all'amministratore di attivarla.")

    if not data.athlete_ids:
        raise HTTPException(status_code=400, detail="Nessun atleta selezionato")

    # Parse data/ora
    try:
        base_dt = datetime.strptime((data.date or "").strip(), "%Y-%m-%d")
    except Exception:
        raise HTTPException(status_code=400, detail="Data non valida")
    hh, mm = 0, 0
    if data.time and data.time.strip():
        try:
            parts = data.time.strip().split(":")
            hh = int(parts[0]); mm = int(parts[1]) if len(parts) > 1 else 0
        except Exception:
            hh, mm = 0, 0
    check_in = base_dt.replace(hour=hh, minute=mm)
    # 🆕 28/09/2026 — orario inserito dal coach in ora di Roma → salviamo in UTC (naive)
    try:
        check_in = check_in.replace(tzinfo=_IT_TZ).astimezone(timezone.utc).replace(tzinfo=None)
    except Exception:
        pass
    actor_name = current_user.get("full_name") or current_user.get("email")

    # Config prova (multi-tenant)
    society_settings = await db.settings.find_one({"type": "society", "society_id": society_id}) if society_id else await db.settings.find_one({"type": "society"})
    max_days = society_settings.get("trial_max_days", 7) if society_settings else 7

    registered = []
    skipped = []

    for aid in data.athlete_ids:
        athlete = await db.athletes.find_one({"id": aid})
        if not athlete:
            skipped.append({"athlete_id": aid, "reason": "non trovato"})
            continue
        if athlete.get("society_id") and athlete.get("society_id") != society_id:
            skipped.append({"athlete_id": aid, "reason": "altra società"})
            continue
        if athlete.get("team_id") and athlete.get("team_id") != team_id:
            skipped.append({"athlete_id": aid, "reason": "non in questa squadra"})
            continue

        athlete_name = athlete.get("full_name") or f"{athlete.get('first_name','')} {athlete.get('last_name','')}".strip()

        # 🐛 Prova terminata (giorni o sedute massime): salta l'atleta invece di
        # accumulare presenze oltre il limite (es. 7/6).
        _trial_block = await get_trial_block_reason(athlete)
        if _trial_block:
            skipped.append({"athlete_id": aid, "athlete_name": athlete_name, "reason": "prova terminata (iscrizione richiesta)"})
            continue

        # Evita duplicati stessa data/squadra/atleta
        dup = await db.attendances.find_one({"athlete_id": aid, "team_id": team_id, "date": data.date})
        if dup:
            # Anche se la presenza per questa data esiste già, ricalcola la prova dai
            # record reali: ripara gli atleti che risultavano ancora "prima prova".
            await _recompute_trial_from_attendance(athlete, team_id)
            skipped.append({"athlete_id": aid, "athlete_name": athlete_name, "reason": "già registrata per questa data"})
            continue

        attendance_dict = {
            "id": str(ObjectId()),
            "athlete_id": aid,
            "team_id": team_id,
            "coach_id": current_user["id"],
            "check_in_time": check_in,
            "date": data.date,
            "training_slot": {"time": data.time} if (data.time and data.time.strip()) else None,
            "status": "allowed",
            "block_reason": None,
            "forced": True,
            "force_note": (data.note or "").strip() or "Presenza inserita manualmente (registrazione multipla admin)",
            "qr_code_used": None,
            "manual_entry": True,
            "manual_by_id": current_user["id"],
            "manual_by_name": actor_name,
            "manual_created_at": datetime.now(timezone.utc).isoformat(),
        }
        await db.attendances.insert_one(attendance_dict)

        # Conteggio prova (come QR): converte pending_trial→trial e conta le sessioni
        # dai record reali, così la prova parte/avanza e può concludersi.
        await _recompute_trial_from_attendance(athlete, team_id)

        await log_audit(
            action="manual_attendance_added",
            user_id=current_user["id"],
            user_email=current_user.get("email", ""),
            society_id=society_id or "",
            target_user_id=aid,
            target_user_name=athlete_name,
            ip_address=get_real_ip(request),
            details={
                "team_name": team.get("name", ""),
                "date": data.date,
                "time": data.time or "",
                "note": (data.note or "").strip(),
                "inserted_by": actor_name,
                "extraordinary": True,
                "bulk": True,
            },
        )
        registered.append({"athlete_id": aid, "athlete_name": athlete_name})

    return {
        "message": f"{len(registered)} presenze registrate",
        "registered_count": len(registered),
        "skipped_count": len(skipped),
        "registered": registered,
        "skipped": skipped,
    }




