@api_router.get("/coach/my-teams")
async def get_coach_teams(current_user = Depends(get_current_user)):
    """Get teams assigned to the current coach"""
    if current_user["role"] != UserRole.COACH:
        raise HTTPException(status_code=403, detail="Solo coach può accedere")
    
    # Get teams assigned to this coach
    assigned_team_ids = current_user.get("assigned_teams", [])
    
    if not assigned_team_ids:
        return []
    
    _sid = current_user.get("society_id")
    _q_teams = {"id": {"$in": assigned_team_ids}}
    if _sid:
        _q_teams["society_id"] = _sid
    # Escludi base64 pesante; la foto è servita via URL (object storage / fallback)
    teams = await db.teams.find(_q_teams, {"team_photo": 0, "team_logo": 0}).to_list(100)
    clean_mongo_docs(teams)
    legacy_photo_ids = set()
    async for t in db.teams.find(
        {**_q_teams, "team_photo": {"$exists": True, "$nin": [None, ""]}},
        {"_id": 0, "id": 1},
    ):
        legacy_photo_ids.add(t["id"])
    _base_url = os.environ.get("EXPO_PUBLIC_BACKEND_URL") or os.environ.get("FRONTEND_URL") or ""
    result = []
    for team in teams:
        t = Team(**team).dict()
        if _base_url and (team.get("team_photo_storage_path") or team["id"] in legacy_photo_ids):
            t["team_photo_url"] = f"{_base_url}/api/teams/{team['id']}/photo.jpg"
        result.append(t)
    return result


@api_router.get("/coach/my-stats")
async def get_coach_my_stats(current_user = Depends(get_current_user)):
    """🆕 27/02/2026 — Statistiche aggregate coach dashboard.
    Ritorna:
      • atleti_seguiti: numero atleti attivi nelle squadre assegnate
      • gare_stagione: gare pianificate stagione corrente
      • gare_prossime: gare nei prossimi 7 giorni
      • allenamenti_settimana: allenamenti pianificati questa settimana (Lun-Dom)
      • presenze_settimana: presenze registrate questa settimana per le squadre del coach
      • presenze_mese: presenze registrate questo mese per le squadre del coach
    """
    if current_user["role"] != UserRole.COACH:
        raise HTTPException(status_code=403, detail="Solo coach può accedere")

    assigned_team_ids: List[str] = current_user.get("assigned_teams", []) or []
    _sid = current_user.get("society_id")

    if not assigned_team_ids:
        return {
            "atleti_seguiti": 0,
            "gare_stagione": 0,
            "gare_prossime": 0,
            "allenamenti_settimana": 0,
            "presenze_settimana": 0,
            "presenze_mese": 0,
        }

    # Squadre del coach (per contare training_sessions)
    _q_teams = {"id": {"$in": assigned_team_ids}}
    if _sid:
        _q_teams["society_id"] = _sid
    teams = await db.teams.find(_q_teams).to_list(200)

    now = datetime.utcnow()
    today_end = now.replace(hour=23, minute=59, second=59, microsecond=999999)
    # Lunedì 00:00 di questa settimana
    week_start = (now - timedelta(days=now.weekday())).replace(hour=0, minute=0, second=0, microsecond=0)
    # Primo del mese 00:00
    month_start = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
    # Fine settimana (Domenica 23:59)
    week_end = (week_start + timedelta(days=6)).replace(hour=23, minute=59, second=59, microsecond=999999)
    # 7 giorni da oggi
    next_week = today_end + timedelta(days=7)

    # Atleti attivi/trial nelle squadre assegnate (uso $or su team_id / team_id_2 come get_team_attendance_stats)
    _q_ath = {
        "$or": [
            {"team_id": {"$in": assigned_team_ids}},
            {"team_id_2": {"$in": assigned_team_ids}},
        ],
        "status": {"$in": ["active", "trial"]},
        "is_withdrawn": {"$ne": True},
    }
    if _sid:
        _q_ath["society_id"] = _sid
    atleti_seguiti = await db.athletes.count_documents(_q_ath)

    # Gare per queste squadre (matches collection ha team_id)
    _q_match_base = {"team_id": {"$in": assigned_team_ids}}
    if _sid:
        _q_match_base["society_id"] = _sid
    gare_stagione = await db.matches.count_documents(_q_match_base)
    _q_match_soon = dict(_q_match_base)
    _q_match_soon["date"] = {"$gte": now.replace(hour=0, minute=0, second=0, microsecond=0), "$lte": next_week}
    gare_prossime = await db.matches.count_documents(_q_match_soon)

    # Allenamenti settimana: somma dei training_sessions configurati sulle squadre (una sessione = un allenamento/settimana)
    allenamenti_settimana = 0
    for t in teams:
        sessions = t.get("training_sessions") or []
        allenamenti_settimana += len(sessions)

    # Presenze registrate settimana / mese per le squadre del coach
    _q_att_week = {"team_id": {"$in": assigned_team_ids}, "check_in_time": {"$gte": week_start, "$lte": week_end}}
    _q_att_month = {"team_id": {"$in": assigned_team_ids}, "check_in_time": {"$gte": month_start, "$lte": today_end}}
    presenze_settimana = await db.attendances.count_documents(_q_att_week)
    presenze_mese = await db.attendances.count_documents(_q_att_month)

    return {
        "atleti_seguiti": atleti_seguiti,
        "gare_stagione": gare_stagione,
        "gare_prossime": gare_prossime,
        "allenamenti_settimana": allenamenti_settimana,
        "presenze_settimana": presenze_settimana,
        "presenze_mese": presenze_mese,
    }

@api_router.get("/coach/commitments")
async def get_coach_commitments(
    user_id: Optional[str] = None,
    athlete_id: Optional[str] = None,
    current_user = Depends(get_current_user),
):
    """Get commitments (trainings + matches) for coach's teams - 7 days.
    🔧 22/06/2026 — Admin può passare ?user_id={coach_id} per vedere gli impegni di un altro coach.
    🆕 23/06/2026 — Admin può passare ?athlete_id={ath_id} per vedere gli impegni di un atleta.
    """
    # 🆕 Admin override: se admin passa user_id o athlete_id
    target_user = current_user
    is_athlete_view = False
    athlete_team_id = None

    if athlete_id and current_user.get("role") in (UserRole.ADMIN, UserRole.PARENT):
        ath = await db.athletes.find_one({"id": athlete_id}, {"_id": 0})
        if not ath:
            raise HTTPException(status_code=404, detail="Atleta non trovato")
        if current_user.get("role") == UserRole.PARENT:
            # 🆕 31/08/2026 — Un genitore può vedere gli impegni SOLO dei propri figli.
            if current_user["id"] not in (ath.get("parent_id"), ath.get("second_parent_id")):
                raise HTTPException(status_code=403, detail="Non sei genitore di questo atleta")
        else:
            if current_user.get("society_id") and ath.get("society_id") and current_user["society_id"] != ath["society_id"]:
                raise HTTPException(status_code=403, detail="Atleta di altra società")
        is_athlete_view = True
        # 🆕 08/07/2026 — Considera anche team_id_2 (seconda squadra) e team_ids array
        athlete_team_ids: List[str] = []
        for tid in [ath.get("team_id"), ath.get("team_id_2"), ath.get("team_id_secondary")]:
            if tid and tid not in athlete_team_ids:
                athlete_team_ids.append(tid)
        for tid in (ath.get("team_ids") or []):
            if tid and tid not in athlete_team_ids:
                athlete_team_ids.append(tid)
        athlete_team_id = athlete_team_ids  # ora è una list, gestita a linea 13224
        # Fake a target_user shape
        target_user = {**current_user, "society_id": ath.get("society_id"), "fiscal_code": ath.get("fiscal_code")}
    elif user_id and current_user.get("role") == UserRole.ADMIN:
        tu = await db.users.find_one({"id": user_id}, {"_id": 0})
        if not tu:
            raise HTTPException(status_code=404, detail="Utente non trovato")
        # Optional society scoping (admin di una società non può vedere coach di altre società)
        if current_user.get("society_id") and tu.get("society_id") and current_user["society_id"] != tu["society_id"]:
            raise HTTPException(status_code=403, detail="Coach di altra società")
        target_user = tu
        if tu.get("role") == UserRole.ATHLETE:
            is_athlete_view = True
    elif current_user["role"] == UserRole.ATHLETE:
        is_athlete_view = True
    elif current_user["role"] not in (UserRole.COACH, UserRole.DIRIGENTE, UserRole.COLLABORATORE, UserRole.VIEWER, UserRole.ADMIN):
        raise HTTPException(status_code=403, detail="Ruolo non autorizzato a vedere gli impegni")

    # 🆕 23/06/2026 — Atleti: cerchiamo i team_ids nel record athletes (no assigned_teams)
    if is_athlete_view:
        if athlete_team_id is not None:
            # Può essere una lista (nuovo formato 08/07/2026) o singolo string (legacy)
            if isinstance(athlete_team_id, list):
                team_ids = [t for t in athlete_team_id if t]
            else:
                team_ids = [athlete_team_id] if athlete_team_id else []
        else:
            athlete_doc = await db.athletes.find_one(
                {"fiscal_code": target_user.get("fiscal_code")},
                {"_id": 0, "team_id": 1, "team_id_2": 1, "team_id_secondary": 1, "team_ids": 1, "society_id": 1},
            )
            team_ids = []
            if athlete_doc:
                for tid in [athlete_doc.get("team_id"), athlete_doc.get("team_id_2"), athlete_doc.get("team_id_secondary")]:
                    if tid and tid not in team_ids:
                        team_ids.append(tid)
                for tid in (athlete_doc.get("team_ids") or []):
                    if tid and tid not in team_ids:
                        team_ids.append(tid)
    else:
        team_ids = target_user.get("assigned_teams", [])
    
    if not team_ids:
        return {"today": [], "tomorrow": [], "day_after": [], "upcoming": []}
    
    # Get teams info (for training schedules) — scoped by society
    _sid = target_user.get("society_id")
    _q_teams = {"id": {"$in": team_ids}}
    if _sid:
        _q_teams["society_id"] = _sid
    teams = await db.teams.find(_q_teams).to_list(20)
    teams_dict = {t["id"]: t for t in teams}

    # 🆕 12/08/2026 — Data inizio attività: gli allenamenti compaiono in "Da Fare"
    # SOLO se la squadra ha una data inizio attività impostata, e solo dalle date
    # >= data inizio. Se non impostata, gli allenamenti restano nascosti (l'attività
    # è ferma). trainings_provisional=True → gli allenamenti sono "provvisori".
    def _parse_activity_date(val):
        if not val:
            return None
        try:
            if isinstance(val, str):
                return datetime.fromisoformat(val.replace('Z', '').replace('+00:00', '')).replace(hour=0, minute=0, second=0, microsecond=0)
            if isinstance(val, datetime):
                return val.replace(hour=0, minute=0, second=0, microsecond=0)
        except Exception:
            return None
        return None
    team_activity = {}
    for _tid, _t in teams_dict.items():
        team_activity[_tid] = {
            "start": _parse_activity_date(_t.get("activity_start_date")),
            "provisional": bool(_t.get("trainings_provisional")),
        }

    def _training_visible(team_id, target_date):
        info = team_activity.get(team_id)
        if not info or not info.get("start"):
            return False  # senza data inizio attività → allenamenti nascosti
        return target_date.replace(hour=0, minute=0, second=0, microsecond=0) >= info["start"]
    
    # Get current date info
    # 🆕 30/08/2026 — Usa l'ora ITALIANA (Europe/Rome), non UTC. Il frontend etichetta i
    # giorni (Oggi/Domani/Dopodomani) con l'ora locale del dispositivo: usando utcnow() qui
    # nascevano disallineamenti di 1 giorno nelle ore serali/notturne (es. allenamento del
    # Lunedì che non compariva su "Oggi" e slittava su "Domani").
    now = now_it().replace(tzinfo=None)
    today = now.replace(hour=0, minute=0, second=0, microsecond=0)
    tomorrow = today + timedelta(days=1)
    day_after = today + timedelta(days=2)
    
    # Day of week mapping (Italian)
    days_map = {
        0: "Lunedì", 1: "Martedì", 2: "Mercoledì", 
        3: "Giovedì", 4: "Venerdì", 5: "Sabato", 6: "Domenica"
    }
    
    def get_day_name(date):
        return days_map[date.weekday()]
    
    # Get matches for 7 days FIRST (to know which teams have home matches on which days)
    end_of_week = today + timedelta(days=7)
    _q_matches = {"team_id": {"$in": team_ids}}
    if _sid:
        _q_matches["society_id"] = _sid
    matches = await db.matches.find(_q_matches).to_list(200)
    # Filter by date in Python (some records have date stored as ISO string)
    filtered_matches = []
    for m in matches:
        d = m.get("date")
        if isinstance(d, str):
            try:
                d = datetime.fromisoformat(d.replace("Z", "").replace("+00:00", ""))
            except Exception:
                continue
        if d and today <= d < end_of_week:
            m["date"] = d
            filtered_matches.append(m)
    matches = filtered_matches

    # Load training overrides (cancellations / modifications) within the same window
    _q_ovr = {
        "team_id": {"$in": team_ids},
        "date": {"$gte": today.strftime("%Y-%m-%d"), "$lt": end_of_week.strftime("%Y-%m-%d")}
    }
    if _sid:
        _q_ovr["society_id"] = _sid
    overrides_cursor = db.training_overrides.find(_q_ovr)
    overrides_map = {}
    async for ov in overrides_cursor:
        overrides_map[(ov.get("team_id"), ov.get("date"))] = ov
    
    # Build a set of (team_id, day_key) for home matches - these will skip training
    # Also build a dict for rifinitura (team_id, day_key) -> team info for rifinitura
    home_match_days = set()
    home_match_rifinitura = {}  # (team_id, day_key) -> team info for rifinitura
    
    for match in matches:
        match_date = match.get("date")
        if isinstance(match_date, str):
            match_date = datetime.fromisoformat(match_date.replace("Z", ""))
        
        # ALL matches (home OR away) hide the training of that team
        # because the team is busy with the match. For HOME matches we also
        # surface the rifinitura (pre-match warm-up) if configured.
        team_id = match.get("team_id")
        team = teams_dict.get(team_id, {})
        rifinitura = team.get("rifinitura", {})
        is_home = match.get("home_away") == "home"

        if today <= match_date < tomorrow:
            home_match_days.add((team_id, "today"))
            if is_home and rifinitura and rifinitura.get("enabled"):
                home_match_rifinitura[(team_id, "today")] = {
                    "team_name": team.get("name", "Squadra"),
                    "rifinitura": rifinitura
                }
        elif tomorrow <= match_date < day_after:
            home_match_days.add((team_id, "tomorrow"))
            if is_home and rifinitura and rifinitura.get("enabled"):
                home_match_rifinitura[(team_id, "tomorrow")] = {
                    "team_name": team.get("name", "Squadra"),
                    "rifinitura": rifinitura
                }
        elif day_after <= match_date < (day_after + timedelta(days=1)):
            home_match_days.add((team_id, "day_after"))
            if is_home and rifinitura and rifinitura.get("enabled"):
                home_match_rifinitura[(team_id, "day_after")] = {
                    "team_name": team.get("name", "Squadra"),
                    "rifinitura": rifinitura
                }
        else:
            # For upcoming, we need to track by date
            date_str = match_date.strftime("%d/%m")
            home_match_days.add((team_id, date_str))
            if is_home and rifinitura and rifinitura.get("enabled"):
                home_match_rifinitura[(team_id, date_str)] = {
                    "team_name": team.get("name", "Squadra"),
                    "rifinitura": rifinitura,
                    "date": date_str,
                    "day_name": days_map[match_date.weekday()]
                }
    
    # Build commitments for each day
    result = {"today": [], "tomorrow": [], "day_after": [], "upcoming": []}
    
    for day_key, target_date in [("today", today), ("tomorrow", tomorrow), ("day_after", day_after)]:
        day_name = get_day_name(target_date)
        date_iso = target_date.strftime("%Y-%m-%d")

        # Check trainings for this day
        for team_id in team_ids:
            # Skip training silently if there's a match (home or away) for this team on this day
            if (team_id, day_key) in home_match_days:
                continue

            team = teams_dict.get(team_id, {})
            team_name = team.get("name", "Squadra")
            training_sessions = team.get("training_sessions", [])
            override = overrides_map.get((team_id, date_iso))
            if not _training_visible(team_id, target_date):
                continue

            for session in training_sessions:
                if session.get("day") == day_name:
                    t_start = session.get("timeStart", "")
                    t_end = session.get("timeEnd", "")
                    venue = session.get("venue", "")
                    cancelled = False
                    modified = False
                    reason = None
                    if override and override.get("status") == "cancelled":
                        cancelled = True
                        reason = override.get("reason")
                    elif override and override.get("status") == "modified":
                        t_start = override.get("new_start_time", t_start) or t_start
                        t_end = override.get("new_end_time", t_end) or t_end
                        venue = override.get("new_venue", venue) or venue
                        reason = override.get("reason")
                        modified = True
                    result[day_key].append({
                        "type": "training",
                        "team_id": team_id,
                        "team_name": team_name,
                        "time_start": t_start,
                        "time_end": t_end,
                        "venue": venue,
                        "title": f"Allenamento {team_name}",
                        "cancelled": cancelled,
                        "modified": modified,
                        "reason": reason,
                        "provisional": team_activity.get(team_id, {}).get("provisional", False),
                    })
        
        # Add rifinitura for home matches on this day
        for team_id in team_ids:
            if (team_id, day_key) in home_match_rifinitura:
                rif_info = home_match_rifinitura[(team_id, day_key)]
                rifinitura = rif_info["rifinitura"]
                result[day_key].append({
                    "type": "rifinitura",
                    "team_id": team_id,
                    "team_name": rif_info["team_name"],
                    "time_start": rifinitura.get("timeStart", ""),
                    "time_end": rifinitura.get("timeEnd", ""),
                    "venue": rifinitura.get("venue", ""),
                    "title": f"Rifinitura pre-gara {rif_info['team_name']}"
                })
    
    # Check trainings for upcoming days (days 4-7)
    for day_offset in range(3, 7):
        target_date = today + timedelta(days=day_offset)
        day_name = get_day_name(target_date)
        date_str = target_date.strftime("%d/%m")
        date_iso = target_date.strftime("%Y-%m-%d")

        for team_id in team_ids:
            # Skip training silently if there's a match (home or away) for this team on this day
            if (team_id, date_str) in home_match_days:
                continue

            team = teams_dict.get(team_id, {})
            team_name = team.get("name", "Squadra")
            training_sessions = team.get("training_sessions", [])
            override = overrides_map.get((team_id, date_iso))
            if not _training_visible(team_id, target_date):
                continue

            for session in training_sessions:
                if session.get("day") == day_name:
                    t_start = session.get("timeStart", "")
                    t_end = session.get("timeEnd", "")
                    venue = session.get("venue", "")
                    cancelled = False
                    modified = False
                    reason = None
                    if override and override.get("status") == "cancelled":
                        cancelled = True
                        reason = override.get("reason")
                    elif override and override.get("status") == "modified":
                        t_start = override.get("new_start_time", t_start) or t_start
                        t_end = override.get("new_end_time", t_end) or t_end
                        venue = override.get("new_venue", venue) or venue
                        reason = override.get("reason")
                        modified = True
                    result["upcoming"].append({
                        "type": "training",
                        "team_id": team_id,
                        "team_name": team_name,
                        "date": date_str,
                        "day_name": day_name,
                        "time_start": t_start,
                        "time_end": t_end,
                        "venue": venue,
                        "title": f"Allenamento {team_name}",
                        "cancelled": cancelled,
                        "modified": modified,
                        "reason": reason,
                        "provisional": team_activity.get(team_id, {}).get("provisional", False),
                    })
    
    # Add rifinitura for upcoming days with home matches
    for day_offset in range(3, 7):
        target_date = today + timedelta(days=day_offset)
        date_str = target_date.strftime("%d/%m")
        day_name = get_day_name(target_date)
        
        for team_id in team_ids:
            if (team_id, date_str) in home_match_rifinitura:
                rif_info = home_match_rifinitura[(team_id, date_str)]
                rifinitura = rif_info["rifinitura"]
                result["upcoming"].append({
                    "type": "rifinitura",
                    "team_id": team_id,
                    "team_name": rif_info["team_name"],
                    "date": date_str,
                    "day_name": day_name,
                    "time_start": rifinitura.get("timeStart", ""),
                    "time_end": rifinitura.get("timeEnd", ""),
                    "venue": rifinitura.get("venue", ""),
                    "title": f"Rifinitura pre-gara {rif_info['team_name']}"
                })
    
    _soc_short = await _society_short_name_for(current_user.get("society_id"))
    for match in matches:
        match_date = match.get("date")
        if isinstance(match_date, str):
            match_date = datetime.fromisoformat(match_date.replace("Z", ""))
        
        if today <= match_date < tomorrow:
            day_key = "today"
        elif tomorrow <= match_date < day_after:
            day_key = "tomorrow"
        elif day_after <= match_date < (day_after + timedelta(days=1)):
            day_key = "day_after"
        elif match_date < end_of_week:
            day_key = "upcoming"
        else:
            continue
        
        match_item = {
            "type": "match",
            "team_id": match.get("team_id"),
            "team_name": match.get("team_name", ""),
            "time": match_date.strftime("%H:%M"),
            "venue": match.get("venue", ""),
            "city": match.get("city", ""),
            "address": match.get("address", ""),
            "opponent": match.get("opponent", ""),
            "home_away": match.get("home_away", "home"),
            "meeting_time": match.get("meeting_time"),
            "notes": match.get("notes"),
            "society_name": _soc_short,
            # 🆕 "Gara Sirio Perugia vs X" (o "X vs Sirio Perugia" in trasferta) invece del nome squadra
            "title": (f"Gara {_soc_short or match.get('team_name', '')} vs {match.get('opponent', '')}"
                      if (match.get("home_away") or "home") == "home"
                      else f"Gara {match.get('opponent', '')} vs {_soc_short or match.get('team_name', '')}"),
        }
        
        if day_key == "upcoming":
            match_item["date"] = match_date.strftime("%d/%m")
            match_item["day_name"] = get_day_name(match_date)
        
        result[day_key].append(match_item)
    
    # Sort by time
    for day_key in ["today", "tomorrow", "day_after"]:
        result[day_key].sort(key=lambda x: x.get("time_start", x.get("time", "00:00")))
    
    # Sort upcoming by date and time
    result["upcoming"].sort(key=lambda x: (x.get("date", ""), x.get("time_start", x.get("time", "00:00"))))

    # 🆕 12/08/2026 — Banner "inizio allenamenti" per le squadre del membro.
    # Visibile fino al giorno dell'inizio (scompare il giorno dopo la data prevista).
    activity_banners = []
    for _tid, _info in team_activity.items():
        _start = _info.get("start")
        if _start and _start.date() >= today.date():
            _t = teams_dict.get(_tid, {})
            activity_banners.append({
                "team_id": _tid,
                "team_name": _t.get("name", "Squadra"),
                "start_date": _start.strftime("%Y-%m-%d"),
                "start_label": _start.strftime("%d/%m/%Y"),
                "provisional": _info.get("provisional", False),
            })
    result["activity_banners"] = activity_banners

    return result

@api_router.get("/coach/commitments-debug")
async def get_coach_commitments_debug(
    user_id: str,
    current_user = Depends(get_current_user),
):
    """🔍 06/2026 — Diagnostica: spiega PERCHÉ un allenamento compare o NON compare
    negli impegni di un coach. Solo admin. Analizza i dati reali delle squadre assegnate."""
    if current_user.get("role") != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")

    coach = await db.users.find_one({"id": user_id}, {"_id": 0})
    if not coach:
        raise HTTPException(status_code=404, detail="Coach non trovato")
    if current_user.get("society_id") and coach.get("society_id") and current_user["society_id"] != coach["society_id"]:
        raise HTTPException(status_code=403, detail="Coach di altra società")

    coach_sid = coach.get("society_id")
    assigned = coach.get("assigned_teams", []) or []

    days_map = {0: "Lunedì", 1: "Martedì", 2: "Mercoledì", 3: "Giovedì", 4: "Venerdì", 5: "Sabato", 6: "Domenica"}
    now = now_it().replace(tzinfo=None)
    today = now.replace(hour=0, minute=0, second=0, microsecond=0)
    end_of_week = today + timedelta(days=7)

    def _parse_asd(val):
        if not val:
            return None, "vuota"
        try:
            if isinstance(val, datetime):
                return val.replace(hour=0, minute=0, second=0, microsecond=0), f"datetime {val.isoformat()}"
            if isinstance(val, str):
                d = datetime.fromisoformat(val.replace('Z', '').replace('+00:00', ''))
                return d.replace(hour=0, minute=0, second=0, microsecond=0), f"stringa '{val}'"
        except Exception as e:
            return None, f"NON parsabile ('{val}': {e})"
        return None, f"tipo non gestito ({type(val).__name__})"

    report = {
        "coach_name": coach.get("full_name") or coach.get("name") or coach.get("email"),
        "coach_society_id": coach_sid,
        "today": today.strftime("%d/%m/%Y (%A)"),
        "assigned_team_ids": assigned,
        "teams": [],
    }

    for tid in assigned:
        entry = {"team_id": tid}
        # Cerca la squadra SENZA filtro società per capire se è una questione di scoping
        team = await db.teams.find_one({"id": tid}, {"_id": 0})
        if not team:
            entry["esito"] = "❌ SQUADRA NON TROVATA: l'id in assigned_teams non corrisponde a nessuna squadra (id obsoleto)."
            report["teams"].append(entry)
            continue
        entry["name"] = team.get("name")
        entry["team_society_id"] = team.get("society_id")
        society_ok = (not coach_sid) or (not team.get("society_id")) or (coach_sid == team.get("society_id"))
        entry["society_match"] = society_ok

        asd_raw = team.get("activity_start_date")
        asd_parsed, asd_desc = _parse_asd(asd_raw)
        entry["activity_start_date_raw"] = str(asd_raw)
        entry["activity_start_date_parsed"] = asd_parsed.strftime("%d/%m/%Y") if asd_parsed else None
        entry["activity_start_date_desc"] = asd_desc

        sessions = team.get("training_sessions", []) or []
        entry["num_training_sessions"] = len(sessions)
        entry["training_days"] = [f"{s.get('day')!r} {s.get('timeStart','')}-{s.get('timeEnd','')}" for s in sessions]

        # Gare nei prossimi 7 giorni per questa squadra
        tms = await db.matches.find({"team_id": tid}).to_list(200)
        match_days = []
        for m in tms:
            d = m.get("date")
            if isinstance(d, str):
                try:
                    d = datetime.fromisoformat(d.replace("Z", "").replace("+00:00", ""))
                except Exception:
                    continue
            if d and today <= d < end_of_week:
                match_days.append(f"{days_map[d.weekday()]} {d.strftime('%d/%m %H:%M')} ({m.get('home_away')})")
        entry["matches_this_week"] = match_days

        # Valuta la visibilità per ciascuno dei prossimi 7 giorni
        valid_day_names = set(days_map.values())
        session_day_values = {s.get("day") for s in sessions}
        unknown_days = [d for d in session_day_values if d not in valid_day_names]
        entry["training_days_non_riconosciuti"] = unknown_days

        reasons = []
        if not society_ok:
            reasons.append("ESCLUSA dal filtro società (society_id squadra diverso da quello del coach)")
        if not asd_parsed:
            reasons.append(f"Data inizio attività {asd_desc} → allenamenti NASCOSTI")
        elif asd_parsed > today:
            reasons.append(f"Data inizio attività nel FUTURO ({asd_parsed.strftime('%d/%m/%Y')}) → ancora nascosti")
        if len(sessions) == 0:
            reasons.append("NESSUN allenamento configurato nella squadra")
        if unknown_days:
            reasons.append(f"Giorni non riconosciuti (accento/maiuscole?): {unknown_days}")
        if match_days:
            reasons.append(f"Gare che possono nascondere l'allenamento del giorno: {match_days}")

        entry["problemi"] = reasons
        entry["esito"] = "✅ Dovrebbe comparire" if not reasons else "⚠️ " + " | ".join(reasons)
        report["teams"].append(entry)

    return report


@api_router.get("/coach/team/{team_id}/athletes")
async def get_coach_team_athletes(team_id: str, current_user = Depends(get_current_user)):
    """Get athletes for a team (coach view - limited info)"""
    if current_user["role"] != UserRole.COACH:
        raise HTTPException(status_code=403, detail="Solo coach può accedere")
    
    # Check if coach is assigned to this team
    assigned_team_ids = current_user.get("assigned_teams", [])
    if team_id not in assigned_team_ids:
        raise HTTPException(status_code=403, detail="Non sei assegnato a questa squadra")
    
    # Get athletes (team_id or team_id_2, including trial athletes with attendances) — scoped by society
    _sid = current_user.get("society_id")
    _q = {
        "$or": [
            {"team_id": team_id},
            {"team_id_2": team_id}
        ],
        "is_withdrawn": {"$ne": True}
    }
    if _sid:
        _q["society_id"] = _sid
    athletes = await db.athletes.find(_q).to_list(1000)
    
    # Also include trial athletes who have attendances for this team
    team_athlete_ids = [a["id"] for a in athletes]
    trial_attendance_ids = await db.attendances.distinct("athlete_id", {"team_id": team_id})
    missing_ids = [aid for aid in trial_attendance_ids if aid not in team_athlete_ids]
    if missing_ids:
        _q_extra = {
            "id": {"$in": missing_ids},
            "status": "trial",
            "is_withdrawn": {"$ne": True}
        }
        if _sid:
            _q_extra["society_id"] = _sid
        extra_athletes = await db.athletes.find(_q_extra).to_list(100)
        athletes.extend(extra_athletes)
    
    clean_mongo_docs(athletes)
    
    # Get certificate info and return limited data
    result = []
    for athlete in athletes:
        cert = await db.certificates.find_one({"athlete_id": athlete["id"]})
        
        athlete_data = {
            "id": athlete["id"],
            "full_name": athlete.get("full_name", ""),
            "first_name": athlete.get("first_name", ""),
            "last_name": athlete.get("last_name", ""),
            "status": athlete.get("status", "active"),
            "certificate_expiry": cert["expiry_date"].isoformat() if cert and cert.get("expiry_date") else None,
            "is_expired": cert["expiry_date"] < datetime.now() if cert and cert.get("expiry_date") else True
        }
        result.append(athlete_data)
    
    return result

