@api_router.get("/stats/overview")
async def get_stats_overview(current_user = Depends(get_current_user)):
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può vedere statistiche")
    
    society_id = current_user.get("society_id")
    
    total_teams = await db.teams.count_documents({"society_id": society_id})
    total_athletes = await db.athletes.count_documents({"society_id": society_id})
    active_athletes = await db.athletes.count_documents({"status": "active", "society_id": society_id})
    
    # Today's attendances - need to check team_id belongs to society
    today_start = datetime.utcnow().replace(hour=0, minute=0, second=0, microsecond=0)
    # Get all team IDs for this society
    society_teams = await db.teams.find({"society_id": society_id}, {"id": 1}).to_list(100)
    team_ids = [t["id"] for t in society_teams]
    
    today_attendances = await db.attendances.count_documents({
        "check_in_time": {"$gte": today_start},
        "team_id": {"$in": team_ids}
    })
    
    # Athlete limit info
    ATHLETE_LIMIT = 150
    LIMIT_END_DATE = datetime(2026, 6, 30, 23, 59, 59)
    limit_active = datetime.utcnow() < LIMIT_END_DATE
    
    return {
        "total_teams": total_teams,
        "total_athletes": total_athletes,
        "active_athletes": active_athletes,
        "today_attendances": today_attendances,
        "athlete_limit": {
            "max": ATHLETE_LIMIT,
            "current": total_athletes,
            "remaining": max(0, ATHLETE_LIMIT - total_athletes),
            "active": limit_active,
            "end_date": LIMIT_END_DATE.strftime("%Y-%m-%d") if limit_active else None
        }
    }

@api_router.get("/admin/recent-18th-birthdays")
async def get_recent_18th_birthdays(days: int = 30, current_user = Depends(get_current_user)):
    """🆕 27/02/2026 (P2 GDPR 18°) — Ritorna gli atleti che hanno compiuto
    18 anni negli ultimi N giorni (default 30). Utile per l'admin dashboard
    per verificare quali profili sono passati alla gestione autonoma.
    """
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")
    _sid = current_user.get("society_id")
    now = now_it()
    since = now - timedelta(days=max(1, min(days, 365)))
    # Un atleta è "recente 18enne" se la sua data di nascita è ESATTAMENTE 18 anni fa,
    # compreso in [now-days, now]. Costruiamo range su DOB:
    dob_end = datetime(now.year - 18, now.month, now.day) + timedelta(days=1)
    dob_start = datetime(since.year - 18, since.month, since.day)
    q = {
        "date_of_birth": {"$gte": dob_start, "$lt": dob_end},
        "is_withdrawn": {"$ne": True},
    }
    if _sid:
        q["society_id"] = _sid
    proj = {"_id": 0, "id": 1, "full_name": 1, "first_name": 1, "last_name": 1,
            "date_of_birth": 1, "email": 1, "parent_ids": 1, "team_id": 1,
            "birthday_18_notified_at": 1, "birthday_18_recipients_count": 1}
    items = await db.athletes.find(q, proj).sort("date_of_birth", -1).to_list(200)
    for a in items:
        dob = a.get("date_of_birth")
        if isinstance(dob, datetime):
            a["date_of_birth"] = dob.strftime("%Y-%m-%d")
            # calcola età esatta oggi
            try:
                a["turned_18_on"] = datetime(dob.year + 18, dob.month, dob.day).strftime("%Y-%m-%d")
            except Exception:
                a["turned_18_on"] = None
    return {"count": len(items), "athletes": items}



@api_router.get("/birthdays/today")
async def get_today_birthdays(current_user = Depends(get_current_user)):
    """Get all birthdays for today - athletes, coaches, and dirigenti.

    NOTE: "today" is the Italian calendar day (Europe/Rome). Using UTC here
    would shift the dashboard by 1-2 hours and show "yesterday's" birthdays
    between midnight and ~02:00 Italian time.
    """
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può vedere i compleanni")

    today = now_it()
    today_month = today.month
    today_day = today.day
    
    birthdays = []
    
    society_id = current_user.get("society_id")
    
    # Projection: avoid transferring heavy base64 photos for this lightweight list.
    ATHLETE_PROJ = {"_id": 0, "id": 1, "full_name": 1, "date_of_birth": 1}
    USER_PROJ = {"_id": 0, "id": 1, "full_name": 1, "date_of_birth": 1, "role": 1}
    
    # Check athletes - filter by society
    athletes = await db.athletes.find({"society_id": society_id}, ATHLETE_PROJ).to_list(1000)
    for athlete in athletes:
        dob = athlete.get("date_of_birth")
        if dob:
            if isinstance(dob, str):
                try:
                    dob = datetime.fromisoformat(dob.replace('Z', '+00:00'))
                except:
                    continue
            if dob.month == today_month and dob.day == today_day:
                age = today.year - dob.year
                birthdays.append({
                    "id": athlete["id"],
                    "name": athlete["full_name"],
                    "type": "atleta",
                    "age": age,
                    "icon": "person"
                })
    
    # Check users (coaches and dirigenti) - filter by society
    users = await db.users.find({
        "society_id": society_id,
        "role": {"$in": [UserRole.COACH, UserRole.VIEWER, UserRole.ADMIN]},
        "status": UserStatus.APPROVED
    }, USER_PROJ).to_list(1000)
    
    for user in users:
        dob = user.get("date_of_birth")
        if dob:
            if isinstance(dob, str):
                try:
                    dob = datetime.fromisoformat(dob.replace('Z', '+00:00'))
                except:
                    continue
            if dob.month == today_month and dob.day == today_day:
                age = today.year - dob.year
                role_label = "coach" if user["role"] == UserRole.COACH else "dirigente"
                if user["role"] == UserRole.ADMIN:
                    role_label = "admin"
                birthdays.append({
                    "id": user["id"],
                    "name": user["full_name"],
                    "type": role_label,
                    "age": age,
                    "icon": "fitness" if user["role"] == UserRole.COACH else "briefcase"
                })
    
    return birthdays


