@api_router.post("/coach/{coach_id}/accept-compensation")
async def accept_coach_compensation(coach_id: str, current_user = Depends(get_current_user)):
    """Coach accepts the compensation offer"""
    if current_user["role"] != UserRole.COACH or current_user["id"] != coach_id:
        raise HTTPException(status_code=403, detail="Solo il coach può accettare il proprio compenso")
    
    # 🆕 27/07/2026 — Blocca se pregresso non dichiarato (Riforma Sport)
    await _require_prior_compensation_declared(coach_id)
    # 🆕 Blocca se manca la Dichiarazione posizione previdenziale (firma separata)
    await _require_pension_declared([coach_id])
    
    # Update coach record
    now = datetime.utcnow()
    # Calculate contract end date (31/05 of current season)
    season_end_year = now.year if now.month <= 5 else now.year + 1
    contract_end = datetime(season_end_year, 5, 31)
    
    await db.users.update_one(
        {"id": coach_id},
        {"$set": {
            "compensation_accepted": True,
            "compensation_accepted_date": now,
            "contract_start_date": now,
            "contract_end_date": contract_end
        }}
    )
    
    return {"message": "Compenso accettato", "contract_end": contract_end.strftime("%d/%m/%Y")}

@api_router.post("/coach/{coach_id}/compensation/{year}/{month}/received")
async def mark_compensation_received(
    coach_id: str, 
    year: int, 
    month: int, 
    exceeded_5000: bool = False,
    exceeded_15000: bool = False,
    current_user = Depends(get_current_user)
):
    """Coach marks compensation as received for a specific month"""
    if current_user["role"] != UserRole.COACH or current_user["id"] != coach_id:
        raise HTTPException(status_code=403, detail="Solo il coach può confermare i propri compensi")
    
    # Get coach's monthly compensation amount
    coach = await db.users.find_one({"id": coach_id})
    if not coach:
        raise HTTPException(status_code=404, detail="Coach non trovato")
    
    amount = coach.get("monthly_compensation", 0)
    
    # Check if record exists
    existing = await db.coach_compensations.find_one({
        "coach_id": coach_id,
        "year": year,
        "month": month
    })
    
    now = datetime.utcnow()
    
    if existing:
        # Update existing
        await db.coach_compensations.update_one(
            {"id": existing["id"]},
            {"$set": {
                "received": True,
                "received_date": now,
                "exceeded_5000": exceeded_5000,
                "exceeded_5000_date": now if exceeded_5000 else None,
                "exceeded_15000": exceeded_15000,
                "exceeded_15000_date": now if exceeded_15000 else None
            }}
        )
    else:
        # Create new record
        record = CoachCompensation(
            coach_id=coach_id,
            month=month,
            year=year,
            amount=amount,
            received=True,
            received_date=now,
            exceeded_5000=exceeded_5000,
            exceeded_5000_date=now if exceeded_5000 else None,
            exceeded_15000=exceeded_15000,
            exceeded_15000_date=now if exceeded_15000 else None
        )
        await db.coach_compensations.insert_one(record.dict())
    
    # If exceeded €5000, notify admin
    if exceeded_5000:
        # Create notification for admin
        notification = AdminNotification(
            type="coach_exceeded_5000",
            title="⚠️ Coach ha superato €5.000",
            message=f"Il coach {coach.get('full_name', 'Sconosciuto')} ha dichiarato di aver superato il limite di €5.000 annuali di compensi sportivi dilettantistici.",
            related_user_id=coach_id,
            related_user_name=coach.get('full_name', '')
        )
        await db.admin_notifications.insert_one(notification.dict())
    
    # If exceeded €15000, notify admin (more urgent!)
    if exceeded_15000:
        notification = AdminNotification(
            type="coach_exceeded_15000",
            title="🚨 URGENTE: Coach ha superato €15.000",
            message=f"ATTENZIONE: Il coach {coach.get('full_name', 'Sconosciuto')} ha dichiarato di aver superato il limite di €15.000 annuali. Questo comporta obblighi fiscali e contributivi aggiuntivi!",
            related_user_id=coach_id,
            related_user_name=coach.get('full_name', '')
        )
        await db.admin_notifications.insert_one(notification.dict())
    
    return {"message": "Compenso confermato", "exceeded_5000": exceeded_5000, "exceeded_15000": exceeded_15000}

@api_router.get("/coach/{coach_id}/compensation/annual/{year}")
async def get_annual_compensation_summary(coach_id: str, year: int, current_user = Depends(get_current_user)):
    """Get annual summary of compensations"""
    if current_user["role"] not in [UserRole.ADMIN, UserRole.COACH]:
        raise HTTPException(status_code=403, detail="Accesso negato")
    
    records = await db.coach_compensations.find({
        "coach_id": coach_id,
        "year": year,
        "received": True
    }).to_list(12)
    
    total = sum(r.get("amount", 0) for r in records)
    exceeded_month = next((r for r in records if r.get("exceeded_5000")), None)
    
    return {
        "year": year,
        "total_received": total,
        "months_received": len(records),
        "exceeded_5000": exceeded_month is not None,
        "exceeded_month": exceeded_month.get("month") if exceeded_month else None
    }

# Quietanza Compenso Sportivo Request model
class CompensationReceiptRequest(BaseModel):
    month: int
    year: int
    amount_gross: float
    signature_base64: str
    exceeded_5000: bool = False
    exceeded_15000: bool = False
    # Auto-dichiarazione INCREMENTALE: importo compensi sportivi percepiti
    # da ALTRE ASD/SSD dall'ultima firma (o dall'inizio anno) ad oggi.
    # Concorre al calcolo cumulativo annuo per le soglie 5K/15K (per cassa).
    external_compensation_amount: float = 0.0
    # Flag esplicito: "No, non ho ricevuto altri compensi"
    external_compensation_none: bool = False

class AdminCreateReceiptRequest(BaseModel):
    month: int
    year: int
    amount_gross: float  # Admin can specify custom amount

@api_router.get("/admin/athletes/{athlete_id}/external-compensations")
async def admin_get_athlete_externals(
    athlete_id: str,
    current_user = Depends(get_current_user)
):
    """🆕 29/06/2026 — Admin: ritorna i compensi esterni dichiarati da un atleta
    raggruppati per anno (utilizzato dal modal "Gestione Quietanze" per calcolare
    correttamente le soglie cronologiche in modo identico al lato user)."""
    if current_user.get("role") != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")
    athlete = await db.athletes.find_one({"id": athlete_id}, {"_id": 0, "id": 1, "society_id": 1, "linked_user_id": 1, "user_id": 1})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    if current_user.get("society_id") and athlete.get("society_id") != current_user.get("society_id"):
        raise HTTPException(status_code=403, detail="Atleta di altra società")
    candidate_ids = list({uid for uid in [athlete_id, athlete.get("linked_user_id"), athlete.get("user_id")] if uid})
    q: dict = {"user_id": {"$in": candidate_ids}} if len(candidate_ids) > 1 else {"user_id": athlete_id}
    by_year: dict = {}
    items: list = []
    async for d in db.external_compensations.find(q, {"_id": 0}):
        y = int(d.get("year") or 0)
        if not y:
            continue
        amt = float(d.get("amount") or 0)
        by_year[y] = by_year.get(y, 0) + amt
        items.append(d)
    return {"by_year": by_year, "items": items}


@api_router.post("/admin/athletes/{athlete_id}/compensation/create-receipt")
async def admin_create_athlete_receipt(
    athlete_id: str,
    request: AdminCreateReceiptRequest,
    current_user = Depends(get_current_user)
):
    """Admin crea una quietanza per un atleta con importo personalizzato (da firmare poi dall'atleta).
    🆕 28/06/2026 — Replica del flusso /admin/coach/{coach_id}/compensation/create-receipt.
    Marca la quietanza come supplementare se l'importo è diverso dal compenso mensile contrattuale."""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo l'admin può creare quietanze")

    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")

    # Compenso base mensile (per identificare quietanze "supplementari")
    athlete_monthly = float(athlete.get("monthly_compensation") or 0)
    delta_extra = float(request.amount_gross) - athlete_monthly
    is_supp = abs(delta_extra) > 0.009
    extra_amt = round(delta_extra, 2) if is_supp else 0.0

    # Check existing receipt for this month/year
    existing = await db.athlete_compensation_receipts.find_one({
        "athlete_id": athlete_id,
        "year": request.year,
        "month": request.month,
    })

    if existing:
        await db.athlete_compensation_receipts.update_one(
            {"athlete_id": athlete_id, "year": request.year, "month": request.month},
            {"$set": {
                "amount_gross": request.amount_gross,
                "amount": request.amount_gross,
                "amount_net": request.amount_gross,
                "is_supplementary": is_supp,
                "extra_amount": extra_amt,
                "updated_at": datetime.now(timezone.utc).isoformat(),
                "updated_by": current_user["id"],
            }}
        )
        return {"message": f"Quietanza aggiornata: {request.month}/{request.year} - €{request.amount_gross}", "updated": True, "is_supplementary": is_supp, "extra_amount": extra_amt}

    receipt_id = str(uuid.uuid4())[:8]
    new_receipt = {
        "id": receipt_id,
        "athlete_id": athlete_id,
        "society_id": athlete.get("society_id"),
        "year": request.year,
        "month": request.month,
        "amount_gross": request.amount_gross,
        "amount": request.amount_gross,
        "amount_net": request.amount_gross,
        "is_supplementary": is_supp,
        "extra_amount": extra_amt,
        "received": True,
        "receipt_signed": False,
        "created_at": datetime.now(timezone.utc).isoformat(),
        "created_by": current_user["id"],
    }
    await db.athlete_compensation_receipts.insert_one(new_receipt)
    return {"message": f"Quietanza creata: {request.month}/{request.year} - €{request.amount_gross}", "created": True, "id": receipt_id, "is_supplementary": is_supp, "extra_amount": extra_amt}


@api_router.post("/admin/coach/{coach_id}/compensation/create-receipt")
async def admin_create_coach_receipt(
    coach_id: str,
    request: AdminCreateReceiptRequest,
    current_user = Depends(get_current_user)
):
    """Admin crea una quietanza per un coach con importo personalizzato (da firmare poi dal coach)"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo l'admin può creare quietanze")
    
    # Get coach data
    coach = await db.users.find_one({"id": coach_id})
    if not coach:
        raise HTTPException(status_code=404, detail="Coach non trovato")

    # 🆕 27/02/2026 — Marcatura "Quietanza Supplementare": se l'admin emette un
    # importo diverso dal compenso mensile contrattuale, il record viene marcato
    # come supplementare con l'extra_amount calcolato (premio/lavoro extra).
    coach_monthly = float(coach.get("monthly_compensation") or 0)
    delta_extra = float(request.amount_gross) - coach_monthly
    is_supp = abs(delta_extra) > 0.009  # tolleranza decimali
    extra_amt = round(delta_extra, 2) if is_supp else 0.0

    # Check if receipt already exists
    existing = await db.coach_compensations.find_one({
        "coach_id": coach_id,
        "year": request.year,
        "month": request.month
    })
    
    if existing:
        # Update existing receipt with new amount
        await db.coach_compensations.update_one(
            {"coach_id": coach_id, "year": request.year, "month": request.month},
            {"$set": {
                "amount_gross": request.amount_gross,
                "amount": request.amount_gross,
                "amount_net": request.amount_gross,
                "is_supplementary": is_supp,
                "extra_amount": extra_amt,
                "updated_at": datetime.now(timezone.utc).isoformat(),
                "updated_by": current_user["id"]
            }}
        )
        return {"message": f"Quietanza aggiornata: {request.month}/{request.year} - €{request.amount_gross}", "updated": True, "is_supplementary": is_supp, "extra_amount": extra_amt}
    else:
        # Create new receipt
        receipt_id = str(uuid.uuid4())[:8]
        new_receipt = {
            "id": receipt_id,
            "coach_id": coach_id,
            "year": request.year,
            "month": request.month,
            "amount_gross": request.amount_gross,
            "amount": request.amount_gross,
            "amount_net": request.amount_gross,
            "is_supplementary": is_supp,
            "extra_amount": extra_amt,
            "received": True,
            "receipt_signed": False,
            "created_at": datetime.now(timezone.utc).isoformat(),
            "created_by": current_user["id"]
        }
        await db.coach_compensations.insert_one(new_receipt)
        return {"message": f"Quietanza creata: {request.month}/{request.year} - €{request.amount_gross}", "created": True, "id": receipt_id, "is_supplementary": is_supp, "extra_amount": extra_amt}

