# Endpoint to get all custom receipts for admin management
@api_router.get("/admin/quietanze/all")
async def admin_get_all_custom_receipts(
    current_user = Depends(get_current_user)
):
    """Get all custom receipts across all users for centralized management"""
    if current_user.get("role") != "admin":
        raise HTTPException(status_code=403, detail="Solo admin")
    
    all_receipts = []
    
    # Cache for admin names to avoid repeated lookups
    admin_cache = {}
    
    async def get_admin_name(admin_id):
        if not admin_id:
            return None
        if admin_id in admin_cache:
            return admin_cache[admin_id]
        admin = await db.users.find_one({"id": admin_id})
        name = admin.get("full_name", "Admin") if admin else None
        admin_cache[admin_id] = name
        return name
    
    # Multi-tenant: only consider users belonging to admin's society
    _sid = current_user.get("society_id")
    _users_q = {"society_id": _sid} if _sid else {}
    society_user_ids = set()
    async for u in db.users.find(_users_q, {"_id": 0, "id": 1}):
        if u.get("id"):
            society_user_ids.add(u["id"])

    # Get coach receipts
    coach_receipts = await db.coach_compensations.find({}).to_list(1000)
    for r in coach_receipts:
        if _sid and r.get("coach_id") not in society_user_ids:
            continue
        user = await db.users.find_one({"id": r.get("coach_id")})
        if user:
            created_by_name = await get_admin_name(r.get("created_by"))
            updated_by_name = await get_admin_name(r.get("updated_by"))
            all_receipts.append({
                "id": str(r.get("_id")),
                "user_id": r.get("coach_id"),
                "user_name": user.get("full_name", "N/A"),
                "user_role": "coach",
                "phone": user.get("phone", "") or user.get("phone_number", ""),
                "payment_made": r.get("payment_made", False),
                "payment_made_date": r.get("payment_made_date"),
                "month": r.get("month"),
                "year": r.get("year"),
                "amount_gross": r.get("amount_gross", r.get("amount", 0)),
                "standard_amount": user.get("monthly_compensation", 0),
                "is_custom": r.get("amount_gross", r.get("amount", 0)) != user.get("monthly_compensation", 0),
                "receipt_signed": r.get("receipt_signed", False),
                "receipt_signed_date": r.get("receipt_signed_date"),
                "exceeded_5000": r.get("exceeded_5000", False),
                "exceeded_15000": r.get("exceeded_15000", False),
                "created_by": r.get("created_by"),
                "created_by_name": created_by_name,
                "created_at": r.get("created_at"),
                "updated_by": r.get("updated_by"),
                "updated_by_name": updated_by_name,
                "updated_at": r.get("updated_at"),
            })
    
    # Get dirigente receipts
    dirigente_receipts = await db.dirigente_compensations.find({}).to_list(1000)
    for r in dirigente_receipts:
        if _sid and r.get("dirigente_id") not in society_user_ids:
            continue
        user = await db.users.find_one({"id": r.get("dirigente_id")})
        if user:
            created_by_name = await get_admin_name(r.get("created_by"))
            updated_by_name = await get_admin_name(r.get("updated_by"))
            all_receipts.append({
                "id": str(r.get("_id")),
                "user_id": r.get("dirigente_id"),
                "user_name": user.get("full_name", "N/A"),
                "user_role": "dirigente",
                "phone": user.get("phone", "") or user.get("phone_number", ""),
                "payment_made": r.get("payment_made", False),
                "payment_made_date": r.get("payment_made_date"),
                "month": r.get("month"),
                "year": r.get("year"),
                "amount_gross": r.get("amount_gross", r.get("amount", 0)),
                "standard_amount": user.get("monthly_compensation", 0),
                "is_custom": r.get("amount_gross", r.get("amount", 0)) != user.get("monthly_compensation", 0),
                "receipt_signed": r.get("receipt_signed", False),
                "receipt_signed_date": r.get("receipt_signed_date"),
                "exceeded_5000": r.get("exceeded_5000", False),
                "exceeded_15000": r.get("exceeded_15000", False),
                "created_by": r.get("created_by"),
                "created_by_name": created_by_name,
                "created_at": r.get("created_at"),
                "updated_by": r.get("updated_by"),
                "updated_by_name": updated_by_name,
                "updated_at": r.get("updated_at"),
            })
    
    # Get collaboratore receipts
    collaboratore_receipts = await db.collaboratore_compensations.find({}).to_list(1000)
    for r in collaboratore_receipts:
        if _sid and r.get("collaboratore_id") not in society_user_ids:
            continue
        user = await db.users.find_one({"id": r.get("collaboratore_id")})
        if user:
            created_by_name = await get_admin_name(r.get("created_by"))
            updated_by_name = await get_admin_name(r.get("updated_by"))
            all_receipts.append({
                "id": str(r.get("_id")),
                "user_id": r.get("collaboratore_id"),
                "user_name": user.get("full_name", "N/A"),
                "user_role": "collaboratore",
                "phone": user.get("phone", "") or user.get("phone_number", ""),
                "payment_made": r.get("payment_made", False),
                "payment_made_date": r.get("payment_made_date"),
                "month": r.get("month"),
                "year": r.get("year"),
                "amount_gross": r.get("amount_gross", r.get("amount", 0)),
                "standard_amount": user.get("monthly_compensation", 0),
                "is_custom": r.get("amount_gross", r.get("amount", 0)) != user.get("monthly_compensation", 0),
                "receipt_signed": r.get("receipt_signed", False),
                "receipt_signed_date": r.get("receipt_signed_date"),
                "exceeded_5000": r.get("exceeded_5000", False),
                "exceeded_15000": r.get("exceeded_15000", False),
                "created_by": r.get("created_by"),
                "created_by_name": created_by_name,
                "created_at": r.get("created_at"),
                "updated_by": r.get("updated_by"),
                "updated_by_name": updated_by_name,
                "updated_at": r.get("updated_at"),
            })

    # 🆕 28/06/2026 — Get athlete receipts (atleti compensated 18+ PRO)
    athlete_receipts = await db.athlete_compensation_receipts.find({}).to_list(1000)
    for r in athlete_receipts:
        # Multi-tenant filter: athletes belong to a society via athletes.society_id
        athlete = await db.athletes.find_one({"id": r.get("athlete_id")})
        if not athlete:
            continue
        if _sid and athlete.get("society_id") != _sid:
            continue
        created_by_name = await get_admin_name(r.get("created_by"))
        updated_by_name = await get_admin_name(r.get("updated_by"))
        amt = r.get("amount_gross", r.get("amount", 0))
        std = athlete.get("monthly_compensation", 0)
        all_receipts.append({
            "id": str(r.get("_id")),
            "user_id": r.get("athlete_id"),
            "user_name": athlete.get("full_name", "N/A"),
            "user_role": "athlete",
            "phone": athlete.get("phone_athlete") or athlete.get("phone") or "",
            "payment_made": r.get("payment_made", False),
            "payment_made_date": r.get("payment_made_date"),
            "month": r.get("month"),
            "year": r.get("year"),
            "amount_gross": amt,
            "standard_amount": std,
            "is_custom": amt != std,
            "receipt_signed": r.get("receipt_signed", False),
            "receipt_signed_date": r.get("receipt_signed_date"),
            "exceeded_5000": r.get("exceeded_5000", False),
            "exceeded_15000": r.get("exceeded_15000", False),
            "created_by": r.get("created_by"),
            "created_by_name": created_by_name,
            "created_at": r.get("created_at"),
            "updated_by": r.get("updated_by"),
            "updated_by_name": updated_by_name,
            "updated_at": r.get("updated_at"),
        })

    # Sort by year desc, month desc
    all_receipts.sort(key=lambda x: (x["year"], x["month"]), reverse=True)
    
    return {
        "receipts": all_receipts,
        "total": len(all_receipts),
        "pending": len([r for r in all_receipts if not r["receipt_signed"]]),
        "custom_pending": len([r for r in all_receipts if r["is_custom"] and not r["receipt_signed"]]),
        "custom_signed": len([r for r in all_receipts if r["is_custom"] and r["receipt_signed"]])
    }


# ─────────────────────────────────────────────────────────────────────────
# 🆕 FASE 1 Quietanze — "Bonifico effettuato" + avviso firma destinatario
# ─────────────────────────────────────────────────────────────────────────
ROLE_RECEIPT_MAP = {
    "coach": ("coach_compensations", "coach_id"),
    "dirigente": ("dirigente_compensations", "dirigente_id"),
    "collaboratore": ("collaboratore_compensations", "collaboratore_id"),
    "athlete": ("athlete_compensation_receipts", "athlete_id"),
}


@api_router.post("/admin/quietanze/mark-payment")
async def admin_mark_quietanza_payment(data: dict = Body(...), current_user = Depends(get_current_user)):
    """Segna (o annulla) il BONIFICO su una singola quietanza. Imposta payment_made
    così il destinatario riceve l'avviso di firmare."""
    if current_user.get("role") != "admin":
        raise HTTPException(status_code=403, detail="Solo admin")
    role = data.get("user_role")
    uid = data.get("user_id")
    if role not in ROLE_RECEIPT_MAP or not uid:
        raise HTTPException(status_code=400, detail="Dati non validi")
    year = int(data.get("year")); month = int(data.get("month"))
    paid = bool(data.get("paid", True))
    coll, idf = ROLE_RECEIPT_MAP[role]
    now = datetime.now(timezone.utc).isoformat()
    upd = {"payment_made": paid, "payment_made_date": now if paid else None, "payment_made_by": current_user["id"]}
    res = await db[coll].update_one({idf: uid, "year": year, "month": month}, {"$set": upd})
    if res.matched_count == 0:
        raise HTTPException(status_code=404, detail="Quietanza non trovata")
    return {"ok": True, "payment_made": paid}


@api_router.post("/admin/quietanze/mark-payment-bulk")
async def admin_mark_quietanza_payment_bulk(data: dict = Body(...), current_user = Depends(get_current_user)):
    """Segna il BONIFICO in blocco per tutte le quietanze di un mese/anno (opzionale
    filtro per ruolo). Di default solo quelle non ancora firmate. Isolato per società."""
    if current_user.get("role") != "admin":
        raise HTTPException(status_code=403, detail="Solo admin")
    year = int(data.get("year")); month = int(data.get("month"))
    only_role = data.get("user_role")
    only_unsigned = bool(data.get("only_unsigned", True))
    _sid = current_user.get("society_id")
    society_user_ids = set()
    _uq = {"society_id": _sid} if _sid else {}
    async for u in db.users.find(_uq, {"_id": 0, "id": 1}):
        if u.get("id"):
            society_user_ids.add(u["id"])
    now = datetime.now(timezone.utc).isoformat()
    count = 0
    roles = [only_role] if only_role in ROLE_RECEIPT_MAP else list(ROLE_RECEIPT_MAP.keys())
    for role in roles:
        coll, idf = ROLE_RECEIPT_MAP[role]
        q = {"year": year, "month": month}
        if only_unsigned:
            q["receipt_signed"] = {"$ne": True}
        async for r in db[coll].find(q):
            owner = r.get(idf)
            if role == "athlete":
                ath = await db.athletes.find_one({"id": owner}, {"_id": 0, "society_id": 1})
                if _sid and (not ath or ath.get("society_id") != _sid):
                    continue
            else:
                if _sid and owner not in society_user_ids:
                    continue
            await db[coll].update_one(
                {"_id": r["_id"]},
                {"$set": {"payment_made": True, "payment_made_date": now, "payment_made_by": current_user["id"]}},
            )
            count += 1
    return {"ok": True, "updated": count, "year": year, "month": month}


@api_router.get("/me/receipts/pending-signature")
async def my_pending_signature_receipts(current_user = Depends(get_current_user)):
    """Quietanze con bonifico effettuato ma NON ancora firmate dall'utente corrente.
    Alimenta l'avviso 'Firma la quietanza di [mese]' nella home del destinatario."""
    role = current_user.get("role")
    MONTHS = ["", "Gennaio", "Febbraio", "Marzo", "Aprile", "Maggio", "Giugno",
              "Luglio", "Agosto", "Settembre", "Ottobre", "Novembre", "Dicembre"]
    targets = []
    if role in ("coach", "dirigente", "collaboratore"):
        coll, idf = ROLE_RECEIPT_MAP[role]
        targets.append((coll, idf, current_user.get("id")))
    aid = current_user.get("athlete_id")
    if aid:
        targets.append(("athlete_compensation_receipts", "athlete_id", aid))
    out = []
    for coll, idf, owner in targets:
        if not owner:
            continue
        async for r in db[coll].find({idf: owner, "payment_made": True, "receipt_signed": {"$ne": True}}):
            m = r.get("month") or 0
            out.append({
                "role": idf.replace("_id", ""),
                "year": r.get("year"),
                "month": m,
                "month_name": MONTHS[m] if 0 < m < 13 else str(m),
                "amount": r.get("amount_gross", r.get("amount", 0)),
            })
    out.sort(key=lambda x: (x.get("year") or 0, x.get("month") or 0), reverse=True)
    return out



@api_router.post("/admin/dirigente/{dirigente_id}/compensation/create-receipt")
async def admin_create_dirigente_receipt(
    dirigente_id: str,
    request: AdminCreateReceiptRequest,
    current_user = Depends(get_current_user)
):
    """Admin crea una quietanza per un dirigente con importo personalizzato"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo l'admin può creare quietanze")
    
    dirigente = await db.users.find_one({"id": dirigente_id})
    if not dirigente:
        raise HTTPException(status_code=404, detail="Dirigente non trovato")
    
    existing = await db.dirigente_compensations.find_one({
        "dirigente_id": dirigente_id,
        "year": request.year,
        "month": request.month
    })
    
    if existing:
        await db.dirigente_compensations.update_one(
            {"dirigente_id": dirigente_id, "year": request.year, "month": request.month},
            {"$set": {
                "amount_gross": request.amount_gross,
                "amount": request.amount_gross,
                "amount_net": request.amount_gross,
                "updated_at": datetime.now(timezone.utc).isoformat(),
                "updated_by": current_user["id"]
            }}
        )
        return {"message": f"Quietanza aggiornata: {request.month}/{request.year} - €{request.amount_gross}", "updated": True}
    else:
        receipt_id = str(uuid.uuid4())[:8]
        new_receipt = {
            "id": receipt_id,
            "dirigente_id": dirigente_id,
            "year": request.year,
            "month": request.month,
            "amount_gross": request.amount_gross,
            "amount": request.amount_gross,
            "amount_net": request.amount_gross,
            "received": True,
            "receipt_signed": False,
            "created_at": datetime.now(timezone.utc).isoformat(),
            "created_by": current_user["id"]
        }
        await db.dirigente_compensations.insert_one(new_receipt)
        return {"message": f"Quietanza creata: {request.month}/{request.year} - €{request.amount_gross}", "created": True, "id": receipt_id}

