# ─────── Auto-dichiarazione compensi esterni (altre ASD/SSD) ───────
# Tracciamento INCREMENTALE auto-dichiarato per il calcolo cumulativo annuo
# delle soglie 5K/15K (criterio per CASSA, non per competenza).
# Ogni record rappresenta una dichiarazione fatta dall'utente in un dato
# momento (es. al momento della firma di una quietanza) per l'incremento di
# compensi sportivi percepiti da ALTRE ASD/SSD dall'ultima dichiarazione.

class ExternalCompensationDeclaration(BaseModel):
    id: str = Field(default_factory=lambda: str(ObjectId()))
    user_id: str
    year: int
    amount: float = 0.0  # importo incrementale dichiarato
    declared_none: bool = False  # se l'utente dichiara esplicitamente "0"
    declared_at: datetime = Field(default_factory=datetime.utcnow)
    # collegamento opzionale alla quietanza per cui è stata dichiarata
    related_receipt_id: Optional[str] = None
    related_receipt_month: Optional[int] = None
    # società che riceveva la dichiarazione (multi-tenancy)
    society_id: Optional[str] = None


async def _get_year_external_compensations_total(user_id: str, year: int) -> float:
    """Somma cumulativa degli importi dichiarati dall'utente per compensi
    ricevuti da ALTRE ASD/SSD nell'anno indicato."""
    try:
        total = 0.0
        async for d in db.external_compensations.find(
            {"user_id": user_id, "year": year,
             "is_previous_season": {"$ne": True}},
            {"_id": 0, "amount": 1},
        ):
            total += float(d.get("amount") or 0)
        return round(total, 2)
    except Exception as ex:
        logger.warning(f"_get_year_external_compensations_total failed for {user_id}/{year}: {ex}")
        return 0.0


async def _get_year_external_by_month(user_id: str, year: int) -> Dict[int, float]:
    """🆕 14/06/2026 — Esterni distribuiti per mese (in base a `related_receipt_month`).
    Gli esterni senza mese vengono ignorati: il calendario li aggregherà solo quando
    saranno legati a una quietanza (mese chiarito)."""
    res: Dict[int, float] = {}
    try:
        async for d in db.external_compensations.find(
            {"user_id": user_id, "year": year,
             "is_previous_season": {"$ne": True}},
            {"_id": 0, "amount": 1, "related_receipt_month": 1},
        ):
            m = d.get("related_receipt_month")
            if m and isinstance(m, int) and 1 <= m <= 12:
                res[m] = round(res.get(m, 0.0) + float(d.get("amount") or 0), 2)
    except Exception as ex:
        logger.warning(f"_get_year_external_by_month failed for {user_id}/{year}: {ex}")
    return res


async def _find_linked_athlete_pro_for_user(user_id: str) -> Optional[dict]:
    """Cerca un record `athletes` con is_compensated=True che condivide
    identità (user_id, linked_user_id, email o fiscal_code) con l'utente
    indicato, NELLA STESSA società. Usato per soglie cumulative Coach+Atleta PRO.
    Ritorna il documento athlete o None.
    """
    try:
        user = await db.users.find_one(
            {"id": user_id},
            {"_id": 0, "id": 1, "email": 1, "fiscal_code": 1, "society_id": 1},
        )
        if not user:
            return None
        society_id = user.get("society_id")
        or_clauses = [{"user_id": user_id}, {"linked_user_id": user_id}]
        if user.get("email"):
            or_clauses.append({"email": user["email"].lower()})
        if user.get("fiscal_code"):
            or_clauses.append({"fiscal_code": user["fiscal_code"].upper()})
            or_clauses.append({"fiscal_code": user["fiscal_code"]})
        query = {"is_compensated": True, "$or": or_clauses}
        if society_id:
            query["society_id"] = society_id
        return await db.athletes.find_one(query)
    except Exception as ex:
        logger.warning(f"_find_linked_athlete_pro_for_user failed for {user_id}: {ex}")
        return None


async def _find_linked_compensated_user_for_athlete(athlete: dict) -> Optional[dict]:
    """Cerca un user record (role coach/dirigente/collaboratore/admin) che
    condivide identità con l'atleta PRO indicato (email/fiscal_code) NELLA
    STESSA società e che ha `is_compensated=True` o `monthly_compensation>0`.
    Ritorna il documento user o None.
    """
    try:
        society_id = athlete.get("society_id")
        or_clauses = []
        # Direct link from athlete record
        for k in ("linked_user_id", "user_id"):
            if athlete.get(k):
                or_clauses.append({"id": athlete[k]})
        if athlete.get("email"):
            or_clauses.append({"email": athlete["email"].lower()})
        if athlete.get("fiscal_code"):
            or_clauses.append({"fiscal_code": athlete["fiscal_code"].upper()})
            or_clauses.append({"fiscal_code": athlete["fiscal_code"]})
        # 🆕 13/06/2026 — Fallback: nome+cognome (case-insensitive) per società
        # quando il record athletes non ha CF/email allineati col record user
        if athlete.get("first_name") and athlete.get("last_name"):
            import re as _re
            fn_pattern = f"^{_re.escape(athlete['first_name'].strip())}$"
            ln_pattern = f"^{_re.escape(athlete['last_name'].strip())}$"
            or_clauses.append({
                "first_name": {"$regex": fn_pattern, "$options": "i"},
                "last_name": {"$regex": ln_pattern, "$options": "i"},
            })
        if not or_clauses:
            return None
        query = {
            "role": {"$in": ["coach", "dirigente", "collaboratore", "admin"]},
            "$or": or_clauses,
        }
        if society_id:
            query["society_id"] = society_id
        # Prefer users that actually have compensation set
        candidates = await db.users.find(query).to_list(5)
        if not candidates:
            return None
        for c in candidates:
            if c.get("is_compensated") or (c.get("monthly_compensation") or 0) > 0:
                return c
        return candidates[0]
    except Exception as ex:
        logger.warning(f"_find_linked_compensated_user_for_athlete failed: {ex}")
        return None


async def _get_signed_yearly_total_as_coach(coach_user_id: str, year: int, payment_shift: int = 0) -> float:
    """Somma compensi firmati come Coach/Dirigente/Collaboratore (coach_compensations) per l'anno.
    Con payment_shift=1 la competenza di dicembre è incassata a gennaio dell'anno dopo."""
    try:
        if payment_shift == 1:
            q = {"coach_id": coach_user_id, "receipt_signed": True,
                 "$or": [{"year": year, "month": {"$ne": 12}}, {"year": year - 1, "month": 12}]}
        else:
            q = {"coach_id": coach_user_id, "year": year, "receipt_signed": True}
        total = 0.0
        async for r in db.coach_compensations.find(
            q, {"_id": 0, "amount_gross": 1, "amount": 1},
        ):
            total += float(r.get("amount_gross") or r.get("amount") or 0)
        return round(total, 2)
    except Exception as ex:
        logger.warning(f"_get_signed_yearly_total_as_coach failed for {coach_user_id}/{year}: {ex}")
        return 0.0


async def _get_signed_yearly_total_as_atleta_pro(athlete_id: str, year: int, payment_shift: int = 0) -> float:
    """Somma compensi firmati come Atleta PRO (atleta_pro_compensations) per l'anno.
    Con payment_shift=1 (cassa = mese successivo) la competenza di dicembre viene
    incassata a gennaio e conta nell'anno solare successivo."""
    try:
        if payment_shift == 1:
            q = {"atleta_id": athlete_id, "receipt_signed": True,
                 "$or": [{"year": year, "month": {"$ne": 12}}, {"year": year - 1, "month": 12}]}
        else:
            q = {"atleta_id": athlete_id, "year": year, "receipt_signed": True}
        total = 0.0
        async for r in db.atleta_pro_compensations.find(
            q, {"_id": 0, "amount_gross": 1, "amount": 1},
        ):
            total += float(r.get("amount_gross") or r.get("amount") or 0)
        return round(total, 2)
    except Exception as ex:
        logger.warning(f"_get_signed_yearly_total_as_atleta_pro failed for {athlete_id}/{year}: {ex}")
        return 0.0


def _parse_contract_year_month(value):
    """Estrae (year, month) da una data contratto (str ISO/datetime). Ritorna (None, None) se non parsabile."""
    if not value:
        return None, None
    if isinstance(value, str):
        parts = value.split("T")[0].split("-")
        if len(parts) >= 2:
            try:
                return int(parts[0]), int(parts[1])
            except (ValueError, TypeError):
                return None, None
    if hasattr(value, "year") and hasattr(value, "month"):
        return value.year, value.month
    return None, None


async def _check_chronological_receipts(
    user_id: str,
    target_year: int,
    target_month: int,
    contract_start_value,
    contract_end_value,
    collection_name: str = "coach_compensations",
    user_id_field: str = "coach_id",
):
    """🆕 22/06/2026 — Enforcement cronologico server-side per le quietanze.

    Verifica che TUTTI i mesi del periodo contrattuale precedenti a (target_year,
    target_month) siano già firmati. Se ne trova uno scoperto, solleva HTTPException 400.

    Args:
        user_id: id dell'utente firmatario
        target_year/target_month: mese che si sta firmando
        contract_start_value/contract_end_value: date contratto (str ISO o datetime)
        collection_name: collezione mongo da interrogare (default coach_compensations)
        user_id_field: campo della collezione che contiene l'id utente
    """
    cs_year, cs_month = _parse_contract_year_month(contract_start_value)
    ce_year, ce_month = _parse_contract_year_month(contract_end_value)
    if not (cs_year and cs_month):
        return  # nessun contratto noto -> nessun enforcement
    end_y = ce_year if ce_year else target_year
    end_m = ce_month if ce_month else 12

    # Carichiamo solo i mesi firmati relativi al periodo del contratto, in modo
    # da poter verificare velocemente quale mese precedente al target manca.
    coll = getattr(db, collection_name)
    cursor = coll.find(
        {user_id_field: user_id, "receipt_signed": True},
        {"_id": 0, "month": 1, "year": 1},
    )
    docs = await cursor.to_list(500)
    signed_set = {(int(d["year"]), int(d["month"])) for d in docs if d.get("year") and d.get("month")}

    ITA_MONTHS = ['', 'Gennaio', 'Febbraio', 'Marzo', 'Aprile', 'Maggio', 'Giugno',
                  'Luglio', 'Agosto', 'Settembre', 'Ottobre', 'Novembre', 'Dicembre']
    for y in range(cs_year, end_y + 1):
        m_start = cs_month if y == cs_year else 1
        m_end = end_m if y == end_y else 12
        for m in range(m_start, m_end + 1):
            if (y, m) == (target_year, target_month):
                return  # raggiunto il mese target, tutti i precedenti sono firmati
            if (y, m) not in signed_set:
                mname = ITA_MONTHS[m] if 1 <= m <= 12 else str(m)
                raise HTTPException(
                    status_code=400,
                    detail=f"Ordine cronologico richiesto: firma prima la quietanza di {mname} {y}."
                )
    # Se siamo arrivati qui senza incontrare target, target è fuori contratto: lasciamo passare.


# ============================================================
# 🆕 Contributi INPS Gestione Separata — Riforma Sport (D.Lgs 36/2021)
# Trattenuta della quota a carico del lavoratore (1/3) sulla sola parte di
# compenso che, in cumulo annuo (per cassa), eccede la franchigia di €5.000.
# Valori standard 2026 (circ. INPS n.8/2026), tutti configurabili.
#   - IVS 25% calcolata sul 50% dell'eccedenza (riduzione transitoria fino 31/12/2027)
#   - +2,03% sull'intera eccedenza (solo lavoratori NON iscritti ad altra previdenza)
#   - ripartizione 2/3 committente, 1/3 lavoratore → trattenuta ≈ 4,84% dell'eccedenza
# ============================================================
INPS_FRANCHIGIA = 5000.0
INPS_IVS_RATE_DEFAULT = 0.25      # lavoratori NON iscritti ad altra previdenza
INPS_IVS_RATE_INSURED = 0.24      # lavoratori già iscritti ad altra previdenza obbligatoria
INPS_MINOR_RATE = 0.0203          # aliquote minori (solo NON iscritti altrove)
INPS_IVS_REDUCTION = 0.50         # riduzione 50% base IVS (transitoria fino 31/12/2027)
INPS_WORKER_SHARE = 1.0 / 3.0     # quota a carico del lavoratore


def compute_sport_inps_withholding(
    yearly_total_before_gross: float,
    payment_gross: float,
    insured_elsewhere: bool = False,
    cfg: Optional[dict] = None,
) -> dict:
    """Calcola la trattenuta INPS (quota lavoratore 1/3) per una singola erogazione.

    `yearly_total_before_gross` = totale LORDO già maturato nell'anno PRIMA di questo
    compenso (quietanze firmate + pregresso + compensi esterni dichiarati).
    `payment_gross` = compenso lordo pattuito di questa erogazione.

    Ritorna un dict con lordo, eccedenza oltre €5.000, contributi e netto corrisposto.
    Se l'eccedenza è nulla (ancora sotto la franchigia) → netto = lordo (applies=False).
    """
    cfg = cfg or {}
    franchigia = float(cfg.get("franchigia", INPS_FRANCHIGIA))
    ivs_reduction = float(cfg.get("ivs_reduction", INPS_IVS_REDUCTION))
    worker_share = float(cfg.get("worker_share", INPS_WORKER_SHARE))
    if insured_elsewhere:
        ivs_rate = float(cfg.get("ivs_rate_insured", INPS_IVS_RATE_INSURED))
        minor_rate = 0.0
    else:
        ivs_rate = float(cfg.get("ivs_rate", INPS_IVS_RATE_DEFAULT))
        minor_rate = float(cfg.get("minor_rate", INPS_MINOR_RATE))

    before = max(0.0, float(yearly_total_before_gross or 0.0))
    gross = max(0.0, float(payment_gross or 0.0))
    after = before + gross
    # Parte di QUESTO compenso che eccede la franchigia cumulativamente
    excess = max(0.0, after - franchigia) - max(0.0, before - franchigia)
    excess = round(min(max(0.0, excess), gross), 2)

    if excess <= 0:
        return {
            "applies": False,
            "amount_gross": round(gross, 2),
            "excess_over_5000": 0.0,
            "ivs_base": 0.0,
            "ivs_rate": ivs_rate,
            "minor_rate": minor_rate,
            "inps_total": 0.0,
            "inps_worker": 0.0,
            "inps_employer": 0.0,
            "amount_net": round(gross, 2),
            "insured_elsewhere": insured_elsewhere,
        }

    ivs_base = excess * ivs_reduction
    ivs_contribution = ivs_base * ivs_rate
    minor_contribution = excess * minor_rate
    inps_total = ivs_contribution + minor_contribution
    inps_worker = round(inps_total * worker_share, 2)
    inps_employer = round(inps_total - inps_worker, 2)
    amount_net = round(gross - inps_worker, 2)
    return {
        "applies": True,
        "amount_gross": round(gross, 2),
        "excess_over_5000": round(excess, 2),
        "ivs_base": round(ivs_base, 2),
        "ivs_rate": ivs_rate,
        "ivs_contribution": round(ivs_contribution, 2),
        "minor_rate": minor_rate,
        "minor_contribution": round(minor_contribution, 2),
        "inps_total": round(inps_total, 2),
        "inps_worker": inps_worker,
        "inps_employer": inps_employer,
        "amount_net": amount_net,
        "insured_elsewhere": insured_elsewhere,
    }



def _detect_threshold_crossings_chronological(
    signed_by_month: dict,
    new_month: int,
    new_amount: float,
    prior_compensation: float = 0.0,
    external_total: float = 0.0,
):
    """
    Calcola in quale mese cronologico (1..12) il cumulativo annuo attraversa la soglia
    €5.000 e €15.000, considerando TUTTI i mesi firmati (anche quelli successivi al mese
    che si sta firmando ora) per gestire correttamente le firme retroattive fuori ordine.

    Args:
        signed_by_month: dict {mese -> importo già firmato per quel mese, ESCLUSO new_month}
        new_month: mese (1..12) che si sta firmando ora
        new_amount: importo della firma corrente
        prior_compensation: compenso pregresso dichiarato (contato come gennaio, proxy)
        external_total: totale compensi esterni anno (contato come gennaio, proxy)

    Returns:
        tuple (month_5k, month_15k): mese cronologico in cui si è superata ciascuna soglia,
        oppure None se non superata.
    """
    monthly = {m: float(signed_by_month.get(m, 0) or 0) for m in range(1, 13)}
    monthly[new_month] = monthly.get(new_month, 0) + float(new_amount or 0)
    # Prior compensation ed external: imputati a gennaio (sono "ricevuti" prima del primo mese sportivo)
    monthly[1] = monthly.get(1, 0) + float(prior_compensation or 0) + float(external_total or 0)

    cumulative = 0.0
    month_5k = None
    month_15k = None
    for m in range(1, 13):
        prev = cumulative
        cumulative += monthly[m]
        if month_5k is None and cumulative > 5000 and prev <= 5000:
            month_5k = m
        if month_15k is None and cumulative > 15000 and prev <= 15000:
            month_15k = m
    return (month_5k, month_15k)


# ╭──────────────────────────────────────────────────────────────╮
# │  🆕 13/06/2026 — RIEPILOGO COMPENSI UNIFICATO (Fase 2)       │
# │  Regola dei QUARTILI SETTIMANALI per mesi parziali           │
# ╰──────────────────────────────────────────────────────────────╯

def _parse_contract_date(value) -> Optional[date]:
    """Normalizza data contratto (str ISO o datetime) in datetime.date.
    Ritorna None se non parsabile o vuoto."""
    if not value:
        return None
    try:
        if isinstance(value, date) and not isinstance(value, datetime):
            return value
        if isinstance(value, datetime):
            return value.date()
        s = str(value).strip()
        if not s:
            return None
        # Tronca al solo prefisso YYYY-MM-DD
        s = s[:10]
        return datetime.fromisoformat(s).date()
    except Exception:
        return None


def _calculate_proportional_amount_quartile(
    contract_start: Optional[date],
    contract_end: Optional[date],
    monthly_amount: float,
    year: int,
    month: int,
) -> tuple:
    """🆕 13/06/2026 — Regola dei QUARTILI SETTIMANALI per il calcolo del
    compenso proporzionale in un mese parziale di contratto.

    Divide il mese in 4 "quartili" (settimane simboliche). I giorni di
    sovrapposizione tra il contratto e il mese determinano quale quartile
    applicare:
        - 4 settimane (mese pieno) → 100% del compenso
        - 3 settimane → 75%
        - 2 settimane → 50%
        - 1 settimana → 25%

    Formula: quartile = round(days_worked / (days_in_month / 4)), clamped 1..4

    Esempi (ottobre 31gg):
        - 08/10 → 31/10 (24gg): 24/7.75 ≈ 3.1 → 3 → 75% (€225 se monthly=€300)
        - 26/10 → 31/10 (6gg): 6/7.75 ≈ 0.77 → 1 → 25% (€75 se monthly=€300)

    Returns: (importo_arrotondato, quartile_0_to_4)
        - quartile=0 se il contratto NON copre nemmeno un giorno del mese
    """
    try:
        amount = float(monthly_amount or 0)
    except (TypeError, ValueError):
        return 0.0, 0
    if amount <= 0 or contract_start is None:
        return 0.0, 0

    # Range del mese richiesto
    try:
        month_start = date(year, month, 1)
    except ValueError:
        return 0.0, 0
    if month == 12:
        month_end = date(year, 12, 31)
    else:
        month_end = date(year, month + 1, 1) - timedelta(days=1)

    # Intersezione contratto ↔ mese
    effective_start = max(month_start, contract_start)
    effective_end = month_end if contract_end is None else min(month_end, contract_end)

    if effective_end < effective_start:
        return 0.0, 0

    days_worked = (effective_end - effective_start).days + 1
    days_in_month = (month_end - month_start).days + 1  # 28/29/30/31

    if days_worked >= days_in_month:
        quartile = 4
    else:
        week_size = days_in_month / 4.0
        quartile = round(days_worked / week_size) if week_size > 0 else 0
        quartile = max(1, min(4, quartile))

    proportional = amount * quartile / 4.0
    return round(proportional, 2), quartile


def _calculate_ras_total(
    contract_start: Optional[date],
    contract_end: Optional[date],
    monthly_amount: float,
) -> dict:
    """Totale "Comunicazione RAS" = somma di TUTTI i compensi proporzionali
    su tutti i mesi coperti dal contratto (regola quartili).
    Ritorna {total, breakdown} per consentire dettaglio mese-per-mese in UI.
    Se contract_end è None, il RAS non è calcolabile → total=0."""
    if not contract_start or not contract_end or not monthly_amount or monthly_amount <= 0:
        return {"total": 0.0, "breakdown": []}
    if contract_end < contract_start:
        return {"total": 0.0, "breakdown": []}
    total = 0.0
    breakdown = []
    cur = date(contract_start.year, contract_start.month, 1)
    end_marker = date(contract_end.year, contract_end.month, 1)
    while cur <= end_marker:
        amount, quartile = _calculate_proportional_amount_quartile(
            contract_start, contract_end, monthly_amount, cur.year, cur.month,
        )
        breakdown.append({"year": cur.year, "month": cur.month, "amount": amount, "quartile": quartile})
        total += amount
        if cur.month == 12:
            cur = date(cur.year + 1, 1, 1)
        else:
            cur = date(cur.year, cur.month + 1, 1)
    return {"total": round(total, 2), "breakdown": breakdown}


def _calculate_fiscal_year_total(
    contract_start: Optional[date],
    contract_end: Optional[date],
    monthly_amount: float,
    year: int,
    payment_shift: int = 0,
) -> dict:
    """Totale anno solare = somma compensi proporzionali nei 12 mesi dell'anno
    (regola quartili). Ritorna anche breakdown per mese.

    🆕 payment_shift: criterio di cassa.
        0 = i compensi sono incassati nel mese di competenza (default).
        1 = i compensi sono incassati il mese SUCCESSIVO: l'importo che cade nel
            mese di pagamento `p` dell'anno solare corrisponde alla competenza del
            mese `p-1` (e gennaio raccoglie la competenza di dicembre dell'anno prima).
            Effetto netto: la competenza di dicembre slitta all'anno solare successivo.
    """
    breakdown = []
    total = 0.0
    for p in range(1, 13):  # p = mese di PAGAMENTO nell'anno solare `year`
        if payment_shift == 1:
            comp_year = year if p > 1 else year - 1
            comp_month = p - 1 if p > 1 else 12
        else:
            comp_year, comp_month = year, p
        amount, quartile = _calculate_proportional_amount_quartile(
            contract_start, contract_end, monthly_amount, comp_year, comp_month,
        )
        breakdown.append({"month": p, "amount": amount, "quartile": quartile})
        total += amount
    return {"total": round(total, 2), "breakdown": breakdown}


async def _get_payment_timing(society_id: Optional[str]) -> str:
    """🆕 Legge il criterio di cassa della società per le soglie compensi.
    Ritorna "same_month" (default) o "next_month"."""
    try:
        q = {"type": "society", "society_id": society_id} if society_id else {"type": "society"}
        ss = await db.settings.find_one(q, {"_id": 0, "compensation_payment_timing": 1})
        return (ss or {}).get("compensation_payment_timing") or "same_month"
    except Exception:
        return "same_month"


def _payment_shift_from_timing(timing: Optional[str]) -> int:
    return 1 if timing == "next_month" else 0


def _rebucket_month_year_for_payment(month: int, year: int, payment_shift: int) -> tuple:
    """🆕 Dato un record di COMPETENZA (month, year), ritorna (payment_month, payment_year)
    secondo il criterio di cassa. Con payment_shift=1 la competenza di dicembre
    diventa gennaio dell'anno successivo."""
    if payment_shift != 1:
        return month, year
    if month >= 12:
        return 1, year + 1
    return month + 1, year



@api_router.get("/admin/persons/{user_id}/profile")
async def admin_person_profile(
    user_id: str,
    current_user = Depends(get_current_user),
):
    """🆕 13/06/2026 — Hub Persona: ritorna anagrafica unificata + status dual-role.
    Risolve sia user_id (coach/dirigente) sia athlete_id."""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")

    user = await db.users.find_one({"id": user_id}, {"_id": 0})
    athlete = None
    if user:
        athlete_id_from_user = user.get("athlete_id") or user.get("athlete_record_id")
        if athlete_id_from_user:
            athlete = await db.athletes.find_one({"id": athlete_id_from_user}, {"_id": 0})
        if not athlete:
            athlete = await _find_linked_athlete_pro_for_user(user["id"])
    else:
        athlete = await db.athletes.find_one({"id": user_id}, {"_id": 0})
        if athlete:
            user = await _find_linked_compensated_user_for_athlete(athlete)

    if not user and not athlete:
        raise HTTPException(status_code=404, detail="Persona non trovata")

    society_id = (user or {}).get("society_id") or (athlete or {}).get("society_id")
    if current_user.get("society_id") and society_id and current_user["society_id"] != society_id:
        raise HTTPException(status_code=403, detail="Persona di altra società")

    has_athlete_role = bool(athlete)
    has_coach_role = bool(user and user.get("role") in ("coach", "dirigente", "collaboratore", "admin")
                          and (float(user.get("monthly_compensation") or 0) > 0 or user.get("contract_start_date")))
    is_dual_role = has_athlete_role and has_coach_role

    def _safe(d, *keys):
        for k in keys:
            v = (d or {}).get(k)
            if v not in (None, ""):
                return v
        return None

    profile = {
        "first_name": _safe(user, "first_name") or _safe(athlete, "first_name") or "",
        "last_name": _safe(user, "last_name") or _safe(athlete, "last_name") or "",
        "fiscal_code": _safe(user, "fiscal_code") or _safe(athlete, "fiscal_code") or "",
        "email": _safe(user, "email") or _safe(athlete, "email") or "",
        "phone": _safe(user, "phone") or _safe(athlete, "phone") or "",
        "birth_date": _safe(user, "birth_date") or _safe(athlete, "birth_date"),
        "birth_place": _safe(user, "birth_place") or _safe(athlete, "birth_place"),
        "address": _safe(user, "address") or _safe(athlete, "address"),
        "city": _safe(user, "city") or _safe(athlete, "city"),
        "province": _safe(user, "province") or _safe(athlete, "province"),
        "postal_code": _safe(user, "postal_code") or _safe(athlete, "postal_code"),
        "photo_url": _safe(user, "photo_url") or _safe(athlete, "photo_url"),
        "qr_identifier": _safe(athlete, "qr_identifier") or _safe(user, "qr_identifier"),
    }

    return {
        "user_id": user["id"] if user else None,
        "athlete_id": athlete["id"] if athlete else None,
        "society_id": society_id,
        "is_dual_role": is_dual_role,
        "has_athlete_role": has_athlete_role,
        "has_coach_role": has_coach_role,
        "coach_role_name": (user or {}).get("role") if has_coach_role else None,
        "profile": profile,
    }



@api_router.get("/admin/persons/{user_id}/compensation-summary")
async def admin_person_compensation_summary(
    user_id: str,
    year: Optional[int] = None,
    current_user = Depends(get_current_user),
):
    """🆕 13/06/2026 — RIEPILOGO COMPENSI UNIFICATO per persona dual-role.

    Restituisce 3 sezioni:
    - **ras_summary**: totale "Comunicazione RAS" (intero contratto sommando
       Coach + Atleta PRO se dual-role) con regola dei quartili.
    - **fiscal_year_current**: anno fiscale richiesto (default = anno corrente)
       con quartili + compensi esterni + pregresso (solo se è il primo anno).
    - **fiscal_year_next**: anno fiscale Y+1, stesso schema (senza pregresso).

    Risolve sia user_id atleta che user_id coach: cerca automaticamente il
    record collegato dell'altra entità (dual-role) tramite CF/email/society.
    """
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")

    # Determina la persona partendo da user_id (può essere user.id o athlete.id)
    user = await db.users.find_one({"id": user_id})
    athlete = None
    if user:
        athlete_id_from_user = user.get("athlete_id") or user.get("athlete_record_id")
        if athlete_id_from_user:
            athlete = await db.athletes.find_one({"id": athlete_id_from_user})
        if not athlete:
            athlete = await _find_linked_athlete_pro_for_user(user["id"])
    else:
        # Tenta come athlete.id
        athlete = await db.athletes.find_one({"id": user_id})
        if athlete:
            user = await _find_linked_compensated_user_for_athlete(athlete)

    if not user and not athlete:
        raise HTTPException(status_code=404, detail="Persona non trovata")

    # Multi-tenant check
    society_id = (user or {}).get("society_id") or (athlete or {}).get("society_id")
    if current_user.get("society_id") and society_id and \
            current_user["society_id"] != society_id:
        raise HTTPException(status_code=403, detail="Persona appartiene a un'altra società")

    # Anno corrente default
    if year is None:
        year = datetime.now(timezone.utc).year
    year_next = year + 1
    # 🆕 Criterio di cassa società (slittamento dicembre)
    _shift = _payment_shift_from_timing(await _get_payment_timing(society_id))

    # === Estrai dati Coach (da users) ===
    coach_section = None
    coach_first_year = None
    coach_prior = 0.0
    if user and user.get("role") in ("coach", "dirigente", "collaboratore", "admin"):
        c_start = _parse_contract_date(user.get("contract_start_date"))
        c_end = _parse_contract_date(user.get("contract_end_date"))
        c_monthly = float(user.get("monthly_compensation") or 0)
        if c_monthly > 0 or c_start:
            coach_prior = float(user.get("other_annual_compensation") or 0)
            ras_data = _calculate_ras_total(c_start, c_end, c_monthly)
            coach_section = {
                "role": user.get("role", "coach"),
                "contract_start": c_start.isoformat() if c_start else None,
                "contract_end": c_end.isoformat() if c_end else None,
                "monthly_amount": c_monthly,
                "ras_total": ras_data["total"],
                "ras_breakdown": ras_data["breakdown"],
                "ras_calculable": bool(c_start and c_end),
                "fiscal_year": _calculate_fiscal_year_total(c_start, c_end, c_monthly, year, _shift),
                "fiscal_year_next": _calculate_fiscal_year_total(c_start, c_end, c_monthly, year_next, _shift),
            }
            if c_start:
                coach_first_year = c_start.year

    # === Estrai dati Atleta PRO (da athletes) ===
    athlete_section = None
    athlete_first_year = None
    athlete_prior = 0.0
    if athlete and (athlete.get("is_compensated") or float(athlete.get("monthly_compensation") or 0) > 0):
        a_start = _parse_contract_date(athlete.get("contract_start_date"))
        a_end = _parse_contract_date(athlete.get("contract_end_date"))
        a_monthly = float(athlete.get("monthly_compensation") or 0)
        athlete_prior = float(athlete.get("other_annual_compensation") or 0)
        ras_data_a = _calculate_ras_total(a_start, a_end, a_monthly)
        athlete_section = {
            "role": "athlete",
            "contract_start": a_start.isoformat() if a_start else None,
            "contract_end": a_end.isoformat() if a_end else None,
            "monthly_amount": a_monthly,
            "ras_total": ras_data_a["total"],
            "ras_breakdown": ras_data_a["breakdown"],
            "ras_calculable": bool(a_start and a_end),
            "fiscal_year": _calculate_fiscal_year_total(a_start, a_end, a_monthly, year, _shift),
            "fiscal_year_next": _calculate_fiscal_year_total(a_start, a_end, a_monthly, year_next, _shift),
        }
        if a_start:
            athlete_first_year = a_start.year

    if not coach_section and not athlete_section:
        # Nessun rapporto compensato attivo — risposta vuota ma valida
        return {
            "user_id": user["id"] if user else None,
            "athlete_id": athlete["id"] if athlete else None,
            "person_name": ((user or {}).get("first_name") or "") + " " + ((user or {}).get("last_name") or "") if user else (((athlete or {}).get("first_name") or "") + " " + ((athlete or {}).get("last_name") or "")),
            "year": year,
            "year_next": year_next,
            "is_dual_role": False,
            "has_compensation": False,
            "ras_summary": None,
            "fiscal_year_current": None,
            "fiscal_year_next": None,
        }

    is_dual_role = bool(coach_section and athlete_section)

    # === Pregresso UNIFICATO per persona ===
    # Solo il valore non-zero (preferendo athlete se entrambi presenti per evitare doppio
    # conteggio: cfr. PRD "campo unico per persona, no migrazione retroattiva").
    # Se entrambi non-zero, sommiamo (l'admin ha esplicitamente dichiarato 2 valori).
    if coach_prior > 0 and athlete_prior > 0:
        unified_prior = round(coach_prior + athlete_prior, 2)
    else:
        unified_prior = round(max(coach_prior, athlete_prior), 2)

    # === Primo anno fiscale (per imputazione del pregresso) ===
    first_year_candidates = [y for y in (coach_first_year, athlete_first_year) if y is not None]
    earliest_first_year = min(first_year_candidates) if first_year_candidates else None

    # === Supplementari = compensi esterni (per CASSA) ===
    external_user_id = user["id"] if user else (athlete or {}).get("user_id") or (athlete or {}).get("linked_user_id")
    external_athlete_id = athlete["id"] if athlete else None

    async def _sum_external(year_target: int) -> float:
        total = 0.0
        if external_user_id:
            total += await _get_year_external_compensations_total(external_user_id, year_target)
        if external_athlete_id and external_athlete_id != external_user_id:
            total += await _get_year_external_compensations_total(external_athlete_id, year_target)
        return round(total, 2)

    external_current = await _sum_external(year)
    external_next = await _sum_external(year_next)

    # 🆕 14/06/2026 — Esterni distribuiti per mese (per cumulo cronologico corretto)
    async def _sum_external_by_month(year_target: int) -> Dict[int, float]:
        merged: Dict[int, float] = {}
        if external_user_id:
            for m, a in (await _get_year_external_by_month(external_user_id, year_target)).items():
                merged[m] = round(merged.get(m, 0.0) + a, 2)
        if external_athlete_id and external_athlete_id != external_user_id:
            for m, a in (await _get_year_external_by_month(external_athlete_id, year_target)).items():
                merged[m] = round(merged.get(m, 0.0) + a, 2)
        return merged

    external_by_month_current = await _sum_external_by_month(year)
    external_by_month_next = await _sum_external_by_month(year_next)

    # === RAS SUMMARY ===
    ras_coach_total = coach_section["ras_total"] if coach_section else 0.0
    ras_athlete_total = athlete_section["ras_total"] if athlete_section else 0.0
    ras_supplementary = 0.0  # esterni NON inclusi nella RAS (RAS = solo contratto societario)
    ras_grand_total = round(ras_coach_total + ras_athlete_total + ras_supplementary, 2)
    ras_calculable = (
        (coach_section is None or coach_section["ras_calculable"]) and
        (athlete_section is None or athlete_section["ras_calculable"])
    )

    # === FISCAL YEAR (corrente) ===
    fy_coach = coach_section["fiscal_year"]["total"] if coach_section else 0.0
    fy_athlete = athlete_section["fiscal_year"]["total"] if athlete_section else 0.0
    is_first_year_current = (earliest_first_year is not None and year == earliest_first_year)
    prior_current = unified_prior if is_first_year_current else 0.0
    fy_current_total = round(fy_coach + fy_athlete + external_current + prior_current, 2)

    # === FISCAL YEAR (successivo) ===
    fy_coach_next = coach_section["fiscal_year_next"]["total"] if coach_section else 0.0
    fy_athlete_next = athlete_section["fiscal_year_next"]["total"] if athlete_section else 0.0
    is_first_year_next = (earliest_first_year is not None and year_next == earliest_first_year)
    prior_next = unified_prior if is_first_year_next else 0.0
    fy_next_total = round(fy_coach_next + fy_athlete_next + external_next + prior_next, 2)

    # === 🆕 14/06/2026 (v3) — Mese di superamento soglie €5K/€15K ===
    # Logica corretta: il cumulato CRONOLOGICO scatta dal PRIMO mese attivo del contratto
    # nell'anno fiscale considerato. Gli esterni si sommano nel MESE in cui sono stati
    # dichiarati (related_receipt_month). Il pregresso si aggiunge al primo mese attivo
    # SOLO nel primo anno fiscale del contratto.
    def _month_breaches(year_target: int, prior_amount: float, external_by_month: Dict[int, float]) -> dict:
        coach_bd = (coach_section["fiscal_year"]["breakdown"] if coach_section and year_target == year
                    else coach_section["fiscal_year_next"]["breakdown"] if coach_section and year_target == year_next
                    else [])
        athlete_bd = (athlete_section["fiscal_year"]["breakdown"] if athlete_section and year_target == year
                      else athlete_section["fiscal_year_next"]["breakdown"] if athlete_section and year_target == year_next
                      else [])
        coach_by_month = {b["month"]: b["amount"] for b in coach_bd if b.get("amount", 0) > 0}
        athlete_by_month = {b["month"]: b["amount"] for b in athlete_bd if b.get("amount", 0) > 0}
        # Primo mese attivo (Coach o Atleta hanno compensi > 0 in quell'anno)
        active_months = sorted(set(coach_by_month.keys()) | set(athlete_by_month.keys()))
        first_active = active_months[0] if active_months else None
        if first_active is None:
            return {"month_exceed_5k": None, "month_exceed_15k": None}
        exceed_5k = None
        exceed_15k = None
        cum = 0.0
        for m in range(first_active, 13):
            month_amount = coach_by_month.get(m, 0) + athlete_by_month.get(m, 0) + (external_by_month.get(m, 0) or 0)
            if m == first_active:
                cum = round(cum + prior_amount + month_amount, 2)
            else:
                cum = round(cum + month_amount, 2)
            if exceed_5k is None and cum > 5000:
                exceed_5k = m
            if exceed_15k is None and cum > 15000:
                exceed_15k = m
                break
        return {"month_exceed_5k": exceed_5k, "month_exceed_15k": exceed_15k}

    breaches_current = _month_breaches(year, prior_current, external_by_month_current)
    breaches_next = _month_breaches(year_next, prior_next, external_by_month_next)

    person_name = ((user or {}).get("first_name") or (athlete or {}).get("first_name") or "") + " " + \
                  ((user or {}).get("last_name") or (athlete or {}).get("last_name") or "")

    return {
        "user_id": user["id"] if user else None,
        "athlete_id": athlete["id"] if athlete else None,
        "person_name": person_name.strip(),
        "year": year,
        "year_next": year_next,
        "is_dual_role": is_dual_role,
        "has_compensation": True,
        "unified_prior_compensation": unified_prior,
        "earliest_first_year": earliest_first_year,
        "ras_summary": {
            "coach_total": ras_coach_total,
            "athlete_total": ras_athlete_total,
            "supplementary": ras_supplementary,
            "grand_total": ras_grand_total,
            "ras_calculable": ras_calculable,
        },
        "fiscal_year_current": {
            "year": year,
            "coach_total": fy_coach,
            "athlete_total": fy_athlete,
            "supplementary": external_current,
            "supplementary_by_month": external_by_month_current,
            "prior_compensation": prior_current,
            "is_first_year": is_first_year_current,
            "grand_total": fy_current_total,
            "exceeds_5k": fy_current_total > 5000,
            "exceeds_15k": fy_current_total > 15000,
            "month_exceed_5k": breaches_current["month_exceed_5k"],
            "month_exceed_15k": breaches_current["month_exceed_15k"],
        },
        "fiscal_year_next": {
            "year": year_next,
            "coach_total": fy_coach_next,
            "athlete_total": fy_athlete_next,
            "supplementary": external_next,
            "supplementary_by_month": external_by_month_next,
            "prior_compensation": prior_next,
            "is_first_year": is_first_year_next,
            "grand_total": fy_next_total,
            "exceeds_5k": fy_next_total > 5000,
            "exceeds_15k": fy_next_total > 15000,
            "month_exceed_5k": breaches_next["month_exceed_5k"],
            "month_exceed_15k": breaches_next["month_exceed_15k"],
        },
        "coach_section": coach_section,
        "athlete_section": athlete_section,
    }




# ╭──────────────────────────────────────────────────────────────╮
# │  🆕 FASE 2B — Promozione Atleta PRO a Coach (dual-role)     │
# ╰──────────────────────────────────────────────────────────────╯
class PromoteAthleteToCoachRequest(BaseModel):
    # 🆕 email/password ora OPZIONALI: l'atleta usa SOLO la sua email atleta per il
    # login; il coach viene creato con email interna alias (es. "alice.z@test.com#coach")
    # mai usata per autenticarsi. Lo switch dal frontend usa SwitchAccountButton.
    coach_email: Optional[str] = None  # legacy: se fornita, deve essere diversa dall'atleta
    coach_password: Optional[str] = None  # legacy
    team_id: str
    monthly_compensation: float = 0.0
    coach_level: Optional[str] = None
    contract_start_date: Optional[str] = None
    contract_end_date: Optional[str] = None


@api_router.get("/auth/linked-accounts")
async def get_linked_accounts(current_user = Depends(get_current_user)):
    """🆕 Switch dual-role: ritorna gli account collegati al user corrente
    (atleta ↔ coach). Usato dal frontend per mostrare il bottone "Passa a Modalità X".
    """
    user_id = current_user["id"]
    role = current_user.get("role")
    linked = []

    if role == "athlete" and current_user.get("athlete_id"):
        # Cerca un coach collegato all'atleta (via promote-to-coach o stesso CF/email)
        athlete = await db.athletes.find_one(
            {"id": current_user["athlete_id"]},
            {"_id": 0, "id": 1, "email": 1, "fiscal_code": 1, "society_id": 1},
        )
        if athlete:
            coach = await _find_linked_compensated_user_for_athlete(athlete)
            if coach and coach.get("id") != user_id:
                linked.append({
                    "user_id": coach["id"],
                    "role": coach.get("role", "coach"),
                    "email": coach.get("email", ""),
                    "label": f"Modalità {(coach.get('role') or 'coach').capitalize()}",
                })
    elif role in ("coach", "dirigente", "collaboratore"):
        # Cerca un atleta PRO collegato (via fiscal_code o linked_athlete_id)
        user_full = await db.users.find_one(
            {"id": user_id},
            {"_id": 0, "id": 1, "email": 1, "fiscal_code": 1, "society_id": 1, "linked_athlete_id": 1},
        )
        if user_full:
            ath = None
            if user_full.get("linked_athlete_id"):
                ath = await db.athletes.find_one({"id": user_full["linked_athlete_id"]})
            if not ath:
                ath = await _find_linked_athlete_pro_for_user(user_id)
            if ath:
                # Trova il user associato all'atleta
                ath_user = await db.users.find_one(
                    {"athlete_id": ath["id"], "role": "athlete"},
                    {"_id": 0, "id": 1, "email": 1, "athlete_id": 1},
                )
                if ath_user and ath_user.get("id") != user_id:
                    linked.append({
                        "user_id": ath_user["id"],
                        "role": "athlete",
                        "email": ath_user.get("email", ""),
                        "label": "Modalità Atleta",
                    })
    # 🆕 24/08/2026 — Dual-role Genitore ↔ Dirigente (promozione parent→dirigente)
    if role == "parent":
        _pu = await db.users.find_one({"id": user_id}, {"_id": 0, "linked_dirigente_user_id": 1})
        _ldid = (_pu or {}).get("linked_dirigente_user_id")
        if _ldid:
            _dir = await db.users.find_one({"id": _ldid}, {"_id": 0, "id": 1, "email": 1, "role": 1})
            if _dir and _dir.get("id") != user_id:
                linked.append({
                    "user_id": _dir["id"],
                    "role": _dir.get("role", "dirigente"),
                    "email": _dir.get("email", ""),
                    "label": "Modalità Dirigente",
                })
    # 🆕 Dual-role Coordinatore ↔ Dirigente (compenso assegnato al coordinatore)
    if role == "coordinatore":
        _cu = await db.users.find_one({"id": user_id}, {"_id": 0, "linked_dirigente_user_id": 1})
        _ldid = (_cu or {}).get("linked_dirigente_user_id")
        if _ldid:
            _dir = await db.users.find_one({"id": _ldid}, {"_id": 0, "id": 1, "email": 1, "role": 1})
            if _dir and _dir.get("id") != user_id:
                linked.append({
                    "user_id": _dir["id"],
                    "role": _dir.get("role", "dirigente"),
                    "email": _dir.get("email", ""),
                    "label": "Modalità Dirigente",
                })
    if role in ("dirigente", "viewer"):
        _du = await db.users.find_one({"id": user_id}, {"_id": 0, "linked_parent_user_id": 1, "linked_coordinatore_user_id": 1})
        _lcid = (_du or {}).get("linked_coordinatore_user_id")
        if _lcid:
            _coord = await db.users.find_one({"id": _lcid}, {"_id": 0, "id": 1, "email": 1})
            if _coord and _coord.get("id") != user_id:
                linked.append({
                    "user_id": _coord["id"],
                    "role": "coordinatore",
                    "email": _coord.get("email", ""),
                    "label": "Modalità Coordinatore",
                })
        _lpid = (_du or {}).get("linked_parent_user_id")
        if _lpid:
            _par = await db.users.find_one({"id": _lpid}, {"_id": 0, "id": 1, "email": 1})
            if _par and _par.get("id") != user_id:
                linked.append({
                    "user_id": _par["id"],
                    "role": "parent",
                    "email": _par.get("email", ""),
                    "label": "Modalità Genitore",
                })
    return {"current_role": role, "linked_accounts": linked}


@api_router.get("/auth/me/dual-role-info")
async def get_dual_role_info(current_user = Depends(get_current_user)):
    """🆕 16/06/2026 — Restituisce le info necessarie per i 2 banner in `/athlete/compensation`:
    - athlete: team_name + monthly_compensation + contract_start_date + contract_end_date
    - coach (se dual-role): team_name + monthly_compensation + contract_start_date + contract_end_date
    """
    user_id = current_user["id"]
    role = current_user.get("role")
    sid = current_user.get("society_id")

    async def _team_names_for_athlete(athlete_doc):
        team_ids = athlete_doc.get("team_ids") or []
        if not team_ids and athlete_doc.get("team_id"):
            team_ids = [athlete_doc["team_id"]]
        if not team_ids:
            return ""
        names = []
        async for t in db.teams.find({"id": {"$in": team_ids}}, {"_id": 0, "name": 1}):
            if t.get("name"):
                names.append(t["name"])
        return " / ".join(names) if names else ""

    async def _team_names_for_coach(coach_user):
        team_ids = coach_user.get("assigned_teams") or []
        if not team_ids:
            return ""
        names = []
        async for t in db.teams.find({"id": {"$in": team_ids}}, {"_id": 0, "name": 1}):
            if t.get("name"):
                names.append(t["name"])
        return " / ".join(names) if names else ""

    athlete_info = None
    coach_info = None

    # Info Atleta (se current user è atleta)
    if role == "athlete" and current_user.get("athlete_id"):
        ath = await db.athletes.find_one(
            {"id": current_user["athlete_id"]},
            {"_id": 0},
        )
        if ath:
            athlete_info = {
                "team_name": await _team_names_for_athlete(ath),
                "monthly_compensation": ath.get("monthly_compensation") or current_user.get("monthly_compensation") or 0,
                "contract_start_date": ath.get("contract_start_date") or current_user.get("contract_start_date"),
                "contract_end_date": ath.get("contract_end_date") or current_user.get("contract_end_date"),
            }
        # Info Coach collegato (se dual-role)
        coach_user = await _find_linked_compensated_user_for_athlete(ath) if ath else None
        if coach_user and coach_user.get("id") != user_id:
            coach_info = {
                "team_name": await _team_names_for_coach(coach_user),
                "monthly_compensation": coach_user.get("monthly_compensation") or 0,
                "contract_start_date": coach_user.get("contract_start_date"),
                "contract_end_date": coach_user.get("contract_end_date"),
            }

    # Info Coach (se current user è coach)
    elif role in ("coach", "dirigente", "collaboratore"):
        coach_user = await db.users.find_one({"id": user_id}, {"_id": 0})
        if coach_user:
            coach_info = {
                "team_name": await _team_names_for_coach(coach_user),
                "monthly_compensation": coach_user.get("monthly_compensation") or 0,
                "contract_start_date": coach_user.get("contract_start_date"),
                "contract_end_date": coach_user.get("contract_end_date"),
            }
        # Info Atleta collegato (se dual-role)
        ath = await _find_linked_athlete_pro_for_user(user_id)
        if ath:
            athlete_info = {
                "team_name": await _team_names_for_athlete(ath),
                "monthly_compensation": ath.get("monthly_compensation") or 0,
                "contract_start_date": ath.get("contract_start_date"),
                "contract_end_date": ath.get("contract_end_date"),
            }

    return {
        "current_role": role,
        "is_dual_role": bool(athlete_info and coach_info),
        "athlete": athlete_info,
        "coach": coach_info,
    }


@api_router.post("/auth/switch-account")
async def switch_to_linked_account(data: dict, current_user = Depends(get_current_user)):
    """🆕 Genera un nuovo JWT per uno degli account collegati al user corrente
    (atleta ↔ coach). Validazione: l'account target deve essere collegato (CF / linked fields).
    """
    target_user_id = (data or {}).get("target_user_id")
    if not target_user_id:
        raise HTTPException(status_code=400, detail="target_user_id richiesto")
    if target_user_id == current_user["id"]:
        raise HTTPException(status_code=400, detail="Sei già su questo account")

    # Verifica che il target sia effettivamente collegato
    accounts = await get_linked_accounts(current_user)  # type: ignore
    allowed = {a["user_id"] for a in accounts.get("linked_accounts", [])}
    if target_user_id not in allowed:
        raise HTTPException(status_code=403, detail="Account non collegato al tuo profilo")

    target = await db.users.find_one({"id": target_user_id})
    if not target:
        raise HTTPException(status_code=404, detail="Account collegato non trovato")

    # Stessa società (sicurezza ulteriore)
    if target.get("society_id") != current_user.get("society_id"):
        raise HTTPException(status_code=403, detail="Account in società diversa")

    new_token = create_token(
        target["id"],
        target.get("role", "athlete"),
        athlete_id=target.get("athlete_id"),
    )
    logging.info(
        f"[SWITCH-ACCOUNT] User {current_user['id']} ({current_user.get('role')}) "
        f"→ {target['id']} ({target.get('role')})"
    )
    return {"token": new_token, "role": target.get("role"), "user_id": target["id"]}


@api_router.post("/admin/parents/{parent_user_id}/promote-to-dirigente")
async def promote_parent_to_dirigente(parent_user_id: str, current_user = Depends(get_current_user)):
    """🆕 24/08/2026 — PROPONE il ruolo DIRIGENTE a un GENITORE esistente,
    mantenendo lo stesso login (dual-role genitore↔dirigente). Crea un account
    dirigente collegato IN ATTESA DI ACCETTAZIONE (`link_status='pending'`).
    Il collegamento diventa attivo (e compare "Passa a Modalità Dirigente") SOLO
    dopo che il genitore ACCETTA l'incarico dalla propria dashboard.
    Rispecchia la promozione Atleta→Coach ma con accettazione dell'interessato."""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo gli admin possono promuovere un genitore a dirigente")

    parent = await db.users.find_one({"id": parent_user_id})
    if not parent:
        raise HTTPException(status_code=404, detail="Genitore non trovato")
    if parent.get("role") != "parent":
        raise HTTPException(status_code=400, detail="L'utente selezionato non è un genitore")
    if parent.get("society_id") != current_user.get("society_id"):
        raise HTTPException(status_code=403, detail="Il genitore appartiene a un'altra società")

    # Già promosso e accettato?
    if parent.get("linked_dirigente_user_id"):
        existing = await db.users.find_one({"id": parent["linked_dirigente_user_id"]})
        if existing and existing.get("link_status") != "pending":
            raise HTTPException(status_code=400, detail="Questo genitore è già anche Dirigente")

    # Proposta già inviata e in attesa di accettazione?
    pending_alias = await db.users.find_one(
        {"linked_parent_user_id": parent_user_id, "role": {"$in": ["dirigente", "viewer"]}, "link_status": "pending"}
    )
    if pending_alias:
        return {
            "message": "Proposta già inviata: in attesa che il genitore accetti l'incarico di Dirigente.",
            "dirigente_user_id": pending_alias["id"],
            "status": "pending",
        }
    active_alias = await db.users.find_one(
        {"linked_parent_user_id": parent_user_id, "role": {"$in": ["dirigente", "viewer"]}, "link_status": {"$ne": "pending"}}
    )
    if active_alias:
        await db.users.update_one({"id": parent_user_id}, {"$set": {"linked_dirigente_user_id": active_alias["id"]}})
        return {"message": "Genitore già dirigente (collegamento ripristinato).", "dirigente_user_id": active_alias["id"], "status": "active"}

    parent_email = (parent.get("email") or "").lower().strip()
    if not parent_email:
        raise HTTPException(status_code=400, detail="Genitore senza email — impossibile creare l'account dirigente collegato")

    dirigente_user_id = str(uuid.uuid4()).replace("-", "")[:24]
    dir_doc = {
        "id": dirigente_user_id,
        "email": f"{parent_email}#dirigente",  # alias interno (login sempre con l'email reale del genitore)
        "role": "dirigente",
        "full_name": parent.get("full_name", ""),
        "first_name": parent.get("first_name", ""),
        "last_name": parent.get("last_name", ""),
        "fiscal_code": parent.get("fiscal_code", ""),
        "date_of_birth": parent.get("date_of_birth"),
        "place_of_birth": parent.get("place_of_birth"),
        "country_of_birth": parent.get("country_of_birth"),
        "gender": parent.get("gender"),
        "address": parent.get("address"),
        "city": parent.get("city"),
        "postal_code": parent.get("postal_code"),
        "province": parent.get("province"),
        "phone": parent.get("phone"),
        "society_id": parent.get("society_id"),
        "status": "approved",
        "link_status": "pending",  # diventa "active" quando il genitore accetta
        "password_hash": hash_password(uuid.uuid4().hex),  # random, mai usata (login via switch)
        "linked_parent_user_id": parent_user_id,
        "promoted_from_parent_id": parent_user_id,
        "promoted_at": datetime.utcnow(),
        "promoted_by": current_user["id"],
        "promoted_by_name": current_user.get("full_name", "Amministrazione"),
        "created_at": datetime.utcnow(),
        "privacy_accepted": False,
    }
    await db.users.insert_one(dir_doc)
    # NB: NON impostiamo `linked_dirigente_user_id` finché il genitore non accetta.
    await db.users.update_one({"id": parent_user_id}, {"$set": {"pending_dirigente_user_id": dirigente_user_id}})
    invalidate_auth_cache(parent_user_id)

    logging.info(f"[PROMOTE-DIRIGENTE] Proposta incarico Dirigente al genitore {parent_user_id} (alias={dirigente_user_id}) da admin {current_user['id']}")
    return {
        "message": "Proposta inviata al genitore. Dovrà accettare l'incarico di Dirigente dalla propria dashboard.",
        "dirigente_user_id": dirigente_user_id,
        "status": "pending",
    }


@api_router.get("/parent/dirigente-proposal")
async def get_parent_dirigente_proposal(current_user = Depends(get_current_user)):
    """🆕 Ritorna la proposta di incarico Dirigente in attesa per il genitore loggato."""
    if current_user.get("role") != "parent":
        return {"pending": False}
    pid = current_user.get("pending_dirigente_user_id")
    if not pid:
        return {"pending": False}
    dir_doc = await db.users.find_one(
        {"id": pid, "link_status": "pending"},
        {"_id": 0, "id": 1, "promoted_by_name": 1, "promoted_at": 1},
    )
    if not dir_doc:
        return {"pending": False}
    return {
        "pending": True,
        "dirigente_user_id": dir_doc["id"],
        "proposed_by_name": dir_doc.get("promoted_by_name", "Amministrazione"),
        "proposed_at": dir_doc.get("promoted_at"),
    }


@api_router.post("/parent/dirigente-proposal/accept")
async def accept_parent_dirigente_proposal(current_user = Depends(get_current_user)):
    """🆕 Il genitore ACCETTA l'incarico di Dirigente: attiva il collegamento
    dual-role. Da questo momento vedrà "Passa a Modalità Dirigente"."""
    if current_user.get("role") != "parent":
        raise HTTPException(status_code=403, detail="Solo un genitore può accettare l'incarico")
    pid = current_user.get("pending_dirigente_user_id")
    if not pid:
        raise HTTPException(status_code=404, detail="Nessuna proposta di incarico in attesa")
    dir_doc = await db.users.find_one({"id": pid})
    if not dir_doc or dir_doc.get("link_status") != "pending":
        # Pulizia difensiva
        await db.users.update_one({"id": current_user["id"]}, {"$unset": {"pending_dirigente_user_id": ""}})
        raise HTTPException(status_code=404, detail="Proposta non più valida")
    now = datetime.utcnow()
    await db.users.update_one(
        {"id": pid},
        {"$set": {"link_status": "active", "accepted_at": now}},
    )
    await db.users.update_one(
        {"id": current_user["id"]},
        {"$set": {"linked_dirigente_user_id": pid}, "$unset": {"pending_dirigente_user_id": ""}},
    )
    invalidate_auth_cache(current_user["id"])
    logging.info(f"[PROMOTE-DIRIGENTE] Genitore {current_user['id']} HA ACCETTATO l'incarico Dirigente (alias={pid})")
    return {"message": "Hai accettato l'incarico di Dirigente. Ora puoi passare alla Modalità Dirigente.", "dirigente_user_id": pid}


@api_router.post("/parent/dirigente-proposal/reject")
async def reject_parent_dirigente_proposal(current_user = Depends(get_current_user)):
    """🆕 Il genitore RIFIUTA l'incarico di Dirigente: elimina l'account collegato in attesa."""
    if current_user.get("role") != "parent":
        raise HTTPException(status_code=403, detail="Solo un genitore può rifiutare l'incarico")
    pid = current_user.get("pending_dirigente_user_id")
    if not pid:
        raise HTTPException(status_code=404, detail="Nessuna proposta di incarico in attesa")
    dir_doc = await db.users.find_one({"id": pid})
    if dir_doc and dir_doc.get("link_status") == "pending":
        await db.users.delete_one({"id": pid})
    await db.users.update_one({"id": current_user["id"]}, {"$unset": {"pending_dirigente_user_id": ""}})
    invalidate_auth_cache(current_user["id"])
    logging.info(f"[PROMOTE-DIRIGENTE] Genitore {current_user['id']} HA RIFIUTATO l'incarico Dirigente (alias={pid})")
    return {"message": "Hai rifiutato l'incarico di Dirigente."}


@api_router.post("/admin/athletes/{athlete_id}/promote-to-coach")
async def promote_athlete_to_coach(
    athlete_id: str,
    request: PromoteAthleteToCoachRequest,
    current_user = Depends(get_current_user),
):
    """🆕 FASE 2B — Crea un account Coach collegato a un Atleta PRO esistente.
    Il match per le soglie cumulative avviene automaticamente via codice fiscale
    e società comune (vedi `_find_linked_athlete_pro_for_user`)."""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo gli admin possono promuovere atleti a coach")
    
    # Atleta deve esistere ed essere PRO/compensated
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    if not athlete.get("is_compensated"):
        raise HTTPException(
            status_code=400,
            detail="Solo gli Atleti PRO (compensated) possono essere promossi a Coach. Imposta prima il tipo come 'Pro / Compensato'.",
        )
    
    athlete_email = (athlete.get("email") or "").lower().strip()
    if not athlete_email:
        raise HTTPException(status_code=400, detail="Atleta senza email — impossibile creare account coach collegato")

    # 🆕 26/06/2026 — Step A "Email di login unica":
    # Il dual-role DEVE sempre usare l'email dell'atleta come unico login.
    # L'admin NON può più assegnare un'email diversa al coach: ignoriamo
    # silenziosamente request.coach_email per evitare disallineamenti
    # ("L'utenza è sempre quella originale, in più ha solo lo zaino di Coach").
    # L'email del record coach è un alias interno con suffisso #coach (non usato per login).
    coach_email = f"{athlete_email}#coach"
    is_alias = True
    # Verifica che non ci sia già un coach collegato a questo atleta
    existing_alias = await db.users.find_one({"linked_athlete_id": athlete_id, "role": "coach"})
    if existing_alias:
        raise HTTPException(status_code=400, detail="Atleta già promosso a Coach")
    
    # Password: solo se l'admin ha fornito una password "vera" (account separato).
    # Altrimenti generiamo una random — non sarà mai usata per il login.
    if request.coach_password:
        if len(request.coach_password) < 6:
            raise HTTPException(status_code=400, detail="La password deve avere almeno 6 caratteri")
        password_to_hash = request.coach_password
    else:
        password_to_hash = uuid.uuid4().hex  # random, mai usata per login esterno
    
    # Validazione team
    team = await db.teams.find_one({"id": request.team_id, "society_id": athlete.get("society_id")})
    if not team:
        raise HTTPException(status_code=404, detail="Squadra non trovata nella società")
    
    # Validazione CF (necessario per il match cumulativo)
    fiscal_code = (athlete.get("fiscal_code") or "").upper().strip()
    if not fiscal_code:
        raise HTTPException(
            status_code=400,
            detail="L'atleta non ha il codice fiscale impostato. Il CF è necessario per collegare i due ruoli ai fini delle soglie cumulative.",
        )
    
    # Date contratto (default = oggi → 30 giugno prossimo)
    today = datetime.utcnow().date()
    contract_start = request.contract_start_date or today.isoformat()
    if request.contract_end_date:
        contract_end = request.contract_end_date
    else:
        end_year = today.year if today.month < 7 else today.year + 1
        contract_end = f"{end_year}-06-30"
    
    # Crea l'account coach
    coach_user_id = str(uuid.uuid4()).replace("-", "")[:24]
    pwd_hash = hash_password(password_to_hash)
    coach_doc = {
        "id": coach_user_id,
        "email": coach_email,
        "role": "coach",
        "full_name": athlete.get("full_name", ""),
        "first_name": athlete.get("first_name", ""),
        "last_name": athlete.get("last_name", ""),
        "fiscal_code": fiscal_code,
        "date_of_birth": athlete.get("date_of_birth"),
        "place_of_birth": athlete.get("place_of_birth"),
        "country_of_birth": athlete.get("country_of_birth"),
        "gender": athlete.get("gender") or athlete.get("sesso") or None,
        "address": athlete.get("address"),
        "city": athlete.get("city"),
        "postal_code": athlete.get("postal_code"),
        "province": athlete.get("province"),
        "phone": athlete.get("phone"),
        # 🆕 Copy-over dati bancari dall'atleta (saranno comunque modificabili dal coach nel suo profilo)
        "iban": athlete.get("iban", ""),
        "iban_holder_first_name": athlete.get("iban_holder_first_name") or athlete.get("first_name", ""),
        "iban_holder_last_name": athlete.get("iban_holder_last_name") or athlete.get("last_name", ""),
        "bank_name": athlete.get("bank_name", ""),
        "society_id": athlete.get("society_id"),
        "status": "approved",
        "password_hash": pwd_hash,
        "monthly_compensation": float(request.monthly_compensation or 0),
        "is_compensated": True,
        # 🐛 FIX: il frontend coach/profile.tsx legge `coach_license_level`,
        # NON `coach_level`. Salviamo ENTRAMBI per retro-compat.
        "coach_license_level": request.coach_level or "",
        "coach_level": request.coach_level or "",
        "assigned_teams": [request.team_id],
        "contract_start_date": contract_start,
        "contract_end_date": contract_end,
        # 🔗 Link esplicito all'atleta PRO collegato (audit / future use)
        "linked_athlete_id": athlete_id,
        "promoted_from_athlete_id": athlete_id,
        "promoted_at": datetime.utcnow(),
        "promoted_by": current_user["id"],
        "created_at": datetime.utcnow(),
        "privacy_accepted": False,
    }
    await db.users.insert_one(coach_doc)
    
    # Audit log
    logging.info(
        f"[PROMOTE-COACH] Atleta {athlete_id} promosso a Coach (user_id={coach_user_id}, "
        f"team={request.team_id}, monthly={request.monthly_compensation}€) da admin {current_user['id']}"
    )
    
    return {
        "message": "Atleta promosso a Coach con successo. Soglie cumulative attive automaticamente.",
        "coach_user_id": coach_user_id,
        "coach_email": coach_email,
        "team_id": request.team_id,
        "monthly_compensation": request.monthly_compensation,
        "linked_athlete_id": athlete_id,
    }


@api_router.post("/admin/migrate-legacy-coach-emails")
async def migrate_legacy_coach_emails(current_user = Depends(get_current_user)):
    """🆕 16/06/2026 — Migra account coach legacy con email del formato `<localpart>.coach@<domain>`
    (creati prima di Email Unica Dual-Role) in alias `<email_atleta>#coach`.

    Effetti:
    - Trova tutti i coach con email che NON è già un alias (#coach)
    - Per ognuno cerca l'atleta collegato via `linked_athlete_id` o CF condiviso
    - Se l'email coach è del formato `.coach@` (legacy), la sostituisce con alias `<email_atleta>#coach`
    - L'utente conserva storico, ma da quel momento NON potrà più loggare con quell'email coach
    """
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo gli admin possono eseguire la migrazione")

    migrated = []
    skipped = []
    errors = []

    async for coach in db.users.find({"role": "coach"}, {"_id": 0}):
        coach_email = (coach.get("email") or "").strip().lower()
        if not coach_email or "#" in coach_email:
            continue  # già alias o vuoto

        # Detecta pattern legacy ".coach@" oppure "_coach@"
        is_legacy = ".coach@" in coach_email or "_coach@" in coach_email or coach_email.endswith(".coach")
        if not is_legacy:
            skipped.append({"coach_id": coach.get("id"), "email": coach_email, "reason": "non legacy"})
            continue

        # Trova l'atleta collegato
        athlete = None
        linked_aid = coach.get("linked_athlete_id")
        if linked_aid:
            athlete = await db.athletes.find_one({"id": linked_aid}, {"_id": 0, "email": 1, "fiscal_code": 1})
        if not athlete and coach.get("fiscal_code"):
            athlete = await db.athletes.find_one(
                {"fiscal_code": coach["fiscal_code"], "is_compensated": True},
                {"_id": 0, "email": 1, "id": 1},
            )
        if not athlete or not athlete.get("email"):
            errors.append({"coach_id": coach.get("id"), "email": coach_email, "reason": "atleta o email atleta non trovato"})
            continue

        new_alias = f"{athlete['email'].strip().lower()}#coach"
        # Evita collisioni
        existing = await db.users.find_one({"email": new_alias, "id": {"$ne": coach.get("id")}})
        if existing:
            errors.append({"coach_id": coach.get("id"), "email": coach_email, "reason": f"alias già usato da {existing.get('id')}"})
            continue

        await db.users.update_one(
            {"id": coach.get("id")},
            {"$set": {"email": new_alias, "linked_athlete_id": athlete.get("id") or linked_aid}},
        )
        migrated.append({"coach_id": coach.get("id"), "old_email": coach_email, "new_email": new_alias})

    return {
        "migrated_count": len(migrated),
        "skipped_count": len(skipped),
        "errors_count": len(errors),
        "migrated": migrated,
        "errors": errors[:20],  # primi 20 errori per il log
    }


@api_router.delete("/admin/athletes/{athlete_id}/promote-to-coach")
async def unlink_athlete_coach(athlete_id: str, current_user = Depends(get_current_user)):
    """🆕 Annulla la promozione: rimuove il record coach collegato all'atleta.
    Utile per ri-promuovere con il nuovo flow (email/password atleta) atleti già
    promossi col vecchio codice (es. Alice → alice.coach@…).
    """
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    # Cerca per linked_athlete_id o tramite CF
    coach = await db.users.find_one({
        "$or": [
            {"linked_athlete_id": athlete_id},
            {"promoted_from_athlete_id": athlete_id},
        ],
        "role": "coach",
    })
    if not coach:
        coach = await _find_linked_compensated_user_for_athlete(athlete)
        if not coach:
            raise HTTPException(status_code=404, detail="Nessun coach collegato")
    coach_id = coach["id"]
    # Soft check: il coach non deve avere quietanze firmate (per audit) — se le ha, blocca
    has_signed = await db.coach_compensations.find_one(
        {"coach_id": coach_id, "$or": [{"signed": True}, {"receipt_signed": True}]}
    )
    if has_signed:
        raise HTTPException(
            status_code=400,
            detail="Il coach collegato ha quietanze firmate. Per integrità contabile non è possibile rimuoverlo.",
        )
    result = await db.users.delete_one({"id": coach_id})
    logging.info(
        f"[UNLINK-COACH] Rimosso coach {coach_id} (atleta {athlete_id}) da admin {current_user['id']}"
    )
    return {"message": "Promozione annullata", "removed_user_id": coach_id, "deleted": result.deleted_count}


@api_router.get("/admin/athletes/{athlete_id}/linked-coach")
async def get_athlete_linked_coach(athlete_id: str, current_user = Depends(get_current_user)):
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")
    athlete = await db.athletes.find_one({"id": athlete_id}, {"_id": 0, "id": 1, "fiscal_code": 1, "email": 1, "society_id": 1})
    if not athlete:
        return {"linked": False}
    coach = await _find_linked_compensated_user_for_athlete(athlete)
    if not coach:
        return {"linked": False}
    # Resolve team names
    team_names = []
    if coach.get("assigned_teams"):
        teams = await db.teams.find({"id": {"$in": coach["assigned_teams"]}}, {"_id": 0, "id": 1, "name": 1}).to_list(20)
        team_names = [t.get("name", "") for t in teams]
    # Sanitize email: rimuovi alias #ruolo per coerenza con Step C
    coach_email_clean = coach.get("email", "")
    if isinstance(coach_email_clean, str) and "#" in coach_email_clean:
        coach_email_clean = coach_email_clean.split("#", 1)[0]
    return {
        "linked": True,
        "coach_user_id": coach["id"],
        "coach_email": coach_email_clean,
        "coach_name": coach.get("full_name", ""),
        "monthly_compensation": coach.get("monthly_compensation", 0),
        "assigned_teams": team_names,
        "coach_level": coach.get("coach_level", ""),
        # 🆕 26/06/2026 — Date contratto coach (per replicare il blocco "Comunicazione RAS" lato admin)
        "contract_start_date": coach.get("contract_start_date", ""),
        "contract_end_date": coach.get("contract_end_date", ""),
    }


async def _record_external_compensation_declaration(
    user_id: str,
    year: int,
    amount: float,
    declared_none: bool,
    related_receipt_id: Optional[str] = None,
    related_receipt_month: Optional[int] = None,
    society_id: Optional[str] = None,
) -> None:
    """Salva una dichiarazione auto-incrementale. Se sia amount<=0 sia
    declared_none=False (= utente non ha confermato), non salva."""
    if not declared_none and (amount is None or amount <= 0):
        return
    doc = ExternalCompensationDeclaration(
        user_id=user_id,
        year=year,
        amount=max(0.0, float(amount or 0)),
        declared_none=bool(declared_none),
        related_receipt_id=related_receipt_id,
        related_receipt_month=related_receipt_month,
        society_id=society_id,
    ).dict()
    await db.external_compensations.insert_one(doc)


