@api_router.get("/me/anagrafica-check")
async def my_anagrafica_check(current_user = Depends(get_current_user)):
    """Diagnostica: ritorna lo stato dell'anagrafica dell'utente loggato senza
    bloccare. Utile per capire quali campi mancano quando handleSign fallisce."""
    u = await db.users.find_one({"id": current_user["id"]}, {"_id": 0})
    if not u:
        # Forse è un atleta
        u = await db.athletes.find_one({"id": current_user["id"]}, {"_id": 0})
    if not u:
        raise HTTPException(status_code=404, detail="Utente non trovato")

    try:
        _require_complete_anagrafica(u)
        return {
            "complete": True,
            "missing_labels": [],
            "profile_snapshot": {
                "fiscal_code": u.get("fiscal_code"),
                "date_of_birth": u.get("date_of_birth"),
                "birth_date": u.get("birth_date"),
                "place_of_birth": u.get("place_of_birth"),
                "birth_place": u.get("birth_place"),
                "country_of_birth": u.get("country_of_birth"),
                "birth_country": u.get("birth_country"),
                "nationality": u.get("nationality"),
            },
        }
    except HTTPException as ex:
        det = ex.detail if isinstance(ex.detail, dict) else {"missing_labels": []}
        return {
            "complete": False,
            "missing_labels": det.get("missing_labels", []),
            "message": det.get("message", ""),
            "profile_snapshot": {
                "fiscal_code": u.get("fiscal_code"),
                "date_of_birth": u.get("date_of_birth"),
                "birth_date": u.get("birth_date"),
                "place_of_birth": u.get("place_of_birth"),
                "birth_place": u.get("birth_place"),
                "country_of_birth": u.get("country_of_birth"),
                "birth_country": u.get("birth_country"),
                "nationality": u.get("nationality"),
            },
        }


@api_router.post("/me/external-compensations")
async def post_my_external_compensation(
    payload: dict = Body(...),
    current_user = Depends(get_current_user),
):
    """L'utente dichiara un incremento di compensi sportivi ricevuti da altre
    ASD/SSD nell'anno indicato. Body: {amount, year, declared_none}"""
    year = int(payload.get("year") or datetime.utcnow().year)
    amount = float(payload.get("amount") or 0)
    declared_none = bool(payload.get("declared_none", False))
    if amount < 0:
        raise HTTPException(status_code=400, detail="Importo non valido")
    if not declared_none and amount <= 0:
        raise HTTPException(status_code=400, detail="Specifica un importo > 0 oppure conferma 'nessun compenso'")
    await _record_external_compensation_declaration(
        user_id=current_user["id"],
        year=year,
        amount=amount,
        declared_none=declared_none,
        society_id=current_user.get("society_id"),
    )
    total = await _get_year_external_compensations_total(current_user["id"], year)
    return {"success": True, "cumulative_year_total": total}


@api_router.get("/me/external-compensations")
async def list_my_external_compensations(
    year: Optional[int] = None,
    current_user = Depends(get_current_user),
):
    """Lista delle dichiarazioni di compensi esterni dell'utente.
    🆕 28/06/2026 — Le dichiarazioni atleta sono salvate con user_id=athlete_id.
    Per atleti dual-role o utenti generici, le dichiarazioni potrebbero essere
    salvate sia con user_id che con athlete_id. Cerchiamo entrambi gli ID."""
    user_id = current_user["id"]
    athlete_id = current_user.get("athlete_id")
    candidate_ids = list({uid for uid in [user_id, athlete_id] if uid})
    q: dict = {"user_id": {"$in": candidate_ids}} if len(candidate_ids) > 1 else {"user_id": user_id}
    if year is not None:
        q["year"] = int(year)
    items: List[dict] = []
    async for d in db.external_compensations.find(q, {"_id": 0}).sort("declared_at", 1):
        items.append(d)
    total = sum(float(i.get("amount") or 0) for i in items)
    return {"items": items, "total": round(total, 2)}


