def get_current_season():
    """Get current season name based on date (July to June) - kept for backward compat with other functions."""
    now = datetime.utcnow()
    if now.month >= 7:
        return f"{now.year}-{now.year + 1}"
    else:
        return f"{now.year - 1}-{now.year}"

