class SignatureDocumentRequest(BaseModel):
    document_type: str  # "privacy_consent", "coach_contract", "compensation_receipt"
    document_title: str
    document_text: str
    signer_name: str
    signer_email: str
    signature_base64: str  # Base64 encoded signature image
    related_entity_id: Optional[str] = None  # athlete_id, coach_id, etc.
    additional_data: Optional[dict] = None  # Any extra data to include
    consent_data: Optional[dict] = None  # Granular consent choices (GDPR)


class GDPRPrivacySignRequest(BaseModel):
    """Request model for GDPR-compliant privacy consent signing"""
    document_type: str  # "gdpr_adult" or "gdpr_minor"
    signature_base64: str  # Base64 encoded signature image
    user_agent: str  # Browser/device info
    # For adult privacy
    signer_name: Optional[str] = None
    signer_surname: Optional[str] = None
    signer_fiscal_code: Optional[str] = None
    signer_birth_date: Optional[str] = None
    signer_birth_place: Optional[str] = None
    signer_address: Optional[str] = None
    signer_city: Optional[str] = None
    signer_province: Optional[str] = None
    # For minor privacy (additional fields)
    minor_id: Optional[str] = None  # athlete_id of the minor
    minor_name: Optional[str] = None
    minor_surname: Optional[str] = None
    minor_fiscal_code: Optional[str] = None
    minor_birth_date: Optional[str] = None
    minor_birth_place: Optional[str] = None
    # Granular consent data (GDPR)
    consent_data: Optional[dict] = None


# ═══════════════════════════════════════════════════════════════════════════════
# 📄 SECTION: PDF GENERATION (GDPR, quietanze, soglie)
# Linee ~17045-21000 — helper functions per generazione PDF firmati.
# Pianificato per estrazione → services/pdf_service.py
# ═══════════════════════════════════════════════════════════════════════════════
def generate_monthly_receipt_pdf(
    society_name: str,
    collaborator_name: str,
    collaborator_fiscal_code: str,
    month_name: str,
    year: int,
    amount_gross: float,
    signature_base64: str,
    signed_at: Optional[Any] = None,
    document_id: Optional[str] = None,
    signer_id: Optional[str] = None,
    ip_address: Optional[str] = None,
    document_hash: Optional[str] = None,
    coach_amount: Optional[float] = None,
    athlete_pro_amount: Optional[float] = None,
    role_label: str = "Collaboratore",  # 🆕 29/06/2026 — label personalizzabile: "Atleta"/"Coach"/"Dirigente"
    inps_breakdown: Optional[dict] = None,  # 🆕 trattenuta INPS (quota lavoratore 1/3) oltre €5.000
) -> bytes:
    """Generate monthly compensation receipt PDF with proper formatting.

    `signed_at` is the ORIGINAL signing date (str ISO or datetime). Falls back
    to today only when missing — should never happen for a signed receipt.

    🆕 Se vengono passati `coach_amount` e `athlete_pro_amount` (entrambi > 0),
    il PDF mostra la suddivisione "Compenso Coach + Compenso Atleta PRO + Totale"
    invece di una singola riga. `amount_gross` rimane il TOTALE (somma dei due).
    """
    if not HAS_PDF_GENERATION:
        raise HTTPException(status_code=500, detail="PDF generation not available")
    
    buffer = io.BytesIO()
    c = canvas.Canvas(buffer, pagesize=A4)
    width, height = A4
    
    # Use original signing date (NOT generation date). Receipts must show the
    # date the collaborator/coach/dirigente actually signed.
    signed_dt = None
    if signed_at:
        try:
            if isinstance(signed_at, str):
                signed_dt = datetime.fromisoformat(signed_at.replace("Z", "+00:00"))
            elif isinstance(signed_at, datetime):
                signed_dt = signed_at
        except Exception:
            signed_dt = None
    if signed_dt is None:
        signed_dt = datetime.now(timezone.utc)
    timestamp = to_rome_time(signed_dt).strftime("%d/%m/%Y")
    timestamp_full = to_rome_time(signed_dt).strftime("%d/%m/%Y %H:%M:%S")
    
    # Title - centered, bold
    c.setFont("Helvetica-Bold", 14)
    title = "QUIETANZA COMPENSO SPORTIVO DILETTANTISTICO"
    c.drawCentredString(width/2, height - 3*cm, title)
    
    # Society name
    c.setFont("Helvetica", 11)
    y = height - 4.5*cm
    c.drawString(2*cm, y, f"ASD/SSD: {society_name}")
    
    # Collaborator info
    y -= 1*cm
    c.drawString(2*cm, y, f"{role_label}: {collaborator_name}")
    
    y -= 0.6*cm
    c.drawString(2*cm, y, f"Codice Fiscale: {collaborator_fiscal_code or '________________________'}")
    
    # Reference month
    y -= 1*cm
    c.drawString(2*cm, y, f"Mese di riferimento: {month_name} {year}")
    
    # Amount - ONLY GROSS, no net
    y -= 1.2*cm
    c.setFont("Helvetica-Bold", 11)
    # 🆕 Doppio compenso (Coach + Atleta PRO) — mostra suddivisione + totale
    has_split = (coach_amount is not None and athlete_pro_amount is not None
                 and coach_amount > 0 and athlete_pro_amount > 0)
    if has_split:
        c.setFont("Helvetica", 10)
        c.drawString(2*cm, y, f"Compenso da Coach: € {coach_amount:.2f}")
        y -= 0.55*cm
        c.drawString(2*cm, y, f"Compenso da Atleta: € {athlete_pro_amount:.2f}")
        y -= 0.65*cm
        c.setFont("Helvetica-Bold", 11)
        c.drawString(2*cm, y, f"Compenso lordo totale: € {amount_gross:.2f}")
    else:
        c.drawString(2*cm, y, f"Compenso lordo: € {amount_gross:.2f}")

    # 🆕 Dettaglio trasparente del calcolo dei contributi INPS (Gestione Separata, Riforma Sport)
    if inps_breakdown and inps_breakdown.get("applies"):
        _role_low = (role_label or "collaboratore").lower()
        _exc = float(inps_breakdown.get('excess_over_5000', 0) or 0)
        _ivs_base = float(inps_breakdown.get('ivs_base', 0) or 0)
        _ivs_rate = float(inps_breakdown.get('ivs_rate', 0) or 0)
        _ivs_contr = float(inps_breakdown.get('ivs_contribution', 0) or 0)
        _minor_rate = float(inps_breakdown.get('minor_rate', 0) or 0)
        _minor_contr = float(inps_breakdown.get('minor_contribution', 0) or 0)
        _tot = float(inps_breakdown.get('inps_total', 0) or 0)
        _worker = float(inps_breakdown.get('inps_worker', 0) or 0)
        _net = float(inps_breakdown.get('amount_net', amount_gross) or 0)
        y -= 0.8*cm
        c.setFont("Helvetica-Bold", 10)
        c.drawString(2*cm, y, "Dettaglio contributi INPS (Gestione Separata - Riforma Sport):")
        y -= 0.5*cm
        c.setFont("Helvetica", 9)
        c.drawString(2.3*cm, y, f"- Quota compenso eccedente la franchigia di €5.000: € {_exc:.2f}")
        y -= 0.42*cm
        c.drawString(2.3*cm, y, f"- Imponibile previdenziale (50% dell'eccedenza, agevolazione fino al 31/12/2027): € {_ivs_base:.2f}")
        y -= 0.42*cm
        c.drawString(2.3*cm, y, f"- Contributo IVS ({_ivs_rate*100:.0f}% dell'imponibile): € {_ivs_contr:.2f}")
        if _minor_rate > 0:
            y -= 0.42*cm
            c.drawString(2.3*cm, y, f"- Aliquote aggiuntive ({_minor_rate*100:.2f}% sul 100% dell'eccedenza): € {_minor_contr:.2f}")
        y -= 0.42*cm
        c.drawString(2.3*cm, y, f"- Contributo INPS totale dovuto: € {_tot:.2f}")
        y -= 0.42*cm
        c.setFont("Helvetica-Bold", 9)
        c.drawString(2.3*cm, y, f"- Trattenuta a carico {_role_low} (1/3 del contributo totale): - € {_worker:.2f}")
        y -= 0.65*cm
        c.setFont("Helvetica-Bold", 11)
        c.drawString(2*cm, y, f"Compenso NETTO corrisposto: € {_net:.2f}")
        y -= 0.45*cm
        c.setFont("Helvetica-Oblique", 8)
        c.drawString(2*cm, y, "Il netto corrisposto e' il lordo pattuito diminuito della quota contributiva INPS a carico")
        y -= 0.35*cm
        c.drawString(2*cm, y, "del lavoratore (1/3 del contributo dovuto). I 2/3 restanti sono a carico della societa'.")

    # Declaration text
    y -= 1.5*cm
    c.setFont("Helvetica", 10)
    # 🆕 30/06/2026 — Dichiarazione e firma usano role_label (Atleta/Coach/
    # Collaboratore/Dirigente) invece di "collaboratore" fisso.
    role_low = (role_label or "collaboratore").lower()
    # 🆕 Informativa/dichiarazione del punto 4 (ricezione del NETTO, lordo≠netto,
    # progressivi distinti, compensi pregressi/altri committenti dichiarati).
    declaration = ("Dichiaro di aver ricevuto l'importo netto indicato nella presente quietanza. "
                   "Sono consapevole che il compenso lordo e l'importo netto effettivamente ricevuto "
                   "sono diversi in presenza di trattenute previdenziali. Ai fini del monitoraggio delle "
                   "soglie fiscali e previdenziali, RegistraTEAM utilizza progressivi distinti, secondo la "
                   "normativa applicabile. Dichiaro inoltre di aver comunicato correttamente gli eventuali "
                   "compensi pregressi e quelli percepiti presso altri committenti.")
    
    # Word wrap declaration
    words = declaration.split(' ')
    lines = []
    current_line = ""
    max_width = width - 4*cm
    for word in words:
        test_line = current_line + " " + word if current_line else word
        if c.stringWidth(test_line, "Helvetica", 10) < max_width:
            current_line = test_line
        else:
            lines.append(current_line)
            current_line = word
    if current_line:
        lines.append(current_line)
    
    for line in lines:
        c.drawString(2*cm, y, line)
        y -= 0.5*cm
    
    # Signature section
    y -= 1.5*cm
    c.setFont("Helvetica", 10)
    c.drawString(2*cm, y, f"Data: {timestamp}")
    # 🆕 Modalità di pagamento (fissa: Bonifico)
    c.drawString(width/2 - 1*cm, y, "Modalità di pagamento: Bonifico")
    # 🆕 30/06/2026 — Etichetta firma dinamica
    sign_label_low = role_low if role_low not in ("collaboratore",) else "collaboratore"
    c.drawString(width - 8*cm, y, f"Firma {sign_label_low}:")
    
    # Add signature image
    if signature_base64 and HAS_PIL:
        try:
            if ',' in signature_base64:
                signature_base64 = signature_base64.split(',')[1]
            
            sig_data = base64.b64decode(signature_base64)
            sig_image = Image.open(io.BytesIO(sig_data))
            
            # Convert to RGB
            if sig_image.mode != 'RGB':
                if sig_image.mode == 'RGBA':
                    background = Image.new('RGB', sig_image.size, (255, 255, 255))
                    background.paste(sig_image, mask=sig_image.split()[3])
                    sig_image = background
                else:
                    sig_image = sig_image.convert('RGB')
            
            # Normalize colors
            pixels = sig_image.load()
            w, h = sig_image.size
            for py in range(h):
                for px in range(w):
                    r, g, b = pixels[px, py]
                    luminance = (r * 0.299 + g * 0.587 + b * 0.114)
                    if luminance < 200:
                        pixels[px, py] = (0, 0, 0)
                    else:
                        pixels[px, py] = (255, 255, 255)
            
            # 🔍 Auto-crop dei margini bianchi: la firma viene tracciata in un
            # canvas più ampio del tratto effettivo. Senza crop, dentro il box PDF
            # (5-6cm) il tratto verrebbe scalato proporzionalmente e risulterebbe
            # illeggibile (es. firma di Fede "piccolissima"). Ritagliamo al bbox
            # del nero, con padding minimo.
            try:
                from PIL import ImageOps as _ImageOps
                _bbox = _ImageOps.invert(sig_image.convert('L')).getbbox()
                if _bbox:
                    _pad = 15
                    _l = max(0, _bbox[0] - _pad)
                    _t = max(0, _bbox[1] - _pad)
                    _r = min(sig_image.width, _bbox[2] + _pad)
                    _b = min(sig_image.height, _bbox[3] + _pad)
                    sig_image = sig_image.crop((_l, _t, _r, _b))
            except Exception:
                pass
            
            sig_buffer = io.BytesIO()
            sig_image.save(sig_buffer, format='PNG')
            sig_buffer.seek(0)
            
            from reportlab.lib.utils import ImageReader
            img_reader = ImageReader(sig_buffer)
            c.drawImage(img_reader, width - 8*cm, y - 2.5*cm, width=6*cm, height=2*cm, preserveAspectRatio=True)
        except Exception as e:
            logging.error(f"Error adding signature: {e}")
    
    # Authentication metadata footer (GDPR audit trail)
    # Drawn at the bottom of the page in small grey font.
    try:
        c.setFont("Helvetica", 7)
        c.setFillColorRGB(0.45, 0.45, 0.45)
        footer_y = 1.6 * cm
        c.drawString(2 * cm, footer_y, "— Metadati di autentica —")
        footer_y -= 0.32 * cm
        c.drawString(2 * cm, footer_y, f"Firmato il: {timestamp_full} (Europe/Rome)")
        if document_id:
            footer_y -= 0.32 * cm
            c.drawString(2 * cm, footer_y, f"ID documento: {document_id}")
        if signer_id:
            footer_y -= 0.32 * cm
            c.drawString(2 * cm, footer_y, f"ID firmatario: {signer_id}")
        if ip_address:
            footer_y -= 0.32 * cm
            c.drawString(2 * cm, footer_y, f"Indirizzo IP firma: {ip_address}")
        if document_hash:
            footer_y -= 0.32 * cm
            label = f"Hash documento: {document_hash[:32]}…" if len(document_hash) > 32 else f"Hash documento: {document_hash}"
            c.drawString(2 * cm, footer_y, label)
        c.setFillColorRGB(0, 0, 0)

        # QR code (bottom-right) — links to public verify page
        if document_id:
            try:
                verify_url = _public_verify_url(document_id)
                qr_png = _generate_qr_png(verify_url)
                if qr_png:
                    from reportlab.lib.utils import ImageReader
                    qr_reader = ImageReader(io.BytesIO(qr_png))
                    qr_size = 2.2 * cm
                    qr_x = width - qr_size - 1.5 * cm
                    qr_y = 0.8 * cm
                    c.drawImage(qr_reader, qr_x, qr_y, width=qr_size, height=qr_size, preserveAspectRatio=True, mask='auto')
                    c.setFont("Helvetica", 6)
                    c.setFillColorRGB(0.4, 0.4, 0.4)
                    c.drawCentredString(qr_x + qr_size / 2, qr_y - 0.2 * cm, "Verifica autenticità")
                    c.setFillColorRGB(0, 0, 0)
            except Exception:
                pass
    except Exception:
        pass

    # 🆕 Nota dual-role (bonifico unico Coach + Atleta PRO)
    if has_split:
        try:
            c.setFont("Helvetica-Oblique", 8)
            c.setFillColorRGB(0.35, 0.35, 0.35)
            c.drawCentredString(
                width / 2,
                1.3 * cm,
                "Documento generato per dual-role Coach + Atleta — bonifico unico",
            )
            c.setFillColorRGB(0, 0, 0)
        except Exception:
            pass

    c.save()
    return buffer.getvalue()


# =============================================================================
# GDPR PRIVACY TEMPLATES - NEW COMPLIANT VERSIONS
# =============================================================================

def generate_gdpr_adult_privacy_pdf(
    society_name: str,
    ragione_sociale: str,
    society_address: str,
    society_fiscal_code: str,
    society_email: str,
    signer_name: str,
    signer_surname: str,
    signer_fiscal_code: str,
    signer_birth_date: str,
    signer_birth_place: str,
    signer_address: str,
    signer_city: str,
    signer_province: str,
    signature_base64: str,
    timestamp: str,
    ip_address: str,
    user_agent: str,
    document_version: str,
    document_hash: str,
    user_id: str,
    society_id: str,
    consent_data: dict = None,
    signer_role: str = "",
    signer_country_of_birth: str = "",
    document_id: Optional[str] = None
) -> bytes:
    """Generate GDPR-compliant privacy consent PDF for adults (collaboratori, coach, dirigenti, atleti maggiorenni)"""
    if not HAS_PDF_GENERATION:
        raise HTTPException(status_code=500, detail="PDF generation not available")
    
    # Usa ragione_sociale se disponibile, altrimenti society_name
    nome_legale = ragione_sociale if ragione_sociale else society_name
    
    buffer = io.BytesIO()
    c = canvas.Canvas(buffer, pagesize=A4)
    width, height = A4
    
    def draw_wrapped_text(canvas_obj, text, x, y, max_width, font_name="Helvetica", font_size=10, line_height=0.45):
        """Helper function to draw wrapped text"""
        canvas_obj.setFont(font_name, font_size)
        words = text.split(' ')
        lines = []
        current_line = ""
        for word in words:
            test_line = current_line + " " + word if current_line else word
            if canvas_obj.stringWidth(test_line, font_name, font_size) < max_width:
                current_line = test_line
            else:
                if current_line:
                    lines.append(current_line)
                current_line = word
        if current_line:
            lines.append(current_line)
        
        for line in lines:
            canvas_obj.drawString(x, y, line)
            y -= line_height * cm
        return y
    
    # ==================== PAGE 1 ====================
    # Header - role-specific title
    staff_roles = ["coach", "collaboratore", "dirigente"]
    is_staff = signer_role.lower() in staff_roles if signer_role else False
    pdf_title = "INFORMATIVA PRIVACY PER STAFF" if is_staff else "INFORMATIVA PRIVACY PER ATLETI MAGGIORENNI"
    
    c.setFont("Helvetica-Bold", 14)
    c.drawCentredString(width/2, height - 2*cm, pdf_title)
    c.setFont("Helvetica", 10)
    c.drawCentredString(width/2, height - 2.6*cm, "(ai sensi del Regolamento UE 2016/679 - GDPR)")
    
    y = height - 3.5*cm
    max_w = width - 4*cm
    
    # Box Dati Societari
    c.setStrokeColor(colors.HexColor("#1565C0"))
    c.setFillColor(colors.HexColor("#E3F2FD"))
    c.roundRect(2*cm, y - 3.0*cm, max_w, 2.8*cm, 5, stroke=1, fill=1)
    c.setFillColor(colors.black)
    
    c.setFont("Helvetica-Bold", 10)
    c.drawString(2.3*cm, y - 0.6*cm, f"Società: {nome_legale}")
    c.setFont("Helvetica", 9)
    c.drawString(2.3*cm, y - 1.15*cm, f"Sede: {society_address}")
    c.drawString(2.3*cm, y - 1.65*cm, f"C.F.: {society_fiscal_code}")
    c.drawString(2.3*cm, y - 2.15*cm, f"Email: {society_email}")
    
    y -= 3.6*cm
    
    # Intro - role-specific greeting
    c.setFont("Helvetica", 10)
    greeting = "Gentile Collaboratore / Membro dello Staff" if is_staff else "Gentile Atleta"
    intro_text = f"{greeting}, la presente informativa descrive le modalità di trattamento dei dati personali da parte della società sportiva {nome_legale}."
    y = draw_wrapped_text(c, intro_text, 2*cm, y, max_w)
    y -= 0.3*cm
    titolare_intro = "Il Titolare del trattamento dei dati personali è la società sportiva sopra indicata nella persona del proprio legale rappresentante pro tempore."
    y = draw_wrapped_text(c, titolare_intro, 2*cm, y, max_w)
    
    y -= 0.5*cm
    
    # Section 1 - Titolare
    c.setFont("Helvetica-Bold", 11)
    c.drawString(2*cm, y, "1. TITOLARE DEL TRATTAMENTO")
    y -= 0.5*cm
    c.setFont("Helvetica", 10)
    titolare_text = f"Il Titolare del trattamento dei dati personali è {nome_legale}, con sede in {society_address}. Per qualsiasi richiesta relativa al trattamento dei dati è possibile contattare la Società tramite i recapiti indicati."
    y = draw_wrapped_text(c, titolare_text, 2*cm, y, max_w)
    
    y -= 0.3*cm
    
    # Section 2 - Finalità
    c.setFont("Helvetica-Bold", 11)
    c.drawString(2*cm, y, "2. FINALITÀ E BASE GIURIDICA DEL TRATTAMENTO")
    y -= 0.5*cm
    c.setFont("Helvetica", 10)
    finalita_text = "I dati personali saranno trattati per le seguenti finalità: gestione dei rapporti sportivi, associativi o collaborativi con la Società; adempimenti degli obblighi di legge, fiscali e contabili; comunicazioni con enti sportivi di riferimento (Federazioni, EPS, RAS); gestione delle attività sportive, organizzative e amministrative della Società; gestione dei compensi sportivi dilettantistici, ove previsti. La base giuridica del trattamento è l'esecuzione del rapporto associativo o collaborativo e l'adempimento degli obblighi previsti dalla normativa vigente."
    y = draw_wrapped_text(c, finalita_text, 2*cm, y, max_w)
    
    y -= 0.3*cm
    
    # Section 3 - Tipologia dati
    c.setFont("Helvetica-Bold", 11)
    c.drawString(2*cm, y, "3. TIPOLOGIA DI DATI TRATTATI")
    y -= 0.5*cm
    c.setFont("Helvetica", 10)
    dati_text = "La Società potrà trattare le seguenti categorie di dati personali: dati anagrafici (nome, cognome, data e luogo di nascita, codice fiscale); dati di contatto (telefono, email, indirizzo); dati relativi alle attività svolte per la Società; dati amministrativi e fiscali connessi alla gestione dei compensi sportivi dilettantistici."
    y = draw_wrapped_text(c, dati_text, 2*cm, y, max_w)
    
    y -= 0.3*cm
    
    # Section 4 - Modalità
    c.setFont("Helvetica-Bold", 11)
    c.drawString(2*cm, y, "4. MODALITÀ DI TRATTAMENTO")
    y -= 0.5*cm
    c.setFont("Helvetica", 10)
    modalita_text = "Il trattamento dei dati avviene mediante strumenti informatici e/o cartacei con modalità idonee a garantire la sicurezza e la riservatezza dei dati personali. La Società può utilizzare applicativi gestionali informatici per l'organizzazione delle attività sportive e amministrative. L'accesso ai dati è consentito esclusivamente ai soggetti autorizzati dalla Società."
    y = draw_wrapped_text(c, modalita_text, 2*cm, y, max_w)
    
    y -= 0.3*cm
    
    # Section 5 - Conservazione
    c.setFont("Helvetica-Bold", 11)
    c.drawString(2*cm, y, "5. PERIODO DI CONSERVAZIONE")
    y -= 0.5*cm
    c.setFont("Helvetica", 10)
    conservazione_text = "I dati personali saranno conservati per tutta la durata del rapporto con la Società e successivamente per il periodo necessario all'adempimento degli obblighi previsti dalla normativa fiscale, amministrativa e sportiva vigente."
    y = draw_wrapped_text(c, conservazione_text, 2*cm, y, max_w)
    
    y -= 0.3*cm
    
    # Section 6 - Diritti
    c.setFont("Helvetica-Bold", 11)
    c.drawString(2*cm, y, "6. DIRITTI DELL'INTERESSATO")
    y -= 0.5*cm
    c.setFont("Helvetica", 10)
    diritti_text = "L'interessato può esercitare i diritti previsti dagli articoli 15-22 del GDPR, tra cui: accesso ai dati personali; rettifica o aggiornamento dei dati; cancellazione dei dati nei casi previsti dalla legge; limitazione o opposizione al trattamento; portabilità dei dati. Le richieste possono essere rivolte al Titolare del trattamento tramite i recapiti indicati dalla Società."
    y = draw_wrapped_text(c, diritti_text, 2*cm, y, max_w)
    
    # Footer page 1
    c.setFont("Helvetica", 8)
    c.drawCentredString(width/2, 1.5*cm, "Pagina 1 di 2")
    
    c.showPage()
    
    # ==================== PAGE 2 ====================
    y = height - 2*cm
    
    # Section 7 - Accettazione digitale
    c.setFont("Helvetica-Bold", 11)
    c.drawString(2*cm, y, "7. ACCETTAZIONE DIGITALE DEL DOCUMENTO")
    y -= 0.6*cm
    c.setFont("Helvetica", 10)
    firma_text = "L'accettazione del presente documento avviene tramite l'applicativo gestionale utilizzato dalla Società. Il sistema registra metadati tecnici dell'accettazione (data, ora, identificativo utente, dispositivo e indirizzo IP) ai fini della tracciabilità e sicurezza."
    y = draw_wrapped_text(c, firma_text, 2*cm, y, max_w)
    
    y -= 0.5*cm
    
    # DICHIARAZIONE
    c.setFont("Helvetica-Bold", 11)
    c.drawString(2*cm, y, "DICHIARAZIONE")
    y -= 0.5*cm
    c.setFont("Helvetica", 10)
    dichiarazione_text = "Il sottoscritto dichiara di aver preso visione dell'informativa sulla privacy ai sensi del Regolamento UE 2016/679 e prende atto del trattamento dei propri dati personali."
    y = draw_wrapped_text(c, dichiarazione_text, 2*cm, y, max_w)
    
    y -= 0.8*cm
    
    # PRESA VISIONE (obbligatoria)
    cd = consent_data or {}
    c.setFont("Helvetica-Bold", 11)
    c.drawString(2*cm, y, "PRESA VISIONE (obbligatoria)")
    y -= 0.5*cm
    c.setFont("Helvetica", 9)
    
    check_pv = "X" if cd.get("privacy_viewed", True) else " "
    c.drawString(2*cm, y, f"[{check_pv}] Dichiaro di aver preso visione dell'informativa sulla privacy")
    y -= 0.6*cm
    
    # CONSENSI FACOLTATIVI
    c.setFont("Helvetica-Bold", 11)
    c.drawString(2*cm, y, "CONSENSI FACOLTATIVI")
    y -= 0.4*cm
    
    c.setFont("Helvetica", 9)
    check_ii = "X" if cd.get("images_internal", False) else " "
    ii_text = f"[{check_ii}] Acconsento all'utilizzo delle mie immagini per finalita' interne (es. comunicazioni, gruppi, attivita')" if is_staff else f"[{check_ii}] Acconsento all'utilizzo delle mie immagini per finalita' interne (es. comunicazioni, gruppi, attivita' sportive)"
    y = draw_wrapped_text(c, ii_text, 2*cm, y, max_w, font_name="Helvetica", font_size=9)
    y -= 0.3*cm
    
    check_ip = "X" if cd.get("images_promo", False) else " "
    ip_text = f"[{check_ip}] Acconsento all'utilizzo delle mie immagini per finalita' promozionali (es. sito web, social, materiale pubblicitario)" if is_staff else f"[{check_ip}] Acconsento all'utilizzo delle mie immagini per finalita' promozionali (es. sito web, social network, materiale pubblicitario)"
    y = draw_wrapped_text(c, ip_text, 2*cm, y, max_w, font_name="Helvetica", font_size=9)
    y -= 0.3*cm
    
    # Nota revoca consensi
    c.setFont("Helvetica-Oblique", 8)
    c.setFillColor(colors.HexColor("#555555"))
    y = draw_wrapped_text(c, "Il consenso e' facoltativo e puo' essere revocato in qualsiasi momento. La revoca ha effetto solo per utilizzi futuri.", 2*cm, y, max_w, font_name="Helvetica-Oblique", font_size=8)
    c.setFillColor(colors.black)
    y -= 0.4*cm
    
    c.setFont("Courier", 7)
    c.setFillColor(colors.HexColor("#888888"))
    c.drawString(2*cm, y, f"Versione doc: {cd.get('document_version', document_version)} | Timestamp: {timestamp} | IP: {ip_address}")
    c.setFillColor(colors.black)
    
    y -= 0.8*cm
    
    # Signer data box
    c.setStrokeColor(colors.HexColor("#8E44AD"))
    c.setFillColor(colors.HexColor("#F5EEF8"))
    c.roundRect(2*cm, y - 3.5*cm, width - 4*cm, 4*cm, 5, fill=1, stroke=1)
    
    c.setFillColor(colors.black)
    c.setFont("Helvetica-Bold", 10)
    c.drawString(2.5*cm, y - 0.4*cm, "DATI DELL'INTERESSATO")
    
    c.setFont("Helvetica", 10)
    y_box = y - 0.9*cm
    c.drawString(2.5*cm, y_box, f"Nome: {signer_surname} {signer_name}")
    y_box -= 0.45*cm
    c.drawString(2.5*cm, y_box, f"Codice Fiscale: {signer_fiscal_code or '________________________'}")
    y_box -= 0.45*cm
    birth_place_str = signer_birth_place or signer_country_of_birth or '________'
    birth_date_str = signer_birth_date or '________'
    c.drawString(2.5*cm, y_box, f"Nato/a a {birth_place_str} il {birth_date_str}")
    y_box -= 0.45*cm
    addr_str = signer_address or '________'
    city_str = signer_city or '________'
    prov_str = signer_province or '__'
    c.drawString(2.5*cm, y_box, f"Residente in {addr_str}, {city_str} ({prov_str})")
    y_box -= 0.45*cm
    c.drawString(2.5*cm, y_box, f"Società: {nome_legale}")
    
    y -= 4.5*cm
    
    # Signature / Acceptance section
    if signature_base64 and HAS_PIL:
        c.setFont("Helvetica-Bold", 10)
        c.drawString(2*cm, y, "Accettazione digitale:")
        y -= 0.5*cm
        try:
            if ',' in signature_base64:
                signature_base64_clean = signature_base64.split(',')[1]
            else:
                signature_base64_clean = signature_base64
            
            sig_data = base64.b64decode(signature_base64_clean)
            sig_image = Image.open(io.BytesIO(sig_data))
            
            if sig_image.mode != 'RGB':
                if sig_image.mode == 'RGBA':
                    background = Image.new('RGB', sig_image.size, (255, 255, 255))
                    background.paste(sig_image, mask=sig_image.split()[3])
                    sig_image = background
                else:
                    sig_image = sig_image.convert('RGB')
            
            sig_buffer = io.BytesIO()
            sig_image.save(sig_buffer, format='PNG')
            sig_buffer.seek(0)
            
            from reportlab.lib.utils import ImageReader
            img_reader = ImageReader(sig_buffer)
            c.drawImage(img_reader, 2*cm, y - 2*cm, width=6*cm, height=2*cm, preserveAspectRatio=True)
        except Exception as e:
            logging.error(f"Error adding signature: {e}")
        y -= 2.5*cm
    else:
        # No signature - document accepted digitally during registration
        c.setFont("Helvetica-Oblique", 9)
        c.setFillColor(colors.HexColor("#555555"))
        y = draw_wrapped_text(c, f"Documento accettato digitalmente tramite applicativo gestionale in fase di registrazione - {timestamp}", 2*cm, y, max_w, font_name="Helvetica-Oblique", font_size=9)
        c.setFillColor(colors.black)
        y -= 0.5*cm
    
    # Technical metadata box (very important for legal validity)
    c.setFont("Helvetica-Bold", 9)
    c.drawString(2*cm, y, "METADATI ACCETTAZIONE (validità probatoria)")
    y -= 0.4*cm
    
    c.setStrokeColor(colors.HexColor("#2C3E50"))
    c.setFillColor(colors.HexColor("#ECF0F1"))
    c.roundRect(2*cm, y - 3*cm, width - 4*cm, 3*cm, 3, fill=1, stroke=1)
    
    c.setFillColor(colors.black)
    c.setFont("Courier", 8)
    y_meta = y - 0.4*cm
    c.drawString(2.3*cm, y_meta, f"document_version: {document_version}")
    y_meta -= 0.35*cm
    c.drawString(2.3*cm, y_meta, f"timestamp: {timestamp}")
    y_meta -= 0.35*cm
    c.drawString(2.3*cm, y_meta, f"user_id: {user_id}")
    y_meta -= 0.35*cm
    c.drawString(2.3*cm, y_meta, f"society_id: {society_id}")
    y_meta -= 0.35*cm
    c.drawString(2.3*cm, y_meta, f"hash_document: {document_hash}")
    y_meta -= 0.35*cm
    c.drawString(2.3*cm, y_meta, f"device_type: {user_agent[:60]}..." if len(user_agent) > 60 else f"device_type: {user_agent}")
    y_meta -= 0.35*cm
    c.drawString(2.3*cm, y_meta, f"ip_address: {ip_address}")
    
    # Footer page 2
    c.setFont("Helvetica", 8)
    c.setFillColor(colors.black)
    c.drawCentredString(width/2, 1.5*cm, "Pagina 2 di 2")

    # 🆕 QR code (bottom-right) — verifica autenticità della firma
    if document_id:
        try:
            verify_url = _public_verify_url(document_id)
            qr_png = _generate_qr_png(verify_url)
            if qr_png:
                from reportlab.lib.utils import ImageReader
                qr_reader = ImageReader(io.BytesIO(qr_png))
                qr_size = 2.2 * cm
                qr_x = width - qr_size - 1.5 * cm
                qr_y = 0.8 * cm
                c.drawImage(qr_reader, qr_x, qr_y, width=qr_size, height=qr_size, preserveAspectRatio=True, mask='auto')
                c.setFont("Helvetica", 6)
                c.setFillColorRGB(0.4, 0.4, 0.4)
                c.drawCentredString(qr_x + qr_size / 2, qr_y - 0.2 * cm, "Verifica autenticità")
                c.setFillColorRGB(0, 0, 0)
        except Exception:
            pass
    
    c.save()
    return buffer.getvalue()


def generate_gdpr_minor_privacy_pdf(
    society_name: str,
    ragione_sociale: str,
    society_address: str,
    society_fiscal_code: str,
    society_email: str,
    parent_name: str,
    parent_surname: str,
    parent_fiscal_code: str,
    minor_name: str,
    minor_surname: str,
    minor_fiscal_code: str,
    minor_birth_date: str,
    minor_birth_place: str,
    signature_base64: str,
    timestamp: str,
    ip_address: str,
    user_agent: str,
    document_version: str,
    document_hash: str,
    user_id: str,
    society_id: str,
    consent_data: dict = None,
    document_id: Optional[str] = None
) -> bytes:
    if not HAS_PDF_GENERATION:
        raise HTTPException(status_code=500, detail="PDF generation not available")
    
    # Usa ragione_sociale se disponibile, altrimenti society_name
    nome_legale = ragione_sociale if ragione_sociale else society_name
    
    buffer = io.BytesIO()
    c = canvas.Canvas(buffer, pagesize=A4)
    width, height = A4
    
    def draw_wrapped_text(canvas_obj, text, x, y, max_width, font_name="Helvetica", font_size=10, line_height=0.45):
        """Helper function to draw wrapped text"""
        canvas_obj.setFont(font_name, font_size)
        words = text.split(' ')
        lines = []
        current_line = ""
        for word in words:
            test_line = current_line + " " + word if current_line else word
            if canvas_obj.stringWidth(test_line, font_name, font_size) < max_width:
                current_line = test_line
            else:
                if current_line:
                    lines.append(current_line)
                current_line = word
        if current_line:
            lines.append(current_line)
        
        for line in lines:
            canvas_obj.drawString(x, y, line)
            y -= line_height * cm
        return y
    
    # ==================== PAGE 1 ====================
    # Header
    c.setFont("Helvetica-Bold", 14)
    c.drawCentredString(width/2, height - 2*cm, "INFORMATIVA PRIVACY PER MINORI")
    c.setFont("Helvetica", 10)
    c.drawCentredString(width/2, height - 2.6*cm, "(Regolamento UE 2016/679 - GDPR)")
    
    y = height - 3.5*cm
    max_w = width - 4*cm
    
    # Box Dati Societari
    c.setStrokeColor(colors.HexColor("#1565C0"))
    c.setFillColor(colors.HexColor("#E3F2FD"))
    c.roundRect(2*cm, y - 3.0*cm, max_w, 2.8*cm, 5, stroke=1, fill=1)
    c.setFillColor(colors.black)
    
    c.setFont("Helvetica-Bold", 10)
    c.drawString(2.3*cm, y - 0.6*cm, f"Società: {nome_legale}")
    c.setFont("Helvetica", 9)
    c.drawString(2.3*cm, y - 1.15*cm, f"Sede: {society_address}")
    c.drawString(2.3*cm, y - 1.65*cm, f"C.F.: {society_fiscal_code}")
    c.drawString(2.3*cm, y - 2.15*cm, f"Email: {society_email}")
    
    y -= 3.6*cm
    
    # Intro
    c.setFont("Helvetica", 10)
    intro_text = f"Gentile Genitore/Tutore, la presente informativa descrive le modalità di trattamento dei dati personali del minore da parte della società sportiva {nome_legale}."
    y = draw_wrapped_text(c, intro_text, 2*cm, y, max_w)
    y -= 0.3*cm
    titolare_intro = "Il Titolare del trattamento dei dati personali è la società sportiva sopra indicata nella persona del proprio legale rappresentante pro tempore."
    y = draw_wrapped_text(c, titolare_intro, 2*cm, y, max_w)
    
    y -= 0.5*cm
    
    # Section 1 - Finalità
    c.setFont("Helvetica-Bold", 11)
    c.drawString(2*cm, y, "1. FINALITÀ DEL TRATTAMENTO")
    y -= 0.5*cm
    c.setFont("Helvetica", 10)
    c.drawString(2*cm, y, "I dati personali del minore e del genitore/tutore saranno trattati per:")
    y -= 0.45*cm
    finalita = [
        "- gestione dell'iscrizione e partecipazione alle attività sportive;",
        "- adempimento degli obblighi previsti dalle normative sportive e assicurative;",
        "- comunicazioni con federazioni sportive, enti di promozione sportiva e organismi sportivi;",
        "- gestione delle presenze ad allenamenti e attività sportive;",
        "- comunicazioni organizzative con le famiglie;",
        "- gestione amministrativa e fiscale delle attività sportive."
    ]
    for f in finalita:
        y = draw_wrapped_text(c, f, 2.3*cm, y, max_w - 0.3*cm)
    
    y -= 0.3*cm
    
    # Section 2 - Tipologia dati
    c.setFont("Helvetica-Bold", 11)
    c.drawString(2*cm, y, "2. TIPOLOGIA DI DATI TRATTATI")
    y -= 0.5*cm
    c.setFont("Helvetica", 10)
    c.drawString(2*cm, y, "La società potrà trattare le seguenti categorie di dati:")
    y -= 0.5*cm
    c.setFont("Helvetica-Bold", 10)
    c.drawString(2*cm, y, "Dati del minore:")
    y -= 0.4*cm
    c.setFont("Helvetica", 10)
    dati_minore = [
        "- nome e cognome",
        "- data di nascita",
        "- codice fiscale",
        "- recapito telefonico (se presente)",
        "- dati relativi alla partecipazione alle attività sportive"
    ]
    for d in dati_minore:
        c.drawString(2.3*cm, y, d)
        y -= 0.4*cm
    
    y -= 0.2*cm
    c.setFont("Helvetica-Bold", 10)
    c.drawString(2*cm, y, "Dati del genitore/tutore:")
    y -= 0.4*cm
    c.setFont("Helvetica", 10)
    dati_genitore = [
        "- nome e cognome",
        "- codice fiscale",
        "- telefono",
        "- email",
        "- indirizzo"
    ]
    for d in dati_genitore:
        c.drawString(2.3*cm, y, d)
        y -= 0.4*cm
    
    y -= 0.2*cm
    cf_nota = "Il codice fiscale del genitore/tutore può essere utilizzato anche ai fini della detrazione fiscale delle spese sportive prevista dalla normativa vigente."
    y = draw_wrapped_text(c, cf_nota, 2*cm, y, max_w)
    
    y -= 0.3*cm
    
    # Section 3 - Modalità (was Section 4)
    c.setFont("Helvetica-Bold", 11)
    c.drawString(2*cm, y, "3. MODALITÀ DI TRATTAMENTO")
    y -= 0.5*cm
    c.setFont("Helvetica", 10)
    modalita_text = "Il trattamento dei dati avviene mediante strumenti informatici e/o cartacei con modalità idonee a garantire la sicurezza e la riservatezza dei dati personali. La società può utilizzare applicativi gestionali informatici per l'organizzazione delle attività sportive e amministrative. L'accesso ai dati è consentito esclusivamente ai soggetti autorizzati dalla società."
    y = draw_wrapped_text(c, modalita_text, 2*cm, y, max_w)
    
    y -= 0.3*cm
    
    # Section 4 - Conservazione
    c.setFont("Helvetica-Bold", 11)
    c.drawString(2*cm, y, "4. PERIODO DI CONSERVAZIONE")
    y -= 0.5*cm
    c.setFont("Helvetica", 10)
    conservazione_text = "I dati saranno conservati per tutta la durata del rapporto sportivo con la società e successivamente per il periodo necessario all'adempimento degli obblighi legali, amministrativi e sportivi previsti dalla normativa vigente."
    y = draw_wrapped_text(c, conservazione_text, 2*cm, y, max_w)
    
    y -= 0.3*cm
    
    # Section 5 - Diritti
    c.setFont("Helvetica-Bold", 11)
    c.drawString(2*cm, y, "5. DIRITTI DELL'INTERESSATO")
    y -= 0.5*cm
    c.setFont("Helvetica", 10)
    c.drawString(2*cm, y, "Il genitore/tutore può esercitare i diritti previsti dagli articoli 15-22 del GDPR, tra cui:")
    y -= 0.45*cm
    diritti = [
        "- accesso ai dati",
        "- rettifica",
        "- cancellazione",
        "- limitazione del trattamento",
        "- opposizione",
        "- portabilità dei dati."
    ]
    for d in diritti:
        c.drawString(2.3*cm, y, d)
        y -= 0.4*cm
    
    # Footer page 1
    c.setFont("Helvetica", 8)
    c.drawCentredString(width/2, 1.5*cm, "Pagina 1 di 3")
    
    c.showPage()
    
    # ==================== PAGE 2 ====================
    y = height - 2*cm
    
    # Section 6 - Immagini e Video
    c.setFont("Helvetica-Bold", 11)
    c.drawString(2*cm, y, "6. UTILIZZO DI IMMAGINI E VIDEO")
    y -= 0.5*cm
    c.setFont("Helvetica", 10)
    immagini_text = "Durante le attività sportive potranno essere realizzate fotografie o riprese video degli atleti. Le immagini potranno essere utilizzate solo previo consenso specifico del genitore/tutore per le seguenti finalità:"
    y = draw_wrapped_text(c, immagini_text, 2*cm, y, max_w)
    
    y -= 0.3*cm
    c.setFont("Helvetica", 10)
    y = draw_wrapped_text(c, "a) Uso interno: documentazione delle attività, comunicazioni alle famiglie, archivio della società.", 2.3*cm, y, max_w - 0.3*cm)
    y -= 0.15*cm
    y = draw_wrapped_text(c, "b) Uso promozionale: sito web, social network, materiale informativo della società.", 2.3*cm, y, max_w - 0.3*cm)
    
    y -= 0.4*cm
    riprese_ctx = "Eventuali riprese di contesto durante eventi, gare o manifestazioni sportive che includano il minore come parte del gruppo non richiedono consenso specifico, in quanto necessarie alla documentazione dell'attività sportiva."
    y = draw_wrapped_text(c, riprese_ctx, 2*cm, y, max_w)
    
    # Show expressed consents in the image section
    y -= 0.5*cm
    cd = consent_data or {}
    c.setFont("Helvetica-Bold", 10)
    c.drawString(2*cm, y, "Consensi espressi dal genitore/tutore:")
    y -= 0.45*cm
    c.setFont("Helvetica", 10)
    
    check_ii = "X" if cd.get("images_internal", False) else " "
    consent_ii_text = "ACCONSENTO" if cd.get("images_internal", False) else "NON ACCONSENTO"
    c.drawString(2.3*cm, y, f"[{check_ii}] Utilizzo immagini per uso interno: {consent_ii_text}")
    y -= 0.45*cm
    
    check_ip = "X" if cd.get("images_promo", False) else " "
    consent_ip_text = "ACCONSENTO" if cd.get("images_promo", False) else "NON ACCONSENTO"
    c.drawString(2.3*cm, y, f"[{check_ip}] Utilizzo immagini per finalità promozionali: {consent_ip_text}")
    y -= 0.45*cm
    
    c.setFont("Helvetica", 9)
    c.setFillColor(colors.HexColor("#666666"))
    y = draw_wrapped_text(c, "I consensi sopra indicati sono facoltativi e possono essere revocati in qualsiasi momento.", 2*cm, y, max_w, font_size=9)
    c.setFillColor(colors.black)
    
    y -= 0.3*cm
    
    # Section 7 - Attestazione
    c.setFont("Helvetica-Bold", 11)
    c.drawString(2*cm, y, "7. ATTESTAZIONE DI PRESA VISIONE E CONSENSI")
    y -= 0.5*cm
    c.setFont("Helvetica", 10)
    firma_text = "La presa visione del presente documento può avvenire in forma digitale tramite l'applicativo gestionale utilizzato dalla società. Il sistema registra metadati tecnici della presa visione, tra cui data, ora e identificativo dell'utente, ai fini della tracciabilità e della sicurezza del sistema."
    y = draw_wrapped_text(c, firma_text, 2*cm, y, max_w)
    
    # Footer page 2
    c.setFont("Helvetica", 8)
    c.drawCentredString(width/2, 1.5*cm, "Pagina 2 di 3")
    
    c.showPage()
    
    # ==================== PAGE 3 ====================
    y = height - 2*cm
    
    # DICHIARAZIONE
    c.setFont("Helvetica-Bold", 11)
    c.drawString(2*cm, y, "DICHIARAZIONE")
    y -= 0.5*cm
    c.setFont("Helvetica", 10)
    dichiarazione_text = "Il sottoscritto genitore/tutore dichiara di aver preso visione dell'informativa e prende atto del trattamento dei dati del minore ai sensi del Regolamento UE 2016/679."
    y = draw_wrapped_text(c, dichiarazione_text, 2*cm, y, max_w)
    
    y -= 0.8*cm
    
    # PRESA VISIONE (obbligatoria)
    cd = consent_data or {}
    c.setFont("Helvetica-Bold", 11)
    c.drawString(2*cm, y, "PRESA VISIONE (obbligatoria)")
    y -= 0.5*cm
    c.setFont("Helvetica", 9)
    
    check_pv = "X" if cd.get("privacy_viewed", True) else " "
    c.drawString(2*cm, y, f"[{check_pv}] Ho preso visione dell'informativa privacy")
    y -= 0.6*cm
    
    # CONSENSI FACOLTATIVI (riepilogo - dettaglio in sezione 6)
    c.setFont("Helvetica-Bold", 11)
    c.drawString(2*cm, y, "CONSENSI FACOLTATIVI (cfr. Sezione 6)")
    y -= 0.5*cm
    c.setFont("Helvetica", 9)
    
    check_ii = "X" if cd.get("images_internal", False) else " "
    consent_ii_label = "ACCONSENTO" if cd.get("images_internal", False) else "NON ACCONSENTO"
    c.drawString(2*cm, y, f"[{check_ii}] Utilizzo immagini per uso interno: {consent_ii_label}")
    y -= 0.4*cm
    
    check_ip = "X" if cd.get("images_promo", False) else " "
    consent_ip_label = "ACCONSENTO" if cd.get("images_promo", False) else "NON ACCONSENTO"
    c.drawString(2*cm, y, f"[{check_ip}] Utilizzo immagini per finalità promozionali: {consent_ip_label}")
    y -= 0.5*cm
    
    # Nota revoca
    c.setFont("Helvetica-Oblique", 8)
    c.setFillColor(colors.HexColor("#666666"))
    c.drawString(2*cm, y, "La revoca dei consensi relativi alle immagini ha effetto solo per utilizzi futuri.")
    c.setFillColor(colors.black)
    y -= 0.4*cm
    
    c.setFont("Courier", 7)
    c.setFillColor(colors.HexColor("#888888"))
    c.drawString(2*cm, y, f"Versione doc: {cd.get('document_version', document_version)} | Timestamp: {timestamp} | IP: {ip_address}")
    c.setFillColor(colors.black)
    
    y -= 1*cm
    
    # Dati del genitore/tutore
    c.setStrokeColor(colors.HexColor("#27AE60"))
    c.setFillColor(colors.HexColor("#E8F8F5"))
    c.roundRect(2*cm, y - 2*cm, width - 4*cm, 2.5*cm, 5, fill=1, stroke=1)
    
    c.setFillColor(colors.black)
    c.setFont("Helvetica-Bold", 10)
    c.drawString(2.5*cm, y - 0.4*cm, "DATI DEL GENITORE/TUTORE")
    
    c.setFont("Helvetica", 10)
    y_box = y - 0.9*cm
    c.drawString(2.5*cm, y_box, f"Genitore/Tutore: {parent_surname} {parent_name}")
    y_box -= 0.45*cm
    c.drawString(2.5*cm, y_box, f"Codice Fiscale: {parent_fiscal_code}")
    
    y -= 3*cm
    
    # Minor data box
    c.setStrokeColor(colors.HexColor("#3498DB"))
    c.setFillColor(colors.HexColor("#EBF5FB"))
    c.roundRect(2*cm, y - 2.5*cm, width - 4*cm, 3*cm, 5, fill=1, stroke=1)
    
    c.setFillColor(colors.black)
    c.setFont("Helvetica-Bold", 10)
    c.drawString(2.5*cm, y - 0.4*cm, "DATI DEL MINORE")
    
    c.setFont("Helvetica", 10)
    y_box = y - 0.9*cm
    c.drawString(2.5*cm, y_box, f"Minore: {minor_surname} {minor_name}")
    y_box -= 0.45*cm
    c.drawString(2.5*cm, y_box, f"Codice Fiscale: {minor_fiscal_code}")
    y_box -= 0.45*cm
    c.drawString(2.5*cm, y_box, f"Nato/a a {minor_birth_place} il {minor_birth_date}")
    y_box -= 0.45*cm
    c.drawString(2.5*cm, y_box, f"Società sportiva: {society_name}")
    
    y -= 4*cm
    
    # Signature
    c.setFont("Helvetica-Bold", 10)
    c.drawString(2*cm, y, "Firma digitale del Genitore/Tutore:")
    
    y -= 0.5*cm
    
    # Draw signature
    if signature_base64 and HAS_PIL:
        try:
            if ',' in signature_base64:
                signature_base64_clean = signature_base64.split(',')[1]
            else:
                signature_base64_clean = signature_base64
            
            sig_data = base64.b64decode(signature_base64_clean)
            sig_image = Image.open(io.BytesIO(sig_data))
            
            if sig_image.mode != 'RGB':
                if sig_image.mode == 'RGBA':
                    background = Image.new('RGB', sig_image.size, (255, 255, 255))
                    background.paste(sig_image, mask=sig_image.split()[3])
                    sig_image = background
                else:
                    sig_image = sig_image.convert('RGB')
            
            sig_buffer = io.BytesIO()
            sig_image.save(sig_buffer, format='PNG')
            sig_buffer.seek(0)
            
            from reportlab.lib.utils import ImageReader
            img_reader = ImageReader(sig_buffer)
            c.drawImage(img_reader, 2*cm, y - 2*cm, width=6*cm, height=2*cm, preserveAspectRatio=True)
        except Exception as e:
            logging.error(f"Error adding signature: {e}")
    
    y -= 2.5*cm
    
    # Technical metadata box
    c.setFont("Helvetica-Bold", 9)
    c.drawString(2*cm, y, "METADATI ACCETTAZIONE (validità probatoria)")
    y -= 0.4*cm
    
    c.setStrokeColor(colors.HexColor("#2C3E50"))
    c.setFillColor(colors.HexColor("#ECF0F1"))
    c.roundRect(2*cm, y - 3.5*cm, width - 4*cm, 3.5*cm, 3, fill=1, stroke=1)
    
    c.setFillColor(colors.black)
    c.setFont("Courier", 8)
    y_meta = y - 0.4*cm
    c.drawString(2.3*cm, y_meta, f"document_version: {document_version}")
    y_meta -= 0.35*cm
    c.drawString(2.3*cm, y_meta, f"document_name: privacy_minore_v{document_version}")
    y_meta -= 0.35*cm
    c.drawString(2.3*cm, y_meta, f"timestamp: {timestamp}")
    y_meta -= 0.35*cm
    c.drawString(2.3*cm, y_meta, f"user_id: {user_id}")
    y_meta -= 0.35*cm
    c.drawString(2.3*cm, y_meta, f"society_id: {society_id}")
    y_meta -= 0.35*cm
    c.drawString(2.3*cm, y_meta, f"hash_document: {document_hash}")
    y_meta -= 0.35*cm
    c.drawString(2.3*cm, y_meta, f"device_type: {user_agent[:60]}..." if len(user_agent) > 60 else f"device_type: {user_agent}")
    y_meta -= 0.35*cm
    c.drawString(2.3*cm, y_meta, f"ip_address: {ip_address}")
    
    # Footer bottom of page 3
    c.setFont("Helvetica", 8)
    c.setFillColor(colors.black)
    c.drawCentredString(width/2, 1.5*cm, "Pagina 3 di 3")

    # 🆕 QR code (bottom-right) — verifica autenticità della firma
    if document_id:
        try:
            verify_url = _public_verify_url(document_id)
            qr_png = _generate_qr_png(verify_url)
            if qr_png:
                from reportlab.lib.utils import ImageReader
                qr_reader = ImageReader(io.BytesIO(qr_png))
                qr_size = 2.2 * cm
                qr_x = width - qr_size - 1.5 * cm
                qr_y = 0.8 * cm
                c.drawImage(qr_reader, qr_x, qr_y, width=qr_size, height=qr_size, preserveAspectRatio=True, mask='auto')
                c.setFont("Helvetica", 6)
                c.setFillColorRGB(0.4, 0.4, 0.4)
                c.drawCentredString(qr_x + qr_size / 2, qr_y - 0.2 * cm, "Verifica autenticità")
                c.setFillColorRGB(0, 0, 0)
        except Exception:
            pass
    
    c.save()
    return buffer.getvalue()



def generate_personal_consent_pdf(
    consent_type: str,
    society_name: str,
    ragione_sociale: str,
    society_address: str,
    society_fiscal_code: str,
    society_email: str,
    parent_name: str,
    parent_fiscal_code: str,
    timestamp: str,
    ip_address: str,
    document_version: str,
    user_id: str,
    society_id: str,
    source: str = "registration",
) -> bytes:
    """Generate a multi-page PDF: Page 1+ = full document text, Last page = acceptance & metadata"""
    if not HAS_PDF_GENERATION:
        raise HTTPException(status_code=500, detail="PDF generation not available")

    nome_legale = ragione_sociale if ragione_sociale else society_name

    # Document titles and full texts
    titles = {
        "privacy_viewed": "INFORMATIVA SULLA PRIVACY",
        "data_processing": "PRESA VISIONE TRATTAMENTO DATI PERSONALI",
        "terms": "TERMINI DI UTILIZZO",
    }

    privacy_sections = [
        ("1. Introduzione", "RegistraTEAM e un'applicazione progettata per supportare associazioni sportive dilettantistiche nella gestione delle squadre, delle presenze e delle attivita amministrative."),
        ("2. Titolare del trattamento", "Il titolare del trattamento e l'associazione sportiva che utilizza l'applicazione."),
        ("3. Responsabile del trattamento", "RegistraTEAM fornisce l'infrastruttura tecnica e puo operare come responsabile del trattamento per attivita tecniche e manutenzione."),
        ("4. Dati trattati", "- Nome e cognome\n- Squadra di appartenenza\n- Presenze agli allenamenti\n- Email\n- Numero di telefono\n- Identificativo QR\n- Dati relativi ai pagamenti (importo, data, numero rata, stato pagamento)\n- Informazioni relative all'idoneita sportiva (tipologia certificato, data emissione, validita, scadenza)\n- Log tecnici"),
        ("5. Finalita", "- Gestione atleti e squadre\n- Registrazione presenze\n- Accesso all'app (login)\n- Comunicazioni tra utenti\n- Invio notifiche\n- Gestione quote associative\n- Generazione attestati per uso amministrativo/fiscale"),
        ("6. Infrastruttura", "I dati sono archiviati su server situati nell'Unione Europea."),
        ("7. Conservazione", "I dati sono conservati per il tempo necessario alle attivita sportive e amministrative."),
        ("8. Sicurezza", "Sono adottate misure tecniche adeguate per proteggere i dati."),
        ("9. Condivisione dei dati", "I dati non vengono venduti e sono accessibili solo a personale autorizzato e amministratori tecnici."),
        ("10. Riprese fotografiche e video", "Durante eventi, gare, allenamenti e manifestazioni sportive potranno essere effettuate riprese fotografiche e video a fini documentativi e informativi. La presenza in tali contesti comporta la possibilita di essere ripresi sullo sfondo delle immagini. Tale trattamento si fonda sul legittimo interesse della Societa. Per eventuali utilizzi promozionali specifici (es. pubblicazione su sito web o social network), sara richiesto apposito consenso. L'interessato ha il diritto di richiedere la rimozione di immagini in cui appare, contattando la Societa."),
        ("11. Diritti", "Gli utenti possono esercitare i diritti GDPR rivolgendosi all'associazione."),
        ("12. Modifiche", "La policy puo essere aggiornata nel tempo."),
        ("13. Contatti", "Contattare l'associazione sportiva o il servizio RegistraTEAM."),
    ]

    terms_sections = [
        ("1. Oggetto", "RegistraTEAM e un software gestionale per associazioni sportive dilettantistiche."),
        ("2. Natura del servizio", "Il software e fornito nello stato in cui si trova, senza garanzia di assenza totale di errori o interruzioni."),
        ("3. Utilizzo", "L'app e utilizzata sotto la responsabilita dell'associazione sportiva."),
        ("4. Dati e responsabilita", "L'associazione e responsabile della correttezza dei dati e del rispetto delle normative."),
        ("5. Presenze", "Le presenze hanno valore organizzativo e statistico."),
        ("6. Pagamenti", "I dati relativi ai pagamenti sono inseriti e gestiti dall'associazione. RegistraTEAM non e responsabile per errori nei dati, anche per usi amministrativi o fiscali."),
        ("7. Limitazione di responsabilita", "Il fornitore non e responsabile per perdite di dati o danni indiretti."),
        ("8. Backup", "La gestione dei dati e responsabilita dell'associazione."),
        ("9. Condizioni economiche", "RegistraTEAM e disponibile gratuitamente e senza limiti di funzionalita:\n\n- fino al 30 settembre 2026 con un limite massimo di 150 utenti registrati (atleti, staff, genitori) per societa;\n- successivamente con limite massimo di 30 utenti registrati per societa nella versione gratuita.\n\nSuperati i limiti indicati, sara necessario sottoscrivere un piano a pagamento. Prezzi e condizioni saranno comunicati tramite l'app o il sito ufficiale."),
        ("10. Modifiche", "Il servizio puo essere aggiornato nel tempo."),
        ("11. Accettazione", "L'utilizzo dell'app implica l'accettazione dei presenti termini."),
    ]

    data_processing_sections = [
        ("Premessa", f"Il/La sottoscritto/a {parent_name}, in qualita di utente della piattaforma RegistraTEAM della societa sportiva {nome_legale}, dichiara quanto segue."),
        ("Oggetto del consenso", "Il presente consenso riguarda il trattamento dei dati personali come descritto nell'Informativa sulla Privacy della societa sportiva, ai sensi del Regolamento UE 2016/679 (GDPR)."),
        ("Dati oggetto del trattamento", "- Nome e cognome\n- Email e numero di telefono\n- Codice fiscale\n- Dati relativi alle presenze\n- Dati relativi ai pagamenti\n- Informazioni sull'idoneita sportiva\n- Eventuali immagini (solo se specificamente autorizzate)"),
        ("Finalita del trattamento", "I dati saranno trattati esclusivamente per:\n- Gestione dell'iscrizione e della partecipazione alle attivita sportive\n- Comunicazioni tra societa, allenatori e famiglie\n- Adempimenti amministrativi e fiscali\n- Gestione delle presenze e delle quote associative"),
        ("Durata del trattamento", "I dati saranno conservati per il tempo strettamente necessario alle finalita sopra indicate e comunque non oltre i termini previsti dalla normativa vigente."),
        ("Diritti dell'interessato", "In qualsiasi momento e possibile esercitare i diritti previsti dagli artt. 15-22 del GDPR (accesso, rettifica, cancellazione, limitazione, portabilita, opposizione) contattando l'associazione sportiva."),
    ]

    sections_map = {
        "privacy_viewed": privacy_sections,
        "data_processing": data_processing_sections,
        "terms": terms_sections,
    }

    doc_title = titles.get(consent_type, "CONSENSO PERSONALE")
    sections = sections_map.get(consent_type, [])

    buffer = io.BytesIO()
    c = canvas.Canvas(buffer, pagesize=A4)
    w, h = A4
    margin_left = 2*cm
    margin_right = 2*cm
    max_w = w - margin_left - margin_right
    footer_y = 1.5*cm

    def draw_footer(canvas_obj, page_num):
        canvas_obj.setFont("Helvetica", 8)
        canvas_obj.setFillColor(colors.grey)
        canvas_obj.drawCentredString(w/2, footer_y, f"{nome_legale} - {doc_title} - Pagina {page_num}")
        canvas_obj.setFillColor(colors.black)

    def wrap_text(text, font_name, font_size, max_width):
        """Split text into lines that fit within max_width"""
        result_lines = []
        for raw_line in text.split('\n'):
            if not raw_line.strip():
                result_lines.append('')
                continue
            words = raw_line.split(' ')
            current = ""
            for word in words:
                test = current + " " + word if current else word
                if c.stringWidth(test, font_name, font_size) < max_width:
                    current = test
                else:
                    if current:
                        result_lines.append(current)
                    current = word
            if current:
                result_lines.append(current)
        return result_lines

    # ========== PAGE 1+: FULL DOCUMENT TEXT ==========
    page_num = 1

    # Header
    c.setFont("Helvetica-Bold", 16)
    c.drawCentredString(w/2, h - 2*cm, doc_title)
    c.setFont("Helvetica", 10)
    c.drawCentredString(w/2, h - 2.7*cm, f"(Regolamento UE 2016/679 - GDPR)")
    c.setFont("Helvetica", 9)
    c.drawCentredString(w/2, h - 3.2*cm, f"Societa: {nome_legale}")
    c.drawCentredString(w/2, h - 3.6*cm, f"Ultimo aggiornamento: Marzo 2026 - Versione {document_version}")

    y = h - 4.5*cm

    for sec_title, sec_text in sections:
        # Check if we need a new page
        if y < 4*cm:
            draw_footer(c, page_num)
            c.showPage()
            page_num += 1
            y = h - 2*cm

        # Section title
        c.setFont("Helvetica-Bold", 11)
        c.drawString(margin_left, y, sec_title)
        y -= 0.5*cm

        # Section text
        c.setFont("Helvetica", 10)
        lines = wrap_text(sec_text, "Helvetica", 10, max_w)
        for line in lines:
            if y < 3*cm:
                draw_footer(c, page_num)
                c.showPage()
                page_num += 1
                y = h - 2*cm
                c.setFont("Helvetica", 10)
            c.drawString(margin_left, y, line)
            y -= 0.38*cm

        y -= 0.4*cm  # Space between sections

    draw_footer(c, page_num)

    # ========== LAST PAGE: ACCEPTANCE DATA & METADATA ==========
    c.showPage()
    page_num += 1
    y = h - 2*cm

    c.setFont("Helvetica-Bold", 14)
    c.drawCentredString(w/2, y, "ATTESTAZIONE DI ACCETTAZIONE")
    y -= 0.7*cm
    c.setFont("Helvetica", 10)
    c.drawCentredString(w/2, y, f"Riferito a: {doc_title}")
    y -= 1.2*cm

    # Society data box
    c.setStrokeColor(colors.HexColor("#1565C0"))
    c.setFillColor(colors.HexColor("#E3F2FD"))
    c.roundRect(margin_left, y - 3.0*cm, max_w, 2.8*cm, 5, stroke=1, fill=1)
    c.setFillColor(colors.black)
    c.setFont("Helvetica-Bold", 10)
    c.drawString(margin_left + 0.3*cm, y - 0.6*cm, f"Societa: {nome_legale}")
    c.setFont("Helvetica", 9)
    c.drawString(margin_left + 0.3*cm, y - 1.15*cm, f"Sede: {society_address}")
    c.drawString(margin_left + 0.3*cm, y - 1.65*cm, f"C.F.: {society_fiscal_code}")
    c.drawString(margin_left + 0.3*cm, y - 2.15*cm, f"Email: {society_email}")
    y -= 3.6*cm

    # Parent data box
    c.setStrokeColor(colors.HexColor("#2E7D32"))
    c.setFillColor(colors.HexColor("#E8F5E9"))
    c.roundRect(margin_left, y - 1.8*cm, max_w, 1.8*cm, 5, stroke=1, fill=1)
    c.setFillColor(colors.black)
    c.setFont("Helvetica-Bold", 10)
    c.drawString(margin_left + 0.3*cm, y - 0.5*cm, "DATI DEL GENITORE/TUTORE")
    c.setFont("Helvetica", 9)
    c.drawString(margin_left + 0.3*cm, y - 1.05*cm, f"Genitore/Tutore: {parent_name}")
    c.drawString(margin_left + 0.3*cm, y - 1.55*cm, f"Codice Fiscale: {parent_fiscal_code}")
    y -= 2.8*cm

    # Digital acceptance box
    c.setFont("Helvetica-Bold", 11)
    c.drawString(margin_left, y, "Accettazione digitale:")
    y -= 0.8*cm

    c.setStrokeColor(colors.HexColor("#4CAF50"))
    c.setLineWidth(1.5)
    c.roundRect(margin_left, y - 2.5*cm, max_w, 2.5*cm, 5, stroke=1, fill=0)

    c.setFont("Helvetica", 10)
    c.drawString(margin_left + 0.5*cm, y - 0.5*cm, f"Presa visione da: {parent_name}")
    c.drawString(margin_left + 0.5*cm, y - 1.0*cm, f"Data: {timestamp}")
    method_label = "Accettazione alla registrazione" if source == "registration" else "Accettazione manuale da profilo"
    c.drawString(margin_left + 0.5*cm, y - 1.5*cm, f"Modalita: {method_label}")
    c.drawString(margin_left + 0.5*cm, y - 2.0*cm, f"Indirizzo IP: {ip_address}")
    y -= 3.8*cm

    # Metadata box
    c.setFont("Helvetica-Bold", 9)
    c.drawString(margin_left, y, "METADATI ACCETTAZIONE (validita probatoria)")
    y -= 0.4*cm

    c.setStrokeColor(colors.HexColor("#2C3E50"))
    c.setFillColor(colors.HexColor("#ECF0F1"))
    c.roundRect(margin_left, y - 3*cm, max_w, 3*cm, 3, fill=1, stroke=1)

    c.setFillColor(colors.black)
    c.setFont("Courier", 8)
    ym = y - 0.4*cm
    import hashlib
    hash_input = f"{consent_type}:{user_id}:{timestamp}:{document_version}"
    doc_hash = hashlib.sha256(hash_input.encode()).hexdigest()
    meta_lines = [
        f"document_version: {document_version}",
        f"timestamp: {timestamp}",
        f"user_id: {user_id}",
        f"society_id: {society_id}",
        f"hash_document: {doc_hash}",
        f"consent_type: {consent_type}",
        f"ip_address: {ip_address}",
    ]
    for ml in meta_lines:
        c.drawString(margin_left + 0.3*cm, ym, ml)
        ym -= 0.35*cm

    draw_footer(c, page_num)

    # Footer
    c.setFont("Helvetica", 8)
    c.setFillColor(colors.grey)
    c.drawCentredString(w/2, 1*cm, "Documento generato automaticamente con validita probatoria ai sensi del GDPR.")
    c.drawCentredString(w/2, 0.6*cm, f"Generato il {datetime.now(timezone.utc).strftime('%d/%m/%Y alle %H:%M:%S UTC')}")

    c.save()
    buffer.seek(0)
    return buffer.getvalue()



def generate_privacy_consent_pdf(
    society_name: str,
    signer_name: str,
    signer_role: str,
    fiscal_code: str,
    birth_date: str,
    birth_place: str,
    address: str,
    city: str,
    province: str,
    signature_base64: str,
    consent_data: dict = None
) -> bytes:
    """Generate privacy consent PDF with professional formatting like receipt"""
    if not HAS_PDF_GENERATION:
        raise HTTPException(status_code=500, detail="PDF generation not available")
    
    if consent_data is None:
        consent_data = {"privacy_viewed": True, "images_internal": None, "images_promo": None}
    
    buffer = io.BytesIO()
    c = canvas.Canvas(buffer, pagesize=A4)
    width, height = A4
    
    timestamp = to_rome_time(datetime.now(timezone.utc)).strftime("%d/%m/%Y")
    
    # Title - centered, bold
    c.setFont("Helvetica-Bold", 14)
    title = "PRESA VISIONE INFORMATIVA PRIVACY"
    c.drawCentredString(width/2, height - 3*cm, title)
    
    c.setFont("Helvetica", 9)
    c.drawCentredString(width/2, height - 3.6*cm, "(ai sensi del Regolamento UE 2016/679 - GDPR)")
    
    # Society name
    c.setFont("Helvetica", 11)
    y = height - 5*cm
    c.drawString(2*cm, y, f"ASD/SSD: {society_name}")
    
    # Role label
    role_labels = {
        'coach': 'Allenatore/Coach',
        'dirigente': 'Dirigente',
        'collaboratore': 'Collaboratore',
        'genitore': 'Genitore',
        'atleta': 'Atleta'
    }
    role_label = role_labels.get(signer_role, signer_role.capitalize() if signer_role else 'Utente')
    
    # Signer info
    y -= 1*cm
    c.drawString(2*cm, y, f"{role_label}: {signer_name}")
    
    y -= 0.6*cm
    c.drawString(2*cm, y, f"Codice Fiscale: {fiscal_code or '________________________'}")
    
    if birth_date or birth_place:
        y -= 0.6*cm
        birth_info = f"Nato/a"
        if birth_place:
            birth_info += f" a {birth_place}"
        if birth_date:
            birth_info += f" il {birth_date}"
        c.drawString(2*cm, y, birth_info)
    
    if address or city:
        y -= 0.6*cm
        address_info = "Residente in"
        if address:
            address_info += f" {address}"
        if city:
            address_info += f", {city}"
        if province:
            address_info += f" ({province})"
        c.drawString(2*cm, y, address_info)
    
    # Declaration section
    y -= 1.5*cm
    c.setFont("Helvetica-Bold", 11)
    c.drawString(2*cm, y, "DICHIARA")
    
    y -= 0.8*cm
    c.setFont("Helvetica", 10)
    declaration1 = "di aver ricevuto l'informativa ai sensi dell'art. 13 del Regolamento UE 2016/679 (GDPR) relativa al trattamento dei propri dati personali da parte della società sportiva sopra indicata."
    
    # Word wrap
    words = declaration1.split(' ')
    lines = []
    current_line = ""
    max_width = width - 4*cm
    for word in words:
        test_line = current_line + " " + word if current_line else word
        if c.stringWidth(test_line, "Helvetica", 10) < max_width:
            current_line = test_line
        else:
            lines.append(current_line)
            current_line = word
    if current_line:
        lines.append(current_line)
    
    for line in lines:
        c.drawString(2*cm, y, line)
        y -= 0.5*cm
    
    # Consent section
    y -= 0.8*cm
    c.setFont("Helvetica-Bold", 11)
    c.drawString(2*cm, y, "PRESA VISIONE (obbligatoria)")
    
    y -= 0.8*cm
    c.setFont("Helvetica", 10)
    
    # 1. Presa visione informativa (obbligatorio)
    check_privacy = "X" if consent_data.get("privacy_viewed", True) else " "
    c.drawString(2*cm, y, f"[{check_privacy}] Ho preso visione dell'informativa privacy")
    y -= 0.8*cm
    
    # Consensi facoltativi
    c.setFont("Helvetica-Bold", 11)
    c.drawString(2*cm, y, "CONSENSI FACOLTATIVI")
    y -= 0.8*cm
    
    # Immagini uso promozionale (facoltativo)
    c.setFont("Helvetica", 10)
    check_img_promo = "X" if consent_data.get("images_promo", False) else " "
    c.drawString(2*cm, y, f"[{check_img_promo}] Utilizzo immagini a scopo promozionale (sito, social, materiale pubblicitario)")
    y -= 0.5*cm
    
    # Nota riprese di contesto
    c.setFont("Helvetica-Oblique", 9)
    c.setFillColor(colors.HexColor("#333333"))
    c.drawString(2*cm, y, "Nota: durante eventi, gare e manifestazioni sportive potranno essere effettuate")
    y -= 0.4*cm
    c.drawString(2*cm, y, "riprese fotografiche e video a fini documentativi. Per utilizzi promozionali specifici")
    y -= 0.4*cm
    c.drawString(2*cm, y, "sara' richiesto apposito consenso.")
    c.setFillColor(colors.black)
    y -= 0.5*cm
    
    # Nota revoca
    c.setFont("Helvetica-Oblique", 8)
    c.setFillColor(colors.HexColor("#666666"))
    c.drawString(2*cm, y, "La revoca dei consensi relativi alle immagini ha effetto solo per utilizzi futuri.")
    c.setFillColor(colors.black)
    y -= 0.5*cm
    
    # Consent metadata
    y -= 0.5*cm
    c.setFont("Courier", 7)
    c.setFillColor(colors.HexColor("#666666"))
    c.drawString(2*cm, y, f"Versione documento: {consent_data.get('document_version', '1.0-2026')}")
    y -= 0.3*cm
    c.drawString(2*cm, y, f"Data consenso: {consent_data.get('timestamp', timestamp)}")
    y -= 0.3*cm
    c.drawString(2*cm, y, f"User ID: {consent_data.get('user_id', 'N/A')}")
    y -= 0.3*cm
    c.drawString(2*cm, y, f"IP: {consent_data.get('ip_address', 'N/A')}")
    c.setFillColor(colors.black)
    
    # Signature section
    y -= 2*cm
    c.setFont("Helvetica", 10)
    c.drawString(2*cm, y, f"Data: {timestamp}")
    c.drawString(width - 8*cm, y, f"Firma {role_label.lower()}:")
    
    # Add signature image
    if signature_base64 and HAS_PIL:
        try:
            if ',' in signature_base64:
                signature_base64 = signature_base64.split(',')[1]
            
            sig_data = base64.b64decode(signature_base64)
            sig_image = Image.open(io.BytesIO(sig_data))
            
            # Convert to RGB
            if sig_image.mode != 'RGB':
                if sig_image.mode == 'RGBA':
                    background = Image.new('RGB', sig_image.size, (255, 255, 255))
                    background.paste(sig_image, mask=sig_image.split()[3])
                    sig_image = background
                else:
                    sig_image = sig_image.convert('RGB')
            
            # Normalize colors
            pixels = sig_image.load()
            w, h = sig_image.size
            for py in range(h):
                for px in range(w):
                    r, g, b = pixels[px, py]
                    luminance = (r * 0.299 + g * 0.587 + b * 0.114)
                    if luminance < 200:
                        pixels[px, py] = (0, 0, 0)
                    else:
                        pixels[px, py] = (255, 255, 255)
            
            # 🔍 Auto-crop dei margini bianchi: la firma viene tracciata in un
            # canvas più ampio del tratto effettivo. Senza crop, dentro il box PDF
            # (5-6cm) il tratto verrebbe scalato proporzionalmente e risulterebbe
            # illeggibile (es. firma di Fede "piccolissima"). Ritagliamo al bbox
            # del nero, con padding minimo.
            try:
                from PIL import ImageOps as _ImageOps
                _bbox = _ImageOps.invert(sig_image.convert('L')).getbbox()
                if _bbox:
                    _pad = 15
                    _l = max(0, _bbox[0] - _pad)
                    _t = max(0, _bbox[1] - _pad)
                    _r = min(sig_image.width, _bbox[2] + _pad)
                    _b = min(sig_image.height, _bbox[3] + _pad)
                    sig_image = sig_image.crop((_l, _t, _r, _b))
            except Exception:
                pass
            
            sig_buffer = io.BytesIO()
            sig_image.save(sig_buffer, format='PNG')
            sig_buffer.seek(0)
            
            from reportlab.lib.utils import ImageReader
            img_reader = ImageReader(sig_buffer)
            c.drawImage(img_reader, width - 8*cm, y - 2.5*cm, width=6*cm, height=2*cm, preserveAspectRatio=True)
        except Exception as e:
            logging.error(f"Error adding signature: {e}")
    
    c.save()
    return buffer.getvalue()

def generate_threshold_5k_pdf(
    society_name: str,
    collaborator_name: str,
    collaborator_fiscal_code: str,
    year: int,
    signature_base64: str,
    society_city: str = "Perugia",
    threshold_metadata: dict = None,
    signed_at: Optional[Any] = None,
    threshold_month: Optional[int] = None,
    document_id: Optional[str] = None,
) -> bytes:
    """Generate €5,000 threshold communication PDF with metadata.

    Args:
      signed_at: Original signing timestamp (str ISO or datetime). If omitted,
                 falls back to today — should never happen for a signed doc.
      threshold_month: Month (1-12) when the threshold was crossed.
      document_id: If provided, embeds a QR code linking to the public verify page.
    """
    if not HAS_PDF_GENERATION:
        raise HTTPException(status_code=500, detail="PDF generation not available")
    
    buffer = io.BytesIO()
    c = canvas.Canvas(buffer, pagesize=A4)
    width, height = A4
    
    # Use original signing date (NOT generation date)
    signed_dt = None
    if signed_at:
        try:
            if isinstance(signed_at, str):
                signed_dt = datetime.fromisoformat(signed_at.replace("Z", "+00:00"))
            elif isinstance(signed_at, datetime):
                signed_dt = signed_at
        except Exception:
            signed_dt = None
    if signed_dt is None:
        signed_dt = datetime.now(timezone.utc)
    timestamp = to_rome_time(signed_dt).strftime("%d/%m/%Y %H:%M:%S")
    
    # Name is already stored as "COGNOME NOME" in database - use as-is
    formatted_name = collaborator_name
    
    # Title - centered, bold
    c.setFont("Helvetica-Bold", 12)
    title1 = "COMUNICAZIONE DI SUPERAMENTO DELLA SOGLIA PREVIDENZIALE"
    title2 = "DI COMPENSI SPORTIVI DILETTANTISTICI DI € 5.000,00 (Cinquemila/00)"
    c.drawCentredString(width/2, height - 2.5*cm, title1)
    c.drawCentredString(width/2, height - 3.2*cm, title2)

    # Intro
    y = height - 4.5*cm
    c.setFont("Helvetica", 11)
    c.drawString(2*cm, y, "Il/La sottoscritto/a")
    
    # Name and fiscal code - using "Cognome e Nome"
    y -= 0.8*cm
    c.drawString(2*cm, y, f"Cognome e Nome: {formatted_name}")
    
    y -= 0.6*cm
    c.drawString(2*cm, y, f"Codice Fiscale: {collaborator_fiscal_code or '________________________'}")
    
    # Relationship
    y -= 1*cm
    c.drawString(2*cm, y, "in relazione al rapporto di collaborazione sportiva dilettantistica con")
    
    y -= 0.6*cm
    c.drawString(2*cm, y, f"ASD/SSD: {society_name}")
    
    # COMUNICA - centered, spaced
    y -= 1.5*cm
    c.setFont("Helvetica-Bold", 14)
    c.drawCentredString(width/2, y, "C O M U N I C A")
    
    # Communication text — prepended with the receipt month that crossed the threshold.
    y -= 1.2*cm
    c.setFont("Helvetica", 10)
    prefix = ""
    try:
        if threshold_month and 1 <= int(threshold_month) <= 12:
            prefix = f"Con la quietanza del mese di {MONTH_NAMES[int(threshold_month)]} {year}, "
    except Exception:
        pass
    text = (
        f"{prefix}il totale dei compensi percepiti per attività sportiva dilettantistica "
        f"nell'anno solare {year}, anche da altri enti sportivi, ha raggiunto e/o superato "
        f"l'importo complessivo di € 5.000,00."
    )
    
    # Word wrap
    words = text.split(' ')
    lines = []
    current_line = ""
    max_width = width - 4*cm
    for word in words:
        test_line = current_line + " " + word if current_line else word
        if c.stringWidth(test_line, "Helvetica", 10) < max_width:
            current_line = test_line
        else:
            lines.append(current_line)
            current_line = word
    if current_line:
        lines.append(current_line)
    
    for line in lines:
        c.drawString(2*cm, y, line)
        y -= 0.5*cm
    
    # Declaration paragraphs
    y -= 0.8*cm
    decl1 = "Il sottoscritto dichiara di essere a conoscenza che, dal momento del superamento della suddetta soglia, i compensi eccedenti sono soggetti agli obblighi previdenziali previsti dalla normativa vigente."
    
    words = decl1.split(' ')
    lines = []
    current_line = ""
    for word in words:
        test_line = current_line + " " + word if current_line else word
        if c.stringWidth(test_line, "Helvetica", 10) < max_width:
            current_line = test_line
        else:
            lines.append(current_line)
            current_line = word
    if current_line:
        lines.append(current_line)
    
    for line in lines:
        c.drawString(2*cm, y, line)
        y -= 0.5*cm
    
    y -= 0.5*cm
    decl2 = "Si impegna inoltre a comunicare tempestivamente eventuali ulteriori variazioni della propria situazione."
    c.drawString(2*cm, y, decl2)
    
    # Signature section
    y -= 2*cm
    c.drawString(2*cm, y, f"Luogo e data: {society_city}, {timestamp}")
    c.drawString(width - 7*cm, y, "Firma:")
    
    # Add signature image
    if signature_base64 and HAS_PIL:
        try:
            if ',' in signature_base64:
                signature_base64 = signature_base64.split(',')[1]
            
            sig_data = base64.b64decode(signature_base64)
            sig_image = Image.open(io.BytesIO(sig_data))
            
            if sig_image.mode != 'RGB':
                if sig_image.mode == 'RGBA':
                    background = Image.new('RGB', sig_image.size, (255, 255, 255))
                    background.paste(sig_image, mask=sig_image.split()[3])
                    sig_image = background
                else:
                    sig_image = sig_image.convert('RGB')
            
            pixels = sig_image.load()
            w, h = sig_image.size
            for py in range(h):
                for px in range(w):
                    r, g, b = pixels[px, py]
                    luminance = (r * 0.299 + g * 0.587 + b * 0.114)
                    if luminance < 200:
                        pixels[px, py] = (0, 0, 0)
                    else:
                        pixels[px, py] = (255, 255, 255)
            
            # 🔍 Auto-crop dei margini bianchi: la firma viene tracciata in un
            # canvas più ampio del tratto effettivo. Senza crop, dentro il box PDF
            # (5-6cm) il tratto verrebbe scalato proporzionalmente e risulterebbe
            # illeggibile (es. firma di Fede "piccolissima"). Ritagliamo al bbox
            # del nero, con padding minimo.
            try:
                from PIL import ImageOps as _ImageOps
                _bbox = _ImageOps.invert(sig_image.convert('L')).getbbox()
                if _bbox:
                    _pad = 15
                    _l = max(0, _bbox[0] - _pad)
                    _t = max(0, _bbox[1] - _pad)
                    _r = min(sig_image.width, _bbox[2] + _pad)
                    _b = min(sig_image.height, _bbox[3] + _pad)
                    sig_image = sig_image.crop((_l, _t, _r, _b))
            except Exception:
                pass
            
            sig_buffer = io.BytesIO()
            sig_image.save(sig_buffer, format='PNG')
            sig_buffer.seek(0)
            
            from reportlab.lib.utils import ImageReader
            img_reader = ImageReader(sig_buffer)
            c.drawImage(img_reader, width - 7*cm, y - 2.5*cm, width=5*cm, height=2*cm, preserveAspectRatio=True)
        except Exception as e:
            logging.error(f"Error adding signature: {e}")
    
    # Add metadata section at the bottom
    if threshold_metadata:
        y = 3.5*cm
        c.setFont("Helvetica", 7)
        c.setFillColorRGB(0.4, 0.4, 0.4)
        c.drawString(2*cm, y, "─" * 80)
        y -= 0.4*cm
        c.drawString(2*cm, y, "METADATI DI VERIFICA (generati automaticamente)")
        y -= 0.35*cm
        c.drawString(2*cm, y, f"Timestamp firma: {threshold_metadata.get('signature_timestamp_rome', 'N/D')}")
        y -= 0.35*cm
        c.drawString(2*cm, y, f"Totale prima: € {threshold_metadata.get('yearly_total_before', 0):,.2f} | Totale dopo: € {threshold_metadata.get('yearly_total_after', 0):,.2f}")
        y -= 0.35*cm
        c.drawString(2*cm, y, f"Compensi pregressi dichiarati: € {threshold_metadata.get('prior_compensation_declared', 0):,.2f}")
        y -= 0.35*cm
        sig_hash = threshold_metadata.get('signature_hash', 'N/D')
        if sig_hash and len(sig_hash) > 20:
            sig_hash = sig_hash[:20] + "..."
        c.drawString(2*cm, y, f"Hash firma: {sig_hash}")

    # QR code (bottom-right) — links to public verify page
    if document_id:
        try:
            verify_url = _public_verify_url(document_id)
            qr_png = _generate_qr_png(verify_url)
            if qr_png:
                from reportlab.lib.utils import ImageReader
                qr_reader = ImageReader(io.BytesIO(qr_png))
                qr_size = 2.4 * cm
                qr_x = width - qr_size - 1.5 * cm
                qr_y = 0.8 * cm
                c.drawImage(qr_reader, qr_x, qr_y, width=qr_size, height=qr_size, preserveAspectRatio=True, mask='auto')
                c.setFont("Helvetica", 6)
                c.setFillColorRGB(0.4, 0.4, 0.4)
                c.drawCentredString(qr_x + qr_size / 2, qr_y - 0.2 * cm, "Verifica autenticità")
                c.setFillColorRGB(0, 0, 0)
        except Exception:
            pass

    c.save()
    return buffer.getvalue()

