# Calculate Codice Fiscale
class CalcolaCodiceFiscaleRequest(BaseModel):
    nome: str
    cognome: str
    data_nascita: str  # formato GG/MM/AAAA o YYYY-MM-DD
    luogo_nascita: str  # nome del comune o stato estero
    sesso: str  # M o F
    stato_nascita: Optional[str] = "Italia"  # Stato di nascita (default: Italia)

@api_router.post("/utils/calcola-cf")
async def calcola_codice_fiscale(data: CalcolaCodiceFiscaleRequest):
    """Calcola il Codice Fiscale italiano dato nome, cognome, data/luogo nascita e sesso"""
    if not CF_AVAILABLE:
        raise HTTPException(status_code=500, detail="Libreria codice fiscale non disponibile")
    
    try:
        # Converti la data nel formato corretto (GG/MM/AAAA)
        data_nascita = data.data_nascita
        if '-' in data_nascita:
            # Converte da YYYY-MM-DD a GG/MM/AAAA
            parts = data_nascita.split('-')
            if len(parts) == 3:
                data_nascita = f"{parts[2]}/{parts[1]}/{parts[0]}"
        
        # Se nato all'estero, usa lo stato come birthplace per il CF
        is_estero = data.stato_nascita and data.stato_nascita.upper() not in ('ITALIA', 'IT', '')
        birthplace = data.stato_nascita.upper() if is_estero else data.luogo_nascita
        
        # Map common Italian country names to names recognized by codicefiscale library
        country_map = {
            'CINA': 'REPUBBLICA POPOLARE CINESE',
            'RUSSIA': 'FEDERAZIONE RUSSA',
            'COREA DEL SUD': 'REPUBBLICA DI COREA',
            'COREA SUD': 'REPUBBLICA DI COREA',
            'COREA': 'REPUBBLICA DI COREA',
            'COREA DEL NORD': 'REPUBBLICA POPOLARE DEMOCRATICA DI COREA',
            'COREA NORD': 'REPUBBLICA POPOLARE DEMOCRATICA DI COREA',
            'INGHILTERRA': 'REGNO UNITO',
            'GRAN BRETAGNA': 'REGNO UNITO',
            'SCOZIA': 'REGNO UNITO',
            'GALLES': 'REGNO UNITO',
            'IRLANDA DEL NORD': 'REGNO UNITO',
            'USA': 'STATI UNITI D\'AMERICA',
            'STATI UNITI': 'STATI UNITI D\'AMERICA',
            'AMERICA': 'STATI UNITI D\'AMERICA',
            'MOLDAVIA': 'MOLDOVA',
            'OLANDA': 'PAESI BASSI',
            'REPUBBLICA CECA': 'CECA REPUBBLICA',
            'CECHIA': 'CECA REPUBBLICA',
            'VIETNAM': 'VIET NAM',
            'MACEDONIA': 'MACEDONIA DEL NORD',
            'EX REPUBBLICA JUGOSLAVA DI MACEDONIA': 'MACEDONIA DEL NORD',
            'CONGO': 'REPUBBLICA DEMOCRATICA DEL CONGO',
            'CITTÀ DEL VATICANO': 'STATO DELLA CITTA\' DEL VATICANO',
            'VATICANO': 'STATO DELLA CITTA\' DEL VATICANO',
        }
        if is_estero and birthplace in country_map:
            birthplace = country_map[birthplace]
        
        # Calcola il CF
        result = codicefiscale.encode(
            lastname=data.cognome.upper(),
            firstname=data.nome.upper(),
            gender=data.sesso.upper(),
            birthdate=data_nascita,
            birthplace=birthplace
        )
        
        if result:
            return {
                "codice_fiscale": result,
                "success": True
            }
        else:
            return {
                "codice_fiscale": None,
                "success": False,
                "error": "Impossibile calcolare il CF. Verifica il luogo di nascita."
            }
    except Exception as e:
        return {
            "codice_fiscale": None,
            "success": False,
            "error": f"Errore nel calcolo: {str(e)}. Verifica che il comune sia corretto."
        }

# =====================================================
# ARCHIVIO DOCUMENTI FIRMATI
# =====================================================

class DocumentFilter(BaseModel):
    season: Optional[str] = None  # Format: "2024-2025"
    figure_type: Optional[str] = None  # coach, dirigente, atleta, collaboratore
    document_type: Optional[str] = None  # privacy_consent, receipt_5000, receipt_15000, etc.
    team_id: Optional[str] = None  # Filter by team
    search: Optional[str] = None  # Search by name

@api_router.get("/documents/archive")
async def get_documents_archive(
    season: Optional[str] = None,
    figure_type: Optional[str] = None,
    document_type: Optional[str] = None,
    team_id: Optional[str] = None,
    search: Optional[str] = None,
    page: int = 1,
    limit: int = 20,
    current_user = Depends(get_current_user)
):
    """Get archived signed documents with filters - Admin only"""
    if current_user["role"] not in (UserRole.ADMIN, UserRole.COORDINATORE):
        raise HTTPException(status_code=403, detail="Solo admin può visualizzare l'archivio")
    
    query = {}
    
    # Multi-tenant: scope to society via signer_id of users + athlete_id of atleti
    # 🆕 28/06/2026 — Le quietanze atleta usano athlete_id (non signer_id), quindi
    # serve un OR sui due campi.
    _sid = current_user.get("society_id")
    if _sid:
        society_user_ids = [u["id"] async for u in db.users.find({"society_id": _sid}, {"_id": 0, "id": 1})]
        society_athlete_ids = [a["id"] async for a in db.athletes.find({"society_id": _sid}, {"_id": 0, "id": 1})]
        query["$or"] = [
            {"signer_id": {"$in": society_user_ids}},
            {"athlete_id": {"$in": society_athlete_ids}},
            {"related_entity_id": {"$in": society_athlete_ids}},
        ]
    
    # Filter by season (e.g., "2024-2025" -> years 2024 and 2025)
    if season:
        try:
            years = [int(y) for y in season.split("-")]
            query["year"] = {"$in": years}
        except:
            pass
    
    # Filter by document type
    # Special mapping for receipt filters: in DB document_type is e.g.
    # "compensation_receipt", "coach_compensation_receipt",
    # "collaboratore_compensation_receipt", "dirigente_compensation_receipt",
    # "atleta_pro_compensation_receipt" — with separate flags
    # exceeded_5000 / exceeded_15000 to mark threshold-crossing months.
    RECEIPT_TYPES = [
        "compensation_receipt",
        "coach_compensation_receipt",
        "collaboratore_compensation_receipt",
        "dirigente_compensation_receipt",
        "atleta_pro_compensation_receipt",
    ]
    if document_type == "receipt_standard":
        query["document_type"] = {"$in": RECEIPT_TYPES}
        query["$and"] = [
            {"$or": [{"exceeded_5000": {"$exists": False}}, {"exceeded_5000": False}]},
            {"$or": [{"exceeded_15000": {"$exists": False}}, {"exceeded_15000": False}]},
        ]
    elif document_type == "receipt_5000":
        query["document_type"] = {"$in": RECEIPT_TYPES}
        query["exceeded_5000"] = True
    elif document_type == "receipt_15000":
        query["document_type"] = {"$in": RECEIPT_TYPES}
        query["exceeded_15000"] = True
    elif document_type:
        query["document_type"] = document_type
    
    # Filter by team - need to find athletes in that team first (society-scoped)
    if team_id:
        # Get athlete IDs from this team
        athlete_ids = []
        _t_a_q = {"team_id": team_id}
        if _sid:
            _t_a_q["society_id"] = _sid
        async for athlete in db.athletes.find(_t_a_q, {"id": 1}):
            athlete_ids.append(athlete.get("id"))
        if athlete_ids:
            query["athlete_id"] = {"$in": athlete_ids}
        else:
            # No athletes in team, return empty
            query["athlete_id"] = {"$in": []}
    
    # Filter by figure type
    if figure_type:
        if figure_type == "coach":
            query["coach_id"] = {"$exists": True, "$ne": None}
            query["dirigente_id"] = {"$exists": False}
            query["athlete_id"] = {"$exists": False}
        elif figure_type == "dirigente":
            query["dirigente_id"] = {"$exists": True, "$ne": None}
        elif figure_type == "atleta":
            query["athlete_id"] = {"$exists": True, "$ne": None}
        elif figure_type == "collaboratore":
            query["collaboratore_id"] = {"$exists": True, "$ne": None}
        elif figure_type == "genitore":
            query["parent_id"] = {"$exists": True, "$ne": None}
    
    # Search by name
    if search:
        query["$or"] = [
            {"coach_name": {"$regex": search, "$options": "i"}},
            {"dirigente_name": {"$regex": search, "$options": "i"}},
            {"athlete_name": {"$regex": search, "$options": "i"}},
            {"collaboratore_name": {"$regex": search, "$options": "i"}},
            {"parent_name": {"$regex": search, "$options": "i"}},
            {"signer_name": {"$regex": search, "$options": "i"}}
        ]
    
    # Get total count
    total = await db.signed_documents.count_documents(query)
    
    # Get documents with pagination
    skip = (page - 1) * limit
    documents = []
    async for doc in db.signed_documents.find(query).sort("signed_at", -1).skip(skip).limit(limit):
        doc.pop("_id", None)
        documents.append({
            "id": doc.get("id"),
            "document_type": doc.get("document_type"),
            "document_title": doc.get("document_title"),
            "figure_type": "genitore" if doc.get("parent_id") else "coach" if doc.get("coach_id") else "dirigente" if doc.get("dirigente_id") else "atleta" if doc.get("athlete_id") else "collaboratore" if doc.get("collaboratore_id") else "altro",
            "figure_name": doc.get("parent_name") or doc.get("coach_name") or doc.get("dirigente_name") or doc.get("athlete_name") or doc.get("collaboratore_name") or doc.get("signer_name") or "N/A",
            "athlete_name": doc.get("athlete_name"),
            "month": doc.get("month"),
            "year": doc.get("year"),
            "amount_gross": doc.get("amount_gross"),
            "signed_at": doc.get("signed_at").isoformat() if doc.get("signed_at") else None,
            "pdf_filename": doc.get("pdf_filename")
        })
    
    # Get available seasons for filter
    seasons = set()
    async for doc in db.signed_documents.find({}, {"year": 1}):
        year = doc.get("year")
        if year:
            seasons.add(f"{year-1}-{year}")
            seasons.add(f"{year}-{year+1}")
    
    return {
        "documents": documents,
        "total": total,
        "page": page,
        "limit": limit,
        "total_pages": (total + limit - 1) // limit,
        "available_seasons": sorted(list(seasons), reverse=True)
    }

@api_router.get("/documents/download/{document_id}")
async def download_document(
    document_id: str,
    current_user = Depends(get_current_user)
):
    """Download a signed document PDF"""
    doc = await db.signed_documents.find_one({"id": document_id})
    if not doc:
        raise HTTPException(status_code=404, detail="Documento non trovato")
    
    # Check permissions: admin can download all, others only their own
    is_admin = current_user["role"] == UserRole.ADMIN
    is_owner = (
        doc.get("coach_id") == current_user.get("coach_id") or
        doc.get("dirigente_id") == current_user.get("dirigente_id") or
        doc.get("athlete_id") == current_user.get("athlete_id") or
        doc.get("collaboratore_id") == current_user.get("collaboratore_id") or
        doc.get("signer_id") == current_user.get("id") or
        str(doc.get("coach_id")) == str(current_user.get("id")) or
        str(doc.get("dirigente_id")) == str(current_user.get("id"))
    )
    
    if not is_admin and not is_owner:
        raise HTTPException(status_code=403, detail="Non autorizzato a scaricare questo documento")
    
    # Try pdf_path first (file on disk)
    pdf_path = doc.get("pdf_path")
    if pdf_path and os.path.exists(pdf_path):
        # Read file
        with open(pdf_path, 'rb') as f:
            pdf_content = f.read()

        # AUTO-FIX: for threshold communication PDFs that were generated before
        # the city/signature fix, the file on disk is incomplete (size < 3.5KB
        # for a real legal doc, the summary fallback is < 2.5KB).
        # NOTE: ReportLab compresses page content streams (zlib), so substring
        # checks on the raw bytes are unreliable — rely on SIZE instead.
        dtype = doc.get("document_type", "")
        if dtype in ("threshold_5000_communication", "threshold_15000_communication") and len(pdf_content) < 3500:
            try:
                fixed = await _regenerate_threshold_communication_pdf(doc)
                if fixed and len(fixed) > 3500:
                    # Overwrite disk file + db cache so it's permanent
                    with open(pdf_path, 'wb') as f:
                        f.write(fixed)
                    try:
                        await db.signed_documents.update_one(
                            {"id": document_id},
                            {"$set": {"pdf_base64": base64.b64encode(fixed).decode()}}
                        )
                    except Exception:
                        pass
                    pdf_content = fixed
                    logger.info(f"Auto-fixed threshold PDF {document_id} ({len(pdf_content)} bytes)")
                else:
                    logger.warning(f"threshold rebuild for {document_id} returned insufficient bytes ({len(fixed) if fixed else 0})")
            except Exception as ex:
                logger.warning(f"threshold auto-fix failed for {document_id}: {ex}")

        # AUTO-FIX: compensation_receipt on disk — if file is from the legacy
        # placeholder generator OR uses today's date instead of signing date
        # (no Auth metadata footer), regenerate from the source-of-truth
        # compensation row so signature + date + audit metadata are restored.
        # NOTE: ReportLab compresses page streams, so we rely on SIZE.
        if dtype in ("compensation_receipt", "coach_compensation_receipt", "collaboratore_compensation_receipt"):
            if len(pdf_content) < 3500:
                try:
                    fixed = await _regenerate_compensation_receipt_pdf(doc)
                    if fixed and len(fixed) > 3500:
                        with open(pdf_path, 'wb') as f:
                            f.write(fixed)
                        try:
                            await db.signed_documents.update_one(
                                {"id": document_id},
                                {"$set": {"pdf_base64": base64.b64encode(fixed).decode()}}
                            )
                        except Exception:
                            pass
                        pdf_content = fixed
                        logger.info(f"Auto-fixed compensation_receipt PDF {document_id} ({len(pdf_content)} bytes)")
                    else:
                        logger.warning(f"compensation_receipt rebuild for {document_id} returned insufficient bytes ({len(fixed) if fixed else 0})")
                except Exception as ex:
                    logger.warning(f"compensation_receipt auto-fix failed for {document_id}: {ex}")

        # AUTO-FIX: for GDPR privacy PDFs that show the legacy summary
        # ("PDF originale non più disponibile") regenerate the full legal doc.
        if dtype in ("gdpr_privacy_adult", "gdpr_privacy_minor", "gdpr_adult", "gdpr_minor", "privacy_consent") and (b"PDF originale non" in pdf_content or b"Riepilogo firma" in pdf_content or len(pdf_content) < 4500):
            try:
                fixed = await _regenerate_gdpr_privacy_pdf(doc)
                if fixed and len(fixed) > 1500:
                    with open(pdf_path, 'wb') as f:
                        f.write(fixed)
                    try:
                        await db.signed_documents.update_one(
                            {"id": document_id},
                            {"$set": {
                                "pdf_base64": base64.b64encode(fixed).decode(),
                                "signature_base64": doc.get("signature_base64", "") or "",
                            }}
                        )
                    except Exception:
                        pass
                    pdf_content = fixed
                    logger.info(f"Auto-fixed GDPR privacy PDF {document_id} ({len(pdf_content)} bytes)")
            except Exception as ex:
                logger.warning(f"gdpr auto-fix failed for {document_id}: {ex}")

        return StreamingResponse(
            io.BytesIO(pdf_content),
            media_type="application/pdf",
            headers={
                "Content-Disposition": f'inline; filename="{doc.get("pdf_filename", f"documento_{document_id}.pdf")}"'
            }
        )

    # Fallback to pdf_base64 (stored in database)
    if doc.get("pdf_base64"):
        pdf_bytes = base64.b64decode(doc["pdf_base64"])
        dtype = doc.get("document_type", "")
        # If the cached pdf_base64 is the legacy summary fallback, regenerate
        if dtype in ("gdpr_privacy_adult", "gdpr_privacy_minor", "gdpr_adult", "gdpr_minor", "privacy_consent") and (b"PDF originale non" in pdf_bytes or b"Riepilogo firma" in pdf_bytes or len(pdf_bytes) < 4500):
            try:
                fixed = await _regenerate_gdpr_privacy_pdf(doc)
                if fixed and len(fixed) > 1500:
                    pdf_bytes = fixed
                    await db.signed_documents.update_one(
                        {"id": document_id},
                        {"$set": {"pdf_base64": base64.b64encode(fixed).decode()}}
                    )
                    logger.info(f"Auto-fixed GDPR privacy cache for {document_id} ({len(pdf_bytes)} bytes)")
            except Exception as ex:
                logger.warning(f"gdpr cache auto-fix failed for {document_id}: {ex}")
        # AUTO-FIX: for compensation receipts whose cached PDF was generated
        # by the legacy placeholder OR by an early version of
        # generate_monthly_receipt_pdf that used datetime.now() as date and
        # had no authentication footer, FORCE invalidation so the rebuild
        # logic below picks up the original signing date + signature + metadata.
        # NOTE: ReportLab compresses page streams, so we rely on SIZE.
        if dtype in ("compensation_receipt", "coach_compensation_receipt", "collaboratore_compensation_receipt"):
            if len(pdf_bytes) < 3500:
                logger.info(f"Invalidating stale compensation_receipt cache for {document_id} ({len(pdf_bytes)} bytes)")
                # Drop the cached base64 so we fall through to the regeneration
                # path lower in this function which rebuilds with the correct
                # date/signature/metadata.
                doc["pdf_base64"] = None
                try:
                    await db.signed_documents.update_one(
                        {"id": document_id},
                        {"$unset": {"pdf_base64": ""}}
                    )
                except Exception:
                    pass
                # Fall through to the regeneration path
            else:
                return StreamingResponse(
                    io.BytesIO(pdf_bytes),
                    media_type="application/pdf",
                    headers={"Content-Disposition": f'inline; filename="documento_{document_id}.pdf"', "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0", "Pragma": "no-cache", "Expires": "0"}
                )
        elif dtype in ("threshold_5000_communication", "threshold_15000_communication"):
            # AUTO-FIX threshold communications: regen if cache is smaller than
            # a real legal doc (full PDF ~5-7KB, summary fallback ~1-2.5KB).
            if len(pdf_bytes) < 3500:
                logger.info(f"Invalidating stale threshold cache for {document_id} ({len(pdf_bytes)} bytes)")
                try:
                    fixed = await _regenerate_threshold_communication_pdf(doc)
                    if fixed and len(fixed) > 3500:
                        pdf_bytes = fixed
                        await db.signed_documents.update_one(
                            {"id": document_id},
                            {"$set": {"pdf_base64": base64.b64encode(fixed).decode()}}
                        )
                        logger.info(f"Auto-fixed threshold PDF {document_id} ({len(pdf_bytes)} bytes)")
                    else:
                        logger.warning(f"threshold rebuild for {document_id} returned insufficient bytes ({len(fixed) if fixed else 0}) — keeping cache")
                except Exception as ex:
                    logger.warning(f"threshold auto-fix failed for {document_id}: {ex}")
            return StreamingResponse(
                io.BytesIO(pdf_bytes),
                media_type="application/pdf",
                headers={"Content-Disposition": f'inline; filename="documento_{document_id}.pdf"', "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0", "Pragma": "no-cache", "Expires": "0"}
            )
        else:
            return StreamingResponse(
                io.BytesIO(pdf_bytes),
                media_type="application/pdf",
                headers={"Content-Disposition": f'inline; filename="documento_{document_id}.pdf"', "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0", "Pragma": "no-cache", "Expires": "0"}
            )

    # Generate PDF on-the-fly for registration-time documents (no PDF stored)
    if doc.get("document_type") in ("gdpr_privacy_adult", "gdpr_privacy_minor", "gdpr_adult", "gdpr_minor", "privacy_consent"):
        try:
            pdf_bytes = await _regenerate_gdpr_privacy_pdf(doc)
            if pdf_bytes:
                await db.signed_documents.update_one(
                    {"id": document_id},
                    {"$set": {"pdf_base64": base64.b64encode(pdf_bytes).decode()}}
                )
                return StreamingResponse(
                    io.BytesIO(pdf_bytes),
                    media_type="application/pdf",
                    headers={"Content-Disposition": f'inline; filename="privacy_{document_id}.pdf"', "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0", "Pragma": "no-cache", "Expires": "0"}
                )
        except Exception as e:
            logger.error(f"Error generating GDPR PDF on-the-fly for {document_id}: {e}", exc_info=True)
    # Legacy adult-only inline regeneration kept below as additional fallback
    if doc.get("document_type") in ("gdpr_privacy_adult", "gdpr_privacy_minor", "gdpr_adult"):
        try:
            signer = await db.users.find_one({"id": doc.get("signer_id")})
            athlete = await db.athletes.find_one({"id": doc.get("related_entity_id")})
            society = await db.societies.find_one({"id": doc.get("society_id")})
            
            # Check profile completeness before generating PDF
            if doc.get("document_type") == "gdpr_privacy_adult" and signer:
                # For adult athletes, validate THEIR profile (they are both signer and athlete)
                signer_missing = []
                if not (signer.get("fiscal_code") or "").strip():
                    signer_missing.append("Codice Fiscale")
                if not signer.get("date_of_birth"):
                    signer_missing.append("Data di nascita")
                if not (signer.get("place_of_birth") or signer.get("country_of_birth") or "").strip():
                    signer_missing.append("Luogo di nascita")
                if not (signer.get("address") or "").strip():
                    signer_missing.append("Indirizzo")
                if not (signer.get("city") or "").strip():
                    signer_missing.append("Città")
                if signer_missing:
                    raise HTTPException(
                        status_code=400, 
                        detail=f"Profilo incompleto. Compilare i seguenti campi prima di visualizzare il documento: {', '.join(signer_missing)}"
                    )
            
            signer_name = doc.get("signer_name") or (signer.get("full_name", "") if signer else "")
            signer_first = signer.get("first_name", "") if signer else ""
            signer_last = signer.get("last_name", "") if signer else ""
            signer_cf = signer.get("fiscal_code", "") or signer.get("tax_code", "") if signer else ""
            signer_bp = signer.get("place_of_birth", "") or signer.get("country_of_birth", "") if signer else ""
            signer_dob = ""
            if signer and signer.get("date_of_birth"):
                try:
                    dob = signer["date_of_birth"]
                    if isinstance(dob, str):
                        dob = datetime.fromisoformat(dob.replace("Z", "+00:00"))
                    signer_dob = dob.strftime("%d/%m/%Y")
                except:
                    pass
            
            consent_data = doc.get("consent_data", {})
            signed_at = doc.get("signed_at", datetime.utcnow())
            ts_str = signed_at.strftime("%Y-%m-%d %H:%M:%S") if isinstance(signed_at, datetime) else str(signed_at)
            
            # Fetch full address: prefer user record, but fallback to athlete
            # record which often has the most complete address data
            addr_src = dict(signer) if signer else {}
            if signer and signer.get("role") == "athlete":
                ath = await db.athletes.find_one({"id": signer.get("athlete_id") or signer.get("id")})
                if ath:
                    for fld in ("address", "city", "province", "postal_code", "birth_place"):
                        if not addr_src.get(fld) and ath.get(fld):
                            addr_src[fld] = ath[fld]

            pdf_bytes = generate_gdpr_adult_privacy_pdf(
                society_name=society.get("name", "") if society else "",
                ragione_sociale=society.get("ragione_sociale", "") if society else "",
                society_address=society.get("address", "") if society else "",
                society_fiscal_code=society.get("fiscal_code", "") if society else "",
                society_email=society.get("email", "") if society else "",
                signer_name=signer_first,
                signer_surname=signer_last,
                signer_fiscal_code=signer_cf,
                signer_birth_date=signer_dob,
                signer_birth_place=signer_bp,
                signer_address=addr_src.get("address", ""),
                signer_city=addr_src.get("city", ""),
                signer_province=addr_src.get("province", ""),
                signature_base64="",
                timestamp=ts_str,
                ip_address="Registrazione",
                user_agent="Registrazione via app",
                document_version="1.0",
                document_hash="generated-on-download",
                user_id=doc.get("signer_id", ""),
                society_id=doc.get("society_id", ""),
                consent_data=consent_data,
                signer_role=signer.get("role", "") if signer else "",
            )
            
            # Cache the generated PDF
            pdf_b64 = base64.b64encode(pdf_bytes).decode()
            await db.signed_documents.update_one(
                {"id": document_id},
                {"$set": {"pdf_base64": pdf_b64}}
            )
            
            return StreamingResponse(
                io.BytesIO(pdf_bytes),
                media_type="application/pdf",
                headers={"Content-Disposition": f'inline; filename="privacy_{signer_name.replace(" ", "_")}.pdf"', "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0", "Pragma": "no-cache", "Expires": "0"}
            )
        except Exception as e:
            logger.error(f"Error generating PDF on-the-fly: {e}")
            raise HTTPException(status_code=500, detail="Errore nella generazione del PDF")
    
    # Final fallback: for ANY signed document without a stored PDF (including
    # compensation_receipt, threshold_5000_communication, gdpr*, etc), generate
    # a summary PDF so the admin can at least see the firma metadata.
    if doc.get("id"):
        try:
            signer = await db.users.find_one({"id": doc.get("signer_id")}) if doc.get("signer_id") else None
            society = await db.societies.find_one({"id": doc.get("society_id")}) if doc.get("society_id") else None

            # For threshold communication docs, rebuild the FULL legal document
            # with text + signature (NOT a summary).
            dtype = doc.get("document_type")
            if dtype in ("threshold_5000_communication", "threshold_15000_communication"):
                pdf_bytes = await _regenerate_threshold_communication_pdf(doc)
                if pdf_bytes:
                    try:
                        await db.signed_documents.update_one(
                            {"id": document_id},
                            {"$set": {"pdf_base64": base64.b64encode(pdf_bytes).decode()}}
                        )
                    except Exception:
                        pass
                    return StreamingResponse(
                        io.BytesIO(pdf_bytes),
                        media_type="application/pdf",
                        headers={"Content-Disposition": f'inline; filename="comunicazione_soglia_{document_id}.pdf"', "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0", "Pragma": "no-cache", "Expires": "0"}
                    )

            # For compensation receipts, rebuild the ORIGINAL full PDF (same
            # layout as Foto 2) using stored coach_id, month, year, amount, etc.
            if dtype in ("compensation_receipt", "coach_compensation_receipt", "collaboratore_compensation_receipt"):
                # 🆕 30/06/2026 — ATLETI PRO: il signed_document non ha signer_id/coach_id
                # bensì athlete_id. Senza questo fallback la rigenerazione caricava
                # firma/nome/CF vuoti per Giulia & co.
                is_athlete_doc = bool(doc.get("athlete_id") or doc.get("atleta_id"))
                ath_record = None
                if is_athlete_doc:
                    ath_id_local = doc.get("athlete_id") or doc.get("atleta_id")
                    ath_record = await db.athletes.find_one({"id": ath_id_local}) if ath_id_local else None
                # Find the coach/collaborator user record for fiscal code
                coach_user = None
                coach_id = doc.get("coach_id") or doc.get("signer_id")
                # Per atleti: coach_id va impostato su athlete_id come "owner id"
                if not coach_id and is_athlete_doc:
                    coach_id = doc.get("athlete_id") or doc.get("atleta_id")
                if coach_id:
                    coach_user = await db.users.find_one({"id": coach_id})
                    if not coach_user:
                        coach_user = await db.coaches.find_one({"id": coach_id}) if hasattr(db, "coaches") else None
                # Fallback: try to find user by full_name match
                if not coach_user and doc.get("coach_name"):
                    coach_user = await db.users.find_one({"full_name": doc.get("coach_name")})
                # Fallback for society if not set in doc
                soc_id = doc.get("society_id")
                if not soc_id and coach_user:
                    soc_id = coach_user.get("society_id")
                if not soc_id and ath_record:
                    soc_id = ath_record.get("society_id")
                if soc_id and not society:
                    society = await db.societies.find_one({"id": soc_id})
                # If still no society, take the only society in the system (single-tenant fallback)
                if not society:
                    society = await db.societies.find_one({})

                month_val = doc.get("month") or (doc.get("additional_data") or {}).get("month")
                year_val = doc.get("year") or (doc.get("additional_data") or {}).get("year")
                amount_val = doc.get("amount_gross") or (doc.get("additional_data") or {}).get("amount_gross") or (doc.get("additional_data") or {}).get("amount")
                month_names = ["", "Gennaio", "Febbraio", "Marzo", "Aprile", "Maggio", "Giugno",
                               "Luglio", "Agosto", "Settembre", "Ottobre", "Novembre", "Dicembre"]
                try:
                    month_name = month_names[int(month_val)] if month_val else ""
                except Exception:
                    month_name = str(month_val) if month_val else ""
                soc_name = (society.get("ragione_sociale") or society.get("name") or "") if society else ""
                # 🆕 30/06/2026 — Per atleti, ricostruiamo il nome dal record
                # athlete (full_name oppure last+first uppercased) prima del
                # fallback su coach_user.
                ath_full_name = None
                if ath_record:
                    ath_full_name = (
                        ath_record.get("full_name")
                        or f"{ath_record.get('last_name', '').upper()} {ath_record.get('first_name', '').upper()}".strip()
                        or None
                    )
                signer_name = (
                    doc.get("athlete_name") if is_athlete_doc else None
                ) or ath_full_name or (
                    doc.get("coach_name")
                    or doc.get("signer_name")
                    or ((coach_user or {}).get("full_name") or "")
                )
                fiscal = (
                    (ath_record or {}).get("fiscal_code")
                    if is_athlete_doc else None
                ) or (coach_user or {}).get("fiscal_code") or (doc.get("additional_data") or {}).get("fiscal_code") or ""
                # Try to fetch the actual hand-written signature from the
                # source-of-truth compensation row. Search across ALL three
                # collections (coach / collaboratore / dirigente) — receipts
                # signed by dirigenti/collaboratori live in their own tables.
                signature_b64 = doc.get("signature_base64", "") or ""
                source_signed_at = None
                source_ip = None
                if coach_id and month_val and year_val:
                    try:
                        m_int = int(month_val)
                        y_int = int(year_val)
                        candidates = [
                            ("coach_compensations", "coach_id"),
                            ("collaboratore_compensations", "collaboratore_id"),
                            ("dirigente_compensations", "dirigente_id"),
                            ("compensations", "coach_id"),  # legacy
                            # 🆕 30/06/2026 — Quietanze ATLETI PRO. Senza, la
                            # rigenerazione per Giulia non trovava la firma e
                            # restituiva PDF senza firma.
                            ("athlete_compensation_receipts", "athlete_id"),
                        ]
                        for coll, key in candidates:
                            # Match month sia come int sia come stringa italiana legacy
                            month_or_q = [{"month": m_int}]
                            if 1 <= m_int <= 12:
                                month_or_q.append({"month": month_names[m_int]})
                            comp = await db[coll].find_one(
                                {key: coach_id, "$or": month_or_q, "year": y_int}
                            )
                            if comp:
                                if not signature_b64:
                                    signature_b64 = comp.get("receipt_signature_base64") or comp.get("signature_base64") or ""
                                if not source_signed_at:
                                    source_signed_at = comp.get("receipt_signed_date") or comp.get("signed_date")
                                if not amount_val:
                                    amount_val = comp.get("amount_gross") or comp.get("amount")
                                if signature_b64 and source_signed_at:
                                    break
                    except Exception:
                        pass

                # Resolve final signing timestamp (priority: signed_documents.signed_at
                # → source compensation.receipt_signed_date → doc.created_at)
                signed_at_final = (
                    doc.get("signed_at")
                    or source_signed_at
                    or doc.get("created_at")
                )

                pdf_bytes = generate_monthly_receipt_pdf(
                    society_name=soc_name,
                    collaborator_name=signer_name,
                    collaborator_fiscal_code=fiscal,
                    month_name=month_name,
                    year=int(year_val) if year_val else datetime.now(timezone.utc).year,
                    amount_gross=float(amount_val) if amount_val else 0.0,
                    signature_base64=signature_b64,
                    signed_at=signed_at_final,
                    document_id=doc.get("id"),
                    signer_id=doc.get("signer_id") or coach_id,
                    ip_address=doc.get("ip_address") or source_ip,
                    document_hash=doc.get("document_hash") or doc.get("hash"),
                    # 🆕 30/06/2026 — Label "Atleta:" sulle quietanze atleti PRO
                    role_label=("Atleta" if is_athlete_doc else "Collaboratore"),
                )
            else:
                pdf_bytes = _generate_consent_summary_pdf(doc, signer, society)
            # Cache for future calls — but NOT for GDPR/privacy/threshold
            # types, where caching a placeholder would lock the document into
            # the legacy summary forever.
            non_cache_types = (
                "gdpr_privacy_adult", "gdpr_privacy_minor",
                "gdpr_adult", "gdpr_minor", "privacy_consent",
                "threshold_5000_communication", "threshold_15000_communication",
            )
            if doc.get("document_type") not in non_cache_types:
                try:
                    pdf_b64 = base64.b64encode(pdf_bytes).decode()
                    await db.signed_documents.update_one({"id": document_id}, {"$set": {"pdf_base64": pdf_b64}})
                except Exception:
                    pass
            safe_name = (doc.get("signer_name") or "documento").replace(" ", "_")
            return StreamingResponse(
                io.BytesIO(pdf_bytes),
                media_type="application/pdf",
                headers={"Content-Disposition": f'inline; filename="{safe_name}_{document_id[:8]}.pdf"', "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0", "Pragma": "no-cache", "Expires": "0"}
            )
        except Exception as e:
            logger.error(f"Error generating legacy summary PDF for {document_id}: {e}")

    raise HTTPException(status_code=404, detail="File PDF non trovato")


@api_router.delete("/documents/{document_id}")
async def admin_request_delete_signed_document(document_id: str, current_user = Depends(get_current_user)):
    """Admin: REQUEST deletion of a signed document.

    Does NOT immediately delete. Creates a 'deletion_request' record and notifies
    the signer (via in-app notification and audit log). The signer must approve
    the deletion from their dashboard. This protects the integrity of signed
    documents (GDPR/contabilità) by requiring co-consent.

    If the document was signed by an admin themselves (e.g., privacy GDPR
    society admin), the deletion is immediate (no co-consent needed).
    """
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può richiedere cancellazione")

    doc = await db.signed_documents.find_one({"id": document_id})
    if not doc:
        # Document not found: check if there's an orphaned compensation row
        # referencing this missing document_id, and unlock it directly.
        # 🐛 29/07/2026 — Aggiunta la collection `athlete_compensation_receipts`
        # (Atleta 18+ PRO) che usa il campo `document_id` invece di
        # `receipt_document_id`. Senza questo, la cancellazione di quietanze
        # orfane atleta falliva con "Documento non trovato" (bug segnalato
        # per BACCO LUCIA — Giugno "LA TUA SOCIETÀ" demo).
        orphan_collections = [
            ("coach_compensations", "coach_id", "receipt_document_id"),
            ("collaboratore_compensations", "collaboratore_id", "receipt_document_id"),
            ("dirigente_compensations", "dirigente_id", "receipt_document_id"),
            ("atleta_pro_compensations", "atleta_id", "receipt_document_id"),
            ("compensations", "coach_id", "receipt_document_id"),
            ("athlete_compensation_receipts", "athlete_id", "document_id"),
        ]
        unlock_patch_generic = {"$set": {
            "receipt_signed": False,
            "receipt_signed_date": None,
            "receipt_document_id": None,
            "receipt_signature_base64": None,
            "received": False,
            "received_date": None,
        }}
        unlock_patch_athlete = {"$set": {
            "receipt_signed": False,
            "receipt_signed_date": None,
            "document_id": None,
            "signature_base64": None,
            "signed": False,
            "signed_date": None,
        }}
        total_unlocked = 0
        for coll_name, _, doc_field in orphan_collections:
            patch = unlock_patch_athlete if coll_name == "athlete_compensation_receipts" else unlock_patch_generic
            res = await db[coll_name].update_many(
                {doc_field: document_id},
                patch,
            )
            total_unlocked += res.modified_count
        if total_unlocked > 0:
            logger.info(
                f"[orphan-cleanup] document {document_id} missing; unlocked "
                f"{total_unlocked} compensation row(s)."
            )
            return {
                "message": "Quietanza orfana ripulita (il documento era già stato cancellato). Il firmatario potrà nuovamente firmare il mese.",
                "orphan_cleaned": True,
                "unlocked": total_unlocked,
            }
        raise HTTPException(status_code=404, detail="Documento non trovato")

    if current_user.get("society_id") and doc.get("society_id") and \
            current_user["society_id"] != doc["society_id"]:
        raise HTTPException(status_code=403, detail="Il documento appartiene a un'altra società")

    signer_id = doc.get("signer_id") or doc.get("coach_id")
    # 🆕 29/06/2026 — Quietanze Atleta 18+ PRO: il signed_documents salva
    # athlete_id (db.athletes.id), il firmatario in db.users si ricava da
    # users.athlete_id == athlete_id. Senza questo fallback la cancellazione
    # diretta veniva eseguita immediatamente (signer_id=None), bypassando il
    # consenso dell'atleta.
    if not signer_id and doc.get("athlete_id"):
        user_doc = await db.users.find_one({"athlete_id": doc["athlete_id"]})
        if user_doc:
            signer_id = user_doc["id"]
    signer_user = await db.users.find_one({"id": signer_id}) if signer_id else None

    # If signer IS the same admin → delete immediately
    if not signer_id or signer_id == current_user["id"]:
        await _execute_document_deletion(doc, deleted_by=current_user)
        return {"message": "Documento cancellato (firmatario coincide con admin)", "immediate": True}

    # Otherwise: create a pending deletion request
    existing = await db.deletion_requests.find_one({"document_id": document_id, "status": "pending"})
    if existing:
        return {"message": "Richiesta di cancellazione già in attesa di approvazione", "request_id": existing["id"], "status": "pending"}

    req_id = str(uuid.uuid4())
    await db.deletion_requests.insert_one({
        "id": req_id,
        "document_id": document_id,
        "document_title": doc.get("document_title"),
        "document_type": doc.get("document_type"),
        "society_id": doc.get("society_id"),
        # 🆕 29/06/2026 — Persist owner IDs so admin UI can show a per-athlete/coach
        # pending badge senza dover risalire al signed_document ad ogni fetch.
        "athlete_id": doc.get("athlete_id") or doc.get("atleta_id"),
        "coach_id": doc.get("coach_id"),
        "collaboratore_id": doc.get("collaboratore_id"),
        "dirigente_id": doc.get("dirigente_id"),
        "requested_by_id": current_user["id"],
        "requested_by_name": current_user.get("full_name") or current_user.get("email"),
        "requested_by_email": current_user.get("email"),
        "signer_id": signer_id,
        "signer_name": doc.get("signer_name") or doc.get("coach_name") or (signer_user or {}).get("full_name"),
        "signer_email": (signer_user or {}).get("email"),
        "status": "pending",
        "created_at": datetime.now(timezone.utc).isoformat(),
    })

    # In-app notification for the signer
    try:
        await db.notifications.insert_one({
            "id": str(uuid.uuid4()),
            "user_id": signer_id,
            "type": "document_deletion_request",
            "title": "Richiesta cancellazione documento firmato",
            "message": f"L'amministratore ha richiesto la cancellazione di '{doc.get('document_title')}'. Apri la richiesta per autorizzare o rifiutare.",
            "related_entity_id": req_id,
            "is_read": False,
            "created_at": datetime.now(timezone.utc).isoformat(),
        })
    except Exception as e:
        logger.warning(f"Failed to create notification: {e}")

    return {
        "message": "Richiesta inoltrata al firmatario. La cancellazione avverrà solo dopo l'autorizzazione.",
        "request_id": req_id,
        "status": "pending",
        "signer_name": doc.get("signer_name"),
    }


async def _execute_document_deletion(doc: dict, deleted_by: dict):
    """Internal helper: actually deletes the document + file + audit log."""
    pdf_path = doc.get("pdf_path")
    if pdf_path:
        try:
            if os.path.exists(pdf_path):
                os.remove(pdf_path)
        except Exception as e:
            logger.warning(f"Impossibile rimuovere file PDF {pdf_path}: {e}")

    # Unlock compensation if it was a quietanza OR a threshold communication
    # so the user sees the month as unsigned again and can re-sign.
    # NOTE: per i documenti threshold_5000/15000_communication la firma è
    # collegata alla riga compensation come per una quietanza normale, quindi
    # va sbloccata allo stesso modo.
    unlockable_types = (
        "compensation_receipt",
        "coach_compensation_receipt",
        "collaboratore_compensation_receipt",
        "dirigente_compensation_receipt",
        "atleta_pro_compensation_receipt",
        "threshold_5000_communication",
        "threshold_15000_communication",
    )
    if doc.get("document_type") in unlockable_types:
        comp_id = (doc.get("additional_data") or {}).get("compensation_id") or doc.get("related_entity_id")
        owner_id = (doc.get("coach_id") or doc.get("signer_id") or
                    doc.get("collaboratore_id") or doc.get("dirigente_id") or
                    doc.get("atleta_id") or doc.get("athlete_id"))
        month_v = doc.get("month") or (doc.get("additional_data") or {}).get("month")
        year_v = doc.get("year") or (doc.get("additional_data") or {}).get("year")
        unlock_patch = {
            "$set": {
                "receipt_signed": False,
                "receipt_signed_at": None,
                "receipt_signed_date": None,
                "receipt_document_id": None,
                "receipt_signature_base64": None,
                "exceeded_5000": False,
                "exceeded_15000": False,
            }
        }
        # 🆕 29/06/2026 — Quietanza Atleta 18+ PRO: la riga vive in
        # `athlete_compensation_receipts` e non in `atleta_pro_compensations`.
        # Cancelliamo la riga direttamente (così l'atleta vede di nuovo il mese
        # come NON firmato e può ri-firmare).
        athlete_doc_types = ("compensation_receipt", "compensation_receipt_split")
        if doc.get("document_type") in athlete_doc_types and (doc.get("athlete_id") or doc.get("atleta_id")):
            aid = doc.get("athlete_id") or doc.get("atleta_id")
            try:
                m_int_a = int(month_v) if month_v is not None else None
            except Exception:
                m_int_a = None
            if aid and m_int_a is not None and year_v is not None:
                month_or = [{"month": m_int_a}]
                if 1 <= m_int_a <= 12:
                    month_or.append({"month": _MONTH_NAMES_IT[m_int_a]})
                try:
                    res_a = await db.athlete_compensation_receipts.delete_many({
                        "athlete_id": aid,
                        "$or": month_or,
                        "year": int(year_v),
                    })
                    if res_a.deleted_count:
                        logger.info(
                            f"Deleted {res_a.deleted_count} athlete_compensation_receipts row(s) "
                            f"for athlete_id={aid} {m_int_a}/{year_v}"
                        )
                except Exception as e:
                    logger.warning(f"Unable to delete athlete_compensation_receipts: {e}")

            # 🆕 29/06/2026 — Dual-role: se la quietanza atleta ha generato una
            # quietanza coach gemella (linked_coach_user_id), sblocchiamola pure.
            linked_coach_uid = doc.get("linked_coach_user_id")
            if linked_coach_uid and m_int_a is not None and year_v is not None:
                try:
                    month_or_c = [{"month": m_int_a}]
                    if 1 <= m_int_a <= 12:
                        month_or_c.append({"month": _MONTH_NAMES_IT[m_int_a]})
                    res_c = await db.coach_compensations.update_many(
                        {"coach_id": linked_coach_uid, "$or": month_or_c, "year": int(year_v)},
                        unlock_patch,
                    )
                    if res_c.modified_count:
                        logger.info(
                            f"Unlocked {res_c.modified_count} linked coach_compensations "
                            f"row(s) for coach_id={linked_coach_uid} {m_int_a}/{year_v}"
                        )
                except Exception as e:
                    logger.warning(f"Unable to unlock linked coach_compensations: {e}")
        # Try every compensation collection: by id first, then by owner+month+year.
        # Match month sia come int sia come stringa italiana legacy.
        collections_with_owner = [
            ("compensations", "coach_id"),
            ("coach_compensations", "coach_id"),
            ("collaboratore_compensations", "collaboratore_id"),
            ("dirigente_compensations", "dirigente_id"),
            ("atleta_pro_compensations", "atleta_id"),
        ]
        try:
            total_unlocked = 0
            if comp_id:
                for coll, _ in collections_with_owner:
                    res = await db[coll].update_one({"id": comp_id}, unlock_patch)
                    total_unlocked += res.modified_count
            if owner_id and month_v is not None and year_v is not None and total_unlocked == 0:
                try:
                    m_int = int(month_v)
                except Exception:
                    m_int = None
                month_match = {"$or": [{"month": int(month_v)} if m_int is not None else {"month": str(month_v)},
                                       {"month": _MONTH_NAMES_IT[m_int] if (m_int and 1 <= m_int <= 12) else None}]} if m_int else {"month": month_v}
                for coll, owner_field in collections_with_owner:
                    base_q = {owner_field: owner_id, "year": int(year_v)}
                    base_q.update(month_match)
                    res = await db[coll].update_many(base_q, unlock_patch)
                    if res.modified_count:
                        total_unlocked += res.modified_count
                        logger.info(
                            f"Unlocked {res.modified_count} row(s) in {coll} for "
                            f"{owner_field}={owner_id} {month_v}/{year_v}"
                        )
        except Exception as e:
            logger.warning(f"Impossibile sbloccare compensation: {e}")

        # 🧹 Cleanup correlati: external_compensations dichiarate per quel mese
        try:
            if owner_id and month_v is not None and year_v is not None:
                try:
                    m_int = int(month_v)
                except Exception:
                    m_int = None
                if m_int is not None:
                    await db.external_compensations.delete_many({
                        "user_id": owner_id,
                        "year": int(year_v),
                        "related_receipt_month": m_int,
                    })
        except Exception:
            pass

        # 🧹 Threshold communication cancellata → cancella anche la dichiarazione
        # soglia corrispondente (se presente) per quel singolo anno
        try:
            if doc.get("document_type") == "threshold_5000_communication":
                t_type = "5000"
            elif doc.get("document_type") == "threshold_15000_communication":
                t_type = "15000"
            else:
                t_type = None
            if t_type and owner_id and year_v is not None:
                await db.threshold_declarations.delete_many({
                    "$or": [
                        {"coach_id": owner_id},
                        {"collaboratore_id": owner_id},
                        {"dirigente_id": owner_id},
                        {"atleta_id": owner_id},
                        {"signer_id": owner_id},
                    ],
                    "year": int(year_v),
                    "threshold_type": t_type,
                })
                # Reset il flag corrispondente su yearly_limits
                field_date = f"exceeded_{t_type}_date"
                field_decl = f"exceeded_{t_type}_declaration_id"
                field_flag = f"exceeded_{t_type}"
                await db.yearly_limits.update_many(
                    {"user_id": owner_id, "year": int(year_v)},
                    {"$set": {field_flag: False, field_date: None, field_decl: None}},
                )
        except Exception as e:
            logger.warning(f"Impossibile resettare threshold/yearly_limits: {e}")

    try:
        await db.audit_logs.insert_one({
            "id": str(uuid.uuid4()),
            "action": "delete_signed_document",
            "actor_id": deleted_by["id"],
            "actor_email": deleted_by.get("email"),
            "society_id": doc.get("society_id"),
            "target_document_id": doc.get("id"),
            "target_signer_name": doc.get("signer_name"),
            "target_document_type": doc.get("document_type"),
            "target_document_title": doc.get("document_title"),
            "created_at": datetime.now(timezone.utc).isoformat(),
        })
    except Exception:
        pass

    await db.signed_documents.delete_one({"id": doc["id"]})


@api_router.get("/admin/diagnostics/compensations/{coach_name}")
async def admin_diagnose_coach_compensations(coach_name: str, current_user = Depends(get_current_user)):
    """Returns full diagnostic info about a coach's compensations vs signed_documents.
    Helps debug 'orphaned receipts' issues.
    """
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")

    # Find coach user(s) by name (case-insensitive partial match)
    users = await db.users.find(
        {"$or": [
            {"full_name": {"$regex": coach_name, "$options": "i"}},
            {"first_name": {"$regex": coach_name, "$options": "i"}},
            {"last_name": {"$regex": coach_name, "$options": "i"}},
        ]},
        {"_id": 0, "id": 1, "full_name": 1, "role": 1, "society_id": 1, "email": 1}
    ).to_list(20)

    result = []
    for u in users:
        comps = await db.compensations.find({"coach_id": u["id"]}, {"_id": 0}).to_list(50)
        for c in comps:
            signed = None
            if c.get("receipt_document_id"):
                signed = await db.signed_documents.find_one({"id": c["receipt_document_id"]}, {"_id": 0, "id": 1})
            if not signed:
                signed = await db.signed_documents.find_one(
                    {"coach_id": u["id"], "month": c.get("month"), "year": c.get("year"),
                     "document_type": {"$in": ["compensation_receipt", "coach_compensation_receipt", "collaboratore_compensation_receipt"]}},
                    {"_id": 0, "id": 1}
                )
            result.append({
                "coach": u.get("full_name"),
                "coach_id": u["id"],
                "month": c.get("month"),
                "year": c.get("year"),
                "amount_gross": c.get("amount_gross"),
                "receipt_signed": c.get("receipt_signed"),
                "receipt_signed_type": type(c.get("receipt_signed")).__name__,
                "receipt_document_id": c.get("receipt_document_id"),
                "linked_signed_doc_exists": bool(signed),
                "comp_society_id": c.get("society_id"),
                "user_society_id": u.get("society_id"),
            })
    return {"matches": len(users), "users": users, "compensations_detail": result}


@api_router.post("/admin/migrations/normalize-athlete-receipts")
async def admin_normalize_athlete_receipts(
    dry_run: bool = True,
    current_user = Depends(get_current_user)
):
    """🆕 28/06/2026 — Migration: normalizza i campi legacy di `athlete_compensation_receipts`.

    Da: `signed`, `signed_date`, `amount`
    A:  `receipt_signed`, `receipt_signed_date`, `amount_gross`

    I campi legacy NON vengono cancellati (per backward-compat con codice non
    ancora migrato), ma i nuovi nomi vengono garantiti su TUTTI i record.

    Args:
        dry_run: se True (default), conta cosa farebbe senza scrivere.
                 Passare ?dry_run=false per eseguire davvero.
    """
    if current_user.get("role") != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")

    society_id = current_user.get("society_id")

    scanned = 0
    needs_update = 0
    updated = 0
    samples: list = []

    query: dict = {}
    if society_id:
        # Multi-tenant: include solo atleti della società
        athlete_ids = [a["id"] async for a in db.athletes.find({"society_id": society_id}, {"_id": 0, "id": 1})]
        query["athlete_id"] = {"$in": athlete_ids}

    async for r in db.athlete_compensation_receipts.find(query, {"_id": 0}):
        scanned += 1
        set_ops: dict = {}
        if r.get("receipt_signed") is None and "signed" in r:
            set_ops["receipt_signed"] = bool(r.get("signed"))
        if r.get("receipt_signed_date") is None and r.get("signed_date") is not None:
            set_ops["receipt_signed_date"] = r.get("signed_date")
        if r.get("amount_gross") is None and r.get("amount") is not None:
            set_ops["amount_gross"] = r.get("amount")
        if set_ops:
            needs_update += 1
            if len(samples) < 5:
                samples.append({
                    "athlete_id": r.get("athlete_id"),
                    "year": r.get("year"),
                    "month": r.get("month"),
                    "applying": set_ops,
                })
            if not dry_run:
                res = await db.athlete_compensation_receipts.update_one(
                    {"id": r.get("id"), "athlete_id": r.get("athlete_id"),
                     "year": r.get("year"), "month": r.get("month")},
                    {"$set": set_ops}
                )
                if res.modified_count > 0:
                    updated += 1

    return {
        "message": ("Dry run completato — nessuna scrittura." if dry_run else f"Migration eseguita: {updated} record aggiornati."),
        "dry_run": dry_run,
        "scanned": scanned,
        "needs_update": needs_update,
        "updated": updated,
        "samples": samples,
    }



async def admin_cleanup_duplicate_privacy(
    dry_run: bool = True,
    current_user = Depends(get_current_user)
):
    """🆕 28/06/2026 — Admin tool: identifica documenti privacy "duplicati" creati
    prima del fix del 28/06/2026. Per ogni atleta che ha sia un documento legacy
    "privacy_consent" (titolo 'Consenso Privacy Atleta') sia un documento nuovo
    "gdpr_adult" (titolo 'Informativa Privacy GDPR - Staff') firmati lo STESSO giorno,
    elimina la copia legacy.

    Args:
        dry_run: se True (default), restituisce solo l'elenco senza cancellare.
                 Passare ?dry_run=false per eseguire la cancellazione.
    """
    if current_user.get("role") != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")

    society_id = current_user.get("society_id")

    duplicates_found: list = []
    deleted_count = 0
    scanned_count = 0

    # Query all gdpr_adult docs (the new flow)
    query: dict = {"document_type": "gdpr_adult"}
    if society_id:
        query["society_id"] = society_id

    async for new_doc in db.signed_documents.find(query, {"_id": 0}):
        scanned_count += 1
        related_id = new_doc.get("related_entity_id") or new_doc.get("athlete_id")
        signed_at = new_doc.get("signed_at") or new_doc.get("created_at")
        if not related_id or not signed_at:
            continue

        # Same calendar day check
        try:
            from datetime import datetime as _dt
            new_dt = _dt.fromisoformat(str(signed_at).replace("Z", "+00:00")) if isinstance(signed_at, str) else signed_at
            day_start = new_dt.replace(hour=0, minute=0, second=0, microsecond=0)
            day_end = new_dt.replace(hour=23, minute=59, second=59, microsecond=999999)
        except Exception:
            continue

        # Find legacy "privacy_consent" doc for the same athlete on the same day
        legacy_query = {
            "document_type": "privacy_consent",
            "related_entity_id": related_id,
        }
        legacy_docs = await db.signed_documents.find(legacy_query, {"_id": 0}).to_list(50)
        for legacy in legacy_docs:
            legacy_signed_at = legacy.get("signed_at") or legacy.get("created_at")
            if not legacy_signed_at:
                continue
            try:
                from datetime import datetime as _dt2
                legacy_dt = _dt2.fromisoformat(str(legacy_signed_at).replace("Z", "+00:00")) if isinstance(legacy_signed_at, str) else legacy_signed_at
            except Exception:
                continue
            if day_start <= legacy_dt <= day_end:
                duplicates_found.append({
                    "athlete_id": related_id,
                    "athlete_name": legacy.get("signer_name", "N/A"),
                    "day": day_start.strftime("%Y-%m-%d"),
                    "legacy_doc_id": legacy.get("id"),
                    "legacy_title": legacy.get("document_title"),
                    "new_doc_id": new_doc.get("id"),
                    "new_title": new_doc.get("document_title"),
                })
                if not dry_run:
                    del_res = await db.signed_documents.delete_one({"id": legacy.get("id")})
                    if del_res.deleted_count > 0:
                        deleted_count += 1

    return {
        "message": ("Dry run: nessuna cancellazione effettuata." if dry_run else f"Eliminati {deleted_count} documenti privacy legacy duplicati."),
        "dry_run": dry_run,
        "scanned_gdpr_adult": scanned_count,
        "duplicates_found": len(duplicates_found),
        "deleted": deleted_count,
        "details": duplicates_found[:50],  # Cap a 50 per non saturare la response
    }


@api_router.post("/admin/compensations/repair-orphaned-receipts")
async def admin_repair_orphaned_compensation_receipts(current_user = Depends(get_current_user)):
    """Admin tool: scans ALL compensation collections (coach/dirigente/
    collaboratore/atleta_pro/legacy) and finds records marked as
    receipt_signed=True that no longer have a matching signed_documents
    record. Resets receipt_signed=False so the user can re-sign.
    Returns aggregated diagnostics + list of repaired records.
    """
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")

    society_id = current_user.get("society_id")

    # (collection_name, owner_id_field, role_label)
    targets = [
        ("coach_compensations", "coach_id", "coach"),
        ("dirigente_compensations", "dirigente_id", "dirigente"),
        ("collaboratore_compensations", "collaboratore_id", "collaboratore"),
        ("atleta_pro_compensations", "atleta_id", "atleta_pro"),
        ("athlete_compensations", "athlete_id", "atleta"),
        ("compensations", "coach_id", "legacy"),
    ]

    repaired = []
    per_collection = {}
    total_scanned = 0
    total_other_soc = 0

    for coll_name, owner_field, role_label in targets:
        coll = db[coll_name]
        scanned = 0
        other_soc = 0
        fixed = 0
        async for comp in coll.find({"receipt_signed": True}):
            scanned += 1
            total_scanned += 1

            # Society scope check (via comp.society_id OR via owner.society_id)
            comp_soc = comp.get("society_id")
            owner_id = comp.get(owner_field)
            if not comp_soc and owner_id:
                owner_doc = await db.users.find_one({"id": owner_id}, {"society_id": 1})
                if owner_doc:
                    comp_soc = owner_doc.get("society_id")
            if society_id and comp_soc and comp_soc != society_id:
                other_soc += 1
                total_other_soc += 1
                continue

            # Look up matching signed_document
            signed_doc = None
            if comp.get("receipt_document_id"):
                signed_doc = await db.signed_documents.find_one(
                    {"id": comp["receipt_document_id"]}, {"_id": 0, "id": 1}
                )
            if not signed_doc and owner_id:
                signed_doc = await db.signed_documents.find_one(
                    {
                        "signer_id": owner_id,
                        "month": comp.get("month"),
                        "year": comp.get("year"),
                    },
                    {"_id": 0, "id": 1},
                )
            if signed_doc:
                continue

            # Orphan: reset
            await coll.update_one(
                {"id": comp["id"]} if comp.get("id") else {"_id": comp["_id"]},
                {"$set": {
                    "receipt_signed": False,
                    "receipt_signed_date": None,
                    "receipt_document_id": None,
                    "receipt_signature_base64": None,
                    "received": False,
                    "received_date": None,
                    "exceeded_5000": False,
                    "exceeded_15000": False,
                }},
            )
            fixed += 1
            repaired.append({
                "collection": coll_name,
                "role": role_label,
                "compensation_id": comp.get("id") or str(comp.get("_id")),
                "owner_id": owner_id,
                "owner_name": comp.get("coach_name") or comp.get("dirigente_name") or comp.get("collaboratore_name") or comp.get("atleta_name") or comp.get("athlete_name") or "—",
                "month": comp.get("month"),
                "year": comp.get("year"),
                "amount": comp.get("amount_gross"),
            })

            # 🧹 Cleanup correlati: external_compensations dichiarate per quel mese
            # + threshold_declarations e yearly_limits reset se è l'unico anno orfano
            try:
                if owner_id and comp.get("month") is not None and comp.get("year"):
                    m_val = comp.get("month")
                    try:
                        m_int = int(m_val)
                    except Exception:
                        m_int = None
                    if m_int is not None:
                        await db.external_compensations.delete_many({
                            "user_id": owner_id,
                            "year": comp["year"],
                            "related_receipt_month": m_int,
                        })
            except Exception:
                pass

        per_collection[coll_name] = {"scanned": scanned, "other_society": other_soc, "fixed": fixed}

    logger.info(
        f"Repair orphaned receipts: total_scanned={total_scanned} "
        f"total_other_society={total_other_soc} total_fixed={len(repaired)} "
        f"per_collection={per_collection}"
    )

    # 🧹 Reset finale threshold_declarations + yearly_limits per gli utenti
    # che dopo la pulizia non hanno più alcuna quietanza firmata nell'anno
    # (evita blocco soglie residue alle prossime firme)
    affected_user_years: dict = {}
    for r in repaired:
        u = r.get("owner_id")
        y = r.get("year")
        if u and y:
            affected_user_years.setdefault(u, set()).add(y)
    cleanup_summary = {"threshold_declarations_removed": 0, "yearly_limits_reset": 0}
    for u, years in affected_user_years.items():
        for y in years:
            # Conta se l'utente ha ancora qualche quietanza firmata in quell'anno
            still_signed = 0
            for coll_name, owner_field, _role in targets:
                still_signed += await db[coll_name].count_documents({
                    owner_field: u, "year": y, "receipt_signed": True,
                })
            if still_signed == 0:
                try:
                    res_t = await db.threshold_declarations.delete_many({
                        "$or": [
                            {"coach_id": u},
                            {"collaboratore_id": u},
                            {"dirigente_id": u},
                            {"atleta_id": u},
                            {"signer_id": u},
                        ],
                        "year": y,
                    })
                    cleanup_summary["threshold_declarations_removed"] += res_t.deleted_count
                except Exception:
                    pass
                try:
                    res_yl = await db.yearly_limits.update_many(
                        {"user_id": u, "year": y},
                        {"$set": {
                            "exceeded_5000": False,
                            "exceeded_5000_date": None,
                            "exceeded_5000_declaration_id": None,
                            "exceeded_15000": False,
                            "exceeded_15000_date": None,
                            "exceeded_15000_declaration_id": None,
                        }},
                    )
                    cleanup_summary["yearly_limits_reset"] += res_yl.modified_count
                except Exception:
                    pass

    return {
        "message": f"{len(repaired)} compensation(s) sbloccate. Gli utenti potranno ora rifirmare le quietanze.",
        "count": len(repaired),
        "scanned": total_scanned,
        "filtered_other_society": total_other_soc,
        "per_collection": per_collection,
        "cleanup": cleanup_summary,
        "repaired": repaired,
    }


@api_router.get("/deletion-requests/pending")
async def list_my_pending_deletion_requests(current_user = Depends(get_current_user)):
    """List pending deletion requests addressed to the current user (signer)."""
    cursor = db.deletion_requests.find(
        {"signer_id": current_user["id"], "status": "pending"},
        {"_id": 0}
    ).sort("created_at", -1)
    return await cursor.to_list(100)


@api_router.get("/admin/deletion-requests/pending-summary")
async def admin_pending_deletion_summary(current_user = Depends(get_current_user)):
    """🆕 29/06/2026 — Admin: lista compatta delle richieste pendenti per badge UI.
    Ritorna mappature {athlete_id: count} e {coach_id: count} così la lista atleti
    e la lista coach possono mostrare un badge senza N chiamate separate."""
    if current_user.get("role") not in ("admin", "super_admin"):
        raise HTTPException(status_code=403, detail="Solo admin")
    society_id = current_user.get("society_id")
    query = {"status": "pending"}
    if society_id:
        query["society_id"] = society_id
    cursor = db.deletion_requests.find(query, {"_id": 0, "athlete_id": 1, "coach_id": 1, "collaboratore_id": 1, "dirigente_id": 1})
    rows = await cursor.to_list(2000)
    by_athlete: dict = {}
    by_coach: dict = {}
    by_collab: dict = {}
    by_dirig: dict = {}
    for r in rows:
        if r.get("athlete_id"):
            by_athlete[r["athlete_id"]] = by_athlete.get(r["athlete_id"], 0) + 1
        if r.get("coach_id"):
            by_coach[r["coach_id"]] = by_coach.get(r["coach_id"], 0) + 1
        if r.get("collaboratore_id"):
            by_collab[r["collaboratore_id"]] = by_collab.get(r["collaboratore_id"], 0) + 1
        if r.get("dirigente_id"):
            by_dirig[r["dirigente_id"]] = by_dirig.get(r["dirigente_id"], 0) + 1
    return {
        "total": len(rows),
        "by_athlete": by_athlete,
        "by_coach": by_coach,
        "by_collaboratore": by_collab,
        "by_dirigente": by_dirig,
    }


@api_router.post("/deletion-requests/{request_id}/approve")
async def approve_deletion_request(request_id: str, current_user = Depends(get_current_user)):
    req = await db.deletion_requests.find_one({"id": request_id})
    if not req:
        raise HTTPException(status_code=404, detail="Richiesta non trovata")
    if req.get("signer_id") != current_user["id"]:
        raise HTTPException(status_code=403, detail="Solo il firmatario può approvare la cancellazione")
    if req.get("status") != "pending":
        raise HTTPException(status_code=400, detail=f"Richiesta già {req.get('status')}")

    doc = await db.signed_documents.find_one({"id": req["document_id"]})
    if doc:
        await _execute_document_deletion(doc, deleted_by=current_user)

    await db.deletion_requests.update_one(
        {"id": request_id},
        {"$set": {
            "status": "approved",
            "approved_at": datetime.now(timezone.utc).isoformat(),
            "approved_by_id": current_user["id"],
        }}
    )
    return {"message": "Cancellazione autorizzata. Documento eliminato."}


@api_router.post("/deletion-requests/{request_id}/reject")
async def reject_deletion_request(request_id: str, current_user = Depends(get_current_user)):
    req = await db.deletion_requests.find_one({"id": request_id})
    if not req:
        raise HTTPException(status_code=404, detail="Richiesta non trovata")
    if req.get("signer_id") != current_user["id"]:
        raise HTTPException(status_code=403, detail="Solo il firmatario può rifiutare la cancellazione")
    if req.get("status") != "pending":
        raise HTTPException(status_code=400, detail=f"Richiesta già {req.get('status')}")

    await db.deletion_requests.update_one(
        {"id": request_id},
        {"$set": {
            "status": "rejected",
            "rejected_at": datetime.now(timezone.utc).isoformat(),
            "rejected_by_id": current_user["id"],
        }}
    )
    return {"message": "Cancellazione rifiutata. Il documento resta valido."}


# ============================================================
# 🆕 09/08/2026 — Cambio ruolo staff (Coach ⇄ Dirigente ⇄ Collaboratore)
# Flusso: l'ADMIN PROPONE un nuovo ruolo → la PERSONA deve ACCETTARE.
# Solo all'accettazione il ruolo cambia davvero. Dati anagrafici e privacy
# restano invariati. Lasciando il ruolo COACH le squadre assegnate vengono
# scollegate automaticamente (assigned_teams svuotato).
# ============================================================
STAFF_ROLE_LABELS = {"coach": "Coach", "dirigente": "Dirigente", "viewer": "Dirigente", "collaboratore": "Collaboratore"}
INTERCHANGEABLE_STAFF_ROLES = ["coach", "dirigente", "collaboratore"]
# 🐛 10/08/2026 — "viewer" è l'alias legacy di "dirigente": va accettato come ruolo
# di PARTENZA valido (altrimenti la proposta falliva con "Ruolo non compatibile: viewer").
SOURCE_STAFF_ROLES = ["coach", "dirigente", "collaboratore", "viewer"]


class RoleChangeProposal(BaseModel):
    to_role: str


@api_router.post("/admin/staff/{user_id}/propose-role-change")
async def propose_role_change(user_id: str, payload: RoleChangeProposal, current_user = Depends(get_current_user)):
    user = await _admin_check_user_and_society(user_id, SOURCE_STAFF_ROLES, current_user)
    to_role = (payload.to_role or "").strip().lower()
    if to_role not in INTERCHANGEABLE_STAFF_ROLES:
        raise HTTPException(status_code=400, detail="Ruolo di destinazione non valido")
    # "viewer" equivale a "dirigente": impedisci una proposta che non cambia nulla
    current_role = user.get("role")
    if to_role == current_role or (to_role == "dirigente" and current_role == "viewer"):
        raise HTTPException(status_code=400, detail="La persona ha già questo ruolo")
    now = datetime.now(timezone.utc).isoformat()
    # Sostituisce eventuali proposte pendenti precedenti
    await db.role_change_requests.update_many(
        {"user_id": user_id, "status": "pending"},
        {"$set": {"status": "superseded", "resolved_at": now}}
    )
    req = {
        "id": str(ObjectId()),
        "society_id": current_user.get("society_id"),
        "user_id": user_id,
        "user_name": user.get("full_name", ""),
        "from_role": user.get("role"),
        "to_role": to_role,
        "status": "pending",
        "requested_by_id": current_user["id"],
        "requested_by_name": current_user.get("full_name", "Amministrazione"),
        "created_at": now,
    }
    await db.role_change_requests.insert_one({**req})
    return {"message": "Proposta inviata. La persona dovrà accettarla.", "request": req}


@api_router.get("/admin/staff/{user_id}/role-change-request")
async def get_staff_role_change_request(user_id: str, current_user = Depends(get_current_user)):
    if current_user.get("role") != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")
    req = await db.role_change_requests.find_one({"user_id": user_id, "status": "pending"}, {"_id": 0})
    if req:
        req["from_role_label"] = STAFF_ROLE_LABELS.get(req.get("from_role"), req.get("from_role"))
        req["to_role_label"] = STAFF_ROLE_LABELS.get(req.get("to_role"), req.get("to_role"))
    return {"request": req}


@api_router.delete("/admin/staff/{user_id}/role-change-request")
async def cancel_staff_role_change_request(user_id: str, current_user = Depends(get_current_user)):
    if current_user.get("role") != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")
    now = datetime.now(timezone.utc).isoformat()
    res = await db.role_change_requests.update_many(
        {"user_id": user_id, "status": "pending", "society_id": current_user.get("society_id")},
        {"$set": {"status": "cancelled", "resolved_at": now}}
    )
    return {"message": "Proposta annullata", "cancelled": res.modified_count}


@api_router.get("/role-change/pending")
async def my_pending_role_change(current_user = Depends(get_current_user)):
    req = await db.role_change_requests.find_one({"user_id": current_user["id"], "status": "pending"}, {"_id": 0})
    if req:
        req["from_role_label"] = STAFF_ROLE_LABELS.get(req.get("from_role"), req.get("from_role"))
        req["to_role_label"] = STAFF_ROLE_LABELS.get(req.get("to_role"), req.get("to_role"))
    return {"request": req}


@api_router.post("/role-change/{request_id}/accept")
async def accept_role_change(request_id: str, current_user = Depends(get_current_user)):
    req = await db.role_change_requests.find_one({"id": request_id})
    if not req:
        raise HTTPException(status_code=404, detail="Richiesta non trovata")
    if req.get("user_id") != current_user["id"]:
        raise HTTPException(status_code=403, detail="Solo la persona interessata può accettare")
    if req.get("status") != "pending":
        raise HTTPException(status_code=400, detail=f"Richiesta già {req.get('status')}")
    to_role = req["to_role"]
    now = datetime.now(timezone.utc).isoformat()
    update = {"role": to_role}
    # Lasciando il ruolo COACH → scollega le squadre assegnate (le riassegnerà l'admin)
    if to_role != "coach":
        update["assigned_teams"] = []
    await db.users.update_one({"id": current_user["id"]}, {"$set": update})
    await db.role_change_requests.update_one(
        {"id": request_id}, {"$set": {"status": "accepted", "resolved_at": now}}
    )
    return {"message": "Ruolo aggiornato", "new_role": to_role, "new_role_label": STAFF_ROLE_LABELS.get(to_role, to_role)}


@api_router.post("/role-change/{request_id}/reject")
async def reject_role_change(request_id: str, current_user = Depends(get_current_user)):
    req = await db.role_change_requests.find_one({"id": request_id})
    if not req:
        raise HTTPException(status_code=404, detail="Richiesta non trovata")
    if req.get("user_id") != current_user["id"]:
        raise HTTPException(status_code=403, detail="Solo la persona interessata può rifiutare")
    if req.get("status") != "pending":
        raise HTTPException(status_code=400, detail=f"Richiesta già {req.get('status')}")
    now = datetime.now(timezone.utc).isoformat()
    await db.role_change_requests.update_one(
        {"id": request_id}, {"$set": {"status": "rejected", "resolved_at": now}}
    )
    return {"message": "Proposta rifiutata"}


async def _regenerate_threshold_communication_pdf(document: dict) -> Optional[bytes]:
    """Regenerate the FULL Comunicazione Superamento Soglia €5k/€15k PDF
    when the original was not stored or was incomplete (no signature/luogo).
    """
    try:
        doc_type = document.get("document_type", "")
        # ⚠️ Check 15000 FIRST because "5000" is a substring of "15000"!
        threshold_type = "15000" if "15000" in doc_type else "5000"

        # Signer can be referenced as signer_id, coach_id, dirigente_id, collaboratore_id, athlete_id
        # 🆕 29/06/2026 — Fix: campo athlete_id (non atleta_id) e ricerca in db.athletes per atleti PRO
        signer_id = (
            document.get("signer_id")
            or document.get("coach_id")
            or document.get("dirigente_id")
            or document.get("collaboratore_id")
            or document.get("athlete_id")
            or document.get("atleta_id")
        )
        signer = await db.users.find_one({"id": signer_id}, {"_id": 0}) if signer_id else None
        # Fallback: atleti compensati PRO non sono in users, ma in athletes
        if signer_id and not signer:
            ath = await db.athletes.find_one({"id": signer_id}, {"_id": 0})
            if ath:
                full_name = (
                    ath.get("full_name")
                    or f"{ath.get('last_name', '').upper()} {ath.get('first_name', '').upper()}".strip()
                    or "Atleta"
                )
                signer = {
                    "id": ath.get("id"),
                    "full_name": full_name,
                    "fiscal_code": ath.get("fiscal_code", ""),
                    "society_id": ath.get("society_id"),
                    "_is_athlete": True,
                }

        # Society: from doc or via signer
        society_id = document.get("society_id") or (signer.get("society_id") if signer else None)
        society = await db.societies.find_one({"id": society_id}, {"_id": 0}) if society_id else None
        settings = await db.settings.find_one({"type": "society", "society_id": society_id}, {"_id": 0}) if society_id else None
        # 🐛 08/07/2026 — Fallback SOLO se non abbiamo un society_id valido, per evitare
        # di prendere le impostazioni di un'altra società.
        if not settings and not society_id:
            settings = await db.settings.find_one({"type": "society"}, {"_id": 0})  # noqa: multitenancy-ok — fallback usato solo se society_id assente

        # Year/month
        month = document.get("month")
        year = document.get("year") or (int(str(document.get("signed_at", ""))[:4]) if document.get("signed_at") else None)

        # Lookup compensation record for signature
        # 🆕 29/06/2026 — Fix nome collezione: athlete_compensation_receipts (era atleta_pro_compensations inesistente)
        comp = None
        if signer_id and year and month:
            for coll in ("coach_compensations", "dirigente_compensations", "collaboratore_compensations", "athlete_compensation_receipts"):
                comp = await db[coll].find_one({
                    "$or": [
                        {"coach_id": signer_id},
                        {"dirigente_id": signer_id},
                        {"collaboratore_id": signer_id},
                        {"athlete_id": signer_id},
                        {"atleta_id": signer_id},
                    ],
                    "month": month, "year": year,
                }, {"_id": 0})
                if comp:
                    break

        # Lookup threshold_declaration for prior_compensation_declared
        # Supports all signer types (coach/collaboratore/dirigente/atleta)
        decl = None
        if signer_id and year:
            decl = await db.threshold_declarations.find_one({
                "$or": [
                    {"coach_id": signer_id},
                    {"collaboratore_id": signer_id},
                    {"dirigente_id": signer_id},
                    {"atleta_id": signer_id},
                    {"signer_id": signer_id},
                ],
                "year": year,
                "threshold_type": threshold_type,
            }, {"_id": 0})

        # Signature: try multiple sources
        # 🆕 30/06/2026 — athlete_compensation_receipts salva il campo
        # `signature_base64` (NON `receipt_signature_base64` come Coach/Dir/Collab),
        # quindi controlliamo ENTRAMBI per non lasciare la PDF senza firma.
        add = document.get("additional_data") or {}
        sig_b64 = (
            document.get("signature_base64")
            or add.get("signature_base64")
            or (comp.get("receipt_signature_base64") if comp else None)
            or (comp.get("signature_base64") if comp else None)
            or (decl.get("signature_base64") if decl else None)
        )

        # Society city
        society_city = (
            (settings.get("city") if settings else None)
            or (society.get("city") if society else None)
            or "Perugia"
        )

        # Collaborator info
        # 🆕 29/06/2026 — Aggiunti athlete_name + athlete signer (cercato in db.athletes
        # nella sezione superiore). Fallback "Atleta" se il documento è di un atleta.
        is_athlete_doc = bool(document.get("athlete_id") or document.get("atleta_id") or (signer and signer.get("_is_athlete")))
        collaborator_name = (
            document.get("signer_name")
            or document.get("athlete_name")
            or document.get("coach_name")
            or (signer.get("full_name") if signer else None)
            or ("Atleta" if is_athlete_doc else "Collaboratore")
        )
        fiscal_code = (
            document.get("fiscal_code")
            or (signer.get("fiscal_code") if signer else None)
            or add.get("fiscal_code")
            or ""
        )

        # Totals: prefer the persisted threshold_metadata (most authoritative
        # snapshot taken at signing time); fall back to additional_data / comp.
        persisted_meta = document.get("threshold_metadata") or {}
        yearly_total = persisted_meta.get("yearly_total_after") or add.get("yearly_total_after") or (comp.get("yearly_total_after") if comp else None)
        yearly_total_before = persisted_meta.get("yearly_total_before") or add.get("yearly_total_before") or (comp.get("yearly_total_before") if comp else None)

        # If totals are missing (legacy docs), reconstruct them by summing
        # all signed compensation rows for that year up to and including the
        # threshold month.
        if (not yearly_total or not yearly_total_before) and signer_id and year and month:
            try:
                m_int, y_int = int(month), int(year)
                cum_after = 0.0
                cum_before = 0.0
                for coll, key in [
                    ("coach_compensations", "coach_id"),
                    ("collaboratore_compensations", "collaboratore_id"),
                    ("dirigente_compensations", "dirigente_id"),
                    ("atleta_pro_compensations", "atleta_id"),
                    # 🆕 30/06/2026 — Fix: la collezione reale degli atleti PRO è
                    # `athlete_compensation_receipts` (i vecchi `atleta_pro_compensations`
                    # non esistono in DB). Senza questa riga, la rigenerazione PDF
                    # per le quietanze atleta mostrava sempre €0.
                    ("athlete_compensation_receipts", "athlete_id"),
                ]:
                    rows = await db[coll].find(
                        {key: signer_id, "year": y_int}
                    ).to_list(50)
                    for r in rows:
                        # athlete_compensation_receipts usa `signed` (legacy) o
                        # `receipt_signed`. Coach/Dir/Collab usano `receipt_signed`.
                        is_signed = bool(r.get("receipt_signed") or r.get("signed"))
                        if not is_signed:
                            continue
                        rm = int(r.get("month") or 0)
                        amt = float(r.get("amount_gross") or r.get("amount") or 0)
                        if rm <= m_int:
                            cum_after += amt
                        if rm < m_int:
                            cum_before += amt
                if not yearly_total:
                    yearly_total = cum_after
                if not yearly_total_before:
                    yearly_total_before = cum_before
            except Exception:
                pass

        yearly_total = yearly_total or 0
        yearly_total_before = yearly_total_before or 0
        prior_comp = persisted_meta.get("prior_compensation_declared") or add.get("prior_compensation_declared") or ((signer or {}).get("other_annual_compensation") if year == ((signer or {}).get("contract_start_date") or "")[:4] else 0) or (decl.get("compensi_pregressi_dichiarati") if decl else None) or 0
        sig_hash = persisted_meta.get("signature_hash") or (hashlib.sha256(sig_b64.encode()).hexdigest() if sig_b64 else "N/D")

        # Original signing timestamp (priority: signed_documents.signed_at →
        # persisted metadata → compensation.receipt_signed_date)
        signed_at_final = (
            document.get("signed_at")
            or persisted_meta.get("signature_timestamp_utc")
            or (comp.get("receipt_signed_date") if comp else None)
        )
        sig_timestamp_rome = persisted_meta.get("signature_timestamp_rome")
        if not sig_timestamp_rome and signed_at_final:
            try:
                if isinstance(signed_at_final, str):
                    _dt = datetime.fromisoformat(signed_at_final.replace("Z", "+00:00"))
                else:
                    _dt = signed_at_final
                sig_timestamp_rome = to_rome_time(_dt).strftime("%d/%m/%Y %H:%M:%S")
            except Exception:
                sig_timestamp_rome = "N/D"

        threshold_meta = {
            "yearly_total_before": yearly_total_before,
            "yearly_total_after": yearly_total,
            "prior_compensation_declared": prior_comp,
            "threshold_crossed": threshold_type,
            "signature_timestamp_utc": str(signed_at_final or ""),
            "signature_timestamp_rome": sig_timestamp_rome or "N/D",
            "signature_hash": sig_hash,
            "monthly_compensation_rate": (comp.get("amount_gross") if comp else None) or persisted_meta.get("monthly_compensation_rate") or 0,
        }

        # Resolve society name
        society_name = (
            (settings.get("ragione_sociale") if settings else None)
            or (society.get("ragione_sociale") if society else None)
            or (society.get("name") if society else None)
            or "ASD/SSD"
        )

        # Use the OFFICIAL generator (same as the live signing flow)
        if threshold_type == "5000":
            pdf_bytes = generate_threshold_5k_pdf(
                society_name=society_name,
                collaborator_name=collaborator_name,
                collaborator_fiscal_code=fiscal_code,
                year=int(year) if year else datetime.utcnow().year,
                signature_base64=sig_b64 or "",
                society_city=society_city,
                threshold_metadata=threshold_meta,
                signed_at=signed_at_final,
                threshold_month=int(month) if month else None,
                document_id=document.get("id"),
            )
        else:
            pdf_bytes = generate_threshold_15k_pdf(
                society_name=society_name,
                collaborator_name=collaborator_name,
                collaborator_fiscal_code=fiscal_code,
                year=int(year) if year else datetime.utcnow().year,
                signature_base64=sig_b64 or "",
                society_city=society_city,
                threshold_metadata=threshold_meta,
                signed_at=signed_at_final,
                threshold_month=int(month) if month else None,
                document_id=document.get("id"),
            )

        return pdf_bytes
    except Exception as e:
        logger.error(f"_regenerate_threshold_communication_pdf failed: {e}", exc_info=True)
        return None


async def _regenerate_compensation_receipt_pdf(document: dict) -> Optional[bytes]:
    """Regenerate a compensation receipt PDF from the source-of-truth row.

    Used to repair stale cached PDFs that lack signature/original signing date/
    authentication metadata. Searches across coach / collaboratore / dirigente /
    athlete compensation collections for the original signature and signed date.
    🆕 29/06/2026 — Esteso per atleti compensati PRO (athlete_id + db.athletes
    + athlete_compensation_receipts + role_label="Atleta").
    """
    try:
        signer_id = (
            document.get("coach_id")
            or document.get("signer_id")
            or document.get("athlete_id")
            or document.get("atleta_id")
        )
        # Read month/year/amount from BOTH top-level (current schema) and
        # additional_data (legacy/alternative schema)
        ad = document.get("additional_data") or {}
        month_val = document.get("month") or ad.get("month")
        year_val = document.get("year") or ad.get("year")
        amount_val = (
            document.get("amount_gross")
            or document.get("amount")
            or ad.get("amount_gross")
            or ad.get("amount")
        )

        # Find signer profile (users for staff, athletes for atleti compensati)
        # 🆕 30/06/2026 — Per doc atleti compensati, vai DIRETTAMENTE su db.athletes:
        # cercare prima in db.users potrebbe restituire un user diverso che capita di
        # avere stesso id (rare collisioni), producendo nome/CF errati o vuoti sulla PDF.
        is_athlete_doc = bool(document.get("athlete_id") or document.get("atleta_id"))
        signer = None
        if is_athlete_doc and signer_id:
            ath = await db.athletes.find_one({"id": signer_id})
            if ath:
                signer = {
                    "id": ath.get("id"),
                    "full_name": (
                        ath.get("full_name")
                        or f"{ath.get('last_name', '').upper()} {ath.get('first_name', '').upper()}".strip()
                        or "Atleta"
                    ),
                    "fiscal_code": ath.get("fiscal_code", ""),
                    "society_id": ath.get("society_id"),
                }
        if not signer and signer_id:
            signer = await db.users.find_one({"id": signer_id})
        if signer_id and not signer:
            ath = await db.athletes.find_one({"id": signer_id})
            if ath:
                signer = {
                    "id": ath.get("id"),
                    "full_name": (
                        ath.get("full_name")
                        or f"{ath.get('last_name', '').upper()} {ath.get('first_name', '').upper()}".strip()
                        or "Atleta"
                    ),
                    "fiscal_code": ath.get("fiscal_code", ""),
                    "society_id": ath.get("society_id"),
                }
                is_athlete_doc = True

        # Find society
        society_id = document.get("society_id") or (signer or {}).get("society_id")
        society_settings = await db.settings.find_one(
            {"type": "society", "society_id": society_id}, {"_id": 0}
        ) if society_id else None
        # 🐛 08/07/2026 — Fallback SOLO se non abbiamo alcun society_id (edge case legacy).
        # Se abbiamo l'id ma non troviamo il settings dedicato, preferiamo prendere il record
        # societies (che potrebbe avere ragione_sociale/name) piuttosto che un settings a caso
        # che potrebbe appartenere a un'altra società.
        if not society_settings:
            if society_id:
                soc_rec = await db.societies.find_one({"id": society_id}, {"_id": 0})
                society_settings = soc_rec or {}
            else:
                society_settings = await db.settings.find_one({"type": "society"}, {"_id": 0}) or {}  # noqa: multitenancy-ok — fallback usato solo se society_id assente
        society_name = society_settings.get("ragione_sociale") or society_settings.get("society_name") or ""

        signer_name = (
            document.get("athlete_name")
            or document.get("coach_name")
            or document.get("signer_name")
            or (signer or {}).get("full_name", "")
        )
        fiscal = (
            document.get("fiscal_code")
            or (signer or {}).get("fiscal_code")
            or (document.get("additional_data") or {}).get("fiscal_code")
            or ""
        )

        # Recover signature + signed_date from source-of-truth compensation row
        signature_b64 = document.get("signature_base64") or ""
        source_signed_at = None
        if signer_id and month_val and year_val:
            try:
                m_int = int(month_val)
                y_int = int(year_val)
                for coll, key in [
                    ("coach_compensations", "coach_id"),
                    ("collaboratore_compensations", "collaboratore_id"),
                    ("dirigente_compensations", "dirigente_id"),
                    ("compensations", "coach_id"),
                    # 🆕 29/06/2026 — Atleti compensati PRO
                    ("athlete_compensation_receipts", "athlete_id"),
                ]:
                    comp = await db[coll].find_one({key: signer_id, "month": m_int, "year": y_int})
                    if comp:
                        if not signature_b64:
                            signature_b64 = comp.get("receipt_signature_base64") or comp.get("signature_base64") or ""
                        if not source_signed_at:
                            source_signed_at = comp.get("receipt_signed_date") or comp.get("signed_date")
                        if signature_b64 and source_signed_at:
                            break
            except Exception:
                pass

        signed_at_final = document.get("signed_at") or source_signed_at or document.get("created_at")

        month_name = _MONTH_NAMES_IT[int(month_val)] if month_val and 1 <= int(month_val) <= 12 else ""

        pdf_bytes = generate_monthly_receipt_pdf(
            society_name=society_name,
            collaborator_name=signer_name,
            collaborator_fiscal_code=fiscal,
            month_name=month_name,
            year=int(year_val) if year_val else datetime.now(timezone.utc).year,
            amount_gross=float(amount_val) if amount_val else 0.0,
            signature_base64=signature_b64,
            signed_at=signed_at_final,
            document_id=document.get("id"),
            signer_id=signer_id,
            ip_address=document.get("ip_address"),
            document_hash=document.get("document_hash") or document.get("hash"),
            # 🆕 29/06/2026 — Label "Atleta:" per quietanze atleti compensati
            role_label=("Atleta" if is_athlete_doc else "Collaboratore"),
        )
        return pdf_bytes
    except Exception as e:
        logger.error(f"_regenerate_compensation_receipt_pdf failed: {e}", exc_info=True)
        return None


async def _regenerate_gdpr_privacy_pdf(document: dict) -> Optional[bytes]:
    """Regenerate the FULL legal GDPR privacy PDF for a signed_documents
    record whose original PDF was lost (ephemeral disk wipe on redeploy) or
    whose cached pdf_base64 contains the legacy summary fallback.

    Handles three document_type cases:
      - gdpr_privacy_adult / gdpr_adult / privacy_consent (adult signing for self)
      - gdpr_privacy_minor / gdpr_minor (parent signing for minor)
      - privacy_consent with related_entity_id pointing to a minor athlete
        (parent signing at registration time — produces minor PDF)
    """
    try:
        signer = await db.users.find_one({"id": document.get("signer_id")}) if document.get("signer_id") else None
        athlete = None
        if document.get("related_entity_id"):
            athlete = await db.athletes.find_one({"id": document.get("related_entity_id")})
        if not athlete and document.get("minor_id"):
            athlete = await db.athletes.find_one({"id": document.get("minor_id")})

        # Society lookup with settings fallback
        # 🔥 24/02/2026 — Multi-tenancy fix: filtra per society_id del documento
        society = await db.societies.find_one({"id": document.get("society_id")}) if document.get("society_id") else None
        if not society:
            society = await db.societies.find_one({})
        doc_society_id = document.get("society_id")
        society_settings = await db.settings.find_one({"type": "society", "society_id": doc_society_id}) if doc_society_id else None

        soc_name = (society_settings.get("name") if society_settings else None) or (society.get("name", "") if society else "")
        soc_ragione = (society_settings.get("ragione_sociale") if society_settings else None) or (society.get("ragione_sociale", "") if society else "")
        soc_address = (society_settings.get("address") if society_settings else None) or (society.get("address", "") if society else "")
        soc_fiscal = (society_settings.get("fiscal_code") if society_settings else None) or (society.get("fiscal_code", "") if society else "")
        soc_email = (society_settings.get("email") if society_settings else None) or (society.get("email", "") if society else "")

        signed_at = document.get("signed_at", datetime.utcnow())
        ts_str = format_it(signed_at, "%Y-%m-%d %H:%M:%S") if isinstance(signed_at, datetime) else str(signed_at)
        consent_data = document.get("consent_data", {}) or {}
        signature_b64 = document.get("signature_base64", "") or ""

        import hashlib
        doc_hash = hashlib.sha256(f"{document.get('id', '')}{ts_str}".encode()).hexdigest()[:16]

        is_minor_consent = (
            document.get("document_type") in ("gdpr_privacy_minor", "gdpr_minor")
            or (document.get("document_type") == "privacy_consent" and athlete and athlete.get("is_minor"))
            or bool(document.get("minor_id"))
        )

        if not is_minor_consent:
            # Adult flow
            signer_first = signer.get("first_name", "") if signer else ""
            signer_last = signer.get("last_name", "") if signer else ""
            # Fallback to splitting signer_name on the document if user record is gone
            if not signer_first and not signer_last:
                full = (document.get("signer_name") or "").strip()
                parts = full.split(" ", 1) if full else ["", ""]
                signer_last = parts[0] if parts else ""
                signer_first = parts[1] if len(parts) > 1 else ""
            signer_cf = (signer.get("fiscal_code") or signer.get("tax_code") or "") if signer else ""
            signer_bp = (signer.get("place_of_birth") or signer.get("country_of_birth") or "") if signer else ""
            signer_dob = ""
            if signer and signer.get("date_of_birth"):
                try:
                    dob = signer["date_of_birth"]
                    if isinstance(dob, str):
                        dob = datetime.fromisoformat(dob.replace("Z", "+00:00"))
                    signer_dob = dob.strftime("%d/%m/%Y")
                except Exception:
                    pass

            return generate_gdpr_adult_privacy_pdf(
                society_name=soc_name,
                ragione_sociale=soc_ragione,
                society_address=soc_address,
                society_fiscal_code=soc_fiscal,
                society_email=soc_email,
                signer_name=signer_first,
                signer_surname=signer_last,
                signer_fiscal_code=signer_cf,
                signer_birth_date=signer_dob,
                signer_birth_place=signer_bp,
                signer_address=signer.get("address", "") if signer else "",
                signer_city=signer.get("city", "") if signer else "",
                signer_province=signer.get("province", "") if signer else "",
                signature_base64=signature_b64,
                timestamp=ts_str,
                ip_address=document.get("ip_address", "Registrazione"),
                user_agent=document.get("user_agent", "web-client"),
                document_version="1.0",
                document_hash=doc_hash,
                user_id=document.get("signer_id", ""),
                society_id=document.get("society_id", ""),
                consent_data=consent_data,
                signer_role=(signer.get("role", "") if signer else ""),
            )

        # Minor flow (parent signed for minor)
        parent = signer
        if not parent and athlete:
            parent = await db.users.find_one({"id": athlete.get("parent_id")})
        # Name fallback from document.signer_name if user record gone
        parent_first = parent.get("first_name", "") if parent else ""
        parent_last = parent.get("last_name", "") if parent else ""
        if not parent_first and not parent_last:
            full = (document.get("signer_name") or "").strip()
            parts = full.split(" ", 1) if full else ["", ""]
            parent_last = parts[0] if parts else ""
            parent_first = parts[1] if len(parts) > 1 else ""

        return generate_gdpr_minor_privacy_pdf(
            society_name=soc_name,
            ragione_sociale=soc_ragione,
            society_address=soc_address,
            society_fiscal_code=soc_fiscal,
            society_email=soc_email,
            parent_name=parent_first,
            parent_surname=parent_last,
            parent_fiscal_code=(parent.get("fiscal_code", "") if parent else ""),
            minor_name=(athlete.get("first_name", "") if athlete else (document.get("minor_name", "") or "")),
            minor_surname=(athlete.get("last_name", "") if athlete else (document.get("minor_surname", "") or "")),
            minor_fiscal_code=(athlete.get("fiscal_code", "") if athlete else (document.get("minor_fiscal_code", "") or "")),
            minor_birth_date=(athlete.get("date_of_birth", "") if athlete else ""),
            minor_birth_place=(athlete.get("place_of_birth", "") if athlete else ""),
            signature_base64=signature_b64,
            timestamp=ts_str,
            ip_address=document.get("ip_address", "Registrazione"),
            user_agent=document.get("user_agent", "web-client"),
            document_version="1.0",
            document_hash=doc_hash,
            user_id=document.get("signer_id", ""),
            society_id=document.get("society_id", ""),
            consent_data=consent_data,
        )
    except Exception as e:
        logger.error(f"_regenerate_gdpr_privacy_pdf failed for {document.get('id')}: {e}", exc_info=True)
        return None


def _generate_consent_summary_pdf(doc: dict, signer: Optional[dict], society: Optional[dict]) -> bytes:
    """Generate a minimal but valid PDF for documents whose original PDF
    was not stored (legacy privacy_consent, trial_declaration, terms_of_use).
    Includes title, signer info, society info, signed_at and document id.
    """
    from reportlab.lib.pagesizes import A4
    from reportlab.pdfgen import canvas as _c
    buf = io.BytesIO()
    p = _c.Canvas(buf, pagesize=A4)
    w, h = A4
    y = h - 60
    p.setFont("Helvetica-Bold", 16)
    p.drawString(50, y, doc.get("document_title", "Documento Firmato"))
    y -= 30
    p.setFont("Helvetica", 10)
    p.drawString(50, y, "Riepilogo firma digitale (PDF originale non più disponibile)")
    y -= 30
    p.line(50, y, w - 50, y)
    y -= 24

    def row(label: str, value: str):
        nonlocal y
        if y < 80:
            p.showPage()
            y = h - 60
            p.setFont("Helvetica", 10)
        p.setFont("Helvetica-Bold", 10)
        p.drawString(50, y, f"{label}:")
        p.setFont("Helvetica", 10)
        # Wrap long values
        max_chars = 70
        v = str(value or "—")
        if len(v) > max_chars:
            p.drawString(170, y, v[:max_chars])
            y -= 14
            p.drawString(170, y, v[max_chars:max_chars*2])
        else:
            p.drawString(170, y, v)
        y -= 18

    row("Documento ID", doc.get("id", ""))
    row("Tipo", doc.get("document_type", ""))
    row("Firmatario", doc.get("signer_name", "") or (signer.get("full_name", "") if signer else ""))
    row("Email firmatario", doc.get("signer_email", "") or (signer.get("email", "") if signer else ""))
    add = doc.get("additional_data") or {}
    if isinstance(add, dict):
        if add.get("role"):
            row("Ruolo", add.get("role"))
        if add.get("fiscal_code"):
            row("Codice Fiscale", add.get("fiscal_code"))
        # Compensation/threshold specific fields
        if add.get("month") or add.get("reference_month"):
            row("Mese di riferimento", str(add.get("month") or add.get("reference_month")))
        if add.get("year") or add.get("reference_year"):
            row("Anno", str(add.get("year") or add.get("reference_year")))
        if add.get("amount") is not None or add.get("gross_amount") is not None:
            amt = add.get("amount") if add.get("amount") is not None else add.get("gross_amount")
            try:
                row("Importo lordo", f"€ {float(amt):,.2f}".replace(",", "X").replace(".", ",").replace("X", "."))
            except Exception:
                row("Importo lordo", str(amt))
        if add.get("net_amount") is not None:
            try:
                row("Importo netto", f"€ {float(add['net_amount']):,.2f}".replace(",", "X").replace(".", ",").replace("X", "."))
            except Exception:
                pass
        if add.get("iban"):
            row("IBAN", add.get("iban"))
        if add.get("threshold"):
            row("Soglia superata", f"€ {add.get('threshold')}")
        if add.get("contract_total"):
            row("Totale Contratto", f"€ {add.get('contract_total')}")
        if add.get("contract_start") and add.get("contract_end"):
            row("Periodo Contratto", f"{add.get('contract_start')} → {add.get('contract_end')}")
        if add.get("notes"):
            row("Note", str(add.get("notes")))
    signed_at = doc.get("signed_at")
    if isinstance(signed_at, datetime):
        signed_at_s = signed_at.strftime("%d/%m/%Y %H:%M")
    else:
        signed_at_s = str(signed_at) if signed_at else "—"
    row("Firmato il", signed_at_s)
    if society:
        row("Società", society.get("ragione_sociale") or society.get("name") or "")

    y -= 10
    p.line(50, y, w - 50, y)
    y -= 20
    p.setFont("Helvetica-Oblique", 9)
    p.drawString(50, y, "Documento generato automaticamente da RegistraTEAM. La firma è registrata nel sistema con timestamp e ID univoco.")
    p.showPage()
    p.save()
    return buf.getvalue()

@api_router.get("/documents/my-documents")
async def get_my_documents(
    signer_id: Optional[str] = None,
    current_user = Depends(get_current_user)
):
    """Get documents signed by the current user, grouped by minor for parents.
       Admin can pass signer_id to view another user's documents."""
    
    # If admin passes signer_id, query for that user's documents
    if signer_id and current_user.get("role") == UserRole.ADMIN:
        target_user_id = signer_id
    else:
        target_user_id = current_user.get("id")
    
    role = current_user.get("role")
    
    # Use signer_id as primary query - works for all roles
    query = {"$or": [
        {"signer_id": target_user_id},
        {"coach_id": target_user_id},
        {"dirigente_id": target_user_id},
        {"collaboratore_id": target_user_id},
        {"parent_id": target_user_id}
    ]}
    # 🆕 06/07/2026 — Escludi documenti archiviati come stagione precedente
    # (reset compenso/riconferma stagionale). Restano nel DB come storico.
    query["$and"] = [
        {"$or": [
            {"is_previous_season": {"$exists": False}},
            {"is_previous_season": {"$ne": True}},
        ]}
    ]
    
    # For athletes: also include documents linked via related_entity_id
    athlete_id = current_user.get("athlete_id")
    if role == UserRole.ATHLETE and athlete_id:
        query["$or"].append({"related_entity_id": athlete_id})
    
    # For parents: also include documents for their children (signed by the other parent)
    if role == UserRole.PARENT or (signer_id and current_user.get("role") == UserRole.ADMIN):
        lookup_id = target_user_id
        # Find all children where this user is parent_id or second_parent_id
        children = await db.athletes.find(
            {"$or": [{"parent_id": lookup_id}, {"second_parent_id": lookup_id}]},
            {"_id": 0, "id": 1}
        ).to_list(100)
        children_ids = [c["id"] for c in children]
        if children_ids:
            query["$or"].append({"minor_id": {"$in": children_ids}})
    
    documents = []
    async for doc in db.signed_documents.find(query).sort([("signed_at", -1), ("created_at", -1)]):
        doc.pop("_id", None)
        documents.append({
            "id": doc.get("id"),
            "document_type": doc.get("document_type"),
            "document_title": doc.get("document_title"),
            "month": doc.get("month"),
            "year": doc.get("year"),
            "amount_gross": doc.get("amount_gross"),
            "athlete_name": doc.get("athlete_name"),
            "signer_name": doc.get("signer_name"),
            # Minor info for grouping
            "minor_id": doc.get("minor_id"),
            "minor_name": doc.get("minor_name"),
            "related_entity_id": doc.get("related_entity_id"),
            # Timestamps
            "signed_at": doc.get("signed_at").isoformat() if doc.get("signed_at") else None,
            "created_at": doc.get("created_at").isoformat() if doc.get("created_at") else None,
            "pdf_filename": doc.get("pdf_filename"),
            # GDPR metadata if present
            "gdpr_metadata": doc.get("gdpr_metadata")
        })
    
    # Group documents by minor for better organization
    grouped = {
        "personal": [],  # Documents of the signer themselves
        "minors": {}     # Documents grouped by minor_id
    }
    
    for doc in documents:
        minor_id = doc.get("minor_id") or doc.get("related_entity_id")
        minor_name = doc.get("minor_name") or doc.get("athlete_name")
        
        # Check if this is a document for a minor (gdpr_minor type or has minor_id)
        is_minor_doc = doc.get("document_type") == "gdpr_minor" or (minor_id and minor_name)
        
        if is_minor_doc and minor_id:
            if minor_id not in grouped["minors"]:
                grouped["minors"][minor_id] = {
                    "minor_id": minor_id,
                    "minor_name": minor_name,
                    "documents": []
                }
            grouped["minors"][minor_id]["documents"].append(doc)
        else:
            grouped["personal"].append(doc)
    
    # Add consent-based virtual documents ONLY if no real GDPR signed document exists
    # Check if there's already a real signed GDPR document for this user
    has_real_gdpr_doc = any(
        d.get("document_type") in ("gdpr_adult", "gdpr_privacy_adult", "privacy_consent")
        for d in grouped["personal"]
    )
    
    target_user = await db.users.find_one(
        {"id": target_user_id},
        {"_id": 0, "consents": 1, "legal_accepted_at": 1, "full_name": 1}
    )
    parent_name = target_user.get("full_name", "") if target_user else ""
    consent_docs = []
    if target_user and target_user.get("consents") and not has_real_gdpr_doc:
        consents = target_user["consents"]
        consent_label_map = {
            "privacy_viewed": "Informativa Privacy - Presa visione",
        }
        for ckey, clabel in consent_label_map.items():
            c = consents.get(ckey)
            if c is None:
                continue
            # Handle both formats: simple bool or dict with "value"
            if isinstance(c, bool):
                c_value = c
                c_timestamp = None
            elif isinstance(c, dict):
                c_value = c.get("value", False)
                c_timestamp = c.get("timestamp")
            else:
                continue
            if c_value:
                consent_docs.append({
                    "id": f"consent_{ckey}_{target_user_id}",
                    "document_type": f"consent_{ckey}",
                    "document_title": clabel,
                    "signed_at": c_timestamp,
                    "created_at": c_timestamp,
                    "is_consent_record": True,
                    "consent_metadata": {
                        "source": c.get("source", "registration") if isinstance(c, dict) else "registration",
                        "ip_address": c.get("ip_address") if isinstance(c, dict) else None,
                        "document_version": c.get("document_version") if isinstance(c, dict) else None,
                        "user_id": c.get("user_id") if isinstance(c, dict) else None,
                    }
                })
        # Note: Terms of Use are not shown as downloadable documents (no PDF generated)
    
    # Merge consent docs with personal section and sort by date (newest first)
    all_personal = consent_docs + grouped["personal"]
    def get_doc_date(d):
        dt = d.get("signed_at") or d.get("created_at")
        if dt is None:
            return ""
        return str(dt)
    all_personal.sort(key=get_doc_date, reverse=True)
    grouped["personal"] = all_personal
    
    # Convert minors dict to list for easier frontend handling
    minors_list = list(grouped["minors"].values())
    
    return {
        "documents": documents,  # Flat list for backwards compatibility
        "grouped": {
            "personal": grouped["personal"],
            "minors": minors_list,
            "parent_name": parent_name,
        },
        "total": len(documents) + len(consent_docs)
    }

# ==================== GDPR DATA DELETION ENDPOINT ====================

@api_router.delete("/auth/delete-my-data")
async def delete_my_data(current_user = Depends(get_current_user)):
    """
    GDPR-compliant endpoint for users to delete all their personal data.
    This is an irreversible action.
    """
    user_id = current_user.get("id")
    email = current_user.get("email")
    role = current_user.get("role")
    
    if not user_id:
        raise HTTPException(status_code=400, detail="ID utente non trovato")
    
    # Track what was deleted for logging
    deleted_items = {
        "user": False,
        "athlete": False,
        "documents": 0,
        "certificates": 0,
        "notifications": 0,
        "receipts": 0
    }
    
    try:
        # 1. Delete all signed documents related to this user
        doc_result = await db.signed_documents.delete_many({
            "$or": [
                {"signer_id": user_id},
                {"athlete_id": user_id},
                {"coach_id": user_id},
                {"dirigente_id": user_id},
                {"collaboratore_id": user_id},
                {"parent_id": user_id}
            ]
        })
        deleted_items["documents"] = doc_result.deleted_count
        
        # 2. Delete receipts (compensation records)
        receipt_result = await db.receipts.delete_many({
            "$or": [
                {"user_id": user_id},
                {"athlete_id": user_id},
                {"coach_id": user_id},
                {"collaboratore_id": user_id}
            ]
        })
        deleted_items["receipts"] = receipt_result.deleted_count
        
        # 3. Delete notifications
        notif_result = await db.notifications.delete_many({"user_id": user_id})
        deleted_items["notifications"] = notif_result.deleted_count
        
        # 4. If user is an athlete or has athlete_id, delete athlete record and certificates
        athlete_id = current_user.get("athlete_id")
        if athlete_id:
            # Delete medical certificates
            cert_result = await db.certificates.delete_many({"athlete_id": athlete_id})
            deleted_items["certificates"] = cert_result.deleted_count
            
            # Delete athlete record
            await db.athletes.delete_one({"id": athlete_id})
            deleted_items["athlete"] = True
        
        # 5. Delete the user account itself
        await db.users.delete_one({"id": user_id})
        deleted_items["user"] = True
        
        # Log the deletion (without PII)
        logger.info(f"GDPR deletion completed for user with role '{role}'. Deleted: {deleted_items}")
        
        return {
            "success": True,
            "message": "Tutti i tuoi dati personali sono stati eliminati in conformità al GDPR.",
            "deleted": deleted_items
        }
        
    except Exception as e:
        logger.error(f"Error during GDPR deletion for user {user_id}: {str(e)}")
        raise HTTPException(
            status_code=500, 
            detail="Si è verificato un errore durante l'eliminazione dei dati. Contatta l'amministratore."
        )

# ==================== SOCIETY CARD PDF ENDPOINTS ====================

@api_router.api_route("/society/card-fiscale", methods=["GET", "POST"])
async def generate_fiscal_card(current_user = Depends(get_current_user)):
    """Genera immagine JPG biglietto da visita della societa - design professionale"""
    _sid = current_user.get("society_id")
    _q = {"type": "society"}
    if _sid:
        _q["society_id"] = _sid
    society = await db.settings.find_one(_q)
    if not society and _sid:
        society = await db.societies.find_one({"id": _sid})
    if not society:
        raise HTTPException(status_code=404, detail="Societa non trovata")
    
    from PIL import Image, ImageDraw, ImageFont
    import base64
    
    # === Color Palette ===
    PRIMARY = (21, 101, 192)       # Blu principale
    PRIMARY_DARK = (13, 71, 161)   # Blu scuro per accenti
    PRIMARY_LIGHT = (227, 242, 253) # Azzurro chiaro sfondo
    DARK_TEXT = (26, 26, 46)
    MID_TEXT = (70, 70, 90)
    LIGHT_TEXT = (130, 130, 150)
    WHITE = (255, 255, 255)
    SEPARATOR = (200, 210, 225)
    GOLD_ACCENT = (218, 165, 32)
    
    FONT_BOLD = "/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf"
    FONT_REG = "/usr/share/fonts/truetype/liberation/LiberationSans-Regular.ttf"
    FONT_ITALIC = "/usr/share/fonts/truetype/liberation/LiberationSans-Italic.ttf"
    try:
        font_name_big = ImageFont.truetype(FONT_BOLD, 26)
        font_ragione = ImageFont.truetype(FONT_ITALIC, 13)
        font_label = ImageFont.truetype(FONT_BOLD, 10)
        font_value = ImageFont.truetype(FONT_REG, 13)
        font_value_bold = ImageFont.truetype(FONT_BOLD, 13)
        font_aff_label = ImageFont.truetype(FONT_BOLD, 10)
        font_aff_value = ImageFont.truetype(FONT_REG, 12)
        font_sport = ImageFont.truetype(FONT_BOLD, 11)
    except Exception:
        font_name_big = font_ragione = font_label = font_value = font_value_bold = ImageFont.load_default()
        font_aff_label = font_aff_value = font_sport = font_label
    
    # === Data extraction ===
    full_name = society.get("name", "Societa Sportiva")
    ragione_sociale = society.get("ragione_sociale", "")
    sport = society.get("sport_praticato", "")
    address = society.get("address", "")
    postal_code = society.get("postal_code", "")
    city = society.get("city", "")
    province = society.get("province", "")
    phone = society.get("phone", "")
    phone2 = society.get("phone2", "")
    email = society.get("email", "")
    pec = society.get("pec", "")
    fiscal_code = society.get("fiscal_code", "")
    partita_iva = society.get("partita_iva", "")
    codice_sdi = society.get("codice_sdi", "")
    president = society.get("president_name", "")
    affiliations = society.get("affiliations", [])
    logo_data = society.get("logo")
    if not logo_data and society.get("logo_storage_path"):
        from storage_util import get_image_datauri
        logo_data = await get_image_datauri(society["logo_storage_path"])
    # === Layout constants ===
    W = 720
    pad_x = 32
    pad_y = 24
    
    # --- Measure content to determine height ---
    tmp_img = Image.new('RGB', (W, 50), WHITE)
    tmp_draw = ImageDraw.Draw(tmp_img)
    
    # Measure name
    name_upper = full_name.upper()
    bbox_name = tmp_draw.textbbox((0, 0), name_upper, font=font_name_big)
    name_h = bbox_name[3] - bbox_name[1]
    
    # === Build the card ===
    # Generous height, we'll crop later
    img = Image.new('RGB', (W, 600), WHITE)
    draw = ImageDraw.Draw(img)
    
    # --- Top accent bar (gradient-like with 2 stripes) ---
    draw.rectangle([(0, 0), (W, 5)], fill=PRIMARY)
    draw.rectangle([(0, 5), (W, 7)], fill=GOLD_ACCENT)
    
    y = pad_y + 7
    
    # --- HEADER: Logo + Nome + Ragione Sociale ---
    logo_size = 80
    logo_placed = False
    logo_right_x = pad_x
    
    if logo_data:
        try:
            if ',' in logo_data:
                logo_data = logo_data.split(',')[1]
            logo_bytes = base64.b64decode(logo_data)
            logo_img = Image.open(io.BytesIO(logo_bytes)).convert('RGBA')
            w, h = logo_img.size
            ratio = min(logo_size / w, logo_size / h)
            new_w, new_h = int(w * ratio), int(h * ratio)
            logo_img = logo_img.resize((new_w, new_h), Image.LANCZOS)
            # Paste with white background
            bg_patch = Image.new('RGB', (new_w, new_h), WHITE)
            bg_patch.paste(logo_img, (0, 0), logo_img)
            logo_y = y + (logo_size - new_h) // 2
            img.paste(bg_patch, (pad_x, logo_y))
            logo_right_x = pad_x + new_w + 16
            logo_placed = True
        except Exception:
            logo_right_x = pad_x
    
    # Name - centered vertically with logo area
    text_x = logo_right_x
    name_y = y + 8
    draw.text((text_x, name_y), name_upper, fill=PRIMARY_DARK, font=font_name_big)
    
    # Ragione Sociale sotto il nome
    rs_y = name_y + name_h + 6
    if ragione_sociale:
        draw.text((text_x, rs_y), ragione_sociale, fill=LIGHT_TEXT, font=font_ragione)
        rs_y += 18
    
    # Sport badge
    if sport:
        badge_y = rs_y + 2
        sport_text = sport.upper()
        bbox_sport = draw.textbbox((0, 0), sport_text, font=font_sport)
        sport_w = bbox_sport[2] - bbox_sport[0]
        # Draw rounded badge background
        badge_pad = 8
        badge_h = 20
        x0 = text_x
        y0 = badge_y
        x1 = x0 + sport_w + badge_pad * 2
        y1 = y0 + badge_h
        draw.rounded_rectangle([(x0, y0), (x1, y1)], radius=4, fill=PRIMARY_LIGHT)
        draw.text((x0 + badge_pad, y0 + 3), sport_text, fill=PRIMARY, font=font_sport)
        rs_y = y1 + 4
    
    # y after header
    header_bottom = max(y + logo_size + 8 if logo_placed else rs_y + 4, rs_y + 4)
    
    # --- Separator line ---
    sep_y = header_bottom + 4
    draw.line([(pad_x, sep_y), (W - pad_x, sep_y)], fill=PRIMARY, width=2)
    
    # --- BODY: Info in 2 columns ---
    body_y = sep_y + 14
    col_left_x = pad_x
    col_right_x = W // 2 + 14
    row_h = 36
    icon_indent = 0  # No icons in JPG, use label+value style
    
    def draw_field(x, y, label, value, bold_value=False):
        """Draw a label-value pair and return new y"""
        if not value:
            return y
        draw.text((x, y), label.upper(), fill=PRIMARY, font=font_label)
        vfont = font_value_bold if bold_value else font_value
        draw.text((x, y + 13), str(value), fill=DARK_TEXT, font=vfont)
        return y + row_h
    
    # LEFT COLUMN: Indirizzo, CAP/Citta, Cod. Fiscale, P. IVA
    y_left = body_y
    
    # Indirizzo
    if address:
        draw.text((col_left_x, y_left), "INDIRIZZO", fill=PRIMARY, font=font_label)
        draw.text((col_left_x, y_left + 13), address, fill=DARK_TEXT, font=font_value)
        y_left += row_h
    
    # CAP, Citta (Prov.)
    location = ""
    if postal_code:
        location += postal_code
    if city:
        location += f"  {city}" if location else city
    if province:
        location += f" ({province})"
    if location:
        draw.text((col_left_x, y_left), "CAP / CITTA", fill=PRIMARY, font=font_label)
        draw.text((col_left_x, y_left + 13), location.strip(), fill=DARK_TEXT, font=font_value)
        y_left += row_h
    
    # Codice Fiscale
    if fiscal_code:
        y_left = draw_field(col_left_x, y_left, "Cod. Fiscale", fiscal_code, bold_value=True)
    
    # Partita IVA
    if partita_iva:
        y_left = draw_field(col_left_x, y_left, "P. IVA", partita_iva, bold_value=True)
    
    # Codice SDI (fatturazione elettronica)
    if codice_sdi:
        y_left = draw_field(col_left_x, y_left, "Codice SDI", codice_sdi.upper(), bold_value=True)
    
    # RIGHT COLUMN: Email, PEC, Telefono, Presidente
    y_right = body_y
    
    # Email
    if email:
        y_right = draw_field(col_right_x, y_right, "Email", email)
    
    # PEC
    if pec:
        y_right = draw_field(col_right_x, y_right, "PEC", pec)
    
    # Telefono (spostato a destra dopo PEC)
    phone_str = ""
    if phone:
        phone_str = phone
    if phone2:
        phone_str += f"  /  {phone2}" if phone_str else phone2
    if phone_str:
        y_right = draw_field(col_right_x, y_right, "Telefono", phone_str)
    
    # Presidente
    if president:
        y_right = draw_field(col_right_x, y_right, "Presidente", president)
    
    # --- AFFILIAZIONI (below both columns) ---
    bottom_y = max(y_left, y_right) + 6
    
    if affiliations:
        draw.line([(pad_x, bottom_y), (W - pad_x, bottom_y)], fill=SEPARATOR, width=1)
        bottom_y += 10
        
        # Header
        draw.text((pad_x, bottom_y), "AFFILIAZIONI SPORTIVE", fill=PRIMARY, font=font_aff_label)
        bottom_y += 16
        
        for aff in affiliations:
            aff_name = aff.get('name', '')
            aff_number = aff.get('number', '')
            # Draw federation name
            draw.text((pad_x + 8, bottom_y), aff_name, fill=MID_TEXT, font=font_aff_label)
            # Draw code next to it
            name_bbox = draw.textbbox((0, 0), aff_name + "  ", font=font_aff_label)
            name_w = name_bbox[2] - name_bbox[0]
            draw.text((pad_x + 8 + name_w, bottom_y), aff_number, fill=DARK_TEXT, font=font_value_bold)
            bottom_y += 20
    
    # --- Bottom accent bar ---
    final_h = bottom_y + pad_y
    img = img.crop((0, 0, W, final_h))
    draw = ImageDraw.Draw(img)
    draw.rectangle([(0, final_h - 5), (W, final_h - 2)], fill=GOLD_ACCENT)
    draw.rectangle([(0, final_h - 2), (W, final_h)], fill=PRIMARY)
    
    # Add thin border
    draw.rectangle([(0, 0), (W - 1, final_h - 1)], outline=(220, 220, 230), width=1)
    
    buffer = io.BytesIO()
    img.save(buffer, format='JPEG', quality=95, dpi=(300, 300))
    buffer.seek(0)
    
    filename = f"Biglietto_{full_name.replace(' ', '_')}.jpg"
    return StreamingResponse(buffer, media_type="image/jpeg", headers={
        "Content-Disposition": f'attachment; filename="{filename}"',
        "Cache-Control": "no-cache, no-store, must-revalidate",
        "Pragma": "no-cache",
        "Expires": "0"
    })

@api_router.get("/society/card-bancaria")
async def generate_bank_card(current_user = Depends(get_current_user)):
    """Genera immagine JPG con i dati bancari della societa"""
    _sid = current_user.get("society_id")
    _q = {"type": "society"}
    if _sid:
        _q["society_id"] = _sid
    society = await db.settings.find_one(_q)
    if not society and _sid:
        society = await db.societies.find_one({"id": _sid})
    if not society:
        raise HTTPException(status_code=404, detail="Societa non trovata")
    
    if not society.get("iban"):
        raise HTTPException(status_code=400, detail="Nessun IBAN inserito nel profilo societa")
    
    from PIL import Image, ImageDraw, ImageFont
    import base64
    
    W, H = 1200, 500
    img = Image.new('RGB', (W, H), '#FFFFFF')
    draw = ImageDraw.Draw(img)
    
    # Gradient background - subtle green to white
    for y in range(H):
        r = int(232 + (255 - 232) * y / H)
        g = int(245 + (255 - 245) * y / H)
        b = int(233 + (255 - 233) * y / H)
        draw.line([(0, y), (W, y)], fill=(r, g, b))
    
    # Top accent bar
    draw.rectangle([(0, 0), (W, 6)], fill='#2E7D32')
    # Bottom accent bar
    draw.rectangle([(0, H - 4), (W, H)], fill='#2E7D32')
    # Left accent bar
    draw.rectangle([(0, 0), (4, H)], fill='#2E7D32')
    
    try:
        font_title = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf", 28)
        font_label = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf", 16)
        font_iban = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf", 34)
        font_bank = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf", 18)
        font_small = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf", 14)
    except:
        font_title = ImageFont.load_default()
        font_label = font_iban = font_bank = font_small = font_title
    
    # Logo area (top left)
    logo_x, logo_y = 30, 24
    logo_size = 80
    logo_data = society.get("logo")
    if not logo_data and society.get("logo_storage_path"):
        from storage_util import get_image_datauri
        logo_data = await get_image_datauri(society["logo_storage_path"])
    if logo_data:
        try:
            if ',' in logo_data:
                logo_data = logo_data.split(',')[1]
            logo_bytes = base64.b64decode(logo_data)
            logo_img = Image.open(io.BytesIO(logo_bytes)).convert('RGBA')
            w, h = logo_img.size
            ratio = min(logo_size / w, logo_size / h)
            new_w, new_h = int(w * ratio), int(h * ratio)
            logo_img = logo_img.resize((new_w, new_h), Image.LANCZOS)
            paste_x = logo_x + (logo_size - new_w) // 2
            paste_y = logo_y + (logo_size - new_h) // 2
            img.paste(logo_img, (paste_x, paste_y), logo_img)
        except:
            pass
    
    name = society.get("ragione_sociale") or society.get("name", "Societa Sportiva")
    
    # Society name
    text_x = logo_x + logo_size + 20
    draw.text((text_x, 35), name.upper(), fill='#1B5E20', font=font_title)
    
    # Separator
    draw.line([(30, 120), (W - 30, 120)], fill='#2E7D32', width=2)
    
    # Section label
    draw.text((W // 2 - 120, 145), "COORDINATE BANCARIE", fill='#666', font=font_label)
    
    # Intestatario
    draw.text((W // 2 - 100, 185), f"Intestatario: {name}", fill='#333', font=font_bank)
    
    # IBAN - large and formatted
    iban_val = society.get("iban", "")
    iban_formatted = "  ".join([iban_val[i:i+4] for i in range(0, len(iban_val), 4)])
    
    # IBAN background box
    iban_box_y = 235
    draw.rounded_rectangle([(60, iban_box_y), (W - 60, iban_box_y + 70)], radius=12, fill='#E8F5E9', outline='#A5D6A7', width=2)
    
    # Center IBAN text
    iban_bbox = draw.textbbox((0, 0), iban_formatted, font=font_iban)
    iban_w = iban_bbox[2] - iban_bbox[0]
    draw.text(((W - iban_w) // 2, iban_box_y + 16), iban_formatted, fill='#1B5E20', font=font_iban)
    
    # Bank name
    if society.get("bank_name"):
        bank_text = f"Banca: {society['bank_name']}"
        bank_bbox = draw.textbbox((0, 0), bank_text, font=font_bank)
        bank_w = bank_bbox[2] - bank_bbox[0]
        draw.text(((W - bank_w) // 2, iban_box_y + 90), bank_text, fill='#555', font=font_bank)
    
    # Footer note
    footer_text = "Utilizzare queste coordinate per i pagamenti alla societa"
    ft_bbox = draw.textbbox((0, 0), footer_text, font=font_small)
    ft_w = ft_bbox[2] - ft_bbox[0]
    draw.text(((W - ft_w) // 2, H - 45), footer_text, fill='#999', font=font_small)
    
    buffer = io.BytesIO()
    img.save(buffer, format='JPEG', quality=92)
    buffer.seek(0)
    
    filename = f"Dati_Bancari_{name.replace(' ', '_')}.jpg"
    return StreamingResponse(buffer, media_type="image/jpeg", headers={"Content-Disposition": f'attachment; filename="{filename}"', "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0", "Pragma": "no-cache", "Expires": "0"})

# ==================== TRIAL PERIOD ENDPOINTS ====================


@api_router.get("/athletes/{athlete_id}/profile-check")
async def check_athlete_profile_completeness(athlete_id: str, current_user = Depends(get_current_user)):
    """Check if parent and athlete profiles are complete for document generation"""
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    # Check the CURRENT user's profile (the one who will sign), not necessarily parent_id
    parent = await db.users.find_one({"id": current_user["id"]})
    
    parent_missing = validate_parent_profile(parent) if parent else ["Account genitore non trovato"]
    athlete_missing = validate_athlete_profile(athlete)
    
    # Check if parent has set data protection password for this athlete
    if parent and current_user["role"] == UserRole.PARENT:
        # 🐛 09/07/2026 (v7.14) fix — Basta che UNA delle 2 password sia impostata
        # (primary O secondo genitore). Prima il check era slot-specific e falliva
        # se l'utente era stato re-associato ad uno slot diverso rispetto a dove
        # aveva salvato la password (segnalazione utente: alert "Password
        # protezione dati" ricorrente pur avendola impostata).
        has_pw = bool(
            athlete.get("data_password_hash")
            or athlete.get("second_parent_data_password_hash")
        )
        if not has_pw:
            parent_missing.append("Password protezione dati")
    
    is_complete = len(parent_missing) == 0 and len(athlete_missing) == 0
    
    return {
        "is_complete": is_complete,
        "parent_missing": parent_missing,
        "athlete_missing": athlete_missing
    }


@api_router.get("/athletes/{athlete_id}/trial-document")
async def generate_trial_document(athlete_id: str, current_user = Depends(get_current_user)):
    """Genera il PDF della dichiarazione per il periodo di prova"""
    if current_user["role"] not in [UserRole.PARENT, UserRole.ADMIN, UserRole.ATHLETE]:
        raise HTTPException(status_code=403, detail="Accesso non autorizzato")
    
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    is_minor = athlete.get("is_minor", False)
    
    # Verify ownership
    if current_user["role"] == UserRole.PARENT:
        if athlete.get("parent_id") != current_user["id"] and athlete.get("second_parent_id") != current_user["id"]:
            raise HTTPException(status_code=403, detail="Non sei il genitore di questo atleta")
    elif current_user["role"] == UserRole.ATHLETE:
        if athlete.get("user_id") != current_user["id"]:
            raise HTTPException(status_code=403, detail="Non sei autorizzato")
    
    # Get parent info
    parent = await db.users.find_one({"id": athlete.get("parent_id")})
    
    # Validate profiles before generating document
    check_profiles_for_document(parent=parent, athlete=athlete)
    
    # Get society info
    society = await db.societies.find_one({"id": athlete.get("society_id")})
    society_name = (society.get("ragione_sociale") or society.get("name") or "Societa Sportiva") if society else "Societa Sportiva"
    
    # Get trial settings from society settings — 🐛 08/07/2026 fix multi-tenancy
    _asid_ts = athlete.get("society_id")
    society_settings = await db.settings.find_one({"type": "society", "society_id": _asid_ts}) if _asid_ts else await db.settings.find_one({"type": "society"})
    trial_max_days = (society_settings.get("trial_max_days", 7) if society_settings else 7)
    trial_max_sessions = (society_settings.get("trial_max_sessions", 3) if society_settings else 3)
    
    # Generate PDF
    from reportlab.lib.pagesizes import A4
    from reportlab.lib.units import cm, mm
    from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
    from reportlab.lib.enums import TA_CENTER, TA_JUSTIFY, TA_LEFT, TA_RIGHT
    from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, HRFlowable
    from reportlab.lib.colors import HexColor, black, grey, white
    
    buffer = io.BytesIO()
    doc = SimpleDocTemplate(buffer, pagesize=A4, leftMargin=2.5*cm, rightMargin=2.5*cm, topMargin=2*cm, bottomMargin=2*cm)
    
    # Colors
    primary = HexColor('#1a237e')
    accent = HexColor('#0d47a1')
    light_bg = HexColor('#f5f7fa')
    border_color = HexColor('#d0d7de')
    text_dark = HexColor('#1a1a2e')
    text_muted = HexColor('#555555')
    
    styles = getSampleStyleSheet()
    title_style = ParagraphStyle('TitleStyle', parent=styles['Title'], fontSize=15, spaceAfter=2, textColor=primary, fontName='Helvetica-Bold', alignment=TA_CENTER)
    doc_title_style = ParagraphStyle('DocTitle', parent=styles['Normal'], fontSize=11, alignment=TA_CENTER, spaceAfter=16, textColor=accent, fontName='Helvetica-Bold', leading=14)
    heading_style = ParagraphStyle('HeadingStyle', parent=styles['Normal'], fontSize=10, spaceBefore=14, spaceAfter=6, textColor=white, fontName='Helvetica-Bold', backColor=primary, leading=16)
    body_justify = ParagraphStyle('BodyJustify', parent=styles['Normal'], fontSize=9.5, leading=14, alignment=TA_JUSTIFY, spaceAfter=4, fontName='Helvetica')
    bullet_style = ParagraphStyle('BulletStyle', parent=styles['Normal'], fontSize=9.5, leading=14, alignment=TA_JUSTIFY, leftIndent=16, spaceAfter=3, fontName='Helvetica')
    highlight_style = ParagraphStyle('Highlight', parent=styles['Normal'], fontSize=10, leading=15, alignment=TA_JUSTIFY, spaceAfter=4, fontName='Helvetica-Bold', textColor=accent)
    footer_style = ParagraphStyle('Footer', parent=styles['Normal'], fontSize=7.5, textColor=HexColor('#999999'), alignment=TA_CENTER, leading=10)
    
    elements = []
    
    # === HEADER ===
    elements.append(Paragraph(society_name.upper(), title_style))
    elements.append(Spacer(1, 3))
    elements.append(HRFlowable(width="100%", thickness=2, color=primary))
    elements.append(Spacer(1, 10))
    elements.append(Paragraph("DICHIARAZIONE PER PERIODO DI PROVA ATLETA MINORE", doc_title_style))
    
    # === DATI GENITORE (table with background) ===
    section_header_style = TableStyle([
        ('BACKGROUND', (0, 0), (-1, 0), primary),
        ('TEXTCOLOR', (0, 0), (-1, 0), white),
        ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
        ('FONTSIZE', (0, 0), (-1, 0), 10),
        ('BOTTOMPADDING', (0, 0), (-1, 0), 6),
        ('TOPPADDING', (0, 0), (-1, 0), 6),
        ('LEFTPADDING', (0, 0), (-1, 0), 10),
    ])
    
    data_table_style = TableStyle([
        ('FONTNAME', (0, 0), (0, -1), 'Helvetica'),
        ('FONTNAME', (1, 0), (1, -1), 'Helvetica-Bold'),
        ('FONTSIZE', (0, 0), (-1, -1), 9.5),
        ('TEXTCOLOR', (0, 0), (0, -1), text_muted),
        ('TEXTCOLOR', (1, 0), (1, -1), text_dark),
        ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
        ('BOTTOMPADDING', (0, 0), (-1, -1), 5),
        ('TOPPADDING', (0, 0), (-1, -1), 5),
        ('LEFTPADDING', (0, 0), (-1, -1), 10),
        ('BACKGROUND', (0, 0), (-1, -1), light_bg),
        ('BOX', (0, 0), (-1, -1), 0.5, border_color),
        ('LINEBELOW', (0, 0), (-1, -2), 0.3, border_color),
    ])
    
    # Section: Genitore
    sh1 = Table([["DATI DEL GENITORE / TUTORE"]], colWidths=[16*cm])
    sh1.setStyle(section_header_style)
    elements.append(sh1)
    
    parent_name = parent.get("full_name", "") if parent else ""
    parent_phone = parent.get("phone", "") if parent else ""
    parent_cf = parent.get("fiscal_code", "") if parent else ""
    
    parent_qualifier = "in qualita di genitore/tutore del minore"
    
    pd = Table([
        ["Nome e Cognome:", parent_name or "________________________________"],
        ["Codice Fiscale:", parent_cf or "________________________________"],
        ["Telefono:", parent_phone or "________________________________"],
    ], colWidths=[4*cm, 12*cm])
    pd.setStyle(data_table_style)
    elements.append(pd)
    elements.append(Spacer(1, 4))
    elements.append(Paragraph(f"<i>{parent_qualifier}</i>", ParagraphStyle('Qualifier', parent=styles['Normal'], fontSize=9, textColor=text_muted, fontName='Helvetica-Oblique', alignment=TA_CENTER)))
    elements.append(Spacer(1, 8))
    
    # Section: Minore
    sh2 = Table([["DATI DELL'ATLETA MINORE"]], colWidths=[16*cm])
    sh2.setStyle(section_header_style)
    elements.append(sh2)
    
    athlete_name = athlete.get("full_name", "")
    athlete_dob_raw = athlete.get("date_of_birth", "")
    athlete_dob = ""
    if athlete_dob_raw:
        if isinstance(athlete_dob_raw, str):
            try:
                dob_dt = datetime.fromisoformat(athlete_dob_raw.replace('Z', '+00:00'))
                athlete_dob = dob_dt.strftime("%d/%m/%Y")
            except:
                athlete_dob = athlete_dob_raw
        elif isinstance(athlete_dob_raw, datetime):
            athlete_dob = athlete_dob_raw.strftime("%d/%m/%Y")
    athlete_cf = athlete.get("codice_fiscale", "") or athlete.get("fiscal_code", "")
    
    md = Table([
        ["Nome e Cognome:", athlete_name or "________________________________"],
        ["Data di Nascita:", athlete_dob or "________________________________"],
        ["Codice Fiscale:", athlete_cf or "________________________________"],
    ], colWidths=[4*cm, 12*cm])
    md.setStyle(data_table_style)
    elements.append(md)
    elements.append(Spacer(1, 10))
    
    # === RICHIESTA ===
    sh3 = Table([["RICHIESTA"]], colWidths=[16*cm])
    sh3.setStyle(section_header_style)
    elements.append(sh3)
    elements.append(Spacer(1, 6))
    elements.append(Paragraph(
        f"CHIEDE che il minore sopra indicato possa partecipare ad un periodo di prova "
        f"dell'attivita sportiva organizzata dalla societa sportiva <b>{society_name}</b>.",
        body_justify
    ))
    elements.append(Spacer(1, 6))
    
    # === DICHIARA ===
    sh4 = Table([["DICHIARA"]], colWidths=[16*cm])
    sh4.setStyle(section_header_style)
    elements.append(sh4)
    elements.append(Spacer(1, 6))
    
    declarations = [
        "di essere consapevole che la pratica dell'attivita sportiva richiede idonea certificazione medica;",
        "che il minore, per quanto a propria conoscenza, non presenta condizioni ostative alla pratica sportiva;",
        "di impegnarsi a consegnare il certificato medico entro il periodo di prova stabilito dalla societa;",
        "di essere informato/a che, in assenza del certificato medico entro i termini previsti, il minore non potra proseguire l'attivita sportiva;",
    ]
    for decl in declarations:
        elements.append(Paragraph(f"\u2022  {decl}", bullet_style))
    
    elements.append(Spacer(1, 8))
    
    # === DURATA PERIODO DI PROVA (highlighted box) ===
    sh5 = Table([["DURATA DEL PERIODO DI PROVA"]], colWidths=[16*cm])
    sh5.setStyle(section_header_style)
    elements.append(sh5)
    elements.append(Spacer(1, 6))
    
    duration_text = (
        f"Il periodo di prova ha durata massima di <b>{trial_max_days} giorni</b> a partire dalla prima "
        f"presenza registrata presso la societa e comunque e limitato ad un massimo di "
        f"<b>{trial_max_sessions} allenamenti</b>."
    )
    # Highlighted box for duration
    dur_table = Table([[Paragraph(duration_text, highlight_style)]], colWidths=[15.4*cm])
    dur_table.setStyle(TableStyle([
        ('BACKGROUND', (0, 0), (-1, -1), HexColor('#e3f2fd')),
        ('BOX', (0, 0), (-1, -1), 1, accent),
        ('LEFTPADDING', (0, 0), (-1, -1), 12),
        ('RIGHTPADDING', (0, 0), (-1, -1), 12),
        ('TOPPADDING', (0, 0), (-1, -1), 10),
        ('BOTTOMPADDING', (0, 0), (-1, -1), 10),
    ]))
    elements.append(dur_table)
    elements.append(Spacer(1, 10))
    
    # === PAGE BREAK - Accettazione su Pagina 2 ===
    from reportlab.platypus import PageBreak
    elements.append(PageBreak())
    
    # Ripeti header su pagina 2
    elements.append(Paragraph(society_name.upper(), title_style))
    elements.append(Spacer(1, 3))
    elements.append(HRFlowable(width="100%", thickness=2, color=primary))
    elements.append(Spacer(1, 10))
    
    # === ACCETTAZIONE ===
    sh6 = Table([["ACCETTAZIONE"]], colWidths=[16*cm])
    sh6.setStyle(section_header_style)
    elements.append(sh6)
    elements.append(Spacer(1, 6))
    elements.append(Paragraph(
        "Con la sottoscrizione del presente documento il genitore/tutore autorizza la partecipazione del "
        "minore al periodo di prova alle condizioni sopra indicate.",
        body_justify
    ))
    elements.append(Spacer(1, 20))
    
    # === FIRMA DIGITALE ===
    elements.append(HRFlowable(width="100%", thickness=0.5, color=border_color))
    elements.append(Spacer(1, 14))
    
    sign_data = [
        ["", "Firma del genitore/tutore:"],
        ["", ""],
        ["", "____________________________"],
    ]
    t3 = Table(sign_data, colWidths=[8*cm, 8*cm])
    t3.setStyle(TableStyle([
        ('FONTNAME', (0, 0), (-1, -1), 'Helvetica'),
        ('FONTSIZE', (0, 0), (-1, -1), 9.5),
        ('VALIGN', (0, 0), (-1, -1), 'TOP'),
        ('TOPPADDING', (0, 0), (-1, -1), 4),
        ('BOTTOMPADDING', (0, 0), (-1, -1), 4),
        ('ALIGN', (1, 0), (1, -1), 'RIGHT'),
    ]))
    elements.append(t3)
    
    elements.append(Spacer(1, 20))
    elements.append(Paragraph(
        f"<i>Documento generato automaticamente da {society_name} tramite RegistraTEAM</i>",
        footer_style
    ))
    
    def _trial_preview_footer(canvas_obj, doc_obj):
        canvas_obj.saveState()
        page_num = doc_obj.page
        canvas_obj.setFont('Helvetica', 8)
        canvas_obj.setFillColor(HexColor('#999999'))
        canvas_obj.drawCentredString(A4[0]/2, 1.5*cm, f"Pagina {page_num} di 2")
        canvas_obj.restoreState()
    
    doc.build(elements, onFirstPage=_trial_preview_footer, onLaterPages=_trial_preview_footer)
    buffer.seek(0)
    
    # GET endpoint is preview only - does NOT mark as generated/signed
    
    filename = f"Dichiarazione_Prova_{athlete.get('last_name', '')}_{athlete.get('first_name', '')}.pdf"
    
    return StreamingResponse(
        buffer,
        media_type="application/pdf",
        headers={"Content-Disposition": f'attachment; filename="{filename}"', "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0", "Pragma": "no-cache", "Expires": "0"}
    )

class TrialSignRequest(BaseModel):
    signature_base64: str

@api_router.post("/athletes/{athlete_id}/sign-trial-document")
async def sign_trial_document(athlete_id: str, body: TrialSignRequest, request: Request, current_user = Depends(get_current_user)):
    """Firma digitale della dichiarazione periodo di prova e genera PDF firmato"""
    if current_user["role"] not in [UserRole.PARENT, UserRole.ADMIN, UserRole.ATHLETE]:
        raise HTTPException(status_code=403, detail="Accesso non autorizzato")
    
    if not body.signature_base64 or len(body.signature_base64) < 100:
        raise HTTPException(status_code=400, detail="Firma non valida. Disegna la tua firma nel riquadro.")
    
    # Lightweight projection: avoid loading heavy base64 photos (~1.7MB total
    # across athlete + signing user + settings) which caused 30s timeouts on
    # the first sign attempt.
    athlete = await db.athletes.find_one(
        {"id": athlete_id},
        {
            "_id": 0,
            "id": 1, "full_name": 1, "first_name": 1, "last_name": 1,
            "fiscal_code": 1, "date_of_birth": 1,
            "place_of_birth": 1, "birth_place": 1,
            "birth_province": 1, "province_of_birth": 1,
            "country_of_birth": 1,
            "is_minor": 1, "parent_id": 1, "second_parent_id": 1,
            "user_id": 1, "society_id": 1, "team_id": 1,
            "address": 1, "city": 1, "postal_code": 1, "province": 1,
            "trial_start_date": 1, "trial_end_date": 1, "trial_signed": 1,
            "status": 1,
        },
    )
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    # Anti-duplicate guard: prevent the same user from signing the same trial
    # document twice (this happened when the old 30s timeout caused users to
    # click "Firma" twice, creating two entries in the archive for the same signature).
    existing_trial_sign = await db.signed_documents.find_one(
        {
            "user_id": current_user["id"],
            "related_entity_id": athlete_id,
            "document_type": "trial_declaration",
            "signed": True,
        },
        {"_id": 0, "id": 1},
    )
    if existing_trial_sign:
        raise HTTPException(
            status_code=409,
            detail="Dichiarazione di Prova già firmata. Trovi la copia firmata nell'archivio documenti."
        )
    
    is_minor = athlete.get("is_minor", False)
    
    if current_user["role"] == UserRole.PARENT:
        if athlete.get("parent_id") != current_user["id"] and athlete.get("second_parent_id") != current_user["id"]:
            raise HTTPException(status_code=403, detail="Non sei il genitore di questo atleta")
    elif current_user["role"] == UserRole.ATHLETE:
        if athlete.get("user_id") != current_user["id"]:
            raise HTTPException(status_code=403, detail="Non sei autorizzato")
    
    # Usa i dati di chi sta firmando (current_user) - light projection (no photos)
    signing_parent = await db.users.find_one(
        {"id": current_user["id"]},
        {
            "_id": 0,
            "id": 1, "email": 1, "full_name": 1, "first_name": 1, "last_name": 1,
            "fiscal_code": 1, "date_of_birth": 1, "place_of_birth": 1,
            "address": 1, "city": 1, "postal_code": 1, "province": 1,
            "phone": 1, "role": 1, "society_id": 1,
        },
    )
    check_profiles_for_document(parent=signing_parent, athlete=athlete)
    
    society = await db.societies.find_one({"id": athlete.get("society_id")}, {"_id": 0, "name": 1, "ragione_sociale": 1})
    society_name = (society.get("ragione_sociale") or society.get("name") or "Societa Sportiva") if society else "Societa Sportiva"
    
    # Settings: only read the trial parameters (avoid loading logo/sport_image base64)
    society_settings = await db.settings.find_one(
        {"type": "society", "society_id": athlete.get("society_id")} if athlete.get("society_id") else {"type": "society"},
        {"_id": 0, "trial_max_days": 1, "trial_max_sessions": 1},
    )
    trial_max_days = (society_settings.get("trial_max_days", 7) if society_settings else 7)
    trial_max_sessions = (society_settings.get("trial_max_sessions", 3) if society_settings else 3)
    
    from reportlab.lib.pagesizes import A4
    from reportlab.lib.units import cm, mm
    from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
    from reportlab.lib.enums import TA_CENTER, TA_JUSTIFY, TA_LEFT, TA_RIGHT
    from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, HRFlowable, Image as RLImage
    from reportlab.lib.colors import HexColor, black, grey, white
    import base64
    
    buffer = io.BytesIO()
    doc = SimpleDocTemplate(buffer, pagesize=A4, leftMargin=2.5*cm, rightMargin=2.5*cm, topMargin=2*cm, bottomMargin=2*cm)
    
    primary = HexColor('#1a237e')
    accent = HexColor('#0d47a1')
    light_bg = HexColor('#f5f7fa')
    border_color = HexColor('#d0d7de')
    text_dark = HexColor('#1a1a2e')
    text_muted = HexColor('#555555')
    
    styles = getSampleStyleSheet()
    title_style = ParagraphStyle('TitleStyle', parent=styles['Title'], fontSize=15, spaceAfter=2, textColor=primary, fontName='Helvetica-Bold', alignment=TA_CENTER)
    doc_title_style = ParagraphStyle('DocTitle', parent=styles['Normal'], fontSize=11, alignment=TA_CENTER, spaceAfter=16, textColor=accent, fontName='Helvetica-Bold', leading=14)
    section_header_style_tbl = TableStyle([
        ('BACKGROUND', (0, 0), (-1, 0), primary),
        ('TEXTCOLOR', (0, 0), (-1, 0), white),
        ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
        ('FONTSIZE', (0, 0), (-1, 0), 10),
        ('BOTTOMPADDING', (0, 0), (-1, 0), 6),
        ('TOPPADDING', (0, 0), (-1, 0), 6),
        ('LEFTPADDING', (0, 0), (-1, 0), 10),
    ])
    data_table_style = TableStyle([
        ('FONTNAME', (0, 0), (0, -1), 'Helvetica'),
        ('FONTNAME', (1, 0), (1, -1), 'Helvetica-Bold'),
        ('FONTSIZE', (0, 0), (-1, -1), 9.5),
        ('TEXTCOLOR', (0, 0), (0, -1), text_muted),
        ('TEXTCOLOR', (1, 0), (1, -1), text_dark),
        ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
        ('TOPPADDING', (0, 0), (-1, -1), 5),
        ('BOTTOMPADDING', (0, 0), (-1, -1), 5),
        ('LEFTPADDING', (0, 0), (-1, -1), 10),
        ('BACKGROUND', (0, 0), (-1, -1), light_bg),
        ('GRID', (0, 0), (-1, -1), 0.5, border_color),
    ])
    body_justify = ParagraphStyle('BodyJustify', parent=styles['Normal'], fontSize=9.5, leading=14, alignment=TA_JUSTIFY, spaceAfter=4, fontName='Helvetica')
    bullet_style = ParagraphStyle('BulletStyle', parent=styles['Normal'], fontSize=9.5, leading=14, alignment=TA_JUSTIFY, leftIndent=16, spaceAfter=3, fontName='Helvetica')
    highlight_style = ParagraphStyle('Highlight', parent=styles['Normal'], fontSize=10, leading=15, alignment=TA_JUSTIFY, spaceAfter=4, fontName='Helvetica-Bold', textColor=accent)
    footer_style = ParagraphStyle('Footer', parent=styles['Normal'], fontSize=7.5, textColor=HexColor('#999999'), alignment=TA_CENTER, leading=10)
    
    elements = []
    
    # === HEADER ===
    elements.append(Paragraph(society_name.upper(), title_style))
    elements.append(Spacer(1, 3))
    elements.append(HRFlowable(width="100%", thickness=2, color=primary))
    elements.append(Spacer(1, 10))
    elements.append(Paragraph("DICHIARAZIONE PER PERIODO DI PROVA ATLETA" + (" MINORE" if is_minor else ""), doc_title_style))
    
    if is_minor:
        # === DATI GENITORE ===
        sh1 = Table([["DATI DEL GENITORE/TUTORE"]], colWidths=[16*cm])
        sh1.setStyle(section_header_style_tbl)
        elements.append(sh1)
        parent_name = signing_parent.get("full_name", "") if signing_parent else ""
        parent_cf = signing_parent.get("fiscal_code", "") if signing_parent else ""
        parent_phone = signing_parent.get("phone", "") if signing_parent else ""
        parent_email = signing_parent.get("email", "") if signing_parent else ""
        data1 = [
            ["Nome e Cognome:", parent_name],
            ["Codice Fiscale:", parent_cf],
            ["Telefono:", parent_phone],
            ["Email:", parent_email],
        ]
        t1 = Table(data1, colWidths=[5*cm, 11*cm])
        t1.setStyle(data_table_style)
        elements.append(t1)
        elements.append(Spacer(1, 10))
    else:
        # For adult athletes, signer_name is used instead of parent_name
        parent_name = signing_parent.get("full_name", "") if signing_parent else athlete.get("full_name", "")
    
    # === DATI ATLETA ===
    sh2 = Table([["DATI DELL'ATLETA" + (" MINORE" if is_minor else "")]], colWidths=[16*cm])
    sh2.setStyle(section_header_style_tbl)
    elements.append(sh2)
    athlete_name = athlete.get("full_name", "")
    athlete_dob = ""
    if athlete.get("date_of_birth"):
        dob = athlete["date_of_birth"]
        if isinstance(dob, str):
            try:
                dob = datetime.fromisoformat(dob.replace('Z', '+00:00'))
            except:
                pass
        if isinstance(dob, datetime):
            athlete_dob = dob.strftime("%d/%m/%Y")
    athlete_cf = athlete.get("fiscal_code", "")
    athlete_pob = athlete.get("place_of_birth") or athlete.get("birth_place", "")
    athlete_country = athlete.get("country_of_birth", "")
    if athlete_country and athlete_country.lower() != "italia":
        if athlete_pob:
            athlete_pob = f"{athlete_pob} ({athlete_country})"
        else:
            athlete_pob = athlete_country
    data2 = [
        ["Nome e Cognome:", athlete_name],
        ["Data di Nascita:", athlete_dob],
        ["Luogo di Nascita:", athlete_pob],
        ["Codice Fiscale:", athlete_cf],
    ]
    t2 = Table(data2, colWidths=[5*cm, 11*cm])
    t2.setStyle(data_table_style)
    elements.append(t2)
    elements.append(Spacer(1, 10))
    
    # === DICHIARAZIONE ===
    sh3 = Table([["DICHIARAZIONE"]], colWidths=[16*cm])
    sh3.setStyle(section_header_style_tbl)
    elements.append(sh3)
    elements.append(Spacer(1, 6))
    if is_minor:
        elements.append(Paragraph(
            f"Il/La sottoscritto/a <b>{parent_name}</b>, in qualita di genitore/tutore legale "
            f"dell'atleta minore <b>{athlete_name}</b>, dichiara di autorizzare la partecipazione "
            f"del minore al periodo di prova presso <b>{society_name}</b> alle seguenti condizioni:",
            body_justify
        ))
    else:
        signer_name = signing_parent.get("full_name", "") if signing_parent else athlete_name
        elements.append(Paragraph(
            f"Il/La sottoscritto/a <b>{signer_name}</b>, dichiara di voler partecipare "
            f"al periodo di prova presso <b>{society_name}</b> alle seguenti condizioni:",
            body_justify
        ))
    elements.append(Spacer(1, 6))
    
    # === CONDIZIONI ===
    sh4 = Table([["CONDIZIONI DEL PERIODO DI PROVA"]], colWidths=[16*cm])
    sh4.setStyle(section_header_style_tbl)
    elements.append(sh4)
    elements.append(Spacer(1, 6))
    elements.append(Paragraph(f"Il periodo di prova avra una durata massima di <b>{trial_max_days} giorni</b> dalla data della prima presenza registrata.", bullet_style))
    elements.append(Paragraph(f"Durante questo periodo, l'atleta potra partecipare a un massimo di <b>{trial_max_sessions} allenamenti</b>.", bullet_style))
    elements.append(Paragraph("La partecipazione e subordinata alla presentazione di un certificato medico valido per attivita sportiva non agonistica.", bullet_style))
    if is_minor:
        elements.append(Paragraph("Il genitore/tutore si impegna a comunicare tempestivamente eventuali problematiche di salute dell'atleta.", bullet_style))
        elements.append(Paragraph("Al termine del periodo di prova, l'atleta potra essere tesserato con il consenso del genitore/tutore.", bullet_style))
    else:
        elements.append(Paragraph("L'atleta si impegna a comunicare tempestivamente eventuali problematiche di salute.", bullet_style))
        elements.append(Paragraph("Al termine del periodo di prova, l'atleta potra procedere con il tesseramento.", bullet_style))
    elements.append(Spacer(1, 10))
    
    # === PAGE BREAK - Accettazione e Firma su Pagina 2 ===
    from reportlab.platypus import PageBreak
    elements.append(PageBreak())
    
    # Ripeti header su pagina 2
    elements.append(Paragraph(society_name.upper(), title_style))
    elements.append(Spacer(1, 3))
    elements.append(HRFlowable(width="100%", thickness=2, color=primary))
    elements.append(Spacer(1, 10))
    
    # === ACCETTAZIONE ===
    sh6 = Table([["ACCETTAZIONE"]], colWidths=[16*cm])
    sh6.setStyle(section_header_style_tbl)
    elements.append(sh6)
    elements.append(Spacer(1, 6))
    if is_minor:
        elements.append(Paragraph(
            "Con la sottoscrizione del presente documento il genitore/tutore autorizza la partecipazione del "
            "minore al periodo di prova alle condizioni sopra indicate.",
            body_justify
        ))
    else:
        elements.append(Paragraph(
            "Con la sottoscrizione del presente documento l'atleta dichiara di accettare le condizioni "
            "del periodo di prova sopra indicate e di parteciparvi volontariamente.",
            body_justify
        ))
    elements.append(Spacer(1, 14))
    
    # === FIRMA DIGITALE (embedded signature image) ===
    elements.append(HRFlowable(width="100%", thickness=0.5, color=border_color))
    elements.append(Spacer(1, 10))
    
    now = datetime.now(timezone.utc)
    rome_now = to_rome_time(now)
    sign_date_str = rome_now.strftime("%d/%m/%Y alle ore %H:%M")
    
    elements.append(Paragraph(f"<b>Firmato digitalmente il {sign_date_str}</b>", ParagraphStyle('SignDate', parent=styles['Normal'], fontSize=9, textColor=text_muted, fontName='Helvetica')))
    elements.append(Spacer(1, 6))
    elements.append(Paragraph("Firma del genitore/tutore:" if is_minor else "Firma dell'atleta:", ParagraphStyle('SignLabel', parent=styles['Normal'], fontSize=9.5, fontName='Helvetica', textColor=text_muted)))
    
    # Embed the actual signature image (subito sotto la label, allineata a sinistra)
    try:
        sig_data = body.signature_base64
        if ',' in sig_data:
            sig_data = sig_data.split(',')[1]
        sig_bytes = base64.b64decode(sig_data)
        sig_buffer = io.BytesIO(sig_bytes)
        sig_img = RLImage(sig_buffer, width=5*cm, height=2*cm, hAlign='LEFT')
        elements.append(sig_img)
    except Exception as e:
        logging.error(f"Error embedding signature: {e}")
        raise HTTPException(status_code=400, detail="Errore nell'elaborazione della firma")
    
    elements.append(Spacer(1, 6))
    elements.append(Paragraph(f"<b>{parent_name}</b>", ParagraphStyle('SignName', parent=styles['Normal'], fontSize=10, fontName='Helvetica-Bold', textColor=text_dark)))
    
    # === METADATI DI FIRMA (stile uniforme con altri documenti) ===
    elements.append(Spacer(1, 16))
    
    import hashlib
    ip_address = get_real_ip(request)
    user_agent = request.headers.get("user-agent", "unknown")
    timestamp_rome = to_rome_time(now).strftime("%Y-%m-%d %H:%M:%S")
    
    hash_content = f"{parent_name}|{athlete_name}|{athlete_cf}|{now.isoformat()}|{society_name}"
    document_hash = hashlib.sha256(hash_content.encode()).hexdigest()[:20] + "..."
    
    meta_line_style = ParagraphStyle('MetaLine', parent=styles['Normal'], fontSize=7, fontName='Helvetica', textColor=HexColor('#666666'), leading=11)
    
    elements.append(Paragraph("─" * 60, meta_line_style))
    elements.append(Spacer(1, 4))
    elements.append(Paragraph("METADATI DI VERIFICA (generati automaticamente)", meta_line_style))
    elements.append(Paragraph(f"Timestamp firma: {timestamp_rome}", meta_line_style))
    elements.append(Paragraph(f"Firmatario: {parent_name} (user_id: {current_user['id'][:12]}...)", meta_line_style))
    elements.append(Paragraph(f"Atleta: {athlete_name} | Society: {athlete.get('society_id', 'N/D')}", meta_line_style))
    elements.append(Paragraph(f"Hash firma: {document_hash}", meta_line_style))
    
    elements.append(Spacer(1, 14))
    elements.append(Paragraph(
        f"<i>Documento firmato digitalmente tramite RegistraTEAM per conto di {society_name}</i>",
        footer_style
    ))
    
    def _trial_signed_footer(canvas_obj, doc_obj):
        canvas_obj.saveState()
        page_num = doc_obj.page
        canvas_obj.setFont('Helvetica', 8)
        canvas_obj.setFillColor(HexColor('#999999'))
        canvas_obj.drawCentredString(A4[0]/2, 1.5*cm, f"Pagina {page_num} di 2")
        canvas_obj.restoreState()
    
    doc.build(elements, onFirstPage=_trial_signed_footer, onLaterPages=_trial_signed_footer)
    buffer.seek(0)
    
    # Mark as signed with signature data and timestamp
    await db.athletes.update_one(
        {"id": athlete_id},
        {"$set": {
            "trial_document_generated": True,
            "trial_document_signed_date": now.isoformat(),
            "trial_document_signed_by": current_user["id"],
            "is_trial": True,
        }}
    )
    
    filename = f"Dichiarazione_Prova_Firmata_{athlete.get('last_name', '')}_{athlete.get('first_name', '')}.pdf"
    
    # Save to signed_documents archive for parent's document section
    import base64 as b64_archive
    pdf_bytes_for_archive = buffer.getvalue()
    pdf_b64_archive = b64_archive.b64encode(pdf_bytes_for_archive).decode('utf-8')
    
    signed_doc_record = {
        "id": str(uuid.uuid4()),
        "document_type": "trial_declaration",
        "document_title": f"Dichiarazione Periodo di Prova - {athlete.get('full_name', '')}",
        "signer_id": current_user["id"],
        "signer_name": parent_name,
        "related_entity_id": athlete_id,
        "athlete_name": athlete.get("full_name", ""),
        "society_id": athlete.get("society_id"),
        "pdf_base64": pdf_b64_archive,
        "pdf_filename": filename,
        "signed_at": now,
        "created_at": now,
    }
    if is_minor:
        signed_doc_record["parent_id"] = current_user["id"]
        signed_doc_record["minor_id"] = athlete_id
        signed_doc_record["minor_name"] = athlete.get("full_name", "")
    await db.signed_documents.insert_one(signed_doc_record)
    
    # Log nell'audit trail
    await log_audit(
        action="trial_document_signed",
        user_id=current_user["id"],
        user_email=current_user.get("email", ""),
        society_id=athlete.get("society_id", ""),
        target_user_id=athlete_id,
        target_user_name=athlete.get("full_name", ""),
        ip_address=get_real_ip(request),
        details={
            "document_type": "trial_declaration",
            "athlete_name": athlete.get("full_name", ""),
            "signer_name": parent_name,
            "signed_at": now.isoformat()
        }
    )
    
    # Send email with signed PDF to signing parent
    try:
        pdf_bytes = buffer.getvalue()
        import base64 as b64_email
        pdf_base64 = b64_email.b64encode(pdf_bytes).decode('utf-8')
        
        signer_email = signing_parent.get("email", "") if signing_parent else ""
        signer_name = signing_parent.get("full_name", "") if signing_parent else ""
        athlete_name = athlete.get("full_name", "")
        
        if signer_email:
            html_content = f"""
            <html>
            <body style="font-family: Arial, sans-serif; padding: 20px;">
                <h2 style="color: #7B1FA2;">Dichiarazione di Prova - {athlete_name}</h2>
                <p>Gentile {signer_name},</p>
                <p>In allegato la dichiarazione firmata per il periodo di prova.</p>
                <p>Puoi sempre consultarla anche nell'app.</p>
                <br>
                <p style="color: #666; font-size: 12px;">
                    {society_name}<br>
                    Email generata automaticamente da RegistraTEAM
                </p>
            </body>
            </html>
            """
            
            await send_email_with_pdf(
                to_email=signer_email,
                subject=f"Dichiarazione di Prova firmata - {athlete_name}",
                html_content=html_content,
                pdf_base64=pdf_base64,
                pdf_filename=filename,
                to_name=signer_name
            )
            logging.info(f"Trial declaration email sent to {signer_email} for athlete {athlete_name}")
    except Exception as e:
        logging.warning(f"Could not send trial declaration email: {e}")
    
    buffer.seek(0)
    
    return StreamingResponse(
        buffer,
        media_type="application/pdf",
        headers={"Content-Disposition": f'attachment; filename="{filename}"', "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0", "Pragma": "no-cache", "Expires": "0"}
    )

@api_router.post("/athletes/{athlete_id}/start-trial")
async def start_trial_period(athlete_id: str, current_user = Depends(get_current_user)):
    """Attiva il periodo di prova per un atleta"""
    if current_user["role"] not in [UserRole.PARENT, UserRole.ADMIN]:
        raise HTTPException(status_code=403, detail="Accesso non autorizzato")
    
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    if current_user["role"] == UserRole.PARENT:
        if athlete.get("parent_id") != current_user["id"] and athlete.get("second_parent_id") != current_user["id"]:
            raise HTTPException(status_code=403, detail="Non sei il genitore di questo atleta")
    
    await db.athletes.update_one(
        {"id": athlete_id},
        {"$set": {"is_trial": True, "trial_document_generated": False, "trial_start_date": None, "trial_end_date": None}}
    )
    
    return {"message": "Periodo di prova attivato. Scarica il documento da stampare e far firmare il giorno del primo allenamento."}

@api_router.get("/athletes/{athlete_id}/trial-status")
async def get_trial_status(athlete_id: str, current_user = Depends(get_current_user)):
    """Ottieni lo stato del periodo di prova con sessioni e giorni"""
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    is_trial = athlete.get("is_trial", False)
    trial_start = athlete.get("trial_start_date")
    trial_end = athlete.get("trial_end_date")
    sessions_count = athlete.get("trial_sessions_count", 0)
    
    # Get trial limits from society settings — 🐛 08/07/2026 fix multi-tenancy
    _asid_tl = athlete.get("society_id")
    society_settings = await db.settings.find_one({"type": "society", "society_id": _asid_tl}) if _asid_tl else await db.settings.find_one({"type": "society"})
    max_days = society_settings.get("trial_max_days", 7) if society_settings else 7
    max_sessions = society_settings.get("trial_max_sessions", 3) if society_settings else 3
    
    days_remaining = None
    trial_expired = False
    sessions_remaining = max_sessions - sessions_count
    sessions_expired = sessions_count >= max_sessions
    
    if trial_end:
        try:
            end_dt = datetime.fromisoformat(str(trial_end)) if isinstance(trial_end, str) else trial_end
            remaining = (end_dt - datetime.now()).days
            days_remaining = max(0, remaining)
            trial_expired = remaining < 0
        except:
            pass
    
    # Determine status: active / warning / expired
    # Warning: last session available OR <= 1 day remaining
    is_warning = False
    is_expired = False
    if is_trial and trial_start:
        if trial_expired or sessions_expired:
            is_expired = True
        elif (sessions_remaining <= 1) or (days_remaining is not None and days_remaining <= 1):
            is_warning = True
    
    return {
        "is_trial": is_trial,
        "trial_start_date": trial_start,
        "trial_end_date": trial_end,
        "trial_document_generated": athlete.get("trial_document_generated", False),
        "days_remaining": days_remaining,
        "max_days": max_days,
        "sessions_count": sessions_count,
        "max_sessions": max_sessions,
        "sessions_remaining": max(0, sessions_remaining),
        "trial_expired": is_expired,
        "trial_warning": is_warning,
        "trial_active": is_trial and not is_expired and trial_start is not None,
        "waiting_first_attendance": is_trial and trial_start is None,
    }

# ==================== END TRIAL FLOW ENDPOINTS ====================

async def check_and_activate_if_ready(athlete_id: str):
    """Check if all 3 steps for end-trial are complete and activate athlete"""
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        return False
    if not athlete.get("end_trial_requested"):
        return False
    
    has_certificate = bool(athlete.get("medical_certificate_expiry"))
    cert_verified = bool(athlete.get("medical_certificate_verified"))
    privacy_signed = bool(athlete.get("privacy_accepted"))
    
    if has_certificate and cert_verified and privacy_signed:
        await db.athletes.update_one(
            {"id": athlete_id},
            {"$set": {
                "status": "active",
                "is_trial": False,
            }}
        )
        return True
    return False


def _trial_missing_reasons(athlete: dict, team: Optional[dict]) -> list:
    """🆕 Perché un atleta in prova NON è ancora attivo: lista motivi leggibili
    ('privacy da firmare', 'certificato mancante', 'certificato da convalidare', 'certificato scaduto')."""
    reasons = []
    if not athlete.get("privacy_accepted"):
        reasons.append("privacy da firmare")
    _cert_type = cert_type_for_team(team)
    if cert_required_for_active(_cert_type):
        if not athlete.get("medical_certificate_expiry"):
            reasons.append("certificato mancante")
        elif not has_valid_verified_cert(athlete):
            exp = athlete.get("medical_certificate_expiry")
            try:
                exp_dt = exp if isinstance(exp, datetime) else datetime.fromisoformat(str(exp)[:19])
                expired = exp_dt.date() < datetime.utcnow().date()
            except Exception:
                expired = False
            reasons.append("certificato scaduto" if expired else "certificato da convalidare")
    return reasons


async def maybe_activate_minor_athlete(athlete_id: str, actor: dict | None = None) -> bool:
    """🆕 MINORENNI in prova: diventano ATTIVI appena hanno (a) privacy firmata dal
    genitore E (b) certificato medico convalidato (se richiesto dalla squadra),
    SENZA dipendere dal flag `end_trial_requested` (il genitore spesso non premeva
    "Termina prova e iscriviti" e l'atleta restava "in prova" per sempre, anche dopo
    aver pagato). Richiamabile dopo firma privacy, convalida certificato, riparazione
    prove e backfill all'avvio. Idempotente."""
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete or athlete.get("is_withdrawn"):
        return False
    if not _compute_is_minor(athlete):
        return False
    in_trial = bool(athlete.get("is_trial")) or athlete.get("status") in ("trial", "pending_trial", "pending_certificate", "pending_decision", "pending")
    if not in_trial or athlete.get("status") in (AthleteStatus.ACTIVE, AthleteStatus.BLOCKED, "rejected"):
        return False
    _team = await db.teams.find_one({"id": athlete.get("team_id")}) if athlete.get("team_id") else None
    if _trial_missing_reasons(athlete, _team):
        return False
    now = datetime.utcnow()
    await db.athletes.update_one(
        {"id": athlete_id},
        {"$set": {
            "status": "active",
            "is_trial": False,
            "trial_status": "completed",
            "trial_completed_at": now,
            "activated_at": now,
            "activated_by": (actor or {}).get("id") if actor else "auto",
        }},
    )
    logger.info(f"[TRIAL→ACTIVE] Minorenne {athlete_id} attivato automaticamente (privacy + certificato ok)")
    return True


async def maybe_activate_adult_athlete(athlete_id: str, actor: dict | None = None) -> bool:
    """🆕 ADULTI (18+): nessun periodo di prova. Un atleta maggiorenne diventa
    ATTIVO ("in forza") SOLO quando ha soddisfatto ENTRAMBI i requisiti:
      (a) privacy firmata  E  (b) certificato medico convalidato dall'admin.
    Richiamabile dopo la firma della privacy, dopo la convalida del certificato
    e all'accettazione dell'admin. Ritorna True se l'atleta è stato attivato ora.
    I MINORENNI non sono mai toccati da questa funzione (mantengono la prova)."""
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        return False
    if _compute_is_minor(athlete):
        return False
    if athlete.get("is_withdrawn"):
        return False
    if athlete.get("status") in (AthleteStatus.ACTIVE, AthleteStatus.BLOCKED, "rejected"):
        return False
    _team = await db.teams.find_one({"id": athlete.get("team_id")}) if athlete.get("team_id") else None
    _cert_type = cert_type_for_team(_team)
    cert_ok = has_valid_verified_cert(athlete) if cert_required_for_active(_cert_type) else True
    privacy_ok = bool(athlete.get("privacy_accepted"))
    if not (cert_ok and privacy_ok):
        return False
    now = datetime.utcnow()
    upd = {
        "status": AthleteStatus.ACTIVE,
        "is_trial": False,
        "trial_end_date": None,
        "activated_at": now.isoformat(),
    }
    if actor:
        upd["activated_by"] = actor.get("id")
        upd["activated_by_name"] = actor.get("full_name", actor.get("email", ""))
    await db.athletes.update_one({"id": athlete_id}, {"$set": upd})
    uid = athlete.get("user_id") or athlete.get("linked_user_id")
    if uid:
        await db.users.update_one({"id": uid}, {"$set": {"status": UserStatus.APPROVED}})
    logging.info(
        f"[AUTO-ACTIVATE-ADULT] athlete_id={athlete_id} attivato (privacy firmata + "
        f"certificato convalidato, athlete_type={athlete.get('athlete_type')})"
    )
    return True


async def maybe_activate_athlete(athlete_id: str, actor: dict | None = None) -> bool:
    """🆕 Attivazione unificata: prova a chiudere la prova e mettere ATTIVO l'atleta
    se è pronto (privacy firmata + certificato ok/non richiesto), indipendentemente
    dal fatto che sia minorenne o maggiorenne. Risolve gli atleti bloccati in
    "PROVA SCADUTA · pronto" che, trattati come maggiorenni (o con is_minor=False /
    data di nascita adulta per dati di test), non venivano mai attivati perché la
    riparazione prove gestiva solo i minorenni. Idempotente."""
    if await maybe_activate_minor_athlete(athlete_id, actor):
        return True
    return await maybe_activate_adult_athlete(athlete_id, actor)



@api_router.post("/athletes/{athlete_id}/waive-trial")
async def waive_trial_and_sign_privacy(athlete_id: str, req: Request, data: dict = Body(default={}), current_user = Depends(get_current_user)):
    """🆕 12/08/2026 — Rinuncia al periodo di prova per MINORENNE già in forza.
    Ripristina la vecchia funzione: il genitore (o admin) firma la privacy e salta
    la prova. Se il certificato medico è GIÀ convalidato → ATTIVO subito; altrimenti
    resta in ATTESA (pending_certificate): non può entrare in palestra finché l'admin
    non convalida la data del certificato medico, poi si attiva automaticamente
    (riusa il flag end_trial_requested + la logica di validazione certificato).
    """
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    if not athlete.get("is_minor"):
        raise HTTPException(status_code=400, detail="Funzione riservata agli atleti minorenni")
    # Autorizzazione: genitore dell'atleta oppure admin (stessa società)
    if current_user["role"] == UserRole.PARENT:
        if athlete.get("parent_id") != current_user["id"] and athlete.get("second_parent_id") != current_user["id"]:
            raise HTTPException(status_code=403, detail="Non sei il genitore di questo atleta")
    elif current_user["role"] not in [UserRole.ADMIN, UserRole.VIEWER, UserRole.DIRIGENTE, UserRole.COORDINATORE]:
        raise HTTPException(status_code=403, detail="Non autorizzato")
    if athlete.get("status") in (AthleteStatus.ACTIVE, AthleteStatus.BLOCKED):
        raise HTTPException(status_code=400, detail="L'atleta è già in forza")

    # IP client (per tracciabilità consenso)
    client_ip = req.client.host if req.client else "unknown"
    fwd = req.headers.get("X-Forwarded-For")
    if fwd:
        client_ip = fwd.split(",")[0].strip()
    now = datetime.now(timezone.utc)

    images_internal = bool(data.get("images_internal", False))
    images_promo = bool(data.get("images_promo", False))
    document_version = data.get("document_version", "1.0-2026")
    signer_id = current_user["id"]

    new_consents = {
        "privacy_viewed": {"value": True, "timestamp": now.isoformat(), "parent_id": signer_id, "child_id": athlete_id, "document_version": document_version, "document_name": f"privacy_minore_v{document_version}", "ip_address": client_ip},
        f"privacy_viewed__{signer_id}": {"value": True, "timestamp": now.isoformat(), "parent_id": signer_id, "child_id": athlete_id, "document_version": document_version, "ip_address": client_ip},
        f"images_internal__{signer_id}": {"value": images_internal, "timestamp": now.isoformat(), "parent_id": signer_id, "child_id": athlete_id, "document_version": document_version, "ip_address": client_ip},
        f"images_promo__{signer_id}": {"value": images_promo, "timestamp": now.isoformat(), "parent_id": signer_id, "child_id": athlete_id, "document_version": document_version, "ip_address": client_ip},
    }
    merged_consents = {**(athlete.get("consents") or {}), **new_consents}
    hist = list(athlete.get("consent_history") or [])
    hist.append({
        "action": "waive_trial_privacy",
        "timestamp": now.isoformat(),
        "user_id": signer_id,
        "user_role": current_user["role"],
        "child_id": athlete_id,
        "ip_address": client_ip,
        "document_version": document_version,
        "consents_given": {"privacy_viewed": True, "images_internal": images_internal, "images_promo": images_promo},
    })

    # GATE certificato: per essere "in forza" serve un certificato convalidato
    _team = await db.teams.find_one({"id": athlete.get("team_id")}) if athlete.get("team_id") else None
    _cert_type = cert_type_for_team(_team)
    cert_ok = has_valid_verified_cert(athlete) if cert_required_for_active(_cert_type) else True

    update = {
        "privacy_accepted": True,
        "privacy_accepted_date": now,
        "end_trial_requested": True,
        "end_trial_requested_date": now,
        "trial_waived": True,
        "trial_waived_by": signer_id,
        "trial_waived_by_name": current_user.get("full_name", current_user.get("email", "")),
        "trial_waived_at": now.isoformat(),
        "consents": merged_consents,
        "consent_history": hist,
    }
    if cert_ok:
        update["status"] = AthleteStatus.ACTIVE
        update["is_trial"] = False
        update["activated_at"] = now.isoformat()
        update["activated_by"] = signer_id
        update["activated_by_name"] = current_user.get("full_name", current_user.get("email", ""))
        result_status = "active"
        msg = "Prova saltata: l'atleta è ora in forza."
    else:
        update["status"] = "pending_certificate"
        result_status = "pending_certificate"
        msg = "Privacy firmata e prova saltata. L'atleta entrerà in forza appena l'admin convaliderà la data del certificato medico (non può entrare in palestra prima)."

    await db.athletes.update_one({"id": athlete_id}, {"$set": update})
    if athlete.get("user_id"):
        await db.users.update_one({"id": athlete["user_id"]}, {"$set": {"status": update["status"]}})

    return {"status": result_status, "message": msg, "cert_validated": cert_ok}


@api_router.post("/athletes/{athlete_id}/request-end-trial")
async def request_end_trial(athlete_id: str, current_user = Depends(get_current_user)):
    """Genitore o admin richiede la fine del periodo di prova"""
    if current_user["role"] not in [UserRole.PARENT, UserRole.ADMIN]:
        raise HTTPException(status_code=403, detail="Non autorizzato")
    
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    if current_user["role"] == UserRole.PARENT:
        if athlete.get("parent_id") != current_user["id"] and athlete.get("second_parent_id") != current_user["id"]:
            raise HTTPException(status_code=403, detail="Non sei il genitore di questo atleta")
    
    if athlete.get("status") != "trial":
        raise HTTPException(status_code=400, detail="L'atleta non e in periodo di prova")
    
    if athlete.get("end_trial_requested"):
        raise HTTPException(status_code=400, detail="Richiesta gia effettuata")
    
    # Check if athlete had a pending deletion request - if so, cancel it and log
    had_deletion_request = athlete.get("deletion_requested", False)
    
    update_fields = {
        "end_trial_requested": True,
        "end_trial_requested_date": datetime.now(timezone.utc),
    }
    
    if had_deletion_request:
        update_fields["deletion_requested"] = False
        update_fields["deletion_requested_at"] = None
        update_fields["deletion_requested_by"] = None
        update_fields["deletion_requested_by_name"] = None
    
    await db.athletes.update_one(
        {"id": athlete_id},
        {"$set": update_fields}
    )
    
    # Log deletion_request_cancelled if applicable
    if had_deletion_request:
        await db.audit_logs.insert_one({
            "id": str(uuid.uuid4()),
            "user_id": current_user["id"],
            "user_email": current_user.get("email", ""),
            "society_id": current_user.get("society_id", ""),
            "action": "deletion_request_cancelled",
            "details": {
                "athlete_id": athlete_id,
                "athlete_name": athlete.get("full_name", ""),
                "parent_name": current_user.get("full_name", ""),
                "reason": "Il genitore ha scelto di rimanere dopo aver richiesto la cancellazione"
            },
            "ip_address": "",
            "created_at": datetime.now(timezone.utc)
        })
    
    # Notifica admin
    if current_user["role"] == UserRole.PARENT:
        admin_notification = {
            "id": str(uuid.uuid4()),
            "type": "end_trial_request",
            "title": "Richiesta fine periodo di prova",
            "message": f"{current_user.get('full_name', '')} ha richiesto la fine del periodo di prova per {athlete.get('full_name', '')}. Verificare il certificato medico.",
            "data": {
                "athlete_id": athlete_id,
                "athlete_name": athlete.get("full_name", ""),
                "parent_name": current_user.get("full_name", ""),
            },
            "read": False,
            "created_at": datetime.now(timezone.utc),
            "society_id": current_user.get("society_id", ""),
        }
        await db.admin_notifications.insert_one(admin_notification)
    
    # For adult athletes (18+) in trial with no obligations, auto-delete data (GDPR)
    is_minor = athlete.get("is_minor", False)
    user_id = athlete.get("user_id")
    
    if not is_minor and user_id:
        # Check if athlete has any fiscal obligations
        fiscal_doc_types = ["compensation_receipt", "quietanza"]
        fiscal_docs = await db.signed_documents.find({
            "signer_id": user_id,
            "document_type": {"$in": fiscal_doc_types}
        }).to_list(10)
        
        if not fiscal_docs:
            # No obligations - auto-delete all data
            await db.athletes.delete_one({"id": athlete_id})
            await db.signed_documents.delete_many({"signer_id": user_id})
            await db.signed_documents.delete_many({"signer_id": athlete_id})
            await db.users.delete_one({"id": user_id})
            
            # Log the auto-deletion
            await db.audit_logs.insert_one({
                "id": str(uuid.uuid4()),
                "user_id": user_id,
                "user_email": athlete.get("email", ""),
                "action": "trial_auto_deletion",
                "details": {
                    "athlete_id": athlete_id,
                    "athlete_name": athlete.get("full_name", ""),
                    "reason": "Atleta 18+ ha rinunciato al periodo di prova - cancellazione automatica GDPR",
                },
                "created_at": datetime.now(timezone.utc)
            })
            
            # Notify admin of auto-deletion
            await db.admin_notifications.insert_one({
                "id": str(uuid.uuid4()),
                "type": "trial_auto_deleted",
                "title": "Atleta rinuncia - dati cancellati",
                "message": f"{athlete.get('full_name', '')} ha rinunciato al periodo di prova. I dati sono stati cancellati automaticamente (GDPR).",
                "data": {
                    "athlete_name": athlete.get("full_name", ""),
                    "athlete_email": athlete.get("email", ""),
                },
                "read": False,
                "created_at": datetime.now(timezone.utc),
            })
            
            return {"message": "Rinuncia registrata. I tuoi dati sono stati cancellati.", "data_deleted": True, "end_trial_requested": True}
    
    return {"message": "Richiesta di fine prova registrata", "end_trial_requested": True}


@api_router.get("/athletes/{athlete_id}/end-trial-status")
async def get_end_trial_status(athlete_id: str, current_user = Depends(get_current_user)):
    """Stato dei 3 step per concludere il periodo di prova"""
    if current_user["role"] not in [UserRole.PARENT, UserRole.ADMIN, UserRole.COACH]:
        raise HTTPException(status_code=403, detail="Non autorizzato")
    
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    has_certificate = bool(athlete.get("medical_certificate_expiry"))
    cert_verified = bool(athlete.get("medical_certificate_verified"))
    privacy_signed = bool(athlete.get("privacy_accepted"))
    all_complete = has_certificate and cert_verified and privacy_signed
    
    # GDPR signing is no longer blocked per-parent since personal consents
    # are captured at registration. Any authorized parent can sign.
    gdpr_signing_blocked = False
    gdpr_signing_blocked_message = ""
    
    return {
        "end_trial_requested": athlete.get("end_trial_requested", False),
        "end_trial_requested_date": athlete.get("end_trial_requested_date"),
        "steps": {
            "certificate_date_entered": has_certificate,
            "certificate_expiry": athlete.get("medical_certificate_expiry"),
            "admin_verified": cert_verified,
            "admin_verified_by": athlete.get("medical_certificate_verified_by_name"),
            "admin_verified_at": athlete.get("medical_certificate_verified_at"),
            "privacy_signed": privacy_signed,
            "privacy_accepted_date": athlete.get("privacy_accepted_date"),
        },
        "all_complete": all_complete,
        "athlete_status": athlete.get("status"),
        "gdpr_signing_blocked": gdpr_signing_blocked,
        "gdpr_signing_blocked_message": gdpr_signing_blocked_message,
    }



