@api_router.get("/minor/dashboard")
async def get_minor_dashboard(current_user = Depends(get_current_user)):
    """Dashboard read-only per atleta minorenne"""
    if current_user.get("role") != "minor":
        raise HTTPException(status_code=403, detail="Accesso riservato agli atleti minorenni")
    
    athlete_id = current_user["athlete_id"]
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    # Certificate expiry - check both athlete field and certificates collection
    cert_expiry = athlete.get("medical_certificate_expiry")
    cert_verified = athlete.get("medical_certificate_verified", False)
    if not cert_expiry:
        cert_doc = await db.certificates.find_one({"athlete_id": athlete_id}, {"_id": 0, "expiry_date": 1, "verified": 1})
        if cert_doc and cert_doc.get("expiry_date"):
            cert_expiry = cert_doc["expiry_date"]
            if isinstance(cert_expiry, datetime):
                cert_expiry = cert_expiry.isoformat()
            cert_verified = cert_doc.get("verified", False)
    elif isinstance(cert_expiry, datetime):
        cert_expiry = cert_expiry.isoformat()
    
    # Team info
    team = None
    team_schedule = None
    if athlete.get("team_id"):
        team = await db.teams.find_one({"id": athlete["team_id"]}, {"_id": 0})
        if team:
            team_schedule = {
                "training_sessions": team.get("training_sessions", []),
                "match_day": team.get("match_day"),
                "warmup_session": team.get("warmup_session"),
            }
    
    # Society info — 🐛 08/07/2026 fix multi-tenancy: filtriamo per society_id dell'atleta.
    # Prima faceva find_one senza filtro → prendeva la prima società del DB.
    ath_sid = athlete.get("society_id")
    society = await db.settings.find_one(
        {"type": "society", "society_id": ath_sid},
        {"_id": 0, "name": 1, "ragione_sociale": 1, "logo": 1, "sport_praticato": 1, "sport": 1, "sport_image": 1},
    ) if ath_sid else None
    if not society and ath_sid:
        society = await db.societies.find_one(
            {"id": ath_sid},
            {"_id": 0, "name": 1, "ragione_sociale": 1, "logo": 1, "sport_praticato": 1, "sport": 1},
        )
    
    # Attendance stats
    week_start = datetime.now() - timedelta(days=datetime.now().weekday())
    week_start = week_start.replace(hour=0, minute=0, second=0, microsecond=0)
    month_start = datetime.now().replace(day=1, hour=0, minute=0, second=0, microsecond=0)
    
    total_attendances = await db.attendances.count_documents({"athlete_id": athlete_id})
    weekly_attendances = await db.attendances.count_documents({
        "athlete_id": athlete_id,
        "check_in_time": {"$gte": week_start}
    })
    monthly_attendances = await db.attendances.count_documents({
        "athlete_id": athlete_id,
        "check_in_time": {"$gte": month_start}
    })
    
    # Recent attendances (last 10) - include team_id for team name lookup
    recent_attendances = await db.attendances.find(
        {"athlete_id": athlete_id},
        {"_id": 0, "id": 1, "date": 1, "check_in_time": 1, "training_slot": 1, "team_id": 1}
    ).sort("check_in_time", -1).limit(10).to_list(10)
    
    # Look up team names for attendances
    att_team_ids = list(set(a.get("team_id") for a in recent_attendances if a.get("team_id")))
    att_teams = {}
    if att_team_ids:
        teams_cursor = await db.teams.find({"id": {"$in": att_team_ids}}, {"_id": 0, "id": 1, "name": 1}).to_list(100)
        att_teams = {t["id"]: t.get("name", "") for t in teams_cursor}
    
    for att in recent_attendances:
        if isinstance(att.get("check_in_time"), datetime):
            att["check_in_time"] = att["check_in_time"].isoformat()
        att["team_name"] = att_teams.get(att.get("team_id"), "")
        # Fallback to athlete's current team if no team_id on attendance
        if not att["team_name"] and team:
            att["team_name"] = team.get("name", "")
        att.pop("team_id", None)
    
    # Upcoming matches (handle both datetime and ISO string date types in DB)
    raw_matches = await db.matches.find({
        "team_id": athlete.get("team_id")
    }, {"_id": 0, "id": 1, "date": 1, "time": 1, "opponent": 1, "venue": 1, "home_away": 1}).to_list(200)
    now_dt = datetime.now()
    upcoming_matches = []
    for m in raw_matches:
        d = m.get("date")
        if isinstance(d, str):
            try:
                d_dt = datetime.fromisoformat(d.replace("Z", "").replace("+00:00", ""))
            except Exception:
                continue
        elif isinstance(d, datetime):
            d_dt = d
        else:
            continue
        if d_dt >= now_dt:
            m["date"] = d_dt
            upcoming_matches.append(m)
    upcoming_matches.sort(key=lambda x: x["date"])
    upcoming_matches = upcoming_matches[:5]
    
    # Trial info
    trial_info = None
    if athlete.get("is_trial") or athlete.get("status") == "trial":
        trial_info = {
            "is_trial": True,
            "trial_start_date": athlete.get("trial_start_date"),
            "trial_end_date": athlete.get("trial_end_date"),
            "trial_days_remaining": None,
            "waiting_first_attendance": athlete.get("trial_start_date") is None,
        }
        if athlete.get("trial_end_date"):
            try:
                end_dt = athlete["trial_end_date"] if isinstance(athlete["trial_end_date"], datetime) else datetime.fromisoformat(str(athlete["trial_end_date"]))
                remaining = (end_dt - datetime.now()).days
                trial_info["trial_days_remaining"] = max(0, remaining)
            except:
                pass
    
    # Load 7-day commitments (with cancel/modify overrides) using shared helper
    from routes.parents import _build_commitments_payload
    athlete_display = athlete.get("nome_lite") or athlete.get("first_name", "")
    team_athletes_map = {}
    _minor_team_ids = [
        athlete.get("team_id"),
        athlete.get("team_id_2"),
        athlete.get("team_id_secondary"),
        *(athlete.get("team_ids") or []),
    ]
    for tid in _minor_team_ids:
        if tid and tid not in team_athletes_map:
            team_athletes_map[tid] = [athlete_display]
    commitments = await _build_commitments_payload(team_athletes_map)
    
    return {
        "commitments": commitments,
        "athlete": {
            "id": athlete["id"],
            "full_name": athlete.get("full_name", ""),
            "first_name": athlete.get("first_name", ""),
            "last_name": athlete.get("last_name", ""),
            "team_id": athlete.get("team_id"),
            "qr_code": athlete.get("qr_code"),
            "qr_identifier": athlete.get("qr_identifier"),
            "athlete_code": athlete.get("athlete_code"),
            "profile_photo": athlete.get("profile_photo"),
            "status": athlete.get("status"),
            "certificate_expiry": cert_expiry,
            "certificate_verified": cert_verified,
            "nome_lite": athlete.get("nome_lite"),
            "lite_color": athlete.get("lite_color"),
            "lite_emoji": athlete.get("lite_emoji"),
        },
        "team": {
            "id": team.get("id") if team else None,
            "name": team.get("name") if team else None,
        } if team else None,
        "schedule": team_schedule,
        "society": {
            "name": society.get("name") if society else None,
            "logo": await _settings_logo_b64(society) or None,
            "sport": society.get("sport_praticato") or society.get("sport") if society else None,
            "sport_image": society.get("sport_image") if society else None,
        } if society else None,
        "stats": {
            "total_attendances": total_attendances,
            "weekly_attendances": weekly_attendances,
            "monthly_attendances": monthly_attendances,
        },
        "recent_attendances": recent_attendances,
        "upcoming_matches": upcoming_matches,
        "trial_info": trial_info,
    }

@api_router.post("/athletes/{athlete_id}/set-minor-pin")
async def set_minor_pin(athlete_id: str, data: SetMinorPin, current_user = Depends(get_current_user)):
    """Genitore o atleta maggiorenne imposta il PIN per l'accesso Lite dell'atleta"""
    if current_user["role"] not in [UserRole.PARENT, UserRole.ADMIN, UserRole.ATHLETE]:
        raise HTTPException(status_code=403, detail="Non autorizzato")
    
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    # Verify ownership
    if current_user["role"] == UserRole.PARENT:
        if athlete.get("parent_id") != current_user["id"] and athlete.get("second_parent_id") != current_user["id"]:
            raise HTTPException(status_code=403, detail="Non sei il genitore di questo atleta")
    elif current_user["role"] == UserRole.ATHLETE:
        if current_user["id"] != athlete.get("user_id") and current_user.get("athlete_id") != athlete_id and current_user["id"] != athlete_id:
            raise HTTPException(status_code=403, detail="Non autorizzato")
    
    # Validate PIN (4-6 digits)
    pin = data.pin.strip()
    if not pin.isdigit() or len(pin) < 4 or len(pin) > 6:
        raise HTTPException(status_code=400, detail="Il PIN deve essere composto da 4 a 6 cifre")
    
    # Hash and store PIN
    await db.athletes.update_one(
        {"id": athlete_id},
        {"$set": {
            "minor_pin_hash": hash_password(pin),
            "minor_access_enabled": True,
        }}
    )
    
    return {"message": "PIN impostato con successo. L'accesso per l'atleta è ora attivo."}


class SetCustomAthleteCode(BaseModel):
    code: str

@api_router.post("/athletes/{athlete_id}/set-custom-code")
async def set_custom_athlete_code(athlete_id: str, data: SetCustomAthleteCode, current_user = Depends(get_current_user)):
    """Genitore o admin imposta un codice personalizzato per l'accesso Lite"""
    if current_user["role"] not in [UserRole.PARENT, UserRole.ADMIN]:
        raise HTTPException(status_code=403, detail="Non autorizzato")
    
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    if current_user["role"] == UserRole.PARENT:
        if athlete.get("parent_id") != current_user["id"] and athlete.get("second_parent_id") != current_user["id"]:
            raise HTTPException(status_code=403, detail="Non sei il genitore di questo atleta")
    
    code = data.code.strip().upper()
    if len(code) < 6:
        raise HTTPException(status_code=400, detail="Il codice deve avere almeno 6 caratteri")
    if len(code) > 20:
        raise HTTPException(status_code=400, detail="Il codice non può superare 20 caratteri")
    if not code.replace(".", "").replace("-", "").replace("_", "").isalnum():
        raise HTTPException(status_code=400, detail="Il codice può contenere solo lettere, numeri, punti, trattini")
    
    # Check uniqueness
    existing = await db.athletes.find_one({"athlete_code": code, "id": {"$ne": athlete_id}})
    if existing:
        raise HTTPException(status_code=409, detail="Questo codice è già in uso da un altro atleta")
    
    await db.athletes.update_one(
        {"id": athlete_id},
        {"$set": {"athlete_code": code}}
    )
    
    return {"message": f"Codice aggiornato: {code}", "athlete_code": code}


class SetNomeLite(BaseModel):
    nome_lite: str

@api_router.post("/athletes/{athlete_id}/set-nome-lite")
async def set_nome_lite(athlete_id: str, data: SetNomeLite, current_user = Depends(get_current_user)):
    """Genitore o atleta maggiorenne imposta il nome lite per l'accesso Lite"""
    if current_user["role"] not in [UserRole.PARENT, UserRole.ADMIN, UserRole.ATHLETE, "minor"]:
        raise HTTPException(status_code=403, detail="Non autorizzato")
    
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    # Verify ownership
    if current_user["role"] == UserRole.PARENT:
        if athlete.get("parent_id") != current_user["id"] and athlete.get("second_parent_id") != current_user["id"]:
            raise HTTPException(status_code=403, detail="Non sei il genitore di questo atleta")
    elif current_user["role"] == "minor":
        if current_user.get("athlete_id") != athlete_id:
            raise HTTPException(status_code=403, detail="Non autorizzato")
    elif current_user["role"] == UserRole.ATHLETE:
        if current_user["id"] != athlete.get("user_id") and current_user.get("athlete_id") != athlete_id and current_user["id"] != athlete_id:
            raise HTTPException(status_code=403, detail="Non autorizzato")
    
    nome = data.nome_lite.strip()
    if len(nome) < 3:
        raise HTTPException(status_code=400, detail="Il nome lite deve avere almeno 3 caratteri")
    if len(nome) > 20:
        raise HTTPException(status_code=400, detail="Il nome lite non può superare 20 caratteri")
    
    # Check uniqueness (case-insensitive)
    existing = await db.athletes.find_one({
        "nome_lite": {"$regex": f"^{nome}$", "$options": "i"},
        "id": {"$ne": athlete_id}
    })
    if existing:
        raise HTTPException(status_code=409, detail="Questo nome lite è già in uso da un altro atleta")
    
    await db.athletes.update_one(
        {"id": athlete_id},
        {"$set": {"nome_lite": nome}}
    )
    
    return {"message": f"Nome Lite impostato: {nome}", "nome_lite": nome}


class SetLitePersonalization(BaseModel):
    lite_color: Optional[str] = None
    lite_emoji: Optional[str] = None

@api_router.post("/athletes/{athlete_id}/set-lite-personalization")
async def set_lite_personalization(athlete_id: str, data: SetLitePersonalization, current_user = Depends(get_current_user)):
    """Atleta personalizza colore e emoji dalla versione Lite"""
    if current_user.get("role") != "minor":
        raise HTTPException(status_code=403, detail="Solo l'atleta può personalizzare la versione Lite")
    
    if current_user.get("athlete_id") != athlete_id:
        raise HTTPException(status_code=403, detail="Non autorizzato")
    
    update_fields = {}
    if data.lite_color is not None:
        update_fields["lite_color"] = data.lite_color
    if data.lite_emoji is not None:
        update_fields["lite_emoji"] = data.lite_emoji
    
    if update_fields:
        await db.athletes.update_one({"id": athlete_id}, {"$set": update_fields})
    
    return {"message": "Personalizzazione salvata", **update_fields}

@api_router.post("/athletes/{athlete_id}/toggle-minor-access")
async def toggle_minor_access(athlete_id: str, current_user = Depends(get_current_user)):
    """Genitore attiva/disattiva l'accesso Lite per l'atleta"""
    if current_user["role"] not in [UserRole.PARENT, UserRole.ADMIN]:
        raise HTTPException(status_code=403, detail="Solo genitori o admin possono gestire l'accesso")
    
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    if current_user["role"] == UserRole.PARENT:
        if athlete.get("parent_id") != current_user["id"] and athlete.get("second_parent_id") != current_user["id"]:
            raise HTTPException(status_code=403, detail="Non sei il genitore di questo atleta")
    
    current_status = athlete.get("minor_access_enabled", False)
    new_status = not current_status
    
    # Cannot enable without a PIN
    if new_status and not athlete.get("minor_pin_hash"):
        raise HTTPException(status_code=400, detail="Devi prima impostare un PIN per attivare l'accesso")
    
    await db.athletes.update_one(
        {"id": athlete_id},
        {"$set": {"minor_access_enabled": new_status}}
    )
    
    status_text = "attivato" if new_status else "disattivato"
    return {"message": f"Accesso minorenne {status_text}", "enabled": new_status}

@api_router.get("/athletes/{athlete_id}/minor-access-status")
async def get_minor_access_status(athlete_id: str, current_user = Depends(get_current_user)):
    """Ottieni lo stato dell'accesso minorenne"""
    if current_user["role"] not in [UserRole.PARENT, UserRole.ADMIN]:
        raise HTTPException(status_code=403, detail="Accesso non autorizzato")
    
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    if current_user["role"] == UserRole.PARENT:
        if athlete.get("parent_id") != current_user["id"] and athlete.get("second_parent_id") != current_user["id"]:
            raise HTTPException(status_code=403, detail="Non sei il genitore di questo atleta")
    
    return {
        "minor_access_enabled": athlete.get("minor_access_enabled", False),
        "has_pin": bool(athlete.get("minor_pin_hash")),
        "athlete_code": athlete.get("athlete_code"),
    }

