# ==================== AUDIT LOGS ENDPOINT ====================

@api_router.get("/audit-logs")
async def get_audit_logs(
    skip: int = 0,
    limit: int = 50,
    action: Optional[str] = None,
    current_user = Depends(get_current_user)
):
    """Get audit logs - Admin only"""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può vedere i log di audit")
    
    # Build query
    query = {"society_id": current_user.get("society_id", "")}
    if action:
        query["action"] = action
    
    # Get total count
    total = await db.audit_logs.count_documents(query)
    
    # Get logs sorted by created_at descending
    logs = await db.audit_logs.find(query).sort("created_at", -1).skip(skip).limit(limit).to_list(limit)
    
    # Clean MongoDB _id
    for log in logs:
        log.pop("_id", None)
    
    return {
        "total": total,
        "skip": skip,
        "limit": limit,
        "logs": logs
    }


# ==================== ATHLETE TIMELINE ENDPOINT ====================

@api_router.get("/athletes/{athlete_id}/timeline")
async def get_athlete_timeline(athlete_id: str, current_user = Depends(get_current_user)):
    """Get chronological timeline of athlete's key events"""
    # Access control: admin, parent of athlete, or athlete themselves
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    if current_user["role"] == UserRole.PARENT:
        if athlete.get("parent_id") != current_user["id"] and athlete.get("second_parent_id") != current_user["id"]:
            raise HTTPException(status_code=403, detail="Non autorizzato")
    elif current_user["role"] == UserRole.ATHLETE:
        if current_user.get("athlete_id") != athlete_id and current_user["id"] != athlete.get("user_id") and current_user["id"] != athlete_id:
            raise HTTPException(status_code=403, detail="Non autorizzato")
    elif current_user["role"] not in [UserRole.ADMIN, UserRole.DIRIGENTE]:
        raise HTTPException(status_code=403, detail="Non autorizzato")
    
    events = []
    
    # 1. Registration
    if athlete.get("created_at"):
        events.append({
            "type": "registration",
            "icon": "person-add",
            "color": "#007AFF",
            "title": "Registrazione",
            "description": f"{athlete.get('full_name', '')} registrato nella piattaforma",
            "date": str(athlete["created_at"]),
        })
    
    # 2. Trial Start
    if athlete.get("trial_start_date"):
        events.append({
            "type": "trial_start",
            "icon": "play-circle",
            "color": "#FF9500",
            "title": "Inizio Periodo di Prova",
            "description": "Inizia il periodo di prova presso la società",
            "date": str(athlete["trial_start_date"]),
        })
    
    # 3. Trial Document Signed
    if athlete.get("trial_document_signed_date"):
        events.append({
            "type": "trial_document_signed",
            "icon": "document-text",
            "color": "#5856D6",
            "title": "Documento Prova Firmato",
            "description": "Firmato il documento di consenso per il periodo di prova",
            "date": str(athlete["trial_document_signed_date"]),
        })
    
    # 4. Privacy/GDPR Accepted
    if athlete.get("privacy_accepted_date"):
        events.append({
            "type": "privacy_accepted",
            "icon": "shield-checkmark",
            "color": "#34C759",
            "title": "Privacy e GDPR Firmati",
            "description": "Consenso privacy e GDPR accettati e firmati",
            "date": str(athlete["privacy_accepted_date"]),
        })
    
    # 🐛 29/08/2026 — DEDUPE Cronologia: gli eventi certificato venivano generati da DUE
    # fonti (campi dell'atleta + collezione certificate_history) → doppioni ("Certificato
    # Medico Caricato" + "Certificato Inserito", e "Convalidato" + "Verificato").
    # Fetch dello storico UNA volta e usa i flag per non duplicare le sezioni 5/6.
    cert_history = await db.certificate_history.find(
        {"athlete_id": athlete_id},
        {"_id": 0, "action": 1, "changed_at": 1, "changed_by_name": 1, "new_verified": 1, "old_verified": 1, "new_expiry_date": 1}
    ).sort("changed_at", 1).to_list(20)
    _hist_has_insert = any(ch.get("action") == "insert" for ch in cert_history)
    _hist_has_verify = any(
        ch.get("action") == "update" and ch.get("old_verified") == False and ch.get("new_verified") == True
        for ch in cert_history
    )

    # 5. Medical Certificate Uploaded — solo se NON già presente nello storico certificati
    if athlete.get("medical_certificate_inserted_at") and not _hist_has_insert:
        inserted_by = athlete.get("medical_certificate_inserted_by_name", "")
        events.append({
            "type": "certificate_uploaded",
            "icon": "medkit",
            "color": "#FF2D55",
            "title": "Certificato Medico Caricato",
            "description": f"Certificato caricato da {inserted_by}" if inserted_by else "Certificato medico caricato",
            "date": str(athlete["medical_certificate_inserted_at"]),
            "detail": f"Scadenza: {format_date_it(athlete.get('medical_certificate_expiry', ''))}" if athlete.get("medical_certificate_expiry") else None,
        })
    
    # 6. Medical Certificate Verified — solo se NON già presente nello storico certificati
    if athlete.get("medical_certificate_verified_at") and not _hist_has_verify:
        verified_by = athlete.get("medical_certificate_verified_by_name", "")
        events.append({
            "type": "certificate_verified",
            "icon": "checkmark-done-circle",
            "color": "#34C759",
            "title": "Certificato Medico Convalidato",
            "description": f"Convalidato da {verified_by}" if verified_by else "Certificato convalidato dall'admin",
            "date": str(athlete["medical_certificate_verified_at"]),
        })
    
    # 7. End Trial Requested (activation process started)
    if athlete.get("end_trial_requested_date"):
        events.append({
            "type": "end_trial_requested",
            "icon": "flag",
            "color": "#AF52DE",
            "title": "Fine Prova - Processo Attivazione",
            "description": "Richiesta di rimanere nella società, avvio procedura attivazione",
            "date": str(athlete["end_trial_requested_date"]),
        })
    
    # 8. Activation (status changed to active)
    if athlete.get("status") == "active" and athlete.get("privacy_accepted_date"):
        # If active, the activation happened when privacy was accepted + certificate verified
        activation_date = athlete.get("medical_certificate_verified_at") or athlete.get("privacy_accepted_date")
        events.append({
            "type": "activated",
            "icon": "star",
            "color": "#FFD700",
            "title": "Membro Attivo",
            "description": "Atleta attivato come membro effettivo della società",
            "date": str(activation_date),
        })
    
    # 9. Team assignments
    if athlete.get("team_id"):
        team = await db.teams.find_one({"id": athlete["team_id"]}, {"_id": 0, "name": 1})
        if team:
            events.append({
                "type": "team_assigned",
                "icon": "people",
                "color": "#007AFF",
                "title": f"Assegnato a {team.get('name', 'Squadra')}",
                "description": "Inserito nella squadra come membro",
                "date": str(athlete.get("created_at", "")),
            })
    if athlete.get("team_id_2"):
        team2 = await db.teams.find_one({"id": athlete["team_id_2"]}, {"_id": 0, "name": 1})
        if team2:
            events.append({
                "type": "team_assigned_2",
                "icon": "people",
                "color": "#5AC8FA",
                "title": f"Assegnato anche a {team2.get('name', 'Squadra')}",
                "description": "Inserito in una seconda squadra",
                "date": str(athlete.get("created_at", "")),
            })
    
    # 10. Audit log events (deletion requests, cancellations, etc.)
    audit_events = await db.audit_logs.find(
        {"details.athlete_id": athlete_id},
        {"_id": 0, "action": 1, "timestamp": 1, "details": 1, "user_email": 1}
    ).sort("timestamp", 1).to_list(50)
    
    for audit in audit_events:
        ts = audit.get("timestamp")
        if isinstance(ts, datetime):
            ts = ts.isoformat()
        action = audit.get("action", "")
        
        if action == "deletion_requested":
            events.append({
                "type": "deletion_requested",
                "icon": "trash",
                "color": "#FF3B30",
                "title": "Richiesta Cancellazione Dati",
                "description": f"Richiesta inviata da {audit.get('user_email', '')}",
                "date": str(ts),
            })
        elif action == "deletion_request_cancelled":
            events.append({
                "type": "deletion_cancelled",
                "icon": "close-circle",
                "color": "#FF9500",
                "title": "Cancellazione Annullata",
                "description": f"Richiesta annullata da {audit.get('user_email', '')}",
                "date": str(ts),
            })
        elif action == "deletion_check_viewed":
            events.append({
                "type": "deletion_check_viewed",
                "icon": "eye",
                "color": "#8E8E93",
                "title": "Verifica Cancellazione Visualizzata",
                "description": f"Il genitore/atleta ha visualizzato le opzioni di cancellazione",
                "date": str(ts),
            })
        elif action == "deletion_approved":
            events.append({
                "type": "deletion_approved",
                "icon": "trash-bin",
                "color": "#FF3B30",
                "title": "Cancellazione Approvata",
                "description": "L'admin ha approvato la cancellazione dei dati",
                "date": str(ts),
            })
        elif action == "deletion_rejected":
            events.append({
                "type": "deletion_rejected",
                "icon": "hand-left",
                "color": "#AF52DE",
                "title": "Cancellazione Rifiutata",
                "description": audit.get("details", {}).get("reason", "Cancellazione rifiutata dall'admin"),
                "date": str(ts),
            })
    
    # 11. Signed documents
    signed_docs = await db.signed_documents.find(
        {"athlete_id": athlete_id},
        {"_id": 0, "document_type": 1, "signed_at": 1, "signer_name": 1, "document_title": 1}
    ).sort("signed_at", 1).to_list(50)
    
    doc_type_labels = {
        "privacy_consent": "Consenso Privacy",
        "gdpr_adult": "GDPR Adulto",
        "gdpr_minor": "GDPR Minore",
        "trial_consent": "Consenso Prova",
        "membership_agreement": "Accordo Tesseramento",
        # 🆕 documenti lavoro sportivo
        "pension_declaration": "Dichiarazione Posizione Previdenziale",
        "prior_compensation_declaration": "Dichiarazione Compensi Pregressi",
        "compensation_receipt": "Quietanza Compenso",
        "threshold_5000_communication": "Comunicazione Superamento €5.000",
        "threshold_15000_communication": "Comunicazione Superamento €15.000",
    }
    
    for doc in signed_docs:
        ts = doc.get("signed_at")
        if isinstance(ts, datetime):
            ts = ts.isoformat()
        _dt = doc.get("document_type", "")
        doc_label = doc.get("document_title") if _dt in ("pension_declaration", "prior_compensation_declaration", "compensation_receipt") and doc.get("document_title") else doc_type_labels.get(_dt, _dt or "Documento")
        _is_work_doc = _dt in ("pension_declaration", "prior_compensation_declaration", "compensation_receipt", "threshold_5000_communication", "threshold_15000_communication")
        events.append({
            "type": "document_signed",
            "icon": "shield-checkmark" if _dt == "pension_declaration" else ("cash" if _is_work_doc else "create"),
            "color": "#6D28D9" if _dt == "pension_declaration" else ("#1D6F42" if _is_work_doc else "#5856D6"),
            "title": f"Firmato: {doc_label}",
            "description": f"Firmato da {doc.get('signer_name', '')}" if doc.get("signer_name") else "Documento firmato digitalmente",
            "date": str(ts) if ts else "",
        })

    # 🆕 13. Accordo di lavoro sportivo: accettazione compenso
    if athlete.get("compensation_accepted") and athlete.get("compensation_accepted_date"):
        events.append({
            "type": "compensation_accepted",
            "icon": "checkmark-circle",
            "color": "#1D6F42",
            "title": "Accordo Compenso Accettato",
            "description": "Compenso mensile accettato dall'atleta" + (f" (€ {float(athlete.get('monthly_compensation') or 0):,.2f}/mese)".replace(",", "X").replace(".", ",").replace("X", ".") if athlete.get("monthly_compensation") else ""),
            "date": str(athlete["compensation_accepted_date"]),
        })
    
    # 12. Certificate history (rinnovi/aggiornamenti). Usa lo storico già caricato sopra.
    # Etichette uniformate a quelle "canoniche" per coerenza (niente più doppioni).
    for ch in cert_history:
        ts = ch.get("changed_at")
        if isinstance(ts, datetime):
            ts = ts.isoformat()
        if ch.get("action") == "insert":
            events.append({
                "type": "cert_history_insert",
                "icon": "medkit",
                "color": "#FF2D55",
                "title": "Certificato Medico Caricato",
                "description": f"Certificato caricato da {ch.get('changed_by_name', '')}" if ch.get('changed_by_name') else "Certificato medico caricato",
                "date": str(ts) if ts else "",
                "detail": f"Scadenza: {format_date_it(ch.get('new_expiry_date', ''))}" if ch.get("new_expiry_date") else None,
            })
        elif ch.get("action") == "update":
            if ch.get("old_verified") == False and ch.get("new_verified") == True:
                events.append({
                    "type": "cert_history_verified",
                    "icon": "checkmark-done-circle",
                    "color": "#34C759",
                    "title": "Certificato Medico Convalidato",
                    "description": f"Convalidato da {ch.get('changed_by_name', '')}" if ch.get('changed_by_name') else "Certificato convalidato dall'admin",
                    "date": str(ts) if ts else "",
                })
    
    # Sort by date
    def parse_date(d):
        try:
            if not d:
                return datetime.min.replace(tzinfo=timezone.utc)
            from dateutil.parser import parse as dateparse
            parsed = dateparse(str(d))
            if parsed.tzinfo is None:
                parsed = parsed.replace(tzinfo=timezone.utc)
            return parsed
        except:
            return datetime.min.replace(tzinfo=timezone.utc)
    
    events.sort(key=lambda e: parse_date(e.get("date", "")), reverse=True)
    
    # Remove duplicate events (same type and very close timestamps)
    seen = set()
    unique_events = []
    for e in events:
        key = f"{e['type']}_{e.get('title', '') if e['type'] == 'document_signed' else ''}_{e.get('date', '')[:16]}"
        if key not in seen:
            seen.add(key)
            unique_events.append(e)
    
    return {
        "athlete_name": athlete.get("full_name", ""),
        "athlete_status": athlete.get("status", ""),
        "events": unique_events,
    }


# ==================== CSV EXPORT ENDPOINTS ====================

@api_router.get("/admin/backup/export")
async def export_full_backup(current_user = Depends(get_current_user)):
    """Esporta un backup completo della società in formato ZIP.

    Contiene JSON sanificati di tutte le collezioni rilevanti (users senza
    password_hash, athletes, teams, matches, attendance, certificates metadata
    senza file binari, settings, audit_logs, notifications, ecc.)
    Solo admin — scoped per society_id.
    """
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può esportare il backup")

    society_id = current_user.get("society_id")
    society_filter = {"society_id": society_id} if society_id else {}

    import zipfile as _zipfile
    from json import JSONEncoder as _JSONEncoder

    class _DateTimeEncoder(_JSONEncoder):
        def default(self, obj):
            if isinstance(obj, datetime):
                return obj.isoformat()
            if hasattr(obj, "isoformat"):
                return obj.isoformat()
            return super().default(obj)

    def _clean(docs: list, drop_fields: Optional[list] = None) -> list:
        drop_fields = drop_fields or []
        cleaned = []
        for d in docs:
            if not isinstance(d, dict):
                continue
            d = {k: v for k, v in d.items() if k != "_id" and k not in drop_fields}
            cleaned.append(d)
        return cleaned

    # Raccogli tutte le collezioni rilevanti (best-effort: se una query fallisce non rompiamo)
    async def _safe_to_list(coll_name: str, filt: dict, drop: Optional[list] = None) -> list:
        try:
            docs = await db[coll_name].find(filt).to_list(10000)
            return _clean(docs, drop)
        except Exception as e:
            logging.warning(f"backup: error fetching {coll_name}: {e}")
            return []

    buf = io.BytesIO()
    with _zipfile.ZipFile(buf, "w", _zipfile.ZIP_DEFLATED) as zf:
        # README con meta
        meta = {
            "society_id": society_id,
            "exported_by": current_user.get("email"),
            "exported_by_name": current_user.get("full_name"),
            "exported_at": datetime.now(timezone.utc).isoformat(),
            "note": (
                "Backup completo della società. I file .json contengono tutti i dati strutturati. "
                "I file binari (logo, foto, certificati PDF, pagamenti) sono esclusi per ridurre la "
                "dimensione — se servono, vanno esportati separatamente dagli endpoint dedicati."
            ),
        }
        zf.writestr("README.json", json.dumps(meta, ensure_ascii=False, indent=2, cls=_DateTimeEncoder))

        # Society profile (da settings, scoped)
        settings_doc = await db.settings.find_one({"type": "society", **society_filter})
        if settings_doc:
            # Rimuovo logo base64 (binario) dal JSON — pesa troppo
            settings_clean = {k: v for k, v in settings_doc.items() if k not in ("_id", "logo", "sport_image", "stamp_signature")}
            zf.writestr("society_profile.json", json.dumps(settings_clean, ensure_ascii=False, indent=2, cls=_DateTimeEncoder))

        # Society record
        if society_id:
            soc = await db.societies.find_one({"id": society_id})
            if soc:
                soc_clean = {k: v for k, v in soc.items() if k != "_id"}
                zf.writestr("society.json", json.dumps(soc_clean, ensure_ascii=False, indent=2, cls=_DateTimeEncoder))

        # Tutte le altre collezioni
        users = await _safe_to_list("users", society_filter, drop=["password_hash", "password_reset_token"])
        zf.writestr("users.json", json.dumps(users, ensure_ascii=False, indent=2, cls=_DateTimeEncoder))

        athletes = await _safe_to_list("athletes", society_filter, drop=["photo", "medical_certificate_file"])
        zf.writestr("athletes.json", json.dumps(athletes, ensure_ascii=False, indent=2, cls=_DateTimeEncoder))

        for coll in (
            "teams", "matches", "attendance", "attendances", "medical_certificates",
            "calendars", "events", "compensations", "notifications", "seasons",
            "consents", "audit_logs", "gdpr_documents", "payments",
            "stripe_payment_attempts", "parent_athlete_links",
        ):
            docs = await _safe_to_list(coll, society_filter)
            if docs:
                zf.writestr(f"{coll}.json", json.dumps(docs, ensure_ascii=False, indent=2, cls=_DateTimeEncoder))

    buf.seek(0)
    filename = f"backup_{datetime.now().strftime('%Y%m%d_%H%M%S')}.zip"
    return StreamingResponse(
        iter([buf.getvalue()]),
        media_type="application/zip",
        headers={"Content-Disposition": f"attachment; filename={filename}", "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0", "Pragma": "no-cache", "Expires": "0"},
    )


# ============================================================
# RESTORE: OTP + restore con wipe/merge + backup automatico
# ------------------------------------------------------------
# Operazione distruttiva. Solo LR può eseguirla. Richiede:
#   1. POST /api/admin/backup/restore/request-otp  → email OTP al LR
#   2. POST /api/admin/backup/restore (multipart)  → zip + password + otp + mode
#
# Prima di qualsiasi ripristino viene creato automaticamente un pre-restore
# backup in /app/backups/ (salvaguardia contro errori umani).
# L'utente corrente (LR che sta facendo il restore) NON viene mai toccato per
# evitare lockout.
# ============================================================
import zipfile as _zipfile_mod

BACKUP_DIR = os.environ.get("BACKUP_DIR", "/tmp/backups")
os.makedirs(BACKUP_DIR, exist_ok=True)

# Collezioni gestite dal restore (stesso set del backup)
RESTORE_COLLECTIONS = (
    "users", "athletes", "teams", "matches", "attendance", "attendances",
    "medical_certificates", "calendars", "events", "compensations",
    "notifications", "seasons", "consents", "audit_logs", "gdpr_documents",
    "payments", "stripe_payment_attempts", "parent_athlete_links",
)


async def _require_legal_representative(user: dict) -> None:
    """Solo il Legale Rappresentante attivo (primary + declaration=legal_representative)
    può usare il restore. Altrimenti HTTP 403."""
    if user.get("role") != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")
    if not user.get("is_primary_admin"):
        raise HTTPException(
            status_code=403,
            detail="Solo il Responsabile Admin con scettro può avviare un ripristino. Se sei il LR, assicurati di aver firmato la dichiarazione.",
        )
    if user.get("primary_admin_declaration") != "legal_representative":
        raise HTTPException(
            status_code=403,
            detail="Solo il Legale Rappresentante firmato può eseguire il ripristino di un backup. Un Dirigente autorizzato non può.",
        )


@api_router.post("/admin/backup/restore/request-otp")
async def request_restore_otp(current_user = Depends(get_current_user)):
    """Step 1: genera OTP a 6 cifre, lo salva in users.restore_otp_* e lo invia per email al LR."""
    await _require_legal_representative(current_user)

    otp = "".join(_secrets.choice("0123456789") for _ in range(6))
    expires = datetime.now(timezone.utc) + timedelta(minutes=10)
    await db.users.update_one(
        {"id": current_user["id"]},
        {"$set": {
            "restore_otp": otp,
            "restore_otp_expires": expires,
            "restore_otp_requested_at": datetime.now(timezone.utc),
        }}
    )

    # Invia email OTP
    html = f"""
    <!DOCTYPE html><html><body style="font-family:Arial,sans-serif;line-height:1.6;color:#333;max-width:600px;margin:0 auto;padding:20px;">
    <div style="background-color:#C62828;color:white;padding:20px;text-align:center;border-radius:8px 8px 0 0;">
        <div style="font-size:40px;">⚠️</div>
        <h2 style="margin:8px 0 0 0;color:white;">Codice di conferma RESTORE</h2>
    </div>
    <div style="background-color:#fafafa;padding:28px;border:1px solid #ddd;border-radius:0 0 8px 8px;">
        <p>Ciao {current_user.get('full_name', '')},</p>
        <p>Hai richiesto di <strong>ripristinare un backup</strong> della Società. Questa è un'operazione <strong style="color:#C62828;">distruttiva e irreversibile</strong>.</p>
        <p>Inserisci il seguente codice per confermare:</p>
        <div style="background-color:#C62828;color:white;font-size:32px;font-weight:bold;padding:18px;text-align:center;border-radius:8px;margin:20px 0;letter-spacing:6px;">{otp}</div>
        <p style="font-size:13px;color:#666;">Il codice scade tra <strong>10 minuti</strong>.</p>
        <p style="font-size:12px;color:#999;margin-top:24px;">Se NON hai richiesto questa operazione, cambia subito la tua password: qualcuno potrebbe aver compromesso il tuo account.</p>
    </div>
    </body></html>
    """
    try:
        await send_transactional_email(
            to_email=current_user["email"],
            subject="⚠️ Codice di conferma RESTORE backup",
            html_content=html,
            to_name=current_user.get("full_name", ""),
        )
    except Exception as e:
        logging.warning(f"restore OTP email failed: {e}")

    return {"success": True, "message": "Codice inviato alla tua email", "expires_in_minutes": 10}


@api_router.post("/admin/backup/restore")
async def restore_backup(
    backup_zip: UploadFile = File(...),
    password: str = Form(...),
    otp: str = Form(...),
    mode: str = Form("wipe"),  # "wipe" o "merge"
    current_user = Depends(get_current_user),
):
    """Step 2: esegue il restore.

    Guardie:
      - LR (primary + declaration=legal_representative)
      - Password corrente dell'utente
      - OTP ricevuto via email (valido 10 minuti)
    Azioni:
      - Crea pre-restore backup automatico in /app/backups/
      - mode=wipe: cancella tutto (tranne l'utente corrente) e reimporta
      - mode=merge: upsert per id, i record nel ZIP sovrascrivono gli esistenti
      - L'utente corrente NON viene mai toccato (evita lockout)
      - Audit log dell'operazione
    """
    await _require_legal_representative(current_user)
    if mode not in ("wipe", "merge"):
        raise HTTPException(status_code=400, detail="mode deve essere 'wipe' o 'merge'")

    # Verifica password
    if not verify_password(password, current_user.get("password_hash", "")):
        raise HTTPException(status_code=403, detail="Password errata")

    # Verifica OTP
    fresh_user = await db.users.find_one({"id": current_user["id"]})
    stored_otp = (fresh_user or {}).get("restore_otp")
    stored_exp = (fresh_user or {}).get("restore_otp_expires")
    if not stored_otp or stored_otp != otp.strip():
        raise HTTPException(status_code=403, detail="Codice OTP non valido")
    if isinstance(stored_exp, datetime) and stored_exp < datetime.now(timezone.utc):
        raise HTTPException(status_code=403, detail="Codice OTP scaduto — richiedine uno nuovo")

    # Leggi ZIP
    try:
        raw = await backup_zip.read()
    except Exception:
        raise HTTPException(status_code=400, detail="Impossibile leggere il file ZIP")
    if not raw or len(raw) < 100:
        raise HTTPException(status_code=400, detail="File ZIP vuoto o non valido")

    try:
        zf = _zipfile_mod.ZipFile(io.BytesIO(raw))
        names = zf.namelist()
        if "users.json" not in names and "athletes.json" not in names:
            raise HTTPException(status_code=400, detail="Lo ZIP non sembra un backup valido (manca users.json o athletes.json)")
    except _zipfile_mod.BadZipFile:
        raise HTTPException(status_code=400, detail="Il file caricato non è un ZIP valido")

    society_id = current_user.get("society_id")
    society_filter = {"society_id": society_id} if society_id else {}

    # 1) PRE-RESTORE BACKUP automatico
    pre_buf = io.BytesIO()
    with _zipfile_mod.ZipFile(pre_buf, "w", _zipfile_mod.ZIP_DEFLATED) as out:
        meta = {
            "kind": "pre-restore-backup",
            "created_at": datetime.now(timezone.utc).isoformat(),
            "triggered_by_user_id": current_user["id"],
            "triggered_by_email": current_user["email"],
            "restore_mode": mode,
        }
        out.writestr("README.json", json.dumps(meta, ensure_ascii=False, indent=2, default=str))
        for coll in RESTORE_COLLECTIONS:
            try:
                docs = await db[coll].find(society_filter).to_list(10000)
                cleaned = [{k: v for k, v in d.items() if k != "_id"} for d in docs if isinstance(d, dict)]
                if cleaned:
                    out.writestr(f"{coll}.json", json.dumps(cleaned, ensure_ascii=False, indent=2, default=str))
            except Exception as e:
                logging.warning(f"pre-restore: error dumping {coll}: {e}")
    pre_buf.seek(0)
    pre_filename = f"pre-restore-{datetime.now().strftime('%Y%m%d_%H%M%S')}.zip"
    pre_path = os.path.join(BACKUP_DIR, pre_filename)
    with open(pre_path, "wb") as f:
        f.write(pre_buf.getvalue())

    # 2) Esegui il restore
    counters = {"inserted": 0, "updated": 0, "skipped_current_user": 0, "collections": []}
    current_user_id = current_user["id"]

    for coll in RESTORE_COLLECTIONS:
        fn = f"{coll}.json"
        if fn not in names:
            continue
        try:
            with zf.open(fn) as f:
                docs_in = json.loads(f.read().decode("utf-8") or "[]")
            if not isinstance(docs_in, list):
                continue
        except Exception as e:
            logging.warning(f"restore: error reading {fn}: {e}")
            continue

        coll_counter = {"name": coll, "inserted": 0, "updated": 0, "deleted": 0}

        if mode == "wipe":
            # Elimina tutto tranne l'utente corrente
            if coll == "users":
                r = await db[coll].delete_many({**society_filter, "id": {"$ne": current_user_id}})
            else:
                r = await db[coll].delete_many(society_filter)
            coll_counter["deleted"] = r.deleted_count

        # Import dei documenti
        for d in docs_in:
            if not isinstance(d, dict):
                continue
            doc_id = d.get("id")
            if not doc_id:
                continue
            # Mai toccare l'utente corrente
            if coll == "users" and doc_id == current_user_id:
                counters["skipped_current_user"] += 1
                continue
            # Assicura scoping
            if society_id and "society_id" not in d:
                d["society_id"] = society_id

            if mode == "wipe":
                d.pop("_id", None)
                try:
                    await db[coll].insert_one(d)
                    coll_counter["inserted"] += 1
                except Exception:
                    # Se c'è un id duplicato (utente corrente), fai update
                    d.pop("_id", None)
                    r = await db[coll].update_one({"id": doc_id}, {"$set": d}, upsert=True)
                    if r.matched_count:
                        coll_counter["updated"] += 1
                    else:
                        coll_counter["inserted"] += 1
            else:  # merge
                d.pop("_id", None)
                r = await db[coll].update_one({"id": doc_id}, {"$set": d}, upsert=True)
                if r.matched_count:
                    coll_counter["updated"] += 1
                else:
                    coll_counter["inserted"] += 1

        counters["inserted"] += coll_counter["inserted"]
        counters["updated"] += coll_counter["updated"]
        counters["collections"].append(coll_counter)

    # 3) Invalida OTP
    await db.users.update_one(
        {"id": current_user["id"]},
        {"$unset": {"restore_otp": "", "restore_otp_expires": "", "restore_otp_requested_at": ""}}
    )

    # 4) Audit log
    try:
        await db.audit_logs.insert_one({
            "id": str(uuid.uuid4()),
            "action": "backup_restore",
            "user_id": current_user["id"],
            "user_email": current_user["email"],
            "society_id": society_id,
            "timestamp": datetime.now(timezone.utc),
            "details": {
                "mode": mode,
                "counters": counters,
                "pre_restore_backup": pre_filename,
            },
        })
    except Exception as e:
        logging.warning(f"restore audit log failed: {e}")

    return {
        "success": True,
        "mode": mode,
        "counters": counters,
        "pre_restore_backup": pre_filename,
        "message": f"Restore {mode} completato con successo. Backup pre-restore salvato come {pre_filename}.",
    }


@api_router.get("/admin/backup/pre-restore-list")
async def list_pre_restore_backups(current_user = Depends(get_current_user)):
    """Lista dei backup pre-restore salvati lato server."""
    await _require_legal_representative(current_user)
    items = []
    try:
        for fn in sorted(os.listdir(BACKUP_DIR), reverse=True):
            if fn.startswith("pre-restore-") and fn.endswith(".zip"):
                path = os.path.join(BACKUP_DIR, fn)
                st = os.stat(path)
                items.append({
                    "filename": fn,
                    "size_bytes": st.st_size,
                    "created_at": datetime.fromtimestamp(st.st_mtime, tz=timezone.utc).isoformat(),
                })
    except Exception as e:
        logging.warning(f"list backups error: {e}")
    return {"backups": items}


@api_router.get("/admin/backup/pre-restore/{filename}")
async def download_pre_restore_backup(filename: str, current_user = Depends(get_current_user)):
    """Scarica uno dei backup pre-restore salvati lato server."""
    await _require_legal_representative(current_user)
    if not filename.startswith("pre-restore-") or ".." in filename or "/" in filename:
        raise HTTPException(status_code=400, detail="Nome file non valido")
    path = os.path.join(BACKUP_DIR, filename)
    if not os.path.isfile(path):
        raise HTTPException(status_code=404, detail="Backup non trovato")
    with open(path, "rb") as f:
        data = f.read()
    return StreamingResponse(
        iter([data]),
        media_type="application/zip",
        headers={"Content-Disposition": f"attachment; filename={filename}", "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0", "Pragma": "no-cache", "Expires": "0"},
    )


