@api_router.get("/preseason/campaigns/{campaign_id}/responses")
async def get_preseason_responses(campaign_id: str, current_user = Depends(get_current_user)):
    """Admin (o Coordinatore con permesso 'events') vede le risposte"""
    if not _has_admin_or_coord_perm(current_user, "events"):
        raise HTTPException(status_code=403, detail="Non autorizzato")
    
    responses = await db.preseason_responses.find(
        {"campaign_id": campaign_id}, {"_id": 0}
    ).sort("created_at", -1).to_list(10000)
    
    # Stats
    total = len(responses)
    interested = sum(1 for r in responses if r.get("interest_level") == "si")
    thinking = sum(1 for r in responses if r.get("interest_level") == "ci_penso")
    not_interested = sum(1 for r in responses if r.get("interest_level") == "no")
    members = sum(1 for r in responses if r.get("already_member"))
    new_athletes = sum(1 for r in responses if not r.get("already_member"))
    played_volleyball = sum(1 for r in responses if r.get("played_volleyball"))
    not_played = sum(1 for r in responses if r.get("played_volleyball") is False)
    
    return {
        "responses": responses,
        "stats": {
            "total": total,
            "interested": interested,
            "thinking": thinking,
            "not_interested": not_interested,
            "existing_members": members,
            "new_athletes": new_athletes,
            "played_volleyball": played_volleyball,
            "not_played_volleyball": not_played,
        }
    }


@api_router.get("/preseason/campaigns/{campaign_id}/export")
async def export_preseason_responses(campaign_id: str, current_user = Depends(get_current_user)):
    """Admin (o Coordinatore con permesso 'events') esporta risposte in CSV"""
    if not _has_admin_or_coord_perm(current_user, "events"):
        raise HTTPException(status_code=403, detail="Non autorizzato")
    
    # Multi-tenant: verify campaign belongs to admin's society
    _sid = current_user.get("society_id")
    _camp_q = {"id": campaign_id}
    if _sid:
        _camp_q["society_id"] = _sid
    campaign_check = await db.preseason_campaigns.find_one(_camp_q, {"_id": 0, "id": 1})
    if not campaign_check:
        raise HTTPException(status_code=404, detail="Campagna non trovata")
    
    responses = await db.preseason_responses.find(
        {"campaign_id": campaign_id}, {"_id": 0}
    ).sort("created_at", 1).to_list(10000)
    
    import csv
    import io
    
    output = io.StringIO()
    writer = csv.writer(output, delimiter=';')
    writer.writerow([
        "Nome", "Cognome", "Data Nascita", "Telefono Atleta", "Telefono Genitore",
        "Gia Iscritto", "Club Precedente", "Ha giocato a pallavolo", "Dove ha giocato",
        "Anni in societa", "Sport precedente", "Campionati Giocati", "Ruolo",
        "Interesse", "Note", "Data Risposta"
    ])
    
    interest_map = {"si": "Si", "ci_penso": "Ci sto pensando", "no": "No"}
    
    for r in responses:
        created = r.get("created_at", "")
        if isinstance(created, datetime):
            created = created.strftime("%d/%m/%Y %H:%M")
        elif isinstance(created, str):
            try:
                created = datetime.fromisoformat(created.replace("Z", "+00:00")).strftime("%d/%m/%Y %H:%M")
            except:
                pass
        
        # Build volleyball experience info
        played_vb = r.get("played_volleyball")
        if played_vb is True:
            played_vb_str = "Si"
        elif played_vb is False:
            played_vb_str = "No"
        else:
            played_vb_str = ""
        
        where_played = []
        if r.get("played_at_school"):
            where_played.append("A scuola")
        if r.get("played_in_society"):
            where_played.append("In societa")
        where_played_str = ", ".join(where_played)
        
        writer.writerow([
            r.get("first_name", ""),
            r.get("last_name", ""),
            r.get("birth_date", ""),
            r.get("phone_athlete", ""),
            r.get("phone_parent", ""),
            "Si" if r.get("already_member") else "No",
            r.get("previous_club", ""),
            played_vb_str,
            where_played_str,
            r.get("years_in_society", ""),
            r.get("previous_sport", ""),
            r.get("championships_played", ""),
            r.get("role_played", ""),
            interest_map.get(r.get("interest_level", ""), r.get("interest_level", "")),
            r.get("notes", ""),
            created,
        ])
    
    csv_content = output.getvalue()
    
    from fastapi.responses import Response
    return Response(
        content=csv_content,
        media_type="text/csv; charset=utf-8",
        headers={
            "Content-Disposition": f"attachment; filename=preiscrizioni_{campaign_id}.csv",
        }
    )


