@api_router.get("/preseason/public/{campaign_id}")
async def get_public_campaign_info(campaign_id: str):
    """Info pubblica campagna per il form esterno"""
    campaign = await db.preseason_campaigns.find_one({"id": campaign_id}, {"_id": 0})
    if not campaign:
        raise HTTPException(status_code=404, detail="Campagna non trovata")
    
    if not campaign.get("is_active"):
        raise HTTPException(status_code=410, detail="La campagna non e piu attiva")
    
    # Check dates
    now = datetime.now(timezone.utc)
    if campaign.get("close_date"):
        try:
            close_str = campaign["close_date"]
            # Parse the close date - handle both date-only and datetime formats
            if "T" in close_str or "+" in close_str or "Z" in close_str:
                close = datetime.fromisoformat(close_str.replace("Z", "+00:00"))
            else:
                # Date-only format (YYYY-MM-DD) - treat as end of day UTC
                close = datetime.fromisoformat(close_str + "T23:59:59+00:00")
            if now > close:
                raise HTTPException(status_code=410, detail="La campagna e scaduta")
        except (ValueError, TypeError):
            pass
    
    # Get society settings (logo + name)
    society = None
    if campaign.get("society_id"):
        society = await db.settings.find_one({"society_id": campaign["society_id"], "type": "society"})
    if not society:
        society = await db.settings.find_one({"type": "society"})  # noqa: multitenancy-ok — fallback dopo tentativo mirato con campaign.society_id
    
    logo = ""
    society_name = campaign.get("society_name", "")
    sport_name = ""
    if society:
        logo = society.get("logo", "")
        if not logo and society.get("logo_storage_path"):
            from storage_util import get_image_datauri
            logo = await get_image_datauri(society["logo_storage_path"]) or ""
        if not society_name:
            society_name = society.get("name", "")
        sport_name = society.get("sport_praticato", "") or society.get("sport_name", "")
    
    return {
        "id": campaign["id"],
        "title": campaign.get("title", ""),
        "season": campaign.get("season", ""),
        "description": campaign.get("description", ""),
        "event_info": campaign.get("event_info", ""),
        "cover_image": campaign.get("cover_image", ""),  # 🆕 27/02/2026
        "society_name": society_name,
        "society_logo": logo,
        "sport_name": sport_name,
        "open_date": campaign.get("open_date"),
        "close_date": campaign.get("close_date"),
    }


# 🆕 27/02/2026 — Endpoint pubblico che serve l'immagine di copertina della campagna
# come immagine binaria (per uso in og:image, che richiede URL assoluto raggiungibile
# dai crawler social senza autenticazione).
def _process_cover_for_og(cover_uri, max_dim: int = 1200, target_kb: int = 280):
    """Decodifica, ridimensiona e comprime la cover per anteprime social (WhatsApp/Facebook).
    WhatsApp NON mostra l'anteprima se l'immagine og:image è troppo pesante (~>300KB) o troppo
    grande in pixel. Qui la normalizziamo: max lato 1200px, JPEG compresso < ~280KB.
    Ritorna (jpeg_bytes, width, height) oppure (None, 0, 0)."""
    if not cover_uri or not isinstance(cover_uri, str) or not cover_uri.startswith("data:"):
        return None, 0, 0
    try:
        import base64 as _b64
        from io import BytesIO
        from PIL import Image
        _, b64 = cover_uri.split(",", 1)
        img = Image.open(BytesIO(_b64.b64decode(b64)))
        # Appiattisci trasparenza su sfondo bianco
        if img.mode in ("RGBA", "LA", "P"):
            img = img.convert("RGBA")
            bg = Image.new("RGBA", img.size, (255, 255, 255, 255))
            img = Image.alpha_composite(bg, img).convert("RGB")
        else:
            img = img.convert("RGB")
        w, h = img.size
        if max(w, h) > max_dim:
            if w >= h:
                img = img.resize((max_dim, max(1, int(h * max_dim / w))), Image.LANCZOS)
            else:
                img = img.resize((max(1, int(w * max_dim / h)), max_dim), Image.LANCZOS)
        quality = 85
        while True:
            buf = BytesIO()
            img.save(buf, format="JPEG", quality=quality, optimize=True)
            data = buf.getvalue()
            if len(data) <= target_kb * 1024 or quality <= 40:
                return data, img.width, img.height
            quality -= 10
    except Exception:
        return None, 0, 0


# ============================================================
# ⚡ 18/08/2026 — Emergent Object Storage: migrazione immagini base64 → storage.
# Riduce il peso dei documenti MongoDB (causa principale della lentezza su Atlas M0)
# ed evita di spingere base64 multi-MB attraverso l'API (causa del mancato
# salvataggio delle copertine pesanti). Fase B (trial): copertine campagne
# pre-stagione. Dual-read: se esiste cover_storage_path si serve dallo storage,
# altrimenti fallback al vecchio base64.
# ------------------------------------------------------------
import requests as _os_requests
from fastapi.concurrency import run_in_threadpool as _run_in_threadpool

_STORAGE_BASE = (os.environ.get("INTEGRATION_PROXY_URL") or "").strip() or "https://integrations.emergentagent.com"
_STORAGE_URL = _STORAGE_BASE.rstrip("/") + "/objstore/api/v1/storage"
_STORAGE_APP = "registrateam"
_storage_key = None


def _storage_init_sync():
    global _storage_key
    if _storage_key:
        return _storage_key
    resp = _os_requests.post(f"{_STORAGE_URL}/init", json={"emergent_key": os.environ.get("EMERGENT_LLM_KEY")}, timeout=30)
    resp.raise_for_status()
    _storage_key = resp.json()["storage_key"]
    return _storage_key


def _storage_put_sync(path, data, content_type):
    global _storage_key
    key = _storage_init_sync()
    resp = _os_requests.put(f"{_STORAGE_URL}/objects/{path}", headers={"X-Storage-Key": key, "Content-Type": content_type}, data=data, timeout=120)
    if resp.status_code == 503:
        _storage_key = None
        key = _storage_init_sync()
        resp = _os_requests.put(f"{_STORAGE_URL}/objects/{path}", headers={"X-Storage-Key": key, "Content-Type": content_type}, data=data, timeout=120)
    resp.raise_for_status()
    return resp.json()


def _storage_get_sync(path):
    global _storage_key
    key = _storage_init_sync()
    resp = _os_requests.get(f"{_STORAGE_URL}/objects/{path}", headers={"X-Storage-Key": key}, timeout=60)
    if resp.status_code == 503:
        _storage_key = None
        key = _storage_init_sync()
        resp = _os_requests.get(f"{_STORAGE_URL}/objects/{path}", headers={"X-Storage-Key": key}, timeout=60)
    resp.raise_for_status()
    return resp.content, resp.headers.get("Content-Type", "application/octet-stream")


async def _store_cover_from_datauri(society_id, campaign_id, data_uri):
    """Comprime la cover (JPEG ~280KB) e la carica su object storage.
    Ritorna lo storage_path oppure None (fallback: si tiene il base64)."""
    jpeg_bytes, _w, _h = _process_cover_for_og(data_uri)
    if not jpeg_bytes:
        return None
    path = f"{_STORAGE_APP}/uploads/{society_id or 'shared'}/covers/{campaign_id}.jpg"
    try:
        await _run_in_threadpool(_storage_put_sync, path, jpeg_bytes, "image/jpeg")
        return path
    except Exception as e:
        logger.warning(f"[storage] upload cover fallito per {campaign_id}: {e}")
        return None


async def _store_team_photo_from_datauri(society_id, team_id, data_uri):
    """Comprime la foto squadra (JPEG) e la carica su object storage.
    Ritorna lo storage_path oppure None (fallback: si tiene il base64)."""
    jpeg_bytes, _w, _h = _process_cover_for_og(data_uri, max_dim=1400, target_kb=450)
    if not jpeg_bytes:
        return None
    path = f"{_STORAGE_APP}/uploads/{society_id or 'shared'}/teams/{team_id}.jpg"
    try:
        await _run_in_threadpool(_storage_put_sync, path, jpeg_bytes, "image/jpeg")
        return path
    except Exception as e:
        logger.warning(f"[storage] upload team photo fallito per {team_id}: {e}")
        return None


def _team_photo_url(team_id: str) -> str:
    """URL pubblico per servire la foto squadra (object storage o fallback base64)."""
    base_url = os.environ.get("EXPO_PUBLIC_BACKEND_URL") or os.environ.get("FRONTEND_URL") or ""
    return f"{base_url}/api/teams/{team_id}/photo.jpg" if base_url else ""


class TeamPhotoUpload(BaseModel):
    image: str  # data URI oppure base64 raw


@api_router.post("/teams/{team_id}/photo")
async def upload_team_photo(team_id: str, body: TeamPhotoUpload, current_user = Depends(get_current_user)):
    """🆕 Carica la FOTO SQUADRA su Emergent Object Storage (no base64 in Mongo).
    Solo admin. Isolata per società."""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può modificare la foto squadra")
    team = await db.teams.find_one({"id": team_id}, {"_id": 0, "id": 1, "society_id": 1})
    if not team:
        raise HTTPException(status_code=404, detail="Squadra non trovata")
    if team.get("society_id") and team.get("society_id") != current_user.get("society_id"):
        raise HTTPException(status_code=403, detail="Accesso negato")

    raw = (body.image or "").strip()
    if not raw:
        raise HTTPException(status_code=400, detail="Immagine mancante")
    data_uri = raw if raw.startswith("data:") else f"data:image/jpeg;base64,{raw}"

    storage_path = await _store_team_photo_from_datauri(
        team.get("society_id") or current_user.get("society_id"), team_id, data_uri
    )
    if not storage_path:
        raise HTTPException(status_code=400, detail="Immagine non valida o non elaborabile")

    # Salva lo storage_path e rimuove il base64 pesante dal documento
    await db.teams.update_one(
        {"id": team_id},
        {"$set": {"team_photo_storage_path": storage_path}, "$unset": {"team_photo": ""}},
    )
    return {"success": True, "team_photo_url": _team_photo_url(team_id)}


@api_router.delete("/teams/{team_id}/photo")
async def delete_team_photo(team_id: str, current_user = Depends(get_current_user)):
    """Rimuove la foto squadra (storage path + eventuale base64 legacy)."""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin può modificare la foto squadra")
    team = await db.teams.find_one({"id": team_id}, {"_id": 0, "id": 1, "society_id": 1})
    if not team:
        raise HTTPException(status_code=404, detail="Squadra non trovata")
    if team.get("society_id") and team.get("society_id") != current_user.get("society_id"):
        raise HTTPException(status_code=403, detail="Accesso negato")
    await db.teams.update_one(
        {"id": team_id}, {"$unset": {"team_photo_storage_path": "", "team_photo": ""}}
    )
    return {"success": True}


@api_router.get("/teams/{team_id}/photo.jpg")
async def get_team_photo_image(team_id: str):
    """Serve la foto squadra come JPEG. Dual-read: object storage → fallback base64 legacy."""
    team = await db.teams.find_one(
        {"id": team_id}, {"_id": 0, "team_photo": 1, "team_photo_storage_path": 1, "society_id": 1}
    )
    if not team:
        raise HTTPException(status_code=404, detail="Squadra non trovata")
    from fastapi.responses import Response
    _sp = team.get("team_photo_storage_path")
    if _sp:
        try:
            _content, _ctype = await _run_in_threadpool(_storage_get_sync, _sp)
            return Response(content=_content, media_type=_ctype or "image/jpeg", headers={"Cache-Control": "public, max-age=300"})
        except Exception as e:
            logger.warning(f"[storage] get team photo fallito {team_id}: {e}")
    # Fallback base64 legacy (raw, senza prefisso data:)
    b64 = team.get("team_photo")
    if b64 and isinstance(b64, str):
        try:
            import base64 as _b64
            data_uri = b64 if b64.startswith("data:") else f"data:image/jpeg;base64,{b64}"
            # 🆕 Migrazione lazy: comprimi e sposta su object storage alla prima lettura,
            # così le vecchie foto base64 pesanti si alleggeriscono nel tempo.
            jpeg_bytes, _w, _h = _process_cover_for_og(data_uri, max_dim=1400, target_kb=450)
            if jpeg_bytes:
                path = f"{_STORAGE_APP}/uploads/{(team.get('society_id') or 'shared')}/teams/{team_id}.jpg"
                try:
                    await _run_in_threadpool(_storage_put_sync, path, jpeg_bytes, "image/jpeg")
                    await db.teams.update_one(
                        {"id": team_id},
                        {"$set": {"team_photo_storage_path": path}, "$unset": {"team_photo": ""}},
                    )
                except Exception as _e:
                    logger.warning(f"[storage] migrazione lazy foto squadra fallita {team_id}: {_e}")
                return Response(content=jpeg_bytes, media_type="image/jpeg", headers={"Cache-Control": "public, max-age=300"})
            raw = data_uri.split(",", 1)[1]
            return Response(content=_b64.b64decode(raw), media_type="image/jpeg", headers={"Cache-Control": "public, max-age=300"})
        except Exception:
            pass
    raise HTTPException(status_code=404, detail="Foto squadra non presente")





@api_router.get("/preseason/public/{campaign_id}/cover.jpg")
async def get_preseason_cover_image(campaign_id: str):
    """Serve la cover image di una campagna come JPEG compresso (ottimizzato per anteprime social).

    🐛 14/08/2026 — Aggiunta compressione/resize server-side: WhatsApp non mostrava l'anteprima
                    quando la locandina caricata era troppo grande/pesante. Ora normalizziamo a
                    max 1200px e JPEG < ~280KB così l'anteprima compare sempre.
    Fallback: se la campagna non ha cover_image → 404 (il chiamante userà il logo società).
    """
    campaign = await db.preseason_campaigns.find_one(
        {"id": campaign_id},
        {"_id": 0, "cover_image": 1, "cover_storage_path": 1}
    )
    if not campaign:
        raise HTTPException(status_code=404, detail="Cover image non presente")
    from fastapi.responses import Response
    # ⚡ 18/08/2026 — Dual-read: prima prova lo storage dedicato, poi fallback base64.
    _sp = campaign.get("cover_storage_path")
    if _sp:
        try:
            _content, _ctype = await _run_in_threadpool(_storage_get_sync, _sp)
            return Response(content=_content, media_type=_ctype or "image/jpeg", headers={"Cache-Control": "public, max-age=300"})
        except Exception as e:
            logger.warning(f"[storage] get cover fallito {campaign_id}: {e}")
            # prosegue col fallback base64 se presente
    cover = campaign.get("cover_image")
    if not cover or not cover.startswith("data:"):
        raise HTTPException(status_code=404, detail="Cover image non presente")
    jpeg_bytes, _w, _h = _process_cover_for_og(cover)
    if jpeg_bytes is None:
        raise HTTPException(status_code=404, detail="Cover image non decodificabile")
    return Response(content=jpeg_bytes, media_type="image/jpeg", headers={"Cache-Control": "public, max-age=300"})


def _convert_date_to_italian(date_str: str) -> str:
    """Convert YYYY-MM-DD to DD/MM/YYYY, or return as-is if already in Italian format"""
    if not date_str:
        return date_str
    if '-' in date_str and len(date_str) == 10:
        parts = date_str.split('-')
        if len(parts) == 3 and len(parts[0]) == 4:
            return f"{parts[2]}/{parts[1]}/{parts[0]}"
    return date_str


def _html_escape(s: str) -> str:
    """Minimal HTML escaping for meta tag content."""
    if not s:
        return ""
    return (
        str(s)
        .replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
        .replace('"', "&quot;")
        .replace("'", "&#39;")
    )


@api_router.api_route("/preseason/share/{campaign_id}", methods=["GET", "HEAD"])
async def get_preseason_share_page(campaign_id: str, request: Request):
    """Public HTML page with dynamic OpenGraph meta tags for WhatsApp/social crawlers.

    - Crawlers (WhatsApp/Facebook/Twitter/Telegram) read the OG tags and display
      the society name + logo instead of the generic "RegistraTEAM" branding.
    - Regular browsers are redirected (meta refresh + JS) to the SPA route
      `/preseason/{campaign_id}` for the real landing page.
    """
    # ⚡ 06/2026 PERF — Anteprima WhatsApp non mostrava titolo/locandina perché questo
    # endpoint era LENTISSIMO (~12s): la find_one caricava l'INTERO documento campagna
    # (incluso il cover_image base64 multi-MB) e per giunta rifaceva l'elaborazione PIL
    # (_process_cover_for_og) a OGNI richiesta. I crawler social (WhatsApp/FB) scadono
    # dopo pochi secondi → nessuna preview. Ora: aggregazione leggera che NON trasferisce
    # il base64 (solo un booleano has_cover_b64) e nessun PIL nel path della richiesta.
    _agg = await db.preseason_campaigns.aggregate([
        {"$match": {"id": campaign_id}},
        {"$project": {
            "_id": 0,
            "title": 1, "season": 1, "description": 1, "event_info": 1,
            "society_id": 1, "society_name": 1,
            "cover_storage_path": 1, "cover_width": 1, "cover_height": 1,
            "has_cover_b64": {"$gt": [{"$strLenBytes": {"$ifNull": ["$cover_image", ""]}}, 0]},
        }},
        {"$limit": 1},
    ]).to_list(1)
    campaign = _agg[0] if _agg else None

    # Fallback HTML if campaign missing / inactive — keep generic but still redirect
    if not campaign:
        frontend_base = (os.environ.get("FRONTEND_URL") or "").rstrip("/")
        redirect_url = f"{frontend_base}/preseason/{campaign_id}" if frontend_base else f"/preseason/{campaign_id}"
        return HTMLResponse(
            content=(
                f"<!DOCTYPE html><html><head><meta charset='utf-8'>"
                f"<meta http-equiv='refresh' content='0; url={redirect_url}'>"
                f"<title>Pre-iscrizione</title></head>"
                f"<body><script>window.location.replace({redirect_url!r});</script>"
                f"<p>Reindirizzamento in corso...</p></body></html>"
            ),
            status_code=200,
        )

    # Resolve society for branding.
    # ⚡ 06/2026 PERF — Proiezione leggera: NON caricare il logo base64 (fino a ~519KB),
    # basta sapere SE esiste (has_logo_b64) + il nome. Il logo è servito via /logo.png.
    _soc_proj = {
        "_id": 0, "name": 1, "society_id": 1, "logo_storage_path": 1,
        "has_logo_b64": {"$gt": [{"$strLenBytes": {"$ifNull": ["$logo", ""]}}, 0]},
    }
    society = None
    if campaign.get("society_id"):
        _s = await db.settings.aggregate([
            {"$match": {"society_id": campaign["society_id"], "type": "society"}},
            {"$project": _soc_proj}, {"$limit": 1},
        ]).to_list(1)
        society = _s[0] if _s else None
    if not society:
        _s = await db.settings.aggregate([
            {"$match": {"type": "society"}},  # noqa: multitenancy-ok — fallback branding pubblico dopo tentativo mirato
            {"$project": _soc_proj}, {"$limit": 1},
        ]).to_list(1)
        society = _s[0] if _s else None

    society_name = campaign.get("society_name") or (society.get("name") if society else "") or "Società Sportiva"
    has_logo = bool(society and (society.get("has_logo_b64") or society.get("logo_storage_path")))
    society_id = (society or {}).get("society_id") or campaign.get("society_id") or ""

    # Construct absolute logo URL (required by WhatsApp/OG crawlers).
    # The logo is served by THIS backend host, so use request host for og:image.
    scheme = request.headers.get("x-forwarded-proto") or request.url.scheme or "https"
    host = request.headers.get("x-forwarded-host") or request.headers.get("host") or request.url.netloc
    backend_url = f"{scheme}://{host}" if host else ""
    # 🆕 27/02/2026 — Priorità immagine OG:
    #   1. cover_image della campagna — se presente
    #   2. logo società (fallback)
    # 🐛 27/07/2026 — Padding 1200×1200 rimosso: peggiorava l'anteprima WhatsApp.
    #                 Ora torniamo a dichiarare le dimensioni reali dell'immagine
    #                 (il preview "piccolo" di WhatsApp mostra la locandina intera
    #                 ed è visivamente più bello del quadratone bianco).
    logo_url = ""
    og_img_width = 512
    og_img_height = 512
    og_img_type = "image/png"
    has_cover = bool(campaign.get("has_cover_b64")) or bool(campaign.get("cover_storage_path"))
    if has_cover and backend_url:
        logo_url = f"{backend_url}/api/preseason/public/{campaign_id}/cover.jpg"
        og_img_type = "image/jpeg"
        # ⚡ Niente PIL qui (era la causa della lentezza). Usa le dimensioni salvate se
        # presenti, altrimenti il formato OG standard 1200×630 (WhatsApp usa comunque
        # i byte reali dell'immagine servita da cover.jpg; le dimensioni sono solo un hint).
        og_img_width = campaign.get("cover_width") or 1200
        og_img_height = campaign.get("cover_height") or 630
    elif has_logo and backend_url:
        if society_id:
            logo_url = f"{backend_url}/api/settings/society/logo.png?society_id={society_id}"
        else:
            logo_url = f"{backend_url}/api/settings/society/logo.png"

    # Frontend (SPA) base URL — used for the human redirect target and og:url.
    # Falls back to backend host only if FRONTEND_URL is not configured.
    frontend_url = (os.environ.get("FRONTEND_URL") or "").rstrip("/") or backend_url

    # 🆕 27/02/2026 — Costruzione anteprima social più ricca:
    # - og:title = TITOLO campagna (era: nome società). Molto più efficace per il click.
    # - og:site_name = nome società (branding sotto il titolo su alcuni social).
    # - og:description = descrizione campagna + info evento (Open Day date) se presente.
    camp_title = (campaign.get("title") or "").strip()
    camp_season = (campaign.get("season") or "").strip()
    if camp_title and camp_season and camp_season not in camp_title:
        page_title = f"{camp_title} — Stagione {camp_season}"
    elif camp_title:
        page_title = camp_title
    else:
        page_title = society_name

    # Descrizione: unisci descrizione + info evento (Open Day) se disponibile.
    desc_parts = []
    if campaign.get("description"):
        desc_parts.append(campaign["description"].strip())
    ev_info = (campaign.get("event_info") or "").strip()
    if ev_info:
        desc_parts.append(f"📅 {ev_info}")
    if not desc_parts:
        desc_parts.append("Pre-iscrizione aperta. Clicca per maggiori informazioni.")
    og_description = "\n\n".join(desc_parts)
    # WhatsApp/OG raccomandano < 300 caratteri per la description
    if len(og_description) > 300:
        og_description = og_description[:297] + "..."

    redirect_url = f"{frontend_url}/preseason/{campaign_id}" if frontend_url else f"/preseason/{campaign_id}"
    share_url = redirect_url

    # Escape all dynamic strings
    e_title = _html_escape(page_title)
    e_society = _html_escape(society_name)
    e_desc = _html_escape(og_description)
    e_logo = _html_escape(logo_url)
    e_share = _html_escape(share_url)
    e_redirect = _html_escape(redirect_url)

    og_image_block = (
        f'<meta property="og:image" content="{e_logo}" />\n'
        f'    <meta property="og:image:secure_url" content="{e_logo}" />\n'
        f'    <meta property="og:image:type" content="{og_img_type}" />\n'
        f'    <meta property="og:image:width" content="{og_img_width}" />\n'
        f'    <meta property="og:image:height" content="{og_img_height}" />\n'
        f'    <meta property="og:image:alt" content="{e_title}" />\n'
        f'    <meta name="twitter:image" content="{e_logo}" />\n'
        if logo_url else ""
    )

    html = f"""<!DOCTYPE html>
<html lang="it">
<head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>{e_title}</title>
    <meta name="description" content="{e_desc}" />

    <!-- OpenGraph (WhatsApp / Facebook / Telegram) -->
    <meta property="og:type" content="website" />
    <meta property="og:site_name" content="{e_society}" />
    <meta property="og:title" content="{e_title}" />
    <meta property="og:description" content="{e_desc}" />
    <meta property="og:url" content="{e_share}" />
    <meta property="og:locale" content="it_IT" />
    {og_image_block}
    <!-- Twitter Card -->
    <meta name="twitter:card" content="summary_large_image" />
    <meta name="twitter:title" content="{e_title}" />
    <meta name="twitter:description" content="{e_desc}" />

    <!-- 🐛 27/07/2026 (parte 5) — RIMOSSO <meta http-equiv="refresh"> perché Facebook/WhatsApp/Telegram
         crawler seguivano il redirect e finivano sulla SPA Vercel senza og:image specifico dell'evento
         (mostravano og della homepage). Ora il redirect avviene SOLO via JavaScript (i crawler non
         eseguono JS quindi restano su questa pagina e leggono gli og:tag corretti).
         Rimosso anche <link rel="canonical"> verso Vercel per lo stesso motivo. -->
</head>
<body>
    <script>window.location.replace({e_redirect!r});</script>
    <noscript><p>Apri <a href="{e_redirect}">{e_society}</a></p></noscript>
</body>
</html>"""

    return HTMLResponse(content=html, status_code=200, headers={"Cache-Control": "public, max-age=120"})



@api_router.post("/preseason/public/{campaign_id}/respond")
async def submit_public_preseason_response(campaign_id: str, data: PreseasonResponse):
    """Risposta pubblica (senza autenticazione) al form pre-stagione"""
    campaign = await db.preseason_campaigns.find_one({"id": campaign_id})
    if not campaign:
        raise HTTPException(status_code=404, detail="Campagna non trovata")
    
    if not campaign.get("is_active"):
        raise HTTPException(status_code=410, detail="La campagna non e piu attiva")
    
    # Check dates
    now = datetime.now(timezone.utc)
    if campaign.get("close_date"):
        try:
            close_str = campaign["close_date"]
            # Parse the close date - handle both date-only and datetime formats
            if "T" in close_str or "+" in close_str or "Z" in close_str:
                close = datetime.fromisoformat(close_str.replace("Z", "+00:00"))
            else:
                # Date-only format (YYYY-MM-DD) - treat as end of day UTC
                close = datetime.fromisoformat(close_str + "T23:59:59+00:00")
            if now > close:
                raise HTTPException(status_code=410, detail="La campagna e scaduta")
        except (ValueError, TypeError):
            pass
    
    response_doc = {
        "id": str(uuid.uuid4()),
        "campaign_id": campaign_id,
        "society_id": campaign.get("society_id", ""),
        "first_name": data.first_name.strip().upper(),
        "last_name": data.last_name.strip().upper(),
        "birth_date": _convert_date_to_italian(data.birth_date),
        "phone_athlete": data.phone_athlete or "",
        "phone_parent": data.phone_parent or "",
        "already_member": data.already_member,
        "previous_club": data.previous_club or "",
        "played_volleyball": data.played_volleyball,
        "played_at_school": data.played_at_school,
        "played_in_society": data.played_in_society,
        "years_in_society": data.years_in_society or "",
        "previous_sport": data.previous_sport or "",
        "championships_played": data.championships_played or "",
        "role_played": data.role_played or "",
        "interest_level": data.interest_level,
        "notes": data.notes or "",
        "email_parent": (data.email_parent or "").strip().lower(),
        "is_existing_athlete": False,
        "athlete_id": None,
        "created_at": datetime.now(timezone.utc),
        "source": "public_form",
    }
    
    await db.preseason_responses.insert_one(response_doc)
    
    # Update count
    await db.preseason_campaigns.update_one(
        {"id": campaign_id},
        {"$inc": {"response_count": 1}}
    )
    
    return {"message": "Grazie! La tua risposta e stata registrata.", "id": response_doc["id"]}


