# │  🆕 26/02/2026 — Withdraw (cancellazione) + Convert-to-Trial │
# ╰──────────────────────────────────────────────────────────────╯
class PreseasonWithdrawRequest(BaseModel):
    keep_contact: bool  # True = soft delete con retention 12 mesi, False = hard delete


@api_router.post("/preseason/public/{response_id}/withdraw")
async def withdraw_preseason_response(response_id: str, data: PreseasonWithdrawRequest):
    """Pre-iscritto annulla la propria pre-iscrizione (link pubblico univoco via email).

    keep_contact=True  → status='withdrawn_keep_contact' + withdrawn_at + retention_until=+12 mesi
    keep_contact=False → hard delete del record
    """
    response = await db.preseason_responses.find_one({"id": response_id})
    if not response:
        raise HTTPException(status_code=404, detail="Pre-iscrizione non trovata o già cancellata")

    # Già cancellata? Idempotente
    if response.get("status") in ("withdrawn_keep_contact", "withdrawn_full_delete"):
        return {"message": "Pre-iscrizione già annullata", "status": response.get("status")}

    if data.keep_contact:
        now = datetime.now(timezone.utc)
        retention_until = now + timedelta(days=365)  # 12 mesi GDPR-friendly
        await db.preseason_responses.update_one(
            {"id": response_id},
            {"$set": {
                "status": "withdrawn_keep_contact",
                "withdrawn_at": now,
                "retention_until": retention_until,
                "withdrawn_keep_contact": True,
            }},
        )
        # Decrementa il contatore della campagna (la response non è più "attiva")
        try:
            await db.preseason_campaigns.update_one(
                {"id": response.get("campaign_id")},
                {"$inc": {"response_count": -1}},
            )
        except Exception:
            pass
        return {
            "message": "Pre-iscrizione annullata. Manterremo i tuoi contatti per 12 mesi per future iniziative.",
            "status": "withdrawn_keep_contact",
            "retention_until": retention_until.isoformat(),
        }
    else:
        # Hard delete: rimuoviamo completamente il record
        await db.preseason_responses.delete_one({"id": response_id})
        try:
            await db.preseason_campaigns.update_one(
                {"id": response.get("campaign_id")},
                {"$inc": {"response_count": -1}},
            )
        except Exception:
            pass
        return {"message": "Pre-iscrizione e dati eliminati. Arrivederci!", "status": "deleted"}


@api_router.post("/preseason/responses/{response_id}/convert-to-trial")
async def convert_preseason_to_trial(response_id: str, current_user = Depends(get_current_user)):
    """Admin (o pre-iscritto loggato) converte una pre-iscrizione in atleta trial.

    Usa il periodo di prova configurato in Impostazioni Società (`trial_max_days`,
    `trial_max_sessions`, default 7gg/3 sessioni). Crea un record `athletes` con
    `status='trial'` precompilato dai dati della pre-iscrizione e marca la response
    come `status='converted'` con `converted_athlete_id`.
    """
    response = await db.preseason_responses.find_one({"id": response_id})
    if not response:
        raise HTTPException(status_code=404, detail="Pre-iscrizione non trovata")

    if response.get("status") == "converted":
        raise HTTPException(status_code=400, detail="Pre-iscrizione già convertita in iscrizione")

    if response.get("status") in ("withdrawn_keep_contact", "withdrawn_full_delete"):
        raise HTTPException(status_code=400, detail="Pre-iscrizione annullata, impossibile convertire")

    # Solo admin o utente proprietario della pre-iscrizione
    is_admin = current_user.get("role") == UserRole.ADMIN
    is_owner = current_user.get("id") == response.get("user_id")
    if not is_admin and not is_owner:
        raise HTTPException(status_code=403, detail="Non autorizzato")

    society_id = response.get("society_id") or current_user.get("society_id", "")

    # Carica trial settings dalla società
    society_settings = await db.settings.find_one({"society_id": society_id, "type": "society"})
    trial_max_days = (society_settings.get("trial_max_days", 7) if society_settings else 7)
    trial_max_sessions = (society_settings.get("trial_max_sessions", 3) if society_settings else 3)

    now = datetime.now(timezone.utc)
    trial_start = now
    trial_end = trial_start + timedelta(days=trial_max_days)

    # Crea athlete trial precompilato
    athlete_id = str(uuid.uuid4())
    athlete_doc = {
        "id": athlete_id,
        "society_id": society_id,
        "first_name": (response.get("first_name") or "").strip().upper(),
        "last_name": (response.get("last_name") or "").strip().upper(),
        "full_name": f"{(response.get('last_name') or '').strip().upper()} {(response.get('first_name') or '').strip().upper()}".strip(),
        "birth_date": response.get("birth_date"),
        "phone": response.get("phone_athlete") or response.get("phone_parent") or "",
        "phone_parent": response.get("phone_parent") or "",
        "status": "trial",
        "trial_start_date": trial_start.isoformat(),
        "trial_end_date": trial_end.isoformat(),
        "trial_max_sessions": trial_max_sessions,
        "trial_max_days": trial_max_days,
        "from_preseason_response_id": response_id,
        "from_preseason_campaign_id": response.get("campaign_id"),
        "previous_club": response.get("previous_club") or "",
        "role_played": response.get("role_played") or "",
        "notes": response.get("notes") or "",
        "athlete_type": "quota",  # Default: atleta a quota (può essere cambiato in pro)
        "created_at": now,
        "created_via": "preseason_conversion",
    }
    await db.athletes.insert_one(athlete_doc)

    # Marca la response come convertita
    await db.preseason_responses.update_one(
        {"id": response_id},
        {"$set": {
            "status": "converted",
            "converted_at": now,
            "converted_athlete_id": athlete_id,
            "converted_by_user_id": current_user["id"],
        }},
    )

    logger.info(f"[PRESEASON-CONVERT] response={response_id} → athlete={athlete_id} (trial {trial_max_days}gg/{trial_max_sessions}sess)")

    return {
        "message": f"Pre-iscrizione convertita in atleta trial ({trial_max_days} giorni / {trial_max_sessions} sessioni)",
        "athlete_id": athlete_id,
        "status": "converted",
        "trial_start_date": trial_start.isoformat(),
        "trial_end_date": trial_end.isoformat(),
    }


class PreseasonInviteRequest(BaseModel):
    email: str


def _parse_birthdate_any(s: str):
    """Parse una data di nascita in formato gg/mm/aaaa o ISO (aaaa-mm-gg)."""
    if not s:
        return None
    s = str(s).strip()
    for fmt in ("%d/%m/%Y", "%Y-%m-%d"):
        try:
            return datetime.strptime(s[:10], fmt)
        except ValueError:
            continue
    try:
        return datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
    except Exception:
        return None


@api_router.post("/preseason/responses/{response_id}/invite")
async def invite_preseason_to_register(response_id: str, data: PreseasonInviteRequest, current_user = Depends(get_current_user)):
    """🆕 Converte una PRE-ISCRIZIONE in ISCRIZIONE inviando al genitore un invito
    via email per completare la registrazione completa (account, privacy GDPR, documenti).
    Riusa l'infrastruttura di invito atleti (`athlete_invitations` + /invite-register)."""
    if not _has_admin_or_coord_perm(current_user, "events"):
        raise HTTPException(status_code=403, detail="Non autorizzato")

    email = (data.email or "").strip().lower()
    if not email or "@" not in email:
        raise HTTPException(status_code=400, detail="Email del genitore non valida")

    response = await db.preseason_responses.find_one({"id": response_id})
    if not response:
        raise HTTPException(status_code=404, detail="Pre-iscrizione non trovata")
    if response.get("status") == "converted":
        raise HTTPException(status_code=400, detail="Pre-iscrizione già iscritta")
    if response.get("status") in ("withdrawn_keep_contact", "withdrawn_full_delete"):
        raise HTTPException(status_code=400, detail="Pre-iscrizione annullata, impossibile invitare")

    society_id = response.get("society_id") or current_user.get("society_id", "")
    society_settings = await db.settings.find_one({"society_id": society_id, "type": "society"})
    society_name = (society_settings.get("name") if society_settings else "") or "la Società"
    society_phone = (society_settings.get("phone") if society_settings else "") or ""
    trial_max_days = (society_settings.get("trial_max_days", 7) if society_settings else 7)
    trial_max_sessions = (society_settings.get("trial_max_sessions", 3) if society_settings else 3)

    first_name = (response.get("first_name") or "").strip()
    last_name = (response.get("last_name") or "").strip()
    athlete_display = f"{first_name} {last_name}".strip() or "l'atleta"

    # Determina se minorenne dalla data di nascita
    dob = _parse_birthdate_any(response.get("birth_date"))
    is_minor = True
    if dob:
        age = (datetime.now() - dob).days // 365
        is_minor = age < 18

    # Annulla eventuali inviti pendenti precedenti per questa email/società
    await db.athlete_invitations.update_many(
        {"email": email, "society_id": society_id, "status": "pending"},
        {"$set": {"status": "cancelled"}},
    )

    token = secrets.token_urlsafe(32)
    invitation = {
        "id": str(ObjectId()),
        "token": token,
        "email": email,
        "first_name": first_name,
        "last_name": last_name,
        "is_minor": is_minor,
        "team_id": None,
        "society_id": society_id,
        "society_name": society_name,
        "invited_by": current_user["id"],
        "invited_by_name": current_user.get("full_name", ""),
        "status": "pending",
        "from_preseason_response_id": response_id,  # 🔗 linkage per marcare convertita al completamento
        "created_at": datetime.now(timezone.utc).isoformat(),
        "expires_at": (datetime.now(timezone.utc) + timedelta(days=14)).isoformat(),
    }
    await db.athlete_invitations.insert_one(invitation)

    base_url = os.environ.get("EXPO_PUBLIC_BACKEND_URL", os.environ.get("FRONTEND_URL", ""))
    register_link = f"{base_url}/invite-register?token={token}"

    wa_line = (
        f"anticipandola con una foto via WhatsApp al numero <strong>{society_phone}</strong> della Società"
        if society_phone else
        "anticipandola con una foto via WhatsApp al responsabile della Società"
    )

    subject = f"{society_name} — Completa l'iscrizione di {athlete_display}"
    html_content = f"""
    <div style="max-width: 600px; margin: 0 auto; font-family: -apple-system, Segoe UI, Roboto, Arial, sans-serif; color: #263238;">
        <div style="background: linear-gradient(135deg, #1565C0, #1976D2); padding: 28px 24px; border-radius: 12px 12px 0 0; text-align:center;">
            <h1 style="color:#fff; margin:0; font-size:22px;">{society_name}</h1>
            <p style="color:#E3F2FD; margin:8px 0 0; font-size:14px;">Invito all'iscrizione</p>
        </div>
        <div style="background:#fff; padding:24px; border:1px solid #e0e0e0; border-top:none;">
            <p style="font-size:15px;">Gentile genitore,</p>
            <p style="font-size:15px; line-height:1.6;">
                hai effettuato la <strong>pre-iscrizione</strong> di <strong>{athlete_display}</strong>.
                Ti invitiamo ora a completare l'<strong>iscrizione</strong> a <strong>{society_name}</strong>.
            </p>

            <div style="background:#E8F5E9; border-radius:10px; padding:14px 16px; margin:18px 0;">
                <p style="margin:0; font-size:14px; line-height:1.6; color:#2E7D32;">
                    L'iscrizione dà diritto a <strong>{trial_max_sessions} allenamenti di prova</strong> in una settimana.
                    Al termine della prova l'atleta potrà decidere se <strong>restare</strong> nella società oppure
                    <strong>abbandonare</strong>, con la cancellazione di tutti i suoi dati.
                </p>
            </div>

            <div style="background:#FFF3E0; border-radius:10px; padding:14px 16px; margin:18px 0;">
                <p style="margin:0; font-size:14px; line-height:1.6; color:#E65100;">
                    ⚠️ Per riprendere l'attività sportiva, oltre all'iscrizione è necessario un
                    <strong>certificato medico sportivo valido</strong>. In attesa di consegnare la copia originale
                    alla Società (come richiesto dalla FIPAV), la si dovrà anticipare {wa_line}.
                </p>
            </div>

            <p style="font-size:14px; line-height:1.6;">
                Da quest'anno {society_name} ha adottato il gestionale <strong>RegistraTEAM</strong> per tutti gli atleti,
                dirigenti, allenatori e collaboratori: <strong>iscrizione</strong>, <strong>consenso privacy</strong> e
                <strong>pagamenti</strong> si effettuano comodamente tramite RegistraTEAM.
            </p>

            <div style="text-align:center; margin:28px 0;">
                <a href="{register_link}" style="background: linear-gradient(135deg,#1565C0,#1976D2); color:#fff; padding:16px 36px; text-decoration:none; border-radius:30px; font-weight:bold; font-size:17px; display:inline-block;">
                    Completa l'iscrizione ora
                </a>
            </div>
            <p style="text-align:center; font-size:12px; color:#888;">Se il pulsante non funziona, copia e incolla questo link:</p>
            <p style="text-align:center; font-size:11px; color:#1565C0; word-break:break-all;">{register_link}</p>
        </div>
        <div style="background:#f5f7fa; padding:14px 24px; border:1px solid #e0e0e0; border-top:none; border-radius:0 0 12px 12px;">
            <p style="color:#888; font-size:12px; margin:0;">Questo invito è valido per 14 giorni.</p>
        </div>
    </div>
    """

    email_sent = False
    email_error = None
    try:
        from email_service import send_transactional_email
        result = await send_transactional_email(
            to_email=email,
            subject=subject,
            html_content=html_content,
            to_name=athlete_display or None,
        )
        email_sent = bool(result and result.get("success"))
        if not email_sent:
            email_error = (result or {}).get("error") or "Errore sconosciuto"
            logging.error(f"[PRESEASON-INVITE] Email fallita per {email}: {email_error}")
    except Exception as e:
        email_error = str(e)
        logging.error(f"[PRESEASON-INVITE] Eccezione invio email: {e}")

    # Aggiorna lo stato della pre-iscrizione a "invitata"
    await db.preseason_responses.update_one(
        {"id": response_id},
        {"$set": {
            "status": "invited",
            "invited_at": datetime.now(timezone.utc),
            "invited_email": email,
            "invitation_token": token,
        }},
    )

    if not email_sent:
        return {
            "message": f"Invito registrato ma l'email non è stata inviata ({email_error}). Verifica l'indirizzo.",
            "email_sent": False,
            "register_link": register_link,
            "status": "invited",
        }
    return {
        "message": f"Invito all'iscrizione inviato a {email}.",
        "email_sent": True,
        "status": "invited",
    }



async def _cleanup_expired_preseason_withdrawals():
    """Scheduler: cancella i record withdrawn_keep_contact scaduti (retention 12 mesi)."""
    try:
        now = datetime.now(timezone.utc)
        result = await db.preseason_responses.delete_many({
            "status": "withdrawn_keep_contact",
            "retention_until": {"$lte": now},
        })
        if result.deleted_count > 0:
            logger.info(f"[PRESEASON-CLEANUP] Eliminati {result.deleted_count} pre-iscritti scaduti (12 mesi)")
    except Exception as e:
        logger.warning(f"[PRESEASON-CLEANUP] failed: {e}")


# Get active campaign for parent banner
@api_router.get("/preseason/active")
async def get_active_preseason_campaign(current_user = Depends(get_current_user)):
    """Ritorna la campagna attiva per mostrare il banner al genitore"""
    society_id = current_user.get("society_id", "")
    now = datetime.now(timezone.utc)
    
    campaign = await db.preseason_campaigns.find_one(
        {"society_id": society_id, "is_active": True},
        {"_id": 0}
    )
    
    if not campaign:
        return {"active": False}
    
    # Check close date
    if campaign.get("close_date"):
        try:
            close = datetime.fromisoformat(campaign["close_date"].replace("Z", "+00:00"))
            if now > close:
                return {"active": False}
        except (ValueError, TypeError):
            pass
    
    # Check if user already responded
    already_responded = await db.preseason_responses.count_documents({
        "campaign_id": campaign["id"],
        "user_id": current_user["id"],
    })
    
    return {
        "active": True,
        "campaign": campaign,
        "already_responded": already_responded > 0,
    }


@api_router.post("/preseason/campaigns/{campaign_id}/send-notifications")
async def send_preseason_notifications(campaign_id: str, current_user = Depends(get_current_user)):
    """Admin (o Coordinatore con permesso 'events') invia email + notifiche in-app ai genitori che non hanno ancora risposto"""
    if not _has_admin_or_coord_perm(current_user, "events"):
        raise HTTPException(status_code=403, detail="Non autorizzato")
    
    campaign = await db.preseason_campaigns.find_one({"id": campaign_id})
    if not campaign:
        raise HTTPException(status_code=404, detail="Campagna non trovata")
    
    society_id = campaign.get("society_id", "")
    
    # Get society info for the email
    society = await db.settings.find_one({"society_id": society_id, "type": "society"})
    society_name = society.get("name", "La tua societa sportiva") if society else "La tua societa sportiva"
    
    # Find all parents in this society
    all_parents = await db.users.find(
        {"society_id": society_id, "role": "parent"},
        {"_id": 0, "id": 1, "email": 1, "full_name": 1}
    ).to_list(10000)
    
    # Find parents who already responded (via user_id in responses)
    responded_user_ids = set()
    responses = await db.preseason_responses.find(
        {"campaign_id": campaign_id, "user_id": {"$exists": True, "$ne": None}},
        {"_id": 0, "user_id": 1}
    ).to_list(10000)
    for r in responses:
        if r.get("user_id"):
            responded_user_ids.add(r["user_id"])
    
    # Filter: only parents who haven't responded
    parents_to_notify = [p for p in all_parents if p["id"] not in responded_user_ids]
    
    if not parents_to_notify:
        return {
            "message": "Tutti i genitori hanno gia risposto!",
            "notified_count": 0,
            "already_responded_count": len(responded_user_ids),
            "total_parents": len(all_parents),
        }
    
    # Build public form link
    base_url = str(os.environ.get("FRONTEND_URL", "")).rstrip("/")
    if not base_url:
        # Try to build from request context
        base_url = ""
    form_link = f"{base_url}/preseason/{campaign_id}" if base_url else f"/preseason/{campaign_id}"
    
    # Build email HTML
    email_html = f"""
    <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;">
        <div style="text-align: center; margin-bottom: 24px;">
            <h1 style="color: #0D47A1; font-size: 22px; margin: 0;">{society_name}</h1>
            <p style="color: #666; font-size: 14px; margin-top: 8px;">{campaign.get('title', 'Pre-iscrizione')}</p>
        </div>
        
        <div style="background-color: #E3F2FD; border-radius: 12px; padding: 20px; margin-bottom: 20px;">
            <h2 style="color: #1565C0; font-size: 18px; margin: 0 0 12px 0;">Stai pensando alla prossima stagione?</h2>
            <p style="color: #333; font-size: 14px; line-height: 22px; margin: 0;">
                Stiamo programmando la stagione <strong>{campaign.get('season', '')}</strong> e ci piacerebbe sapere se sei interessato/a a continuare con noi!
            </p>
        </div>
        
        {f'<p style="color: #555; font-size: 14px; line-height: 22px;">{campaign.get("description", "")}</p>' if campaign.get("description") else ""}
        
        <div style="text-align: center; margin: 24px 0;">
            <a href="{form_link}" style="display: inline-block; background-color: #0D47A1; color: white; text-decoration: none; padding: 14px 32px; border-radius: 8px; font-size: 16px; font-weight: bold;">
                Compila il modulo
            </a>
        </div>
        
        <div style="background-color: #E8F5E9; border-radius: 8px; padding: 12px; text-align: center; margin-bottom: 20px;">
            <p style="color: #2E7D32; font-size: 12px; margin: 0; font-weight: 600;">
                La compilazione e non vincolante — serve solo per la programmazione
            </p>
        </div>
        
        {f'<p style="color: #999; font-size: 12px; text-align: center;">Scadenza: {campaign.get("close_date", "")[:10] if campaign.get("close_date") else "non definita"}</p>' if campaign.get("close_date") else ""}
        
        <hr style="border: none; border-top: 1px solid #eee; margin: 20px 0;">
        <p style="color: #aaa; font-size: 11px; text-align: center;">
            Questa email e stata inviata da {society_name} tramite RegistraTEAM.
        </p>
    </div>
    """
    
    # Send emails and in-app notifications
    from email_service import send_transactional_email
    email_sent = 0
    email_failed = 0
    
    for parent in parents_to_notify:
        # In-app notification
        await db.admin_notifications.insert_one({
            "id": str(uuid.uuid4()),
            "society_id": society_id,
            "admin_id": parent["id"],
            "type": "preseason_survey",
            "title": f"Pre-iscrizione {campaign.get('season', '')}",
            "message": f"{society_name} ti chiede: torni la prossima stagione? Compila il modulo di interesse.",
            "read": False,
            "created_at": datetime.now(timezone.utc).isoformat(),
            "entity_type": "preseason_campaign",
            "entity_id": campaign_id,
            "action_url": f"/preseason/{campaign_id}",
        })
        
        # Email
        if parent.get("email"):
            try:
                await send_transactional_email(
                    to_email=parent["email"],
                    subject=f"{society_name} - {campaign.get('title', 'Pre-iscrizione prossima stagione')}",
                    html_content=email_html,
                )
                email_sent += 1
            except Exception as e:
                logger.error(f"Email failed for {parent['email']}: {e}")
                email_failed += 1
    
    # Log the notification send
    await db.preseason_campaigns.update_one(
        {"id": campaign_id},
        {"$set": {
            "last_notification_sent": datetime.now(timezone.utc),
            "notification_count": (campaign.get("notification_count", 0) or 0) + 1,
        }}
    )
    
    return {
        "message": f"Notifiche inviate a {len(parents_to_notify)} genitori",
        "notified_count": len(parents_to_notify),
        "email_sent": email_sent,
        "email_failed": email_failed,
        "already_responded_count": len(responded_user_ids),
        "total_parents": len(all_parents),
    }


