# ==================== CONSENT MANAGEMENT ENDPOINTS ====================

class ConsentUpdateRequest(BaseModel):
    images_internal: Optional[bool] = None
    images_promo: Optional[bool] = None

@api_router.get("/users/me/consents")
async def get_my_consents(current_user = Depends(get_current_user)):
    """Get current user's consent status."""
    user = await db.users.find_one({"id": current_user["id"]}, {"_id": 0, "consents": 1, "consent_history": 1})
    return {
        "consents": user.get("consents") if user else None,
        "consent_history": user.get("consent_history", []) if user else [],
    }

@api_router.patch("/users/me/consents")
async def update_my_consents(
    data: ConsentUpdateRequest,
    req: Request,
    current_user = Depends(get_current_user)
):
    """Update optional consents (images_internal, images_promo) for the current user."""
    client_ip = req.client.host if req.client else "unknown"
    forwarded_for = req.headers.get("X-Forwarded-For")
    if forwarded_for:
        client_ip = forwarded_for.split(",")[0].strip()
    
    now = datetime.now(timezone.utc)
    user = await db.users.find_one({"id": current_user["id"]})
    if not user:
        raise HTTPException(status_code=404, detail="Utente non trovato")
    
    existing_consents = user.get("consents") or {}
    existing_history = user.get("consent_history") or []
    
    update_fields = {}
    new_history_entries = []
    
    if data.images_internal is not None:
        old_val = existing_consents.get("images_internal", {}).get("value") if existing_consents.get("images_internal") else None
        if old_val != data.images_internal:
            existing_consents["images_internal"] = {
                "value": data.images_internal,
                "timestamp": now.isoformat(),
                "user_id": current_user["id"],
                "document_version": "1.0",
                "ip_address": client_ip,
            }
            new_history_entries.append({
                "type": "images_internal",
                "old_value": old_val,
                "new_value": data.images_internal,
                "timestamp": now.isoformat(),
                "user_id": current_user["id"],
                "ip_address": client_ip,
            })
    
    if data.images_promo is not None:
        old_val = existing_consents.get("images_promo", {}).get("value") if existing_consents.get("images_promo") else None
        if old_val != data.images_promo:
            existing_consents["images_promo"] = {
                "value": data.images_promo,
                "timestamp": now.isoformat(),
                "user_id": current_user["id"],
                "document_version": "1.0",
                "ip_address": client_ip,
            }
            new_history_entries.append({
                "type": "images_promo",
                "old_value": old_val,
                "new_value": data.images_promo,
                "timestamp": now.isoformat(),
                "user_id": current_user["id"],
                "ip_address": client_ip,
            })
    
    if new_history_entries:
        updated_history = existing_history + new_history_entries
        await db.users.update_one(
            {"id": current_user["id"]},
            {"$set": {"consents": existing_consents, "consent_history": updated_history}}
        )
    
    return {"success": True, "consents": existing_consents}

@api_router.get("/athletes/{athlete_id}/consents")
async def get_athlete_consents(athlete_id: str, current_user = Depends(get_current_user)):
    """Get an athlete's consent status with per-parent breakdown and final state."""
    athlete = await db.athletes.find_one({"id": athlete_id}, {"_id": 0, "consents": 1, "consent_history": 1, "parent_id": 1, "second_parent_id": 1})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    is_parent = current_user["id"] in [athlete.get("parent_id"), athlete.get("second_parent_id")]
    is_self = current_user["role"] == "athlete" and current_user.get("athlete_id") == athlete_id
    if current_user["role"] not in ["admin"] and not is_parent and not is_self:
        raise HTTPException(status_code=403, detail="Non autorizzato")
    
    consents = athlete.get("consents") or {}
    
    # Calcola lo stato finale per i consensi immagini (regola: un NO = NEGATO)
    parent_ids = [pid for pid in [athlete.get("parent_id"), athlete.get("second_parent_id")] if pid]
    
    def _extract_consent_value(entry):
        """Extract bool value from consent entry (handles both bool and dict formats)."""
        if isinstance(entry, bool):
            return entry
        if isinstance(entry, dict):
            return entry.get("value", False)
        return False

    final_consents = {}
    for consent_type in ["images_internal", "images_promo"]:
        parent_states = {}
        for pid in parent_ids:
            key = f"{consent_type}__{pid}"
            if key in consents:
                parent_states[pid] = _extract_consent_value(consents[key])
            elif pid == athlete.get("parent_id") and consent_type in consents:
                # Retrocompatibilità: consenso senza parent_id specifico
                parent_states[pid] = _extract_consent_value(consents[consent_type])
        
        # Regola: se almeno un genitore nega → NEGATO. Solo se TUTTI accettano → ACCETTATO
        if parent_states:
            final_consents[consent_type] = {
                "final_value": all(parent_states.values()),
                "per_parent": parent_states,
                "denied_by": [pid for pid, v in parent_states.items() if not v] or None,
            }
        else:
            raw = consents.get(consent_type)
            final_consents[consent_type] = {
                "final_value": _extract_consent_value(raw) if raw is not None else False,
                "per_parent": {},
                "denied_by": None,
            }
    
    return {
        "consents": consents,
        "final_consents": final_consents,
        "consent_history": athlete.get("consent_history", []),
    }

@api_router.patch("/athletes/{athlete_id}/consents")
async def update_athlete_consents(
    athlete_id: str,
    data: ConsentUpdateRequest,
    req: Request,
    current_user = Depends(get_current_user)
):
    """Update optional consents for an athlete. Saves per parent_id + child_id."""
    client_ip = req.client.host if req.client else "unknown"
    forwarded_for = req.headers.get("X-Forwarded-For")
    if forwarded_for:
        client_ip = forwarded_for.split(",")[0].strip()
    
    athlete = await db.athletes.find_one({"id": athlete_id})
    if not athlete:
        raise HTTPException(status_code=404, detail="Atleta non trovato")
    
    is_parent = current_user["id"] in [athlete.get("parent_id"), athlete.get("second_parent_id")]
    is_self = current_user["role"] == "athlete" and current_user.get("athlete_id") == athlete_id
    if current_user["role"] not in ["admin"] and not is_parent and not is_self:
        raise HTTPException(status_code=403, detail="Non autorizzato")
    
    # Block image consent changes if privacy has not been signed for this athlete.
    # 🐛 08/08/2026 — Per i MINORI 'athlete.privacy_accepted' resta False (la privacy è
    # per-genitore): consideriamo firmata anche se il genitore che agisce (o uno dei
    # genitori) ha dato la 'presa visione' (consents.privacy_viewed[__parentId].value == True).
    _privacy_ok = bool(athlete.get("privacy_accepted"))
    if not _privacy_ok:
        _cons_pv = athlete.get("consents") or {}
        _pid = current_user["id"]
        for _pv_key in ("privacy_viewed", f"privacy_viewed__{_pid}",
                        f"privacy_viewed__{athlete.get('parent_id')}",
                        f"privacy_viewed__{athlete.get('second_parent_id')}"):
            _pv = _cons_pv.get(_pv_key)
            if _pv is True or (isinstance(_pv, dict) and _pv.get("value") is True):
                _privacy_ok = True
                break
    if not _privacy_ok and current_user["role"] != "admin":
        raise HTTPException(status_code=403, detail="Per modificare i consensi è necessario prima firmare la privacy.")
    
    now = datetime.now(timezone.utc)
    existing_consents = athlete.get("consents") or {}
    existing_history = athlete.get("consent_history") or []
    parent_id = current_user["id"]
    
    new_history_entries = []
    
    # For adult athletes updating their own consents, use direct key (not per-parent key)
    is_self_athlete = current_user["role"] == "athlete" and current_user.get("athlete_id") == athlete_id
    
    for consent_type_name, consent_value in [("images_internal", data.images_internal), ("images_promo", data.images_promo)]:
        if consent_value is not None:
            if is_self_athlete:
                # Adult athlete: use direct key
                consent_key = consent_type_name
            else:
                # Parent: use per-parent key
                consent_key = f"{consent_type_name}__{parent_id}"
            
            old_entry = existing_consents.get(consent_key) or existing_consents.get(consent_type_name) or {}
            if isinstance(old_entry, bool):
                old_val = old_entry
            else:
                old_val = old_entry.get("value") if isinstance(old_entry, dict) else None
            
            if old_val != consent_value:
                entry = {
                    "value": consent_value,
                    "timestamp": now.isoformat(),
                    "user_id": parent_id,
                    "document_version": "1.0",
                    "ip_address": client_ip,
                }
                if not is_self_athlete:
                    entry["parent_id"] = parent_id
                    entry["child_id"] = athlete_id
                if old_val is True and consent_value is False:
                    entry["revoked_at"] = now.isoformat()
                
                existing_consents[consent_key] = entry
                
                new_history_entries.append({
                    "type": consent_type_name,
                    "action": "revoked" if (old_val is True and consent_value is False) else "granted" if consent_value else "updated",
                    "old_value": old_val,
                    "new_value": consent_value,
                    "timestamp": now.isoformat(),
                    "parent_id": parent_id,
                    "child_id": athlete_id,
                    "ip_address": client_ip,
                })
    
    if new_history_entries:
        updated_history = existing_history + new_history_entries
        await db.athletes.update_one(
            {"id": athlete_id},
            {"$set": {"consents": existing_consents, "consent_history": updated_history}}
        )
    
    # Ricalcola final_consents IMMEDIATAMENTE dopo l'aggiornamento
    athlete_updated = await db.athletes.find_one({"id": athlete_id}, {"_id": 0, "parent_id": 1, "second_parent_id": 1, "consents": 1})
    updated_consents = athlete_updated.get("consents") or {}
    parent_ids = [pid for pid in [athlete_updated.get("parent_id"), athlete_updated.get("second_parent_id")] if pid]
    
    final_consents = {}
    for ct in ["images_internal", "images_promo"]:
        parent_states = {}
        for pid in parent_ids:
            key = f"{ct}__{pid}"
            if key in updated_consents:
                parent_states[pid] = updated_consents[key].get("value", False)
            elif pid == athlete_updated.get("parent_id") and ct in updated_consents:
                parent_states[pid] = updated_consents[ct].get("value", False)
        
        if parent_states:
            final_consents[ct] = {
                "final_value": all(parent_states.values()),
                "per_parent": parent_states,
                "denied_by": [pid for pid, v in parent_states.items() if not v] or None,
            }
        else:
            final_consents[ct] = {
                "final_value": updated_consents.get(ct, {}).get("value", False) if updated_consents.get(ct) else False,
                "per_parent": {},
                "denied_by": None,
            }
    
    return {"success": True, "consents": updated_consents, "final_consents": final_consents}

@api_router.get("/admin/consent-history/{entity_type}/{entity_id}")
async def get_consent_history_admin(
    entity_type: str,
    entity_id: str,
    current_user = Depends(get_current_user)
):
    """Admin-only: get full consent audit trail for a user or athlete."""
    if current_user["role"] not in ["admin"]:
        raise HTTPException(status_code=403, detail="Solo admin")
    
    if entity_type == "user":
        entity = await db.users.find_one({"id": entity_id}, {"_id": 0, "consents": 1, "consent_history": 1, "full_name": 1, "email": 1, "role": 1, "linked_athlete_id": 1})
    elif entity_type == "athlete":
        entity = await db.athletes.find_one({"id": entity_id}, {"_id": 0, "consents": 1, "consent_history": 1, "full_name": 1, "first_name": 1, "last_name": 1})
    else:
        raise HTTPException(status_code=400, detail="entity_type deve essere 'user' o 'athlete'")
    
    if not entity:
        raise HTTPException(status_code=404, detail="Entità non trovata")
    
    consents = entity.get("consents")
    consent_history = entity.get("consent_history", [])

    # 🐛 Fix doppio incarico: uno staff promosso da atleta firma privacy/consensi
    # immagine sul record ATLETA collegato. Per la vista di dettaglio riempiamo le
    # chiavi mancanti (privacy_viewed / images_*) dal record atleta collegato.
    if entity_type == "user" and entity.get("linked_athlete_id"):
        la = await db.athletes.find_one(
            {"id": entity["linked_athlete_id"]},
            {"_id": 0, "consents": 1, "consent_history": 1, "privacy_accepted": 1},
        )
        if la:
            merged = dict(consents or {})
            la_cons = la.get("consents") or {}
            for k in ("privacy_viewed", "images_internal", "images_promo"):
                cur = merged.get(k)
                cur_val = cur.get("value") if isinstance(cur, dict) else cur
                if cur_val is None and la_cons.get(k) is not None:
                    merged[k] = la_cons[k]
            # privacy_accepted dell'atleta implica presa visione informativa
            if merged.get("privacy_viewed") is None and la.get("privacy_accepted"):
                merged["privacy_viewed"] = {"value": True}
            consents = merged
            if not consent_history:
                consent_history = la.get("consent_history", [])

    return {
        "entity_type": entity_type,
        "entity_id": entity_id,
        "full_name": entity.get("full_name") or f'{entity.get("last_name", "")} {entity.get("first_name", "")}',
        "email": entity.get("email"),
        "role": entity.get("role"),
        "consents": consents,
        "consent_history": consent_history,
    }

@api_router.get("/admin/all-consents")
async def get_all_consents_admin(current_user = Depends(get_current_user)):
    """Admin-only: Get consent overview for all users and athletes."""
    if current_user["role"] not in ["admin"]:
        raise HTTPException(status_code=403, detail="Solo admin")
    
    result = []
    
    _sid = current_user.get("society_id")
    _u_q = {"role": {"$ne": "admin"}}
    _a_q = {}
    if _sid:
        _u_q["society_id"] = _sid
        _a_q["society_id"] = _sid

    # Get users with consents
    users = await db.users.find(
        _u_q,
        {"_id": 0, "id": 1, "full_name": 1, "email": 1, "role": 1, "consents": 1, "consent_history": 1}
    ).to_list(500)
    
    for u in users:
        consents = u.get("consents") or {}
        history = u.get("consent_history") or []
        if consents or history:
            result.append({
                "entity_type": "user",
                "entity_id": u["id"],
                "full_name": u.get("full_name", ""),
                "email": u.get("email", ""),
                "role": u.get("role", ""),
                "consents": consents,
                "history_count": len(history),
                "last_change": history[-1]["timestamp"] if history else None,
            })
    
    # Get athletes with consents (society-scoped)
    athletes = await db.athletes.find(
        _a_q,
        {"_id": 0, "id": 1, "full_name": 1, "first_name": 1, "last_name": 1, "consents": 1, "consent_history": 1, "team_id": 1}
    ).to_list(500)
    
    # Pre-load team names for athletes
    _team_ids = list({a.get("team_id") for a in athletes if a.get("team_id")})
    _teams = await db.teams.find({"id": {"$in": _team_ids}}, {"_id": 0, "id": 1, "name": 1}).to_list(500) if _team_ids else []
    _team_names = {t["id"]: t.get("name", "—") for t in _teams}
    
    for a in athletes:
        consents = a.get("consents") or {}
        history = a.get("consent_history") or []
        if consents or history:
            result.append({
                "entity_type": "athlete",
                "entity_id": a["id"],
                "full_name": a.get("full_name") or f'{a.get("last_name", "")} {a.get("first_name", "")}',
                "role": "atleta",
                "team_id": a.get("team_id"),
                "team_name": _team_names.get(a.get("team_id")) if a.get("team_id") else None,
                "consents": consents,
                "history_count": len(history),
                "last_change": history[-1]["timestamp"] if history else None,
            })
    
    return result


