@api_router.put("/admin/whatsapp/settings")
async def update_whatsapp_settings(payload: dict, current_user=Depends(get_current_user)):
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")
    sid = current_user.get("society_id")
    settings_in = (payload or {}).get("settings") or {}
    # Validate keys
    cleaned = {}
    for key in DEFAULT_TEMPLATES.keys():
        item = settings_in.get(key) or {}
        td = item.get("threshold_days")
        try:
            td = int(td)
            if td < 0 or td > 365:
                raise ValueError
        except Exception:
            td = DEFAULT_TEMPLATES[key]["threshold_days"]
        cleaned[key] = {
            "label": (item.get("label") or DEFAULT_TEMPLATES[key]["label"])[:120],
            "threshold_days": td,
            "template": (item.get("template") or DEFAULT_TEMPLATES[key]["template"])[:1000],
        }
    await db.settings.update_one(
        {"type": "whatsapp_reminders_config", "society_id": sid},
        {"$set": {"settings": cleaned, "updated_at": datetime.utcnow(), "updated_by": current_user["id"]}},
        upsert=True,
    )
    return {"ok": True, "settings": cleaned}


@api_router.get("/admin/whatsapp/pending-reminders")
async def get_pending_reminders(current_user=Depends(get_current_user)):
    """Return list of cases that require a WhatsApp reminder.
    Admin sees all of their society. Coach sees only athletes/cases of their teams.
    """
    role = current_user["role"]
    if role not in (UserRole.ADMIN, UserRole.COACH):
        raise HTTPException(status_code=403, detail="Solo admin o coach")

    sid = current_user.get("society_id")
    settings = await _wa_get_settings(sid)
    now = datetime.now(timezone.utc)
    today = now.date()

    # Reminders log (this society)
    reminders_log = await db.whatsapp_reminders.find({"society_id": sid}).to_list(2000)

    # 🆕 Casi dismissati dall'admin (collezione whatsapp_reminders_dismissed)
    dismissed_keys = set()
    async for d in db.whatsapp_reminders_dismissed.find(
        {"society_id": sid}, {"_id": 0, "case_key": 1}
    ):
        if d.get("case_key"):
            dismissed_keys.add(d["case_key"])

    def _make_case_key(case_type: str, athlete_id=None, user_id=None, year=None, month=None) -> str:
        parts = [
            case_type,
            f"a:{athlete_id}" if athlete_id else "a:none",
            f"u:{user_id}" if user_id else "u:none",
            f"y:{year}" if year else "y:none",
            f"m:{month}" if month else "m:none",
        ]
        return "|".join(parts)

    # Restrict by team if coach
    coach_team_ids: Optional[List[str]] = None
    if role == UserRole.COACH:
        coach_team_ids = current_user.get("assigned_team_ids") or []
        if current_user.get("assigned_team_id"):
            coach_team_ids = list(set(coach_team_ids + [current_user["assigned_team_id"]]))

    # Build athletes query
    ath_q: Dict[str, Any] = {"is_withdrawn": {"$ne": True}}
    if sid:
        ath_q["society_id"] = sid
    if coach_team_ids is not None:
        ath_q["$or"] = [{"team_id": {"$in": coach_team_ids}}, {"team_id_2": {"$in": coach_team_ids}}]

    cases: List[Dict[str, Any]] = []
    # 🚀 18/08/2026 PERF — projection: escludi le foto base64 (non servono qui).
    athletes = await db.athletes.find(ath_q, {
        "athlete_photo": 0, "athlete_photo_artistic": 0, "doc_back_image": 0,
        "doc_front_image": 0, "id_back": 0, "id_front": 0, "document_back": 0,
        "document_front": 0, "privacy_signature": 0, "receipt_signature_base64": 0,
        "privacy_pdf_snapshot": 0,
    }).to_list(5000)

    # Pre-fetch ALL users of this society in a single query to build a phone cache
    # (avoids N+1 lookups inside _wa_get_phones for each athlete's parent_id)
    user_phone_cache: dict = {}
    if sid:
        async for u in db.users.find({"society_id": sid}, {"_id": 0, "id": 1, "full_name": 1, "phone": 1}):
            uid = u.get("id")
            if uid:
                user_phone_cache[uid] = {
                    "full_name": u.get("full_name", ""),
                    "phone": u.get("phone", ""),
                }

    for ath in athletes:
        ath_id = ath.get("id")
        first = ath.get("first_name") or ""
        last = ath.get("last_name") or ""
        full_name = ath.get("full_name") or f"{first} {last}".strip()
        contacts = await _wa_get_phones(ath, user_phone_cache=user_phone_cache)
        # NOTE: even if contacts is empty, we still surface the case so that
        # the admin knows there is something to do (e.g. recover phone offline).

        is_trial = ath.get("is_trial", False)
        trial_end = ath.get("trial_end_date")
        trial_start = ath.get("trial_start_date")
        status = ath.get("status", "")
        trial_doc_signed = bool(ath.get("trial_document_generated"))
        privacy_signed = bool(ath.get("privacy_accepted"))
        # "Atleta è in prova" se uno qualunque tra is_trial=True OR status='trial'
        is_in_trial = is_trial or status == "trial"

        # Normalise dates
        def _to_date(v):
            if not v: return None
            if isinstance(v, datetime): return v.date()
            try: return datetime.fromisoformat(str(v).replace("Z","+00:00")).date()
            except Exception: return None

        te = _to_date(trial_end)
        ts = _to_date(trial_start)

        # (a) [RIMOSSO 28/09/2026] Il sollecito "Firma inizio periodo di prova"
        # (trial_start_unsigned) è stato eliminato: la firma di inizio prova non è
        # più richiesta (il consenso alla prova si raccoglie con la spunta obbligatoria
        # in fase di iscrizione). Nessun sollecito viene più generato per questo caso.

        # (b) certificato mancante / non convalidato — per TUTTI gli atleti non ritirati
        # 🆕 12/09/2026 (richiesta utente): il tab "Certif. mancante" deve elencare TUTTI
        # gli atleti senza certificato valido, a prescindere dal periodo di prova.
        # "Senza certificato" = manca la data di emissione OPPURE non è ancora convalidato dall'admin.
        _issue_date = ath.get("medical_certificate_issue_date") or ath.get("medical_certificate_date")
        _cert_verified = bool(ath.get("medical_certificate_verified"))
        if (not _issue_date) or (not _cert_verified):
            ck = _make_case_key("trial_end_no_certificate", athlete_id=ath_id)
            if ck not in dismissed_keys:
                last = _wa_last_reminder(reminders_log, "trial_end_no_certificate", ath_id, None)
                _end_ctx = te.strftime("%d/%m/%Y") if te else ""
                _overdue = (today - te).days if (te and te <= today) else 0
                cases.append({
                    "case": "trial_end_no_certificate",
                    "case_key": ck,
                    "label": settings["trial_end_no_certificate"]["label"],
                    "athlete_id": ath_id,
                    "athlete_name": full_name,
                    "team_id": ath.get("team_id"),
                    "contacts": contacts,
                    "data_context": {"end_date": _end_ctx},
                    "days_overdue": _overdue,
                    "last_reminder_at": (last or {}).get("sent_at"),
                    "template": settings["trial_end_no_certificate"]["template"],
                })

        # (b/c/d) trial ended
        # 🐛 18/08/2026 FIX — La prova può essere "finita" SOLO se è davvero
        # iniziata: `trial_start_date` viene valorizzata unicamente al primo scan
        # QR (primo allenamento). Alcuni flussi di registrazione impostano invece
        # `trial_end_date` (registrazione + 7gg) SUBITO, lasciando trial_start=None:
        # senza questa guardia comparivano solleciti "Fine prova" per atleti che
        # NON hanno mai iniziato la prova (allenamenti non ancora partiti / nessun
        # certificato → non avrebbero potuto fare la prova). Ora richiediamo `ts`.
        if ts and te and te <= today:
            days_since_end = (today - te).days

            # (c) no privacy
            if not privacy_signed and days_since_end >= settings["trial_end_no_privacy"]["threshold_days"]:
                ck = _make_case_key("trial_end_no_privacy", athlete_id=ath_id)
                if ck not in dismissed_keys:
                    last = _wa_last_reminder(reminders_log, "trial_end_no_privacy", ath_id, None)
                    cases.append({
                        "case": "trial_end_no_privacy",
                        "case_key": ck,
                        "label": settings["trial_end_no_privacy"]["label"],
                        "athlete_id": ath_id,
                        "athlete_name": full_name,
                        "team_id": ath.get("team_id"),
                        "contacts": contacts,
                        "data_context": {"end_date": te.strftime("%d/%m/%Y")},
                        "days_overdue": days_since_end,
                        "last_reminder_at": (last or {}).get("sent_at"),
                        "template": settings["trial_end_no_privacy"]["template"],
                    })

            # (d) no decision (status still pending_certificate/pending_decision)
            decision_pending = status in ("pending_decision", "pending_certificate", "pending_trial") and is_trial is False
            if decision_pending and days_since_end >= settings["trial_end_no_decision"]["threshold_days"]:
                ck = _make_case_key("trial_end_no_decision", athlete_id=ath_id)
                if ck not in dismissed_keys:
                    last = _wa_last_reminder(reminders_log, "trial_end_no_decision", ath_id, None)
                    cases.append({
                        "case": "trial_end_no_decision",
                        "case_key": ck,
                        "label": settings["trial_end_no_decision"]["label"],
                        "athlete_id": ath_id,
                        "athlete_name": full_name,
                        "team_id": ath.get("team_id"),
                        "contacts": contacts,
                        "data_context": {"end_date": te.strftime("%d/%m/%Y")},
                        "days_overdue": days_since_end,
                        "last_reminder_at": (last or {}).get("sent_at"),
                        "template": settings["trial_end_no_decision"]["template"],
                    })

        # (f) certificate expiring/expired
        cert_expiry = ath.get("medical_certificate_expiry")
        if cert_expiry:
            ce = _to_date(cert_expiry)
            if ce:
                days_to = (ce - today).days
                thresh = settings["certificate_expiring"]["threshold_days"]
                if days_to <= thresh:
                    ck = _make_case_key("certificate_expiring", athlete_id=ath_id)
                    if ck not in dismissed_keys:
                        last = _wa_last_reminder(reminders_log, "certificate_expiring", ath_id, None)
                        cases.append({
                            "case": "certificate_expiring",
                            "case_key": ck,
                            "label": settings["certificate_expiring"]["label"],
                            "athlete_id": ath_id,
                            "athlete_name": full_name,
                            "team_id": ath.get("team_id"),
                            "contacts": contacts,
                            "data_context": {"expiry_date": ce.strftime("%d/%m/%Y")},
                            "days_overdue": max(0, -days_to),
                            "expires_in_days": days_to,
                            "last_reminder_at": (last or {}).get("sent_at"),
                            "template": settings["certificate_expiring"]["template"],
                        })

    # (e) Unsigned receipts (only admin sees)
    if role == UserRole.ADMIN:
        # Build society_user_ids
        society_user_ids: Optional[List[str]] = None
        if sid:
            society_user_ids = [u["id"] async for u in db.users.find({"society_id": sid}, {"_id": 0, "id": 1})]

        threshold_e = settings["unsigned_receipt"]["threshold_days"]
        coll_specs = [
            ("coach_compensations", "coach_id", "coach"),
            ("dirigente_compensations", "dirigente_id", "dirigente"),
            ("collaboratore_compensations", "collaboratore_id", "collaboratore"),
        ]
        for coll_name, owner_field, role_label in coll_specs:
            q = {"receipt_signed": {"$ne": True}, "received": True}
            if society_user_ids is not None:
                q[owner_field] = {"$in": society_user_ids}
            async for comp in db[coll_name].find(q):
                # Determine "received_date" or "created_at" as starting point
                received_date_raw = comp.get("received_date") or comp.get("created_at")
                rd = None
                if isinstance(received_date_raw, datetime):
                    rd = received_date_raw.date()
                elif received_date_raw:
                    try:
                        rd = datetime.fromisoformat(str(received_date_raw).replace("Z","+00:00")).date()
                    except Exception:
                        rd = None
                if not rd:
                    continue
                days_since = (today - rd).days
                if days_since < threshold_e:
                    continue
                owner_id = comp.get(owner_field)
                user = await db.users.find_one({"id": owner_id}, {"_id": 0, "full_name": 1, "first_name": 1, "phone": 1})
                if not user:
                    continue
                phone = user.get("phone")
                if not phone:
                    continue
                month_label = comp.get("month_name") or f"{comp.get('month')}/{comp.get('year')}"
                ck = _make_case_key(
                    "unsigned_receipt",
                    user_id=owner_id,
                    year=comp.get("year"),
                    month=comp.get("month"),
                )
                if ck in dismissed_keys:
                    continue
                last = _wa_last_reminder(reminders_log, "unsigned_receipt", None, owner_id)
                # Also key on month so multiple months don't collapse
                cases.append({
                    "case": "unsigned_receipt",
                    "case_key": ck,
                    "label": settings["unsigned_receipt"]["label"],
                    "athlete_id": None,
                    "athlete_name": None,
                    "team_id": None,
                    "user_id": owner_id,
                    "user_role": role_label,
                    "contacts": [{
                        "name": user.get("first_name") or user.get("full_name") or role_label,
                        "phone": phone,
                        "role": role_label,
                    }],
                    "data_context": {
                        "month": month_label,
                        "amount": comp.get("amount_gross") or comp.get("amount"),
                    },
                    "compensation_id": comp.get("id"),
                    "days_overdue": days_since,
                    "last_reminder_at": (last or {}).get("sent_at"),
                    "template": settings["unsigned_receipt"]["template"],
                })

    # Sort: most overdue first
    cases.sort(key=lambda x: -(x.get("days_overdue") or 0))

    return {
        "count": len(cases),
        "cases": cases,
        "society_name": (await db.societies.find_one({"id": sid}, {"_id": 0, "name": 1}) or {}).get("name") if sid else None,
    }


class WhatsAppDismissRequest(BaseModel):
    case_key: str


@api_router.post("/admin/whatsapp/dismiss")
async def dismiss_whatsapp_reminder(body: WhatsAppDismissRequest, current_user=Depends(get_current_user)):
    """Nasconde un sollecito WhatsApp dalla lista pendenti.
    Il sollecito ricomparirà solo se l'admin lo ripristina con 'restore'.
    """
    role = current_user["role"]
    if role not in (UserRole.ADMIN, UserRole.COACH):
        raise HTTPException(status_code=403, detail="Solo admin o coach")
    if not body.case_key or "|" not in body.case_key:
        raise HTTPException(status_code=400, detail="case_key non valido")

    sid = current_user.get("society_id")
    # Upsert: se già esistente, aggiorna solo dismissed_at
    await db.whatsapp_reminders_dismissed.update_one(
        {"society_id": sid, "case_key": body.case_key},
        {"$set": {
            "society_id": sid,
            "case_key": body.case_key,
            "dismissed_at": datetime.now(timezone.utc).isoformat(),
            "dismissed_by": current_user.get("id"),
            "dismissed_by_name": current_user.get("full_name") or current_user.get("email"),
        }},
        upsert=True,
    )
    return {"success": True, "case_key": body.case_key}


@api_router.post("/admin/whatsapp/dismiss/restore")
async def restore_whatsapp_reminder(body: WhatsAppDismissRequest, current_user=Depends(get_current_user)):
    """Ripristina un sollecito WhatsApp precedentemente nascosto."""
    role = current_user["role"]
    if role not in (UserRole.ADMIN, UserRole.COACH):
        raise HTTPException(status_code=403, detail="Solo admin o coach")
    sid = current_user.get("society_id")
    result = await db.whatsapp_reminders_dismissed.delete_one(
        {"society_id": sid, "case_key": body.case_key}
    )
    return {"success": True, "deleted": result.deleted_count}


@api_router.post("/admin/whatsapp/settings/reset-defaults")
async def reset_whatsapp_settings_defaults(current_user=Depends(get_current_user)):
    """Cancella i template personalizzati e ripristina i default del sistema."""
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")
    sid = current_user.get("society_id")
    r = await db.settings.delete_one({"type": "whatsapp_reminders_config", "society_id": sid})
    return {"ok": True, "deleted": r.deleted_count}


_WA_COUNT_CACHE: dict = {}
_WA_COUNT_CACHE_TTL = 60  # seconds


@api_router.get("/admin/whatsapp/pending-count")
async def get_whatsapp_pending_count(current_user=Depends(get_current_user)):
    """Lightweight endpoint: returns just the count, used by dashboard badges.

    Optimizations:
      - In-memory cache per (society_id, role, team_ids) with 60s TTL
      - Returns immediately if cached
      - On miss, runs the heavier pending-reminders calc in background
        (the next call within 60s will get the fresh value)
    """
    if current_user["role"] not in (UserRole.ADMIN, UserRole.COACH):
        raise HTTPException(status_code=403, detail="Solo admin o coach")

    # Cache key: differentiate admin (all society) vs coach (team-scoped)
    sid = current_user.get("society_id") or "_global_"
    role = current_user["role"]
    if role == UserRole.COACH:
        team_ids = sorted(current_user.get("assigned_team_ids") or [])
        if current_user.get("assigned_team_id"):
            team_ids = sorted(set(team_ids + [current_user["assigned_team_id"]]))
        cache_key = f"coach::{sid}::{','.join(team_ids)}"
    else:
        cache_key = f"admin::{sid}"

    import time as _time
    now = _time.time()
    entry = _WA_COUNT_CACHE.get(cache_key)
    if entry and (now - entry["ts"]) < _WA_COUNT_CACHE_TTL:
        return {"count": entry["count"], "cached": True}

    try:
        data = await get_pending_reminders(current_user=current_user)
        cnt = data.get("count", 0)
    except Exception as e:
        logger.warning(f"pending-count fallback: {e}")
        cnt = 0
    _WA_COUNT_CACHE[cache_key] = {"count": cnt, "ts": now}
    return {"count": cnt, "cached": False}


@api_router.post("/admin/whatsapp/log-sent")
async def log_whatsapp_sent(payload: ReminderLogIn, current_user=Depends(get_current_user)):
    if current_user["role"] not in (UserRole.ADMIN, UserRole.COACH):
        raise HTTPException(status_code=403, detail="Solo admin o coach")
    rec = {
        "id": str(uuid.uuid4()),
        "society_id": current_user.get("society_id"),
        "case": payload.case,
        "target_user_id": payload.target_user_id,
        "target_athlete_id": payload.target_athlete_id,
        "target_phone": _normalize_phone(payload.target_phone),
        "message_sent": payload.message_sent[:2000],
        "sent_by": current_user["id"],
        "sent_by_name": current_user.get("full_name"),
        "sent_by_role": current_user["role"],
        "sent_at": datetime.now(timezone.utc).isoformat(),
    }
    await db.whatsapp_reminders.insert_one(dict(rec))
    return {"ok": True, "id": rec["id"]}


@api_router.get("/admin/whatsapp/render")
async def render_whatsapp_message(case: str, athlete_id: Optional[str] = None, user_id: Optional[str] = None, contact_name: str = "", current_user=Depends(get_current_user)):
    """Render the message with variables substituted (server-side single source of truth)."""
    if current_user["role"] not in (UserRole.ADMIN, UserRole.COACH):
        raise HTTPException(status_code=403, detail="Solo admin o coach")
    sid = current_user.get("society_id")
    settings = await _wa_get_settings(sid)
    if case not in settings:
        raise HTTPException(status_code=400, detail="Caso non valido")

    society = await db.societies.find_one({"id": sid}, {"_id": 0, "name": 1}) if sid else None
    society_name = (society or {}).get("name", "RegistraTEAM")
    link = _link_app()

    nome = contact_name or ""
    atleta_name = ""
    data_str = ""
    if athlete_id:
        ath = await db.athletes.find_one({"id": athlete_id}, {"_id": 0})
        if ath:
            # Solo nome dell'atleta (no cognome) per messaggio più amichevole
            atleta_name = ath.get("first_name") or ath.get("full_name") or f"{ath.get('first_name','')} {ath.get('last_name','')}".strip()
            if case in ("trial_end_no_certificate", "trial_end_no_privacy", "trial_end_no_decision"):
                te = ath.get("trial_end_date")
                if isinstance(te, datetime):
                    data_str = te.strftime("%d/%m/%Y")
                elif te:
                    try:
                        data_str = datetime.fromisoformat(str(te).replace("Z","+00:00")).strftime("%d/%m/%Y")
                    except Exception:
                        pass
            elif case == "trial_start_unsigned":
                ts = ath.get("trial_start_date")
                if isinstance(ts, datetime):
                    data_str = ts.strftime("%d/%m/%Y")
            elif case == "certificate_expiring":
                ce = ath.get("medical_certificate_expiry")
                if ce:
                    try:
                        data_str = datetime.fromisoformat(str(ce).replace("Z","+00:00")).strftime("%d/%m/%Y")
                    except Exception:
                        data_str = str(ce)

    msg = _wa_render(settings[case]["template"], nome=nome, atleta=atleta_name, data=data_str, link=link)
    msg = msg.replace("{società}", society_name).replace("{societa}", society_name)
    return {"message": msg, "label": settings[case]["label"]}


