# ─────────────────────────── Consensi Immagini (Admin) ───────────────────────────
@api_router.get("/admin/athletes/image-consents")
async def admin_list_image_consents(
    consent_type: str = "images_promo",  # "images_promo" or "images_internal"
    only_denied: bool = True,
    team_id: Optional[str] = None,
    minors_only: bool = False,
    current_user = Depends(get_current_user),
):
    """Admin: lista atleti raggruppati per squadra con stato consenso immagini.

    Per ogni atleta calcola il `final_value` del consenso applicando la regola
    "un NO = NEGATO" sui consensi per-genitore. Per atleti maggiorenni che hanno
    firmato in autonomia, viene letta la chiave diretta.

    Query params:
    - consent_type: "images_promo" (default) o "images_internal"
    - only_denied: se true (default) restituisce solo gli atleti SENZA consenso
    - team_id: filtra per squadra specifica
    - minors_only: se true, esclude gli atleti maggiorenni
    """
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")

    if consent_type not in ("images_promo", "images_internal"):
        raise HTTPException(status_code=400, detail="consent_type non valido")

    society_id = current_user.get("society_id")
    query: dict = {"society_id": society_id}
    if team_id:
        query["team_id"] = team_id
    athletes = await db.athletes.find(query, {"_id": 0}).to_list(5000)

    # Map team_id → team_name
    team_ids = list({a.get("team_id") for a in athletes if a.get("team_id")})
    teams = await db.teams.find({"id": {"$in": team_ids}}, {"_id": 0, "id": 1, "name": 1}).to_list(500)
    team_names = {t["id"]: t.get("name", "—") for t in teams}

    # Map parent_id → parent_name (only for the parents referenced)
    parent_ids = set()
    for a in athletes:
        for k in ("parent_id", "second_parent_id"):
            pid = a.get(k)
            if pid:
                parent_ids.add(pid)
    parents = await db.users.find(
        {"id": {"$in": list(parent_ids)}},
        {"_id": 0, "id": 1, "full_name": 1, "email": 1},
    ).to_list(2000) if parent_ids else []
    parent_info = {p["id"]: p for p in parents}

    def _extract(entry):
        # 🐛 09/08/2026 — Ritorna il valore GREZZO: True / False / None (non espresso).
        # Prima ritornava False anche per i consensi mai compilati (None), facendo
        # risultare i minori come "Negato" pur non avendo mai firmato nulla.
        if isinstance(entry, bool):
            return entry
        if isinstance(entry, dict):
            return entry.get("value")
        return None

    def _privacy_signed(a: dict) -> bool:
        cons = a.get("consents") or {}
        if a.get("privacy_accepted"):
            return True
        for k, v in cons.items():
            if k == "privacy_viewed" or (isinstance(k, str) and k.startswith("privacy_viewed__")):
                if v is True or (isinstance(v, dict) and v.get("value") is True):
                    return True
        return False

    def _is_minor(a: dict) -> bool:
        bd = a.get("date_of_birth") or a.get("birth_date")
        if not bd:
            return False
        try:
            if isinstance(bd, str):
                bd_date = datetime.fromisoformat(bd.replace("Z", "+00:00")).date()
            elif hasattr(bd, "date"):
                bd_date = bd.date()
            else:
                bd_date = bd
            today = datetime.now().date()
            age = today.year - bd_date.year - ((today.month, today.day) < (bd_date.month, bd_date.day))
            return age < 18
        except Exception:
            return False

    result_athletes = []
    for a in athletes:
        if minors_only and not _is_minor(a):
            continue

        consents = a.get("consents") or {}
        athlete_parent_ids = [pid for pid in [a.get("parent_id"), a.get("second_parent_id")] if pid]
        priv_signed = _privacy_signed(a)

        # Compute final value — considera SOLO i consensi effettivamente espressi
        # (True/False). Un valore None (mai compilato) NON conta come "negato".
        parent_states = {}
        for pid in athlete_parent_ids:
            key = f"{consent_type}__{pid}"
            if key in consents:
                v = _extract(consents[key])
                if v is not None:
                    parent_states[pid] = v
            elif pid == a.get("parent_id") and consent_type in consents:
                v = _extract(consents[consent_type])
                if v is not None:
                    parent_states[pid] = v

        if parent_states:
            final_value = all(parent_states.values())
            denied_by_ids = [pid for pid, v in parent_states.items() if not v]
            denied_by_names = [
                (parent_info.get(pid) or {}).get("full_name") or (parent_info.get(pid) or {}).get("email") or pid
                for pid in denied_by_ids
            ]
            has_record = True
        else:
            raw = _extract(consents.get(consent_type))
            final_value = bool(raw) if raw is not None else False
            denied_by_names = []
            has_record = raw is not None

        if only_denied and final_value:
            continue

        full_name = f"{a.get('last_name','')} {a.get('first_name','')}".strip() or a.get("full_name", "—")
        result_athletes.append({
            "athlete_id": a.get("id"),
            "entity_type": "athlete",
            "full_name": full_name,
            "team_id": a.get("team_id"),
            "team_name": team_names.get(a.get("team_id"), "Senza squadra"),
            "birth_date": a.get("date_of_birth") or a.get("birth_date"),
            "is_minor": _is_minor(a),
            "consent_given": final_value,
            "denied_by_parents": denied_by_names,
            "has_signed": has_record,
            "privacy_signed": priv_signed,
            "privacy_accepted": bool(a.get("privacy_accepted")),
        })

    # Group by team
    by_team: dict = {}
    for r in result_athletes:
        tid = r["team_id"] or "_none_"
        if tid not in by_team:
            by_team[tid] = {
                "team_id": r["team_id"],
                "team_name": r["team_name"],
                "is_staff": False,
                "athletes": [],
            }
        by_team[tid]["athletes"].append(r)

    # Sort teams by name; athletes within each team by last name (full_name)
    groups = sorted(by_team.values(), key=lambda g: (g["team_name"] or "").lower())
    for g in groups:
        g["athletes"].sort(key=lambda x: (x["full_name"] or "").lower())
        g["count"] = len(g["athletes"])

    # 🆕 03/08/2026 — Includere anche lo STAFF (coach, dirigenti, collaboratori):
    # i loro consensi immagine sono salvati sul record utente (users.consents).
    # Vengono raggruppati per ruolo e mostrati SOLO quando non c'è un filtro squadra
    # e non è attivo minors_only (lo staff è adulto).
    staff_groups_out = []
    if not team_id and not minors_only:
        STAFF_ROLES = ["coach", "dirigente", "collaboratore", "admin"]
        role_label = {
            "coach": "Staff · Coach",
            "dirigente": "Staff · Dirigenti",
            "admin": "Staff · Dirigenti",
            "collaboratore": "Staff · Collaboratori",
        }
        nav_prefix = {"coach": "coach", "dirigente": "dirigente", "admin": "dirigente", "collaboratore": "collaboratore"}
        staff_users = await db.users.find(
            {"society_id": society_id, "role": {"$in": STAFF_ROLES}},
            {"_id": 0, "id": 1, "full_name": 1, "email": 1, "role": 1, "consents": 1, "is_institutional": 1, "linked_athlete_id": 1},
        ).to_list(5000)

        # 🐛 03/08/2026 (fix doppio incarico) — Lo staff promosso da atleta firma
        # privacy e consensi immagine sul record ATLETA collegato (linked_athlete_id),
        # non sul record utente. Carichiamo quei record per usarli come fallback,
        # così un coach che è anche atleta non risulta erroneamente "senza consenso".
        linked_ids = [u.get("linked_athlete_id") for u in staff_users if u.get("linked_athlete_id")]
        linked_athletes: dict = {}
        if linked_ids:
            for la in await db.athletes.find(
                {"id": {"$in": linked_ids}},
                {"_id": 0, "id": 1, "consents": 1, "privacy_accepted": 1},
            ).to_list(5000):
                linked_athletes[la["id"]] = la

        staff_by_label: dict = {}
        for u in staff_users:
            if u.get("is_institutional"):
                continue  # l'account istituzionale non firma consensi immagine
            consents = u.get("consents") or {}
            raw_v = _extract(consents.get(consent_type))
            privacy_raw = consents.get("privacy_viewed")
            priv_signed = (_extract(privacy_raw) is True)

            # Fallback su atleta collegato (doppio incarico)
            la = linked_athletes.get(u.get("linked_athlete_id")) if u.get("linked_athlete_id") else None
            if la is not None:
                la_cons = la.get("consents") or {}
                if raw_v is None:
                    raw_v = _extract(la_cons.get(consent_type))
                if not priv_signed:
                    priv_signed = _privacy_signed(la)

            final_value = bool(raw_v) if raw_v is not None else False
            has_record = raw_v is not None
            if only_denied and final_value:
                continue
            label = role_label.get(u.get("role"), "Staff")
            entry = {
                "athlete_id": u.get("id"),
                "entity_type": "staff",
                "role": u.get("role"),
                "nav_path": f"/admin/{nav_prefix.get(u.get('role'), 'coach')}/{u.get('id')}",
                "full_name": u.get("full_name") or u.get("email") or "—",
                "team_id": None,
                "team_name": label,
                "birth_date": None,
                "is_minor": False,
                "consent_given": final_value,
                "denied_by_parents": [],
                "has_signed": has_record,
                "privacy_signed": priv_signed,
                "privacy_accepted": priv_signed,
            }
            staff_by_label.setdefault(label, {
                "team_id": f"_staff_{label}",
                "team_name": label,
                "is_staff": True,
                "athletes": [],
            })
            staff_by_label[label]["athletes"].append(entry)
        staff_groups_out = sorted(staff_by_label.values(), key=lambda g: (g["team_name"] or "").lower())
        for g in staff_groups_out:
            g["athletes"].sort(key=lambda x: (x["full_name"] or "").lower())
            g["count"] = len(g["athletes"])

    all_groups = groups + staff_groups_out
    total_all = len(result_athletes) + sum(g["count"] for g in staff_groups_out)

    return {
        "consent_type": consent_type,
        "only_denied": only_denied,
        "minors_only": minors_only,
        "team_id_filter": team_id,
        "total": total_all,
        "groups": all_groups,
    }


