def _public_verify_url(document_id: str) -> str:
    """Build the public verification URL for a signed document QR code.
    Points to the FRONTEND SPA route (so it works on Vercel-hosted production
    where the marketing domain doesn't proxy /api/* to the backend).
    """
    base = (os.environ.get("FRONTEND_URL") or "").rstrip("/")
    return f"{base}/verify/{document_id}"


def _generate_qr_png(data: str) -> Optional[bytes]:
    """Generate a small PNG (transparent-free) QR code for the given data."""
    try:
        import qrcode
        qr = qrcode.QRCode(version=None, error_correction=qrcode.constants.ERROR_CORRECT_M, box_size=4, border=2)
        qr.add_data(data)
        qr.make(fit=True)
        img = qr.make_image(fill_color="black", back_color="white").convert("RGB")
        buf = io.BytesIO()
        img.save(buf, format="PNG")
        return buf.getvalue()
    except Exception as e:
        logger.warning(f"QR generation failed: {e}")
        return None


@api_router.get("/documents/verify/{document_id}")
async def public_document_verify(document_id: str, format: str = "html"):
    """Public endpoint (no auth) — verifies document authenticity.

    Returns HTML by default (for direct browser access) or JSON when called
    with ?format=json (for the frontend SPA route to render natively).
    """
    doc = await db.signed_documents.find_one(
        {"id": document_id},
        {"_id": 0, "id": 1, "document_type": 1, "signer_name": 1, "coach_name": 1,
         "dirigente_name": 1, "collaboratore_name": 1, "athlete_name": 1,
         "signed_at": 1, "month": 1, "year": 1, "amount_gross": 1, "threshold_metadata": 1,
         "society_id": 1, "athlete_id": 1, "coach_id": 1, "dirigente_id": 1,
         "collaboratore_id": 1, "signer_id": 1,
         "signature_hash": 1, "gdpr_metadata": 1},
    )
    if not doc:
        if format == "json":
            raise HTTPException(status_code=404, detail="Documento non trovato")
        html = """
        <html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Documento non trovato</title>
        <style>body{font-family:-apple-system,system-ui,Helvetica,Arial,sans-serif;background:#f5f5f5;padding:20px;color:#333}
        .box{background:#fff;max-width:520px;margin:40px auto;padding:32px 24px;border-radius:10px;box-shadow:0 1px 4px rgba(0,0,0,.1);text-align:center}
        .icon{font-size:48px;color:#D32F2F}
        h1{margin:12px 0 6px;font-size:22px;color:#D32F2F}
        p{color:#666;line-height:1.5}</style>
        </head><body><div class="box"><div class="icon">✕</div><h1>Documento non trovato</h1>
        <p>L'identificativo non corrisponde ad alcun documento firmato nei nostri archivi.</p></div></body></html>
        """
        return HTMLResponse(content=html, status_code=404)

    # Mask signer name (first name + initial)
    raw_name = (doc.get("signer_name") or doc.get("coach_name") or "").strip()
    if raw_name:
        parts = raw_name.split()
        if len(parts) >= 2:
            masked = f"{parts[0]} {parts[1][0]}."
            for p in parts[2:]:
                masked += f" {p[0]}."
        else:
            masked = raw_name
    else:
        masked = "—"

    dtype = doc.get("document_type", "")
    type_label = {
        "compensation_receipt": "Quietanza di compenso sportivo dilettantistico",
        "coach_compensation_receipt": "Quietanza di compenso sportivo dilettantistico",
        "collaboratore_compensation_receipt": "Quietanza di compenso sportivo dilettantistico",
        "threshold_5000_communication": "Comunicazione superamento soglia € 5.000",
        "threshold_15000_communication": "Comunicazione superamento soglia € 15.000",
    }.get(dtype, dtype or "Documento firmato")

    signed_at = doc.get("signed_at")
    try:
        if isinstance(signed_at, str):
            _dt = datetime.fromisoformat(signed_at.replace("Z", "+00:00"))
        elif hasattr(signed_at, "isoformat"):
            _dt = signed_at
        else:
            _dt = None
        signed_str = to_rome_time(_dt).strftime("%d/%m/%Y %H:%M:%S") if _dt else "—"
    except Exception:
        signed_str = "—"

    # Month reference
    m_int = int(doc.get("month")) if doc.get("month") else None
    y_int = int(doc.get("year")) if doc.get("year") else None
    month_ref = f"{MONTH_NAMES.get(m_int, '')} {y_int}".strip() if m_int else "—"

    tm = doc.get("threshold_metadata") or {}
    gm = doc.get("gdpr_metadata") or {}
    # 🆕 30/06/2026 — Hash firma: priorità threshold_metadata (quietanze
    # soglia) → top-level signature_hash (privacy GDPR / quietanze semplici)
    # → fallback gdpr_metadata.document_hash (hash del contenuto documento).
    sig_hash_full = (
        tm.get("signature_hash")
        or doc.get("signature_hash")
        or gm.get("document_hash")
        or ""
    )
    sig_hash = sig_hash_full[:16] or "—"

    threshold_block = ""
    if dtype.startswith("threshold_"):
        threshold_block = f"""
        <div class="row"><span class="lbl">Soglia superata</span><span class="val">€ {('15.000' if '15000' in dtype else '5.000')}</span></div>
        <div class="row"><span class="lbl">Mese di superamento</span><span class="val">{month_ref}</span></div>"""
    else:
        amt = doc.get("amount_gross")
        amt_str = f"€ {float(amt):.2f}" if amt is not None else "—"
        threshold_block = f"""
        <div class="row"><span class="lbl">Mese di riferimento</span><span class="val">{month_ref}</span></div>
        <div class="row"><span class="lbl">Importo lordo</span><span class="val">{amt_str}</span></div>"""

    # Society name
    # 🐛 27/07/2026 (bug multi-tenancy) — PRIMA: se document.society_id era None/vuoto,
    # il codice faceva find_one({"type": "society"}) SENZA filtro tenant, prendendo la
    # PRIMA società del DB (Pallavolo Perugia SSD in ordine di creazione) e mostrandola
    # a utenti di altre società (leak visibile in QR verification pagina pubblica).
    # ADESSO: se society_id manca → risalire dal firmatario (utente/atleta) via il
    # rispettivo id_field. Nessun fallback cross-tenant globale.
    society_name = ""
    try:
        sid = doc.get("society_id")
        # 🐛 27/07/2026 — Legacy docs (dirigente/coach/collaboratore/atleta) creati
        # prima del fix del 27/07 non hanno society_id. Deduciamolo dal firmatario
        # partendo dagli id specifici (senza mai fare query globali).
        if not sid:
            candidate_ids = [
                doc.get("signer_id"),
                doc.get("coach_id"),
                doc.get("dirigente_id"),
                doc.get("collaboratore_id"),
                doc.get("athlete_id"),
            ]
            for cid in candidate_ids:
                if not cid:
                    continue
                u = await db.users.find_one({"id": cid}, {"_id": 0, "society_id": 1})
                if u and u.get("society_id"):
                    sid = u["society_id"]
                    break
                a = await db.athletes.find_one({"id": cid}, {"_id": 0, "society_id": 1})
                if a and a.get("society_id"):
                    sid = a["society_id"]
                    break
        if sid:
            s = await db.settings.find_one(
                {"type": "society", "society_id": sid},
                {"_id": 0, "ragione_sociale": 1, "society_name": 1, "name": 1},
            )
            # 🐛 27/07/2026 — Il campo in settings è `name` (non `society_name`).
            society_name = (
                (s or {}).get("ragione_sociale")
                or (s or {}).get("name")
                or (s or {}).get("society_name")
                or ""
            )
            if not society_name:
                # Fallback: cerca in societies collection (tipicamente ha "name")
                soc = await db.societies.find_one({"id": sid}, {"_id": 0, "name": 1, "ragione_sociale": 1})
                society_name = (soc or {}).get("ragione_sociale") or (soc or {}).get("name") or ""
    except Exception:
        pass

    # JSON branch (used by the frontend SPA /verify/[id] route)
    if format == "json":
        amt = doc.get("amount_gross")
        return {
            "document_id": document_id,
            "type_label": type_label,
            "kind": "threshold" if dtype.startswith("threshold_") else "receipt",
            "threshold": "15000" if "15000" in dtype else ("5000" if "5000" in dtype else None),
            "society_name": society_name,
            "signer_masked": masked,
            "signed_at_rome": signed_str,
            "month_ref": month_ref,
            "amount_str": (f"€ {float(amt):.2f}" if amt is not None else None),
            "signature_hash_prefix": (sig_hash_full[:16] or None),
        }

    html = f"""<!doctype html><html lang="it"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Verifica autenticità documento</title>
<style>
body{{font-family:-apple-system,system-ui,Helvetica,Arial,sans-serif;background:#f5f5f5;margin:0;padding:16px;color:#222}}
.box{{background:#fff;max-width:560px;margin:24px auto;padding:0;border-radius:12px;box-shadow:0 2px 10px rgba(0,0,0,.08);overflow:hidden}}
.hd{{background:#2E7D32;color:#fff;padding:22px 20px;text-align:center}}
.hd .badge{{display:inline-block;background:#fff;color:#2E7D32;border-radius:20px;padding:4px 12px;font-size:11px;font-weight:700;letter-spacing:.5px;margin-bottom:8px}}
.hd h1{{margin:0;font-size:18px;font-weight:600;line-height:1.3}}
.body{{padding:20px}}
.row{{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #f0f0f0;font-size:14px}}
.row:last-child{{border-bottom:none}}
.lbl{{color:#666;font-weight:500;flex-shrink:0;padding-right:12px}}
.val{{color:#222;text-align:right;font-weight:600;word-break:break-word}}
.note{{background:#FFF9E5;border-left:3px solid #FBC02D;padding:12px 14px;margin-top:16px;border-radius:0 6px 6px 0;font-size:12px;color:#666;line-height:1.5}}
.foot{{text-align:center;padding:12px;font-size:11px;color:#999}}
</style></head>
<body>
<div class="box">
  <div class="hd">
    <div class="badge">✓ DOCUMENTO AUTENTICO</div>
    <h1>{type_label}</h1>
  </div>
  <div class="body">
    <div class="row"><span class="lbl">Società</span><span class="val">{society_name or '—'}</span></div>
    <div class="row"><span class="lbl">Firmatario</span><span class="val">{masked}</span></div>
    <div class="row"><span class="lbl">Data firma</span><span class="val">{signed_str}<br><span style="font-size:11px;color:#888;font-weight:normal">(Europe/Rome)</span></span></div>
    {threshold_block}
    <div class="row"><span class="lbl">ID documento</span><span class="val" style="font-family:monospace;font-size:11px">{document_id}</span></div>
    <div class="row"><span class="lbl">Hash firma</span><span class="val" style="font-family:monospace;font-size:11px">{sig_hash}…</span></div>
    <div class="note">
      Per tutela della privacy non vengono mostrati nome completo, codice fiscale, importo dettagliato o immagine della firma.
      Questa pagina prova solo l'<strong>esistenza e l'autenticità</strong> della firma elettronica sul documento.
    </div>
  </div>
  <div class="foot">Generato da RegistraTEAM · {datetime.now(timezone.utc).year}</div>
</div>
</body></html>"""
    return HTMLResponse(content=html, headers={"Cache-Control": "no-store"})


@api_router.post("/admin/athletes/cleanup-pro-trial-status")
async def admin_cleanup_pro_trial_status(current_user = Depends(get_current_user)):
    """🆕 30/06/2026 — One-shot: ripulisce lo stato 'trial/pending_trial' dagli
    atleti PRO (`is_compensated=True`). Le atlete promosse a PRO non devono mai
    essere in periodo di prova; lo stato corretto è:
      • 'active' se hanno certificato medico convalidato
      • 'pending_certificate' altrimenti (in attesa convalida del coach)

    Pensato per allineare i record creati prima del fix del 30/06 (es. sorelle
    Prati che mostravano "In attesa" pur essendo PRO)."""
    if current_user.get("role") not in ("admin", "super_admin"):
        raise HTTPException(status_code=403, detail="Solo admin")
    society_id = current_user.get("society_id")
    q: dict = {"is_compensated": True}
    if society_id:
        q["society_id"] = society_id
    athletes = await db.athletes.find(q, {
        "_id": 0, "id": 1, "full_name": 1, "first_name": 1, "last_name": 1,
        "is_trial": 1, "trial_status": 1, "status": 1,
        "medical_certificate_expiry": 1, "medical_certificate_validated_at": 1,
    }).to_list(1000)
    updated = 0
    out: list = []
    now_dt = datetime.utcnow()
    for ath in athletes:
        # Calcola lo status target (active vs pending_certificate)
        cert_valid = False
        exp_raw = ath.get("medical_certificate_expiry")
        try:
            if exp_raw:
                if isinstance(exp_raw, str):
                    exp_dt = datetime.fromisoformat(exp_raw.replace("Z", "+00:00"))
                else:
                    exp_dt = exp_raw
                exp_naive = exp_dt.replace(tzinfo=None) if hasattr(exp_dt, "tzinfo") else exp_dt
                cert_valid = exp_naive > now_dt and bool(ath.get("medical_certificate_validated_at"))
        except Exception:
            cert_valid = False
        target_status = "active" if cert_valid else "pending_certificate"
        # Aggiorna solo se necessario
        needs_update = (
            ath.get("is_trial") is True
            or ath.get("trial_status") in ("active", "ongoing", "pending")
            or ath.get("status") in ("trial", "pending_trial", "in_attesa", "pending_decision")
        )
        if needs_update or ath.get("status") != target_status:
            await db.athletes.update_one(
                {"id": ath["id"]},
                {"$set": {
                    "is_trial": False,
                    "trial_status": "completed",
                    "trial_start_date": None,
                    "trial_end_date": None,
                    "status": target_status,
                }}
            )
            updated += 1
            out.append({
                "id": ath["id"],
                "name": ath.get("full_name") or f"{ath.get('last_name','')} {ath.get('first_name','')}".strip(),
                "old_status": ath.get("status"),
                "new_status": target_status,
            })
    return {"total_pro_athletes": len(athletes), "updated": updated, "details": out}
async def admin_regenerate_all_receipts(current_user = Depends(get_current_user)):
    """Admin: forza la rigenerazione di TUTTE le quietanze della società.

    Per ogni quietanza firmata (compensation_receipt / coach_compensation_receipt
    / collaboratore_compensation_receipt) invalida la cache (pdf_base64 +
    pdf_path su disco) così che al prossimo download verrà rigenerata con:
      - data di firma originale
      - firma immagine (recuperata dal source-of-truth compensation row)
      - metadati di autentica GDPR
    """
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")

    society_id = current_user.get("society_id")
    base_filter = {"document_type": {"$in": [
        "compensation_receipt",
        "coach_compensation_receipt",
        "collaboratore_compensation_receipt",
        "threshold_5000_communication",
        "threshold_15000_communication",
    ]}}
    # If admin has a society_id, include docs of that society OR legacy docs
    # without society_id field (their society is implied by the signer).
    if society_id:
        query = {**base_filter, "$or": [
            {"society_id": society_id},
            {"society_id": {"$exists": False}},
            {"society_id": None},
        ]}
    else:
        query = base_filter

    docs = await db.signed_documents.find(query, {"_id": 0, "id": 1, "pdf_path": 1}).to_list(20000)
    invalidated_cache = 0
    removed_files = 0
    errors = []
    for d in docs:
        # 1) Unset pdf_base64 cache in DB
        try:
            res = await db.signed_documents.update_one(
                {"id": d["id"]},
                {"$unset": {"pdf_base64": ""}}
            )
            if res.modified_count:
                invalidated_cache += 1
        except Exception as e:
            errors.append({"id": d["id"], "error": str(e)})
            continue
        # 2) Remove stale PDF file from disk (will be regenerated on next download)
        if d.get("pdf_path"):
            try:
                if os.path.exists(d["pdf_path"]):
                    os.remove(d["pdf_path"])
                    removed_files += 1
            except Exception as e:
                errors.append({"id": d["id"], "error": f"file_remove: {str(e)}"})

    return {
        "message": f"Rigenerazione preparata per {len(docs)} quietanze. Verranno ricostruite con metadati e firma corretti al prossimo accesso.",
        "total": len(docs),
        "cache_invalidated": invalidated_cache,
        "files_removed": removed_files,
        "errors": errors[:50],  # cap to avoid huge response
    }


# ─────────────────────────── /Rigenera quietanze ───────────────────────────


@api_router.post("/admin/wipe-user-compensation-data")
async def admin_wipe_user_compensation_data(
    payload: dict = Body(...),
    current_user = Depends(get_current_user),
):
    """Admin: wipe TOTALE dei dati compensi di un utente.
    Cancella in modo definitivo:
      - tutte le righe in collaboratore_compensations / coach_compensations /
        dirigente_compensations / atleta_pro_compensations
      - tutte le threshold_declarations
      - tutti i signed_documents di tipo quietanza + comunicazione soglia +
        dichiarazione soglia firmati da quell'utente

    Body JSON: {"email": "user@example.com", "confirm": "YES_DELETE_ALL"}
    """
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")

    email = (payload.get("email") or "").strip().lower()
    confirm = payload.get("confirm")
    only_year = payload.get("year")  # opzionale: se specificato, ripulisce solo quell'anno
    if only_year is not None:
        try:
            only_year = int(only_year)
        except Exception:
            raise HTTPException(status_code=400, detail='Il campo "year" deve essere un intero')
    if not email:
        raise HTTPException(status_code=400, detail="email obbligatoria")
    if confirm != "YES_DELETE_ALL":
        raise HTTPException(status_code=400, detail='Aggiungi "confirm": "YES_DELETE_ALL" per procedere')

    user = await db.users.find_one({"email": email}, {"_id": 0})
    if not user:
        raise HTTPException(status_code=404, detail=f"Utente {email} non trovato")

    user_id = user["id"]

    # Multi-tenant safety: l'admin può cancellare solo utenti della propria società
    society_id = current_user.get("society_id")
    if society_id and user.get("society_id") and user["society_id"] != society_id:
        raise HTTPException(status_code=403, detail="Utente di un'altra società")

    deleted: dict = {"year_filter": only_year}

    # 1. Compensation rows (cancella indipendentemente dal tipo, l'utente può
    #    essere coach/collaboratore/dirigente/atleta_pro o multi-ruolo)
    for coll, key in [
        ("coach_compensations", "coach_id"),
        ("collaboratore_compensations", "collaboratore_id"),
        ("dirigente_compensations", "dirigente_id"),
        ("atleta_pro_compensations", "atleta_id"),
        ("compensations", "coach_id"),  # legacy
    ]:
        try:
            q = {key: user_id}
            if only_year is not None:
                q["year"] = only_year
            r = await db[coll].delete_many(q)
            deleted[coll] = r.deleted_count
        except Exception as e:
            deleted[coll] = f"error: {e}"

    # 2. Threshold declarations
    try:
        q = {
            "$or": [
                {"coach_id": user_id},
                {"collaboratore_id": user_id},
                {"dirigente_id": user_id},
                {"atleta_id": user_id},
                {"signer_id": user_id},
            ]
        }
        if only_year is not None:
            q["year"] = only_year
        r = await db.threshold_declarations.delete_many(q)
        deleted["threshold_declarations"] = r.deleted_count
    except Exception as e:
        deleted["threshold_declarations"] = f"error: {e}"

    # 3. Signed documents (quietanze + comunicazioni soglia + dichiarazioni)
    receipt_doc_types = [
        "compensation_receipt",
        "coach_compensation_receipt",
        "collaboratore_compensation_receipt",
        "dirigente_compensation_receipt",
        "atleta_pro_compensation_receipt",
        "threshold_5000_communication",
        "threshold_15000_communication",
        "threshold_declaration_5000",
        "threshold_declaration_15000",
    ]
    try:
        # Recupera i pdf_path da cancellare anche dal filesystem
        q = {
            "$or": [
                {"coach_id": user_id},
                {"collaboratore_id": user_id},
                {"dirigente_id": user_id},
                {"atleta_id": user_id},
                {"signer_id": user_id},
            ],
            "document_type": {"$in": receipt_doc_types},
        }
        if only_year is not None:
            q["year"] = only_year
        docs_to_delete = await db.signed_documents.find(
            q,
            {"_id": 0, "id": 1, "pdf_path": 1, "document_type": 1},
        ).to_list(5000)

        files_removed = 0
        for d in docs_to_delete:
            p = d.get("pdf_path")
            if p and os.path.exists(p):
                try:
                    os.remove(p)
                    files_removed += 1
                except Exception:
                    pass

        r = await db.signed_documents.delete_many(q)
        deleted["signed_documents"] = r.deleted_count
        deleted["files_removed"] = files_removed
    except Exception as e:
        deleted["signed_documents"] = f"error: {e}"

    # 4. Reset eventuali flag di soglia sui yearly_limits dell'utente
    try:
        q = {"user_id": user_id}
        if only_year is not None:
            q["year"] = only_year
        r = await db.yearly_limits.update_many(
            q,
            {"$set": {
                "exceeded_5000": False,
                "exceeded_5000_date": None,
                "exceeded_5000_declaration_id": None,
                "exceeded_15000": False,
                "exceeded_15000_date": None,
                "exceeded_15000_declaration_id": None,
            }},
        )
        deleted["yearly_limits_reset"] = r.modified_count
    except Exception:
        deleted["yearly_limits_reset"] = 0

    # 5. external_compensations dichiarate per quell'anno
    try:
        q = {"user_id": user_id}
        if only_year is not None:
            q["year"] = only_year
        r = await db.external_compensations.delete_many(q)
        deleted["external_compensations"] = r.deleted_count
    except Exception:
        deleted["external_compensations"] = 0

    logger.warning(
        f"WIPE COMPENSATION DATA: admin={current_user.get('email')} target={email} ({user_id}) result={deleted}"
    )

    return {
        "success": True,
        "user_email": email,
        "user_id": user_id,
        "deleted": deleted,
    }


@api_router.post("/admin/athletes/image-consents/notify-team")
async def admin_notify_team_image_consents(
    payload: dict = Body(...),
    current_user = Depends(get_current_user),
):
    """Admin: invia un'email al coach (e p.c. società) con la lista degli atleti
    della sua squadra SENZA consenso uso immagini, per uso operativo (es. foto
    di squadra a fine partita).

    Body JSON: {"team_id": "...", "consent_type": "images_promo" | "images_internal"}
    """
    if current_user["role"] != UserRole.ADMIN:
        raise HTTPException(status_code=403, detail="Solo admin")

    team_id = payload.get("team_id")
    consent_type = payload.get("consent_type", "images_promo")
    if not team_id:
        raise HTTPException(status_code=400, detail="team_id obbligatorio")
    if consent_type not in ("images_promo", "images_internal"):
        raise HTTPException(status_code=400, detail="consent_type non valido")

    society_id = current_user.get("society_id")

    # Resolve team
    team = await db.teams.find_one({"id": team_id, "society_id": society_id}, {"_id": 0})
    if not team:
        raise HTTPException(status_code=404, detail="Squadra non trovata")

    # Find coaches assigned to this team
    coaches = await db.users.find(
        {
            "society_id": society_id,
            "role": UserRole.COACH,
            "$or": [
                {"assigned_team_ids": team_id},
                {"assigned_team_id": team_id},
            ],
        },
        {"_id": 0, "id": 1, "full_name": 1, "email": 1},
    ).to_list(50)
    if not coaches:
        raise HTTPException(
            status_code=400,
            detail="Nessun coach assegnato a questa squadra. Assegna un coach prima di inviare la notifica.",
        )

    # Society email (cc)
    society_settings = await db.settings.find_one(
        {"type": "society", "society_id": society_id}, {"_id": 0}
    ) or await db.settings.find_one({"type": "society"}, {"_id": 0}) or {}  # noqa: multitenancy-ok — fallback dopo tentativo mirato
    society_email = society_settings.get("society_email")
    society_name = society_settings.get("ragione_sociale") or society_settings.get("society_name") or "la società"

    # Fetch athletes (denied only) for this team
    athletes = await db.athletes.find(
        {"society_id": society_id, "team_id": team_id}, {"_id": 0}
    ).to_list(2000)
    parent_ids = {pid for a in athletes for pid in [a.get("parent_id"), a.get("second_parent_id")] if pid}
    parents = await db.users.find(
        {"id": {"$in": list(parent_ids)}},
        {"_id": 0, "id": 1, "full_name": 1, "email": 1},
    ).to_list(2000) if parent_ids else []
    parent_info = {p["id"]: p for p in parents}

    def _extract(entry):
        if isinstance(entry, bool):
            return entry
        if isinstance(entry, dict):
            return entry.get("value", False)
        return False

    denied_rows = []
    for a in athletes:
        consents = a.get("consents") or {}
        athlete_parent_ids = [pid for pid in [a.get("parent_id"), a.get("second_parent_id")] if pid]
        parent_states = {}
        for pid in athlete_parent_ids:
            key = f"{consent_type}__{pid}"
            if key in consents:
                parent_states[pid] = _extract(consents[key])
            elif pid == a.get("parent_id") and consent_type in consents:
                parent_states[pid] = _extract(consents[consent_type])
        if parent_states:
            final_value = all(parent_states.values())
            denied_by_names = [
                (parent_info.get(pid) or {}).get("full_name") or (parent_info.get(pid) or {}).get("email") or pid
                for pid, v in parent_states.items() if not v
            ]
        else:
            raw = consents.get(consent_type)
            final_value = _extract(raw) if raw is not None else False
            denied_by_names = []
        if final_value:
            continue
        full_name = f"{a.get('last_name','')} {a.get('first_name','')}".strip() or a.get("full_name", "—")
        denied_rows.append({"name": full_name, "denied_by": denied_by_names})

    consent_label = "promozionale (social, sito, materiale promozionale)" if consent_type == "images_promo" else "uso interno (gruppi WhatsApp, archivio storico)"
    team_name = team.get("name", "—")

    if not denied_rows:
        rows_html = "<p style='color:#2E7D32; font-weight:bold;'>✅ Tutti gli atleti di questa squadra hanno dato il consenso. Nessuna restrizione.</p>"
    else:
        rows_html = "<ul style='padding-left:20px; line-height:1.7;'>"
        for r in denied_rows:
            extra = f" <span style='color:#666;font-size:12px;'>(negato da: {' · '.join(r['denied_by'])})</span>" if r['denied_by'] else ""
            rows_html += f"<li><strong>{r['name']}</strong>{extra}</li>"
        rows_html += "</ul>"

    html = f"""
<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; color: #333;">
  <div style="background: #1976D2; color: #fff; padding: 20px; border-radius: 8px 8px 0 0;">
    <h2 style="margin:0;">📸 Consensi Immagini — Squadra {team_name}</h2>
  </div>
  <div style="background: #fff; padding: 24px; border: 1px solid #e0e0e0; border-top: none; border-radius: 0 0 8px 8px;">
    <p>Ciao,</p>
    <p>Per garantire il rispetto del GDPR e della privacy dei tuoi atleti, ti inviamo l'elenco aggiornato degli atleti della squadra <strong>{team_name}</strong> che <strong>NON hanno prestato consenso</strong> per l'uso delle immagini ad uso <strong>{consent_label}</strong>.</p>
    <div style="background: #FFF3E0; border-left: 4px solid #FF9800; padding: 12px 16px; margin: 16px 0; border-radius: 4px;">
      <strong>⚠️ Atleti da escludere da foto / video / pubblicazioni:</strong>
      {rows_html}
    </div>
    <p style="font-size: 13px; color: #666;">
      <strong>Cosa fare:</strong><br/>
      • Durante le foto di squadra (fine partita, eventi), assicurati che questi atleti non compaiano oppure oscurane il volto prima di pubblicare.<br/>
      • Questa lista può cambiare nel tempo (i genitori possono modificare il consenso in qualsiasi momento). Consulta la sezione "Consensi Immagini" nel pannello Admin prima di ogni pubblicazione importante.
    </p>
    <p style="font-size: 12px; color: #999; margin-top: 24px; border-top: 1px solid #eee; padding-top: 12px;">
      Email automatica generata da {society_name} tramite RegistraTEAM. In copia: l'indirizzo istituzionale della società.
    </p>
  </div>
</div>
"""
    subject = f"[GDPR] Consensi Immagini — {team_name} ({len(denied_rows)} atleti da escludere)"

    from email_service import send_transactional_email

    sent_to: list = []
    errors: list = []
    cc_list = [society_email] if society_email and society_email not in [c.get("email") for c in coaches] else None

    for coach in coaches:
        coach_email = coach.get("email")
        if not coach_email:
            continue
        try:
            result = await send_transactional_email(
                to_email=coach_email,
                to_name=coach.get("full_name"),
                subject=subject,
                html_content=html,
                cc_list=cc_list,
            )
            if result.get("success"):
                sent_to.append(coach_email)
            else:
                errors.append({"email": coach_email, "error": result.get("error", "unknown")})
        except Exception as e:
            errors.append({"email": coach_email, "error": str(e)})

    return {
        "message": f"Email inviata a {len(sent_to)} coach.",
        "sent_to": sent_to,
        "cc": cc_list or [],
        "team_name": team_name,
        "denied_count": len(denied_rows),
        "errors": errors,
    }


