@app.on_event("startup")
async def ensure_mongodb_indexes():
    """Create MongoDB indexes at startup for performance.
    Idempotent: create_index is a no-op if the index already exists.
    Runs in background to avoid blocking startup.
    """
    import asyncio as _asyncio

    async def _create_indexes():
        try:
            # users: lookups by id, email, society_id
            await db.users.create_index("id")
            await db.users.create_index("email")
            await db.users.create_index("society_id")
            await db.users.create_index([("society_id", 1), ("role", 1)])
            # teams
            await db.teams.create_index("id")
            await db.teams.create_index("society_id")
            # athletes: the hot collection
            await db.athletes.create_index("id")
            await db.athletes.create_index("society_id")
            await db.athletes.create_index("team_id")
            # 🚀 16/08/2026 — Indici per le query multi-squadra (conteggi/roster su
            # team_id_2 e team_ids[]). Senza questi indici i $or introdotti il 15/08
            # facevano collection scan → lentezza aprendo squadre/registro presenze.
            await db.athletes.create_index("team_id_2")
            await db.athletes.create_index("team_ids")
            await db.athletes.create_index([("society_id", 1), ("team_id_2", 1)])
            await db.athletes.create_index([("society_id", 1), ("team_ids", 1)])
            await db.athletes.create_index("user_id")
            await db.athletes.create_index([("society_id", 1), ("team_id", 1)])
            # 🆕 08/07/2026 (v7.11) — Indice compound per login Lite: nome_lite deve essere
            # unico DENTRO la società (una Chiara⭐ per società, non a livello globale).
            # `sparse=True` ignora gli atleti che non hanno ancora scelto un nome_lite.
            # `partialFilterExpression` ulteriore garanzia: indice attivo solo quando
            # nome_lite è una stringa non vuota.
            try:
                await db.athletes.create_index(
                    [("society_id", 1), ("nome_lite", 1)],
                    unique=True,
                    partialFilterExpression={"nome_lite": {"$exists": True, "$type": "string"}},
                    name="ux_society_nomelite",
                )
            except Exception as _idx_exc:
                logger.warning(f"Failed to create ux_society_nomelite index: {_idx_exc}")
            
            # 🆕 08/07/2026 (v7.12) — Indice unique su fiscal_code: garantisce che la stessa
            # persona (identificata dal CF) non venga registrata due volte con codici diversi.
            # partialFilter perché atleti senza CF sono ammessi (edge case: prova gratuita minori).
            try:
                await db.athletes.create_index(
                    [("fiscal_code", 1)],
                    unique=True,
                    partialFilterExpression={"fiscal_code": {"$exists": True, "$type": "string"}},
                    name="ux_fiscal_code",
                )
            except Exception as _idx_exc:
                logger.warning(f"Failed to create ux_fiscal_code index: {_idx_exc}")
            # matches
            await db.matches.create_index("id")
            await db.matches.create_index("society_id")
            await db.matches.create_index("team_id")
            await db.matches.create_index("match_number")
            # settings
            await db.settings.create_index([("type", 1), ("society_id", 1)])
            # notifications
            try:
                await db.notifications.create_index("id")
                await db.notifications.create_index("user_id")
                await db.notifications.create_index("society_id")
                await db.notifications.create_index([("user_id", 1), ("read", 1)])
            except Exception:
                pass
            # attendance / presence
            try:
                await db.attendance.create_index([("society_id", 1), ("athlete_id", 1)])
                await db.attendance.create_index([("society_id", 1), ("team_id", 1), ("date", -1)])
            except Exception:
                pass
            # 🚀 12/08/2026 — Il codice usa la collezione `attendances` (PLURALE, 28
            # occorrenze) ma finora gli indici erano solo su `attendance` (singolare):
            # la collezione calda faceva scansioni complete su ogni query presenze,
            # rallentando progressivamente man mano che le presenze crescevano nella
            # stagione. Indici sui campi effettivamente filtrati (athlete_id, team_id,
            # check_in_time).
            try:
                await db.attendances.create_index("athlete_id")
                await db.attendances.create_index("team_id")
                await db.attendances.create_index([("athlete_id", 1), ("check_in_time", 1)])
                await db.attendances.create_index([("team_id", 1), ("check_in_time", 1)])
            except Exception:
                pass
            # 🚀 12/08/2026 — signed_documents (contiene pdf_base64 pesante) senza indici:
            # lookup per id/related_entity_id/società ora indicizzati.
            try:
                await db.signed_documents.create_index("id")
                await db.signed_documents.create_index("society_id")
                await db.signed_documents.create_index("related_entity_id")
                await db.signed_documents.create_index("athlete_id")
                await db.signed_documents.create_index("signer_id")
            except Exception:
                pass
            # payments
            try:
                await db.payments.create_index([("society_id", 1), ("athlete_id", 1)])
                await db.payments.create_index("id")
                await db.payments.create_index("athlete_id")
                # 🚀 06/2026 — cartella ATLETI: query {athlete_id:$in, paid:True}
                await db.payments.create_index([("athlete_id", 1), ("paid", 1)])
            except Exception:
                pass
            # 🚀 06/2026 — Indici mancanti su collezioni CALDE che finora facevano
            # collection scan → lentezza nell'aprire le cartelle (società, eventi,
            # certificati, compensi, richieste). Tutti idempotenti e non-bloccanti.
            async def _safe_idx(coll, keys, **kw):
                try:
                    await coll.create_index(keys, **kw)
                except Exception:
                    pass
            # societies: 61 query (id/society_id/invite_code) — era SENZA indici.
            await _safe_idx(db.societies, "id")
            await _safe_idx(db.societies, "society_id")
            await _safe_idx(db.societies, "invite_code")
            # preseason (eventi/pre-iscrizioni)
            await _safe_idx(db.preseason_campaigns, "id")
            await _safe_idx(db.preseason_campaigns, "society_id")
            await _safe_idx(db.preseason_responses, "id")
            await _safe_idx(db.preseason_responses, "campaign_id")
            await _safe_idx(db.preseason_responses, "society_id")
            # certificati (usati nella scheda atleta)
            await _safe_idx(db.certificates, "id")
            await _safe_idx(db.certificates, "athlete_id")
            await _safe_idx(db.certificates, "society_id")
            await _safe_idx(db.medical_certificates_archive, "id")
            await _safe_idx(db.medical_certificates_archive, "athlete_id")
            await _safe_idx(db.medical_certificates_archive, "society_id")
            # compensi (Riforma Sport / pregresso)
            await _safe_idx(db.coach_compensations, "coach_id")
            await _safe_idx(db.coach_compensations, "society_id")
            await _safe_idx(db.collaboratore_compensations, "collaboratore_id")
            await _safe_idx(db.collaboratore_compensations, "society_id")
            await _safe_idx(db.dirigente_compensations, "dirigente_id")
            await _safe_idx(db.dirigente_compensations, "society_id")
            await _safe_idx(db.atleta_pro_compensations, "atleta_id")
            await _safe_idx(db.atleta_pro_compensations, "athlete_id")
            await _safe_idx(db.atleta_pro_compensations, "society_id")
            # 🚀 06/2026 — cartella ATLETI PRO
            await _safe_idx(db.atleta_pro_compensations, [("atleta_id", 1), ("year", 1)])
            await _safe_idx(db.athletes, [("society_id", 1), ("is_compensated", 1)])
            await _safe_idx(db.athlete_compensations, "athlete_id")
            await _safe_idx(db.athlete_compensations, "society_id")
            await _safe_idx(db.athlete_compensation_receipts, "athlete_id")
            await _safe_idx(db.athlete_compensation_receipts, "society_id")
            await _safe_idx(db.external_compensations, "society_id")
            await _safe_idx(db.threshold_declarations, "society_id")
            await _safe_idx(db.threshold_declarations, "user_id")
            # richieste / inviti / audit
            await _safe_idx(db.role_change_requests, "id")
            await _safe_idx(db.role_change_requests, "user_id")
            await _safe_idx(db.role_change_requests, "society_id")
            await _safe_idx(db.deletion_requests, "id")
            await _safe_idx(db.deletion_requests, "society_id")
            await _safe_idx(db.athlete_invitations, "token")
            await _safe_idx(db.athlete_invitations, "society_id")
            await _safe_idx(db.audit_logs, "society_id")
            # auth: velocizza il rate-limiting su login (lookup per email/ip)
            await _safe_idx(db.login_attempts, "email")
            await _safe_idx(db.login_rate_limits, "email")

            # 🚀 16/08/2026 — Pre-compressione una-tantum delle immagini pesanti su
            # collezioni PICCOLE (settings/societies): così la primissima apertura della
            # pagina Società / biglietto da visita è già veloce dopo il deploy, senza
            # attendere la compressione lazy on-read. Idempotente (salta se già leggera).
            try:
                from utils import compress_base64_image as _cbi
                for _coll, _fields in (
                    (db.settings, ("logo", "sport_image", "stamp_signature")),
                    (db.societies, ("logo",)),
                ):
                    async for _doc in _coll.find({}, {"_id": 1, "logo": 1, "sport_image": 1, "stamp_signature": 1}):
                        _upd = {}
                        for _f in _fields:
                            _v = _doc.get(_f)
                            if isinstance(_v, str) and len(_v) > 500_000:
                                _c = _cbi(_v)
                                if _c and _c != _v and len(_c) < len(_v):
                                    _upd[_f] = _c
                        if _upd:
                            await _coll.update_one({"_id": _doc["_id"]}, {"$set": _upd})
                logger.info("Pre-compressione immagini società completata.")
            except Exception as _exc_img:
                logger.warning(f"Pre-compressione immagini saltata: {_exc_img}")
            logger.info("MongoDB indexes ensured.")
        except Exception as exc:
            logger.warning(f"Could not create some indexes: {exc}")

    _asyncio.create_task(_create_indexes())

@app.on_event("startup")
async def run_data_migrations():
    """One-time data fixes applied at startup."""
    # Fix ROSI Giulio email: giulia@test.com -> giulio@test.com
    result = await db.users.update_one(
        {"email": "giulia@test.com"},
        {"$set": {"email": "giulio@test.com"}}
    )
    if result.modified_count > 0:
        logger.info("Migration: email giulia@test.com -> giulio@test.com applicata")

    # 🔥 24/02/2026 — Sync retroattivo compensation_accepted da users → athletes
    # (per atleti PRO che hanno accettato il compenso PRIMA del fix di propagazione)
    try:
        accepted_users = await db.users.find(
            {"role": "athlete", "compensation_accepted": True},
            {"id": 1, "athlete_id": 1, "compensation_accepted_date": 1},
        ).to_list(10000)
        synced = 0
        for u in accepted_users:
            # In db.users il record atleta ha athlete_id che punta a db.athletes.id
            athlete_doc_id = u.get("athlete_id") or u.get("id")
            res = await db.athletes.update_one(
                {"id": athlete_doc_id, "$or": [
                    {"compensation_accepted": {"$ne": True}},
                    {"compensation_accepted": {"$exists": False}},
                ]},
                {"$set": {
                    "compensation_accepted": True,
                    "compensation_accepted_date": u.get("compensation_accepted_date"),
                }},
            )
            if res.modified_count > 0:
                synced += 1
        logger.info(f"Migration compensation_accepted sync: {synced}/{len(accepted_users)} atleti aggiornati")
    except Exception as exc:
        logger.warning(f"Migration compensation_accepted sync failed: {exc}")

    # 🆕 24/08/2026 — Backfill "no prova per 18+": attiva retroattivamente gli atleti
    # MAGGIORENNI che sono già a posto (privacy firmata + certificato convalidato)
    # ma erano rimasti in uno stato di attesa (trial/pending_*). Idempotente.
    try:
        adult_ready_q = {
            "is_minor": {"$ne": True},
            "is_withdrawn": {"$ne": True},
            "status": {"$nin": ["active", "blocked", "rejected"]},
            "privacy_accepted": True,
            "medical_certificate_verified": True,
            "medical_certificate_expiry": {"$exists": True, "$ne": None},
        }
        activated_backfill = 0
        candidates = await db.athletes.find(adult_ready_q, {"_id": 0, "id": 1}).to_list(20000)
        for c in candidates:
            if await maybe_activate_adult_athlete(c["id"]):
                activated_backfill += 1
        logger.info(f"Migration 18+ no-prova backfill: {activated_backfill}/{len(candidates)} atleti maggiorenni attivati")
    except Exception as exc:
        logger.warning(f"Migration 18+ no-prova backfill failed: {exc}")

    # 🆕 Backfill MINORENNI bloccati "in prova" pur avendo privacy firmata + certificato
    # convalidato (il genitore non aveva premuto "Termina prova"). Idempotente.
    try:
        minor_ready_q = {
            "is_withdrawn": {"$ne": True},
            "$or": [{"is_trial": True}, {"status": {"$in": ["trial", "pending_trial", "pending_certificate", "pending_decision"]}}],
            "privacy_accepted": True,
        }
        minor_activated = 0
        minor_candidates = await db.athletes.find(minor_ready_q, {"_id": 0, "id": 1}).to_list(20000)
        for c in minor_candidates:
            if await maybe_activate_minor_athlete(c["id"]):
                minor_activated += 1
        logger.info(f"Migration minorenni prova→attivo backfill: {minor_activated}/{len(minor_candidates)} atleti attivati")
    except Exception as exc:
        logger.warning(f"Migration minorenni prova→attivo backfill failed: {exc}")

    # 🆕 01/07/2026 — Migrazione one-shot `active_seasons`: modello "clean slate" per rinnovi.
    # Ogni user/athlete diventa "membro di una stagione". La lista operativa filtra per
    # active_seasons contains <current_season>. L'archivio lista per <archived_season>.
    # Idempotente: aggiorna solo record senza il campo.
    try:
        # Trova tutte le società con impostazioni per calcolare la propria stagione precedente.
        societies_settings = await db.settings.find({"type": "society"}).to_list(1000)
        for s in societies_settings:
            sid = s.get("society_id")
            if not sid:
                continue
            start_month = int(s.get("season_start_month", 7) or 7)
            start_day = int(s.get("season_start_day", 1) or 1)
            from utils import get_current_season_for_society as _get_cs
            current_season = await _get_cs(db, sid)
            try:
                cur_start = int(current_season.split("-")[0])
                prev_season = f"{cur_start - 1}-{cur_start}"
            except Exception:
                prev_season = current_season

            # Cleanup residui flag "Riconferma" di stamattina (li abbiamo abbandonati).
            await db.athletes.update_many(
                {"society_id": sid},
                {"$unset": {
                    "renewed_for_next_season": "",
                    "imported_to_season": "",
                    "imported_at": "",
                    "imported_by": "",
                    "pro_data_pending_review": "",
                    "pro_data_pending_review_season": "",
                    "monthly_compensation_previous_season": "",
                    "other_annual_compensation_previous_season": "",
                }},
            )
            await db.users.update_many(
                {"society_id": sid},
                {"$unset": {
                    "renewed_for_next_season": "",
                    "imported_to_season": "",
                    "imported_at": "",
                    "imported_by": "",
                    "pro_data_pending_review": "",
                    "pro_data_pending_review_season": "",
                    "monthly_compensation_previous_season": "",
                    "other_annual_compensation_previous_season": "",
                }},
            )

            # 🆕 27/08/2026 BUGFIX "genitore invisibile": la migrazione assegnava la
            # stagione PRECEDENTE a QUALSIASI record senza active_seasons, comprese le
            # iscrizioni NUOVE fatte in questa stagione (che nascevano senza il campo).
            # Risultato: atleti appena iscritti e i loro genitori finivano archiviati
            # nella stagione vecchia → sparivano dalle liste correnti.
            # Ora distinguiamo in base a created_at: chi è stato creato DOPO l'inizio
            # della stagione corrente entra nella stagione CORRENTE, gli altri (storici)
            # nella precedente.
            from datetime import datetime as _dt_mig
            season_start_dt = None
            try:
                _cur_year = int(current_season.split("-")[0])
                season_start_dt = _dt_mig(_cur_year, start_month, start_day)
            except Exception:
                season_start_dt = None

            a_cur = a_prev = u_cur = u_prev = 0
            if season_start_dt is not None:
                # Nuove iscrizioni di QUESTA stagione senza campo → stagione CORRENTE
                _r = await db.athletes.update_many(
                    {"society_id": sid, "active_seasons": {"$exists": False}, "created_at": {"$gte": season_start_dt}},
                    {"$set": {"active_seasons": [current_season]}},
                )
                a_cur = _r.modified_count
                _r = await db.users.update_many(
                    {"society_id": sid, "active_seasons": {"$exists": False}, "created_at": {"$gte": season_start_dt}},
                    {"$set": {"active_seasons": [current_season]}},
                )
                u_cur = _r.modified_count

            # Restanti record storici senza campo → stagione PRECEDENTE
            a_res = await db.athletes.update_many(
                {"society_id": sid, "active_seasons": {"$exists": False}},
                {"$set": {"active_seasons": [prev_season]}},
            )
            u_res = await db.users.update_many(
                {"society_id": sid, "active_seasons": {"$exists": False}},
                {"$set": {"active_seasons": [prev_season]}},
            )
            a_prev, u_prev = a_res.modified_count, u_res.modified_count

            # 🩹 CORRETTIVO one-shot idempotente: record CREATI in questa stagione ma
            # erroneamente archiviati SOLO nella stagione precedente (danneggiati dal bug
            # prima di questo fix) → riportali nella stagione CORRENTE.
            a_fix = u_fix = 0
            if season_start_dt is not None:
                _r = await db.athletes.update_many(
                    {"society_id": sid, "active_seasons": [prev_season], "created_at": {"$gte": season_start_dt}},
                    {"$set": {"active_seasons": [current_season]}},
                )
                a_fix = _r.modified_count
                _r = await db.users.update_many(
                    {"society_id": sid, "active_seasons": [prev_season], "created_at": {"$gte": season_start_dt}},
                    {"$set": {"active_seasons": [current_season]}},
                )
                u_fix = _r.modified_count

            if a_cur or a_prev or u_cur or u_prev or a_fix or u_fix:
                logger.info(
                    f"Migration active_seasons society={sid} cur={current_season} prev={prev_season}: "
                    f"athletes(cur={a_cur},prev={a_prev},fix={a_fix}), users(cur={u_cur},prev={u_prev},fix={u_fix})"
                )
    except Exception as exc:
        logger.warning(f"Migration active_seasons failed: {exc}")

    # 🆕 08/07/2026 — Migrazione one-shot `team_ids` (array canonico squadre atleti).
    # Popola team_ids dai campi legacy team_id/team_id_2 per gli atleti che non hanno ancora l'array.
    # Idempotente: aggiorna solo record con `team_ids` mancante/vuoto.
    try:
        cursor = db.athletes.find(
            {"$or": [
                {"team_ids": {"$exists": False}},
                {"team_ids": {"$size": 0}},
            ]},
            {"_id": 0, "id": 1, "team_id": 1, "team_id_2": 1},
        )
        migrated = 0
        async for a in cursor:
            ids = []
            for tid in [a.get("team_id"), a.get("team_id_2")]:
                if tid and tid not in ids:
                    ids.append(tid)
            if ids:
                await db.athletes.update_one(
                    {"id": a["id"]},
                    {"$set": {"team_ids": ids}},
                )
                migrated += 1
        if migrated:
            logger.info(f"Migration team_ids: {migrated} atleti aggiornati con array team_ids canonico")
    except Exception as exc:
        logger.warning(f"Migration team_ids failed: {exc}")

